-- ---------------------------------------------------------------- the transform
-- An FFT of size n, its sign positive (an inverse transform without the 1/n), in place on 1-based re/im.
local plans = {}
local function plan(n)
  local p = plans[n]
  if p then return p end
  p = { n = n, rev = {}, c = {}, s = {} }
  local levels = floor(math.log(n, 2) + 0.5)
  for i = 0, n - 1 do
    local r, x = 0, i
    for _ = 1, levels do r = r * 2 + x % 2; x = floor(x / 2) end
    p.rev[i + 1] = r + 1
  end
  for j = 0, n / 2 - 1 do p.c[j] = cos(2 * pi * j / n); p.s[j] = sin(2 * pi * j / n) end
  plans[n] = p
  return p
end
local function ifft(re, im, p)
  local n, rev, ct, st = p.n, p.rev, p.c, p.s
  for i = 1, n do
    local j = rev[i]
    if j > i then re[i], re[j] = re[j], re[i]; im[i], im[j] = im[j], im[i] end
  end
  local size = 2
  while size <= n do
    local half = size / 2
    local step = n / size
    for start = 1, n, size do
      local t = 0
      for k = start, start + half - 1 do
        local wr, wi = ct[t], st[t]
        t += step
        local b = k + half
        local br, bi = re[b], im[b]
        local tr, ti = br * wr - bi * wi, br * wi + bi * wr
        local ar, ai = re[k], im[k]
        re[b], im[b] = ar - tr, ai - ti
        re[k], im[k] = ar + tr, ai + ti
      end
    end
    size *= 2
  end
end
-- DCT-IV of M values through an inverse FFT of M/2 (worked out for this file):
--   u[m] = (X[2m] - i X[M-1-2m]) e^(i pi m / M);  U = sum u[m] e^(2 pi i n m / (M/2));
--   Z[n] = U[n] e^(i pi (n + 1/4) / M);  C[2n] = Re Z[n], C[M-1-2n] = Im Z[n]
local twiddles = {}
local function dct4(X, C, M, xOff)
  xOff = xOff or 0
  local L = M / 2
  local t = twiddles[M]
  if not t then
    t = { pc = {}, ps = {}, qc = {}, qs = {}, re = table.create(L, 0), im = table.create(L, 0), p = plan(L) }
    for m = 0, L - 1 do
      t.pc[m] = cos(pi * m / M); t.ps[m] = sin(pi * m / M)
      t.qc[m] = cos(pi * (m + 0.25) / M); t.qs[m] = sin(pi * (m + 0.25) / M)
    end
    twiddles[M] = t
  end
  local re, im, pc, ps, qc, qs = t.re, t.im, t.pc, t.ps, t.qc, t.qs
  for m = 0, L - 1 do
    local a, b = X[xOff + 2 * m + 1], X[xOff + M - 2 * m]
    local c, s = pc[m], ps[m]
    -- (a - ib)(c + is) = a c + b s + i (a s - b c)
    re[m + 1], im[m + 1] = a * c + b * s, a * s - b * c
  end
  ifft(re, im, t.p)
  for n = 0, L - 1 do
    local ur, ui = re[n + 1], im[n + 1]
    local c, s = qc[n], qs[n]
    C[2 * n + 1] = ur * c - ui * s
    C[M - 2 * n] = ur * s + ui * c
  end
end
-- IMDCT: N = 2M samples from M coefficients, with the standard's 2/N
local function imdct(X, Y, M, xOff, scratch)
  dct4(X, scratch, M, xOff)
  local h, scale = M / 2, 2 / (2 * M)
  for n = 0, h - 1 do Y[n + 1] = scratch[n + h + 1] * scale end
  for n = h, 3 * h - 1 do Y[n + 1] = -scratch[3 * h - n] * scale end
  for n = 3 * h, 2 * M - 1 do Y[n + 1] = -scratch[n - 3 * h + 1] * scale end
end
AAC.test = { dct4 = dct4, imdct = imdct }

-- ---------------------------------------------------------------- windows
local function bessel0(x)
  local sum, term, k = 1, 1, 1
  while term > 1e-12 * sum do
    term *= (x / (2 * k)) ^ 2
    sum += term
    k += 1
  end
  return sum
end
local function windows(N, alpha)
  local sine, kbd = {}, {}
  for n = 0, N - 1 do sine[n + 1] = sin(pi * (n + 0.5) / N) end
  local w, total = {}, 0
  for n = 0, N / 2 do
    local x = (n - N / 4) / (N / 4)
    w[n] = bessel0(pi * alpha * sqrt(math.max(0, 1 - x * x)))
    total += w[n]
  end
  local acc = 0
  for n = 0, N / 2 - 1 do
    acc += w[n]
    local value = sqrt(acc / total)
    kbd[n + 1] = value
    kbd[N - n] = value
  end
  return { [0] = sine, [1] = kbd }
end
local LW, SW = windows(2048, 4), windows(256, 6)

-- ---------------------------------------------------------------- one channel's stream
local function newIcs() return { groupLen = {}, cb = {}, sf = {}, tnsN = {}, tnsLen = {}, tnsOrder = {}, tnsDir = {}, tnsCoef = {}, pk = {}, pa = {} } end
local function icsInfo(ics, rate)
  bit1()
  ics.seq = bits(2)
  ics.shape = bit1()
  if ics.seq == 2 then
    ics.maxSfb = bits(4)
    local grouping = bits(7)
    ics.numWindows = 8
    ics.swb = SHORT[rate]
    local groups = 1
    ics.groupLen[1] = 1
    for i = 6, 0, -1 do
      if band(rshift(grouping, i), 1) == 1 then ics.groupLen[groups] += 1 else groups += 1; ics.groupLen[groups] = 1 end
    end
    ics.numGroups = groups
  else
    ics.maxSfb = bits(6)
    ics.numWindows, ics.numGroups = 1, 1
    ics.groupLen[1] = 1
    ics.swb = LONG[rate]
    if bit1() == 1 then error("aac: prediction (not AAC-LC)") end
  end
  ics.numSwb = #ics.swb - 1
  if ics.maxSfb > ics.numSwb then error("aac: max_sfb") end
end
local function tnsData(ics)
  local long = ics.seq ~= 2
  for w = 0, ics.numWindows - 1 do
    local count = bits(long and 2 or 1)
    ics.tnsN[w] = count
    if count > 0 then
      local res = bit1()
      for f = 1, count do
        local key = w * 4 + f
        ics.tnsLen[key] = bits(long and 6 or 4)
        local order = bits(long and 5 or 3)
        ics.tnsOrder[key] = order
        if order > 0 then
          ics.tnsDir[key] = bit1()
          local compress = bit1()
          local width = res + 3 - compress
          local half = 2 ^ (res + 2)
          local iq, iqm = (half - 0.5) / (pi / 2), (half + 0.5) / (pi / 2)
          for i = 1, order do
            local c = bits(width)
            if c >= 2 ^ (width - 1) then c -= 2 ^ width end
            ics.tnsCoef[key * 32 + i] = sin(c / (c >= 0 and iq or iqm))
          end
        end
      end
    end
  end
end
local function stream(ics, common, rate, q)
  local gain = bits(8)
  if not common then icsInfo(ics, rate) end
  local cb, sf, groups, maxSfb = ics.cb, ics.sf, ics.numGroups, ics.maxSfb
  -- sections
  local long = ics.seq ~= 2
  local width, esc = long and 5 or 3, long and 31 or 7
  for g = 0, groups - 1 do
    local k = 0
    while k < maxSfb do
      local book = bits(4)
      local length = 0
      local incr = bits(width)
      while incr == esc do length += incr; incr = bits(width) end
      length += incr
      if length == 0 or k + length > maxSfb or book == 12 then error("aac: section") end
      for sfb = k, k + length - 1 do cb[g * 64 + sfb] = book end
      k += length
    end
  end
  -- scale factors
  local scale, position, noise, first = gain, 0, gain - 90, true
  for g = 0, groups - 1 do
    for sfb = 0, maxSfb - 1 do
      local key = g * 64 + sfb
      local book = cb[key]
      if book == 0 then sf[key] = 0
      elseif book == 14 or book == 15 then position += huff(SFZ, SFO) - 61; sf[key] = position
      elseif book == 13 then
        if first then noise += bits(9) - 256; first = false else noise += huff(SFZ, SFO) - 61 end
        sf[key] = noise
      else
        scale += huff(SFZ, SFO) - 61
        sf[key] = scale
      end
    end
  end
  -- pulses (long windows only)
  ics.pulses = 0
  if bit1() == 1 then
    if not long then error("aac: pulse in short") end
    local count = bits(2) + 1
    local k = ics.swb[bits(6) + 1]
    for i = 1, count do
      k += bits(5)
      ics.pk[i], ics.pa[i] = k, bits(4)
    end
    ics.pulses = count
  end
  ics.tnsOn = bit1() == 1
  if ics.tnsOn then tnsData(ics) end
  if bit1() == 1 then error("aac: gain control (not AAC-LC)") end
  -- the spectrum, quantized
  for i = 1, 1024 do q[i] = 0 end
  local swb = ics.swb
  local win = 0
  for g = 0, groups - 1 do
    local glen = ics.groupLen[g + 1]
    for sfb = 0, maxSfb - 1 do
      local book = cb[g * 64 + sfb]
      if book >= 1 and book <= 11 then
        local B = BOOK[book]
        local zero, one, values, dim, unsigned = B.zero, B.one, B.values, B.dim, B.unsigned
        local from, to = swb[sfb + 1], swb[sfb + 2]
        for w = 0, glen - 1 do
          local base = (win + w) * 128
          local k = from
          while k < to do
            local index = huff(zero, one)
            if dim == 4 then
              local v = index * 4
              local a, b, c, d = values[v - 3], values[v - 2], values[v - 1], values[v]
              if unsigned then
                if a ~= 0 and bit1() == 1 then a = -a end
                if b ~= 0 and bit1() == 1 then b = -b end
                if c ~= 0 and bit1() == 1 then c = -c end
                if d ~= 0 and bit1() == 1 then d = -d end
              end
              local at = base + k
              q[at + 1], q[at + 2], q[at + 3], q[at + 4] = a, b, c, d
              k += 4
            else
              local v = index * 2
              local y, z = values[v - 1], values[v]
              if unsigned then
                if y ~= 0 and bit1() == 1 then y = -y end
                if z ~= 0 and bit1() == 1 then z = -z end
              end
              if book == 11 then
                if y == 16 or y == -16 then
                  local n = 4
                  while bit1() == 1 do n += 1; if n > 20 then error("aac: escape") end end
                  local e = 2 ^ n + bits(n)
                  y = y < 0 and -e or e
                end
                if z == 16 or z == -16 then
                  local n = 4
                  while bit1() == 1 do n += 1; if n > 20 then error("aac: escape") end end
                  local e = 2 ^ n + bits(n)
                  z = z < 0 and -e or e
                end
              end
              local at = base + k
              q[at + 1], q[at + 2] = y, z
              k += 2
            end
          end
        end
      end
    end
    win += glen
  end
end
-- quantized -> real values; noise bands filled; intensity bands left for the pair
local seed = 1
local function random()
  seed = (seed * 1664525 + 1013904223) % 4294967296
  return seed / 2147483648 - 1
end
local function dequantize(ics, q, spec)
  for i = 1, 1024 do spec[i] = 0 end
  if ics.pulses > 0 then
    for i = 1, ics.pulses do
      local at = ics.pk[i] + 1
      local v = q[at]
      if v < 0 then q[at] = v - ics.pa[i] else q[at] = v + ics.pa[i] end
    end
  end
  local swb, cb, sf = ics.swb, ics.cb, ics.sf
  local win = 0
  for g = 0, ics.numGroups - 1 do
    local glen = ics.groupLen[g + 1]
    for sfb = 0, ics.maxSfb - 1 do
      local key = g * 64 + sfb
      local book = cb[key]
      local from, to = swb[sfb + 1], swb[sfb + 2]
      if book >= 1 and book <= 11 then
        local gain = 2 ^ (0.25 * (sf[key] - 100))
        for w = 0, glen - 1 do
          local base = (win + w) * 128
          for k = base + from + 1, base + to do
            local v = q[k]
            if v > 0 then spec[k] = (POW43[v] or v ^ (4 / 3)) * gain
            elseif v < 0 then spec[k] = -(POW43[-v] or (-v) ^ (4 / 3)) * gain end
          end
        end
      elseif book == 13 then
        for w = 0, glen - 1 do
          local base = (win + w) * 128
          local energy = 0
          for k = base + from + 1, base + to do
            local r = random()
            spec[k] = r
            energy += r * r
          end
          local scale = 2 ^ (0.25 * sf[key]) / sqrt(math.max(energy, 1e-9))
          for k = base + from + 1, base + to do spec[k] *= scale end
        end
      end
    end
    win += glen
  end
end
-- TNS: each filter run over its bands, from the bottom up or the top down
local lpc, tmp = {}, {}
local function tns(ics, spec, rate)
  if not ics.tnsOn then return end
  local long = ics.seq ~= 2
  local most = long and TNS_LONG[rate] or TNS_SHORT[rate]
  local swb, numSwb, maxSfb = ics.swb, ics.numSwb, ics.maxSfb
  for w = 0, ics.numWindows - 1 do
    local top = numSwb
    local base = long and 0 or w * 128
    for f = 1, ics.tnsN[w] or 0 do
      local key = w * 4 + f
      local bottom = math.max(top - ics.tnsLen[key], 0)
      local order = ics.tnsOrder[key]
      if order > 0 then
        for m = 1, order do
          local r = ics.tnsCoef[key * 32 + m]
          for i = 1, m - 1 do tmp[i] = lpc[i] + r * lpc[m - i] end
          for i = 1, m - 1 do lpc[i] = tmp[i] end
          lpc[m] = r
        end
        local startBand = math.min(bottom, most, maxSfb)
        local endBand = math.min(top, most, maxSfb)
        local start, stop = swb[startBand + 1], swb[endBand + 1]
        local size = stop - start
        if size > 0 then
          local inc, pos = 1, base + start + 1
          if ics.tnsDir[key] == 1 then inc, pos = -1, base + stop end
          for m = 0, size - 1 do
            local acc = spec[pos]
            for i = 1, math.min(m, order) do acc -= spec[pos - i * inc] * lpc[i] end
            spec[pos] = acc
            pos += inc
          end
        end
      end
      top = bottom
    end
  end
end
-- the filterbank: the frame's 1024 samples out, the next frame's half kept
local function filterbank(ics, spec, ch, out)
  local seq, shape, prev = ics.seq, ics.shape, ch.prevShape
  local time, scratch, short = ch.time, ch.scratch, ch.short
  local overlap = ch.overlap
  if seq == 2 then
    for i = 1, 2048 do time[i] = 0 end
    for j = 0, 7 do
      imdct(spec, short, 128, j * 128, scratch)
      local left = j == 0 and SW[prev] or SW[shape]
      local right = SW[shape]
      local at = 448 + j * 128
      for n = 1, 128 do time[at + n] += short[n] * left[n] end
      for n = 129, 256 do time[at + n] += short[n] * right[n] end
    end
  else
    imdct(spec, time, 1024, 0, scratch)
    local left, right = LW[prev], LW[shape]
    if seq == 3 then
      for n = 1, 448 do time[n] = 0 end
      local sl = SW[prev]
      for n = 449, 576 do time[n] *= sl[n - 448] end
    else
      for n = 1, 1024 do time[n] *= left[n] end
    end
    if seq == 1 then
      local sr = SW[shape]
      for n = 1473, 1600 do time[n] *= sr[n - 1472 + 128] end
      for n = 1601, 2048 do time[n] = 0 end
    else
      for n = 1025, 2048 do time[n] *= right[n] end
    end
  end
  for n = 1, 1024 do
    out[n] = time[n] + overlap[n]
    overlap[n] = time[n + 1024]
  end
  ch.prevShape = shape
end

-- ---------------------------------------------------------------- frames
local function newChannel()
  return { q = table.create(1024, 0), spec = table.create(1024, 0), time = table.create(2048, 0), scratch = table.create(1024, 0),
    short = table.create(256, 0), overlap = table.create(1024, 0), out = table.create(1024, 0), prevShape = 0, ics = newIcs() }
end
-- one raw_data_block: SCE/CPE (and fill/data elements skipped) up to END
local function frame(dec)
  local rate, chans = dec.rate, dec.channels
  local used = 0
  while true do
    local id = bits(3)
    if id == 7 then break end
    if id == 0 or id == 3 then
      bits(4)
      used += 1
      local ch = chans[used] or chans[1]
      stream(ch.ics, false, rate, ch.q)
      dequantize(ch.ics, ch.q, ch.spec)
      tns(ch.ics, ch.spec, rate)
      filterbank(ch.ics, ch.spec, ch, ch.out)
    elseif id == 1 then
      bits(4)
      local a, b = chans[used + 1], chans[used + 2]
      used += 2
      if not (a and b) then error("aac: more channels than set up") end
      local common = bit1() == 1
      local msMask = 0
      local ms = dec.ms
      if common then
        icsInfo(a.ics, rate)
        -- (one window for both: the second channel's stream reads none of its own)
        local one, other = a.ics, b.ics
        other.seq, other.shape, other.maxSfb, other.numWindows, other.numGroups = one.seq, one.shape, one.maxSfb, one.numWindows, one.numGroups
        other.swb, other.numSwb = one.swb, one.numSwb
        for i = 1, one.numGroups do other.groupLen[i] = one.groupLen[i] end
        msMask = bits(2)
        if msMask == 1 then
          for g = 0, a.ics.numGroups - 1 do
            for sfb = 0, a.ics.maxSfb - 1 do ms[g * 64 + sfb] = bit1() end
          end
        end
      end
      stream(a.ics, common, rate, a.q)
      stream(b.ics, common, rate, b.q)
      dequantize(a.ics, a.q, a.spec)
      dequantize(b.ics, b.q, b.spec)
      -- mid/side, then intensity: right from left, by band
      if common then
        local ics, swb = b.ics, b.ics.swb
        local win = 0
        for g = 0, ics.numGroups - 1 do
          local glen = ics.groupLen[g + 1]
          for sfb = 0, ics.maxSfb - 1 do
            local key = g * 64 + sfb
            local book = ics.cb[key]
            local from, to = swb[sfb + 1], swb[sfb + 2]
            local msUsed = msMask == 2 or (msMask == 1 and ms[key] == 1)
            if book == 14 or book == 15 then
              local scale = 0.5 ^ (0.25 * ics.sf[key])
              local sign = (book == 15 and 1 or -1) * ((msMask == 1 and ms[key] == 1) and -1 or 1)
              for w = 0, glen - 1 do
                local base = (win + w) * 128
                for k = base + from + 1, base + to do b.spec[k] = a.spec[k] * scale * sign end
              end
            elseif msUsed and book ~= 13 and a.ics.cb[key] ~= 13 then
              for w = 0, glen - 1 do
                local base = (win + w) * 128
                for k = base + from + 1, base + to do
                  local m, s = a.spec[k], b.spec[k]
                  a.spec[k], b.spec[k] = m + s, m - s
                end
              end
            end
          end
          win += glen
        end
      end
      tns(a.ics, a.spec, rate)
      tns(b.ics, b.spec, rate)
      filterbank(a.ics, a.spec, a, a.out)
      filterbank(b.ics, b.spec, b, b.out)
    elseif id == 6 then
      local count = bits(4)
      if count == 15 then count += bits(8) - 1 end
      RP += count * 8
    elseif id == 4 then
      bits(4)
      local align = bit1() == 1
      local count = bits(8)
      if count == 255 then count += bits(8) end
      if align then RP = math.ceil(RP / 8) * 8 end
      RP += count * 8
    else
      error("aac: element " .. id .. " not handled")
    end
  end
  return used
end

-- ---------------------------------------------------------------- MP4 (fragmented): the setup and the frames
local function u32(s, i) return (string.unpack(">I4", s, i)) end
local function walk(s, from, to, each)
  local i = from
  while i + 7 <= to do
    local size = u32(s, i)
    local kind = string.sub(s, i + 4, i + 7)
    local head = 8
    if size == 1 then size = string.unpack(">I8", s, i + 8); head = 16 elseif size == 0 then size = to - i + 1 end
    if size < head then break end
    each(kind, i + head, i + size - 1, i)
    i += size
  end
end
local function descriptor(s, i)
  local tag = string.byte(s, i)
  local length = 0
  i += 1
  for _ = 1, 4 do
    local b = string.byte(s, i)
    i += 1
    length = length * 128 + band(b, 0x7F)
    if b < 0x80 then break end
  end
  return tag, length, i
end
-- the AudioSpecificConfig in the init segment's esds: object type, rate index, channels
function AAC.config(init)
  local found
  local function dig(kind, from, to)
    if found then return end
    if kind == "moov" or kind == "trak" or kind == "mdia" or kind == "minf" or kind == "stbl" then walk(init, from, to, dig)
    elseif kind == "stsd" then walk(init, from + 8, to, dig)
    elseif kind == "mp4a" then walk(init, from + 28, to, dig)
    elseif kind == "esds" then
      local i = from + 4
      local tag, length
      tag, length, i = descriptor(init, i)
      if tag == 3 then
        i += 2
        local flags = string.byte(init, i)
        i += 1
        if band(flags, 0x80) ~= 0 then i += 2 end
        if band(flags, 0x40) ~= 0 then i += 1 + string.byte(init, i) end
        if band(flags, 0x20) ~= 0 then i += 2 end
        tag, length, i = descriptor(init, i)
      end
      if tag == 4 then
        i += 13
        tag, length, i = descriptor(init, i)
      end
      if tag == 5 then
        local a, b = string.byte(init, i, i + 1)
        local object = rshift(a, 3)
        local rate = band(a, 7) * 2 + rshift(b, 7)
        local channels = band(rshift(b, 3), 15)
        found = { object = object, rate = rate, channels = channels }
      end
      local _ = length
    end
  end
  walk(init, 1, #init, dig)
  return found
end
-- every frame of one media segment (moof + mdat, any number of them): its bytes, in order
function AAC.frames(segment, out)
  out = out or {}
  local sizes = {}
  walk(segment, 1, #segment, function(kind, from, to)
    if kind == "moof" then
      table.clear(sizes)
      walk(segment, from, to, function(k2, f2, t2)
        if k2 ~= "traf" then return end
        local default = 0
        walk(segment, f2, t2, function(k3, f3)
          if k3 == "tfhd" then
            local flags = band(u32(segment, f3), 0xFFFFFF)
            local i = f3 + 8
            if band(flags, 0x01) ~= 0 then i += 8 end
            if band(flags, 0x02) ~= 0 then i += 4 end
            if band(flags, 0x08) ~= 0 then i += 4 end
            if band(flags, 0x10) ~= 0 then default = u32(segment, i) end
          elseif k3 == "trun" then
            local flags = band(u32(segment, f3), 0xFFFFFF)
            local count = u32(segment, f3 + 4)
            local i = f3 + 8
            if band(flags, 0x001) ~= 0 then i += 4 end
            if band(flags, 0x004) ~= 0 then i += 4 end
            for _ = 1, count do
              if band(flags, 0x100) ~= 0 then i += 4 end
              local size = default
              if band(flags, 0x200) ~= 0 then size = u32(segment, i); i += 4 end
              if band(flags, 0x400) ~= 0 then i += 4 end
              if band(flags, 0x800) ~= 0 then i += 4 end
              sizes[#sizes + 1] = size
            end
          end
        end)
      end)
    elseif kind == "mdat" then
      local at = from
      for _, size in ipairs(sizes) do
        if size > 0 and at + size - 1 <= to then out[#out + 1] = string.sub(segment, at, at + size - 1) end
        at += size
      end
    end
  end)
  return out
end

-- ---------------------------------------------------------------- a decoder, and WAV out
function AAC.decoder(config)
  prepare()
  seed = 1                             -- (the noise starts the same each time: the same song decodes the same)
  local channels = math.clamp(config.channels or 2, 1, 2)
  local dec = { rate = config.rate or 4, channels = {}, count = channels, ms = {} }
  for i = 1, channels do dec.channels[i] = newChannel() end
  dec.sampleRate = RATES[dec.rate] or 44100
  -- one frame's bytes -> true, each channel's 1024 samples in channel.out (silence on a frame that will not decode)
  function dec.decode(data)
    RB, RP = buffer.fromstring(data), 0
    local ok, why = pcall(frame, dec)
    if not ok then
      for _, ch in ipairs(dec.channels) do
        for n = 1, 1024 do ch.out[n] = ch.overlap[n] * 0; ch.overlap[n] = 0 end
      end
      dec.errors = (dec.errors or 0) + 1
      dec.lastError = why
    end
    return ok
  end
  return dec
end
-- a WAV file's header for `bytes` of 16-bit samples
local function wavHeader(rate, channels, bytes)
  return "RIFF" .. string.pack("<I4", 36 + bytes) .. "WAVEfmt " .. string.pack("<I4I2I2I4I4I2I2", 16, 1, channels, rate, rate * channels * 2, channels * 2, 16)
    .. "data" .. string.pack("<I4", bytes)
end
AAC.wavHeader = wavHeader
-- the frame just decoded, as 16-bit samples (interleaved), into `out` at byte `at`
local writei16 = buffer.writei16
local function putFrame(dec, out, at)
  local left = dec.channels[1].out
  if dec.count == 2 then
    local right = dec.channels[2].out
    for n = 1, 1024 do
      local l, r = left[n], right[n]
      l = l > 32767 and 32767 or (l < -32768 and -32768 or l)
      r = r > 32767 and 32767 or (r < -32768 and -32768 or r)
      writei16(out, at, l >= 0 and floor(l + 0.5) or -floor(-l + 0.5))
      writei16(out, at + 2, r >= 0 and floor(r + 0.5) or -floor(-r + 0.5))
      at += 4
    end
  else
    for n = 1, 1024 do
      local l = left[n]
      l = l > 32767 and 32767 or (l < -32768 and -32768 or l)
      writei16(out, at, l >= 0 and floor(l + 0.5) or -floor(-l + 0.5))
      at += 2
    end
  end
end
local function setup(init)
  local config = AAC.config(init)
  if not config then return nil, "no AAC setup in the stream" end
  if config.object ~= 2 and config.object ~= 5 and config.object ~= 29 then return nil, "not AAC-LC (object " .. tostring(config.object) .. ")" end
  return AAC.decoder(config)
end
-- init + segments -> a WAV file's bytes (16-bit). progress(fraction) now and then; yield() between batches.
function AAC.toWav(init, segments, progress, yield)
  local dec, why = setup(init)
  if not dec then return nil, why end
  local frames = {}
  for _, segment in ipairs(segments) do AAC.frames(segment, frames) end
  if #frames == 0 then return nil, "no frames in the stream" end
  local channels = dec.count
  local bytes = #frames * 1024 * channels * 2
  local out = buffer.create(44 + bytes)
  buffer.writestring(out, 0, wavHeader(dec.sampleRate, channels, bytes))
  local at = 44
  local started = os.clock()
  for index, data in ipairs(frames) do
    dec.decode(data)
    putFrame(dec, out, at)
    at += 1024 * channels * 2
    if yield and os.clock() - started > 0.012 then
      if progress then progress(index / #frames) end
      yield()
      started = os.clock()
    end
  end
  if progress then progress(1) end
  return buffer.tostring(out), nil, { frames = #frames, errors = dec.errors or 0, lastError = dec.lastError, rate = dec.sampleRate, channels = channels }
end

-- Decoded as it arrives, and handed over a piece at a time, so a song plays a few seconds after it
-- is asked for instead of after all of it is decoded. Each piece is `piece` seconds of WAV plus
-- `overlap` more: the start of the next one, for the player to cross into it without a gap.
--   opts.segment(i)  -> the i-th media segment's bytes, nil after the last (it may wait for a download)
--   opts.onPiece(index, wav, startSeconds, ownSeconds, fileSeconds, last)
--   opts.progress(decodedSeconds), opts.yield(), opts.cancelled() -> true to stop
--   opts.budget: seconds of work between yields (opts.first for the first piece, so it starts quickly)
--   opts.firstPiece: a shorter first piece (seconds), so the song starts sooner
-- -> true, nil, info | false, why
function AAC.stream(init, opts)
  local dec, why = setup(init)
  if not dec then return false, why end
  local channels, rate = dec.count, dec.sampleRate
  local frameBytes = 1024 * channels * 2
  local pieceFrames = math.max(8, floor((opts.piece or 12) * rate / 1024 + 0.5))
  local firstFrames = math.max(8, floor((opts.firstPiece or opts.piece or 12) * rate / 1024 + 0.5))
  local overlapFrames = math.max(1, math.ceil((opts.overlap or 0.06) * rate / 1024))
  local function ownFrames(index) return index == 1 and firstFrames or pieceFrames end
  local size = (math.max(pieceFrames, firstFrames) + overlapFrames) * frameBytes
  local function newPiece(index, first) return { index = index, first = first, frames = 0, buf = buffer.create(size) } end
  local current, following = newPiece(1, 0), nil
  local decoded, count = 0, 0
  local budget = opts.first or 0.03
  local started = os.clock()
  local yield = opts.yield or task.wait
  local function emit(piece, last)
    local bytes = piece.frames * frameBytes
    local wav = wavHeader(rate, channels, bytes) .. buffer.readstring(piece.buf, 0, bytes)
    piece.buf = nil
    count += 1
    local own = (last and piece.frames or ownFrames(piece.index)) * 1024 / rate
    opts.onPiece(piece.index, wav, piece.first * 1024 / rate, own, piece.frames * 1024 / rate, last)
    budget = opts.budget or 0.006
  end
  local i = 0
  local list = {}
  while true do
    i += 1
    local segment = opts.segment(i)
    if segment == nil then break end
    if opts.cancelled and opts.cancelled() then return false, "cancelled" end
    table.clear(list)
    AAC.frames(segment, list)
    for _, data in ipairs(list) do
      dec.decode(data)
      local slot = decoded - current.first
      local own = ownFrames(current.index)
      putFrame(dec, current.buf, slot * frameBytes)
      current.frames = slot + 1
      if slot >= own then
        -- (in the overlap: also the head of the next piece)
        following = following or newPiece(current.index + 1, current.first + own)
        buffer.copy(following.buf, (slot - own) * frameBytes, current.buf, slot * frameBytes, frameBytes)
        following.frames = slot - own + 1
      end
      decoded += 1
      if current.frames == own + overlapFrames then
        emit(current, false)
        current, following = following, nil
      end
      if os.clock() - started > budget then
        if opts.progress then opts.progress(decoded * 1024 / rate) end
        yield()
        if opts.cancelled and opts.cancelled() then return false, "cancelled" end
        started = os.clock()
      end
    end
  end
  if decoded == 0 then return false, "no frames in the stream" end
  if current.frames > 0 then emit(current, true) end
  if opts.progress then opts.progress(decoded * 1024 / rate) end
  return true, nil, { frames = decoded, errors = dec.errors or 0, lastError = dec.lastError, rate = rate, channels = channels, pieces = count,
    seconds = decoded * 1024 / rate }
end
end
do -- 45_music.lua
-- ============================================================================
--  45 music    a music player in every look: SoundCloud, Audius, your own
--              files, or a link; a queue, likes, playlists, history, sound
--              shaping, crossfades, a mini player and keys
--
--  How each source plays (measured 2026-10-21 from the game client):
--    * SoundCloud: the client id is read from soundcloud.com's own scripts (no
--      key to sign up for; kept 12 h, read again on a 401/403). Search is
--      api-v2 /search/tracks. Streams are AAC in fragmented MP4 over HLS (96 of
--      100 tracks had nothing else), which Roblox will not load, so 44_aac.lua
--      decodes them as they download, in 12 s pieces (the first 6 s) with 0.3 s of overlap: the
--      first piece plays a few seconds after the click, and the player crosses
--      from piece to piece on that overlap. The pieces stay on disk: the next
--      play starts at once. An MP3 stream, where a track still has one, is used
--      as it is. A track behind DRM (#EXT-X-KEY) says so and is skipped.
--    * Audius: api.audius.co search, trending and /stream (an MP3, at once).
--    * Files: .mp3 .ogg .wav .flac in workspace/BasedHub/music.
--    * Link: a direct audio URL, or a Roblox audio id.
--  Three voices (Sounds) share one SoundGroup that carries the effects, so a
--  piece change, a crossfade between songs and the sound settings all agree.
--  What plays "in front" (Music.front) is this player, or what this PC plays
--  (48_pc); the words in time are 47_lyrics, the card and island 49_card.
-- ============================================================================
local S, util, Motion, UI, Config, Window, fs = B.S, B.util, B.Motion, B.UI, B.Config, B.Window, B.fs
local Http = S.HttpService

local Music = { queue = {}, index = 0, now = nil, state = "idle", status = nil, results = {}, resultsFor = nil, changed = B.Signal.new() }
B.Music = Music

local FOLDER = fs.path("music")
Music.CACHE_ANY = 100000      -- the Keep up to slider's last stop (MB): no limit
local CACHE = fs.path("music/cache")
local ART = fs.path("music/art")
local INDEX = fs.path("music/cache.json")
local APP = "BASEDHUB"
local UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36"

-- ---------------------------------------------------------------- the web
local function fetch(url)
  local send = (type(request) == "function" and request) or (type(http_request) == "function" and http_request) or nil
  if send then
    local ok, response = pcall(send, { Url = url, Method = "GET", Headers = { ["User-Agent"] = UA } })
    if ok and type(response) == "table" then return response.StatusCode or 0, response.Body end
    return -1, nil
  end
  local ok, body = pcall(game.HttpGet, game, url)
  return ok and 200 or -1, ok and body or nil
end
local function json(text)
  if type(text) ~= "string" then return nil end
  local ok, value = pcall(Http.JSONDecode, Http, text)
  return ok and value or nil
end
local function encode(text) return Http:UrlEncode(tostring(text or "")) end
local function token() return string.format("%06x", math.random(0, 0xFFFFFF)) end

-- ---------------------------------------------------------------- the cache: kept songs, the least lately played go first past the size set
local index
local function cacheIndex()
  if not index then
    index = fs.readJson(INDEX)
    if type(index) ~= "table" or type(index.files) ~= "table" then index = { files = {} } end
  end
  return index
end
local function removeEntry(path)
  if fs.isdir(path) then
    for _, file in ipairs(fs.list(path)) do fs.remove(file) end
    if type(delfolder) == "function" then pcall(delfolder, path) end
  else
    fs.remove(path)
  end
end
local function present(path) return fs.exists(path) or fs.isdir(path) end
local function cacheTouch(path, size)
  local data = cacheIndex()
  local old = data.files[path]
  data.files[path] = { size = size or (old and old.size) or 0, used = os.time() }
  local mb = Config.get("music.cacheMb") or 600
  local limit = mb >= Music.CACHE_ANY and math.huge or mb * 1048576
  local total, list = 0, {}
  for file, info in pairs(data.files) do
    if present(file) then total += info.size or 0; list[#list + 1] = { file, info } else data.files[file] = nil end
  end
  table.sort(list, function(a, b) return (a[2].used or 0) < (b[2].used or 0) end)
  for _, item in ipairs(list) do
    if total <= limit then break end
    if item[1] ~= path and not (Music.now and string.find(item[1], Music.now.key, 1, true)) then
      removeEntry(item[1])
      total -= item[2].size or 0
      data.files[item[1]] = nil
    end
  end
  fs.writeJson(INDEX, data)
end
function Music.cacheSize()
  local total, count = 0, 0
  for file, info in pairs(cacheIndex().files) do
    if present(file) then total += info.size or 0; count += 1 end
  end
  return total, count
end
function Music.clearCache()
  for file in pairs(cacheIndex().files) do
    if not (Music.now and string.find(file, Music.now.key, 1, true)) then removeEntry(file); index.files[file] = nil end
  end
  fs.writeJson(INDEX, index)
end
local assets = {}
local function asset(path)
  if assets[path] then return assets[path] end
  if type(getcustomasset) ~= "function" or not fs.exists(path) then return nil end
  local ok, id = pcall(getcustomasset, path)
  B.identity()
  if ok and id then assets[path] = id; return id end
  return nil
end

-- ---------------------------------------------------------------- SoundCloud
local SC = { id = nil, at = 0 }
local function scId(fresh)
  if SC.id and not fresh and os.time() - SC.at < 12 * 3600 then return SC.id end
  local saved = fs.readJson(fs.path("music/soundcloud.json"))
  if not fresh and type(saved) == "table" and type(saved.id) == "string" and os.time() - (saved.at or 0) < 12 * 3600 then
    SC.id, SC.at = saved.id, saved.at
    return SC.id
  end
  local code, html = fetch("https://soundcloud.com/")
  if code ~= 200 or not html then return nil end
  local scripts = {}
  for src in string.gmatch(html, '<script crossorigin src="(https://a%-v2%.sndcdn%.com/assets/[^"]+%.js)"') do scripts[#scripts + 1] = src end
  for i = #scripts, 1, -1 do
    local _, js = fetch(scripts[i])
    local id = js and (string.match(js, 'client_id:"([%w%-_]+)"') or string.match(js, 'client_id=([%w%-_]+)'))
    if id then
      SC.id, SC.at = id, os.time()
      fs.writeJson(fs.path("music/soundcloud.json"), { id = id, at = SC.at })
      return id
    end
  end
  return nil
end
local function scGet(url)
  local id = scId(false)
  if not id then return nil, "SoundCloud could not be reached" end
  local sep = string.find(url, "?", 1, true) and "&" or "?"
  local code, body = fetch(url .. sep .. "client_id=" .. id)
  if code == 401 or code == 403 then
    id = scId(true)
    if not id then return nil, "SoundCloud refused the key" end
    code, body = fetch(url .. sep .. "client_id=" .. id)
  end
  if code ~= 200 then return nil, "SoundCloud said " .. tostring(code) end
  return body
end
local function scTrack(t)
  local media = type(t.media) == "table" and t.media.transcodings or {}
  local playable, preview = false, false
  for _, tr in ipairs(media) do
    local mime = tostring(tr.format and tr.format.mime_type or "")
    if string.find(mime, "audio/mpeg", 1, true) or string.find(mime, "mp4a", 1, true) then playable = true end
    if tr.snipped then preview = true end
  end
  local art = t.artwork_url or (type(t.user) == "table" and t.user.avatar_url) or nil
  if type(art) == "string" then art = (string.gsub(art, "%-large%.", "-t300x300.")) else art = nil end
  return { source = "sc", key = "sc_" .. tostring(t.id), id = t.id, title = tostring(t.title or "?"), artist = tostring(type(t.user) == "table" and t.user.username or "SoundCloud"),
    duration = math.floor((t.full_duration or t.duration or 0) / 1000), art = art, link = t.permalink_url, auth = t.track_authorization,
    playable = playable and t.policy ~= "BLOCK", preview = preview or t.policy == "SNIP", plays = t.playback_count, raw = media }
end
function SC.search(query)
  local body, why = scGet("https://api-v2.soundcloud.com/search/tracks?q=" .. encode(query) .. "&limit=40&offset=0&linked_partitioning=1")
  if not body then return nil, why end
  local data = json(body)
  local out = {}
  for _, t in ipairs(type(data) == "table" and data.collection or {}) do out[#out + 1] = scTrack(t) end
  return out
end
function SC.related(id)
  local body = scGet("https://api-v2.soundcloud.com/tracks/" .. tostring(id) .. "/related?limit=20")
  local data = json(body)
  local out = {}
  for _, t in ipairs(type(data) == "table" and data.collection or {}) do
    local track = scTrack(t)
    if track.playable then out[#out + 1] = track end
  end
  return out
end
-- a playlist -> its init (fMP4) url and its segment urls
local function playlist(url, text)
  local function join(rel)
    if string.find(rel, "^https?://") then return rel end
    if string.sub(rel, 1, 1) == "/" then return (string.match(url, "^(https?://[^/]+)") or "") .. rel end
    return (string.match(url, "^(https?://.*/)") or "") .. rel
  end
  local init = string.match(text, '#EXT%-X%-MAP:[^\r\n]*URI="([^"]+)"')
  local urls = {}
  for line in string.gmatch(text, "[^\r\n]+") do
    line = string.match(line, "^%s*(.-)%s*$")
    if line ~= "" and string.sub(line, 1, 1) ~= "#" then urls[#urls + 1] = join(line) end
  end
  return init and join(init) or nil, urls
end
-- what to play: { mp3 = url } | { hls = playlist url, aac = true } | nil, why
function SC.stream(track)
  local mp3, hlsMp3, aac
  for _, tr in ipairs(track.raw or {}) do
    local mime = tostring(tr.format and tr.format.mime_type or "")
    local protocol = tostring(tr.format and tr.format.protocol or "")
    local isMp3 = string.find(mime, "audio/mpeg", 1, true) ~= nil
    if protocol == "progressive" and isMp3 then mp3 = mp3 or tr.url
    elseif protocol == "hls" and isMp3 then hlsMp3 = hlsMp3 or tr.url
    elseif protocol == "hls" and string.find(mime, "mp4a", 1, true) then aac = aac or tr.url end
  end
  local function resolve(url)
    local extra = track.auth and ((string.find(url, "?", 1, true) and "&" or "?") .. "track_authorization=" .. track.auth) or ""
    local data = json((scGet(url .. extra)))
    return type(data) == "table" and data.url or nil
  end
  if mp3 then
    local direct = resolve(mp3)
    if direct then return { mp3 = direct } end
  end
  if hlsMp3 then
    local url = resolve(hlsMp3)
    if url then return { hls = url } end
  end
  if aac then
    local url = resolve(aac)
    if url then return { hls = url, aac = true } end
  end
  return nil, "SoundCloud has no stream for this one"
end

-- ---------------------------------------------------------------- Audius
local AU = {}
local function auHost()
  if AU.host then return AU.host end
  local _, body = fetch("https://api.audius.co")
  local data = json(body)
  local list = type(data) == "table" and data.data
  AU.host = type(list) == "table" and #list > 0 and list[math.random(#list)] or "https://api.audius.co"
  return AU.host
end
local function auTrack(t)
  local art = type(t.artwork) == "table" and (t.artwork["480x480"] or t.artwork["150x150"]) or nil
  return { source = "au", key = "au_" .. tostring(t.id), id = t.id, title = tostring(t.title or "?"), artist = tostring(type(t.user) == "table" and t.user.name or "Audius"),
    duration = tonumber(t.duration) or 0, art = art, playable = t.is_streamable ~= false, plays = t.play_count }
end
local function auList(path)
  local code, body = fetch(auHost() .. path)
  if code ~= 200 then AU.host = nil; return nil, "Audius said " .. tostring(code) end
  local data = json(body)
  local out = {}
  for _, t in ipairs(type(data) == "table" and data.data or {}) do out[#out + 1] = auTrack(t) end
  return out
end
function AU.search(query) return auList("/v1/tracks/search?query=" .. encode(query) .. "&app_name=" .. APP) end
function AU.trending() return auList("/v1/tracks/trending?limit=40&app_name=" .. APP) end

-- ---------------------------------------------------------------- your own files, and links
local AUDIO = { mp3 = true, ogg = true, wav = true, flac = true }
function Music.files()
  fs.mkdir(FOLDER)
  local out = {}
  for _, path in ipairs(fs.list(FOLDER)) do
    local name, ext = string.match(path, "([^/]+)%.(%w+)$")
    if name and AUDIO[string.lower(ext)] then
      out[#out + 1] = { source = "file", key = "file_" .. string.gsub(name, "[^%w]", ""), title = name, artist = "Your files", duration = 0, path = path, playable = true }
    end
  end
  return out
end
function Music.link(text)
  text = string.match(tostring(text or ""), "^%s*(.-)%s*$")
  local id = string.match(text, "^rbxassetid://(%d+)$") or string.match(text, "^(%d+)$")
  if id then return { source = "roblox", key = "rbx_" .. id, title = "Roblox audio " .. id, artist = "Roblox", duration = 0, sound = "rbxassetid://" .. id, playable = true } end
  if string.find(text, "^https?://") then
    local name = string.match(text, "([^/%?]+)%.%w+%f[%?%z]") or "A link"
    return { source = "link", key = "link_" .. string.sub(string.gsub(text, "%W", ""), -40), title = name, artist = "Link", duration = 0, url = text, playable = true }
  end
  return nil
end

-- ---------------------------------------------------------------- getting a song: a job per song, shared by the player and the prefetch
-- job: { track, kind = "file" | "pieces", asset, pieces = { { asset, start, own, file, last } }, done, failed, why, phase, ready, changed }
local jobs = {}
Music.jobs = jobs
local function say(text) Music.status = text; Music.changed:fire("status") end
local function newJob(track)
  local job = { track = track, pieces = {}, changed = B.Signal.new(), phase = "Getting it ready", fraction = 0 }
  function job.fire() job.changed:fire() end
  return job
end
local function fail(job, why)
  job.failed, job.why = true, why or "it would not play"
  job.fire()
end
local function fileJob(job, data, ext)
  local path = CACHE .. "/" .. job.track.key .. "_" .. token() .. ext
  fs.write(path, data)
  local id = asset(path)
  if not id then return fail(job, "the file would not load") end
  cacheTouch(path, #data)
  job.kind, job.asset, job.done, job.ready = "file", id, true, true
  job.fire()
end
-- a song kept from before: one file, or a folder of pieces with its info.json
local function fromCache(job)
  local key = job.track.key
  for _, file in ipairs(fs.list(CACHE)) do
    local name = string.match(file, "([^/]+)$") or ""
    if string.sub(name, 1, #key + 1) == key .. "_" and string.find(name, "%.%w+$") then
      local id = asset(file)
      if id then
        cacheTouch(file)
        job.kind, job.asset, job.done, job.ready = "file", id, true, true
        return true
      end
    end
  end
  local folder = CACHE .. "/" .. key
  local info = fs.readJson(folder .. "/info.json")
  if type(info) == "table" and type(info.pieces) == "table" and #info.pieces > 0 then
    for i, p in ipairs(info.pieces) do
      local id = asset(folder .. "/" .. p.name)
      if not id then return false end
      job.pieces[i] = { asset = id, start = p.start, own = p.own, file = p.file, last = p.last }
    end
    cacheTouch(folder)
    job.kind, job.done, job.ready, job.total = "pieces", true, true, info.total
    return true
  end
  return false
end
-- SoundCloud's AAC: downloaded four segments at a time, decoded as it comes, kept a piece at a time
local converting = nil
local function convert(job, url)
  local code, text = fetch(url)
  if code ~= 200 or not text then return fail(job, "the stream would not open") end
  if string.find(text, "#EXT-X-KEY", 1, true) then return fail(job, "this one is protected (DRM)") end
  local init, urls = playlist(url, text)
  if not init or #urls == 0 then return fail(job, "the stream is empty") end
  local _, head = fetch(init)
  if not head then return fail(job, "the stream would not open") end
  -- (a song another conversion was busy with in the background gives way to the one asked for)
  if converting and converting ~= job and not converting.foreground then converting.cancelled = true end
  while converting and converting ~= job and not job.cancelled do task.wait(0.1) end
  if job.cancelled then return fail(job, "cancelled") end
  converting = job
  local parts, nextUrl, active, broken = {}, 1, 0, false
  task.spawn(function()
    while nextUrl <= #urls and not broken and not job.cancelled do
      while active >= 4 do task.wait() end
      local i = nextUrl
      nextUrl += 1
      active += 1
      task.spawn(function()
        local body
        for _ = 1, 3 do
          local c, data = fetch(urls[i])
          if c == 200 and data and #data > 0 then body = data; break end
          task.wait(0.4)
        end
        if body then parts[i] = body else broken = true end
        active -= 1
      end)
    end
  end)
  local folder = CACHE .. "/" .. job.track.key
  removeEntry(folder)
  fs.mkdir(folder)
  local stamp = token()
  local kept, bytes = {}, 0
  job.kind = "pieces"
  local total = math.max(job.track.duration or 0, 1)
  local ok, why, info = B.AAC.stream(head, {
    piece = 12, firstPiece = 6, overlap = 0.3,
    first = job.foreground and 0.03 or 0.006, budget = 0.006,
    segment = function(i)
      if i > #urls then return nil end
      while parts[i] == nil and not broken and not job.cancelled do task.wait() end
      local body = parts[i]
      parts[i] = false
      return body or nil
    end,
    cancelled = function() return job.cancelled == true end,
    progress = function(seconds)
      job.phase, job.fraction = "Converting", math.clamp(seconds / total, 0, 1)
      job.fire()
    end,
    onPiece = function(i, wav, start, own, file, last)
      local name = "p" .. i .. "_" .. stamp .. ".wav"
      fs.write(folder .. "/" .. name, wav)
      bytes += #wav
      local id = asset(folder .. "/" .. name)
      job.pieces[i] = { asset = id, start = start, own = own, file = file, last = last }
      kept[i] = { name = name, start = start, own = own, file = file, last = last }
      job.ready = true
      job.fire()
    end,
  })
  B.identity()
  if converting == job then converting = nil end
  if not ok then
    removeEntry(folder)
    if broken then why = "a part of the stream failed" end
    return fail(job, why)
  end
  fs.writeJson(folder .. "/info.json", { v = 1, pieces = kept, total = info.seconds, rate = info.rate, channels = info.channels })
  cacheTouch(folder, bytes)
  job.total, job.done = info.seconds, true
  job.fire()
end
local function run(job)
  local track = job.track
  if track.sound then job.kind, job.asset, job.done, job.ready = "file", track.sound, true, true; return job.fire() end
  if track.source == "file" then
    local id = asset(track.path)
    if not id then return fail(job, "the file would not load") end
    job.kind, job.asset, job.done, job.ready = "file", id, true, true
    return job.fire()
  end
  if fromCache(job) then return job.fire() end
  job.phase = "Downloading"
  job.fire()
  if track.source == "link" then
    local code, body = fetch(track.url)
    if code ~= 200 or not body or #body < 512 then return fail(job, "the link did not answer") end
    local magic = string.sub(body, 1, 4)
    return fileJob(job, body, magic == "OggS" and ".ogg" or (magic == "RIFF" and ".wav" or (magic == "fLaC" and ".flac" or ".mp3")))
  elseif track.source == "au" then
    local code, body = fetch(auHost() .. "/v1/tracks/" .. tostring(track.id) .. "/stream?app_name=" .. APP)
    if code ~= 200 or not body or #body < 1000 then AU.host = nil; return fail(job, "Audius would not stream it") end
    return fileJob(job, body, ".mp3")
  elseif track.source == "sc" then
    if not track.raw then Music.revive(track) end
    local stream, why = SC.stream(track)
    if not stream then return fail(job, why) end
    if stream.mp3 then
      local code, body = fetch(stream.mp3)
      if code ~= 200 or not body then return fail(job, "the download failed") end
      return fileJob(job, body, ".mp3")
    end
    if not stream.aac then
      -- (an HLS of MP3 parts: the parts joined are an MP3)
      local code, text = fetch(stream.hls)
      if code ~= 200 or not text then return fail(job, "the stream would not open") end
      local _, urls = playlist(stream.hls, text)
      local all = {}
      for i, url in ipairs(urls) do
        local c, data = fetch(url)
        if c ~= 200 or not data then return fail(job, "a part of the stream failed") end
        all[i] = data
        job.phase, job.fraction = "Downloading", i / #urls
        job.fire()
      end
      return fileJob(job, table.concat(all), ".mp3")
    end
    if not B.AAC then return fail(job, "no AAC decoder") end
    return convert(job, stream.hls)
  end
  return fail(job, "no source")
end
-- the job for a track: the one already going, or a new one
local function jobFor(track, foreground)
  local job = jobs[track.key]
  if job and not job.failed and not job.cancelled then
    if foreground then job.foreground = true end
    return job
  end
  job = newJob(track)
  job.foreground = foreground
  jobs[track.key] = job
  task.spawn(function()
    local ok, err = pcall(run, job)
    B.identity()
    if not ok then fail(job, tostring(err)) end
    if job.failed then jobs[track.key] = nil end
  end)
  return job
end

-- ---------------------------------------------------------------- the deck: three voices in a group that carries the effects
local deck = { voices = {}, main = nil, nextVoice = nil, piece = 0, job = nil, track = nil, mode = nil, waiting = false, paused = {}, seek = nil }
Music.deck = deck
local group, eq, reverb, pitch, comp
local function speed() return (Config.get("music.speed") or 100) / 100 end
-- The volume the group goes to: the setting, or what a volume line is being dragged to (Music.liveVolume, a share of
-- 0..200 %). The group eases there every frame (step), so a drag never steps or clicks.
local function volumeGoal()
  local percent = Music.liveVolume and Music.liveVolume * 200 or (Config.get("music.volume") or 60)
  return math.clamp(percent / 100, 0, 3) * 0.6
end
local function effects()
  if not group then return end
  -- (the volume itself is eased there by step every frame; set at once only for a group just made)
  if not deck.volumeSet then group.Volume = volumeGoal(); deck.volumeSet = true end
  eq.LowGain = Config.get("music.bass") or 0
  eq.MidGain = Config.get("music.mid") or 0
  eq.HighGain = Config.get("music.treble") or 0
  local wet = (Config.get("music.reverb") or 0) / 100
  reverb.Enabled = wet > 0
  reverb.WetLevel = -26 + wet * 22
  reverb.DryLevel = -wet * 3
  reverb.DecayTime = 0.8 + wet * 3.2
  local rate = speed()
  pitch.Enabled = Config.get("music.keepPitch") == true and math.abs(rate - 1) > 0.01
  pitch.Octave = math.clamp(1 / rate, 0.5, 2)
  comp.Enabled = Config.get("music.even") == true
  comp.Threshold, comp.Ratio, comp.Attack, comp.Release, comp.GainMakeup = -20, 4, 0.01, 0.25, 6
  for _, voice in ipairs(deck.voices) do voice.sound.PlaybackSpeed = rate end
end
local ended
local function ensureDeck()
  if group and group.Parent then return end
  group = Instance.new("SoundGroup")
  group.Name = util.randomName()
  group.Parent = S.SoundService
  B.own(group)
  deck.volumeSet = false
  eq = Instance.new("EqualizerSoundEffect"); eq.Priority = 1; eq.Parent = group
  comp = Instance.new("CompressorSoundEffect"); comp.Priority = 2; comp.Parent = group
  pitch = Instance.new("PitchShiftSoundEffect"); pitch.Priority = 3; pitch.Parent = group
  reverb = Instance.new("ReverbSoundEffect"); reverb.Priority = 4; reverb.Parent = group
  table.clear(deck.voices)
  for i = 1, 3 do
    local sound = Instance.new("Sound")
    sound.Name = "Voice" .. i
    sound.SoundGroup = group
    sound.Parent = group
    local voice = { sound = sound, gain = 0 }
    sound.Ended:Connect(function() if B.alive then B.try("music.ended", ended, voice) end end)
    deck.voices[i] = voice
  end
  effects()
end
function Music.sound() return deck.main and deck.main.sound or nil end
-- Is a seek on its way (and, given a voice, is it the one that seek loads)? The frame's next-piece look stands aside
-- for it, and no use of a free voice takes its voice: before 2026-11-02 that look took the very voice a seek was
-- loading and loaded the piece after the old place into it, so a seek played the wrong part, and crossed back into
-- itself (a part heard twice).
local function seekHas(voice)
  if voice then return voice.held ~= nil end
  return deck.seek ~= nil
end
-- a voice nothing is using
local function freeVoice()
  for _, voice in ipairs(deck.voices) do
    if voice ~= deck.main and voice ~= deck.nextVoice and not voice.fade and not seekHas(voice) and not voice.sound.IsPlaying then return voice end
  end
  return nil
end
-- a voice for a seek, whatever is going on: a free one, else the next piece's (loaded again later), else one fading out
local function voiceForSeek()
  local voice = freeVoice()
  if voice then return voice end
  if deck.nextVoice and not deck.nextVoice.held then
    voice = deck.nextVoice
    deck.nextVoice = nil
    return voice
  end
  for _, other in ipairs(deck.voices) do
    if other ~= deck.main and not other.held then
      other.fade = nil
      other.sound:Stop()
      return other
    end
  end
  return nil
end
-- a seek not landed yet is let go of (another seek, a new song, a stop)
local function dropSeek()
  local pending = deck.seek
  deck.seek = nil
  if pending and pending.voice and pending.voice.held == pending.token then
    pending.voice.held = nil
    if pending.voice ~= deck.main then pending.voice.sound:Stop() end
  end
end
local function fadeVoice(voice, to, seconds, stop)
  voice.fade = { from = voice.gain, to = to, t = 0, dur = math.max(seconds, 0.01), stop = stop }
end
local function stopAll(seconds)
  dropSeek()
  for _, voice in ipairs(deck.voices) do
    voice.held = nil
    if voice.sound.IsPlaying then
      if seconds and seconds > 0 then fadeVoice(voice, 0, seconds, true) else voice.fade = nil; voice.sound:Stop() end
    end
  end
  deck.main, deck.nextVoice, deck.waiting = nil, nil, false
  table.clear(deck.paused)
end
-- where the song is, and how long it is
function Music.position()
  -- (a seek on its way: where it goes, so the line and the words are there at once and never jump back)
  if deck.seek then return deck.seek.target end
  local main = deck.main
  if not main then return Music.startAt or Music.resumeAt or 0 end
  if deck.mode == "pieces" then
    local p = deck.job and deck.job.pieces[deck.piece]
    return (p and p.start or 0) + main.sound.TimePosition
  end
  return main.sound.TimePosition
end
function Music.length()
  local job = deck.job
  if deck.mode == "pieces" then return (job and job.done and job.total) or (deck.track and deck.track.duration) or 0 end
  local main = deck.main
  if main and main.sound.TimeLength > 0 then return main.sound.TimeLength end
  return (deck.track and deck.track.duration) or (Music.now and Music.now.duration) or 0
end
function Music.loudness()
  local main = deck.main
  return (main and main.sound.IsPlaying) and main.sound.PlaybackLoudness or 0
end

local function remember(track)
  local history = table.clone(Config.get("music.history") or {})
  for i = #history, 1, -1 do if history[i].key == track.key then table.remove(history, i) end end
  table.insert(history, 1, Music.compact(track))
  while #history > 60 do table.remove(history) end
  Config.set("music.history", history)
end
-- the deck takes up a song whose job has its first sound loaded on `voice`
local function begin(track, job, voice, offset, fadeIn)
  local old = deck.main
  dropSeek()
  voice.held = nil
  deck.track, deck.job, deck.mode = track, job, job.kind
  deck.piece = job.kind == "pieces" and 1 or 0
  deck.main, deck.nextVoice, deck.waiting = voice, nil, false
  table.clear(deck.paused)
  local sound = voice.sound
  sound.PlaybackSpeed = speed()
  sound.TimePosition = offset or 0
  sound:Play()
  voice.gain = fadeIn and 0 or 1
  if fadeIn then fadeVoice(voice, 1, fadeIn) else voice.fade = nil end
  if old and old ~= voice and old.sound.IsPlaying then fadeVoice(old, 0, fadeIn or 0.12, true) end
  Music.state = "playing"
  Music.startedAt = os.clock()
  say(nil)
  remember(track)
  Music.changed:fire("state")
  if Config.get("music.announce") ~= false then
    Window.toast({ title = track.title, text = track.artist, icon = "music", time = 2.6, music = track })
  end
  Music.prefetch()
end
-- load a job's first sound on a free voice, then start it (at `offset` seconds: a restored session)
local playToken = 0
local function startJob(track, job, offset)
  playToken += 1
  local mine = playToken
  task.spawn(function()
    while not (job.ready or job.failed) and mine == playToken do
      say(string.format("%s%s", job.phase or "Getting it ready", (job.fraction and job.fraction > 0) and string.format(" %d%%", math.floor(job.fraction * 100)) or "..."))
      task.wait(0.1)
    end
    if mine ~= playToken then return end
    if job.failed then
      Music.state = "error"
      say("Could not play: " .. tostring(job.why))
      Music.changed:fire("state")
      -- (a song that will not play is passed over, after a moment)
      task.delay(1.6, function() if mine == playToken and Music.state == "error" and #Music.queue > Music.index then Music.next(true) end end)
      return
    end
    ensureDeck()
    local voice = freeVoice()
    while not voice and mine == playToken do task.wait(); voice = freeVoice() end
    if mine ~= playToken then return end
    -- (a restored session's place, or one a seek asked for while it was loading: the piece that holds it)
    if Music.startAt then offset = Music.startAt; Music.startAt = nil end
    local first, at = job.asset, offset or 0
    if job.kind == "pieces" then
      local k = 1
      if at > 0 then
        while not job.done and not job.failed and (job.pieces[#job.pieces].start + job.pieces[#job.pieces].own) < at and mine == playToken do task.wait(0.1) end
        for i, p in ipairs(job.pieces) do if at < p.start + p.own then k = i; break end end
      end
      first, at = job.pieces[k].asset, math.max(at - job.pieces[k].start, 0)
      job.startPiece = k
    end
    voice.sound.SoundId = first
    local began = os.clock()
    while not voice.sound.IsLoaded and os.clock() - began < 12 and mine == playToken do task.wait() end
    if mine ~= playToken then return end
    if not voice.sound.IsLoaded then
      Music.state = "error"
      say("The sound would not load")
      Music.changed:fire("state")
      return
    end
    begin(track, job, voice, at, 0.06)
    if job.startPiece then deck.piece = job.startPiece; job.startPiece = nil end
  end)
end

-- ---------------------------------------------------------------- the queue
-- play a track now: it goes in after the one playing and becomes the one playing
function Music.play(track, fromQueue)
  if not track or track.playable == false then return end
  -- (a song kept from this PC plays here through SoundCloud: the closest by name and length)
  if track.source == "pc" then
    say("Finding it on SoundCloud...")
    task.spawn(function()
      local found = Music.findOnSoundCloud(track)
      B.identity()
      if not found then say("Not on SoundCloud: " .. tostring(track.title)); return end
      if fromQueue and Music.queue[Music.index] == track then Music.queue[Music.index] = found end
      Music.play(found, fromQueue)
    end)
    return
  end
  if not fromQueue then
    local at = math.max(Music.index + 1, 1)
    table.insert(Music.queue, at, track)
    Music.index = at
  end
  Music.resumeAt, Music.startAt = nil, nil
  Music.now = track
  Music.state = "loading"
  stopAll(0.15)
  deck.track = track
  -- (its words are looked for from the click, not from when a view first asks: ready by the time it plays)
  if B.Lyrics then B.try("music.lyrics", B.Lyrics.forTrack, track) end
  Music.changed:fire("track")
  Music.changed:fire("queue")
  startJob(track, jobFor(track, true), 0)
end
-- which song comes next (shuffle draws it once and keeps it)
local shuffleBag = nil
function Music.upcoming()
  local count = #Music.queue
  if count == 0 then return nil end
  if Config.get("music.repeat") == "one" and Music.now then return Music.now end
  if Config.get("music.shuffle") and count > 1 then
    if not (shuffleBag and Music.queue[shuffleBag] and shuffleBag ~= Music.index) then
      repeat shuffleBag = math.random(count) until shuffleBag ~= Music.index
    end
    return Music.queue[shuffleBag]
  end
  if Music.index + 1 <= count then return Music.queue[Music.index + 1] end
  if Config.get("music.repeat") == "all" then return Music.queue[1] end
  return nil
end
-- the next of the queue is made ready while this one plays
function Music.prefetch()
  local nextTrack = Music.upcoming()
  -- (the next song's words too, while this one plays)
  if nextTrack and nextTrack ~= Music.now and B.Lyrics then B.try("music.lyrics", B.Lyrics.forTrack, nextTrack) end
  if not nextTrack or nextTrack == Music.now or nextTrack.source == "file" or nextTrack.sound then return end
  if jobs[nextTrack.key] or Music.prefetching == nextTrack.key then return end
  Music.prefetching = nextTrack.key
  task.delay(2, function()
    if Music.prefetching == nextTrack.key then Music.prefetching = nil end
    if not B.alive or Music.upcoming() ~= nextTrack or jobs[nextTrack.key] then return end
    jobFor(nextTrack, false)
  end)
end
local function advanceIndex(track)
  for i, item in ipairs(Music.queue) do
    if item == track then Music.index = i; return end
  end
end
local autoBusy = false
function Music.next(auto)
  local nextTrack = Music.upcoming()
  shuffleBag = nil
  if nextTrack and nextTrack == Music.now and not auto then
    -- (repeat one: the button still moves on)
    nextTrack = Music.queue[Music.index + 1] or (Config.get("music.repeat") ~= "off" and Music.queue[1]) or nil
  end
  if nextTrack then
    if nextTrack == Music.now and auto then Music.seekTo(0); return end
    advanceIndex(nextTrack)
    Music.play(nextTrack, true)
    return
  end
  -- the queue ran out: songs like the last one (SoundCloud), or the rest of what was searched
  if auto and Config.get("music.autoplay") ~= false and Music.now and not autoBusy then
    autoBusy = true
    local last = Music.now
    task.spawn(function()
      local more
      if last.source == "sc" and last.id then more = SC.related(last.id) end
      B.identity()
      if not more or #more == 0 then
        more = {}
        local after = false
        for _, track in ipairs(Music.results) do
          if after and track.playable ~= false then more[#more + 1] = track end
          if track.key == last.key then after = true end
        end
      end
      autoBusy = false
      if #more == 0 then Music.state = "idle"; Music.changed:fire("state"); return end
      for i = 1, math.min(#more, 10) do Music.queue[#Music.queue + 1] = more[i] end
      Music.changed:fire("queue")
      Music.index += 1
      Music.play(Music.queue[Music.index], true)
    end)
    return
  end
  Music.state = "idle"
  stopAll(0.3)
  Music.changed:fire("state")
end
function Music.previous()
  if Music.position() > 4 then Music.seekTo(0); return end
  if Music.index > 1 then
    Music.index -= 1
    Music.play(Music.queue[Music.index], true)
  else
    Music.seekTo(0)
  end
end
function Music.toggle()
  if not deck.main or not Music.now then
    local first = Music.now or Music.queue[math.max(Music.index, 1)] or Music.results[1]
    if not first then return end
    if Music.state == "loading" then return end
    -- (a restored song starts where it was)
    local at = Music.resumeAt
    Music.resumeAt = nil
    if not table.find(Music.queue, first) then Music.play(first); return end
    advanceIndex(first)
    local track = first
    Music.now = track
    Music.state = "loading"
    deck.track = track
    Music.changed:fire("state")
    startJob(track, jobFor(track, true), at or 0)
    return
  end
  if Music.state == "playing" then
    table.clear(deck.paused)
    for _, voice in ipairs(deck.voices) do
      if voice.sound.IsPlaying then voice.sound:Pause(); deck.paused[#deck.paused + 1] = voice end
    end
    Music.state = "paused"
  elseif Music.state == "paused" then
    for _, voice in ipairs(deck.paused) do voice.sound:Resume() end
    table.clear(deck.paused)
    Music.state = "playing"
    Music.startedAt = os.clock()
  end
  Music.changed:fire("state")
end
function Music.stop()
  playToken += 1
  stopAll(0.2)
  Music.state = "idle"
  say(nil)
  Music.changed:fire("state")
end
-- To a time (seconds) in the song. One file: its place is set at once. In pieces (SoundCloud's AAC): the piece that
-- has that time is loaded on a voice held for this seek, and the song is heard from there the moment it has loaded;
-- every other voice then stops (the old place, the next piece meant for it). Until then the song reads as being there
-- already (Music.position), so the line and the words go at once. Past what is converted yet: the old place goes
-- quiet and it waits ("Buffering..."), then starts at the very time asked for. A newer seek, a new song or a stop
-- lets go of one still on its way: only the last one lands.
local seekToken = 0
local function pieceFor(job, seconds)
  for i, p in ipairs(job.pieces) do
    if seconds < p.start + p.own then return i, p end
  end
  return nil
end
function Music.seekTo(seconds)
  local main = deck.main
  if not main then
    -- (still getting it ready: it starts there instead)
    if Music.state == "loading" and type(seconds) == "number" then Music.startAt = math.max(0, seconds) end
    return
  end
  seconds = math.max(0, tonumber(seconds) or 0)
  seekToken += 1
  local token = seekToken
  dropSeek()
  if deck.mode ~= "pieces" then
    local length = main.sound.TimeLength
    -- (a length not known yet would put it at 0: the start of the song again)
    main.sound.TimePosition = length > 0.1 and math.min(seconds, length - 0.05) or seconds
    if Music.state == "playing" and not main.sound.IsPlaying then main.sound:Play() end
    return
  end
  local job = deck.job
  if not job then return end
  local k, p = pieceFor(job, seconds)
  if not k and job.done and #job.pieces > 0 then
    -- (past the end: the last moment of it)
    k = #job.pieces
    p = job.pieces[k]
    seconds = math.max(p.start + p.own - 0.3, p.start)
  end
  if k and k == deck.piece and main.sound.IsLoaded then
    -- (in the piece already playing: only its place changes)
    main.sound.TimePosition = math.clamp(seconds - p.start, 0, math.max(p.file - 0.05, 0))
    if Music.state == "playing" and not main.sound.IsPlaying then main.sound:Play() end
    deck.waiting = false
    say(nil)
    return
  end
  local pending = { token = token, target = seconds, job = job }
  deck.seek = pending
  task.spawn(function()
    -- not converted that far yet: quiet until it is
    if not k then
      say("Buffering...")
      for _, voice in ipairs(deck.voices) do if voice.sound.IsPlaying then voice.fade = nil; voice.sound:Pause() end end
      while seekToken == token and deck.job == job and not job.failed do
        k, p = pieceFor(job, seconds)
        if k then break end
        if job.done then
          k = #job.pieces
          p = job.pieces[k]
          if p then seconds = math.max(p.start + p.own - 0.3, p.start); pending.target = seconds end
          break
        end
        task.wait(0.1)
      end
      if seekToken ~= token or deck.job ~= job or not p then return end
    end
    local voice = voiceForSeek()
    while not voice and seekToken == token do task.wait(); voice = voiceForSeek() end
    if seekToken ~= token then return end
    voice.held = token
    pending.voice = voice
    voice.fade = nil
    voice.sound:Stop()
    voice.sound.SoundId = p.asset
    local began = os.clock()
    while not voice.sound.IsLoaded and os.clock() - began < 6 and seekToken == token do task.wait() end
    if seekToken ~= token or deck.job ~= job then
      if voice.held == token then voice.held = nil end
      return
    end
    voice.held = nil
    deck.seek = nil
    if not voice.sound.IsLoaded then
      say("That part would not load")
      task.delay(2, function() if Music.status == "That part would not load" then say(nil) end end)
      return
    end
    -- it lands: this voice is the song now, everything else is quiet
    for _, other in ipairs(deck.voices) do
      if other ~= voice then other.fade = nil; other.gain = 0; other.sound:Stop() end
    end
    voice.sound.PlaybackSpeed = speed()
    voice.sound.TimePosition = math.clamp(seconds - p.start, 0, math.max(p.file - 0.05, 0))
    voice.gain = 1
    voice.sound.Volume = 1
    voice.sound:Play()
    table.clear(deck.paused)
    if Music.state ~= "playing" then voice.sound:Pause(); deck.paused[1] = voice end
    deck.main, deck.piece, deck.waiting, deck.nextVoice = voice, k, false, nil
    say(nil)
  end)
end
function Music.seek(fraction)
  local length = Music.length()
  if length > 0 then Music.seekTo(math.clamp(fraction, 0, 0.999) * length) end
end

-- the end of a voice: the next piece, or the next song
ended = function(voice)
  -- (a seek on its way has the song: the old place running out is not the end)
  if voice ~= deck.main or Music.state ~= "playing" or deck.seek then return end
  if deck.mode == "pieces" then
    local p = deck.job and deck.job.pieces[deck.piece]
    if p and not p.last then
      -- (the next piece is not ready: it carries on from here when it is)
      deck.waiting = true
      say("Buffering...")
      return
    end
  end
  if Config.get("music.repeat") == "one" then Music.seekTo(0); return end
  Music.next(true)
end

-- every frame: fades, the step from piece to piece, and the crossfade into the next song
local function step(dt)
  if not group then return end
  -- the volume eases to where it is set (a line dragged, a key, the slider): no steps, no clicks
  local goal = volumeGoal()
  local level = group.Volume
  if math.abs(goal - level) > 0.0004 then
    group.Volume = math.abs(goal - level) < 0.002 and goal or level + (goal - level) * (1 - math.exp(-math.min(dt, 0.1) * 16))
  end
  for _, voice in ipairs(deck.voices) do
    local f = voice.fade
    if f then
      f.t += dt
      local p = math.clamp(f.t / f.dur, 0, 1)
      voice.gain = f.from + (f.to - f.from) * p
      if p >= 1 then
        voice.fade = nil
        if f.stop then voice.sound:Stop() end
      end
    end
    -- (2026-11-11: only when it has changed. This runs every frame for every voice)
    if voice.sound.Volume ~= voice.gain then voice.sound.Volume = voice.gain end
  end
  -- (nothing moves on from piece to piece while a seek is on its way: it has the song)
  if Music.state ~= "playing" or not deck.main or seekHas() then return end
  local main = deck.main
  if deck.mode == "pieces" then
    local job = deck.job
    local p = job.pieces[deck.piece]
    local q = job.pieces[deck.piece + 1]
    if q and not deck.nextVoice then
      local voice = freeVoice()
      if voice then voice.sound.SoundId = q.asset; deck.nextVoice = voice end
    end
    local nv = deck.nextVoice
    if p and q and nv and nv.sound.IsLoaded then
      if deck.waiting then
        -- (it ran out and waited: carry on where the last one stopped)
        nv.sound.PlaybackSpeed = speed()
        nv.sound.TimePosition = math.max(0, p.file - p.own)
        nv.sound:Play()
        nv.gain, nv.fade = 1, nil
        deck.main, deck.nextVoice, deck.piece, deck.waiting = nv, nil, deck.piece + 1, false
        say(nil)
      elseif main.sound.TimePosition >= p.own then
        -- the overlap (0.3 s, longer than a slow frame): the next piece comes in under this one
        local left = math.clamp(p.file - main.sound.TimePosition, 0.02, 0.1)
        nv.sound.PlaybackSpeed = speed()
        nv.sound.TimePosition = main.sound.TimePosition - p.own
        nv.sound:Play()
        nv.gain = 0
        fadeVoice(nv, 1, left)
        fadeVoice(main, 0, left, true)
        deck.main, deck.nextVoice, deck.piece = nv, nil, deck.piece + 1
      end
    end
  end
  -- the crossfade into the next song, when one is set and the next is ready
  local fade = Config.get("music.fade") or 0
  if fade > 0 and not deck.crossing then
    local length = Music.length()
    local left = length - Music.position()
    local cur = deck.job and deck.job.pieces[deck.piece]
    local lastPiece = deck.mode ~= "pieces" or (deck.job and deck.job.done and cur and cur.last)
    if length > fade * 2 and left <= fade and left > 0.2 and lastPiece then
      local nextTrack = Music.upcoming()
      local job = nextTrack and nextTrack ~= Music.now and jobs[nextTrack.key]
      if job and job.ready and not job.failed then
        local voice = freeVoice()
        if voice then
          deck.crossing = true
          voice.sound.SoundId = job.kind == "pieces" and job.pieces[1].asset or job.asset
          task.spawn(function()
            local began = os.clock()
            while not voice.sound.IsLoaded and os.clock() - began < 2 do task.wait() end
            deck.crossing = false
            if not voice.sound.IsLoaded or Music.state ~= "playing" then return end
            local fadeFor = math.max(Music.length() - Music.position(), 0.3)
            shuffleBag = nil
            advanceIndex(nextTrack)
            Music.now = nextTrack
            Music.changed:fire("track")
            begin(nextTrack, job, voice, 0, fadeFor)
          end)
        end
      elseif nextTrack and not job then
        Music.prefetch()
      end
    end
  end
end
Motion.every(step, nil, "music.deck")

-- ---------------------------------------------------------------- the library: queue, likes, playlists
function Music.enqueue(track, playNext)
  if playNext then table.insert(Music.queue, math.max(Music.index + 1, 1), track) else Music.queue[#Music.queue + 1] = track end
  Music.changed:fire("queue")
  Music.prefetch()
end
function Music.remove(position)
  if not Music.queue[position] then return end
  table.remove(Music.queue, position)
  if position <= Music.index then Music.index = math.max(Music.index - 1, 0) end
  shuffleBag = nil
  Music.changed:fire("queue")
end
function Music.move(from, to)
  local track = Music.queue[from]
  if not track or not Music.queue[to] or from == to then return end
  local current = Music.queue[Music.index]
  table.remove(Music.queue, from)
  table.insert(Music.queue, to, track)
  if current then advanceIndex(current) end
  Music.changed:fire("queue")
end
function Music.clearQueue()
  local current = Music.now
  table.clear(Music.queue)
  Music.index = 0
  if current and Music.state ~= "idle" then Music.queue[1] = current; Music.index = 1 end
  shuffleBag = nil
  Music.changed:fire("queue")
end
-- what is kept of a track (likes, history, playlists): enough to find and play it again
function Music.compact(track)
  return { source = track.source, key = track.key, id = track.id, title = track.title, artist = track.artist, duration = track.duration, art = track.art,
    link = track.link, path = track.path, url = track.url, sound = track.sound }
end
function Music.liked(track)
  if not track then return false end
  for _, item in ipairs(Config.get("music.liked") or {}) do if item.key == track.key then return true end end
  return false
end
function Music.like(track, on)
  if not track then return end
  local list = table.clone(Config.get("music.liked") or {})
  for i = #list, 1, -1 do if list[i].key == track.key then table.remove(list, i) end end
  if on then table.insert(list, 1, Music.compact(track)) end
  Config.set("music.liked", list)
  Music.changed:fire("liked")
end
function Music.playlists() return Config.get("music.playlists") or {} end
local function savePlaylists(list) Config.set("music.playlists", list); Music.changed:fire("playlists") end
function Music.newPlaylist(name)
  name = string.match(tostring(name or ""), "^%s*(.-)%s*$")
  if name == "" then return nil end
  local list = table.clone(Music.playlists())
  for _, item in ipairs(list) do if string.lower(item.name) == string.lower(name) then return item end end
  local item = { name = string.sub(name, 1, 40), tracks = {} }
  list[#list + 1] = item
  savePlaylists(list)
  return item
end
function Music.addTo(name, track)
  local list = table.clone(Music.playlists())
  for i, item in ipairs(list) do
    if item.name == name then
      local copy = { name = item.name, tracks = table.clone(item.tracks or {}) }
      for _, t in ipairs(copy.tracks) do if t.key == track.key then return end end
      copy.tracks[#copy.tracks + 1] = Music.compact(track)
      list[i] = copy
      savePlaylists(list)
      return
    end
  end
end
function Music.removeFrom(name, key)
  local list = table.clone(Music.playlists())
  for i, item in ipairs(list) do
    if item.name == name then
      local copy = { name = item.name, tracks = {} }
      for _, t in ipairs(item.tracks or {}) do if t.key ~= key then copy.tracks[#copy.tracks + 1] = t end end
      list[i] = copy
      savePlaylists(list)
      return
    end
  end
end
function Music.deletePlaylist(name)
  local list = {}
  for _, item in ipairs(Music.playlists()) do if item.name ~= name then list[#list + 1] = item end end
  savePlaylists(list)
end
-- play a list from the start (or a chosen song in it)
function Music.playList(tracks, first)
  if #tracks == 0 then return end
  table.clear(Music.queue)
  for _, t in ipairs(tracks) do Music.queue[#Music.queue + 1] = table.clone(t) end
  Music.index = math.clamp(first or 1, 1, #Music.queue)
  if Config.get("music.shuffle") and not first then Music.index = math.random(#Music.queue) end
  shuffleBag = nil
  Music.changed:fire("queue")
  Music.play(Music.queue[Music.index], true)
end
-- a kept SoundCloud track has no stream list: it is asked for again
function Music.revive(track)
  if track and track.source == "sc" and not track.raw and track.id then
    local body = scGet("https://api-v2.soundcloud.com/tracks/" .. tostring(track.id))
    local data = json(body)
    if type(data) == "table" and data.id then
      local fresh = scTrack(data)
      track.raw, track.auth, track.playable, track.preview = fresh.raw, fresh.auth, fresh.playable, fresh.preview
      track.art = track.art or fresh.art
    end
    B.identity()
  end
  return track
end
function Music.findOnSoundCloud(track)
  local list = SC.search(tostring(track.artist or "") .. " " .. tostring(track.title or ""))
  local best, bestOff
  for _, t in ipairs(list or {}) do
    if t.playable and not t.preview then
      local off = ((track.duration or 0) > 0 and (t.duration or 0) > 0) and math.abs(t.duration - track.duration) or 30
      if not best or off < bestOff then best, bestOff = t, off end
    end
  end
  return best
end
function Music.search(source, query)
  local list, why
  if source == "files" then list = Music.files()
  elseif source == "au" then
    if #string.gsub(query or "", "%s", "") == 0 then list, why = AU.trending() else list, why = AU.search(query) end
  else list, why = SC.search(query) end
  B.identity()
  if list then
    Music.results, Music.resultsFor = list, source
    Music.changed:fire("results")
  end
  return list, why
end
-- the cover: downloaded once, then shown from disk
local artWaiting = {}
function Music.coverPath(track) return track and track.art and (ART .. "/" .. track.key .. ".jpg") or nil end
function Music.cover(track, image, done)
  if not (track and image) then return end
  if not track.art then image.Image = ""; if done then done(nil) end; return end
  local path = Music.coverPath(track)
  local id = asset(path)
  if id then image.Image = id; if done then done(path) end; return end
  image.Image = ""
  if artWaiting[path] then table.insert(artWaiting[path], { image, done }); return end
  artWaiting[path] = { { image, done } }
  task.spawn(function()
    local code, data = fetch(track.art)
    if code == 200 and data and #data > 100 then fs.write(path, data) end
    local got = asset(path)
    for _, waiting in ipairs(artWaiting[path]) do
      if waiting[1].Parent and got then waiting[1].Image = got end
      if waiting[2] then B.try("music.cover", waiting[2], got and path or nil) end
    end
    artWaiting[path] = nil
  end)
end
function Music.time(seconds)
  seconds = math.max(0, math.floor(seconds or 0))
  if seconds >= 3600 then return string.format("%d:%02d:%02d", seconds // 3600, (seconds // 60) % 60, seconds % 60) end
  return string.format("%d:%02d", seconds // 60, seconds % 60)
end
function Music.plays(n)
  n = tonumber(n)
  if not n or n <= 0 then return nil end
  if n >= 1e6 then return string.format("%.1fM plays", n / 1e6) end
  if n >= 1e3 then return string.format("%.0fK plays", n / 1e3) end
  return n .. " plays"
end
local SOURCE_NAME = { sc = "SoundCloud", au = "Audius", file = "Your file", link = "Link", roblox = "Roblox", pc = "This PC" }
function Music.sourceName(track) return track and SOURCE_NAME[track.source] or "" end

-- ---------------------------------------------------------------- in front: this player, or this PC's (48_pc)
-- Both answer the same calls, so the card, the island and the tab draw either.
local GAME = { kind = "game" }
Music.game = GAME
function GAME.track() return Music.now end
function GAME.state() return Music.state end
function GAME.status() return Music.status end
function GAME.position() return Music.position() end
function GAME.length() return Music.length() end
function GAME.toggle() Music.toggle() end
function GAME.next() Music.next(false) end
function GAME.previous() Music.previous() end
function GAME.seekTo(seconds) Music.seekTo(seconds) end
function GAME.seek(fraction) Music.seek(fraction) end
function GAME.canSeek() return deck.main ~= nil end
-- (the line is the whole 0..200 % the setting has: a 200 % setting fell to 100 % the moment it was touched, before)
function GAME.volume() return math.clamp((Music.liveVolume and Music.liveVolume * 200 or (Config.get("music.volume") or 60)) / 200, 0, 1) end
-- while dragged it is heard at once and saved when let go (final)
function GAME.setVolume(value, final)
  value = math.clamp(value, 0, 1)
  if final == false then Music.liveVolume = value; return end
  Music.liveVolume = nil
  Config.set("music.volume", math.floor(value * 200 + 0.5))
end
function GAME.shuffle() return Config.get("music.shuffle") == true end
function GAME.setShuffle(on) Config.set("music.shuffle", on == true) end
function GAME.repeatMode() return Config.get("music.repeat") or "off" end
function GAME.setRepeat(mode) Config.set("music.repeat", mode) end
function GAME.cover(track, image, done) Music.cover(track, image, done) end
function GAME.tint(track, done) Music.tint(track, done) end
function GAME.loudness() return Music.loudness() end
function GAME.label(track) return Music.sourceName(track) end
-- the next songs: { track, index } (at most eight)
function GAME.queue()
  local out = {}
  for i = Music.index + 1, math.min(#Music.queue, Music.index + 8) do out[#out + 1] = { track = Music.queue[i], index = i } end
  return out
end
-- the game's player, unless this PC is the one playing (or started last, or the game has nothing)
function Music.front()
  local PC = B.PC
  local pc = PC and PC.ctl
  if not (pc and PC.live and PC.track) then return GAME end
  local gameOn = Music.state == "playing" or Music.state == "loading"
  local pcOn = PC.playing()
  if pcOn and not gameOn then return pc end
  if gameOn and not pcOn then return GAME end
  local pcLater = (PC.startedAt or 0) > (Music.startedAt or 0)
  if pcOn and gameOn then return pcLater and pc or GAME end
  if not Music.now or pcLater then return pc end
  return GAME
end
-- the Music tab, in the look in use
function Music.openTab()
  local look = Window.look()
  Window.showActive(true)
  if look == "unnamed" and B.Unnamed and B.Unnamed.go then B.Unnamed.go("music")
  elseif look == "novoline" and B.Novoline and B.Novoline.go then B.Novoline.go("music")
  else Window.go("music") end
end

-- ---------------------------------------------------------------- drawing: the same pieces in every look (Window.kit)
-- what a drawing listens to is let go of when the drawing is gone
local function life(root)
  local links, jobsOf = {}, {}
  local api = {}
  local function cleanup()
    for _, job in ipairs(jobsOf) do job.cancel() end
    for _, link in ipairs(links) do link.disconnect() end
    table.clear(links)
  end
  function api.signal(signal, fn) links[#links + 1] = signal:connect(function(...) if root.Parent then fn(...) end end) end
  function api.config(id, fn) local off = Config.on(id, function(...) if root.Parent then fn(...) end end); links[#links + 1] = { disconnect = off } end
  function api.every(fn, hz, scope)
    local job
    job = Motion.every(function(dt)
      if not root.Parent then cleanup(); return end
      fn(dt)
    end, hz, scope)
    jobsOf[#jobsOf + 1] = job
  end
  api.every(function() end, 0.5, "music.life")
  return api
end
Music.life = life
local function frame(parent, props)
  local f = Instance.new("Frame")
  f.BorderSizePixel, f.BackgroundTransparency = 0, 1
  for key, value in pairs(props or {}) do f[key] = value end
  f.Parent = parent
  return f
end
local function round(f, radius)
  local c = Instance.new("UICorner")
  c.CornerRadius = radius == true and UDim.new(1, 0) or UDim.new(0, radius)
  c.Parent = f
  return c
end
-- Glass (the BASED look, 2026-11-02): a pane of frosted glass. A faint fill of the look's ink, lightest at its top, and
-- a rim of light brightest at the upper left and lower right, the way light catches a pane's edges. `strength` 1 is
-- the player's deck; buttons and rows take less. Only in the BASED look: Unnamed and Novoline keep their own.
local function glass(target, kit, strength, radius)
  strength = strength or 1
  kit.paint(target, "BackgroundColor3", "text")
  target.BackgroundTransparency = 1 - 0.065 * strength
  if radius then round(target, radius) end
  local shade = target:FindFirstChild("GlassShade") or Instance.new("UIGradient")
  shade.Name = "GlassShade"
  shade.Rotation = 90
  shade.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(0.55, 0.45), NumberSequenceKeypoint.new(1, 0.7) })
  shade.Parent = target
  local rim = target:FindFirstChild("GlassRim") or Instance.new("UIStroke")
  rim.Name = "GlassRim"
  rim.Thickness = 1
  rim.Transparency = 1 - 0.32 * math.min(strength, 1.4)
  rim.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
  kit.paint(rim, "Color", "text")
  rim.Parent = target
  local catch = rim:FindFirstChild("GlassCatch") or Instance.new("UIGradient")
  catch.Name = "GlassCatch"
  catch.Rotation = 38
  catch.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(0.3, 0.7), NumberSequenceKeypoint.new(0.7, 0.85),
    NumberSequenceKeypoint.new(1, 0.25) })
  catch.Parent = rim
  return target
end
Music.glass = glass
-- a band of light that crosses a pane now and then (the deck while it plays): a reflection, not a flash
local function sheen(parent, z)
  local band = frame(parent, { Name = "Sheen", Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0, ZIndex = z or 1 })
  local light = Instance.new("UIGradient")
  light.Rotation = 24
  light.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.42, 1), NumberSequenceKeypoint.new(0.5, 0.9),
    NumberSequenceKeypoint.new(0.58, 1), NumberSequenceKeypoint.new(1, 1) })
  light.Offset = Vector2.new(-1, 0)
  light.Parent = band
  return band, light
end
local function hitbox(parent, props)
  local button = Instance.new("TextButton")
  button.Text, button.AutoButtonColor, button.BackgroundTransparency, button.BorderSizePixel = "", false, 1, 0
  button.Size = UDim2.fromScale(1, 1)
  button.ZIndex = 8
  for key, value in pairs(props or {}) do button[key] = value end
  button.Parent = parent
  return button
end
local function icon(parent, name, size, kit, role, props)
  local image = Instance.new("ImageLabel")
  image.BackgroundTransparency, image.BorderSizePixel = 1, 0
  image.Size = UDim2.fromOffset(size, size)
  image.ScaleType = Enum.ScaleType.Fit
  UI.setIcon(image, name)
  kit.paint(image, "ImageColor3", role or "text")
  for key, value in pairs(props or {}) do image[key] = value end
  image.Parent = parent
  return image
end
-- a round button: an icon on a tinted disc (or the accent, for the main one)
local function circle(parent, name, size, kit, run, main, tip, glassy)
  local disc = frame(parent, { Size = UDim2.fromOffset(size, size), Name = name })
  local filled = main == true
  -- (glass: the player's own buttons in the BASED look, each a little disc of it)
  glassy = glassy == true and kit.look == "based"
  if kit.look ~= "unnamed" then round(disc, true) end
  local function rest()
    if filled then kit.fill(disc, "accent")
    elseif glassy then glass(disc, kit, 0.75)
    else kit.clear(disc) end
  end
  rest()
  if kit.look == "unnamed" and filled then kit.outline(disc) end
  if glassy and filled then
    -- the main one: the accent, lit from above, and glowing under itself
    local gloss = Instance.new("UIGradient")
    gloss.Rotation = 90
    gloss.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(205, 205, 205))
    gloss.Parent = disc
    pcall(function()
      local glow = Instance.new("UIShadow")
      glow.BlurRadius, glow.Offset, glow.Transparency = UDim.new(0, 16), UDim2.fromOffset(0, 4), 0.55
      kit.paint(glow, "Color", "accent")
      glow.Parent = disc
    end)
  end
  local inner = math.floor(size * (filled and 0.46 or 0.5))
  local glyph = icon(disc, name, inner, kit, filled and "onAccent" or "text", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
  local hit = hitbox(disc)
  hit.MouseEnter:Connect(function()
    if filled then disc.BackgroundTransparency = 0.12
    elseif glassy then glass(disc, kit, 1.5)
    else kit.fill(disc, "hover") end
  end)
  hit.MouseLeave:Connect(rest)
  hit.Activated:Connect(B.safe("music.button", function()
    UI.sfx("click", 0.45)
    if not Motion.reduced then
      glyph.Size = UDim2.fromOffset(math.floor(inner * 0.78), math.floor(inner * 0.78))
      Motion.to(glyph, "Size", UDim2.fromOffset(inner, inner), "bouncy")
    end
    run()
  end))
  if tip and kit.look == "based" then UI.tooltip(hit, tip) end
  return disc, glyph
end
Music.circle = circle
local function cover(parent, kit, size, props)
  local image = Instance.new("ImageLabel")
  image.Name = "Cover"
  image.BorderSizePixel = 0
  image.Size = UDim2.fromOffset(size, size)
  image.ScaleType = Enum.ScaleType.Crop
  kit.fill(image, "field")
  for key, value in pairs(props or {}) do image[key] = value end
  if kit.look == "unnamed" then kit.outline(image) else round(image, math.max(6, math.floor(size * 0.12))) end
  image.Parent = parent
  local placeholder = icon(image, "music", math.floor(size * 0.38), kit, "faint", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
    ZIndex = image.ZIndex })
  image:GetPropertyChangedSignal("Image"):Connect(function() placeholder.Visible = image.Image == "" end)
  return image
end
Music.coverImage = cover
-- A line that slides when it is longer than its box (a long song name): it waits, glides to its
-- end, waits, glides back. A short one sits still. Moved by Position.X.Scale (a share of the box),
-- so the look's scale never throws it off.
local function marquee(parent, kit, props, bold, size)
  local holder = frame(parent, props)
  holder.ClipsDescendants = true
  local label = kit.text(holder, "", { Size = UDim2.new(0, 0, 1, 0), AutomaticSize = Enum.AutomaticSize.X, TextTruncate = Enum.TextTruncate.None,
    ZIndex = holder.ZIndex }, bold, size)
  local api = { holder = holder, label = label, t = 0 }
  function api.set(value)
    value = tostring(value or "")
    if label.Text ~= value then
      label.Text = value
      api.t = 0
      label.Position = UDim2.new()
    end
  end
  function api.step(dt)
    local width = holder.AbsoluteSize.X
    local over = label.AbsoluteSize.X - width
    if over <= 1 or width <= 0 then
      if label.Position.X.Scale ~= 0 then label.Position = UDim2.new() end
      api.t = 0
      return
    end
    local glide, back, rest = over / 38, over / 90, 1.6
    local cycle = rest * 2 + glide + back
    api.t = (api.t + dt) % cycle
    local t, p = api.t, 0
    if t < rest then p = 0
    elseif t < rest + glide then p = (t - rest) / glide
    elseif t < rest * 2 + glide then p = 1
    else p = 1 - (t - rest * 2 - glide) / back end
    p = p * p * (3 - 2 * p)
    label.Position = UDim2.new(-(over / width) * p, 0, 0, 0)
  end
  return api
end
Music.marquee = marquee

-- the cover's colour, for the tint behind the player (46_cover.lua reads it)
local tintOf = {}
function Music.tint(track, done)
  if not track or not track.art or Config.get("music.tint") == false then done(nil); return end
  if tintOf[track.key] ~= nil then done(tintOf[track.key] or nil); return end
  local probe = Instance.new("ImageLabel")
  Music.cover(track, probe, function(path)
    probe:Destroy()
    -- (read off the thread that asked: it takes a few frames)
    task.spawn(function()
      local color = path and B.Cover and B.Cover.color(path) or nil
      B.identity()
      tintOf[track.key] = color or false
      B.try("music.tint", done, color)
    end)
  end)
end

-- The player: the cover (a record slides out of it while it plays), the names, the bars, the line, the buttons.
function Music.viewPlayer(holder, shown)
  local kit = Window.kit(holder)
  local L = life(holder)
  shown = shown or function() return Window.showing("music") end
  local square = kit.look == "unnamed"
  local coverSize = square and 112 or 148
  local deckFrame = frame(holder, { Name = "Deck", Size = UDim2.fromScale(1, 1), ClipsDescendants = true })
  -- (the BASED look: the deck is a pane of glass, with a reflection crossing it now and then while it plays)
  local glassy = kit.look == "based"
  local sheenBand, sheenLight
  if glassy then
    glass(deckFrame, kit, 1, kit.radius)
    sheenBand, sheenLight = sheen(deckFrame, 1)
    round(sheenBand, kit.radius)
  end
  -- the tint: the cover's colour, strongest on the left
  local tint = frame(deckFrame, { Name = "Tint", Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 1, ZIndex = 0 })
  if not square then round(tint, kit.radius) end
  local shade = Instance.new("UIGradient")
  shade.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.45), NumberSequenceKeypoint.new(0.55, 0.82), NumberSequenceKeypoint.new(1, 1) })
  shade.Parent = tint
  local pad = square and 6 or 14
  -- the record
  local disc, label, sheen
  if not square then
    disc = frame(deckFrame, { Name = "Record", Size = UDim2.fromOffset(coverSize - 12, coverSize - 12), AnchorPoint = Vector2.new(0.5, 0.5),
      Position = UDim2.fromOffset(pad + coverSize / 2, pad + coverSize / 2), BackgroundColor3 = Color3.fromRGB(14, 14, 16), BackgroundTransparency = 0, ZIndex = 2 })
    round(disc, true)
    for _, s in ipairs({ 0.92, 0.8, 0.68, 0.56 }) do
      local groove = frame(disc, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(s, s), ZIndex = 2 })
      round(groove, true)
      local line = Instance.new("UIStroke")
      line.Color, line.Transparency, line.Thickness = Color3.fromRGB(46, 46, 52), 0.35, 1
      line.Parent = groove
    end
    label = Instance.new("ImageLabel")
    label.Name = "Label"
    label.BorderSizePixel, label.AnchorPoint, label.Position, label.Size = 0, Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5), UDim2.fromScale(0.4, 0.4)
    label.ScaleType, label.ZIndex = Enum.ScaleType.Crop, 3
    kit.fill(label, "accent")
    round(label, true)
    label.Parent = disc
    local hole = frame(label, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(6, 6),
      BackgroundColor3 = Color3.fromRGB(10, 10, 12), BackgroundTransparency = 0, ZIndex = 4 })
    round(hole, true)
    sheen = frame(deckFrame, { AnchorPoint = Vector2.new(0.5, 0.5), Size = disc.Size, Position = disc.Position, BackgroundColor3 = Color3.new(1, 1, 1),
      BackgroundTransparency = 0.86, ZIndex = 3 })
    round(sheen, true)
    local light = Instance.new("UIGradient")
    light.Rotation = 35
    light.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.45, 0.55), NumberSequenceKeypoint.new(0.5, 0.2),
      NumberSequenceKeypoint.new(0.55, 0.55), NumberSequenceKeypoint.new(1, 1) })
    light.Parent = sheen
  end
  local art = cover(deckFrame, kit, coverSize, { Position = UDim2.fromOffset(pad, pad), ZIndex = 5 })
  if glassy then
    -- the cover under glass: light across its top half
    local gloss = frame(art, { Name = "Gloss", Size = UDim2.fromScale(1, 0.55), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0, ZIndex = 6 })
    round(gloss, math.max(6, math.floor(coverSize * 0.12)))
    local fall = Instance.new("UIGradient")
    fall.Rotation = 90
    fall.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.8), NumberSequenceKeypoint.new(1, 1) })
    fall.Parent = gloss
  end
  local right = pad + coverSize + (square and 14 or 64)
  local area = frame(deckFrame, { Name = "Side", Position = UDim2.fromOffset(right, pad), Size = UDim2.new(1, -(right + pad), 1, -pad * 2), ZIndex = 5 })
  local big = kit.size + (square and 3 or 6)
  local title = marquee(area, kit, { Size = UDim2.new(1, -44, 0, big + 6), ZIndex = 5 }, true, big)
  title.set("Nothing playing")
  local artist = kit.text(area, "Search below, or play your own files.", { Position = UDim2.fromOffset(0, big + 6), Size = UDim2.new(1, -44, 0, kit.size + 4),
    TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 5 }, false, kit.size)
  kit.paint(artist, "TextColor3", "dim")
  local badge = frame(area, { Position = UDim2.fromOffset(0, big + kit.size + 14), Size = UDim2.fromOffset(0, 16), AutomaticSize = Enum.AutomaticSize.X, ZIndex = 5, Visible = false })
  kit.fill(badge, "field")
  if not square then round(badge, true) end
  local badgeText = kit.text(badge, "", { Size = UDim2.fromOffset(0, 16), AutomaticSize = Enum.AutomaticSize.X, ZIndex = 6 }, true, kit.size - 3)
  kit.paint(badgeText, "TextColor3", "accent")
  local badgePad = Instance.new("UIPadding")
  badgePad.PaddingLeft, badgePad.PaddingRight = UDim.new(0, 8), UDim.new(0, 8)
  badgePad.Parent = badge
  local status = kit.text(area, "", { Position = UDim2.fromOffset(0, big + kit.size + 14), Size = UDim2.new(1, -120, 0, 16), ZIndex = 5 }, false, kit.size - 1)
  kit.paint(status, "TextColor3", "accent")
  local _, heart = circle(area, "heart", 32, kit, function() local track = Music.front().track(); if track then Music.like(track, not Music.liked(track)) end end, false, "Like", true)
  heart.Parent.AnchorPoint, heart.Parent.Position = Vector2.new(1, 0), UDim2.new(1, 0, 0, 0)
  -- the bars: how loud it is, spread over a made-up spectrum that moves with it
  local barsY = big + kit.size + 36
  local bars = frame(area, { Name = "Bars", Position = UDim2.fromOffset(0, barsY), Size = UDim2.new(1, 0, 0, square and 18 or 26), ZIndex = 5 })
  local barList, barLevel = {}, {}
  local COUNT = square and 32 or 40
  for i = 1, COUNT do
    local bar = frame(bars, { AnchorPoint = Vector2.new(0, 1), Position = UDim2.new((i - 1) / COUNT, 1, 1, 0), Size = UDim2.new(1 / COUNT, -2, 0, 2), ZIndex = 5 })
    kit.fill(bar, "accent")
    if not square then round(bar, 1) end
    barList[i], barLevel[i] = bar, 0
  end
  -- the line: drag or click it
  local lineY = barsY + (square and 24 or 34)
  local rail = frame(area, { Name = "Rail", Position = UDim2.fromOffset(0, lineY), Size = UDim2.new(1, 0, 0, square and 6 or 4), ZIndex = 5 })
  if glassy then glass(rail, kit, 1.6) else kit.fill(rail, "field") end
  if square then kit.outline(rail) else round(rail, true) end
  local fill = frame(rail, { Size = UDim2.fromScale(0, 1), ZIndex = 6 })
  kit.fill(fill, "accent")
  if not square then round(fill, true) end
  local knob = frame(rail, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0, 0.5), Size = UDim2.fromOffset(square and 4 or 12, square and 10 or 12),
    BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0, ZIndex = 7 })
  if not square then round(knob, true) end
  local at = kit.text(area, "0:00", { Position = UDim2.fromOffset(0, lineY + 8), Size = UDim2.fromOffset(60, 14), ZIndex = 5 }, false, kit.size - 2)
  kit.paint(at, "TextColor3", "faint")
  local length = kit.text(area, "0:00", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, lineY + 8), Size = UDim2.fromOffset(60, 14), ZIndex = 5,
    TextXAlignment = Enum.TextXAlignment.Right }, false, kit.size - 2)
  kit.paint(length, "TextColor3", "faint")
  local dragging = nil
  local seekHit = hitbox(rail, { Size = UDim2.new(1, 0, 0, 20), Position = UDim2.new(0, 0, 0.5, -10), ZIndex = 9 })
  local function fractionAt(point) return math.clamp((point.X - rail.AbsolutePosition.X) / math.max(rail.AbsoluteSize.X, 1), 0, 1) end
  UI.drag(seekHit, function(point) dragging = fractionAt(point) end, function(point) dragging = fractionAt(point) end, function()
    if dragging then Music.front().seek(dragging) end
    dragging = nil
  end)
  -- the buttons
  local row = frame(area, { Name = "Buttons", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, lineY + (square and 22 or 26)),
    Size = UDim2.fromOffset(0, 44), AutomaticSize = Enum.AutomaticSize.X, ZIndex = 5 })
  local layout = Instance.new("UIListLayout")
  layout.FillDirection, layout.Padding, layout.VerticalAlignment, layout.SortOrder = Enum.FillDirection.Horizontal, UDim.new(0, square and 6 or 12),
    Enum.VerticalAlignment.Center, Enum.SortOrder.LayoutOrder
  layout.Parent = row
  local shuffle, shuffleIcon = circle(row, "shuffle", 30, kit, function() local ctl = Music.front(); ctl.setShuffle(not ctl.shuffle()) end, false, "Shuffle", true)
  shuffle.LayoutOrder = 1
  local back = circle(row, "skip-back", 34, kit, function() Music.front().previous() end, false, "Back", true)
  back.LayoutOrder = 2
  local play, playIcon = circle(row, "play", square and 34 or 44, kit, function() Music.front().toggle() end, true, nil, true)
  play.LayoutOrder = 3
  local forward = circle(row, "skip-forward", 34, kit, function() Music.front().next() end, false, "Next", true)
  forward.LayoutOrder = 4
  local loop, loopIcon = circle(row, "repeat", 30, kit, function()
    local ctl = Music.front()
    local now = ctl.repeatMode()
    ctl.setRepeat(now == "off" and "all" or (now == "all" and "one" or "off"))
  end, false, "Repeat", true)
  loop.LayoutOrder = 5
  local coverKey
  local function paint()
    local ctl = Music.front()
    local track = ctl.track()
    title.set(track and track.title or "Nothing playing")
    artist.Text = track and (track.artist .. (track.preview and "  ·  30 s preview" or "")) or "Search below, or play your own files."
    local busy = ctl.status()
    status.Text = busy or ""
    status.Visible = busy ~= nil
    badge.Visible = track ~= nil and busy == nil
    badgeText.Text = string.upper(track and ctl.label(track) or "")
    local key = track and track.key or nil
    if key ~= coverKey then
      coverKey = key
      if track then
        ctl.cover(track, art)
        if label then ctl.cover(track, label) end
        ctl.tint(track, function(color)
          if not tint.Parent or coverKey ~= key then return end
          if color then
            tint.BackgroundColor3 = color
            Motion.to(tint, "BackgroundTransparency", 0, "smooth")
          else
            Motion.to(tint, "BackgroundTransparency", 1, "smooth")
          end
        end)
      else
        art.Image = ""
        if label then label.Image = "" end
        tint.BackgroundTransparency = 1
      end
    end
    UI.setIcon(playIcon, ctl.state() == "playing" and "pause" or "play")
    kit.paint(heart, "ImageColor3", (track and Music.liked(track)) and "accent" or "text")
    kit.paint(shuffleIcon, "ImageColor3", ctl.shuffle() and "accent" or "text")
    local mode = ctl.repeatMode()
    UI.setIcon(loopIcon, mode == "one" and "repeat-1" or "repeat")
    kit.paint(loopIcon, "ImageColor3", mode ~= "off" and "accent" or "text")
  end
  L.signal(Music.changed, paint)
  L.config("music.shuffle", paint)
  L.config("music.repeat", paint)
  L.config("music.liked", paint)
  paint()
  local spin, out = 0, 0
  local level, peak = 0, 4
  local paintedFor
  L.every(function(dt)
    if not shown() then return end
    title.step(dt)
    local ctl = Music.front()
    -- (what is in front changed, or its state: drawn again)
    local current = ctl.track()
    local stamp = (current and current.key or "") .. ctl.state() .. ctl.kind
    if stamp ~= paintedFor then paintedFor = stamp; paint() end
    local position, total = ctl.position(), ctl.length()
    local f = dragging or (total > 0 and math.clamp(position / total, 0, 1) or 0)
    fill.Size = UDim2.fromScale(f, 1)
    knob.Position = UDim2.fromScale(f, 0.5)
    at.Text = Music.time(dragging and dragging * total or position)
    length.Text = Music.time(total)
    -- the record: out of its sleeve and turning while it plays (33 turns a minute)
    local playing = ctl.state() == "playing"
    if disc then
      out += ((playing and 1 or 0) - out) * math.min(dt * 6, 1)
      if playing then spin = (spin + dt * 198) % 360 end
      local x = pad + coverSize / 2 + out * 50
      disc.Position = UDim2.fromOffset(x, pad + coverSize / 2)
      sheen.Position = disc.Position
      disc.Rotation = spin
    end
    -- the bars: against the loudest lately, so they move at any volume
    local raw = playing and ctl.loudness() or 0
    peak = math.max(peak * (1 - math.min(dt * 0.35, 1)), raw, 4)
    local loud = playing and math.clamp(raw / peak * 1.05, 0, 1.15) or 0
    level += (loud - level) * math.min(dt * 14, 1)
    local now = os.clock()
    for i = 1, COUNT do
      local x = (i - 1) / (COUNT - 1)
      local shape = 0.55 + 0.45 * math.sin(now * (2.1 + x * 3.3) + i * 1.7) * math.cos(now * 1.3 + i * 0.6)
      local tilt = 1 - x * 0.55
      local want = level * tilt * (0.35 + 0.65 * math.abs(shape))
      barLevel[i] += (want - barLevel[i]) * math.min(dt * 18, 1)
      barList[i].Size = UDim2.new(1 / COUNT, -2, math.clamp(barLevel[i], 0.06, 1), 0)
    end
    bars.Visible = Config.get("music.visual") ~= "off"
    if sheenLight then
      local cycle = (os.clock() % 7) / 1.4
      sheenBand.Visible = playing and cycle < 1 and not Motion.reduced
      if sheenBand.Visible then sheenLight.Offset = Vector2.new(-1 + 2 * cycle, 0) end
    end
  end, 60, "music.player")
end

-- The small player (Novoline's Home card, tight places): the cover, the names, the line, the buttons.
function Music.viewCompact(holder, shown)
  local kit = Window.kit(holder)
  local L = life(holder)
  shown = shown or function() return true end
  local square = kit.look == "unnamed"
  local art = cover(holder, kit, 84, { Position = UDim2.fromOffset(12, 6), ZIndex = 5 })
  local x = 110
  local title = marquee(holder, kit, { Position = UDim2.fromOffset(x, 10), Size = UDim2.new(1, -(x + 12), 0, kit.size + 6), ZIndex = 5 }, true, kit.size + 1)
  local artist = kit.text(holder, "", { Position = UDim2.fromOffset(x, kit.size + 18), Size = UDim2.new(1, -(x + 12), 0, kit.size + 2), ZIndex = 5,
    TextTruncate = Enum.TextTruncate.AtEnd }, false, kit.size - 1)
  kit.paint(artist, "TextColor3", "dim")
  local status = kit.text(holder, "", { Position = UDim2.fromOffset(x, kit.size * 2 + 22), Size = UDim2.new(1, -(x + 12), 0, kit.size), ZIndex = 5,
    TextTruncate = Enum.TextTruncate.AtEnd }, false, kit.size - 3)
  kit.paint(status, "TextColor3", "accent")
  local rail = frame(holder, { Position = UDim2.fromOffset(12, 104), Size = UDim2.new(1, -24, 0, 3), ZIndex = 5 })
  kit.fill(rail, "field")
  if not square then round(rail, true) end
  local fill = frame(rail, { Size = UDim2.fromScale(0, 1), ZIndex = 6 })
  kit.fill(fill, "accent")
  if not square then round(fill, true) end
  local at = kit.text(holder, "0:00", { Position = UDim2.fromOffset(12, 110), Size = UDim2.fromOffset(50, 12), ZIndex = 5 }, false, kit.size - 4)
  kit.paint(at, "TextColor3", "faint")
  local long = kit.text(holder, "0:00", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -12, 0, 110), Size = UDim2.fromOffset(50, 12), ZIndex = 5,
    TextXAlignment = Enum.TextXAlignment.Right }, false, kit.size - 4)
  kit.paint(long, "TextColor3", "faint")
  local seekHit = hitbox(rail, { Size = UDim2.new(1, 0, 0, 16), Position = UDim2.new(0, 0, 0.5, -8), ZIndex = 9 })
  UI.drag(seekHit, function(point) Music.front().seek(math.clamp((point.X - rail.AbsolutePosition.X) / math.max(rail.AbsoluteSize.X, 1), 0, 1)) end)
  local row = frame(holder, { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 126), Size = UDim2.fromOffset(0, 36), AutomaticSize = Enum.AutomaticSize.X, ZIndex = 5 })
  local layout = Instance.new("UIListLayout")
  layout.FillDirection, layout.Padding, layout.VerticalAlignment, layout.SortOrder = Enum.FillDirection.Horizontal, UDim.new(0, 12), Enum.VerticalAlignment.Center, Enum.SortOrder.LayoutOrder
  layout.Parent = row
  local _, heart = circle(row, "heart", 28, kit, function() local track = Music.front().track(); if track then Music.like(track, not Music.liked(track)) end end)
  heart.Parent.LayoutOrder = 1
  local back = circle(row, "skip-back", 30, kit, function() Music.front().previous() end)
  back.LayoutOrder = 2
  local play, playIcon = circle(row, "play", 36, kit, function() Music.front().toggle() end, true)
  play.LayoutOrder = 3
  local forward = circle(row, "skip-forward", 30, kit, function() Music.front().next() end)
  forward.LayoutOrder = 4
  local _, shuffleIcon = circle(row, "shuffle", 28, kit, function() local ctl = Music.front(); ctl.setShuffle(not ctl.shuffle()) end)
  shuffleIcon.Parent.LayoutOrder = 5
  local coverKey
  local function paint()
    local ctl = Music.front()
    local track = ctl.track()
    title.set(track and track.title or "Nothing playing")
    artist.Text = track and track.artist or "Pick a song in the Music tab"
    status.Text = ctl.status() or (track and string.upper(ctl.label(track)) or "")
    local key = track and track.key or nil
    if key ~= coverKey then
      coverKey = key
      if track then ctl.cover(track, art) else art.Image = "" end
    end
    UI.setIcon(playIcon, ctl.state() == "playing" and "pause" or "play")
    kit.paint(heart, "ImageColor3", (track and Music.liked(track)) and "accent" or "text")
    kit.paint(shuffleIcon, "ImageColor3", ctl.shuffle() and "accent" or "text")
  end
  L.signal(Music.changed, paint)
  L.config("music.liked", paint)
  L.config("music.shuffle", paint)
  paint()
  local paintedFor
  L.every(function(dt)
    if not shown() then return end
    title.step(dt)
    local ctl = Music.front()
    local current = ctl.track()
    local stamp = (current and current.key or "") .. ctl.state() .. ctl.kind
    if stamp ~= paintedFor then paintedFor = stamp; paint() end
    local position, total = ctl.position(), ctl.length()
    fill.Size = UDim2.fromScale(total > 0 and math.clamp(position / total, 0, 1) or 0, 1)
    at.Text = Music.time(position)
    long.Text = Music.time(total)
  end, 30, "music.compact")
end

-- One line of a track list: cover, names, length, buttons.
local function trackRow(list, track, order, kit, actions)
  local square = kit.look == "unnamed"
  local height = square and 36 or 48
  local row = frame(list, { Name = "Track", Size = UDim2.new(1, -4, 0, height), LayoutOrder = order })
  if not square then round(row, 10) end
  local art = cover(row, kit, height - 10, { Position = UDim2.fromOffset(5, 5), ZIndex = 2 })
  Music.cover(track, art)
  local playing = Music.now and Music.now.key == track.key
  local x = height + 4
  local name = kit.text(row, track.title, { Position = UDim2.fromOffset(x, square and 2 or 6), Size = UDim2.new(1, -(x + 40 + #actions * 30), 0, kit.size + 5),
    TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 2 }, true, kit.size)
  kit.paint(name, "TextColor3", playing and "accent" or "text")
  local bits = { track.artist }
  local plays = Music.plays(track.plays)
  if plays then bits[#bits + 1] = plays end
  if track.preview then bits[#bits + 1] = "30 s preview" end
  if track.playable == false then bits[#bits + 1] = "can't play" end
  local sub = kit.text(row, table.concat(bits, "  ·  "), { Position = UDim2.fromOffset(x, (square and 2 or 6) + kit.size + 5),
    Size = UDim2.new(1, -(x + 40 + #actions * 30), 0, kit.size + 2), TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 2 }, false, kit.size - 2)
  kit.paint(sub, "TextColor3", "dim")
  local long = kit.text(row, (track.duration and track.duration > 0) and Music.time(track.duration) or "", { AnchorPoint = Vector2.new(1, 0.5),
    Position = UDim2.new(1, -(8 + #actions * 30), 0.5, 0), Size = UDim2.fromOffset(40, 14), TextXAlignment = Enum.TextXAlignment.Right, ZIndex = 2 }, false, kit.size - 2)
  kit.paint(long, "TextColor3", "faint")
  local hit = hitbox(row, { Name = "Play", Size = UDim2.new(1, -(6 + #actions * 30), 1, 0), ZIndex = 3 })
  hit.MouseEnter:Connect(function() if kit.look == "based" then glass(row, kit, 1.3) else kit.fill(row, "hover") end end)
  hit.MouseLeave:Connect(function()
    kit.clear(row)
    local rim = row:FindFirstChild("GlassRim")
    if rim then rim.Transparency = 1 end
  end)
  row:SetAttribute("Key", track.key)
  if not actions.ownClick then
    hit.Activated:Connect(B.safe("music.row", function()
      if track.playable == false then return end
      UI.sfx("click", 0.4)
      Music.play(track)
    end))
  end
  for i, action in ipairs(actions) do
    local button, glyph = circle(row, action[1], 26, kit, function() action[2](track, row) end, false)
    button.AnchorPoint, button.Position = Vector2.new(1, 0.5), UDim2.new(1, -4 - (#actions - i) * 30, 0.5, 0)
    button.ZIndex = 4
    kit.paint(glyph, "ImageColor3", (action[3] and action[3](track)) and "accent" or "dim")
  end
  return row, hit
end
Music.trackRow = trackRow
-- a list that scrolls, drawn again by `fill(list, kit)` when asked
local function listBox(holder, top, fill)
  local kit = Window.kit(holder)
  local area = frame(holder, { Name = "List", Position = UDim2.fromOffset(0, top), Size = UDim2.new(1, 0, 1, -top), ClipsDescendants = true })
  -- (the BASED look: every list on a pane of frosted glass)
  if kit.look == "based" then glass(area, kit, 0.55, 12) end
  local scroller = Instance.new("ScrollingFrame")
  scroller.BackgroundTransparency, scroller.BorderSizePixel = 1, 0
  scroller.Size = UDim2.fromScale(1, 1)
  scroller.AutomaticCanvasSize, scroller.CanvasSize = Enum.AutomaticSize.Y, UDim2.new()
  scroller.ScrollBarThickness = 3
  kit.paint(scroller, "ScrollBarImageColor3", "accent")
  scroller.ScrollingDirection = Enum.ScrollingDirection.Y
  scroller.Parent = area
  local layout = Instance.new("UIListLayout"); layout.Padding = UDim.new(0, 2); layout.SortOrder = Enum.SortOrder.LayoutOrder; layout.Parent = scroller
  local function redraw()
    if not area.Parent then return end
    for _, child in ipairs(scroller:GetChildren()) do if child:IsA("GuiObject") then child:Destroy() end end
    B.try("music.list", fill, scroller, kit)
  end
  redraw()
  return scroller, redraw
end
local function empty(list, kit, text)
  local label = kit.text(list, text, { Size = UDim2.new(1, -16, 0, 40), TextWrapped = true, TextTruncate = Enum.TextTruncate.None }, false, kit.size - 1)
  kit.paint(label, "TextColor3", "dim")
  local padding = Instance.new("UIPadding"); padding.PaddingLeft = UDim.new(0, 8); padding.Parent = label
  return label
end
-- the menu of playlists a song can go in
local function addMenu(track, anchor, kit)
  local items = {}
  for _, item in ipairs(Music.playlists()) do
    items[#items + 1] = { label = item.name, icon = "list-music", run = function()
      Music.addTo(item.name, track)
      Window.toast({ title = "Added to " .. item.name, text = track.title, icon = "list-plus", time = 1.8 })
    end }
  end
  items[#items + 1] = { label = "Play next", icon = "skip-forward", run = function() Music.enqueue(track, true) end }
  items[#items + 1] = { label = "Add to the queue", icon = "list-plus", run = function()
    Music.enqueue(track)
    Window.toast({ title = "Queued", text = track.title, icon = "list-plus", time = 1.6 })
  end }
  if #Music.playlists() == 0 then items[#items + 1] = { label = "Make a playlist in Playlists", icon = "info", run = function() end } end
  kit.menu(anchor, items)
end
local function songActions()
  return {
    { "heart", function(t) Music.like(t, not Music.liked(t)) end, function(t) return Music.liked(t) end },
    { "list-plus", function(t, row) addMenu(t, row, Window.kit(row)) end },
  }
end

-- search: the source, the box, what it found
local SOURCES = { { "sc", "SoundCloud" }, { "au", "Audius" }, { "files", "Your files" }, { "link", "Link / id" } }
function Music.viewSearch(holder)
  local kit = Window.kit(holder)
  local L = life(holder)
  local square = kit.look == "unnamed"
  local tabs = frame(holder, { Name = "Sources", Size = UDim2.new(1, 0, 0, 30) })
  local tabLayout = Instance.new("UIListLayout")
  tabLayout.FillDirection, tabLayout.Padding, tabLayout.SortOrder = Enum.FillDirection.Horizontal, UDim.new(0, 6), Enum.SortOrder.LayoutOrder
  tabLayout.Parent = tabs
  local chips = {}
  for i, source in ipairs(SOURCES) do
    local chip = frame(tabs, { Size = UDim2.new(0.25, -5, 1, 0), LayoutOrder = i })
    if square then kit.outline(chip) else round(chip, true) end
    local label = kit.text(chip, source[2], { Name = "Source", Size = UDim2.fromScale(1, 1), TextXAlignment = Enum.TextXAlignment.Center }, true, kit.size - 1)
    chips[source[1]] = { chip = chip, label = label }
    hitbox(chip).Activated:Connect(B.safe("music.source", function() UI.sfx("tab", 0.4); Config.set("music.source", source[1]) end))
  end
  local field = frame(holder, { Name = "Field", Position = UDim2.fromOffset(0, 38), Size = UDim2.new(1, 0, 0, 34) })
  if kit.look == "based" then glass(field, kit, 1.4) else kit.fill(field, "field") end
  if square then kit.outline(field) else round(field, 10) end
  icon(field, "search", 16, kit, "faint", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 10, 0.5, 0) })
  local box = kit.entry(field, kit.size)
  box.Size, box.Position = UDim2.new(1, -110, 1, 0), UDim2.fromOffset(34, 0)
  box.Text = ""
  local go = frame(field, { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -4, 0.5, 0), Size = UDim2.fromOffset(68, 26) })
  kit.fill(go, "accent")
  if square then kit.outline(go) else round(go, true) end
  -- (named: words on the accent are the accent's own ink, light or dark scheme)
  local goText = kit.text(go, "Search", { Name = "OnAccent", Size = UDim2.fromScale(1, 1), TextXAlignment = Enum.TextXAlignment.Center }, true, kit.size - 1)
  kit.paint(goText, "TextColor3", "onAccent")
  local note = kit.text(holder, "", { Position = UDim2.fromOffset(2, 78), Size = UDim2.new(1, -4, 0, 16) }, false, kit.size - 1)
  kit.paint(note, "TextColor3", "dim")
  local _, redraw = listBox(holder, 98, function(list, k)
    local source = Config.get("music.source")
    if source == "link" then
      empty(list, k, "Paste a direct audio link (.mp3 .ogg .wav) or a Roblox audio id above, then press Enter.")
      return
    end
    if Music.resultsFor ~= source or #Music.results == 0 then
      empty(list, k, source == "files" and "Put .mp3, .ogg or .wav files in workspace/BasedHub/music, then press Enter."
        or (source == "au" and "Press Enter for what is trending on Audius, or type to search." or "Type an artist or a song, then press Enter."))
      return
    end
    for i, track in ipairs(Music.results) do trackRow(list, track, i, k, songActions()) end
  end)
  local function paintSource()
    local source = Config.get("music.source")
    for key, chip in pairs(chips) do
      local on = key == source
      kit.fill(chip.chip, on and "accent" or "field")
      kit.paint(chip.label, "TextColor3", on and "onAccent" or "dim")
    end
    box.PlaceholderText = source == "link" and "A link or an audio id" or (source == "files" and "Press Enter to list your files"
      or (source == "au" and "Search Audius (Enter alone: trending)" or "Search SoundCloud"))
    goText.Text = source == "link" and "Play" or (source == "files" and "List" or "Search")
    note.Text = ""
    redraw()
  end
  L.config("music.source", paintSource)
  local busy = false
  local function search()
    if busy then return end
    local source = Config.get("music.source")
    local text = box.Text
    if source == "link" then
      local track = Music.link(text)
      if not track then note.Text = "That is not a link or an audio id."; return end
      Music.play(track)
      note.Text = "Playing the link."
      return
    end
    if source == "sc" and #string.gsub(text, "%s", "") == 0 then note.Text = "Type something to look for."; return end
    busy = true
    note.Text = "Looking..."
    task.spawn(function()
      local list, why = Music.search(source, text)
      busy = false
      if not note.Parent then return end
      if list then
        note.Text = #list == 0 and "Nothing found." or (#list .. " found. Click one to play it.")
      else
        note.Text = "No results: " .. tostring(why)
      end
      redraw()
    end)
  end
  box.FocusLost:Connect(function(enter) if enter then search() end end)
  hitbox(go).Activated:Connect(B.safe("music.search", function() UI.sfx("click", 0.5); search() end))
  L.signal(Music.changed, function(what) if what == "track" or what == "liked" then redraw() end end)
  paintSource()
end
function Music.viewQueue(holder)
  local L = life(holder)
  local _, redraw = listBox(holder, 0, function(list, kit)
    if #Music.queue == 0 then empty(list, kit, "Nothing queued. Use + on a song, or play a playlist."); return end
    for i, track in ipairs(Music.queue) do
      local actions = { ownClick = true,
        { "arrow-up", function() Music.move(i, i - 1) end },
        { "x", function() Music.remove(i) end },
      }
      local row, hit = trackRow(list, track, i, kit, actions)
      hit.Activated:Connect(B.safe("music.queue.row", function()
        Music.index = i
        Music.play(track, true)
      end))
      if i == Music.index then kit.fill(row, "field") end
    end
  end)
  L.signal(Music.changed, function(what) if what == "queue" or what == "track" then redraw() end end)
end
function Music.viewLiked(holder)
  local L = life(holder)
  local _, redraw = listBox(holder, 0, function(list, kit)
    local liked = Config.get("music.liked") or {}
    if #liked == 0 then empty(list, kit, "Songs you like (the heart) are kept here."); return end
    for i, item in ipairs(liked) do
      local actions = { ownClick = true,
        { "list-plus", function(t, row) addMenu(t, row, Window.kit(row)) end },
        { "heart-off", function(t) Music.like(t, false) end },
      }
      local _, hit = trackRow(list, table.clone(item), i, kit, actions)
      hit.Activated:Connect(B.safe("music.liked.row", function() Music.playList(Config.get("music.liked") or {}, i) end))
    end
  end)
  L.config("music.liked", function() redraw() end)
  L.signal(Music.changed, function(what) if what == "track" then redraw() end end)
end
function Music.viewHistory(holder)
  local L = life(holder)
  local _, redraw = listBox(holder, 0, function(list, kit)
    local history = Config.get("music.history") or {}
    if #history == 0 then empty(list, kit, "What you play is listed here."); return end
    for i, item in ipairs(history) do
      if i > 40 then break end
      local track = table.clone(item)
      local actions = songActions()
      actions.ownClick = true
      local _, hit = trackRow(list, track, i, kit, actions)
      hit.Activated:Connect(B.safe("music.history.row", function() Music.play(track) end))
    end
  end)
  L.config("music.history", function() redraw() end)
end
-- playlists: make one, open one to see its songs, play it, delete it (twice)
function Music.viewPlaylists(holder)
  local kit = Window.kit(holder)
  local L = life(holder)
  local square = kit.look == "unnamed"
  local field = frame(holder, { Name = "New", Size = UDim2.new(1, 0, 0, 30) })
  kit.fill(field, "field")
  if square then kit.outline(field) else round(field, 9) end
  local box = kit.entry(field, kit.size)
  box.Size, box.Position = UDim2.new(1, -96, 1, 0), UDim2.fromOffset(10, 0)
  box.PlaceholderText, box.Text = "New playlist name", ""
  local make = frame(field, { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -3, 0.5, 0), Size = UDim2.fromOffset(78, 24) })
  kit.fill(make, "accent")
  if square then kit.outline(make) else round(make, true) end
  local makeText = kit.text(make, "Create", { Name = "OnAccent", Size = UDim2.fromScale(1, 1), TextXAlignment = Enum.TextXAlignment.Center }, true, kit.size - 1)
  kit.paint(makeText, "TextColor3", "onAccent")
  local opened, armed = nil, nil
  local redraw
  local _, draw = listBox(holder, 38, function(list, k)
    local lists = Music.playlists()
    if #lists == 0 then empty(list, k, "No playlists yet. Name one above, then add songs with + on any song."); return end
    local order = 0
    for _, item in ipairs(lists) do
      order += 1
      local row = frame(list, { Size = UDim2.new(1, -4, 0, square and 26 or 40), LayoutOrder = order })
      if not square then round(row, 10) end
      local open = opened == item.name
      kit.fill(row, open and "field" or "card")
      if square then kit.outline(row) end
      icon(row, "list-music", 16, k, "accent", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 10, 0.5, 0) })
      local count = #(item.tracks or {})
      k.text(row, item.name, { Position = UDim2.fromOffset(34, 0), Size = UDim2.new(1, -170, 1, 0) }, true, k.size)
      local sub = k.text(row, count .. (count == 1 and " song" or " songs"), { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -70, 0.5, 0),
        Size = UDim2.fromOffset(60, 14), TextXAlignment = Enum.TextXAlignment.Right }, false, k.size - 2)
      k.paint(sub, "TextColor3", "dim")
      local hit = hitbox(row, { Size = UDim2.new(1, -66, 1, 0), ZIndex = 3 })
      hit.Activated:Connect(B.safe("music.playlist.open", function()
        opened = (opened ~= item.name) and item.name or nil
        armed = nil
        redraw()
      end))
      local playButton = circle(row, "play", 26, k, function() Music.playList(item.tracks or {}) end, false)
      playButton.AnchorPoint, playButton.Position = Vector2.new(1, 0.5), UDim2.new(1, -36, 0.5, 0)
      local del, delIcon = circle(row, "trash-2", 26, k, function()
        if armed == item.name then
          armed = nil
          if opened == item.name then opened = nil end
          Music.deletePlaylist(item.name)
        else
          armed = item.name
          Window.toast({ title = "Click again to delete", text = item.name, icon = "trash-2", tone = "warn", time = 2 })
          task.delay(2.2, function() if armed == item.name then armed = nil; redraw() end end)
          redraw()
        end
      end, false)
      del.AnchorPoint, del.Position = Vector2.new(1, 0.5), UDim2.new(1, -6, 0.5, 0)
      k.paint(delIcon, "ImageColor3", armed == item.name and "bad" or "dim")
      if open then
        for i, t in ipairs(item.tracks or {}) do
          order += 1
          local _, songHit = trackRow(list, table.clone(t), order, k, { ownClick = true,
            { "x", function(tr) Music.removeFrom(item.name, tr.key) end },
          })
          -- (a song in a playlist plays the playlist from there)
          songHit.Activated:Connect(B.safe("music.playlist.song", function() Music.playList(item.tracks or {}, i) end))
        end
        if count == 0 then
          order += 1
          local hint = empty(list, k, "Empty: use + on any song to add it here.")
          hint.LayoutOrder = order
        end
      end
    end
  end)
  redraw = draw
  local function create()
    local made = Music.newPlaylist(box.Text)
    if made then
      box.Text = ""
      opened = made.name
      Window.toast({ title = "Playlist made", text = made.name, icon = "list-music", time = 1.6 })
      redraw()
    end
  end
  box.FocusLost:Connect(function(enter) if enter then create() end end)
  hitbox(make).Activated:Connect(B.safe("music.playlist.new", function() UI.sfx("click", 0.5); create() end))
  L.signal(Music.changed, function(what) if what == "playlists" then redraw() end end)
end

-- The words, in time: the card's scrolling lines, drawn in the look's own colours (the word being
-- sung in the cover's colour when the card has one)
function Music.viewLyrics(holder)
  local kit = Window.kit(holder)
  local L = life(holder)
  local function color(role)
    local ok, value = pcall(kit.color, role)
    return (ok and typeof(value) == "Color3") and value or Color3.new(1, 1, 1)
  end
  -- (the BASED look: the words on a pane of glass, set in from its edges)
  local host = holder
  if kit.look == "based" then
    glass(holder, kit, 0.6, kit.radius)
    host = frame(holder, { Name = "Inner", Position = UDim2.fromOffset(16, 10), Size = UDim2.new(1, -32, 1, -20) })
  end
  local list = B.Card.lyricList(host, { font = kit.font(true), size = 18, gap = 12, z = 2, dim = color("dim"), colors = function()
    local now = B.Card.wordColor(color("accent"))
    return { sung = B.Lyrics.hex(color("text")), now = B.Lyrics.hex(now), next = B.Lyrics.hex(color("faint")) }
  end })
  L.every(function(dt)
    if Window.showing("music") then list.step(dt, Music.front()) end
  end, 30, "music.lyrics")
end

-- ---------------------------------------------------------------- where you were: the queue and the song, kept for next time
local function saveSession()
  if Config.get("music.resume") == false then return end
  local queue = {}
  for i, track in ipairs(Music.queue) do
    if i > 100 then break end
    queue[#queue + 1] = Music.compact(track)
  end
  Config.set("music.session", { queue = queue, index = Music.index, at = math.floor(Music.position()) })
end
local function restoreSession()
  local session = Config.get("music.session")
  if Config.get("music.resume") == false or type(session) ~= "table" or type(session.queue) ~= "table" or #session.queue == 0 then return end
  for _, track in ipairs(session.queue) do Music.queue[#Music.queue + 1] = table.clone(track) end
  Music.index = math.clamp(tonumber(session.index) or 1, 1, #Music.queue)
  Music.now = Music.queue[Music.index]
  Music.resumeAt = tonumber(session.at) or 0
  Music.state = "idle"
  Music.changed:fire("queue")
  Music.changed:fire("track")
end

-- ---------------------------------------------------------------- settings, keys, the tab
function Music.define()
  for id, default in pairs({ volume = 60, speed = 100, keepPitch = false, bass = 0, mid = 0, treble = 0, reverb = 0, even = false, fade = 0, shuffle = false,
    autoplay = true, mini = true, cacheMb = 800, tint = true, announce = true, resume = true }) do
    Config.define("music." .. id, default)
  end
  Config.define("music.repeat", "off")
  Config.define("music.source", "sc")
  Config.define("music.visual", "bars")
  for _, id in ipairs({ "music.liked", "music.history", "music.playlists" }) do Config.define(id, {}) end
  Config.define("music.session", {})
  for _, id in ipairs({ "music.liked", "music.history", "music.playlists", "music.session" }) do Config.unshared(id) end
  if B.Lyrics then B.Lyrics.define() end
  if B.Card then B.Card.define() end
  if B.PC then B.PC.define(); B.PC.start() end
  if B.Quiet then B.Quiet.start() end
  for _, id in ipairs({ "music.volume", "music.speed", "music.keepPitch", "music.bass", "music.mid", "music.treble", "music.reverb", "music.even" }) do
    Config.on(id, effects)
  end
  -- the keys work from the start (the tab itself may not be drawn yet)
  local ACTIONS = {
    { "music.toggle", "Music: play / pause", function() Music.front().toggle() end },
    { "music.next", "Music: next song", function() Music.front().next() end },
    { "music.previous", "Music: song before", function() Music.front().previous() end },
    { "music.like", "Music: like this song", function() local track = Music.front().track(); if track then Music.like(track, not Music.liked(track)) end end },
    { "music.louder", "Music: louder", function() Config.set("music.volume", math.min((Config.get("music.volume") or 60) + 10, 200)) end },
    { "music.quieter", "Music: quieter", function() Config.set("music.volume", math.max((Config.get("music.volume") or 60) - 10, 0)) end },
    { "music.size", "Music: big / small player", function() if B.Card then B.Card.toggleMode() end end },
  }
  for _, action in ipairs(ACTIONS) do
    Config.action(action[1], action[3])
    if B.Controls then B.Controls.bindables[action[1]] = B.Controls.bindables[action[1]] or { label = action[2], kind = "button" } end
  end
  Config.actionState("music.toggle", function() return Music.front().state() == "playing" end)
  restoreSession()
  B.onUnload:connect(function()
    saveSession()
    stopAll()
  end)
  Motion.every(function() if Music.state == "playing" then saveSession() end end, 1 / 15, "music.session")
end
B.pages = B.pages or {}
B.pages[#B.pages + 1] = function()
  Music.define()
  fs.mkdir(CACHE)
  fs.mkdir(ART)
  task.defer(function() if B.alive and B.Card then B.Card.start() end end)
  Window.page({ id = "music", title = "Music", icon = "music", group = "Hub", order = 870, eyebrow = "Your music, while you play", build = function(page)
    -- (stage: in a look whose Music tab has the player as its stage, Novoline's, this one is that)
    local now = page:section({ title = "Now playing", icon = "disc-3", full = true, stage = true })
    now:custom({ height = 214, name = "Player", build = function(f) Music.viewPlayer(f) end })
    local words = page:section({ title = "Lyrics", icon = "message-circle", full = true, desc = "Every word as it is sung. Click a line to go to it." })
    words:custom({ height = 260, name = "Lyrics", build = Music.viewLyrics })
    local find = page:section({ title = "Find music", icon = "search", full = true, desc = "SoundCloud songs start in a few seconds and are kept, so they start at once next time." })
    find:custom({ height = 420, name = "Search", build = Music.viewSearch })
    local queue = page:section({ title = "Queue", icon = "list-music", column = 1 })
    queue:custom({ height = 260, name = "Queue", build = Music.viewQueue })
    queue:button({ label = "Clear the queue", tip = "Removes every song from the queue.", text = "Clear", bindable = false, run = function() Music.clearQueue() end })
    local liked = page:section({ title = "Liked", icon = "heart", column = 2 })
    liked:custom({ height = 260, name = "Liked", build = Music.viewLiked })
    liked:button({ label = "Play every liked song", tip = "Plays all your liked songs.", text = "Play", bindable = false, run = function() Music.playList(Config.get("music.liked") or {}) end })
    local lists = page:section({ title = "Playlists", icon = "library", column = 1 })
    lists:custom({ height = 300, name = "Playlists", build = Music.viewPlaylists })
    local recent = page:section({ title = "Played lately", icon = "history", column = 2 })
    recent:custom({ height = 300, name = "History", build = Music.viewHistory })
    local sound = page:section({ title = "Sound", icon = "sliders-horizontal", column = 1 })
    sound:slider({ id = "music.volume", label = "Volume", tip = "How loud the music is.", min = 0, max = 200, step = 1, default = 60, suffix = "%" })
    sound:toggle({ id = "music.muteGame", label = "Mute the game", desc = "Only the music and the menu are heard.", default = false })
    sound:slider({ id = "music.gameVolume", label = "Game volume", desc = "How loud the game itself is. 0: silent.", min = 0, max = 100, step = 1, default = 100, suffix = "%" })
    sound:slider({ id = "music.speed", label = "Speed", tip = "How fast the song plays.", min = 50, max = 200, step = 5, default = 100, suffix = "%" })
    sound:toggle({ id = "music.keepPitch", label = "Keep the pitch", desc = "Faster or slower without the voice going high or low.", default = false, bindable = false })
    sound:slider({ id = "music.bass", label = "Bass", tip = "More or less low end.", min = -10, max = 20, step = 1, default = 0, suffix = " dB" })
    sound:slider({ id = "music.mid", label = "Middle", tip = "More or less middle.", min = -10, max = 10, step = 1, default = 0, suffix = " dB" })
    sound:slider({ id = "music.treble", label = "Treble", tip = "More or less high end.", min = -10, max = 10, step = 1, default = 0, suffix = " dB" })
    sound:slider({ id = "music.reverb", label = "Echo", tip = "Adds room sound.", min = 0, max = 100, step = 5, default = 0, suffix = "%" })
    sound:toggle({ id = "music.even", label = "Even loudness", desc = "Quiet and loud songs end up closer.", default = false, bindable = false })
    sound:slider({ id = "music.fade", label = "Crossfade", desc = "Songs blend into the next. 0: off.", min = 0, max = 10, step = 1, default = 0, suffix = " s" })
    local player = page:section({ title = "Player", icon = "settings-2", column = 2 })
    player:button({ id = "music.toggle", label = "Play / pause", tip = "Plays or pauses the song.", text = "Toggle", run = function() Music.front().toggle() end })
    player:button({ id = "music.next", label = "Next song", tip = "Skips to the next song.", text = "Next", run = function() Music.front().next() end })
    player:button({ id = "music.previous", label = "Song before", tip = "Goes back a song.", text = "Back", run = function() Music.front().previous() end })
    player:button({ id = "music.size", label = "Big / small player", tip = "Switches the on-screen player's size.", text = "Switch", run = function() if B.Card then B.Card.toggleMode() end end })
    player:button({ id = "music.like", label = "Like this song", tip = "Adds the song to your liked list.", text = "Like", run = function() local track = Music.front().track(); if track then Music.like(track, not Music.liked(track)) end end })
    player:toggle({ id = "music.autoplay", label = "Keep playing", desc = "When the queue ends, songs like the last one play.", default = true, bindable = false })
    player:toggle({ id = "music.resume", label = "Pick up where you were", desc = "The queue and the song come back next time.", default = true, bindable = false })
    player:toggle({ id = "music.announce", label = "Show each new song", tip = "A message when a new song starts.", default = true, bindable = false })
    local look = page:section({ title = "Look", icon = "palette", column = 1 })
    look:toggle({ id = "music.mini", label = "Player on screen", desc = "While the menu is shut. Tap its cover: big or small.", default = true, bindable = false })
    look:toggle({ id = "music.island", label = "Island", desc = "The line being sung, at the top of the screen.", default = true, bindable = false })
    look:segmented({ id = "music.visual", label = "Bars", tip = "How the music bars look.", options = { { "bars", "Bars" }, { "off", "Off" } }, default = "bars" })
    look:toggle({ id = "music.tint", label = "Cover colour", desc = "The player takes the colour of the cover.", default = true, bindable = false })
    look:toggle({ id = "music.lyrics", label = "Lyrics", desc = "Looked up for each song (LRCLIB, NetEase).", default = true, bindable = false })
    look:slider({ id = "music.lyricsShift", label = "Lyrics timing", desc = "Up: the words come sooner.", min = -2000, max = 2000, step = 100, default = 0, suffix = " ms" })
    -- (2026-11-09: this song's own nudge, kept for it, on top of the timing above; and a fresh look-up for a wrong match)
    local function nudge(ms)
      local track = Music.front().track()
      if not (track and B.Lyrics) then return end
      local now = B.Lyrics.nudge(track, ms)
      Window.toast({ title = "Lyrics for this song", text = string.format("%+.1f s (kept for this song)", now / 1000), icon = "clock", time = 2 })
    end
    look:button({ id = "music.lyricsSooner", label = "This song's words", tip = "0.1 s sooner, kept for this song.", text = "Sooner", run = function() nudge(100) end })
    look:button({ id = "music.lyricsLater", label = "This song's words", tip = "0.1 s later, kept for this song.", text = "Later", run = function() nudge(-100) end })
    look:button({ id = "music.lyricsAgain", label = "Wrong words?", tip = "Looks this song's words up again.", text = "Find again", run = function()
      local track = Music.front().track()
      if track and B.Lyrics then B.Lyrics.again(track) end
    end })
    local pc = page:section({ title = "Music on this PC", icon = "monitor", column = 2, desc = "Spotify, Apple Music or a browser, worked from here." })
    pc:toggle({ id = "music.pc", label = "Show what this PC plays", tip = "Shows Spotify or browser music in the game.", default = false, bindable = false })
    local pcLine = pc:note({ icon = "info", text = "" })
    pc:button({ label = "Set up (copies a command)", tip = "Copies the command that sets up PC music.", text = "Set up", bindable = false, run = function()
      local command, why = B.PC.install()
      if not command then
        Window.toast({ title = "Could not set it up", text = tostring(why), icon = "triangle-alert", tone = "bad" })
        return
      end
      Config.set("music.pc", true)
      B.clipboard(command)
      Window.toast({ title = "Command copied", text = "Press Win+R, paste it, press Enter.", icon = "clipboard", time = 6 })
    end })
    pc:button({ label = "Close the helper", tip = "Stops the PC music helper.", text = "Close", bindable = false, run = function() B.PC.send("quit") end })
    Motion.every(function()
      if pcLine.frame.Parent and Window.showing("music") then pcLine.set(B.PC.describe()) end
    end, 2, "music.pcLine")
    local keep = page:section({ title = "Kept songs", icon = "hard-drive", column = 2 })
    keep:slider({ id = "music.cacheMb", label = "Keep up to", desc = "Songs kept on disk start at once next time. All the way right: no limit.", min = 100,
      max = Music.CACHE_ANY, step = 100, default = 800, curve = 2.6, valueWidth = 84, format = function(v)
        if v >= Music.CACHE_ANY then return "No limit" end
        return v >= 1000 and string.format("%.1f GB", v / 1000) or (util.comma(v) .. " MB")
      end })
    local line = keep:note({ icon = "info", text = "" })
    keep:button({ label = "Clear kept songs", tip = "Deletes downloaded songs to free space.", text = "Clear", style = "danger", bindable = false, run = function()
      Music.clearCache()
      Window.toast({ title = "Kept songs cleared", icon = "trash-2" })
    end })
    Motion.every(function()
      if not (line.frame.Parent and Window.showing("music")) then return end
      local size, count = Music.cacheSize()
      local mb = size / 1048576
      local amount = mb >= 1024 and string.format("%.2f GB", mb / 1024) or string.format("%.0f MB", mb)
      line.set(string.format("%d songs kept, %s. Your own files go in workspace/BasedHub/music.", count, amount))
    end, 0.5, "music.cacheLine")
  end })
end
end
do -- 45a_quiet.lua
-- ============================================================================
--  45a quiet   the game's own sound turned down, or off: the music and the
--              menu are what you hear
--
--  Every sound the game plays that is not the hub's (B.owns: the music, the
--  menu's clicks, the hit sounds, the flight) is turned down by the setting:
--  a Sound, the new audio's AudioPlayer, a voice (AudioDeviceInput). What the
--  game wants each at is kept and given back when it is let go, and a game
--  that sets a volume again is turned down again at once. At full volume
--  nothing is watched at all.
-- ============================================================================
local S, Config, Motion = B.S, B.Config, B.Motion
local Quiet = { count = 0 }
B.Quiet = Quiet

local KINDS = { Sound = "Volume", AudioPlayer = "Volume", AudioDeviceInput = "Volume" }
local ROOTS = { "Workspace", "SoundService", "ReplicatedStorage", "ReplicatedFirst", "Players", "Lighting", "Chat", "TextChatService" }
local watched = {}       -- item -> { want = volume the game wants, property, link, gone, ours = what was last written, lost = sweeps unparented }
local roots = {}         -- DescendantAdded links while it is on
local factor = 1

local function write(item, entry)
  local value = entry.want * factor
  entry.ours = value
  if item[entry.property] ~= value then pcall(function() item[entry.property] = value end) end
end
local function forget(item, putBack)
  local entry = watched[item]
  if not entry then return end
  watched[item] = nil
  Quiet.count -= 1
  if entry.link then entry.link:Disconnect() end
  if entry.gone then entry.gone:Disconnect() end
  if putBack then pcall(function() item[entry.property] = entry.want end) end
end
local function take(item)
  if watched[item] then return end
  local ok, class = pcall(function() return item.ClassName end)
  local property = ok and KINDS[class]
  if not property or B.owns(item) then return end
  local read, value = pcall(function() return item[property] end)
  if not read or type(value) ~= "number" then return end
  local entry = { want = value, property = property, lost = 0 }
  watched[item] = entry
  Quiet.count += 1
  -- (the game set it again: that is what it wants now. Our own writes come back here too, and are told apart by value)
  entry.link = item:GetPropertyChangedSignal(property):Connect(function()
    local now = item[property]
    if entry.ours ~= nil and math.abs(now - entry.ours) < 1e-4 then return end
    entry.want = now
    write(item, entry)
  end)
  local okGone, gone = pcall(function() return item.Destroying:Connect(function() forget(item, false) end) end)
  if okGone then entry.gone = gone end
  write(item, entry)
end
Quiet.take = take

-- everything there now, a few thousand a frame (a big map has tens of thousands of things in it)
local scanToken = 0
local function scanAll()
  scanToken += 1
  local token = scanToken
  task.spawn(function()
    for _, name in ipairs(ROOTS) do
      local okRoot, root = pcall(function() return game:GetService(name) end)
      if okRoot and root then
        local okList, list = pcall(function() return root:GetDescendants() end)
        if okList then
          for index, item in ipairs(list) do
            if scanToken ~= token or factor >= 1 then return end
            take(item)
            if index % 3000 == 0 then task.wait() end
          end
        end
      end
    end
  end)
end
local function watch(on)
  for _, link in ipairs(roots) do link:Disconnect() end
  table.clear(roots)
  if not on then return end
  for _, name in ipairs(ROOTS) do
    local okRoot, root = pcall(function() return game:GetService(name) end)
    if okRoot and root then
      roots[#roots + 1] = root.DescendantAdded:Connect(function(item)
        if KINDS[item.ClassName] then take(item) end
      end)
    end
  end
end

-- how loud the game is: 0 muted .. 1 as it is
function Quiet.level()
  if Config.get("music.muteGame") == true then return 0 end
  return math.clamp((Config.get("music.gameVolume") or 100) / 100, 0, 1)
end
function Quiet.apply()
  local level = Quiet.level()
  local was = factor
  factor = level
  if level >= 1 then
    -- (back to how the game had it, and nothing watched any more)
    scanToken += 1
    watch(false)
    for item in pairs(watched) do forget(item, true) end
    Quiet.count = 0
    return
  end
  for item, entry in pairs(watched) do write(item, entry) end
  if was >= 1 then
    watch(true)
    scanAll()
  end
end

function Quiet.define()
  Config.define("music.muteGame", false)
  Config.define("music.gameVolume", 100)
end
function Quiet.start()
  if Quiet.started then return end
  Quiet.started = true
  Quiet.define()
  Config.on("music.muteGame", function() B.try("quiet.apply", Quiet.apply) end)
  Config.on("music.gameVolume", function() B.try("quiet.apply", Quiet.apply) end)
  -- (things put aside and never destroyed: let go of after two looks, so nothing is held on to for ever)
  Motion.every(function()
    if factor >= 1 then return end
    for item, entry in pairs(watched) do
      if item.Parent == nil then
        entry.lost += 1
        if entry.lost >= 2 then forget(item, true) end
      else
        entry.lost = 0
      end
    end
  end, 0.1, "quiet.sweep")
  B.try("quiet.apply", Quiet.apply)
  B.onUnload:connect(function()
    scanToken += 1
    watch(false)
    for item in pairs(watched) do forget(item, true) end
  end)
end
end
do -- 46_cover.lua
-- ============================================================================
--  46 cover    the colour of a song's cover, for the music player's tint
--
--  Measured 2026-10-21: an EditableImage reads a PNG from a custom asset, but
--  refuses a JPEG ("Failed to load texture, unexpected format"), and covers
--  are JPEG. So the JPEG is read here, only as far as its DC coefficients:
--  each 8x8 block's average, which is plenty for one colour. Baseline and
--  progressive files (Huffman coding), any sampling. PNGs go through the
--  EditableImage. It yields as it goes, so a big cover costs no frame.
-- ============================================================================
local S = B.S
local Cover = {}
B.Cover = Cover

local band, rshift = bit32.band, bit32.rshift
local byte = string.byte
local floor, ceil = math.floor, math.ceil

local function u16(s, i) return (byte(s, i) or 0) * 256 + (byte(s, i + 1) or 0) end
local function huffman(counts, symbols)
  local maxcode, valptr, mincode = {}, {}, {}
  local code, k = 0, 1
  for len = 1, 16 do
    local n = counts[len]
    if n > 0 then
      valptr[len], mincode[len] = k, code
      code += n
      k += n
      maxcode[len] = code - 1
    else
      maxcode[len] = -1
    end
    code *= 2
  end
  return { maxcode = maxcode, valptr = valptr, mincode = mincode, symbols = symbols }
end

-- the bits of one scan (0xFF00 is a stuffed 0xFF; another marker reads as zeros)
local data, pos, cur, left = "", 1, 0, 0
local function bit()
  if left == 0 then
    local b = byte(data, pos) or 0
    if b == 0xFF then
      local after = byte(data, pos + 1) or 0
      if after == 0 then pos += 2 else b = 0 end
    else
      pos += 1
    end
    cur, left = b, 8
  end
  left -= 1
  return band(rshift(cur, left), 1)
end
local function bits(n)
  local v = 0
  for _ = 1, n do v = v * 2 + bit() end
  return v
end
local function decode(h)
  if not h then return 0 end
  local code = 0
  for len = 1, 16 do
    code = code * 2 + bit()
    if code <= h.maxcode[len] then return h.symbols[h.valptr[len] + code - h.mincode[len]] or 0 end
  end
  return 0
end
local function extend(v, size)
  if size == 0 then return 0 end
  if v < 2 ^ (size - 1) then return v - 2 ^ size + 1 end
  return v
end
local function nextMarker(s, at)
  while at < #s do
    if byte(s, at) == 0xFF then
      local m = byte(s, at + 1) or 0
      if m ~= 0 and not (m >= 0xD0 and m <= 0xD7) and m ~= 0xFF then return at end
    end
    at += 1
  end
  return #s
end

-- each component's block averages (DC), on the grid of an interleaved scan
local function readJpeg(s, yield)
  if u16(s, 1) ~= 0xFFD8 then return nil end
  local quant, dcTables, acTables = {}, {}, {}
  local frame, interval = nil, 0
  local i, work = 3, 0
  while i < #s do
    if byte(s, i) ~= 0xFF then i += 1; continue end
    local m = byte(s, i + 1) or 0
    if m == 0xFF then i += 1; continue end
    if m == 0xD8 or m == 0x01 or (m >= 0xD0 and m <= 0xD7) then i += 2; continue end
    if m == 0xD9 then break end
    local length = u16(s, i + 2)
    local seg, stop = i + 4, i + 2 + length
    if m == 0xDB then
      local j = seg
      while j < stop do
        local pq, tq = rshift(byte(s, j), 4), band(byte(s, j), 15)
        quant[tq] = pq == 0 and byte(s, j + 1) or u16(s, j + 1)
        j += 1 + (pq == 0 and 64 or 128)
      end
    elseif m == 0xC0 or m == 0xC1 or m == 0xC2 then
      frame = { progressive = m == 0xC2, height = u16(s, seg + 1), width = u16(s, seg + 3), comps = {} }
      local hmax, vmax = 1, 1
      for c = 1, byte(s, seg + 5) do
        local base = seg + 6 + (c - 1) * 3
        local hv = byte(s, base + 1)
        local comp = { id = byte(s, base), h = math.max(rshift(hv, 4), 1), v = math.max(band(hv, 15), 1), tq = byte(s, base + 2), pred = 0, grid = {}, done = false }
        hmax, vmax = math.max(hmax, comp.h), math.max(vmax, comp.v)
        frame.comps[c] = comp
      end
      frame.mcux, frame.mcuy = ceil(frame.width / (8 * hmax)), ceil(frame.height / (8 * vmax))
      for _, comp in ipairs(frame.comps) do
        comp.bw = ceil(ceil(frame.width * comp.h / hmax) / 8)
        comp.bh = ceil(ceil(frame.height * comp.v / vmax) / 8)
        comp.gw = frame.mcux * comp.h
      end
    elseif m == 0xC4 then
      local j = seg
      while j < stop do
        local tc, th = rshift(byte(s, j), 4), band(byte(s, j), 15)
        local counts, total = {}, 0
        for k = 1, 16 do counts[k] = byte(s, j + k) or 0; total += counts[k] end
        local symbols = {}
        for k = 1, total do symbols[k] = byte(s, j + 16 + k) or 0 end
        if tc == 0 then dcTables[th] = huffman(counts, symbols) else acTables[th] = huffman(counts, symbols) end
        j += 17 + total
      end
    elseif m == 0xDD then
      interval = u16(s, seg)
    elseif m == 0xC3 or (m >= 0xC5 and m <= 0xCF and m ~= 0xC8 and m ~= 0xCC) then
      return nil  -- (lossless or arithmetic coding: not covers)
    elseif m == 0xDA then
      if not frame then return nil end
      local count = byte(s, seg)
      local comps = {}
      for c = 1, count do
        local id, tables = byte(s, seg + 1 + (c - 1) * 2), byte(s, seg + 2 + (c - 1) * 2)
        for _, comp in ipairs(frame.comps) do
          if comp.id == id then comp.td, comp.ta = rshift(tables, 4), band(tables, 15); comps[#comps + 1] = comp end
        end
      end
      local after = seg + 1 + count * 2
      local ss, ah, al = byte(s, after), rshift(byte(s, after + 2), 4), band(byte(s, after + 2), 15)
      local wanted = (not frame.progressive) or (ss == 0 and ah == 0)
      if wanted then
        data, pos, left = s, stop, 0
        local skipAC = not frame.progressive
        local scale = 2 ^ al
        for _, comp in ipairs(comps) do comp.pred = 0 end
        local function restart()
          left = 0
          if byte(s, pos) == 0xFF and (byte(s, pos + 1) or 0) >= 0xD0 and (byte(s, pos + 1) or 0) <= 0xD7 then pos += 2 end
          for _, comp in ipairs(comps) do comp.pred = 0 end
        end
        local function block(comp, bx, by)
          local size = decode(dcTables[comp.td])
          comp.pred += extend(bits(size), size)
          comp.grid[by * comp.gw + bx] = comp.pred * scale
          if skipAC then
            local h, k = acTables[comp.ta], 1
            while k < 64 do
              local rs = decode(h)
              local r, sz = rshift(rs, 4), band(rs, 15)
              if sz == 0 then
                if r == 15 then k += 16 else break end
              else
                k += r
                bits(sz)
                k += 1
              end
            end
          end
          work += 1
          if yield and work % 300 == 0 then yield() end
        end
        if #comps > 1 then
          for n = 0, frame.mcux * frame.mcuy - 1 do
            if interval > 0 and n > 0 and n % interval == 0 then restart() end
            local mx, my = n % frame.mcux, n // frame.mcux
            for _, comp in ipairs(comps) do
              for v = 0, comp.v - 1 do
                for h = 0, comp.h - 1 do block(comp, mx * comp.h + h, my * comp.v + v) end
              end
            end
          end
        elseif comps[1] then
          local comp, n = comps[1], 0
          for by = 0, comp.bh - 1 do
            for bx = 0, comp.bw - 1 do
              if interval > 0 and n > 0 and n % interval == 0 then restart() end
              block(comp, bx, by)
              n += 1
            end
          end
        end
        for _, comp in ipairs(comps) do comp.done = true end
      end
      i = nextMarker(s, math.max(pos, stop))
      -- (every component's averages are in: the rest of a progressive file is detail)
      local all = true
      for _, comp in ipairs(frame.comps) do if not comp.done then all = false end end
      if all then break end
      continue
    end
    i = stop
  end
  if not frame or not frame.comps[1] or not frame.comps[1].done then return nil end
  return frame, quant
end

-- a few hundred colours from the block averages
local function jpegColors(s, yield)
  local frame, quant = readJpeg(s, yield)
  if not frame then return nil end
  local Y, Cb, Cr = frame.comps[1], frame.comps[2], frame.comps[3]
  local function q(comp) return quant[comp.tq] or 1 end
  local out = {}
  local step = math.max(1, floor(math.sqrt(Y.bw * Y.bh / 900)))
  for by = 0, Y.bh - 1, step do
    for bx = 0, Y.bw - 1, step do
      local y = (Y.grid[by * Y.gw + bx] or 0) * q(Y) / 8 + 128
      local r, g, b = y, y, y
      if Cb and Cr and Cb.done and Cr.done then
        local cx, cy = floor(bx * Cb.h / Y.h), floor(by * Cb.v / Y.v)
        local cb = (Cb.grid[cy * Cb.gw + cx] or 0) * q(Cb) / 8
        local cr = (Cr.grid[cy * Cr.gw + cx] or 0) * q(Cr) / 8
        r, g, b = y + 1.402 * cr, y - 0.344136 * cb - 0.714136 * cr, y + 1.772 * cb
      end
      out[#out + 1] = Color3.new(math.clamp(r / 255, 0, 1), math.clamp(g / 255, 0, 1), math.clamp(b / 255, 0, 1))
    end
  end
  return out
end
local function pngColors(path)
  if type(getcustomasset) ~= "function" then return nil end
  local okId, id = pcall(getcustomasset, path)
  if not okId then return nil end
  local ok, image = pcall(function() return S.AssetService:CreateEditableImageAsync(Content.fromUri(id)) end)
  B.identity()
  if not ok or not image then return nil end
  local out = {}
  pcall(function()
    local size = image.Size
    local pixels = image:ReadPixelsBuffer(Vector2.zero, size)
    local total = size.X * size.Y
    local stride = math.max(1, floor(total / 900))
    for n = 0, total - 1, stride do
      local at = n * 4
      out[#out + 1] = Color3.fromRGB(buffer.readu8(pixels, at), buffer.readu8(pixels, at + 1), buffer.readu8(pixels, at + 2))
    end
  end)
  pcall(function() image:Destroy() end)
  return out
end

-- the colour that stands out: hues weighed by how vivid they are, the heaviest one's average
function Cover.pick(colors)
  if not colors or #colors == 0 then return nil end
  local bins = {}
  local r0, g0, b0 = 0, 0, 0
  for _, c in ipairs(colors) do
    r0, g0, b0 = r0 + c.R, g0 + c.G, b0 + c.B
    local h, sat, val = c:ToHSV()
    if val > 0.16 and sat > 0.2 then
      local key = floor(h * 18) % 18
      local weight = sat * (1.2 - math.abs(val - 0.62))
      local bin = bins[key]
      if not bin then bin = { w = 0, r = 0, g = 0, b = 0 }; bins[key] = bin end
      bin.w += weight
      bin.r, bin.g, bin.b = bin.r + c.R * weight, bin.g + c.G * weight, bin.b + c.B * weight
    end
  end
  local best
  for _, bin in pairs(bins) do if not best or bin.w > best.w then best = bin end end
  if not best or best.w < #colors * 0.03 then
    -- (a grey cover: its own grey, kept dark)
    local n = #colors
    local _, _, val = Color3.new(r0 / n, g0 / n, b0 / n):ToHSV()
    return Color3.fromHSV(0, 0, math.clamp(val * 0.6, 0.16, 0.42))
  end
  local h, sat, val = Color3.new(best.r / best.w, best.g / best.w, best.b / best.w):ToHSV()
  return Color3.fromHSV(h, math.clamp(sat * 1.12, 0.38, 0.92), math.clamp(val, 0.42, 0.86))
end

-- path of a cover file -> Color3 (or nil); yields while it reads
-- (one at a time: the bit reader is shared, and it yields)
local busy = false
function Cover.color(path)
  local ok, s = pcall(readfile, path)
  if not ok or type(s) ~= "string" or #s < 64 then return nil end
  while busy do task.wait() end
  busy = true
  local colors
  if string.sub(s, 1, 8) == "\137PNG\r\n\26\n" then
    local done, got = pcall(pngColors, path)
    colors = done and got or nil
  elseif u16(s, 1) == 0xFFD8 then
    local done, got = pcall(jpegColors, s, task.wait)
    colors = done and got or nil
  end
  busy = false
  local picked, color = pcall(Cover.pick, colors)
  return picked and color or nil
end
Cover.test = { readJpeg = readJpeg, jpegColors = jpegColors }
end
do -- 47_lyrics.lua
-- ============================================================================
--  47 lyrics   the words of the song, in time: the lines from LRCLIB, the time
--              of each word from NetEase where it has it
--
--  Measured 2026-10-25 from this PC:
--    * LRCLIB (lrclib.net: open, no key) answers a search in 1 to 3 s, and had
--      lines with times for every song tried.
--    * NetEase (music.163.com: no key) cloud search + song/lyric/v1 "yrc" has
--      each word's own time. Its first match had them for 4 of 12 songs;
--      looking through its first three matches found them for 10 of 10
--      popular songs. 1 to 4 s.
--    * Where only the lines have times, each line's words are spread over the
--      time it is sung, by their letters: 0.08 s a letter + 0.2 s, at least
--      0.6 s, each word weighed by its letters + 1. Against the real word times
--      of those 10 songs (4,892 words): half the words within 0.16 s, nine in
--      ten within 0.67 s (slow, held notes are the worst). Every word at its
--      line's start would be 1.05 s and 2.94 s.
--  Kept on disk (music/lyrics). A song with none is asked for again in 3 days.
-- ============================================================================
local S, Config, fs = B.S, B.Config, B.fs
local Http = S.HttpService
local Lyrics = { entries = {}, byTrack = {}, changed = B.Signal.new() }
B.Lyrics = Lyrics

local FOLDER = fs.path("music/lyrics")
local AGENT = "BASEDHub/1.0 (https://github.com/Mrzaytoon/based-hub)"
local BROWSER = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36"
local NETEASE = "https://music.163.com"
local PER_LETTER, PLUS, LEAST = 0.08, 0.2, 0.6
local RETRY = 3 * 86400

-- ---------------------------------------------------------------- the web
local function get(url, agent, referer)
  local send = (type(request) == "function" and request) or (type(http_request) == "function" and http_request) or nil
  local code, body = -1, nil
  if send then
    local headers = { ["User-Agent"] = agent or AGENT }
    if referer then headers.Referer = referer end
    local ok, response = pcall(send, { Url = url, Method = "GET", Headers = headers })
    if ok and type(response) == "table" then code, body = response.StatusCode or 0, response.Body end
  else
    local ok, text = pcall(game.HttpGet, game, url)
    if ok then code, body = 200, text end
  end
  B.identity()
  return code, body
end
local function json(text)
  if type(text) ~= "string" then return nil end
  local ok, value = pcall(Http.JSONDecode, Http, text)
  return ok and value or nil
end
-- (a lookup's requests: one the site did not answer marks it, so "nothing found" is not kept when nothing was asked)
local function ask(ctx, url, agent, referer)
  local code, body = get(url, agent, referer)
  if code ~= 200 and ctx then ctx.miss = true end
  return code, body
end
local function encode(text) return Http:UrlEncode(tostring(text or "")) end
local function trim(text) return (string.match(tostring(text or ""), "^%s*(.-)%s*$")) end
local function letters(text)
  local ok, n = pcall(utf8.len, text)
  return (ok and n) or #text
end

-- ---------------------------------------------------------------- names
-- Accents off (2026-11-09): LRCLIB writes Yeat's "ORCHESTRATË" with the Ë made both ways (one letter, or E and a
-- combining mark), the uploads write "orchestrate": the same name. The Latin-1 letters (U+00C0..U+00FF, C3 80..BF in
-- UTF-8) go to their plain letters and the combining marks (U+0300..U+036F) go.
local FOLD = {}
do
  local base = { "a", "a", "a", "a", "a", "a", "ae", "c", "e", "e", "e", "e", "i", "i", "i", "i", "d", "n", "o", "o", "o", "o", "o", " ",
    "o", "u", "u", "u", "u", "y", "th", "ss" }
  for i, letter in ipairs(base) do
    FOLD[string.char(0xC3, 0x7F + i)] = letter
    FOLD[string.char(0xC3, 0x9F + i)] = (letter == "ss") and "y" or letter
  end
end
local function unaccent(text)
  text = string.gsub(text, "\204[\128-\191]", "")
  text = string.gsub(text, "\205[\128-\175]", "")
  return (string.gsub(text, "\195[\128-\191]", function(c) return FOLD[c] or c end))
end
Lyrics.unaccent = unaccent
-- a name as names are compared: lower case, letters and digits, single spaces, no accents
local function plain(text)
  text = string.lower(unaccent(tostring(text or "")))
  text = string.gsub(text, "&", " and ")
  text = string.gsub(text, "[%p%c]+", " ")
  text = string.gsub(text, "%s+", " ")
  return trim(text)
end
Lyrics.plain = plain
-- what in brackets is not part of a song's name. ("remix", "slowed", "sped up", "live" stay: those
-- are other recordings, with other times)
local NOISE = { "official", "audio", "video", "lyric", "visuali", "prod", "remaster", "explicit", "clean", "dirty", "hq", "hd", "4k",
  "music video", "free dl", "download", "leak", "snippet", "unreleased", "feat", "ft.", "ft ", "with ", "bass boost", "8d", "copyright", "mv" }
local function noise(inner)
  local low = string.lower(inner)
  for _, word in ipairs(NOISE) do
    if string.find(low, word, 1, true) then return "" end
  end
  return nil
end
-- a song's title and artist as a lyrics site names them: "Artist - Title" split, the noise in
-- brackets and the featured artists taken off. The third answer says the name was split (uploads
-- write "Title - Artist" too: the other way round is tried as well).
function Lyrics.clean(title, artist)
  title, artist = tostring(title or ""), tostring(artist or "")
  title = string.gsub(string.gsub(title, "\u{2013}", "-"), "\u{2014}", "-")
  local left, right = string.match(title, "^(.-)%s+%-%s+(.+)$")
  local split = false
  if left and right and trim(left) ~= "" then artist, title, split = left, right, true end
  title = string.gsub(title, "%s*(%b())", function(inner) return noise(inner) end)
  title = string.gsub(title, "%s*(%b[])", function(inner) return noise(inner) end)
  title = string.gsub(title, "%s+[fF][eE]?[aA]?[tT]%.?%s.*$", "")
  title = string.gsub(title, "%s+[wW]/%s.*$", "")
  artist = string.gsub(artist, "%s*%b()", "")
  artist = string.gsub(artist, "%s*%-%s*[Tt]opic$", "")
  artist = string.gsub(artist, "VEVO$", "")
  return trim(title), trim(artist), split
end
-- A speed edit (Track B7, 2026-11-09). The owner plays mostly SoundCloud uploads named "(Slowed)", "slowed + reverb",
-- "(slowed to perfection)", "sped up", "nightcore": the whole song played slower or faster, so its words come at the
-- original's times stretched by the one same factor. No lyrics site has those uploads' own times; looked up under their
-- own name, a site's loose search gave another song's words at a close length (the cache on the owner's PC: "yeat -
-- orchestrate (slowed to perfection)", 202 s, held the lines of another song, 200.76 s), or the original's times at
-- the original's speed. So: the edit's words are the ORIGINAL's, looked up under the name with the edit taken off,
-- and their times are stretched to this upload's length (build). A part of a song ("best part", "loop", "1 hour") is
-- not a stretch of it: its words come without times.
-- Returns "slowed" | "sped" | nil, the name without the edit, and true for a part of a song.
-- (whole words of plain(): "Slowed+Reverb" is "slowed reverb", and "Cutie" is no cut)
local EDIT_SLOW = { "slowed", "slowd", "slow reverb", "slow and reverb", "slowed down" }
local EDIT_FAST = { "sped up", "speed up", "spedup", "speedup", "nightcore", "sped" }
local EDIT_PART = { "best part", "loop", "looped", "1 hour", "one hour", "extended", "part only", "intro only", "cut" }
local function hasWord(text, list)
  local pad = " " .. plain(text) .. " "
  for _, word in ipairs(list) do
    if string.find(pad, " " .. word .. " ", 1, true) then return true end
  end
  return false
end
function Lyrics.edit(title)
  title = tostring(title or "")
  local kind = (hasWord(title, EDIT_SLOW) and "slowed") or (hasWord(title, EDIT_FAST) and "sped") or nil
  if not kind then return nil, title, false end
  local part = hasWord(title, EDIT_PART)
  local words = kind == "slowed" and EDIT_SLOW or EDIT_FAST
  local function edited(inner)
    if hasWord(inner, words) or hasWord(inner, { "reverb" }) then return "" end
    return nil
  end
  local base = string.gsub(title, "%s*(%b())", edited)
  base = string.gsub(base, "%s*(%b[])", edited)
  -- (written after the name with no brackets: "Devil Eyes Slowed", "alone slowed X reverb", "Song - sped up")
  local lowBase = string.lower(base)
  local cut
  for _, word in ipairs(words) do
    local first = string.match(word, "^(%S+)")
    local at = string.find(lowBase, "[%s%-|~]+" .. first .. "%f[%W]")
    if at and (not cut or at < cut) then cut = at end
  end
  if cut then base = string.sub(base, 1, cut - 1) end
  base = string.gsub(base, "[%s%-|~,]+$", "")
  return kind, trim(base), part
end
-- the same song name, however it is decorated ("Fell In Luv (feat. X)" against "Fell In Luv")
local function sameTitle(a, b)
  local x, y = plain(a), plain(b)
  if x == "" or y == "" then return false end
  if x == y then return true end
  return (#y >= 4 and string.find(x, y, 1, true) ~= nil) or (#x >= 4 and string.find(y, x, 1, true) ~= nil)
end
Lyrics.sameTitle = sameTitle
-- the first of several artists ("A, B & C" -> "A")
local function firstArtist(artist)
  local first = string.match(artist, "^(.-)%s*[,&]%s") or string.match(artist, "^(.-)%s+[xX]%s") or string.match(artist, "^(.-)%s+[Ff]eat")
  return first and trim(first) or artist
end

-- ---------------------------------------------------------------- reading lyrics
local function stamp(text)
  local m, s, f = string.match(text, "^(%d+):(%d+)[%.:]?(%d*)$")
  if not m then return nil end
  local fraction = (f ~= "" and tonumber(f) / (10 ^ #f)) or 0
  return tonumber(m) * 60 + tonumber(s) + fraction
end
local function lines(text)
  return string.gmatch(text .. "\n", "([^\r\n]*)\r?\n")
end
-- LRC: "[mm:ss.xx]words", several times on one line, an [offset:], and the words' own times
-- ("<mm:ss.xx>word") where a file has them
function Lyrics.parseLrc(text)
  local out, offset = {}, 0
  for raw in lines(tostring(text or "")) do
    local shift = string.match(raw, "^%s*%[offset:%s*([%+%-]?%d+)%s*%]")
    -- (the "+" taken off first: not every tonumber reads one)
    local value = shift and tonumber((string.gsub(shift, "^%+", ""))) or nil
    if value then offset = value / 1000 end
    local times, rest = {}, raw
    while true do
      local tag, after = string.match(rest, "^%s*%[([%d:%.]+)%](.*)$")
      if not tag then break end
      local t = stamp(tag)
      if t then times[#times + 1] = t end
      rest = after
    end
    if #times > 0 then
      local words
      if string.find(rest, "<%d+:%d+") then
        words = {}
        for tag, word in string.gmatch(rest, "<([%d:%.]+)>([^<]*)") do
          local t = stamp(tag)
          if t and trim(word) ~= "" then words[#words + 1] = { t = t, w = word } end
        end
        rest = string.gsub(rest, "<[%d:%.]+>", "")
        if #words == 0 then words = nil end
      end
      for k, t in ipairs(times) do
        out[#out + 1] = { t = t, text = trim(rest), words = k == 1 and words or nil }
      end
    end
  end
  table.sort(out, function(a, b) return a.t < b.t end)
  -- ("+" in an [offset:] brings the words sooner)
  if offset ~= 0 then
    for _, line in ipairs(out) do
      line.t -= offset
      for _, word in ipairs(line.words or {}) do word.t -= offset end
    end
  end
  return out
end
-- NetEase's word timing: "[start,length](start,length,0)word(start,length,0)word...", in ms. A
-- word runs up to the next mark (it can hold brackets of its own).
function Lyrics.parseYrc(text)
  local out = {}
  for raw in lines(tostring(text or "")) do
    local ls, ld, rest = string.match(raw, "^%[(%d+),(%d+)%](.*)$")
    if ls then
      local words, at = {}, 1
      while true do
        local s, e, ws, wd = string.find(rest, "%((%d+),(%d+),%-?%d+%)", at)
        if not s then break end
        local following = string.find(rest, "%(%d+,%d+,%-?%d+%)", e + 1)
        local word = string.sub(rest, e + 1, (following or (#rest + 1)) - 1)
        if trim(word) ~= "" then
          local start = tonumber(ws) / 1000
          words[#words + 1] = { t = start, e = start + tonumber(wd) / 1000, w = word }
        end
        if not following then break end
        at = following
      end
      if #words > 0 then
        local parts = {}
        for i, word in ipairs(words) do parts[i] = word.w end
        local start = tonumber(ls) / 1000
        out[#out + 1] = { t = start, e = start + tonumber(ld) / 1000, text = trim(table.concat(parts)), words = words }
      end
    end
  end
  table.sort(out, function(a, b) return a.t < b.t end)
  return out
end
-- the credits a Chinese lyrics file opens with ("作词 : ...") are not words of the song
local function dropCredits(list)
  local out = {}
  for _, line in ipairs(list) do
    local credit = string.find(line.text, "^[^%w]*[\128-\255]+%s*[:\u{FF1A}]") ~= nil
    if not credit then out[#out + 1] = line end
  end
  return out
end
Lyrics.dropCredits = dropCredits

-- every line gets an end and words with times: the file's own, or spread over the line (see the top)
function Lyrics.spread(list, length)
  for i, line in ipairs(list) do
    local after = list[i + 1]
    local limit = after and after.t or (line.t + 8)
    if length and length > 0 and not after then limit = math.max(math.min(limit, length), line.t + 0.5) end
    local gap = math.max(limit - line.t, 0.2)
    if not line.e then
      line.e = line.t + math.max(math.min(gap - 0.05, math.max(LEAST, letters(line.text) * PER_LETTER + PLUS)), 0.15)
    end
    if line.words then
      -- (words with a start and no end end where the next one starts)
      for k, word in ipairs(line.words) do
        if not word.e then
          local nextWord = line.words[k + 1]
          word.e = nextWord and nextWord.t or math.max(line.e, word.t + 0.2)
        end
      end
    elseif line.text ~= "" then
      local parts = {}
      for word in string.gmatch(line.text, "%S+") do parts[#parts + 1] = word end
      local total = 0
      local weights = {}
      for k, word in ipairs(parts) do weights[k] = letters(word) + 1; total += weights[k] end
      local t, span = line.t, line.e - line.t
      local words = {}
      for k, word in ipairs(parts) do
        local d = span * weights[k] / total
        words[k] = { t = t, e = t + d, w = k < #parts and (word .. " ") or word }
        t += d
      end
      line.words, line.guessed = words, true
    end
  end
  return list
end

-- ---------------------------------------------------------------- where the song is in them
-- the line at `t` (0 before the first), the word in it (0 before its first), how far through that word
function Lyrics.at(list, t)
  if not list or #list == 0 or t < list[1].t then return 0, 0, 0 end
  local lo, hi = 1, #list
  while lo < hi do
    local mid = (lo + hi + 1) // 2
    if list[mid].t <= t then lo = mid else hi = mid - 1 end
  end
  local line = list[lo]
  local word, through = 0, 0
  for k, w in ipairs(line.words or {}) do
    if w.t <= t then word = k else break end
  end
  local w = line.words and line.words[word]
  if w then through = math.clamp((t - w.t) / math.max(w.e - w.t, 0.05), 0, 1) end
  return lo, word, through
end
-- is line `i` being sung at `t`, or was it a moment ago (and nothing else has started)?
function Lyrics.live(list, i, t)
  local line = list and list[i]
  if not line or line.text == "" then return false end
  local after = list[i + 1]
  if after and t >= after.t then return false end
  return t <= (line.e or line.t) + 2.5
end

-- ---------------------------------------------------------------- drawing a line
local ESCAPE = { ["&"] = "&amp;", ["<"] = "&lt;", [">"] = "&gt;", ['"'] = "&quot;", ["'"] = "&apos;" }
function Lyrics.escape(text) return (string.gsub(tostring(text or ""), "[&<>\"']", ESCAPE)) end
function Lyrics.hex(color)
  return string.format("#%02X%02X%02X", math.floor(color.R * 255 + 0.5), math.floor(color.G * 255 + 0.5), math.floor(color.B * 255 + 0.5))
end
-- rich text for a line: sung words, the word being sung, the rest. colors = { sung, now, next } (hex)
function Lyrics.markup(line, word, colors)
  if not line then return "" end
  if not line.words then return string.format('<font color="%s">%s</font>', colors.sung, Lyrics.escape(line.text)) end
  local out = {}
  for k, w in ipairs(line.words) do
    local color = (k < word and colors.sung) or (k == word and colors.now) or colors.next
    out[#out + 1] = string.format('<font color="%s">%s</font>', color, Lyrics.escape(w.w))
  end
  return table.concat(out)
end

-- ---------------------------------------------------------------- finding them
-- the same artist, however it is spelled ("PlayboiCarti", "Playboi Carti", "Playboi Carti, X")
local function squash(text) return (string.gsub(plain(text), " ", "")) end
local function sameArtist(a, b)
  local x, y = squash(a), squash(b)
  return x ~= "" and y ~= "" and (x == y or string.find(x, y, 1, true) ~= nil or string.find(y, x, 1, true) ~= nil)
end
Lyrics.sameArtist = sameArtist
-- LRCLIB's best answer: lines with times first, then the closest length. (A recording of another
-- length is used only for its words: load() takes the times off.)
-- (2026-11-09: only the song asked for. Its own name, always; and its artist too when no length holds the pick to the
-- recording (a speed edit: the original's length is not known). Its free search answered with any song of a close
-- length: another song's words, live)
local function lrclibPick(list, length, artist, slack, needArtist, title)
  slack = slack or 12
  if not (length and length > 0) then needArtist = true end
  local best, bestScore
  for _, item in ipairs(type(list) == "table" and list or {}) do
    if type(item) == "table" and (item.syncedLyrics or item.plainLyrics or item.instrumental) and (not needArtist or sameArtist(item.artistName, artist))
      and (title == nil or sameTitle(item.trackName or item.name or "", title)) then
      local score = (type(item.syncedLyrics) == "string" and 100) or (item.instrumental and 40) or 20
      local d = tonumber(item.duration)
      if length and length > 0 and d then
        local off = math.abs(d - length)
        if off > slack then score = -1 else score -= off * 4 end
      end
      if score >= 0 and artist ~= "" and plain(item.artistName) == plain(artist) then score += 10 end
      -- (for a speed edit's original: one whose length is known, or its times cannot be stretched; LRCLIB has some without)
      if score >= 0 and not (length and length > 0) and d then score += 5 end
      if score >= 0 and (not bestScore or score > bestScore) then best, bestScore = item, score end
    end
  end
  return best
end
local function fromLrclib(title, artist, length, ctx)
  local queries = { "track_name=" .. encode(title) .. "&artist_name=" .. encode(artist) }
  local first = firstArtist(artist)
  if first ~= artist and first ~= "" then queries[#queries + 1] = "track_name=" .. encode(title) .. "&artist_name=" .. encode(first) end
  queries[#queries + 1] = "q=" .. encode(title .. " " .. first)
  for _, query in ipairs(queries) do
    local code, body = ask(ctx, "https://lrclib.net/api/search?" .. query)
    if code == 200 then
      local item = lrclibPick(json(body), length, artist, nil, nil, title)
      if item then return item end
    end
  end
  -- the title alone (an artist spelled another way): a recording of the same length (3 s), or by
  -- the same artist at any length up to 30 s off
  local code, body = ask(ctx, "https://lrclib.net/api/search?track_name=" .. encode(title))
  if code == 200 then
    local list = json(body)
    return (length and length > 0 and lrclibPick(list, length, artist, 3, nil, title)) or lrclibPick(list, length, artist, 30, true, title)
  end
  return nil
end
-- NetEase: the first three of its matches with the right name, artist and length, for the one with
-- each word's time (and, failing that, the first with timed lines)
local function fromNetease(title, artist, length, ctx)
  local code, body = ask(ctx, NETEASE .. "/api/cloudsearch/pc?s=" .. encode(title .. " " .. firstArtist(artist)) .. "&type=1&limit=8", BROWSER, NETEASE .. "/")
  if code ~= 200 then return nil end
  local data = json(body)
  local songs = type(data) == "table" and type(data.result) == "table" and data.result.songs or nil
  if type(songs) ~= "table" then return nil end
  local want, who = plain(title), plain(firstArtist(artist))
  local looked, timedLines, timedLength = 0, nil, nil
  for _, song in ipairs(songs) do
    if looked >= 3 then break end
    if type(song) == "table" then
      local name = plain(song.name)
      local nameOk = name == want or (#want >= 4 and (string.find(name, want, 1, true) ~= nil or string.find(want, name, 1, true) ~= nil))
      local whoOk = who == ""
      for _, person in ipairs(type(song.ar) == "table" and song.ar or {}) do
        if sameArtist(type(person) == "table" and person.name or "", who) then whoOk = true end
      end
      local d = tonumber(song.dt) and song.dt / 1000 or nil
      local off = (length and length > 0 and d) and math.abs(d - length) or 0
      -- (the right artist at another length: its words, without times; anyone else's only at the same length. With
      -- no length to hold it to (a speed edit's original), the right artist only)
      local anchored = length ~= nil and length > 0
      if nameOk and ((whoOk and off <= 30) or (anchored and off <= 1.5)) then
        looked += 1
        local c2, b2 = ask(ctx, NETEASE .. "/api/song/lyric/v1?id=" .. tostring(song.id) .. "&lv=1&yv=1", BROWSER, NETEASE .. "/")
        local found = c2 == 200 and json(b2) or nil
        if type(found) == "table" then
          if found.pureMusic == true then return { kind = "instrumental", from = "NetEase" } end
          local yrc = type(found.yrc) == "table" and found.yrc.lyric or nil
          if type(yrc) == "string" and #Lyrics.parseYrc(yrc) > 0 then return { kind = "words", yrc = yrc, from = "NetEase", length = d } end
          local lrc = type(found.lrc) == "table" and found.lrc.lyric or nil
          if not timedLines and type(lrc) == "string" and #dropCredits(Lyrics.parseLrc(lrc)) > 2 then timedLines, timedLength = lrc, d end
        end
      end
    end
  end
  if timedLines then return { kind = "lines", lrc = timedLines, from = "NetEase", length = timedLength } end
  return nil
end
-- what is kept, made into lines to show
local function build(entry, kept, length)
  entry.kind, entry.from, entry.loose = kept.kind, kept.from, kept.loose == true
  entry.timed = false
  if kept.kind == "words" then
    entry.lines = Lyrics.spread(Lyrics.parseYrc(kept.yrc), length)
    entry.timed = true
  elseif kept.kind == "lines" then
    entry.lines = Lyrics.spread(dropCredits(Lyrics.parseLrc(kept.lrc)), length)
    entry.timed = true
  elseif kept.kind == "plain" then
    entry.lines = {}
    for raw in lines(kept.plain or "") do entry.lines[#entry.lines + 1] = { t = 0, text = trim(raw) } end
  else
    entry.lines = {}
  end
  if (kept.kind == "words" or kept.kind == "lines") and #entry.lines == 0 then entry.kind, entry.timed = "none", false end
  -- A speed edit (Lyrics.edit): the original's times, stretched to this upload's length, when the two lengths say a
  -- whole song played slower (1.03 to 1.8 as long) or faster (0.55 to 0.97); else its words without times.
  entry.scale = nil
  if entry.edit and entry.timed then
    local r = (length and length > 0 and tonumber(kept.length) and kept.length > 0) and length / kept.length or nil
    local fits = r ~= nil and ((entry.edit == "slowed" and r >= 1.03 and r <= 1.8) or (entry.edit == "sped" and r >= 0.55 and r <= 0.97))
    if fits and not entry.part then
      Lyrics.stretch(entry.lines, r)
      entry.scale, entry.origin = r, kept.length
    else
      for _, line in ipairs(entry.lines) do line.t, line.e, line.words, line.guessed = 0, nil, nil, nil end
      entry.kind, entry.timed, entry.loose = "plain", false, true
    end
  end
  entry.state = (entry.kind == "none") and "none" or "ready"
end
-- (a stretched edit, once its song has loaded: the upload's own length is more exact than the site's whole seconds. Measured
-- 2026-11-09: SoundCloud says 202 for 202.69 s, 0.7 s off by the end. Lines checked against Whisper's word times on the
-- cached audio of two of the owner's uploads: median -0.02 s and -0.01 s, no drift from the first third to the last)
function Lyrics.fit(entry, exact)
  if not (entry and entry.scale and entry.origin and exact and exact > 0) then return end
  local r = exact / entry.origin
  if math.abs(r - entry.scale) < 1e-4 or math.abs(r - entry.scale) > 0.05 then return end
  Lyrics.stretch(entry.lines, r / entry.scale)
  entry.scale = r
end
-- every time in the lines (and their words) times r
function Lyrics.stretch(list, r)
  for _, line in ipairs(list) do
    line.t *= r
    if line.e then line.e *= r end
    for _, word in ipairs(line.words or {}) do
      word.t *= r
      if word.e then word.e *= r end
    end
  end
  return list
end
-- (the cache's own version: 2 since 2026-11-09, when the matching was made strict; what was kept before is looked up again)
local KEPT = 2
local function load(entry, length)
  local path = FOLDER .. "/" .. (entry.file or entry.key) .. ".json"
  local kept = fs.readJson(path)
  if type(kept) == "table" and kept.v == KEPT and (kept.kind ~= "none" or os.time() - (tonumber(kept.at) or 0) < RETRY) then
    build(entry, kept, length)
    Lyrics.changed:fire(entry)
    return
  end
  -- (a speed edit is looked up as its original, whose length is not this one: no length to pick by)
  local want = (not entry.edit) and length or nil
  -- NetEase alongside LRCLIB: whichever has each word's time wins
  local ctx = {}
  local netease, neteaseDone = nil, false
  task.spawn(function()
    local ok, got = pcall(fromNetease, entry.title, entry.artist, want, ctx)
    if ok and not got and entry.split then ok, got = pcall(fromNetease, entry.artist, entry.title, want, ctx) end
    B.identity()
    if not ok then ctx.miss = true end
    netease, neteaseDone = ok and got or nil, true
  end)
  local item = fromLrclib(entry.title, entry.artist, want, ctx)
  if not item and entry.split then item = fromLrclib(entry.artist, entry.title, want, ctx) end
  local waited = 0
  while not neteaseDone and waited < 8 do waited += task.wait(0.1) end
  if not neteaseDone then ctx.miss = true end
  if netease and (netease.kind == "words" or netease.kind == "instrumental") then
    kept = netease
  elseif item and type(item.syncedLyrics) == "string" and item.syncedLyrics ~= "" then
    kept = { kind = "lines", lrc = item.syncedLyrics, from = "LRCLIB", length = tonumber(item.duration) }
  elseif netease then
    kept = netease
  elseif item and item.instrumental then
    kept = { kind = "instrumental", from = "LRCLIB" }
  elseif item and type(item.plainLyrics) == "string" and item.plainLyrics ~= "" then
    kept = { kind = "plain", plain = item.plainLyrics, from = "LRCLIB" }
  else
    kept = { kind = "none" }
  end
  -- Nothing found, but a site did not answer (offline, busy, slow): not kept, asked again in a little while (12 s, 24 s,
  -- 36 s). Kept as "none", a song with words showed none for three days after one bad moment.
  if kept.kind == "none" and ctx.miss then
    entry.tries = (entry.tries or 0) + 1
    entry.offline = true
    entry.retryAt = os.clock() + 12 * entry.tries
    build(entry, kept, length)
    Lyrics.changed:fire(entry)
    return
  end
  entry.offline, entry.retryAt = nil, nil
  -- another length of the song (a re-upload, a longer intro): its times would be wrong, so its words
  -- are shown without them (a speed edit's are stretched instead, in build)
  if not entry.edit and length and length > 0 and kept.length and math.abs(kept.length - length) > 4 and (kept.kind == "words" or kept.kind == "lines") then
    local list = kept.kind == "words" and Lyrics.parseYrc(kept.yrc) or dropCredits(Lyrics.parseLrc(kept.lrc))
    local words = {}
    for _, line in ipairs(list) do if line.text ~= "" then words[#words + 1] = line.text end end
    kept = { kind = "plain", plain = table.concat(words, "\n"), from = kept.from, loose = true }
  end
  kept.v, kept.at = KEPT, os.time()
  fs.mkdir(FOLDER)
  fs.writeJson(path, kept)
  build(entry, kept, length)
  Lyrics.changed:fire(entry)
end
local function keyOf(title, artist)
  local key = string.gsub(plain(artist) .. " " .. plain(title), "[^%w]+", "-")
  return string.sub(key, 1, 90)
end
-- the lyrics of a track: { state = "loading" | "ready" | "none", kind, lines, timed, from }, asked for
-- the first time a track is seen (nil: lyrics are off, or the track has no name)
local function fetch(entry, length)
  entry.state, entry.busy = "loading", true
  task.spawn(function()
    local ok, err = pcall(load, entry, length)
    B.identity()
    entry.busy = false
    if not ok then
      B.fault("lyrics.load", err)
      entry.state, entry.kind = "none", "none"
      entry.tries, entry.offline = (entry.tries or 0) + 1, true
      entry.retryAt = os.clock() + 12 * entry.tries
      Lyrics.changed:fire(entry)
    end
  end)
end
function Lyrics.forTrack(track, exact)
  if not track or Config.get("music.lyrics") == false then return nil end
  local known = Lyrics.byTrack[track.key]
  if known then
    if exact and known.scale then Lyrics.fit(known, exact) end
    -- (not answered last time: asked again, up to three more times)
    if known.offline and not known.busy and known.retryAt and os.clock() >= known.retryAt and (known.tries or 0) < 4 then
      fetch(known, known.length or tonumber(track.duration) or 0)
    end
    return known
  end
  local title, artist, split = Lyrics.clean(track.title, track.artist)
  if title == "" then return nil end
  -- (a speed edit: the original's words, under the name with the edit taken off; kept on disk as the original's, and
  -- stretched to this upload's own length, so one entry a length)
  local edit, base, part = Lyrics.edit(title)
  if edit and base ~= "" then title = base end
  local length = tonumber(track.duration) or 0
  local file = keyOf(title, artist)
  local key = edit and (file .. "~" .. edit .. "~" .. math.floor(length + 0.5)) or file
  local entry = Lyrics.entries[key]
  if not entry then
    entry = { state = "loading", key = key, file = file, title = title, artist = artist, split = split, lines = {}, length = length,
      edit = edit, part = part == true }
    Lyrics.entries[key] = entry
    fetch(entry, entry.length)
  end
  Lyrics.byTrack[track.key] = entry
  return entry
end
-- This song's own nudge (2026-11-09), ms, saved per track: one upload starts later than another, and a global shift
-- cannot fit both. On top of the global Lyrics timing.
function Lyrics.nudgeOf(track)
  local map = Config.get("music.lyricsNudge")
  return (track and type(map) == "table" and tonumber(map[track.key])) or 0
end
function Lyrics.nudge(track, ms)
  if not (track and track.key) then return 0 end
  local map = table.clone(Config.get("music.lyricsNudge") or {})
  local now = math.clamp(math.floor((tonumber(map[track.key]) or 0) + ms + 0.5), -10000, 10000)
  map[track.key] = now ~= 0 and now or nil
  Config.set("music.lyricsNudge", map)
  return now
end
-- the shift on the song's time, in seconds: the global timing and this song's nudge
function Lyrics.shiftOf(track)
  return ((Config.get("music.lyricsShift") or 0) + Lyrics.nudgeOf(track)) / 1000
end
-- the song's time as the words are read: the timing setting (and the song's own nudge) move them sooner or later
function Lyrics.clock(position, track)
  return position + Lyrics.shiftOf(track)
end
-- looked up again from the sites (a wrong match): what was kept is dropped
function Lyrics.again(track)
  if not track then return nil end
  local entry = Lyrics.byTrack[track.key]
  if entry then
    if entry.busy then return entry end
    fs.remove(FOLDER .. "/" .. (entry.file or entry.key) .. ".json")
    Lyrics.entries[entry.key] = nil
    Lyrics.byTrack[track.key] = nil
  end
  return Lyrics.forTrack(track)
end
-- what a view shows while there are no lines
function Lyrics.note(entry)
  if not entry then return "Lyrics are off." end
  if entry.state == "loading" then return "Looking for the words..." end
  if entry.offline then return "The lyrics sites did not answer. Trying again..." end
  if entry.kind == "instrumental" then return "Instrumental" end
  if entry.state == "none" then return "No lyrics found for this one." end
  return nil
end

function Lyrics.define()
  Config.define("music.lyrics", true)
  Config.define("music.lyricsShift", 0)
  Config.define("music.lyricsNudge", {})
end
end
do -- 48_pc.lua
-- ============================================================================
--  48 pc       music on this PC: what Spotify, Apple Music or a browser is
--              playing, shown in the hub and worked from it
--
--  A small helper (based/pc/based-music.ps1, written out by the hub as
--  BasedHub/pc/based-music.txt and started once with Win+R) reads Windows' own
--  "now playing" (the media sessions the volume flyout shows) and writes it
--  with the cover to BasedHub/pc/now.json. The hub writes what to do to
--  do.json. Files both ways: no port, no network, any executor. (Measured: the
--  executor refuses to write a .ps1 or a .cmd, "invalid file path", so the
--  command reads the .txt and runs it.)
--
--  Measured 2026-10-25 against a test session on this PC: the name, artist,
--  length, place and cover come through; play/pause, seek, the app's own
--  volume (the volume mixer) and quit work. The helper keeps to the app it
--  shows until another app STARTS playing (pausing Spotify from here does not
--  hand the player to a video in a browser). A place sent while paused shows
--  once it plays again (the app's own report), so the hub shows it at once.
-- ============================================================================
local S, Config, fs, Motion = B.S, B.Config, B.fs, B.Motion
local Http = S.HttpService
local PC = { state = nil, live = false, track = nil, changed = B.Signal.new(), sent = {}, id = 0, startedAt = 0 }
B.PC = PC

local DIR = fs.path("pc")
local NOW, ORDERS, ALIVE = DIR .. "/now.json", DIR .. "/do.json", DIR .. "/alive.txt"
local HELPER = DIR .. "/based-music.txt"
-- where an executor keeps its workspace, for the one-line command (others get a command that finds it)
local WORKSPACES = { potassium = "\\Potassium\\workspace" }

local function nowMs()
  local ok, ms = pcall(function() return DateTime.now().UnixTimestampMillis end)
  if ok and type(ms) == "number" then return ms end
  return os.time() * 1000
end
PC.nowMs = nowMs

-- ---------------------------------------------------------------- the helper
-- (under 259 letters either way: the Run box takes no more)
function PC.command()
  local root = WORKSPACES[string.lower(tostring(B.executor))]
  if root then
    return string.format("powershell -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -Command \"$p=$env:LOCALAPPDATA+'%s\\%s\\pc\\based-music.txt';"
      .. "&([scriptblock]::Create((gc -Raw -LiteralPath $p))) -Dir (Split-Path $p)\"", root, fs.root)
  end
  -- (finds the newest copy under the places executors keep their files)
  return "powershell -NoP -W Hidden -Ep Bypass -C \"$f=gci $env:LOCALAPPDATA,$env:APPDATA -Fi based-music.txt -Rec -Dep 5 -EA 0|sort LastWriteTime|select -L 1;"
    .. "if($f){&([scriptblock]::Create((gc -Raw -LiteralPath $f.FullName))) -Dir $f.DirectoryName}\""
end
-- writes the helper next to the hub's files; the command that starts it
function PC.install()
  if type(B.PC_HELPER) ~= "string" or B.PC_HELPER == "" then return nil, "this build has no helper in it" end
  fs.mkdir(DIR)
  if not fs.write(HELPER, B.PC_HELPER) then return nil, "the executor would not write the helper" end
  fs.write(ALIVE, tostring(os.time()))
  return PC.command()
end

-- ---------------------------------------------------------------- what it says
local lastText
local function trackOf(s)
  local title = tostring(s.title or "")
  local artist = tostring(s.artist or "")
  local app = tostring(s.app or "An app")
  local key = "pc_" .. string.sub(string.gsub(string.lower(app .. "_" .. artist .. "_" .. title), "[^%w]+", "-"), 1, 80)
  local cover = (type(s.cover) == "string" and s.cover ~= "") and (DIR .. "/" .. s.cover) or nil
  local track = PC.track
  if not (track and track.key == key) then
    track = { source = "pc", key = key, playable = true }
  end
  track.title = title ~= "" and title or "Something on this PC"
  track.artist = artist ~= "" and artist or app
  track.album, track.app = tostring(s.album or ""), app
  track.duration = tonumber(s.length) or 0
  track.coverFile = cover
  return track
end
local function read()
  local text = fs.read(NOW)
  if text and text ~= lastText then
    lastText = text
    local ok, data = pcall(Http.JSONDecode, Http, text)
    if ok and type(data) == "table" then
      local before = PC.state
      PC.state = data
      local old = PC.track
      local playingBefore = before and before.playing == true
      if data.ok and not data.closed and not data.none and data.title then
        PC.track = trackOf(data)
      else
        PC.track = nil
      end
      if PC.track ~= old then PC.changed:fire("track") end
      if (data.playing == true) and (not playingBefore or PC.track ~= old) then PC.startedAt = os.clock() end
      if (before and before.playing) ~= data.playing then PC.changed:fire("state") end
      -- (a guess the helper has now answered goes)
      if PC.guess and PC.guess.track ~= data.track then PC.guess = nil end
    end
  end
  local s = PC.state
  local live = s ~= nil and s.ok == true and not s.closed and (nowMs() - (tonumber(s.at) or 0)) < 4000
  if live ~= PC.live then
    PC.live = live
    PC.changed:fire("live")
  end
end
PC.read = read

-- ---------------------------------------------------------------- telling it what to do
-- This load's own name for its orders, made with the first one: a reload starts a new name, so the
-- helper never takes new orders for ones it has done. (Measured 2026-10-28: math.random gave the same
-- first number on every load, so two loads shared a name and the second one's orders were passed over.)
local session
function PC.send(what, value)
  session = session or string.format("%x-%04x", math.floor(nowMs()), math.random(0, 0xFFFF))
  PC.id += 1
  PC.sent[#PC.sent + 1] = { id = PC.id, ["do"] = what, to = value }
  while #PC.sent > 12 do table.remove(PC.sent, 1) end
  fs.mkdir(DIR)
  fs.writeJson(ORDERS, { s = session, cmds = PC.sent })
end
function PC.playing()
  local guess = PC.guess
  if guess and guess.playing ~= nil and os.clock() < guess.till then return guess.playing end
  return PC.live and PC.state ~= nil and PC.state.playing == true
end
function PC.position()
  local s = PC.state
  if not s then return 0 end
  local guess = PC.guess
  if guess and guess.position and os.clock() < guess.till then
    return guess.position + (PC.playing() and (os.clock() - guess.at) or 0)
  end
  local p = tonumber(s.position) or 0
  if s.playing then p += math.max(0, nowMs() - (tonumber(s.at) or nowMs())) / 1000 * (tonumber(s.rate) or 1) end
  local length = tonumber(s.length) or 0
  if length > 0 then p = math.min(p, length) end
  return math.max(p, 0)
end

-- ---------------------------------------------------------------- the player's side of it (Music.front)
local assets = {}
local function asset(path)
  if assets[path] then return assets[path] end
  if type(getcustomasset) ~= "function" or not fs.exists(path) then return nil end
  local ok, id = pcall(getcustomasset, path)
  B.identity()
  if ok and id then assets[path] = id; return id end
  return nil
end
local tints = {}
local volumeSent = 0
local ctl = { kind = "pc" }
PC.ctl = ctl
function ctl.track() return PC.live and PC.track or nil end
function ctl.state()
  if not (PC.live and PC.track) then return "idle" end
  return PC.playing() and "playing" or "paused"
end
function ctl.status() return nil end
ctl.position = PC.position
function ctl.length() return PC.state and tonumber(PC.state.length) or 0 end
function ctl.toggle()
  PC.guess = { playing = not PC.playing(), track = PC.state and PC.state.track, till = os.clock() + 1.6,
    position = PC.position(), at = os.clock() }
  PC.send("toggle")
end
function ctl.next() PC.send("next") end
function ctl.previous() PC.send("previous") end
function ctl.seekTo(seconds)
  seconds = math.max(0, seconds)
  PC.guess = { position = seconds, at = os.clock(), till = os.clock() + 1.6, track = PC.state and PC.state.track }
  PC.send("seek", seconds)
end
function ctl.seek(fraction)
  local length = ctl.length()
  if length > 0 then ctl.seekTo(math.clamp(fraction, 0, 0.999) * length) end
end
function ctl.canSeek() return PC.state ~= nil and PC.state.canSeek == true and (tonumber(PC.state.length) or 0) > 0 end
function ctl.volume()
  local v = PC.volumeGuess and os.clock() < PC.volumeGuess.till and PC.volumeGuess.value or (PC.state and tonumber(PC.state.volume))
  return (v and v >= 0) and v or nil
end
function ctl.setVolume(value, final)
  value = math.clamp(value, 0, 1)
  PC.volumeGuess = { value = value, till = os.clock() + 2 }
  -- (while dragging, ten a second at most)
  if final or os.clock() - volumeSent > 0.1 then
    volumeSent = os.clock()
    PC.send("volume", math.floor(value * 1000 + 0.5) / 1000)
  end
end
function ctl.shuffle() return PC.state ~= nil and PC.state.shuffle == true end
function ctl.setShuffle(on) PC.send("shuffle", on == true) end
function ctl.repeatMode() return PC.state and PC.state["repeat"] or "off" end
function ctl.setRepeat(mode) PC.send("repeat", mode) end
function ctl.cover(track, image, done)
  local id = track and track.coverFile and asset(track.coverFile) or nil
  image.Image = id or ""
  if done then done(id and track.coverFile or nil) end
end
function ctl.tint(track, done)
  if not track or not track.coverFile or Config.get("music.tint") == false then done(nil); return end
  local known = tints[track.coverFile]
  if known ~= nil then done(known or nil); return end
  task.spawn(function()
    local color = B.Cover and B.Cover.color(track.coverFile) or nil
    B.identity()
    tints[track.coverFile] = color or false
    B.try("pc.tint", done, color)
  end)
end
-- (Windows does not say how loud it is: the bars move with the playing)
function ctl.loudness()
  if not PC.playing() then return 0 end
  local t = os.clock()
  return 60 + 35 * math.abs(math.sin(t * 2.7)) * (0.6 + 0.4 * math.sin(t * 0.9 + 1))
end
function ctl.label(track) return ((track and track.app) or "An app") .. " on this PC" end
function ctl.queue() return nil end

-- ---------------------------------------------------------------- running
function PC.define()
  Config.define("music.pc", false)
end
function PC.start()
  if PC.started then return end
  PC.started = true
  -- (2026-11-11: while the helper is not answering, its file is looked for once a second, not six times: each look
  -- is a read from disk, up to a millisecond of a frame, and with the helper closed there is nothing to read. For the
  -- first 3 s after it is switched on it is looked for at the full pace, so a helper that is there is found at once)
  local ticks, onSince = 0, nil
  Motion.every(function()
    if Config.get("music.pc") ~= true then
      if PC.live then PC.live = false; PC.changed:fire("live") end
      onSince = nil
      return
    end
    local now = os.clock()
    onSince = onSince or now
    ticks += 1
    if not PC.live and now - onSince > 3 and ticks % 6 ~= 0 then return end
    B.try("pc.read", read)
  end, 6, "pc.read")
  -- the helper closes itself when this has not been written for 20 minutes
  Motion.every(function()
    if Config.get("music.pc") == true then fs.write(ALIVE, tostring(os.time())) end
  end, 0.2, "pc.alive")
  PC.changed:connect(function(what) if B.Music then B.Music.changed:fire(what == "live" and "state" or what) end end)
end
-- what the Music tab says about it
function PC.describe()
  if Config.get("music.pc") ~= true then return "Off. Set it up below to see and control what this PC plays." end
  local s = PC.state
  if not s then return "Waiting for the helper. Press Set up, then Win+R, paste, Enter." end
  if s.closed then return "The helper was closed. Press Set up to start it again." end
  if s.ok == false then return tostring(s.why or "The helper could not start.") end
  if not PC.live then return "The helper stopped answering. Press Set up to start it again." end
  if s.none then return "Connected. Nothing is playing on this PC." end
  return string.format("Connected: %s, %s.", tostring(s.app or "an app"), s.playing and "playing" or "paused")
end
end
do -- 49_card.lua
-- ============================================================================
--  49 card     the player on the screen while you play, and the island at the
--              top: the song, the colours of its cover, its words in time
--
--  The card (where the mini player was) plays what is in front
--  (Music.front): a song in the game, or what this PC is playing (48_pc).
--    full: the cover, the names, the line, the buttons, the volume, and the
--          words or the queue in the cover's place (the buttons at the bottom)
--    mini: the cover small, the names, the line, the buttons
--  A tap on the cover goes from one to the other. Drag it by any empty part.
--  The island: a pill at the top with the line being sung, word by word (in
--  the Novoline look its own island shows it, src/53).
--  Colours: the card takes the cover's colour, darkened; its line, bars and
--  the word being sung take it lightened (a grey cover: white).
-- ============================================================================
local Motion, UI, Config, Window = B.Motion, B.UI, B.Config, B.Window
local Music, Lyrics = B.Music, B.Lyrics
local Card = { mode = "full", view = "cover" }
B.Card = Card
local Island = {}
B.Island = Island

local WHITE = Color3.new(1, 1, 1)
local GREY = Color3.fromRGB(150, 150, 156)
local FAINT = Color3.fromRGB(112, 112, 118)
local FULL_W, FULL_H = 248, 456
local MINI_W, MINI_H = 288, 124
local GREY_HEX = "#8E8E93"

-- ---------------------------------------------------------------- small parts
local function frame(parent, props)
  local f = Instance.new("Frame")
  f.BorderSizePixel, f.BackgroundTransparency = 0, 1
  for key, value in pairs(props or {}) do f[key] = value end
  f.Parent = parent
  return f
end
local function round(f, radius)
  local c = Instance.new("UICorner")
  c.CornerRadius = radius == true and UDim.new(1, 0) or UDim.new(0, radius)
  c.Parent = f
  return c
end
local function text(parent, value, size, font, color, props)
  local l = Instance.new("TextLabel")
  l.BackgroundTransparency, l.BorderSizePixel = 1, 0
  l.FontFace = font
  l.TextSize = size
  l.TextColor3 = color or WHITE
  l.Text = value or ""
  l.TextXAlignment = Enum.TextXAlignment.Left
  l.TextYAlignment = Enum.TextYAlignment.Center
  l.TextTruncate = Enum.TextTruncate.AtEnd
  for key, v in pairs(props or {}) do l[key] = v end
  l.Parent = parent
  return l
end
local function glyph(parent, name, size, color, props)
  local image = Instance.new("ImageLabel")
  image.BackgroundTransparency, image.BorderSizePixel = 1, 0
  image.Size = UDim2.fromOffset(size, size)
  image.ScaleType = Enum.ScaleType.Fit
  image.ImageColor3 = color or WHITE
  UI.setIcon(image, name)
  for key, v in pairs(props or {}) do image[key] = v end
  image.Parent = parent
  return image
end
local function hit(parent, z, props)
  local button = Instance.new("TextButton")
  button.Name = "Hit"
  button.Text, button.AutoButtonColor, button.BackgroundTransparency, button.BorderSizePixel = "", false, 1, 0
  button.Size = UDim2.fromScale(1, 1)
  button.ZIndex = z
  for key, v in pairs(props or {}) do button[key] = v end
  button.Parent = parent
  return button
end
-- a bare glyph to press (no disc, as Apple's are): it dims under the mouse and gives on a press
local function press(parent, name, size, z, run, box)
  local holder = frame(parent, { Name = name, Size = UDim2.fromOffset(box or (size + 12), box or (size + 12)), AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = z })
  local image = glyph(holder, name, size, WHITE, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), ZIndex = z + 1 })
  local give = Instance.new("UIScale")
  give.Parent = image
  local button = hit(holder, z + 2)
  button.MouseEnter:Connect(function() image.ImageTransparency = 0.28 end)
  button.MouseLeave:Connect(function() image.ImageTransparency = 0; Motion.to(give, "Scale", 1, "bouncy") end)
  button.MouseButton1Down:Connect(function() Motion.to(give, "Scale", 0.84, "quick") end)
  button.MouseButton1Up:Connect(function() Motion.to(give, "Scale", 1, "bouncy") end)
  button.Activated:Connect(B.safe("card.button", function()
    UI.sfx("click", 0.4)
    run()
  end))
  return holder, image
end
-- how much the UIScales above a frame enlarge it (to turn its pixels back into offsets)
local function scaleOf(gui)
  local s, node = 1, gui
  while node and node:IsA("GuiObject") do
    local sizer = node:FindFirstChildOfClass("UIScale")
    if sizer then s *= sizer.Scale end
    node = node.Parent
  end
  return s > 0 and s or 1
end
-- a line to drag (the song's place, the volume), placed by its middle: thin, a little thicker while held
local function line(parent, props, z, onMove, onEnd)
  local bar = frame(parent, props)
  bar.ZIndex = z
  bar.AnchorPoint = Vector2.new(0, 0.5)
  bar.BackgroundColor3, bar.BackgroundTransparency = WHITE, 0.8
  round(bar, true)
  local fill = frame(bar, { Name = "Fill", Size = UDim2.fromScale(0, 1), BackgroundColor3 = WHITE, BackgroundTransparency = 0, ZIndex = z + 1 })
  round(fill, true)
  local button = hit(bar, z + 3, { Size = UDim2.new(1, 8, 0, 18), Position = UDim2.new(0, -4, 0.5, -9) })
  local api = { frame = bar, fill = fill, dragging = nil, height = props.Size.Y.Offset }
  local function at(point) return math.clamp((point.X - bar.AbsolutePosition.X) / math.max(bar.AbsoluteSize.X, 1), 0, 1) end
  local function thick(on)
    local h = on and api.height + 3 or api.height
    Motion.to(bar, "Size", UDim2.new(bar.Size.X.Scale, bar.Size.X.Offset, 0, h), "snappy")
  end
  button.MouseEnter:Connect(function() thick(true) end)
  button.MouseLeave:Connect(function() if not api.dragging then thick(false) end end)
  UI.drag(button, function(point)
    api.dragging = at(point)
    thick(true)
    if onMove then onMove(api.dragging) end
  end, function(point)
    api.dragging = at(point)
    if onMove then onMove(api.dragging) end
  end, function()
    local value = api.dragging
    api.dragging = nil
    thick(false)
    if value and onEnd then onEnd(value) end
  end)
  function api.set(f) fill.Size = UDim2.fromScale(math.clamp(f, 0, 1), 1) end
  return api
end
-- a name that slides when it is longer than its box (as the music tab's does)
local function marquee(parent, font, size, z)
  local holder = frame(parent, { Name = "Marquee", ClipsDescendants = true, ZIndex = z })
  local label = text(holder, "", size, font, WHITE, { Size = UDim2.new(0, 0, 1, 0), AutomaticSize = Enum.AutomaticSize.X,
    TextTruncate = Enum.TextTruncate.None, ZIndex = z })
  local api = { holder = holder, label = label, t = 0 }
  function api.set(value)
    value = tostring(value or "")
    if label.Text ~= value then label.Text = value; api.t = 0; label.Position = UDim2.new() end
  end
  function api.step(dt)
    local width = holder.AbsoluteSize.X
    local over = label.AbsoluteSize.X - width
    if over <= 1 or width <= 0 then
      if label.Position.X.Scale ~= 0 then label.Position = UDim2.new() end
      api.t = 0
      return
    end
    local glide, back, rest = over / 38, over / 90, 1.6
    api.t = (api.t + dt) % (rest * 2 + glide + back)
    local t, p = api.t, 0
    if t < rest then p = 0
    elseif t < rest + glide then p = (t - rest) / glide
    elseif t < rest * 2 + glide then p = 1
    else p = 1 - (t - rest * 2 - glide) / back end
    p = p * p * (3 - 2 * p)
    label.Position = UDim2.new(-(over / width) * p, 0, 0, 0)
  end
  return api
end

-- ---------------------------------------------------------------- the colours of a cover
-- back: the card, darkened; low: its bottom; accent: the line, the bars, the word being sung
local function palette(color)
  if not color then return nil end
  local h, s = color:ToHSV()
  if s < 0.14 then
    return { back = Color3.fromHSV(0, 0, 0.14), low = Color3.fromHSV(0, 0, 0.07), accent = WHITE, vivid = false }
  end
  return { back = Color3.fromHSV(h, math.min(s * 0.75, 0.62), 0.22), low = Color3.fromHSV(h, math.min(s * 0.85, 0.7), 0.1),
    accent = Color3.fromHSV(h, math.clamp(s * 0.8, 0.32, 0.68), 1), vivid = true }
end
Card.palette = palette
local palettes = {}
-- the palette of a track (nil while it is read, or with the cover colour off)
function Card.paletteOf(ctl, track, done)
  if not track then done(nil); return end
  local known = palettes[track.key]
  if known ~= nil then done(known or nil); return end
  ctl.tint(track, function(color)
    palettes[track.key] = palette(color) or false
    done(palettes[track.key] or nil)
  end)
end
-- the colour of the word being sung: the cover's when it has one, the look's own for a grey cover
function Card.wordColor(fallback)
  return (Card.vivid and Card.accent and Config.get("music.tint") ~= false) and Card.accent or fallback
end
local function kitAccent(kit)
  local ok, color = pcall(kit.color, "accent")
  return (ok and typeof(color) == "Color3") and color or Color3.fromRGB(255, 59, 78)
end

-- ---------------------------------------------------------------- the words, scrolling (the card, the music tab)
-- opts: font, size, z, dim (Color3 of the lines not sung now), colors() -> { sung, now, next } (hex)
function Card.lyricList(parent, opts)
  local z = opts.z or 2
  local area = frame(parent, { Name = "Lyrics", Size = UDim2.fromScale(1, 1), ClipsDescendants = true, ZIndex = z })
  local column = frame(area, { Name = "Lines", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, ZIndex = z })
  local layout = Instance.new("UIListLayout")
  layout.Padding, layout.SortOrder = UDim.new(0, opts.gap or 10), Enum.SortOrder.LayoutOrder
  layout.Parent = column
  local note = text(area, "", (opts.size or 15) - 2, opts.font, opts.dim or GREY, { Size = UDim2.fromScale(1, 1), TextWrapped = true,
    TextXAlignment = Enum.TextXAlignment.Center, TextTruncate = Enum.TextTruncate.None, ZIndex = z, Visible = false })
  local api = { area = area, labels = {}, current = -1, word = -1, entry = nil, state = nil, ctl = nil }
  local dim = opts.dim or GREY
  local function plainText(lineInfo)
    return lineInfo.text == "" and "\u{2022}  \u{2022}  \u{2022}" or Lyrics.escape(lineInfo.text)
  end
  local function clear()
    for _, child in ipairs(column:GetChildren()) do if child:IsA("GuiObject") then child:Destroy() end end
    table.clear(api.labels)
    column.Position = UDim2.new()
  end
  local function rebuild(entry)
    clear()
    if entry.loose then
      text(column, "Another length of this song: the words, without their times.", (opts.size or 15) - 4, opts.font, dim, { Name = "Note",
        Size = UDim2.new(1, -6, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, TextWrapped = true, TextTruncate = Enum.TextTruncate.None, LayoutOrder = 0, ZIndex = z + 1 })
    end
    for i, lineInfo in ipairs(entry.lines) do
      local button = Instance.new("TextButton")
      button.Name = "Line"
      button.AutoButtonColor, button.BackgroundTransparency, button.BorderSizePixel = false, 1, 0
      button.RichText, button.TextWrapped = true, true
      button.FontFace, button.TextSize = opts.font, opts.size or 15
      button.TextXAlignment, button.TextYAlignment = Enum.TextXAlignment.Left, Enum.TextYAlignment.Top
      button.TextColor3, button.TextTransparency = dim, 0.35
      button.Text = plainText(lineInfo)
      button.Size = UDim2.new(1, -6, 0, 0)
      button.AutomaticSize = Enum.AutomaticSize.Y
      button.LayoutOrder, button.ZIndex = i, z + 1
      button.Parent = column
      -- (a line with a time: a click goes to it)
      button.Activated:Connect(B.safe("lyrics.line", function()
        local ctl = api.ctl
        if entry.timed and ctl then ctl.seekTo(math.max(lineInfo.t - Lyrics.shiftOf(ctl.track()) + 0.02, 0)) end
      end))
      api.labels[i] = button
    end
  end
  function api.repaint() api.word = -1 end
  -- the line being sung, a third of the way down: once the lines have a size (a list built this frame has not)
  local function scrollTo(target)
    if not target then
      Motion.to(column, "Position", UDim2.new(), "gentle")
      return true
    end
    if target.AbsoluteSize.Y <= 0 then return false end
    local s = scaleOf(area)
    local y = (target.AbsolutePosition.Y - column.AbsolutePosition.Y) / s
    local view = area.AbsoluteSize.Y / s
    Motion.to(column, "Position", UDim2.fromOffset(0, math.floor(view * 0.3 - y)), "gentle")
    return true
  end
  function api.step(_, ctl)
    api.ctl = ctl
    local track = ctl and ctl.track()
    local entry = track and Lyrics.forTrack(track, ctl.length()) or nil
    local state = entry and entry.state
    if entry ~= api.entry or state ~= api.state then
      api.entry, api.state = entry, state
      api.current, api.word = -1, -1
      if entry and state == "ready" and #entry.lines > 0 then
        rebuild(entry)
        note.Visible = false
      else
        clear()
        note.Text = (not track and "Nothing playing") or Lyrics.note(entry) or ""
        note.Visible = true
      end
    end
    if not (entry and state == "ready" and entry.timed) then return end
    local t = Lyrics.clock(ctl.position(), track)
    local i, w = Lyrics.at(entry.lines, t)
    if i ~= api.current then
      local old = api.labels[api.current]
      if old then
        old.Text = plainText(entry.lines[api.current])
        old.TextColor3, old.TextTransparency = dim, 0.35
      end
      api.current, api.word = i, -1
      local target = api.labels[i]
      if target then target.TextColor3, target.TextTransparency = WHITE, 0 end
      -- (before the first line, after a seek back to the start: the top)
      api.scrollFor = i
    end
    if api.scrollFor ~= nil then
      local target = api.scrollFor > 0 and api.labels[api.scrollFor] or nil
      if scrollTo(target) then api.scrollFor = nil end
    end
    if i > 0 and w ~= api.word then
      api.word = w
      local target = api.labels[i]
      if target then target.Text = Lyrics.markup(entry.lines[i], w, opts.colors()) end
    end
  end
  return api
end

-- ---------------------------------------------------------------- the island's row: cover, bars, the line
-- (also drawn inside the Novoline look's own island). opts: font, size, z, accent() -> Color3
function Island.row(parent, opts)
  local z = opts.z or 22
  local row = frame(parent, { Name = "LyricRow", Size = UDim2.fromScale(1, 1), ZIndex = z })
  local art = Instance.new("ImageLabel")
  art.Name = "Cover"
  art.BackgroundColor3, art.BorderSizePixel = Color3.fromRGB(40, 40, 46), 0
  art.AnchorPoint, art.Position, art.Size = Vector2.new(0, 0.5), UDim2.new(0, 5, 0.5, 0), UDim2.fromOffset(28, 28)
  art.ScaleType, art.ZIndex = Enum.ScaleType.Crop, z + 1
  art.Parent = row
  round(art, true)
  local bars = {}
  for i = 1, 4 do
    local bar = frame(row, { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 41 + (i - 1) * 5, 0.5, 0), Size = UDim2.fromOffset(3, 4),
      BackgroundColor3 = WHITE, BackgroundTransparency = 0, ZIndex = z + 1 })
    round(bar, true)
    bars[i] = bar
  end
  local clip = frame(row, { Name = "Words", Position = UDim2.fromOffset(66, 0), Size = UDim2.new(1, -78, 1, 0), ClipsDescendants = true, ZIndex = z + 1 })
  local function newLabel()
    return text(clip, "", opts.size or 14, opts.font, WHITE, { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0),
      Size = UDim2.fromOffset(0, 20), AutomaticSize = Enum.AutomaticSize.X, RichText = true, TextTruncate = Enum.TextTruncate.None, ZIndex = z + 2 })
  end
  local a, b = newLabel(), newLabel()
  b.TextTransparency = 1
  local api = { frame = row, showing = a, key = nil, markup = nil }
  local coverKey, level, peak, spin = nil, 0, 4, 0
  local lastLine, lastWord = -1, -1
  function api.step(dt, ctl)
    local track = ctl.track()
    if not track then return 220, false end
    if track.key ~= coverKey then
      coverKey = track.key
      ctl.cover(track, art)
      lastLine, lastWord = -1, -1
    end
    local accent = opts.accent and opts.accent() or WHITE
    local playing = ctl.state() == "playing"
    if playing then spin = (spin + dt * 40) % 360 end
    art.Rotation = spin
    -- the words: the line being sung, or the song's name between lines
    local entry = Lyrics.forTrack(track, ctl.length())
    local key, markup
    if entry and entry.state == "ready" and entry.timed then
      local t = Lyrics.clock(ctl.position(), track)
      local i, w = Lyrics.at(entry.lines, t)
      if i > 0 and Lyrics.live(entry.lines, i, t) then
        key = "line" .. i
        if i ~= lastLine or w ~= lastWord or api.key ~= key then
          lastLine, lastWord = i, w
          markup = Lyrics.markup(entry.lines[i], w, { sung = "#FFFFFF", now = Lyrics.hex(accent), next = GREY_HEX })
        end
      end
    end
    local isLine = key ~= nil
    if not key then
      key = "name " .. track.key
      if api.key ~= key then
        markup = Lyrics.escape(track.title) .. string.format('<font color="%s">  \u{00B7}  %s</font>', GREY_HEX, Lyrics.escape(track.artist))
      end
    end
    if key ~= api.key then
      -- the old line rises away, the new one comes up from below
      local old, new = api.showing, (api.showing == a and b or a)
      api.key, api.showing = key, new
      new.Text = markup or ""
      if Motion.reduced then
        new.Position, new.TextTransparency = UDim2.new(0, 0, 0.5, 0), 0
        old.TextTransparency = 1
      else
        new.Position, new.TextTransparency = UDim2.new(0, 0, 0.5, 13), 1
        Motion.to(new, "Position", UDim2.new(0, 0, 0.5, 0), "smooth")
        Motion.to(new, "TextTransparency", 0, "smooth")
        Motion.to(old, "Position", UDim2.new(0, 0, 0.5, -13), "smooth")
        Motion.to(old, "TextTransparency", 1, "quick")
      end
    elseif markup then
      api.showing.Text = markup
    end
    -- the bars: against the loudest lately, so they move at any volume
    local raw = playing and ctl.loudness() or 0
    peak = math.max(peak * (1 - math.min(dt * 0.35, 1)), raw, 4)
    local loud = playing and math.clamp(raw / peak * 1.05, 0, 1.15) or 0
    level += (loud - level) * math.min(dt * 12, 1)
    local now = os.clock()
    for i, bar in ipairs(bars) do
      local wobble = 0.4 + 0.6 * math.abs(math.sin(now * (3.3 + i * 1.1) + i * 1.9))
      bar.Size = UDim2.fromOffset(3, math.clamp(4 + level * 14 * wobble, 4, 18))
      bar.BackgroundColor3 = accent
    end
    local width = api.showing.AbsoluteSize.X / scaleOf(clip)
    return math.clamp(66 + width + 16, 200, 560), isLine
  end
  return api
end

-- ---------------------------------------------------------------- the island (the BASED and Unnamed looks)
function Island.start()
  if Island.pill or not Window.hud then return end
  local pill = frame(Window.hud, { Name = "MusicIsland", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 10),
    Size = UDim2.fromOffset(38, 38), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.04, Visible = false, ZIndex = 20,
    ClipsDescendants = true })
  round(pill, true)
  local rim = Instance.new("UIStroke")
  rim.Color, rim.Transparency, rim.Thickness = WHITE, 0.9, 1
  rim.Parent = pill
  local sizer = Instance.new("UIScale")
  sizer.Parent = pill
  Island.pill = pill
  local row, rowLook
  local width, shown = 38, false
  local function build()
    if row then row.frame:Destroy() end
    local kit = Window.activeKit()
    rowLook = kit.look
    row = Island.row(pill, { font = kit.font(true), size = 14, z = 21, accent = function() return Card.wordColor(kitAccent(kit)) end })
    local corner = pill:FindFirstChildOfClass("UICorner")
    if corner then corner.CornerRadius = kit.look == "unnamed" and UDim.new(0, 0) or UDim.new(1, 0) end
  end
  build()
  hit(pill, 30).Activated:Connect(B.safe("music.island", function() Music.openTab() end))
  Motion.every(function(dt)
    local ctl = Music.front()
    local track = ctl.track()
    local show = Window.look() ~= "novoline" and Config.get("music.island") ~= false and track ~= nil and ctl.state() ~= "idle" and not Window.anyOpen()
    if show ~= shown then
      shown = show
      pill.Visible = show
      if show then
        -- (it opens out from a dot)
        width = 38
        pill.Size = UDim2.fromOffset(38, 38)
      end
    end
    if not show then return end
    if rowLook ~= Window.activeKit().look then build() end
    sizer.Scale = Window.scale or 1
    local want = row.step(dt, ctl)
    if math.abs(want - width) > 1 then
      width = want
      Motion.to(pill, "Size", UDim2.fromOffset(want, 38), "smooth")
    end
  end, nil, "music.island")
end

-- ---------------------------------------------------------------- the card
local function layoutFor(mode, view)
  if mode == "mini" then
    return { w = MINI_W, h = MINI_H, cover = { 12, 12, 46 }, title = { 68, 12, MINI_W - 68 - 44, 18 }, titleSize = 13,
      artist = { 68, 32, MINI_W - 68 - 44, 15 }, artistSize = 11, heart = { FULL_W - 46, 254 }, more = { FULL_W - 22, 254 } }
  end
  if view == "cover" then
    return { w = FULL_W, h = FULL_H, cover = { 14, 14, FULL_W - 28 }, title = { 14, 242, FULL_W - 28 - 58, 20 }, titleSize = 15,
      artist = { 14, 263, FULL_W - 28 - 58, 16 }, artistSize = 12, heart = { FULL_W - 46, 253 }, more = { FULL_W - 22, 253 } }
  end
  return { w = FULL_W, h = FULL_H, cover = { 14, 14, 48 }, title = { 72, 15, FULL_W - 72 - 62, 20 }, titleSize = 14,
    artist = { 72, 36, FULL_W - 72 - 62, 16 }, artistSize = 12, heart = { FULL_W - 46, 38 }, more = { FULL_W - 22, 38 } }
end

local parts
local function setText(label, value) if label.Text ~= value then label.Text = value end end
local function timeOf(seconds) return Music.time(seconds) end

-- go to the size and view asked for (instant: no motion, for the first build)
function Card.apply(instant)
  if not parts then return end
  local L = layoutFor(Card.mode, Card.view)
  local function move(instance, property, value)
    if instant or Motion.reduced then Motion.snap(instance, property, value) else Motion.to(instance, property, value, "smooth") end
  end
  move(Card.holder, "Size", UDim2.fromOffset(L.w, L.h))
  move(parts.cover, "Position", UDim2.fromOffset(L.cover[1], L.cover[2]))
  move(parts.cover, "Size", UDim2.fromOffset(L.cover[3], L.cover[3]))
  parts.coverCorner.CornerRadius = UDim.new(0, (parts.square and 0) or (L.cover[3] > 100 and 12 or 8))
  move(parts.title.holder, "Position", UDim2.fromOffset(L.title[1], L.title[2]))
  move(parts.title.holder, "Size", UDim2.fromOffset(L.title[3], L.title[4]))
  parts.title.label.TextSize = L.titleSize
  move(parts.artist, "Position", UDim2.fromOffset(L.artist[1], L.artist[2]))
  move(parts.artist, "Size", UDim2.fromOffset(L.artist[3], L.artist[4]))
  parts.artist.TextSize = L.artistSize
  move(parts.heart, "Position", UDim2.fromOffset(L.heart[1], L.heart[2]))
  move(parts.more, "Position", UDim2.fromOffset(L.more[1], L.more[2]))
  local full, list = Card.mode == "full", Card.mode == "full" and Card.view ~= "cover"
  local function show(group, on)
    if instant then UI.setFade(group, on and 1 or 0) else UI.fade(group, on and 1 or 0, "smooth") end
  end
  show(parts.full, full)
  show(parts.mini, not full)
  show(parts.list, list)
  parts.lyrics.area.Visible = Card.view == "lyrics"
  parts.queue.Visible = Card.view == "queue"
  parts.paintButtons()
end
function Card.setMode(mode, view)
  Card.mode = mode
  if view then Card.view = view end
  Config.set("music.cardMode", Card.mode)
  Config.set("music.cardView", Card.view)
  Card.apply(false)
end
-- the cover: mini -> full; the words or the queue -> the cover; the cover -> mini
function Card.tapCover()
  if Card.mode == "mini" then Card.setMode("full", "cover")
  elseif Card.view ~= "cover" then Card.setMode("full", "cover")
  else Card.setMode("mini") end
end
function Card.toggleMode()
  Card.setMode(Card.mode == "mini" and "full" or "mini")
end

-- the next songs of the game's queue, in the card
local function fillQueue(list)
  for _, child in ipairs(list:GetChildren()) do if child:IsA("GuiObject") then child:Destroy() end end
  local ctl = Music.front()
  local upcoming = ctl.queue and ctl.queue() or nil
  local font = parts.font
  if not upcoming or #upcoming == 0 then
    text(list, upcoming and "Nothing next. Add songs with + in the Music tab." or "The queue is the app's own on this PC.", 12, font, GREY,
      { Size = UDim2.new(1, 0, 0, 40), TextWrapped = true, TextTruncate = Enum.TextTruncate.None, ZIndex = 9 })
    return
  end
  for order, item in ipairs(upcoming) do
    local row = Instance.new("TextButton")
    row.Name = "Next"
    row.AutoButtonColor, row.BackgroundColor3, row.BackgroundTransparency, row.BorderSizePixel = false, WHITE, 1, 0
    row.Text, row.Size, row.LayoutOrder, row.ZIndex = "", UDim2.new(1, 0, 0, 34), order, 9
    row.Parent = list
    round(row, 8)
    text(row, item.track.title, 12, parts.bold, WHITE, { Position = UDim2.fromOffset(8, 2), Size = UDim2.new(1, -16, 0, 16), ZIndex = 10 })
    text(row, item.track.artist, 11, font, GREY, { Position = UDim2.fromOffset(8, 17), Size = UDim2.new(1, -16, 0, 14), ZIndex = 10 })
    row.MouseEnter:Connect(function() row.BackgroundTransparency = 0.92 end)
    row.MouseLeave:Connect(function() row.BackgroundTransparency = 1 end)
    row.Activated:Connect(B.safe("card.queue", function()
      Music.index = item.index
      Music.play(item.track, true)
    end))
  end
end

local function build()
  local holder = Card.holder
  for _, child in ipairs(holder:GetChildren()) do
    if child:IsA("GuiObject") then child:Destroy() end
  end
  local kit = Window.activeKit()
  local square = kit.look == "unnamed"
  local bold, regular = kit.font(true), kit.font(false)
  parts = { kit = kit, square = square, font = regular, bold = bold, look = kit.look }
  -- the card: the cover's colour, darker toward the bottom
  local back = frame(holder, { Name = "Back", Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.fromRGB(24, 24, 28), BackgroundTransparency = 0.03, ZIndex = 1 })
  if not square then round(back, 18) end
  local shade = Instance.new("UIGradient")
  shade.Rotation = 90
  shade.Color = ColorSequence.new(WHITE, Color3.fromRGB(120, 120, 120))
  shade.Parent = back
  local rim = Instance.new("UIStroke")
  rim.Color, rim.Transparency, rim.Thickness = WHITE, square and 0.7 or 0.9, 1
  rim.Parent = back
  pcall(function()
    local shadow = Instance.new("UIShadow")
    shadow.Color, shadow.BlurRadius, shadow.Offset, shadow.Transparency = Color3.new(0, 0, 0), UDim.new(0, 26), UDim2.fromOffset(0, 10), 0.45
    shadow.Parent = back
  end)
  parts.back = back
  -- drag it by anything that is not a button
  local grab = hit(holder, 2, { Name = "Grab" })
  local from
  UI.drag(grab, function(point)
    from = point - holder.AbsolutePosition
  end, function(point)
    local layer = Window.hud.AbsoluteSize
    if layer.X <= 0 or layer.Y <= 0 then return end
    local topLeft = point - from - Window.hud.AbsolutePosition
    local bottom = topLeft.Y + holder.AbsoluteSize.Y
    Card.at = Vector2.new(math.clamp(topLeft.X / layer.X, 0, 1), math.clamp(bottom / layer.Y, 0, 1))
    Card.seat()
  end, function()
    if Card.at then
      Config.set("music.cardX", Card.at.X)
      Config.set("music.cardY", Card.at.Y)
    end
  end)
  -- the cover (tap: big or small)
  local cover = Instance.new("ImageLabel")
  cover.Name = "Cover"
  cover.BackgroundColor3, cover.BorderSizePixel = Color3.fromRGB(44, 44, 50), 0
  cover.ScaleType, cover.ZIndex = Enum.ScaleType.Crop, 6
  cover.Parent = holder
  parts.coverCorner = round(cover, 12)
  local placeholder = glyph(cover, "music", 28, FAINT, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), ZIndex = 7 })
  cover:GetPropertyChangedSignal("Image"):Connect(function() placeholder.Visible = cover.Image == "" end)
  local coverHit = hit(cover, 8, { Name = "Tap" })
  coverHit.Activated:Connect(B.safe("card.cover", function() UI.sfx("click", 0.35); Card.tapCover() end))
  parts.cover = cover
  parts.title = marquee(holder, bold, 15, 6)
  parts.artist = text(holder, "", 12, regular, GREY, { Name = "Artist", ZIndex = 6 })

  -- the full card's own parts
  local full = UI.group(holder, { Name = "Full", Size = UDim2.fromOffset(FULL_W, FULL_H), ZIndex = 4 })
  parts.full = full
  local heart, heartIcon = press(full, "heart", 18, 10, function()
    local track = Music.front().track()
    if track then Music.like(track, not Music.liked(track)) end
  end)
  parts.heart, parts.heartIcon = heart, heartIcon
  parts.more = press(full, "ellipsis", 18, 10, function() Music.openTab() end)
  local seekLine = line(full, { Position = UDim2.fromOffset(14, 298), Size = UDim2.fromOffset(FULL_W - 28, 4) }, 10, nil, function(f)
    local ctl = Music.front()
    if ctl.canSeek() then ctl.seek(f) end
  end)
  parts.seekLine = seekLine
  parts.at = text(full, "0:00", 10, regular, FAINT, { Position = UDim2.fromOffset(14, 306), Size = UDim2.fromOffset(70, 12), ZIndex = 10 })
  parts.left = text(full, "-0:00", 10, regular, FAINT, { Position = UDim2.fromOffset(FULL_W - 84, 306), Size = UDim2.fromOffset(70, 12),
    TextXAlignment = Enum.TextXAlignment.Right, ZIndex = 10 })
  local prev = press(full, "skip-back", 22, 10, function() Music.front().previous() end, 40)
  prev.Position = UDim2.fromOffset(FULL_W / 2 - 64, 352)
  local play, playIcon = press(full, "play", 30, 10, function() Music.front().toggle() end, 48)
  play.Position = UDim2.fromOffset(FULL_W / 2, 352)
  local nxt = press(full, "skip-forward", 22, 10, function() Music.front().next() end, 40)
  nxt.Position = UDim2.fromOffset(FULL_W / 2 + 64, 352)
  parts.playIcon = playIcon
  -- the volume: the game's music, or the app on this PC (the volume mixer)
  local quiet = glyph(full, "volume-x", 12, FAINT, { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.fromOffset(14, 400), ZIndex = 10 })
  parts.quiet = quiet
  local volumeLine = line(full, { Position = UDim2.fromOffset(34, 400), Size = UDim2.fromOffset(FULL_W - 68, 4) }, 10, function(f)
    local ctl = Music.front()
    if ctl.setVolume then ctl.setVolume(f, false) end
  end, function(f)
    local ctl = Music.front()
    if ctl.setVolume then ctl.setVolume(f, true) end
  end)
  parts.volumeLine = volumeLine
  parts.loud = glyph(full, "volume-2", 14, FAINT, { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.fromOffset(FULL_W - 14, 400), ZIndex = 10 })
  -- the bottom: words, where it plays, the queue
  local words, wordsIcon = press(full, "message-circle", 16, 10, function()
    Card.setMode("full", Card.view == "lyrics" and "cover" or "lyrics")
  end, 30)
  words.Position = UDim2.fromOffset(28, 434)
  parts.wordsIcon = wordsIcon
  local queue, queueIcon = press(full, "list", 16, 10, function()
    Card.setMode("full", Card.view == "queue" and "cover" or "queue")
  end, 30)
  queue.Position = UDim2.fromOffset(FULL_W - 28, 434)
  parts.queueIcon = queueIcon
  local where = frame(full, { Name = "Where", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(FULL_W / 2, 434), Size = UDim2.fromOffset(150, 16), ZIndex = 10 })
  parts.whereIcon = glyph(where, "music", 11, FAINT, { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), ZIndex = 11 })
  parts.where = text(where, "", 10, regular, FAINT, { Position = UDim2.fromOffset(15, 0), Size = UDim2.new(1, -15, 1, 0), ZIndex = 11 })
  parts.whereBox = where

  -- the words or the queue, where the cover was
  local list = UI.group(holder, { Name = "List", Position = UDim2.fromOffset(14, 72), Size = UDim2.fromOffset(FULL_W - 28, 212), ZIndex = 5 })
  parts.list = list
  parts.lyrics = Card.lyricList(list, { font = bold, size = 15, z = 6, dim = GREY, colors = function()
    return { sung = "#FFFFFF", now = Lyrics.hex(Card.wordColor(kitAccent(kit))), next = GREY_HEX }
  end })
  local queueList = Instance.new("ScrollingFrame")
  queueList.Name = "Queue"
  queueList.BackgroundTransparency, queueList.BorderSizePixel = 1, 0
  queueList.Size = UDim2.fromScale(1, 1)
  queueList.AutomaticCanvasSize, queueList.CanvasSize = Enum.AutomaticSize.Y, UDim2.new()
  queueList.ScrollBarThickness, queueList.ScrollBarImageColor3 = 2, WHITE
  queueList.ZIndex = 8
  queueList.Parent = list
  local queueLayout = Instance.new("UIListLayout")
  queueLayout.Padding, queueLayout.SortOrder = UDim.new(0, 2), Enum.SortOrder.LayoutOrder
  queueLayout.Parent = queueList
  parts.queue = queueList

  -- the mini card's own parts
  local mini = UI.group(holder, { Name = "Mini", Size = UDim2.fromOffset(MINI_W, MINI_H), ZIndex = 4 })
  parts.mini = mini
  local bars = {}
  for i = 1, 4 do
    local bar = frame(mini, { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.fromOffset(MINI_W - 34 + (i - 1) * 5, 22), Size = UDim2.fromOffset(3, 4),
      BackgroundColor3 = WHITE, BackgroundTransparency = 0, ZIndex = 10 })
    round(bar, true)
    bars[i] = bar
  end
  parts.bars = bars
  local miniLine = line(mini, { Position = UDim2.fromOffset(12, 70), Size = UDim2.fromOffset(MINI_W - 24, 3) }, 10, nil, function(f)
    local ctl = Music.front()
    if ctl.canSeek() then ctl.seek(f) end
  end)
  parts.miniLine = miniLine
  parts.miniAt = text(mini, "0:00", 9, regular, FAINT, { Position = UDim2.fromOffset(12, 76), Size = UDim2.fromOffset(60, 11), ZIndex = 10 })
  parts.miniLeft = text(mini, "-0:00", 9, regular, FAINT, { Position = UDim2.fromOffset(MINI_W - 72, 76), Size = UDim2.fromOffset(60, 11),
    TextXAlignment = Enum.TextXAlignment.Right, ZIndex = 10 })
  local miniHeart, miniHeartIcon = press(mini, "heart", 15, 10, function()
    local track = Music.front().track()
    if track then Music.like(track, not Music.liked(track)) end
  end, 28)
  miniHeart.Position = UDim2.fromOffset(26, 104)
  parts.miniHeartIcon = miniHeartIcon
  local miniPrev = press(mini, "skip-back", 17, 10, function() Music.front().previous() end, 32)
  miniPrev.Position = UDim2.fromOffset(MINI_W / 2 - 46, 104)
  local miniPlay, miniPlayIcon = press(mini, "play", 22, 10, function() Music.front().toggle() end, 36)
  miniPlay.Position = UDim2.fromOffset(MINI_W / 2, 104)
  parts.miniPlayIcon = miniPlayIcon
  local miniNext = press(mini, "skip-forward", 17, 10, function() Music.front().next() end, 32)
  miniNext.Position = UDim2.fromOffset(MINI_W / 2 + 46, 104)
  local grow = press(mini, "maximize-2", 14, 10, function() Card.setMode("full", "cover") end, 28)
  grow.Position = UDim2.fromOffset(MINI_W - 26, 104)

  -- colours, names, the buttons that show a state
  function parts.paintButtons()
    local ctl = Music.front()
    local accent = Card.accent or kitAccent(kit)
    wordsIcon.ImageColor3 = Card.view == "lyrics" and accent or FAINT
    queueIcon.ImageColor3 = Card.view == "queue" and accent or FAINT
    queue.Visible = ctl.kind ~= "pc"
  end
  Card.coverKey = nil
  Card.apply(true)
end

-- the colours and names of what is in front (on a change of song or state)
local function paint()
  if not parts then return end
  local ctl = Music.front()
  local track = ctl.track()
  parts.title.set(track and track.title or "Nothing playing")
  setText(parts.artist, track and (ctl.status() or track.artist) or "")
  local playing = ctl.state() == "playing"
  UI.setIcon(parts.playIcon, playing and "pause" or "play")
  UI.setIcon(parts.miniPlayIcon, playing and "pause" or "play")
  local liked = track ~= nil and Music.liked(track)
  local accent = Card.accent or kitAccent(parts.kit)
  parts.heartIcon.ImageColor3 = liked and accent or WHITE
  parts.miniHeartIcon.ImageColor3 = liked and accent or WHITE
  UI.setIcon(parts.whereIcon, ctl.kind == "pc" and "monitor" or "music")
  setText(parts.where, track and ctl.label(track) or "")
  local key = track and track.key or nil
  if key ~= Card.coverKey then
    Card.coverKey = key
    if track then
      ctl.cover(track, parts.cover)
      Card.paletteOf(ctl, track, function(pal)
        if not parts or Card.coverKey ~= key then return end
        Card.accent = pal and pal.accent or nil
        Card.vivid = pal ~= nil and pal.vivid == true
        local back = pal and pal.back or Color3.fromRGB(24, 24, 28)
        Motion.to(parts.back, "BackgroundColor3", back, "gentle")
        local fill = Card.accent or WHITE
        for _, bar in ipairs({ parts.seekLine.fill, parts.miniLine.fill }) do bar.BackgroundColor3 = fill end
        parts.lyrics.repaint()
        parts.paintButtons()
        paint()
      end)
    else
      parts.cover.Image = ""
    end
  end
  parts.paintButtons()
  if Card.view == "queue" then fillQueue(parts.queue) end
end
Card.paint = paint

-- ---------------------------------------------------------------- the wide card (Novoline's Home): every cover, every colour
-- The cover with its record, the names, the line, the buttons; under them Shuffle, Library and
-- Playlists. The whole card takes the cover's colour; the line and the tiles' icons its light one.
local WIDE_W, WIDE_H = 420, 260
function Card.viewWide(holder, shown)
  local kit = Window.kit(holder)
  local L = Music.life(holder)
  shown = shown or function() return true end
  local bold, regular = kit.font(true), kit.font(false)
  local tint = frame(holder, { Name = "Tint", Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.fromRGB(30, 30, 36), BackgroundTransparency = 1, ZIndex = 21 })
  round(tint, 28)
  local shade = Instance.new("UIGradient")
  shade.Rotation = 35
  shade.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.15), NumberSequenceKeypoint.new(1, 0.6) })
  shade.Parent = tint
  -- the record, out of its sleeve while it plays
  local disc = frame(holder, { Name = "Record", AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(138, 138), Position = UDim2.fromOffset(18 + 75, 18 + 75),
    BackgroundColor3 = Color3.fromRGB(12, 12, 14), BackgroundTransparency = 0, ZIndex = 22 })
  round(disc, true)
  for _, s in ipairs({ 0.94, 0.82, 0.7, 0.58 }) do
    local groove = frame(disc, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(s, s), ZIndex = 22 })
    round(groove, true)
    local ring = Instance.new("UIStroke")
    ring.Color, ring.Transparency, ring.Thickness = Color3.fromRGB(46, 46, 52), 0.4, 1
    ring.Parent = groove
  end
  local cover = Instance.new("ImageLabel")
  cover.Name = "Cover"
  cover.BackgroundColor3, cover.BorderSizePixel = Color3.fromRGB(44, 44, 50), 0
  cover.Position, cover.Size = UDim2.fromOffset(18, 18), UDim2.fromOffset(150, 150)
  cover.ScaleType, cover.ZIndex = Enum.ScaleType.Crop, 23
  cover.Parent = holder
  round(cover, 14)
  local placeholder = glyph(cover, "music", 34, FAINT, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), ZIndex = 24 })
  cover:GetPropertyChangedSignal("Image"):Connect(function() placeholder.Visible = cover.Image == "" end)
  -- the names, the line, the buttons
  local x = 236
  local title = marquee(holder, bold, 17, 23)
  title.holder.Position, title.holder.Size = UDim2.fromOffset(x, 22), UDim2.fromOffset(WIDE_W - x - 18, 22)
  local artist = text(holder, "", 13, regular, GREY, { Position = UDim2.fromOffset(x, 46), Size = UDim2.fromOffset(WIDE_W - x - 18, 18), ZIndex = 23 })
  local seek = line(holder, { Position = UDim2.fromOffset(x, 88), Size = UDim2.fromOffset(WIDE_W - x - 18, 4) }, 23, nil, function(f)
    local ctl = Music.front()
    if ctl.canSeek() then ctl.seek(f) end
  end)
  local at = text(holder, "0:00", 10, regular, FAINT, { Position = UDim2.fromOffset(x, 97), Size = UDim2.fromOffset(60, 12), ZIndex = 23 })
  local long = text(holder, "0:00", 10, regular, FAINT, { Position = UDim2.fromOffset(WIDE_W - 18 - 60, 97), Size = UDim2.fromOffset(60, 12),
    TextXAlignment = Enum.TextXAlignment.Right, ZIndex = 23 })
  local y = 140
  local prev = press(holder, "skip-back", 20, 23, function() Music.front().previous() end, 34)
  prev.Position = UDim2.fromOffset(x + 14, y)
  local play, playIcon = press(holder, "play", 28, 23, function() Music.front().toggle() end, 42)
  play.Position = UDim2.fromOffset(x + 60, y)
  local nxt = press(holder, "skip-forward", 20, 23, function() Music.front().next() end, 34)
  nxt.Position = UDim2.fromOffset(x + 106, y)
  -- (out: the menu shuts and the player is left on the screen; the words: the Music tab)
  local out = press(holder, "external-link", 16, 23, function() Window.showActive(false) end, 30)
  out.Position = UDim2.fromOffset(x + 142, y)
  local words = press(holder, "message-circle", 16, 23, function() Music.openTab() end, 30)
  words.Position = UDim2.fromOffset(x + 170, y)
  -- the tiles
  local tiles = {}
  local tileW = math.floor((WIDE_W - 36 - 20) / 3)
  local function tile(index, icon, label, run)
    local box = frame(holder, { Name = label, Position = UDim2.fromOffset(18 + (index - 1) * (tileW + 10), 184), Size = UDim2.fromOffset(tileW, 60),
      BackgroundColor3 = Color3.fromRGB(40, 40, 46), BackgroundTransparency = 0.15, ZIndex = 23 })
    round(box, 14)
    local rim = Instance.new("UIStroke")
    rim.Color, rim.Transparency, rim.Thickness = WHITE, 0.9, 1
    rim.Parent = box
    local mark = glyph(box, icon, 15, WHITE, { Position = UDim2.fromOffset(12, 10), ZIndex = 24 })
    text(box, label, 12, bold, WHITE, { Position = UDim2.fromOffset(12, 29), Size = UDim2.new(1, -20, 0, 14), ZIndex = 24 })
    local sub = text(box, "", 10, regular, GREY, { Position = UDim2.fromOffset(12, 43), Size = UDim2.new(1, -20, 0, 12), ZIndex = 24 })
    local give = Instance.new("UIScale")
    give.Parent = box
    local button = hit(box, 26)
    button.MouseEnter:Connect(function() box.BackgroundTransparency = 0.05 end)
    button.MouseLeave:Connect(function() box.BackgroundTransparency = 0.15; Motion.to(give, "Scale", 1, "bouncy") end)
    button.MouseButton1Down:Connect(function() Motion.to(give, "Scale", 0.96, "quick") end)
    button.MouseButton1Up:Connect(function() Motion.to(give, "Scale", 1, "bouncy") end)
    button.Activated:Connect(B.safe("card.tile", function() UI.sfx("click", 0.4); run() end))
    tiles[index] = { box = box, mark = mark, sub = sub }
  end
  tile(1, "shuffle", "Shuffle", function() local ctl = Music.front(); ctl.setShuffle(not ctl.shuffle()) end)
  tile(2, "search", "Library", function() Music.openTab() end)
  tile(3, "library", "Playlists", function() Music.openTab() end)
  local coverKey, accent = nil, nil
  local function colours(pal)
    accent = pal and pal.accent or nil
    local back = pal and pal.back or nil
    if back then
      tint.BackgroundColor3 = back
      Motion.to(tint, "BackgroundTransparency", 0, "gentle")
    else
      Motion.to(tint, "BackgroundTransparency", 1, "gentle")
    end
    local h, s = (pal and pal.accent or WHITE):ToHSV()
    local tileColor = pal and Color3.fromHSV(h, math.min(s * 0.5, 0.45), 0.3) or Color3.fromRGB(40, 40, 46)
    for _, item in ipairs(tiles) do
      item.box.BackgroundColor3 = tileColor
      item.mark.ImageColor3 = accent or kitAccent(kit)
    end
    seek.fill.BackgroundColor3 = accent or kitAccent(kit)
  end
  colours(nil)
  local function paintWide()
    local ctl = Music.front()
    local track = ctl.track()
    title.set(track and track.title or "Nothing playing")
    artist.Text = track and (ctl.status() or track.artist) or "Pick a song in the Music tab"
    UI.setIcon(playIcon, ctl.state() == "playing" and "pause" or "play")
    tiles[1].sub.Text = ctl.shuffle() and "On" or "Off"
    local liked = #(Config.get("music.liked") or {})
    tiles[2].sub.Text = liked .. (liked == 1 and " song" or " songs")
    local lists = #Music.playlists()
    tiles[3].sub.Text = lists .. (lists == 1 and " playlist" or " playlists")
    local key = track and track.key or nil
    if key ~= coverKey then
      coverKey = key
      if track then
        ctl.cover(track, cover)
        Card.paletteOf(ctl, track, function(pal)
          if coverKey == key and holder.Parent then colours(pal) end
        end)
      else
        cover.Image = ""
        colours(nil)
      end
    end
  end
  L.signal(Music.changed, paintWide)
  L.config("music.liked", paintWide)
  L.config("music.playlists", paintWide)
  L.config("music.shuffle", paintWide)
  paintWide()
  local out, spin, stamp = 0, 0, nil
  L.every(function(dt)
    if not shown() then return end
    local ctl = Music.front()
    local track = ctl.track()
    local now = (track and track.key or "") .. ctl.state() .. ctl.kind
    if now ~= stamp then stamp = now; paintWide() end
    title.step(dt)
    local position, length = ctl.position(), ctl.length()
    local f = seek.dragging or (length > 0 and math.clamp(position / length, 0, 1) or 0)
    seek.set(f)
    setText(at, Music.time(seek.dragging and seek.dragging * length or position))
    setText(long, length > 0 and Music.time(length) or "--:--")
    -- the record slides out while it plays and turns (33 a minute)
    local playing = ctl.state() == "playing"
    out += ((playing and 1 or 0) - out) * math.min(dt * 5, 1)
    if playing then spin = (spin + dt * 198) % 360 end
    disc.Position = UDim2.fromOffset(18 + 75 + out * 46, 18 + 75)
    disc.Rotation = spin
  end, 60, "music.wide")
end
Card.WIDE = Vector2.new(WIDE_W, WIDE_H)

-- where it sits: its bottom-left corner, kept on screen
function Card.seat()
  local holder = Card.holder
  local at = Card.at
  holder.AnchorPoint = Vector2.new(0, 1)
  -- (how far under its place it is while it comes and goes with the menu)
  local drop = Card.drop and Card.drop.Value or 0
  if not at then
    holder.Position = UDim2.new(0, 16, 1, -16 + drop)
    return
  end
  local layer = Window.hud.AbsoluteSize
  local size = holder.AbsoluteSize
  if layer.X <= 0 or layer.Y <= 0 then holder.Position = UDim2.fromScale(at.X, at.Y); return end
  local x = math.clamp(at.X * layer.X, 4, math.max(layer.X - size.X - 4, 4))
  local y = math.clamp(at.Y * layer.Y, math.min(size.Y + 4, layer.Y), layer.Y - 4)
  holder.Position = UDim2.fromOffset(x, y + drop)
end

function Card.define()
  Config.define("music.island", true)
  Config.define("music.cardMode", "full")
  Config.define("music.cardView", "cover")
  Config.define("music.cardX", -1)
  Config.define("music.cardY", -1)
  for _, id in ipairs({ "music.cardMode", "music.cardView", "music.cardX", "music.cardY" }) do Config.unshared(id) end
end
function Card.start()
  if Card.holder or not Window.hud then return end
  Card.mode = Config.get("music.cardMode") == "mini" and "mini" or "full"
  local view = Config.get("music.cardView")
  Card.view = (view == "lyrics" or view == "queue") and view or "cover"
  local x, y = Config.get("music.cardX"), Config.get("music.cardY")
  if type(x) == "number" and x >= 0 and type(y) == "number" and y >= 0 then Card.at = Vector2.new(x, y) end
  local holder = frame(Window.hud, { Name = "MusicCard", Size = UDim2.fromOffset(FULL_W, FULL_H), Visible = false, ZIndex = 1 })
  -- (one UIScale a frame: the window's scale, times the pop when it shows)
  local sizer = Instance.new("UIScale")
  sizer.Parent = holder
  local pop = Instance.new("NumberValue")
  pop.Value = 1
  local drop = Instance.new("NumberValue")
  drop.Value = 0
  Card.drop = drop
  Card.holder = holder
  build()
  Card.seat()
  paint()
  Music.changed:connect(function(what)
    if what == "queue" and Card.view ~= "queue" then return end
    B.try("card.paint", paint)
  end)
  Config.on("music.liked", function() B.try("card.paint", paint) end)
  -- It comes and goes with the menu, on the menu's own clock (2026-10-30: it had one of its own,
  -- and came back over the menu's cards while they were still going down). The menu opening: it
  -- sinks and fades with the cards rising (0.16 s). The menu closing: it waits for the cards to
  -- have gone down (each look's close takes so long), then rises into place with the same ease.
  local shown, leaving, menuShutAt = false, nil, -math.huge
  local wasOpen = Window.anyOpen()
  local CLOSE_TAKES = { novoline = 0.3, unnamed = 0.12, based = 0.24 }
  Motion.every(function(dt)
    local kit = Window.activeKit()
    if parts and kit.look ~= parts.look then build(); paint() end
    local ctl = Music.front()
    local track = ctl.track()
    local open = Window.anyOpen()
    if wasOpen and not open then menuShutAt = os.clock() end
    wasOpen = open
    local settled = os.clock() - menuShutAt >= (CLOSE_TAKES[kit.look] or 0.24)
    local show = Config.get("music.mini") ~= false and track ~= nil and ctl.state() ~= "idle" and not open and settled
    if show ~= shown then
      shown = show
      if show then
        leaving = nil
        holder.Visible = true
        paint()
        if Motion.reduced then pop.Value, drop.Value = 1, 0 else
          pop.Value, drop.Value = 0.94, 14
          Motion.to(pop, "Value", 1, "smooth")
          Motion.to(drop, "Value", 0, "smooth")
        end
      elseif Motion.reduced or not holder.Visible then
        holder.Visible = false
      else
        -- (going: down and smaller, quickly, then put away)
        local token = {}
        leaving = token
        Motion.to(pop, "Value", 0.94, { 0.16, 0 })
        Motion.to(drop, "Value", 14, { 0.16, 0 }, function() if leaving == token then holder.Visible = false end end)
      end
    end
    if leaving and holder.Visible then sizer.Scale = (Window.scale or 1) * pop.Value; Card.seat() end
    if not show or not parts then return end
    sizer.Scale = (Window.scale or 1) * pop.Value
    Card.seat()
    if parts.paintedFor ~= track.key or parts.paintedState ~= ctl.state() then
      parts.paintedFor, parts.paintedState = track.key, ctl.state()
      paint()
    end
    parts.title.step(dt)
    local position, length = ctl.position(), ctl.length()
    local fraction = length > 0 and math.clamp(position / length, 0, 1) or 0
    local seeking = parts.seekLine.dragging or parts.miniLine.dragging
    if seeking then fraction = seeking; position = seeking * length end
    parts.seekLine.set(fraction)
    parts.miniLine.set(fraction)
    local at = length > 0 and timeOf(position) or "--:--"
    local left = length > 0 and ("-" .. timeOf(math.max(length - position, 0))) or ""
    setText(parts.at, at)
    setText(parts.left, left)
    setText(parts.miniAt, at)
    setText(parts.miniLeft, left)
    -- (while it is dragged the line is where the pointer is: it used to stay put until let go, then jump)
    local held = parts.volumeLine.dragging
    local volume = held or (ctl.volume and ctl.volume() or nil)
    parts.volumeLine.frame.Visible = volume ~= nil
    parts.quiet.Visible, parts.loud.Visible = volume ~= nil, volume ~= nil
    parts.volumeLine.set(volume or 0)
    local quietIcon = (volume or 1) <= 0.001 and "volume-x" or "volume-2"
    if parts.quietIcon ~= quietIcon then parts.quietIcon = quietIcon; UI.setIcon(parts.quiet, quietIcon) end
    if Card.mode == "full" and Card.view == "lyrics" then parts.lyrics.step(dt, ctl) end
    if Card.mode == "mini" then
      local accent = Card.accent or WHITE
      local playing = ctl.state() == "playing"
      local raw = playing and ctl.loudness() or 0
      parts.peak = math.max((parts.peak or 4) * (1 - math.min(dt * 0.35, 1)), raw, 4)
      local loud = playing and math.clamp(raw / parts.peak * 1.05, 0, 1.15) or 0
      parts.level = (parts.level or 0) + (loud - (parts.level or 0)) * math.min(dt * 12, 1)
      local now = os.clock()
      for i, bar in ipairs(parts.bars) do
        local wobble = 0.4 + 0.6 * math.abs(math.sin(now * (3.3 + i * 1.1) + i * 1.9))
        bar.Size = UDim2.fromOffset(3, math.clamp(4 + parts.level * 12 * wobble, 4, 16))
        bar.BackgroundColor3 = accent
      end
    end
  end, nil, "music.card")
  Island.start()
end
end
do -- 50_settings.lua
-- ============================================================================
--  50 settings   the hub's own preferences and the Settings tab
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Window, Controls = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Window, B.Controls
local Assets = B.Assets
local Prefs = {}
B.Prefs = Prefs
B.pages = B.pages or {}

function Prefs.define()
  Config.define("app.scheme", "dark")
  Config.define("app.accent", Theme.accents[1].color)
  Config.define("app.glass", 60)
  Config.define("app.blur", true)
  Config.define("app.radius", 100)
  Config.define("app.scale", 100)
  Config.define("app.motion", "full")
  Config.define("app.motionSpeed", 100)
  Config.define("app.sfx", true)
  Config.define("app.sfxVolume", 45)
  Config.define("app.sfxSet", "novoline")
  Config.define("app.key.menu", "RightControl")
  Config.define("app.key.panic", "None")
  Config.define("app.freeCursor", true)
  -- (2026-11-18, the owner's word: "make the based hub menu always stays minimised by default". The hub starts with
  -- its window down; the menu key and the island bring it up)
  Config.define("app.startMinimised", true)
  Config.define("app.window.x", 0.5)
  Config.define("app.window.y", 0.5)
  Config.define("app.intro", "lotion")
  Config.define("app.introVolume", 50)
  -- The lotion film is everyone's intro from 2026-11-09 (the brand film was, from 2026-10-29), for
  -- whoever had picked another one too: it is set once, on the first launch of this build, and from
  -- then on the pick is theirs again.
  -- (a counter of its own, kept out of share codes: a pasted code never sets it back)
  Config.define("app.introSeen", 0)
  Config.unshared("app.introSeen")
  if (Config.get("app.introSeen") or 0) < 2 then
    Config.set("app.intro", "lotion")
    Config.set("app.introSeen", 2)
  end
  -- (the intros taken out on 2026-11-09: a pick of one, from an old share code say, is the lotion film)
  local gone = { reel = true, lock = true, prates = true, signal = true }
  if gone[Config.get("app.intro")] then Config.set("app.intro", "lotion") end
  Config.define("app.filmQuality", "auto")
  Config.define("app.island", true)
  Config.define("app.keyHud", true)
  Config.define("app.toasts", true)
  Config.define("app.scrollbar", "always")
  Config.define("app.font", "inter")
end

function Prefs.apply()
  Theme.state.scheme = Config.get("app.scheme")
  Theme.state.accent = Config.get("app.accent")
  Theme.state.glass = Config.get("app.glass") / 100
  Theme.state.radius = Config.get("app.radius") / 100
  Theme.apply()
  Motion.reduced = Config.get("app.motion") == "reduced"
  Motion.speed = Config.get("app.motionSpeed") / 100
  UI.sfxOn = Config.get("app.sfx")
  UI.sfxVolume = Config.get("app.sfxVolume") / 100
  UI.sfxSet = Config.get("app.sfxSet")
  UI.setScrollbar(Config.get("app.scrollbar"))
  B.Blur.set(Config.get("app.blur") == true)
  if Config.get("app.font") ~= "inter" then UI.setLetters(Config.get("app.font")) end
  Config.on("app.font", function(v) UI.setLetters(v) end)
  Motion.every(UI.sweepFontsSome, 10, "ui.fontsweep")

  Config.on("app.scheme", function(v) Theme.set({ scheme = v }) end)
  Config.on("app.accent", function(v) Theme.set({ accent = v }) end)
  Config.on("app.glass", function(v) Theme.set({ glass = v / 100 }) end)
  Config.on("app.radius", function(v) Theme.set({ radius = v / 100 }) end)
  Config.on("app.blur", function(v) B.Blur.set(v == true) end)
  Config.on("app.scale", function() Window.rescale() end)
  Config.on("app.motion", function(v) Motion.reduced = v == "reduced" end)
  Config.on("app.motionSpeed", function(v) Motion.speed = v / 100 end)
  Config.on("app.sfx", function(v) UI.sfxOn = v end)
  Config.on("app.sfxVolume", function(v) UI.sfxVolume = v / 100 end)
  Config.on("app.sfxSet", function(v) UI.sfxSet = v end)
  Config.on("app.scrollbar", function(v) UI.setScrollbar(v) end)
  Config.on("app.freeCursor", function(v) if Window.modal then Window.modal.Visible = Window.open and v end end)
end

-- the accent row: a swatch per preset, then a free colour
local function accentPicker(frame)
  local row = UI.frame(frame, { Size = UDim2.new(1, -28, 0, 30), Position = UDim2.fromOffset(14, 8) })
  UI.list(row, "x", 9, { v = "Center" })
  local rings = {}
  local function mark()
    local current = Config.get("app.accent")
    for color, ring in pairs(rings) do
      Motion.to(ring, "Transparency", util.toHex(color) == util.toHex(current) and 0 or 1, "quick")
    end
  end
  for index, accent in ipairs(Theme.accents) do
    local swatch = UI.frame(row, { Size = UDim2.fromOffset(24, 24), BackgroundTransparency = 0, BackgroundColor3 = accent.color, LayoutOrder = index })
    UI.corner(swatch, true)
    local ring = Instance.new("UIStroke")
    ring.Thickness = 2
    ring.Transparency = 1
    pcall(function() ring.BorderStrokePosition = Enum.BorderStrokePosition.Outer end)
    pcall(function() ring.BorderOffset = UDim.new(0, 2) end)
    Theme.bind(ring, "Color", "ink")
    ring.Parent = swatch
    rings[accent.color] = ring
    local scale = UI.scaleOf(swatch)
    local hit = UI.button(swatch, {
      hover = function(on) Motion.to(scale, "Scale", on and 1.12 or 1, "snappy") end,
      click = function() UI.sfx("click", 0.6); Config.set("app.accent", accent.color) end,
    })
    UI.tooltip(hit, accent.label)
  end
  local custom = UI.frame(row, { Size = UDim2.fromOffset(24, 24), LayoutOrder = 99, Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill2A" } })
  UI.corner(custom, true)
  UI.icon(custom, "pipette", 13, "sub", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
  local hit = UI.button(custom, { click = function()
    Controls.colorPopover(custom, Config.get("app.accent"), function(color) Config.set("app.accent", color) end)
  end })
  UI.tooltip(hit, "Any colour")
  Config.on("app.accent", function() if row.Parent then mark() end end)
  mark()
end

B.pages[#B.pages + 1] = function()
  Window.page({ id = "settings", title = "Settings", icon = "settings", group = "Hub", order = 900, eyebrow = "Make it yours", build = function(page)
    local look = page:section({ title = "Appearance", icon = "palette", desc = "Changes apply live." })
    -- (2026-11-11: the Unnamed and Novoline looks are out of the build for now, _retired/menus-1111: with neither in,
    -- there is nothing to pick between and the row is not made; what was saved for it stays as it was saved)
    if B.Unnamed or B.Novoline then
      local styles = { { "based", "BASED" } }
      if B.Unnamed then styles[#styles + 1] = { "unnamed", "Unnamed" } end
      if B.Novoline then styles[#styles + 1] = { "novoline", "Novoline" } end
      look:dropdown({ id = "app.gui", label = "Menu style", desc = B.Novoline and "BASED, the old dark menu, or Novoline's dock." or "BASED, or the Unnamed menu.", options = styles })
    end
    do
      local families = {}
      for _, spec in ipairs(UI.FAMILIES) do families[#families + 1] = { spec[1], spec[2] } end
      look:dropdown({ id = "app.font", label = "Font", desc = "Every word in the BASED look.", options = families })
    end
    if B.Unnamed then look:color({ id = "app.unnamed.accent", label = "Unnamed colour", desc = "The line on the Unnamed menu's boxes." }) end
    if B.Unnamed and B.Unnamed.FONTS then
      local faces = {}
      for _, spec in ipairs(B.Unnamed.FONTS) do faces[#faces + 1] = { spec[1], spec[2] } end
      look:dropdown({ id = "app.unnamed.font", label = "Unnamed font", desc = "Its letters, and its key list's. Monocraft is the Minecraft one.", options = faces })
      look:slider({ id = "app.unnamed.textSize", label = "Unnamed text size", tip = "Text size in the Unnamed look.", min = 80, max = 130, step = 5, suffix = "%" })
      look:toggle({ id = "app.unnamed.watermark", label = "Unnamed watermark", desc = "Name, game, fps, ping and time, top left.", bindable = false })
    end
    if B.Novoline then
      look:color({ id = "app.novoline.accent", label = "Novoline colour", desc = "Its one colour: icons, checks, the island's dot." })
      local faces = {}
      for _, spec in ipairs(B.Novoline.FONTS) do faces[#faces + 1] = { spec[1], spec[2] } end
      look:dropdown({ id = "app.novoline.font", label = "Novoline font", desc = "Gotham is Novoline's own.", options = faces })
      look:slider({ id = "app.novoline.size", label = "Novoline size", tip = "How big the Novoline look is.", min = 70, max = 140, step = 5, suffix = "%" })
      look:slider({ id = "app.novoline.shade", label = "Novoline shade", desc = "How dark the game goes behind it.", min = 0, max = 100, step = 5, suffix = "%" })
      look:toggle({ id = "app.novoline.dock", label = "Keep the dock", desc = "The pill stays at the bottom while it is shut.", bindable = false })
      look:toggle({ id = "app.novoline.island", label = "Novoline island", desc = "The song and every message, top middle.", bindable = false })
    end
    look:segmented({ id = "app.scheme", label = "Scheme", tip = "Dark, light or midnight.", options = { { "dark", "Graphite" }, { "midnight", "Midnight" }, { "light", "Porcelain" } }, width = 232 })
    look:custom({ height = 46, name = "Accent", build = accentPicker })
    look:slider({ id = "app.glass", label = "Glass", desc = "Clear on the left, tinted on the right.", min = 0, max = 100, step = 1, suffix = "%" })
    look:toggle({ id = "app.blur", label = "Real blur", desc = "Blurs the game behind the window. Needs graphics quality 8 or higher.", bindable = false })
    look:slider({ id = "app.radius", label = "Corner roundness", tip = "How round the corners are.", min = 40, max = 130, step = 5, suffix = "%" })
    look:slider({ id = "app.scale", label = "Interface size", desc = "It never grows past the screen.", min = 60, max = 160, step = 5, suffix = "%" })
    look:segmented({ id = "app.scrollbar", label = "Scrollbar", desc = "Drag it, or click beside it to jump.", options = { { "always", "Always" }, { "auto", "Scrolling" }, { "off", "Off" } }, width = 232 })

    local motion = page:section({ title = "Motion & sound", icon = "activity" })
    motion:segmented({ id = "app.motion", label = "Animations", tip = "Full or reduced motion.", options = { { "full", "Full" }, { "reduced", "Reduced" } }, width = 170 })
    motion:slider({ id = "app.motionSpeed", label = "Animation speed", tip = "How fast animations play.", min = 40, max = 250, step = 10, suffix = "%" })
    motion:toggle({ id = "app.sfx", label = "Interface sounds", tip = "Clicks and pops in the menu.", bindable = false })
    motion:slider({ id = "app.sfxVolume", label = "Sound volume", tip = "How loud the menu sounds are.", min = 0, max = 100, step = 5, suffix = "%" })
    motion:segmented({ id = "app.sfxSet", label = "Menu sounds", tip = "Open, close, tab and notification sounds.", options = { { "novoline", "Novoline" }, { "based", "BASED" } },
      default = "novoline", width = 190 })

    local keys = page:section({ title = "Keys", icon = "keyboard" })
    keys:keybind({ tip = "The key that opens and closes the hub.", id = "app.key.menu", label = "Open / close the hub" })
    keys:keybind({ id = "app.key.panic", label = "Panic", desc = "Unloads BASED instantly: every feature off, nothing left behind." })
    keys:toggle({ id = "app.freeCursor", label = "Free the cursor while open", desc = "Unlocks the mouse in first-person games.", bindable = false })
    keys:button({ label = "Every key, on a keyboard", desc = "What each one does, and a click to change it.", text = "Open", bindable = false, run = function() Window.go("keys") end })
    keys:note({ icon = "info", text = "Right-click any toggle or button to bind it to a key." })

    local screen = page:section({ title = "On screen", icon = "monitor", desc = "What stays up while the hub is hidden." })
    screen:toggle({ id = "app.startMinimised", label = "Start minimised", desc = "The hub loads with its window down. The menu key opens it.", bindable = false })
    screen:toggle({ id = "app.island", label = "The island", desc = "The pill at the top: frame rate and ping, and your speed in flight. Click it to bring the hub back.", bindable = false })
    screen:toggle({ id = "app.keyHud", label = "My keys", desc = "Each bound feature with its key, lit while it is on.", bindable = false })
    screen:toggle({ id = "app.toasts", label = "Say which game this is on launch", tip = "A message naming the game when it loads.", bindable = false })

    if B.Board and B.Board.installed() then
      B.Board.define()
      local board = page:section({ title = "Home board", icon = "film", desc = "The film on the Home tab." })
      board:toggle({ id = "home.board", label = "Play it", desc = "Silent in the card. Off shows a still instead.", bindable = false })
      board:toggle({ id = "home.boardHover", label = "Open on hover", desc = "Rest the mouse on it: it comes forward and the sound comes in.", bindable = false })
      board:slider({ id = "home.boardVolume", label = "Sound volume", tip = "How loud the Home film is.", min = 0, max = 100, step = 5, suffix = "%" })
      board:slider({ id = "home.boardSize", label = "Opened size", desc = "How much of the screen's width it takes.", min = 30, max = 90, step = 2, suffix = "%" })
      board:dropdown({ id = "home.boardQuality", label = "Picture", tip = "Ultra or HD for the Home film.", options = { { "ultra", "Ultra · 1820×1024" }, { "hd", "HD · 1024×576" } } })
    end

    local intro = page:section({ title = "Intro", icon = "clapperboard" })
    intro:dropdown({ id = "app.intro", label = "On launch", desc = "Your edits play with their own sound. Shuffle: a different one each time.",
      options = { { "lotion", "BASED lotion" }, { "brand", "BASED brand film" }, { "richard", "Neverlose vs BASED" }, { "cinematic", "Cinematic" },
        { "quick", "Quick" }, { "shuffle", "Shuffle" }, { "off", "Off" } } })
    -- the film and its music are settings only where there is a film: without one the intro is the name alone
    local function anyFilm()
      local quality = Config.get("app.filmQuality")
      if B.Film.pick(quality) then return true end
      for _, spec in pairs(B.FILMS or {}) do
        if B.Film.pick(quality, spec) then return true end
      end
      return false
    end
    if B.Film and not B.Assets.lite and anyFilm() then
      intro:slider({ id = "app.introVolume", label = "Music volume", tip = "How loud the intro is.", min = 0, max = 100, step = 5, suffix = "%" })
      -- a choice of picture only where there is one to make: an install fetches the one size its screen suits
      if B.Film.has("hd") and B.Film.has("ultra") then
        intro:dropdown({ id = "app.filmQuality", label = "Film quality", tip = "Ultra or HD for the intro films.", options = { { "auto", "Auto" }, { "ultra", "Ultra · 1820×1024" }, { "hd", "HD · 1024×576" } } })
      end
    end
    intro:button({ label = "Replay the intro", tip = "Plays your intro again.", text = "Play", run = function()
      if not B.Loader then return end
      local chosen = Config.get("app.intro")
      Window.showActive(false)
      B.Loader.run(function() Window.showActive(true) end, chosen == "off" and B.Loader.MAIN or chosen)
    end })

    local data = page:section({ title = "Configs", icon = "save", desc = "Feature settings save on their own." })
    data:segmented({ label = "Saved", tip = "One config for every game, or one per game.", options = { { "global", "One for all games" }, { "game", "One per game" } }, default = Config.profileMode, width = 232,
      changed = function(mode) if mode ~= Config.profileMode then Config.setMode(mode); Window.toast({ title = "Config scope changed", text = mode == "game" and "This game now has its own settings." or "One config for every game.", icon = "save" }) end end })
    data:button({ label = "Copy share code", desc = "Everything: settings, colours, font, keys.", text = "Copy", run = function()
      local code = Config.export()
      if not code then Window.toast({ title = "Could not make a code", text = "A setting here cannot be written down.", icon = "triangle-alert", tone = "warn" })
      elseif B.clipboard(code) then Window.toast({ title = "Share code copied", text = "Whoever pastes it gets your exact setup.", icon = "clipboard", tone = "ok" })
      else Window.toast({ title = "Could not copy", text = "This executor has no clipboard access.", icon = "triangle-alert", tone = "warn" }) end
    end })
    local importBox
    importBox = data:input({ label = "Paste share code", tip = "Paste a code to copy someone's setup.", placeholder = "Paste, then Enter", width = 170, changed = function(text)
      if text == "" then return end
      local ok, count, note = Config.import(text)
      importBox.box.Text = ""
      Window.toast(ok and { title = "Setup loaded", text = count .. " settings and keys applied." .. (note and (" " .. note) or ""), icon = "circle-check", tone = "ok" }
        or { title = "Code not read", text = note or "That text could not be read.", icon = "triangle-alert", tone = "warn", time = 6 })
    end })
    data:button({ label = "Reset every feature", desc = "Appearance and keys are kept.", text = "Reset", style = "danger", run = function()
      Config.resetAll(false)
      Window.toast({ title = "Features reset", text = "Everything is back to its default.", icon = "rotate-ccw" })
    end })

    local about = page:section({ title = "About", icon = "info" })
    local function stat(label, value)
      about:custom({ height = 34, build = function(frame)
        UI.text(frame, label, "label", "sub", { Position = UDim2.new(0, 14, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), TextSize = 13 })
        local text = UI.text(frame, "", "mono", "ink", { Position = UDim2.new(1, -14, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5) })
        if type(value) == "function" then
          text.Text = tostring(value())
          Motion.every(function() if text.Parent and Window.showing("settings") then text.Text = tostring(value()) end end, 2, "about")
        else text.Text = tostring(value) end
      end })
    end
    stat("Version", B.VERSION .. "  ·  " .. B.BUILD)
    stat("Executor", B.executor)
    stat("Assets", function() return Assets.lite and "missing (lite mode)" or (Assets.calls .. " registered this session") end)
    stat("Started in", function() return (B.bootMs or 0) .. " ms" end)
    stat("Faults", function() return #B.faults end)
    about:button({ label = "Copy diagnostics", tip = "Copies info that helps fix a problem.", text = "Copy", run = function()
      local lines = { "BASED " .. B.VERSION .. " " .. B.BUILD, "executor " .. B.executor, "place " .. game.PlaceId .. " universe " .. game.GameId }
      for _, fault in ipairs(B.faults) do lines[#lines + 1] = string.format("[%.1fs] %s: %s", fault.at, fault.scope, fault.message) end
      B.clipboard(table.concat(lines, "\n"))
      Window.toast({ title = "Diagnostics copied", icon = "clipboard", tone = "ok" })
    end })
    about:button({ label = "Unload BASED", tip = "Turns the hub off completely.", text = "Unload", style = "danger", bindable = false, run = function() B.unload() end })
    about:note({ text = "Fonts: Inter, Instrument Serif, Archivo, Geist Mono (SIL OFL). Icons: Lucide (ISC). Interface sounds: Kenney (CC0)." })
  end })
end
end
do -- 51_keys.lua
-- ============================================================================
--  51 keys     the keyboard, drawn, with what every key does written on it
--
--  A key can be given a feature from either side: right-click a toggle or a
--  button and press a key, or come here, click the key and pick the feature.
--  The picture is the same either way. A bound key carries its feature's name
--  (in two lines when it has to; a key too narrow for the whole name carries the
--  mark of its group, and the name is in the list under the board, never cut
--  short) and lights up while that feature is on. Six looks a key can have, each
--  its own: free, the hub's own, bound and off, held (works while held), on, and
--  two things on one key. The same list can sit on screen while the hub is
--  hidden, grouped (movement, combat, visuals, flight, the hub), in columns.
--
--  Drawn in the look it is in: the BASED window, the Unnamed menu and Novoline
--  each draw the board, the list and the list on screen in their own colours and
--  letters (Window.kit). Every size here is in design px: text never under 12,
--  room between any two things never under 6.
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Window, Controls = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Window, B.Controls
local UIS = S.UserInputService
local TS = S.TweenService
local TextService = S.TextService
local Keys = { caps = {}, builtin = {}, views = {}, lists = {} }
B.Keys = Keys
B.pages = B.pages or {}

-- An ANSI board in units of one key; every row is fifteen units wide (the last, under it, twelve and a half).
local function k(key, width) return { key = key, width = width or 1 } end
local function gap(width) return { width = width } end
local ROWS = {
  { k("Escape"), gap(1), k("F1"), k("F2"), k("F3"), k("F4"), gap(0.5), k("F5"), k("F6"), k("F7"), k("F8"), gap(0.5), k("F9"), k("F10"), k("F11"), k("F12") },
  { k("Backquote"), k("One"), k("Two"), k("Three"), k("Four"), k("Five"), k("Six"), k("Seven"), k("Eight"), k("Nine"), k("Zero"), k("Minus"), k("Equals"), k("Backspace", 2) },
  { k("Tab", 1.5), k("Q"), k("W"), k("E"), k("R"), k("T"), k("Y"), k("U"), k("I"), k("O"), k("P"), k("LeftBracket"), k("RightBracket"), k("BackSlash", 1.5) },
  { k("CapsLock", 1.75), k("A"), k("S"), k("D"), k("F"), k("G"), k("H"), k("J"), k("K"), k("L"), k("Semicolon"), k("Quote"), k("Return", 2.25) },
  { k("LeftShift", 2.25), k("Z"), k("X"), k("C"), k("V"), k("B"), k("N"), k("M"), k("Comma"), k("Period"), k("Slash"), k("RightShift", 2.75) },
  { k("LeftControl", 1.5), k("LeftAlt", 1.25), k("Space", 5.5), k("RightAlt", 1.25), k("RightControl", 1.5), k("Left"), k("Up"), k("Down"), k("Right") },
  { k("Insert", 1.25), k("Delete", 1.25), k("Home", 1.25), k("End", 1.25), k("PageUp", 1.25), k("PageDown", 1.25), gap(0.5), k("MouseButton2", 2.25), k("MouseButton3", 2.25) },
}
Keys.ROWS = ROWS
-- Room between any two things (keys, rows, chips) is never under GAP; no text is drawn under 12.
-- A key is 52 tall when the board is wide enough for a name in two lines, else 40 (its key and a mark).
local GAP, MIN_TEXT = 6, 12
local TALL, SHORT = 52, 40
Keys.GAP, Keys.MIN_TEXT = GAP, MIN_TEXT
local function stepFor(width) return math.max(20, math.floor((width + GAP) / 15)) end
local function capHeight(step) return step >= 44 and TALL or SHORT end
local function boardHeight(step) return #ROWS * (capHeight(step) + GAP) - GAP end
local LEGEND_H, STATES_H = 34, 20
local function frameHeight(step) return 4 + boardHeight(step) + 8 + LEGEND_H + GAP + STATES_H + GAP end
-- the width each look gives the board when it cannot be measured yet (design px: measured 2026-11-09)
local ROOM = { based = 736, unnamed = 536, novoline = 564 }
-- and the least it takes as measured: Novoline builds a tab's sections in a narrower card before
-- it shows them in its Options card (measured 340 there, 564 shown), and its wide card is 540 at least
local LEAST = { based = 736, unnamed = 400, novoline = 540 }
-- room left at each side of the board, inside its card: the BASED and Novoline cards have round
-- corners a key at the very edge would sit in; Unnamed's square boxes are padded already
local SIDE = { based = 10, unnamed = 0, novoline = 10 }
local function boardStep(width, look) return stepFor(width - 2 * (SIDE[look] or 0)) end
Keys.width = 15 * boardStep(ROOM.based, "based") - GAP
Keys.height = boardHeight(boardStep(ROOM.based, "based"))
local LONG = { MouseButton2 = "Right click", MouseButton3 = "Middle click", Backspace = "Backspace", Return = "Enter", CapsLock = "Caps", Space = "Space",
  LeftShift = "Shift", RightShift = "Shift", LeftControl = "Ctrl", RightControl = "Ctrl", LeftAlt = "Alt", RightAlt = "Alt", Tab = "Tab", Escape = "Esc",
  Insert = "Ins", Delete = "Del", PageUp = "PgUp", PageDown = "PgDn" }
-- (only for a board too narrow for the others)
local MINI = { Backspace = "Bk", Return = "Ent", CapsLock = "Cap", LeftShift = "Sft", RightShift = "Sft", LeftControl = "Ctl", RightControl = "Ctl", Space = "Spc",
  MouseButton2 = "M2", MouseButton3 = "M3", Escape = "Es", Home = "Hm", PageUp = "PU", PageDown = "PD", Insert = "In", Delete = "Dl" }
-- the arrows are drawn, not written: "Right" is wider than a key on the narrow boards
local ARROWS = { Left = { icon = "arrow-left" }, Up = { icon = "arrow-up" }, Down = { icon = "arrow-down" }, Right = { icon = "arrow-right" } }
local BADGES = { hold = { icon = "hand" }, clash = { icon = "triangle-alert" } }
-- on the cap the two Shifts and the two Ctrls are told apart by where they sit; in a sentence they need saying
local function keyName(key) return Config.keyLabel(key) end

-- ---------------------------------------------------------------- measuring
-- Text is measured in design px with the engine's own fonts nearest each look's letters, and a
-- look whose letters run wider (Unnamed's Monocraft) is measured wider. The same numbers decide
-- every fit here, so nothing is drawn in a box it does not fit.
local FACE = { text = Enum.Font.GothamMedium, bold = Enum.Font.GothamBold, mono = Enum.Font.Code, wide = Enum.Font.GothamBlack }
local WIDER = { based = 1, novoline = 1, unnamed = 1.2 }
local widths = {}
function Keys.textWidth(text, size, kind, look)
  text = tostring(text or "")
  if text == "" then return 0 end
  if not FACE[kind] then kind = "text" end
  local key = kind .. "|" .. tostring(size) .. "|" .. text
  local width = widths[key]
  if width == nil then
    local ok, bounds = pcall(TextService.GetTextSize, TextService, text, size, FACE[kind], Vector2.new(100000, 1000))
    width = (ok and typeof(bounds) == "Vector2") and bounds.X or ((utf8.len(text) or #text) * size * 0.62)
    widths[key] = width
  end
  return math.ceil(width * (WIDER[look] or 1) - 0.001)
end
-- `text` in at most `lines` lines no wider than `width`, broken between words; nil when it cannot be
-- drawn whole that way (a word wider than the room, or more lines than there are)
function Keys.wrap(text, size, width, lines, kind, look)
  local out, line = {}, nil
  for word in string.gmatch(tostring(text or ""), "%S+") do
    if Keys.textWidth(word, size, kind, look) > width then return nil end
    local joined = line and (line .. " " .. word) or word
    if line and Keys.textWidth(joined, size, kind, look) > width then
      out[#out + 1] = line
      line = word
    else
      line = joined
    end
  end
  if line then out[#out + 1] = line end
  if #out > (lines or 1) then return nil end
  return out
end
-- how wide a frame is in design px (its look's own scale taken out); `fallback` when it is not laid out yet
local function designWidth(frame, fallback)
  local scale, up = 1, frame
  while up and up:IsA("GuiObject") do
    local sizer = up:FindFirstChildOfClass("UIScale")
    if sizer then scale *= sizer.Scale end
    up = up.Parent
  end
  local width = scale > 0 and frame.AbsoluteSize.X / scale or 0
  if width < 240 or width > 2400 then return fallback end
  return math.floor(width + 0.01)
end

-- how wide the board or the list may be in `frame`, drawn in `look`
local function roomOf(frame, look, known)
  if look == "based" then return ROOM.based end
  return math.max(designWidth(frame, known or ROOM[look] or ROOM.based), LEAST[look] or 400)
end

-- ---------------------------------------------------------------- drawing in the look it is in
-- roles as Window.kit has them (card field hover line back text dim faint accent onAccent good bad) and warn
local TOKEN = { text = "ink", dim = "sub", faint = "faint", accent = "accent", onAccent = "accentInk", warn = "warn", card = "ink", field = "ink",
  hover = "ink", line = "ink", back = "base", good = "ok", bad = "bad" }
local function tone(kit, instance, property, role)
  if kit.look == "based" then Theme.bind(instance, property, TOKEN[role] or "ink"); return end
  Theme.unbind(instance, property)
  if role == "warn" then
    kit.paint(instance, property, "text")   -- (off the accent, if it wore it)
    instance[property] = T.warn
  else
    kit.paint(instance, property, role)
  end
end
-- how see-through: a theme key (the BASED look) or a number
local function see(kit, instance, property, value)
  if type(value) == "string" then
    if kit.look == "based" then Theme.bind(instance, property, value); return end
    value = T[value] or 0
  end
  if kit.look == "based" then Theme.unbind(instance, property) end
  instance[property] = value
end
-- a colour (and how see-through) set at once, or faded to from what it is now
local function fade(kit, instance, property, role, animate)
  local from = instance[property]
  tone(kit, instance, property, role)
  if animate and not Motion.reduced then
    local to = instance[property]
    instance[property] = from
    TS:Create(instance, Keys.LIGHT, { [property] = to }):Play()
  end
end
local function fadeAlpha(kit, instance, property, value, animate)
  local from = instance[property]
  see(kit, instance, property, value)
  if animate and not Motion.reduced then
    local to = instance[property]
    instance[property] = from
    TS:Create(instance, Keys.LIGHT, { [property] = to }):Play()
  end
end
-- what kind of letters a look writes keys and names in, for measuring them
local function kinds(look)
  if look == "unnamed" then return "mono", "mono" end
  if look == "novoline" then return "bold", "text" end
  return "mono", "text"
end
-- a label in the look's letters: never cut short, never wrapped by the engine (lines are ours)
local function write(kit, parent, value, opts)
  local label
  if kit.look == "based" then
    local style = opts.mono and (opts.bold and "monoBold" or "mono") or (opts.wide and "eyebrow") or (opts.bold and "heading") or (opts.caption and "caption") or "label"
    label = UI.text(parent, value, style, TOKEN[opts.role or "text"] or "ink")
    label.TextSize = opts.size or MIN_TEXT
  else
    label = kit.text(parent, value, nil, opts.bold == true or opts.wide == true, opts.size or MIN_TEXT)
    tone(kit, label, "TextColor3", opts.role or "text")
  end
  label.AutomaticSize = Enum.AutomaticSize.None
  label.TextTruncate = Enum.TextTruncate.None
  label.TextWrapped = false
  if opts.props then for key, v in pairs(opts.props) do label[key] = v end end
  return label
end
local function glyph(kit, parent, name, size, role, props)
  local image = UI.icon(parent, name, size, TOKEN[role] or "ink", props)
  if kit.look ~= "based" then tone(kit, image, "ImageColor3", role) end
  return image
end
local function round(kit, frame, radius)
  if kit.look == "based" then return UI.corner(frame, radius) end
  if (kit.radius or 0) == 0 then return nil end
  if type(radius) == "string" then radius = kit.small end
  return kit.corner(frame, radius)
end
local function edge(kit, frame)
  if kit.look == "based" then return UI.stroke(frame, "ink", "strokeA") end
  local stroke = Instance.new("UIStroke")
  stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
  stroke.Thickness = 1
  stroke.Parent = frame
  return stroke
end
local function kitOf(look) return (Window.kits and Window.kits[look]) or Window.kit(nil) end

-- ---------------------------------------------------------------- groups
Keys.GROUPS = {
  { id = "movement", label = "Movement", icon = "footprints" },
  { id = "combat", label = "Combat", icon = "crosshair" },
  { id = "visuals", label = "Visuals", icon = "eye" },
  { id = "flight", label = "Flight", icon = "plane" },
  { id = "hub", label = "Hub", icon = "command" },
}
local GROUP = {}
for index, group in ipairs(Keys.GROUPS) do group.rank = index; GROUP[group.id] = group end
local BY_ID = { move = "movement", aim = "combat", esp = "visuals", world = "visuals", fx = "visuals", self = "visuals", fly = "flight", flight = "flight" }
local BY_PAGE = { movement = "movement", combat = "combat", ragebot = "combat", resolver = "combat", loadout = "combat", visuals = "visuals", display = "visuals",
  skins = "visuals" }
-- which group a feature is in: from its flag ("move.*", "*.fly*"), else from the tab it is on
function Keys.groupOf(id, pageId)
  id = tostring(id or "")
  local last = string.lower(string.match(id, "([^%.]+)$") or id)
  if string.find(last, "^fly") or string.find(last, "flight", 1, true) then return "flight" end
  local first = string.match(id, "^([^%.]+)%.")
  if first and BY_ID[first] then return BY_ID[first] end
  local page = pageId and string.lower(string.match(tostring(pageId), "([^%.]+)$") or tostring(pageId)) or nil
  if page and BY_PAGE[page] then return BY_PAGE[page] end
  return "hub"
end
function Keys.group(id) return GROUP[id] or GROUP.hub end

-- ---------------------------------------------------------------- what is on a key
-- the keys the hub and flight already use, read fresh: four of them can be moved
local OWN = {
  { flag = "app.key.menu", short = "Menu", what = "opens and closes the hub", label = "Open / close the hub", group = "hub" },
  { flag = "app.key.panic", short = "Panic", what = "unloads BASED", label = "Panic", group = "hub" },
  { flag = "fly.key.boost", short = "Boost", what = "flight: boost", label = "Flight: boost", group = "flight" },
  { flag = "fly.key.down", short = "Descend", what = "flight: come down", label = "Flight: come down", group = "flight" },
}
local function readBuiltins()
  local map = {}
  local function put(key, short, what, flag, group)
    if type(key) ~= "string" or key == "None" then return end
    map[key] = map[key] or {}
    table.insert(map[key], { short = short, what = what, flag = flag, group = group })
  end
  for _, own in ipairs(OWN) do put(Config.get(own.flag), own.short, own.what, own.flag, own.group) end
  put("Space", "Climb", "flight: charge on the ground, climb in the air", nil, "flight")
  for _, key in ipairs({ "W", "A", "S", "D" }) do put(key, "Move", "walk and steer", nil, "movement") end
  Keys.builtin = map
  return map
end
-- (a feature whose switch has not been drawn yet is named from its id: "dahood.airJump" -> "Air jump")
local function nameFromId(id)
  local last = string.match(id, "([^%.]+)$") or id
  last = string.gsub(last, "(%l)(%u)", "%1 %2")
  return string.upper(string.sub(last, 1, 1)) .. string.lower(string.sub(last, 2))
end
local function featureOf(id)
  local entry = Controls.bindables[id]
  local kind = entry and entry.kind or (type(Config.get(id)) == "boolean" and "toggle" or "button")
  local page = entry and entry.page or nil
  return entry and entry.label or nameFromId(id), kind, page and page.title or nil, Keys.groupOf(id, page and page.id or nil)
end
-- every feature bound to `key`, by name
function Keys.on(key)
  local list = {}
  for id, bind in pairs(Config.binds) do
    if bind.key == key then
      local label, kind, page, group = featureOf(id)
      list[#list + 1] = { id = id, label = label, kind = kind, page = page, group = group, mode = bind.mode,
        on = Config.get(id) == true or (kind == "button" and Config.isActive(id)) }
    end
  end
  table.sort(list, function(a, b)
    if a.label ~= b.label then return a.label < b.label end
    return a.id < b.id
  end)
  return list
end
-- every bind there is, in keyboard order
local ORDER = {}
for _, row in ipairs(ROWS) do
  for _, item in ipairs(row) do
    if item.key then ORDER[item.key] = #ORDER + 1; ORDER[#ORDER + 1] = item.key end
  end
end
function Keys.all()
  local out = {}
  for id, bind in pairs(Config.binds) do
    if bind.key then
      local label, kind, page, group = featureOf(id)
      out[#out + 1] = { id = id, key = bind.key, label = label, kind = kind, page = page, group = group, mode = bind.mode, order = ORDER[bind.key] or 999,
        on = Config.get(id) == true or (kind == "button" and Config.isActive(id)) }
    end
  end
  table.sort(out, function(a, b)
    if a.order ~= b.order then return a.order < b.order end
    if a.label ~= b.label then return a.label < b.label end
    return a.id < b.id
  end)
  return out
end
-- the binds with what is shared marked (two on a key, or one on the hub's own), and the hub's own
-- keys too when `own`; sorted by group when `grouped`
function Keys.listed(own, grouped)
  readBuiltins()
  local binds = Keys.all()
  local count = {}
  for _, bind in ipairs(binds) do count[bind.key] = (count[bind.key] or 0) + 1 end
  for _, bind in ipairs(binds) do bind.clash = count[bind.key] > 1 or Keys.builtin[bind.key] ~= nil end
  if own then
    for _, item in ipairs(OWN) do
      local key = Config.get(item.flag)
      if type(key) == "string" and key ~= "None" then
        binds[#binds + 1] = { id = item.flag, key = key, label = item.label, kind = "builtin", builtin = true, on = false, group = item.group,
          order = ORDER[key] or 999, clash = count[key] ~= nil }
      end
    end
  end
  table.sort(binds, function(a, b)
    if grouped and a.group ~= b.group then return Keys.group(a.group).rank < Keys.group(b.group).rank end
    if a.order ~= b.order then return a.order < b.order end
    if (a.builtin == true) ~= (b.builtin == true) then return not a.builtin end
    if a.label ~= b.label then return a.label < b.label end
    return a.id < b.id
  end)
  return binds
end
-- what a key does, in a sentence. With `room` (design px) it is kept to two lines of that width:
-- the features that do not fit are counted instead.
function Keys.describe(key, room, look)
  local features, roles = Keys.on(key), Keys.builtin[key]
  local parts = {}
  for _, f in ipairs(features) do
    parts[#parts + 1] = f.label .. (f.kind == "toggle" and (f.mode == "hold" and " (while held" or " (toggle") .. (f.on and ", on)" or ", off)") or " (runs it)")
  end
  for _, role in ipairs(roles or {}) do parts[#parts + 1] = role.what end
  local name = keyName(key)
  if #parts == 0 then return name .. "  ·  free. Click it to give it a feature." end
  local clash = #features > 1 or (#features > 0 and roles ~= nil)
  local tail = clash and "   — more than one thing on this key" or ""
  local shown = #parts
  while true do
    local text = name .. "  ·  " .. table.concat(parts, "  +  ", 1, shown) .. (shown < #parts and ("  +  " .. (#parts - shown) .. " more") or "") .. tail
    if not room or shown <= 1 or Keys.wrap(text, MIN_TEXT, room, 2, "text", look) then return text end
    shown -= 1
  end
end

-- ---------------------------------------------------------------- menus
local function menuRow(content, order, item, close, width)
  local x = item.icon and 34 or 10
  local room = width - x - (item.hint and 78 or 30)
  local lines = Keys.wrap(item.label, 13, room, 3, "text", "based") or { item.label }
  local tall = #lines <= 1 and 32 or (12 + #lines * 16)
  local row = UI.frame(content, { Name = item.name or "Item", Size = UDim2.new(1, 0, 0, tall), LayoutOrder = order, Theme = { BackgroundColor3 = "ink" } })
  UI.corner(row, "rSmall")
  if item.icon then
    UI.icon(row, item.icon, 16, item.danger and "bad" or "sub", { Position = UDim2.new(0, 10, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
  end
  UI.text(row, table.concat(lines, "\n"), "label", item.danger and "bad" or "ink", { Position = UDim2.new(0, x, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), TextSize = 13,
    Size = UDim2.new(1, -(x + (item.hint and 78 or 30)), 0, #lines * 16), AutomaticSize = Enum.AutomaticSize.None, TextTruncate = Enum.TextTruncate.None })
  if item.checked then
    UI.icon(row, "check", 15, "accent", { Position = UDim2.new(1, -10, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5) })
  elseif item.hint then
    UI.text(row, item.hint, "mono", "faint", { Position = UDim2.new(1, -10, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5), TextSize = 12 })
  end
  UI.button(row, {
    hover = function(on) Motion.to(row, "BackgroundTransparency", on and T.fill2A or 1, "quick") end,
    click = function()
      UI.sfx("click", 0.6)
      close()
      if item.run then B.try("keys.menu", item.run) end
    end,
  })
  return row
end
-- pick a feature for `key`: every toggle and button the hub has, searchable
function Keys.pick(anchor, key)
  local list = {}
  for id, entry in pairs(Controls.bindables) do
    local bind = Config.bindOf(id)
    if not (bind and bind.key == key) then
      list[#list + 1] = { id = id, label = entry.label, page = entry.page and entry.page.title or "", key = bind and bind.key or nil }
    end
  end
  table.sort(list, function(a, b) return a.label < b.label end)
  return UI.popover(anchor, { width = 300, align = "center", pad = 8, gap = 6 }, function(content, close)
    UI.text(content, "Give " .. keyName(key) .. " a feature", "eyebrow", "faint", { LayoutOrder = 1, TextSize = 12 })
    local _, box = Controls.field(content, { Width = 284, PlaceholderText = "Search " .. #list .. " features" }, function() end)
    box.Parent.LayoutOrder = 2
    local holder = UI.frame(content, { Name = "List", Size = UDim2.new(1, 0, 0, 252), LayoutOrder = 3, ClipsDescendants = true })
    local scroller = UI.scroll(holder, { Size = UDim2.fromScale(1, 1), Name = "Scroll" })
    local rows = UI.frame(scroller, { Name = "Rows", Size = UDim2.new(1, -6, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
    UI.list(rows, "y", 2)
    local made = {}
    for index, feature in ipairs(list) do
      local row = menuRow(rows, index, { name = feature.id, label = feature.label, hint = feature.key and Config.keyLabel(feature.key) or feature.page, run = function()
        Config.bind(feature.id, key)
        Window.toast({ title = feature.label .. " is on " .. keyName(key), text = "Right-click the key to clear it.", icon = "keyboard" })
      end }, close, 278)
      made[index] = { row = row, text = string.lower(feature.label .. " " .. feature.page) }
    end
    if #list == 0 then
      UI.text(rows, "Nothing left to bind: open the other tabs once so their switches are known.", "caption", "sub", { TextWrapped = true, Size = UDim2.new(1, -8, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y })
    end
    box:GetPropertyChangedSignal("Text"):Connect(function()
      local query = string.lower(box.Text)
      for _, item in ipairs(made) do item.row.Visible = query == "" or string.find(item.text, query, 1, true) ~= nil end
    end)
  end)
end
-- what clicking a key opens: what is on it, and what can be done about that
function Keys.menu(anchor, key)
  local features, roles = Keys.on(key), Keys.builtin[key]
  return UI.popover(anchor, { width = 268, align = "center" }, function(content, close)
    local order = 0
    local function add(item) order += 1; return menuRow(content, order, item, close, 256) end
    local head = UI.frame(content, { Name = "Head", Size = UDim2.new(1, 0, 0, 30), LayoutOrder = 0 })
    UI.text(head, keyName(key), "heading", "ink", { Position = UDim2.new(0, 10, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
    UI.text(head, #features == 0 and (roles and roles[1].short or "Free") or (#features .. (#features == 1 and " feature" or " features")), "mono", "faint",
      { Position = UDim2.new(1, -10, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5), TextSize = 12 })
    for _, f in ipairs(features) do
      if f.kind == "toggle" then
        add({ name = "Hold_" .. f.id, label = f.label .. ": only while held", icon = "hand", checked = f.mode == "hold", run = function()
          Config.bind(f.id, key, f.mode == "hold" and "toggle" or "hold")
        end })
      end
      add({ name = "Unbind_" .. f.id, label = "Take " .. f.label .. " off this key", icon = "x", danger = true, run = function() Config.bind(f.id, nil) end })
    end
    for _, role in ipairs(roles or {}) do
      if role.flag then
        add({ name = "Move_" .. role.flag, label = "Move " .. string.lower(role.short) .. " to another key…", icon = "keyboard", run = function()
          Window.toast({ title = "Press a key", text = "Esc cancels · Backspace clears", icon = "keyboard", time = 2.2 })
          Controls.captureKey(function(next, cancelled)
            if not cancelled then Config.set(role.flag, next or "None") end
          end)
        end })
      end
    end
    add({ name = "Bind", label = "Bind a feature to this key…", icon = "plus", run = function() task.defer(Keys.pick, anchor, key) end })
  end)
end
function Keys.clear(key)
  local cleared = 0
  for _, f in ipairs(Keys.on(key)) do
    Config.bind(f.id, nil)
    cleared += 1
  end
  if cleared > 0 then Window.toast({ title = keyName(key) .. " is free again", text = cleared .. (cleared == 1 and " feature taken off it." or " features taken off it."), icon = "keyboard" }) end
  return cleared
end

-- ---------------------------------------------------------------- the board
-- The six looks of a key: its fill and edge (a role and how see-through: the BASED look's theme
-- key first, the other looks' number second), the edge's width, and the colour of its letters.
local STATES = {
  free = { fill = "field", a = { "fill1A", 0 }, edge = "line", ea = { "strokeA", 0 }, thick = 1, ink = "dim", name = "dim" },
  builtin = { fill = "hover", a = { "fill3A", 0 }, edge = "dim", ea = { 0.55, 0.45 }, thick = 1, ink = "text", name = "dim", mark = "faint" },
  off = { fill = "accent", a = { 0.8, 0.8 }, edge = "accent", ea = { 0.35, 0.35 }, thick = 1, ink = "text", name = "text", mark = "accent" },
  held = { fill = "accent", a = { 0.9, 0.9 }, edge = "accent", ea = { 0, 0 }, thick = 1, ink = "text", name = "text", mark = "accent" },
  on = { fill = "accent", a = { 0, 0 }, edge = "accent", ea = { 0, 0 }, thick = 1, ink = "onAccent", name = "onAccent", mark = "onAccent" },
  conflict = { fill = "warn", a = { 0.82, 0.8 }, edge = "warn", ea = { 0, 0 }, thick = 2, ink = "text", name = "text", mark = "warn" },
}
Keys.STATES = STATES
local function stateOf(features, roles)
  local on, hold = false, false
  for _, f in ipairs(features) do
    on = on or f.on
    hold = hold or (f.kind == "toggle" and f.mode == "hold")
  end
  local clash = #features > 1 or (#features > 0 and roles ~= nil)
  local state
  if #features == 0 then state = roles and "builtin" or "free"
  elseif clash then state = "conflict"
  elseif on then state = "on"
  elseif hold then state = "held"
  else state = "off" end
  return state, on, hold, clash
end
Keys.stateOf = stateOf
-- paint a cap (or a swatch of the legend under the board) in `state`
local function dress(kit, parts, state, on)
  local style = STATES[state] or STATES.free
  local based = kit.look == "based"
  tone(kit, parts.cap, "BackgroundColor3", style.fill)
  see(kit, parts.cap, "BackgroundTransparency", (state == "conflict" and on) and 0.3 or (based and style.a[1] or style.a[2]))
  tone(kit, parts.stroke, "Color", style.edge)
  see(kit, parts.stroke, "Transparency", based and style.ea[1] or style.ea[2])
  parts.stroke.Thickness = style.thick
  if parts.label then tone(kit, parts.label, "TextColor3", style.ink) end
  if parts.arrow then tone(kit, parts.arrow, "ImageColor3", style.ink) end
  if parts.what then tone(kit, parts.what, "TextColor3", style.name) end
  if parts.mark then tone(kit, parts.mark, "ImageColor3", style.mark or style.ink) end
end
-- the key's own name that fits `room`, longest first
local function labelFor(key, room, size, kind, look)
  local seen = {}
  for _, text in ipairs({ LONG[key] or Config.keyLabel(key), Config.keyLabel(key), MINI[key] or Config.keyLabel(key) }) do
    if not seen[text] then
      seen[text] = true
      if Keys.textWidth(text, size, kind, look) <= room then return text end
    end
  end
  return nil
end
-- where everything on a cap goes: its key on top (in the middle, or to the left of a badge), the
-- feature's name under it in up to two lines, or the group's mark when the name will not fit whole
local function arrange(entry, name, markIcon, badge, on)
  local view = entry.view
  local kit, look = view.kit, view.look
  local w, h = entry.width, entry.height
  local keyKind = kinds(look)
  local size = entry.label.TextSize
  local content = name ~= nil
  local arrow = entry.arrow
  local label, what, mark, sign = entry.label, entry.what, entry.mark, entry.badge
  -- the badge (held, or two on the key): top right if the key's name leaves room, else bottom right
  local low = false
  local text
  if arrow then
    text = ""
    if badge then low = 14 + 16 + 8 > w end
  elseif badge then
    text = labelFor(entry.key, w - 8 - 16, size, keyKind, look)
    if not text then
      low = true
      text = labelFor(entry.key, w - 6, size, keyKind, look) or (MINI[entry.key] or Config.keyLabel(entry.key))
    end
  else
    text = labelFor(entry.key, w - 6, size, keyKind, look) or (MINI[entry.key] or Config.keyLabel(entry.key))
  end
  label.Text = text
  local textW = Keys.textWidth(text, size, keyKind, look)
  local besideBadge = badge and not low and (w / 2 + textW / 2 > w - 18)
  if not content and not badge then
    label.AnchorPoint, label.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
    label.Size, label.TextXAlignment = UDim2.fromOffset(w - 4, 16), Enum.TextXAlignment.Center
  -- (2026-11-09, read live with the real fonts: a 12 px line is 16 px tall (GeistMono and the rest); a 14 px box left
  -- every key's letter "not fitting" and a two-line name 1 px short. So the letter's box is 16, from 3 down)
  elseif besideBadge then
    label.AnchorPoint, label.Position = Vector2.new(0, 0), UDim2.fromOffset(4, 3)
    label.Size, label.TextXAlignment = UDim2.fromOffset(w - 8 - 16, 16), Enum.TextXAlignment.Left
  else
    label.AnchorPoint, label.Position = Vector2.new(0.5, 0), UDim2.new(0.5, 0, 0, 3)
    label.Size, label.TextXAlignment = UDim2.fromOffset(w - 4, 16), Enum.TextXAlignment.Center
  end
  if arrow then
    arrow.AnchorPoint = Vector2.new(0.5, 0.5)
    arrow.Position = (content or badge) and UDim2.new(0.5, (badge and not low) and -6 or 0, 0, 11) or UDim2.fromScale(0.5, 0.5)
  end
  -- the badge
  sign.Visible = badge ~= nil
  if badge then
    UI.setIcon(sign, BADGES[badge].icon)
    tone(kit, sign, "ImageColor3", badge == "clash" and "warn" or (on and "onAccent" or "accent"))
    sign.Position = low and UDim2.fromOffset(w - 15, h - 15) or UDim2.fromOffset(w - 15, 4)
  end
  -- the name, whole, or the mark of its group
  local lines = nil
  if content and not low then
    lines = Keys.wrap(name, what.TextSize, w - 2, h >= TALL and 2 or 1, select(2, kinds(look)), look)
  end
  what.Text = lines and table.concat(lines, "\n") or (name or "")
  what.Visible = lines ~= nil
  -- (two real 12 px lines are 32 tall: from 19 down to a 1 px margin)
  local area = h - 19 - 1
  what.Position, what.Size = UDim2.new(0.5, 0, 0, 19), UDim2.fromOffset(w - 2, area)
  entry.lines = lines and #lines or 0
  local marked = content and not lines and not low and markIcon ~= nil
  mark.Visible = marked
  if marked then
    UI.setIcon(mark, markIcon)
    mark.Position = UDim2.new(0.5, 0, 0, 19 + math.floor((area - 16) / 2))
  end
end
local function paint(entry)
  local key = entry.key
  local features, roles = Keys.on(key), Keys.builtin[key]
  local state, on, hold, clash = stateOf(features, roles)
  entry.features, entry.roles, entry.clash, entry.lit, entry.state, entry.hold = features, roles, clash, on, state, hold
  dress(entry.view.kit, { cap = entry.cap, stroke = entry.stroke, label = entry.label, arrow = entry.arrow, what = entry.what, mark = entry.mark }, state, on)
  local name, markIcon
  if #features > 0 then
    name = features[1].label .. (#features > 1 and ("  +" .. #features - 1) or "")
    markIcon = Keys.group(features[1].group).icon
  elseif roles then
    name = roles[1].short
    markIcon = Keys.group(roles[1].group).icon
  end
  arrange(entry, name, markIcon, clash and "clash" or (hold and "hold" or nil), on)
end
Keys.paint = paint
local repaintQueued = false
local function liveViews()
  for index = #Keys.views, 1, -1 do
    if not Keys.views[index].board.Parent then table.remove(Keys.views, index) end
  end
  return Keys.views
end
-- (2026-11-11) The board and the list under it are on the Keys tab: painted again at once while that tab is showing,
-- and otherwise once, when it next is (Window.lazy). Every press of a bound key came here, and with the menu shut it
-- painted every cap of a board nobody could see. The list on screen (renderHud) is still drawn at once.
local paintBoard = Window.lazy("keys", function()
  for _, view in ipairs(liveViews()) do
    for _, entry in pairs(view.caps) do paint(entry) end
  end
  if Keys.renderList then Keys.renderList() end
end)
function Keys.repaint()
  if repaintQueued then return end
  repaintQueued = true
  task.defer(function()
    repaintQueued = false
    readBuiltins()
    paintBoard()
    if Keys.renderHud then Keys.renderHud() end
  end)
end
-- the legend of the six looks, under the board
local SWATCHES = { { "on", "On" }, { "off", "Off" }, { "held", "Held" }, { "conflict", "Conflict" }, { "builtin", "Built-in" } }
local function swatches(view)
  local kit, look = view.kit, view.look
  local strip = view.states
  for _, child in ipairs(strip:GetChildren()) do child:Destroy() end
  local x = 0
  for _, item in ipairs(SWATCHES) do
    local swatch = UI.frame(strip, { Name = "Swatch_" .. item[1], Position = UDim2.fromOffset(x, 1), Size = UDim2.fromOffset(24, STATES_H - 2) })
    round(kit, swatch, 5)
    local stroke = edge(kit, swatch)
    dress(kit, { cap = swatch, stroke = stroke }, item[1], item[1] == "on")
    local badge = item[1] == "held" and "hold" or (item[1] == "conflict" and "clash" or nil)
    if badge then
      local sign = glyph(kit, swatch, BADGES[badge].icon, 12, badge == "clash" and "warn" or "accent", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
      sign.Name = "Badge"
    end
    x += 24 + GAP
    local words = item[2]
    local wordsW = Keys.textWidth(words, MIN_TEXT, select(2, kinds(look)), look)
    write(kit, strip, words, { size = MIN_TEXT, caption = true, role = "dim", props = { Name = "Says_" .. item[1], Position = UDim2.fromOffset(x, 0),
      Size = UDim2.fromOffset(wordsW + 2, STATES_H) } })
    x += wordsW + 2 + GAP * 3
  end
  return x - GAP * 3
end
local function layoutBoard(view, width)
  local step = boardStep(width, view.look)
  if view.step == step then return end
  view.step = step
  local tall = capHeight(step)
  local boardW, boardH = 15 * step - GAP, boardHeight(step)
  view.width, view.boardW = width, boardW
  view.board.Size = UDim2.fromOffset(boardW, boardH)
  for rowIndex, row in ipairs(ROWS) do
    local units = 0
    local y = (rowIndex - 1) * (tall + GAP)
    for _, item in ipairs(row) do
      if item.key then
        local x = math.floor(units * step + 0.5)
        local w = math.floor((units + item.width) * step + 0.5) - GAP - x
        -- (an even width keeps a key anchored at its centre on whole pixels; the pixel goes to the gap)
        if w % 2 == 1 then w -= 1 end
        local entry = view.caps[item.key]
        entry.width, entry.height = w, tall
        entry.cap.Size = UDim2.fromOffset(w, tall)
        entry.cap.Position = UDim2.fromOffset(x + w / 2, y + tall / 2)
      end
      units += item.width
    end
  end
  local legendY = 4 + boardH + 8
  view.legend.Position, view.legend.Size = UDim2.new(0.5, 0, 0, legendY), UDim2.fromOffset(boardW, LEGEND_H)
  local stripW = swatches(view)
  view.states.Position, view.states.Size = UDim2.new(0.5, 0, 0, legendY + LEGEND_H + GAP), UDim2.fromOffset(stripW, STATES_H)
  view.frame.Size = UDim2.new(1, 0, 0, frameHeight(step))
  for _, entry in pairs(view.caps) do paint(entry) end
end
local RESTING = "Click a key to give it a feature. Right-click a key to clear it. Bound keys light up while their feature is on."
local listening = false
local function listen()
  if listening then return end
  listening = true
  -- a key pressed for real dips on the board: it is the quickest way to find out which one is which
  B.connect(UIS.InputBegan, function(input)
    local key = Config.keyName(input)
    if not key or not Window.showing("keys") then return end
    for _, view in ipairs(liveViews()) do
      local entry = view.caps[key]
      if entry then
        entry.held = true
        Motion.to(entry.scale, "Scale", 0.9, "quick")
      end
    end
  end, "keys.press")
  B.connect(UIS.InputEnded, function(input)
    local key = Config.keyName(input)
    if not key then return end
    for _, view in ipairs(liveViews()) do
      local entry = view.caps[key]
      if entry and entry.held then
        entry.held = false
        Motion.to(entry.scale, "Scale", 1, "bouncy")
      end
    end
  end, "keys.release")
  Theme.changed:connect(function() Keys.repaint() end)
end
local function board(frame)
  local kit = Window.kit(frame)
  local look = kit.look
  readBuiltins()
  listen()
  -- (as wide as the card, so a look that shrinks what is wider than its card leaves this alone)
  local area = UI.frame(frame, { Name = "Area", Size = UDim2.fromScale(1, 1) })
  local view = { kit = kit, look = look, frame = frame, area = area, caps = {} }
  view.board = UI.frame(area, { Name = "Board", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 4), Size = UDim2.fromOffset(Keys.width, Keys.height) })
  view.legend = write(kit, area, RESTING, { size = MIN_TEXT, caption = true, role = "dim", props = { Name = "Legend", AnchorPoint = Vector2.new(0.5, 0),
    TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Center, TextYAlignment = Enum.TextYAlignment.Top } })
  view.states = UI.frame(area, { Name = "States", AnchorPoint = Vector2.new(0.5, 0) })
  for _, row in ipairs(ROWS) do
    for _, item in ipairs(row) do
      if item.key then
        local key = item.key
        -- anchored at its centre, so the press shrinks it in place
        local cap = UI.pressable(view.board, { Name = "Cap_" .. key, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(40, TALL) })
        round(kit, cap, "rSmall")
        local entry = { key = key, cap = cap, scale = UI.scaleOf(cap), view = view, width = 40, height = TALL }
        entry.stroke = edge(kit, cap)
        entry.label = write(kit, cap, "", { mono = look ~= "novoline", bold = look == "novoline", size = MIN_TEXT, role = "dim", props = { Name = "Label" } })
        if ARROWS[key] then entry.arrow = glyph(kit, cap, ARROWS[key].icon, 14, "dim", { Name = "Arrow" }) end
        entry.what = write(kit, cap, "", { size = MIN_TEXT, caption = true, role = "text", props = { Name = "What", AnchorPoint = Vector2.new(0.5, 0),
          TextXAlignment = Enum.TextXAlignment.Center, Visible = false } })
        -- (not "Mark": that is a player's row in the hub's lists)
        entry.mark = glyph(kit, cap, "circle", 16, "accent", { Name = "GroupMark", AnchorPoint = Vector2.new(0.5, 0), Visible = false })
        entry.badge = glyph(kit, cap, "hand", 12, "accent", { Name = "Badge", Visible = false })
        view.caps[key] = entry
        local legend = view.legend
        UI.wire(cap, {
          hover = function(over)
            legend.Text = over and Keys.describe(key, view.boardW, look) or RESTING
            tone(kit, legend, "TextColor3", over and (entry.clash and "warn" or "text") or "dim")
            -- (a wide key grows less, so it never reaches into the gap beside it)
            if not entry.held then Motion.to(entry.scale, "Scale", over and (1 + math.min(0.05, 4 / math.max(entry.width, 1))) or 1, "snappy") end
          end,
          click = function() UI.sfx("click", 0.6); Keys.menu(cap, key) end,
          alt = function() Keys.clear(key) end,
        })
      end
    end
  end
  Keys.views[#Keys.views + 1] = view
  Keys.caps, Keys.legend, Keys.boardView = view.caps, view.legend, view
  layoutBoard(view, roomOf(frame, look))
  -- (the Unnamed and Novoline windows can be made wider: the board follows its card)
  if look ~= "based" then
    local queued = false
    frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
      if queued then return end
      queued = true
      task.defer(function()
        queued = false
        if view.board.Parent then layoutBoard(view, roomOf(frame, look, view.width)) end
      end)
    end)
  end
end
Keys.layoutBoard = layoutBoard

-- ---------------------------------------------------------------- how a key's row lights (the list beside the board and the list on screen)
-- per look: the chip behind the key (role, see-through, lit and not), the key, the name, the wash
local LIT = {
  based = { chip = { "accent", 0, "accent", 0.8 }, key = { "onAccent", "text" }, name = { "text", "dim" }, wash = { "accent", 0.88, "accent", 1 } },
  unnamed = { chip = { "field", 1, "field", 1 }, key = { "accent", "faint" }, name = { "text", "dim" }, wash = { "hover", 0.82, "hover", 1 } },
  novoline = { chip = { "text", 0, "field", 0 }, key = { "back", "dim" }, name = { "text", "dim" }, wash = { "text", 0.93, "text", 1 } },
}
local OWN_LOOK = { chip = { "hover", "fill3A", 0 }, key = "dim", name = "dim" }
local function light(kit, row, on, animate)
  row.on = on
  local lit = LIT[kit.look] or LIT.based
  if row.builtin then
    tone(kit, row.chip, "BackgroundColor3", OWN_LOOK.chip[1])
    see(kit, row.chip, "BackgroundTransparency", kit.look == "based" and OWN_LOOK.chip[2] or OWN_LOOK.chip[3])
    tone(kit, row.key, "TextColor3", OWN_LOOK.key)
    tone(kit, row.name, "TextColor3", OWN_LOOK.name)
    if row.wash then see(kit, row.wash, "BackgroundTransparency", 1) end
    return
  end
  fade(kit, row.chip, "BackgroundColor3", on and lit.chip[1] or lit.chip[3], animate)
  fadeAlpha(kit, row.chip, "BackgroundTransparency", on and lit.chip[2] or lit.chip[4], animate)
  fade(kit, row.key, "TextColor3", on and lit.key[1] or lit.key[2], animate)
  fade(kit, row.name, "TextColor3", on and lit.name[1] or lit.name[2], animate)
  if row.wash then
    tone(kit, row.wash, "BackgroundColor3", on and lit.wash[1] or lit.wash[3])
    fadeAlpha(kit, row.wash, "BackgroundTransparency", on and lit.wash[2] or lit.wash[4], animate)
  end
  -- (the Unnamed list says it in words too, the old menus' way: "(on)", "(off)")
  if row.says then row.says.Text = on and "(on)" or "(off)" end
  if animate and on and row.pop and not Motion.reduced then
    row.pop.Scale = 1.22
    Motion.to(row.pop, "Scale", 1, "bouncy")
  end
end
Keys.light = light

-- ---------------------------------------------------------------- the list beside it
local function renderOne(view)
  local holder, kit, look, frame = view.holder, view.kit, view.look, view.frame
  if not holder.Parent then return end
  for _, child in ipairs(holder:GetChildren()) do
    if child:IsA("GuiObject") then child:Destroy() end
  end
  local width = roomOf(frame, look, view.width)
  view.width = width
  local keyKind, nameKind = kinds(look)
  local binds = Keys.listed(false, true)
  local function done(height)
    holder.Size = UDim2.new(1, 0, 0, height)
    frame.Size = UDim2.new(1, 0, 0, height)
  end
  if #binds == 0 then
    local empty = UI.frame(holder, { Name = "Empty", Size = UDim2.new(1, 0, 0, 78) })
    glyph(kit, empty, "keyboard", 20, "faint", { Position = UDim2.fromOffset(14, 16) })
    write(kit, empty, "Nothing is bound yet", { size = 14, role = "text", props = { Position = UDim2.fromOffset(44, 12), Size = UDim2.new(1, -58, 0, 18) } })
    write(kit, empty, "Click a key on the board, or right-click any switch in the hub and press the key you want for it.", { size = MIN_TEXT, caption = true, role = "dim",
      props = { Position = UDim2.fromOffset(44, 34), Size = UDim2.new(1, -58, 0, 34), TextWrapped = true, TextYAlignment = Enum.TextYAlignment.Top } })
    done(78)
    return
  end
  local y, group, first = 2, nil, true
  for index, bind in ipairs(binds) do
    if bind.group ~= group then
      group = bind.group
      local info = Keys.group(group)
      local head = UI.frame(holder, { Name = "Group_" .. group, Position = UDim2.fromOffset(0, y + (first and 0 or 6)), Size = UDim2.new(1, 0, 0, 22) })
      glyph(kit, head, info.icon, 14, "accent", { Position = UDim2.fromOffset(14, 4) })
      write(kit, head, look == "unnamed" and string.lower(info.label) or info.label, { size = MIN_TEXT, bold = true, role = "faint",
        props = { Name = "Title", Position = UDim2.fromOffset(36, 0), Size = UDim2.new(1, -50, 1, 0) } })
      y += 22 + (first and 0 or 6)
      first = false
    end
    local modeText = bind.kind == "toggle" and (bind.mode == "hold" and "While held" or "Toggle") or "Runs it"
    local modeW = math.max(80, Keys.textWidth(modeText, MIN_TEXT, nameKind, look) + 24)
    local keyText = Config.keyLabel(bind.key)
    local chipW = math.max(58, Keys.textWidth(keyText, MIN_TEXT, keyKind, look) + 20)
    local nameX = 14 + chipW + 12
    local nameRoom = width - nameX - (14 + 26 + 8 + modeW + 12)
    local nameText = look == "unnamed" and string.lower(bind.label) or bind.label
    local lines = Keys.wrap(nameText, 13, nameRoom, 3, nameKind, look) or { nameText }
    local caption = bind.page and (bind.page .. (bind.clash and "  ·  shares its key" or "")) or (bind.clash and "Shares its key" or nil)
    local nameH = #lines * 17
    local rowH = math.max(46, 12 + nameH + (caption and 17 or 0) + 10)
    local row = UI.frame(holder, { Name = "Bind_" .. bind.id, Position = UDim2.fromOffset(0, y), Size = UDim2.new(1, 0, 0, rowH), LayoutOrder = index })
    if binds[index - 1] and binds[index - 1].group == bind.group then
      local rule = UI.frame(row, { Name = "Rule", Size = UDim2.new(1, -28, 0, 1), Position = UDim2.fromOffset(14, 0) })
      tone(kit, rule, "BackgroundColor3", "line")
      see(kit, rule, "BackgroundTransparency", look == "based" and "strokeA" or 0)
    end
    local chip = UI.frame(row, { Name = "Chip", Position = UDim2.new(0, 14, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), Size = UDim2.fromOffset(chipW, 26) })
    round(kit, chip, 7)
    local key = write(kit, chip, keyText, { mono = look ~= "novoline", bold = true, size = MIN_TEXT, role = "text", props = { Name = "Key", Size = UDim2.fromScale(1, 1),
      TextXAlignment = Enum.TextXAlignment.Center } })
    local top = math.floor((rowH - nameH - (caption and 17 or 0)) / 2)
    local name = write(kit, row, table.concat(lines, "\n"), { size = 13, role = "text", props = { Name = "Feature", Position = UDim2.fromOffset(nameX, top),
      Size = UDim2.fromOffset(math.max(nameRoom, 1), nameH) } })
    if caption then
      write(kit, row, caption, { size = MIN_TEXT, caption = true, role = bind.clash and "warn" or "faint", props = { Name = "Page", Position = UDim2.fromOffset(nameX, top + nameH),
        Size = UDim2.fromOffset(math.max(nameRoom, 1), 17) } })
    end
    light(kit, { chip = chip, key = key, name = name }, bind.on, false)
    -- (the Unnamed list on screen writes its keys in brackets; here they sit on a plate)
    if look == "unnamed" then see(kit, chip, "BackgroundTransparency", 0) end
    -- how the key works it: press to flip, hold to keep on, or simply run
    local mode = UI.pressable(row, { Name = "Mode", AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -(14 + 26 + 8), 0.5, 0), Size = UDim2.fromOffset(modeW, 26) })
    tone(kit, mode, "BackgroundColor3", "field")
    see(kit, mode, "BackgroundTransparency", look == "based" and "fill2A" or 0)
    round(kit, mode, 7)
    write(kit, mode, modeText, { size = MIN_TEXT, caption = true, role = bind.kind == "toggle" and "text" or "faint", props = { Size = UDim2.fromScale(1, 1),
      TextXAlignment = Enum.TextXAlignment.Center } })
    if bind.kind == "toggle" then
      UI.wire(mode, { click = function() UI.sfx("click", 0.5); Config.bind(bind.id, bind.key, bind.mode == "hold" and "toggle" or "hold") end })
    end
    local remove = UI.pressable(row, { Name = "Unbind", AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -14, 0.5, 0), Size = UDim2.fromOffset(26, 26) })
    round(kit, remove, 7)
    local cross = glyph(kit, remove, "x", 14, "faint", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
    UI.wire(remove, {
      hover = function(over) tone(kit, cross, "ImageColor3", over and "bad" or "faint") end,
      click = function() UI.sfx("click", 0.5); Config.bind(bind.id, nil) end,
    })
    y += rowH
  end
  done(y + GAP)
end
function Keys.renderList()
  for index = #Keys.lists, 1, -1 do
    local view = Keys.lists[index]
    if view.holder.Parent then renderOne(view) else table.remove(Keys.lists, index) end
  end
end
local function list(frame)
  local kit = Window.kit(frame)
  local holder = UI.frame(frame, { Name = "Bound", Size = UDim2.new(1, 0, 0, 0) })
  local view = { frame = frame, holder = holder, kit = kit, look = kit.look }
  Keys.lists[#Keys.lists + 1] = view
  renderOne(view)
  if kit.look ~= "based" then
    local queued = false
    frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
      if queued then return end
      queued = true
      task.defer(function()
        queued = false
        local width = roomOf(frame, view.look, view.width)
        if holder.Parent and math.abs(width - (view.width or 0)) > 4 then renderOne(view) end
      end)
    end)
  end
end

-- ---------------------------------------------------------------- a list on screen that lights smoothly
-- Rows are kept from one draw to the next: a feature switched on fades its row in (and its key
-- chip pops), switched off it fades back. Only a change of what is shown redraws the rows.
local LIGHT = TweenInfo.new(0.32, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
Keys.LIGHT = LIGHT
-- what the rows show, as one string: equal means only the lights may have changed
function Keys.shape(binds, moving, most)
  local parts = { moving and "m" or "-", tostring(#binds) }
  for index, bind in ipairs(binds) do
    if index > most then break end
    parts[#parts + 1] = bind.id .. "|" .. tostring(bind.key) .. "|" .. tostring(bind.mode) .. "|" .. tostring(bind.label) .. "|" .. tostring(bind.group)
      .. "|" .. tostring(bind.clash) .. "|" .. tostring(bind.builtin)
  end
  return table.concat(parts, ";")
end
-- each look's card: padding, a row's height, the chip's, how its key and names are written
local SKINS = {
  based = { pad = 10, row = 20, chip = 18, chipPad = 6, name = 12, title = 12, titleH = 16, titleKind = "wide", least = 150, base = 0.04,
    words = { "KEYS", "KEYS  ·  DRAG ME, THEN LOCK", "Nothing is bound yet" } },
  unnamed = { pad = 8, row = 18, chip = 18, chipPad = 0, name = 12, title = 12, titleH = 16, titleKind = "mono", least = 170, base = 0, top = 26, centre = true,
    lower = true, brackets = true, words = { "keybinds", "keybinds  (drag, then lock)", "nothing bound yet" } },
  novoline = { pad = 10, row = 20, chip = 18, chipPad = 6, name = 12, title = 12, titleH = 16, titleKind = "bold", least = 160, base = 0,
    words = { "Keybinds", "Keybinds  ·  drag, then lock", "Nothing bound yet" } },
}
Keys.SKINS = SKINS
local TAGS = { hold = "hold", clash = "clash", builtin = "built in" }
-- (the Unnamed list: every switch says how it is, in brackets, as the old menus did)
local BRACKETED = { hold = "(hold)", clash = "(clash)", builtin = "(built in)" }
-- The list on screen in `look`, in `holder`. render(binds, moving, opts) draws it and says how big it
-- is (design px); opts: gap (between rows), columns (at least), groups, opacity (0-100), room (Vector2).
function Keys.panelFor(holder, look)
  local kit = kitOf(look)
  look = kit.look
  local skin = SKINS[look] or SKINS.based
  local keyKind, nameKind = kinds(look)
  local card
  if look == "based" then
    card = UI.glass(holder, { level = "popover", radius = 14, shadow = 20, shadowY = 8, grain = false, props = { Size = UDim2.fromScale(1, 1) } })
  else
    card = Instance.new("Frame")
    card.Name = look == "unnamed" and "KeysUnnamed" or "KeysNovoline"
    card.BorderSizePixel = 0
    card.Size = UDim2.fromScale(1, 1)
    card.Parent = holder
    local parts = B.Novoline and B.Novoline.parts
    if look == "novoline" and parts and parts.glass then parts.glass(card, 18) else
      kit.fill(card, "back")
      kit.outline(card)
    end
    if look == "unnamed" then
      local crown = Instance.new("Frame")
      crown.Name, crown.BorderSizePixel, crown.Size, crown.ZIndex = "Crown", 0, UDim2.new(1, 0, 0, 2), 3
      crown.Parent = card
      kit.paint(crown, "BackgroundColor3", "accent")
    end
  end
  local body = UI.frame(card, { Name = "Body", Size = UDim2.fromScale(1, 1), ZIndex = 2 })
  local api = { frame = card, body = body, rows = {}, shape = nil, w = skin.least, h = 40, look = look, kit = kit }
  function api.forget() api.shape = nil end
  local function measure(bind)
    local keyText = Config.keyLabel(bind.key)
    if skin.brackets then keyText = "[" .. keyText .. "]" end
    local keyW = Keys.textWidth(keyText, MIN_TEXT, keyKind, look)
    local chipW = skin.chipPad > 0 and math.max(30, keyW + skin.chipPad * 2) or (keyW + 2)
    local nameText = skin.lower and string.lower(bind.label) or bind.label
    local nameW = Keys.textWidth(nameText, skin.name, nameKind, look) + 2
    local words = skin.brackets and BRACKETED or TAGS
    local tag = bind.builtin and words.builtin or (bind.clash and words.clash) or ((bind.kind == "toggle" and bind.mode == "hold") and words.hold) or nil
    local live = false
    if not tag and skin.brackets and bind.kind == "toggle" then tag, live = bind.on and "(on)" or "(off)", true end
    local tagW = tag and (Keys.textWidth(tag, MIN_TEXT, nameKind, look) + 2) or 0
    -- (room for the longer of the two, so the row keeps its width when the switch flips)
    if live then tagW = math.max(Keys.textWidth("(on)", MIN_TEXT, nameKind, look), Keys.textWidth("(off)", MIN_TEXT, nameKind, look)) + 2 end
    return { bind = bind, keyText = keyText, chipW = chipW, nameText = nameText, nameW = nameW, tag = tag, tagW = tagW, live = live,
      w = chipW + 8 + nameW + (tag and (8 + tagW) or 0), h = skin.row }
  end
  -- the items into at most `columns` columns no taller than `limit`, a group's name never last in one
  local function pack(items, gapY, limit)
    local cols, col = {}, nil
    for index, item in ipairs(items) do
      local need = item.h
      if item.head and items[index + 1] then need += gapY + items[index + 1].h end
      if col and #col.items > 0 and col.h + gapY + need > limit then col = nil end
      if not col then
        col = { items = {}, h = 0, w = 0 }
        cols[#cols + 1] = col
      else
        col.h += gapY
      end
      item.y = col.h
      col.items[#col.items + 1] = item
      col.h += item.h
      col.w = math.max(col.w, item.w)
    end
    return cols
  end
  local function layout(binds, gapY, want, grouped, room)
    local colGap = math.max(16, gapY * 2)
    local top = skin.top or (skin.pad + skin.titleH + math.max(GAP, gapY))
    local headH = 16
    local function itemsOf(count)
      local items, last = {}, nil
      for index = 1, count do
        local bind = binds[index]
        if grouped and bind.group ~= last then
          last = bind.group
          local info = Keys.group(last)
          local words = skin.lower and string.lower(info.label) or info.label
          items[#items + 1] = { head = info, words = words, h = headH, w = 12 + 6 + Keys.textWidth(words, MIN_TEXT, nameKind, look) + 2 }
        end
        items[#items + 1] = measure(bind)
      end
      if count < #binds then
        local words = "+" .. (#binds - count) .. " more"
        items[#items + 1] = { more = true, words = words, h = 16, w = Keys.textWidth(words, MIN_TEXT, nameKind, look) + 2 }
      end
      return items
    end
    local count = #binds
    while true do
      local items = itemsOf(count)
      local total, tallest = 0, 0
      for index, item in ipairs(items) do total += item.h + (index > 1 and gapY or 0); tallest = math.max(tallest, item.h) end
      for columns = want, 4 do
        local limit = math.max(math.ceil(total / columns), tallest + (items[1] and items[1].head and (gapY + skin.row) or 0))
        local cols = pack(items, gapY, limit)
        while #cols > columns do
          limit += math.max(2, math.floor(limit * 0.05))
          cols = pack(items, gapY, limit)
        end
        local w, h = skin.pad * 2, 0
        for index, col in ipairs(cols) do w += col.w + (index > 1 and colGap or 0); h = math.max(h, col.h) end
        h += top + skin.pad
        if (w <= room.X and h <= room.Y) or (columns == 4 and count <= 1) then return items, cols, colGap, top end
      end
      if count <= 1 then return itemsOf(count), pack(itemsOf(count), gapY, math.huge), colGap, top end
      count -= 1
    end
  end
  function api.render(binds, moving, opts)
    local gapY = math.max(GAP, math.floor(opts.gap or 8))
    local want = math.clamp(math.floor(opts.columns or 1), 1, 4)
    local grouped = opts.groups ~= false
    local room = opts.room or Vector2.new(1200, 900)
    local opacity = math.clamp((opts.opacity or 100) / 100, 0, 1)
    card.BackgroundTransparency = 1 - (1 - skin.base) * opacity
    local shape = table.concat({ look, gapY, want, tostring(grouped), math.floor(room.X / 8), math.floor(room.Y / 8), Keys.shape(binds, moving, 200) }, "#")
    if shape == api.shape then
      for _, bind in ipairs(binds) do
        local row = api.rows[bind.id]
        if row and row.on ~= bind.on then light(kit, row, bind.on, true) end
      end
      return api.w, api.h
    end
    api.shape = shape
    local before = {}
    for id, row in pairs(api.rows) do before[id] = row.on end
    table.clear(api.rows)
    for _, child in ipairs(body:GetChildren()) do child:Destroy() end
    local titleText = moving and skin.words[2] or skin.words[1]
    local titleW = Keys.textWidth(titleText, skin.title, skin.titleKind, look) + 2
    local _, cols, colGap, top = layout(binds, gapY, want, grouped, room)
    local w = skin.pad * 2
    for index, col in ipairs(cols) do w += col.w + (index > 1 and colGap or 0) end
    local h = 0
    for _, col in ipairs(cols) do h = math.max(h, col.h) end
    if #binds == 0 then
      local words = skin.words[3]
      local wordsW = Keys.textWidth(words, MIN_TEXT, nameKind, look) + 2
      write(kit, body, words, { size = MIN_TEXT, caption = true, role = "dim", props = { Name = "Empty", Position = UDim2.fromOffset(skin.pad, top), Size = UDim2.fromOffset(wordsW, 16) } })
      w, h = math.max(w, skin.pad * 2 + wordsW), 16
    end
    w = math.max(w, skin.least, titleW + skin.pad * 2)
    h = top + h + skin.pad
    -- the title: top left, or (Unnamed) in the middle over its line
    local title = write(kit, body, titleText, { size = skin.title, wide = look == "based", bold = look ~= "based", role = moving and "accent" or "faint",
      props = { Name = "Title" } })
    if skin.centre then
      title.Position, title.Size, title.TextXAlignment = UDim2.fromOffset(0, 3), UDim2.new(1, 0, 0, skin.titleH), Enum.TextXAlignment.Center
    else
      title.Position, title.Size = UDim2.fromOffset(skin.pad, skin.pad), UDim2.fromOffset(titleW, skin.titleH)
    end
    local x = skin.pad
    for index, col in ipairs(cols) do
      if index > 1 then x += colGap end
      for _, item in ipairs(col.items) do
        local y = top + item.y
        if item.head then
          local head = UI.frame(body, { Name = "Group_" .. item.head.id, Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(item.w, item.h) })
          glyph(kit, head, item.head.icon, 12, "accent", { Position = UDim2.fromOffset(0, 2) })
          write(kit, head, item.words, { size = MIN_TEXT, bold = true, role = "faint", props = { Name = "Words", Position = UDim2.fromOffset(18, 0), Size = UDim2.fromOffset(item.w - 18, item.h) } })
        elseif item.more then
          write(kit, body, item.words, { size = MIN_TEXT, caption = true, role = "faint", props = { Name = "More", Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(item.w, item.h) } })
        else
          local bind = item.bind
          local line = UI.frame(body, { Name = (bind.builtin and "Own_" or "Bind_") .. bind.id, Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(item.w, item.h) })
          local wash = UI.frame(line, { Name = "Wash", Size = UDim2.new(1, 8, 1, 0), Position = UDim2.fromOffset(-4, 0) })
          round(kit, wash, 6)
          local chipH = skin.chip
          local chip = UI.frame(line, { Name = "Chip", Position = UDim2.fromOffset(0, math.floor((item.h - chipH) / 2)), Size = UDim2.fromOffset(item.chipW, chipH) })
          if look == "novoline" then round(kit, chip, true) else round(kit, chip, 6) end
          local pop = Instance.new("UIScale"); pop.Parent = chip
          local key = write(kit, chip, item.keyText, { mono = look ~= "novoline", bold = true, size = MIN_TEXT, role = "text", props = { Name = "Key", Size = UDim2.fromScale(1, 1),
            TextXAlignment = Enum.TextXAlignment.Center } })
          local name = write(kit, line, item.nameText, { size = skin.name, caption = look == "based", role = "dim", props = { Name = "Feature",
            Position = UDim2.fromOffset(item.chipW + 8, 0), Size = UDim2.fromOffset(item.nameW, item.h) } })
          local said
          if item.tag then
            said = write(kit, line, item.tag, { size = MIN_TEXT, caption = true, role = bind.clash and not bind.builtin and "warn" or "faint", props = { Name = "Tag",
              Position = UDim2.fromOffset(item.chipW + 8 + item.nameW + 8, 0), Size = UDim2.fromOffset(item.tagW, item.h) } })
          end
          local row = { chip = chip, wash = wash, key = key, name = name, pop = pop, builtin = bind.builtin == true, says = item.live and said or nil }
          api.rows[bind.id] = row
          local was = before[bind.id]
          light(kit, row, was == nil and bind.on or was, false)
          if was ~= nil and was ~= bind.on then light(kit, row, bind.on, true) end
        end
      end
      x += col.w
    end
    api.w, api.h = w, h
    return w, h
  end
  return api
end
-- (the BASED card on its own, as it was asked for before there were three)
function Keys.basedPanel(holder) return Keys.panelFor(holder, "based") end
-- the look the list on screen is drawn in: the look in use
function Keys.lookNow()
  local look = Window.look and Window.look() or "based"
  if not (Window.kits and Window.kits[look]) then return "based" end
  return look
end
-- how big it is drawn: the hub's own size and its own. (2026-11-09, the owner: "keys mini layout looks really massive, shrink
-- it to the good size": it was made bigger on a taller screen too, x1.3 on 1440, with 26 px rows and the group names: some 800 px
-- tall for 14 keys. Now 12 px letters on every screen, 20 px rows, 6 apart, no group names unless asked for)
function Keys.hudScale()
  return ((Config.get("app.scale") or 100) / 100) * ((Config.get("app.keyHudSize") or 100) / 100)
end
-- what else is on screen that the list must keep clear of: the island, the hunt panel, the target
-- list and the status line, Unnamed's watermark, Novoline's dock (rects in the HUD layer's px)
local KEEP = { Island = true, MusicIsland = true, Watermark = true, Hunt = true, Dock = true, Targets = true, Status = true }
-- (on screen: it and every frame it is in up to its screen are shown; the HUD layer and the screens
-- themselves are the hub's and never hidden)
local function shown(item)
  local up = item
  while up and up ~= Window.hud and up:IsA("GuiObject") do
    if up.Visible == false then return false end
    up = up.Parent
  end
  return true
end
function Keys.keepOuts()
  local out, seen = {}, {}
  if not Window.hud then return out end
  local origin = Window.hud.AbsolutePosition
  local function scan(parent)
    for _, child in ipairs(parent:GetChildren()) do
      if KEEP[child.Name] and not seen[child] and child:IsA("GuiObject") and child ~= Keys.panel and shown(child) then
        seen[child] = true
        local size = child.AbsoluteSize
        if size.X > 1 and size.Y > 1 then out[#out + 1] = { p = child.AbsolutePosition - origin, s = size, name = child.Name } end
      end
    end
  end
  scan(Window.hud)
  for _, gui in ipairs(B.screens or {}) do
    if gui.Parent then scan(gui) end
  end
  return out
end
local MARGIN = 8
local function hits(p, size, rect)
  return p.X < rect.p.X + rect.s.X and rect.p.X < p.X + size.X and p.Y < rect.p.Y + rect.s.Y and rect.p.Y < p.Y + size.Y
end
-- the nearest place to `at` where a box of `size` is whole on screen and clear of every rect
function Keys.clearOf(at, size, rects, layer)
  local function free(p)
    if p.X < MARGIN - 0.5 or p.Y < MARGIN - 0.5 or p.X + size.X > layer.X - MARGIN + 0.5 or p.Y + size.Y > layer.Y - MARGIN + 0.5 then return false end
    for _, rect in ipairs(rects) do
      if hits(p, size, rect) then return false end
    end
    return true
  end
  if free(at) then return at end
  local apart = GAP * 2
  local xs, ys = { at.X }, { at.Y }
  for _, rect in ipairs(rects) do
    xs[#xs + 1] = rect.p.X - size.X - apart
    xs[#xs + 1] = rect.p.X + rect.s.X + apart
    ys[#ys + 1] = rect.p.Y - size.Y - apart
    ys[#ys + 1] = rect.p.Y + rect.s.Y + apart
  end
  local best, far = nil, math.huge
  for _, x in ipairs(xs) do
    for _, y in ipairs(ys) do
      local p = Vector2.new(x, y)
      local d = (p - at).Magnitude
      if d < far and free(p) then best, far = p, d end
    end
  end
  return best or at
end

-- ---------------------------------------------------------------- the list on screen
-- While the hub is hidden: each bound feature with its key, lit while it is on. It sits in the
-- bottom right corner until it is put somewhere else: unlocked (Keys tab), it shows with the hub
-- open too and goes where it is dragged; locked again, it stays there. Wherever it is, it is kept
-- whole on screen and clear of the island, the hunt panel and the target list; a list too long for
-- the screen goes into more columns, and what still does not fit is counted.
function Keys.hud()
  if Keys.panel or not Window.hud then return end
  local holder = UI.frame(Window.hud, { Name = "KeyList", AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -16, 1, -16), Size = UDim2.fromOffset(170, 40),
    Visible = false })
  local function unlocked() return Config.get("app.keyHudLock") == false end
  local sizer = Instance.new("UIScale"); sizer.Scale = Keys.hudScale(); sizer.Parent = holder
  Keys.sizer = sizer
  local dragging = false
  -- where it goes: `put` (a share of the screen, while it is dragged), else where it was left, else the corner
  local function place(put)
    local layer = Window.hud.AbsoluteSize
    if layer.X < 2 or layer.Y < 2 then return end
    local size = Vector2.new(holder.Size.X.Offset, holder.Size.Y.Offset) * sizer.Scale
    local x, y
    if put then x, y = put.X, put.Y else x, y = Config.get("app.keyHudX"), Config.get("app.keyHudY") end
    local anchor, sx, sy, ox, oy
    if type(x) == "number" and type(y) == "number" and x >= 0 and y >= 0 then
      anchor, sx, sy, ox, oy = Vector2.new(0.5, 0.5), math.clamp(x, 0.02, 0.98), math.clamp(y, 0.02, 0.98), 0, 0
    else
      anchor, sx, sy, ox, oy = Vector2.new(1, 1), 1, 1, -16, -16
    end
    local want = Vector2.new(sx * layer.X + ox, sy * layer.Y + oy) - anchor * size
    local at = Vector2.new(math.clamp(want.X, MARGIN, math.max(MARGIN, layer.X - size.X - MARGIN)), math.clamp(want.Y, MARGIN, math.max(MARGIN, layer.Y - size.Y - MARGIN)))
    if not put then at = Keys.clearOf(at, size, Keys.keepOuts(), layer) end
    local nudge = at - want
    holder.AnchorPoint = anchor
    holder.Position = UDim2.new(sx, ox + math.floor(nudge.X + 0.5), sy, oy + math.floor(nudge.Y + 0.5))
  end
  Keys.place = place
  -- three looks, each drawn its own way: the BASED glass card, the Unnamed box, Novoline's dark card.
  -- Never one with another look's window.
  local style, panel
  local function dress()
    if panel then panel.frame:Destroy(); panel = nil end
    style = Keys.lookNow()
    panel = Keys.panelFor(holder, style)
    Keys.panelApi = panel
  end
  dress()
  Keys.panel = holder
  -- the hand it is moved by: over all of it, and only there while it is unlocked
  local grip = UI.new("TextButton", { Name = "Move", Text = "", AutoButtonColor = false, BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 20, Visible = false, Parent = holder })
  local from, moved
  UI.drag(grip, function(point)
    local centre = holder.AbsolutePosition + holder.AbsoluteSize / 2
    from = centre - point
    dragging, moved = true, false
    return true
  end, function(point)
    local layer = Window.hud
    local size = layer.AbsoluteSize
    if size.X < 1 or size.Y < 1 then return end
    local at = point + from - layer.AbsolutePosition
    moved = true
    place(Vector2.new(math.clamp(at.X / size.X, 0.02, 0.98), math.clamp(at.Y / size.Y, 0.02, 0.98)))
  end, function()
    dragging = false
    if not moved then return end
    -- (both read before either is kept: keeping one seats the list again, by the other's old value)
    local x, y = holder.Position.X.Scale, holder.Position.Y.Scale
    Config.set("app.keyHudX", x)
    Config.set("app.keyHudY", y)
  end)
  local function own() return Config.get("app.keyHudOwn") == true end
  local function shouldShow()
    if Config.get("app.keyHud") == false then return false end
    if unlocked() then return true end
    return not Window.anyOpen() and (next(Config.binds) ~= nil or own())
  end
  local lastLayer = nil
  function Keys.renderHud()
    if not holder.Parent then return end
    if Keys.lookNow() ~= style then dress() end
    sizer.Scale = Keys.hudScale()
    local grouped = Config.get("app.keyHudGroups") ~= false
    local binds = Keys.listed(own(), grouped)
    local moving = unlocked()
    grip.Visible = moving
    holder.Visible = shouldShow() and (#binds > 0 or moving)
    if not holder.Visible then return end
    local layer = Window.hud.AbsoluteSize
    lastLayer = layer
    -- (room for it: two thirds of the screen's height and three fifths of its width at most, so a
    -- long list goes into columns before it climbs to the island, and the middle stays clear)
    local room = Vector2.new(math.max(170, layer.X * 0.6 - MARGIN * 2), math.max(120, layer.Y * 0.66 - MARGIN * 2)) / math.max(sizer.Scale, 0.1)
    local w, h = panel.render(binds, moving, { gap = Config.get("app.keyHudGap"), columns = Config.get("app.keyHudColumns"), groups = grouped,
      opacity = Config.get("app.keyHudOpacity"), room = room })
    holder.Size = UDim2.fromOffset(w, h)
    if not dragging then place() end
  end
  Window.onShow:connect(function() Keys.renderHud() end)
  -- A bound button lights too: while what it started goes on (an emote playing), or for a moment
  -- after its key. Pressed: drawn at once; then looked at five times a second, drawn only on a change.
  local lit = ""
  local function litNow()
    local parts = {}
    for id, bind in pairs(Config.binds) do
      if bind.key and Config.isAction(id) and Config.isActive(id) then parts[#parts + 1] = id end
    end
    table.sort(parts)
    return table.concat(parts, ",")
  end
  Config.actionRan:connect(function() lit = litNow(); Keys.renderHud() end)
  Motion.every(function()
    if not holder.Visible then return end
    local now = litNow()
    if now ~= lit then lit = now; Keys.renderHud(); return end
    -- the screen or the size changed: drawn again; else only kept clear of what came up beside it
    if math.abs(Keys.hudScale() - sizer.Scale) > 0.001 or Window.hud.AbsoluteSize ~= lastLayer then Keys.renderHud(); return end
    if not dragging then place() end
  end, 5, "keys.lit")
  for _, id in ipairs({ "app.keyHud", "app.keyHudLock", "app.gui", "app.scale", "app.keyHudSize", "app.keyHudGap", "app.keyHudOpacity", "app.keyHudColumns",
    "app.keyHudGroups", "app.keyHudOwn" }) do
    Config.on(id, function() Keys.renderHud() end)
  end
  -- (another look's letters are other widths: measured again once that look has them)
  for _, id in ipairs({ "app.unnamed.font", "app.unnamed.textSize", "app.novoline.font" }) do
    Config.on(id, function()
      task.defer(function()
        if panel and panel.forget then panel.forget() end
        Keys.renderHud()
        Keys.repaint()
      end)
    end)
  end
  Theme.changed:connect(function() if panel and panel.forget then panel.forget() end; Keys.renderHud() end)
  Config.on("app.keyHudX", function() place() end)
  Config.on("app.keyHudY", function() place() end)
  Keys.renderHud()
end

-- ---------------------------------------------------------------- the tab
function Keys.define()
  Config.define("app.keyHud", true)
  Config.define("app.keyHudLock", true)
  Config.define("app.keyHudX", -1)          -- where it was put, as a share of the screen; under 0: the corner
  Config.define("app.keyHudY", -1)
  Config.define("app.keyHudSize", 100)      -- the list on screen: how big (%), the room between rows (px),
  Config.define("app.keyHudGap", 6)         -- how solid its card is (%), how many columns at least,
  Config.define("app.keyHudOpacity", 100)   -- grouped or not, and the hub's own keys in it or not
  Config.define("app.keyHudColumns", 1)
  Config.define("app.keyHudGroups", false)
  Config.define("app.keyHudOwn", false)
end
B.pages[#B.pages + 1] = function()
  Keys.define()
  -- anything that changes what a key does, or whether a bound feature is on, redraws the board
  Config.bindsChanged:connect(function() Keys.repaint() end)
  Config.changed:connect(function(id)
    if Config.binds[id] or id == "app.key.menu" or id == "app.key.panic" or id == "fly.key.boost" or id == "fly.key.down" then Keys.repaint() end
  end)
  Config.loaded:connect(function() Keys.repaint() end)
  Window.page({ id = "keys", title = "Keys", icon = "keyboard", group = "Hub", order = 890, eyebrow = "What every key does", build = function(page)
    local map = page:section({ title = "Your keyboard", icon = "keyboard", full = true, desc = "Every key the hub listens to, and what it does." })
    map:custom({ height = frameHeight(boardStep(ROOM.based, "based")), name = "Keyboard", build = board })

    local bound = page:section({ title = "Bound features", icon = "link", full = true, desc = "By group: movement, combat, visuals, flight, the hub." })
    bound:custom({ name = "List", build = list })

    local own = page:section({ title = "The hub's own keys", icon = "command", column = 1, weight = 6 })
    own:keybind({ tip = "The key that opens and closes the hub.", id = "app.key.menu", label = "Open / close the hub" })
    own:keybind({ id = "app.key.panic", label = "Panic", desc = "Unloads BASED instantly." })
    own:keybind({ id = "fly.key.boost", label = "Flight: boost", tip = "Hold to fly faster.", default = "LeftShift" })
    own:keybind({ id = "fly.key.down", label = "Flight: come down", tip = "Hold to go down.", default = "LeftControl" })
    own:button({ label = "Clear every bound key", desc = "The hub's own keys are kept.", text = "Clear", style = "danger", bindable = false, run = function()
      local cleared = 0
      for id in pairs(table.clone(Config.binds)) do Config.bind(id, nil); cleared += 1 end
      Window.toast({ title = cleared == 0 and "Nothing was bound" or "Keys cleared", text = cleared > 0 and (cleared .. " features are off their keys.") or nil, icon = "keyboard" })
    end })

    local screen = page:section({ title = "On screen", icon = "monitor", column = 2, weight = 6 })
    screen:toggle({ id = "app.keyHud", label = "Show my keys on screen", desc = "A list while the hub is hidden, lit for what is on.", bindable = false })
    screen:toggle({ id = "app.keyHudLock", label = "Lock where it sits", desc = "Off: drag the list anywhere. On: it stays.", bindable = false })
    screen:button({ label = "Back to the corner", desc = "Moves the list back to the bottom right.", text = "Reset", bindable = false, run = function()
      Config.set("app.keyHudX", -1)
      Config.set("app.keyHudY", -1)
    end })
    screen:slider({ id = "app.keyHudSize", label = "Size", min = 75, max = 175, step = 5, default = 100, suffix = "%", desc = "How big the list is drawn." })
    screen:slider({ id = "app.keyHudGap", label = "Spacing", min = 6, max = 16, step = 1, default = 6, suffix = " px", desc = "Room between the rows." })
    screen:slider({ id = "app.keyHudOpacity", label = "Opacity", min = 20, max = 100, step = 5, default = 100, suffix = "%", desc = "How solid the card behind it is." })
    screen:slider({ id = "app.keyHudColumns", label = "Columns", min = 1, max = 4, step = 1, default = 1, desc = "Side by side. More come if it would not fit." })
    screen:toggle({ id = "app.keyHudGroups", label = "Group them", default = false, desc = "Movement, combat, visuals, flight, the hub.", bindable = false })
    screen:toggle({ id = "app.keyHudOwn", label = "The hub's keys too", desc = "Adds Menu, Panic and the flight keys.", bindable = false })
  end })
end
end
do -- 52_unnamed.lua
-- ============================================================================
--  52 unnamed    the second look: the Unnamed hub's menu, drawn as its library draws it
--
--  The same tabs and the same settings as the BASED window. Every control here
--  is bound to the very flag its BASED twin is, so the two windows always agree
--  and either one can be used. One is shown at a time: Settings > Menu style,
--  or the button at the top of either window.
--
--  2026-11-14: redrawn from the Unnamed hub's own library, number for number
--  (_work/polish-1114/UNNAMED-MENU.md has every size and where it was read):
--  a 550 x 650 window in Roboto Mono, every text with a black line round it,
--  a 25 px title row, tabs as wide as their names, boxes with a coloured line
--  on top, a 13 px square to tick, a bar with its name above it and value/max
--  written on it, a 20 px box that opens a list. A control lights only its
--  outer line when the mouse is on it. What is the hub's own stays: the search
--  box and the way back to BASED (in the title row, left), a key on a row
--  (right click), a typed number on a bar (right click), boxes the full width.
--
--  A tab's own drawing (a custom block) can give a version of itself for this
--  window (page:custom(height, build, alt)); one that does not is drawn as it
--  is, inside a box.
-- ============================================================================
local S, util, Motion, UI, Config, Window, Controls = B.S, B.util, B.Motion, B.UI, B.Config, B.Window, B.Controls
local UIS = S.UserInputService
local U = { open = false, built = false, pages = {}, tabs = {} }
B.Unnamed = U

-- (2026-11-16, a player's clip: switches drawn ON that would not turn off. `id and Config.define(...) or default` falls
-- through to the default when the saved value is false: a switch that ships on and was saved off was drawn on, and a
-- click asked for "off", which it already was, so nothing moved. These two never fall through.)
local function initial(id, default)
  if id then return Config.define(id, default) end
  return default
end
local function orDefault(value, fallback)
  if value ~= nil then return value end
  return fallback
end
local function rgb(r, g, b) return Color3.fromRGB(r, g, b) end
-- Their theme: one grey for the window and what can be clicked (main), a darker one for the page and its boxes (page),
-- a line colour, black for every outer line, white letters. The older names are kept beside them: other parts read U.C.
local C = {
  main = rgb(24, 24, 24), page = rgb(20, 20, 20), line = rgb(31, 31, 31), black = rgb(0, 0, 0),
  text = rgb(255, 255, 255), dim = rgb(170, 170, 170), faint = rgb(120, 120, 120), hint = rgb(190, 190, 190), risk = rgb(255, 0, 0),
  back = rgb(24, 24, 24), frame = rgb(24, 24, 24), box = rgb(20, 20, 20), edge = rgb(31, 31, 31), dark = rgb(0, 0, 0),
  field = rgb(24, 24, 24), fieldHi = rgb(31, 31, 31), tab = rgb(20, 20, 20), tabOn = rgb(24, 24, 24), tabEdge = rgb(25, 25, 25),
}
U.C = C
local ACCENT = rgb(71, 119, 182)
local W, H = 550, 650                  -- design pixels, as theirs; scaled only by the user's own app.scale
local FILL = TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
local CURSOR = "http://www.roblox.com/asset/?id=4292970642"
local FONT, BOLD

-- ---------------------------------------------------------------- the letters
-- Settings > Unnamed letters. Roboto Mono first: the face their menu is drawn in.
-- `size` is how big each set is drawn against the size the menu asks for, so each reads at
-- about the same height (measured in game: the height of "Hg" against Arial's).
local FONTS = {
  { "roboto", "Roboto Mono", function() return Font.fromEnum(Enum.Font.RobotoMono) end, 1 },
  { "monocraft", "Monocraft", function() return B.F.craft end, 1 },
  { "proggy", "Proggy Clean", function() return B.F.proggy end, 1.25 },
  { "proggytiny", "Proggy Tiny", function() return B.F.proggyTiny end, 1.35 },
  { "arial", "Arial", function() return Font.fromEnum(Enum.Font.Arial) end, 1 },
  { "builder", "Builder Sans", function() return Font.fromName("BuilderSans") end, 1 },
  { "gotham", "Gotham", function() return Font.fromName("GothamSSm") end, 0.95 },
  { "ubuntu", "Ubuntu", function() return Font.fromName("Ubuntu") end, 1 },
  { "inter", "Inter", function() return (B.F0 or B.F).text500 end, 0.97 },
  { "geist", "Geist Mono", function() return (B.F0 or B.F).mono400 end, 0.95 },
  { "arcade", "Arcade", function() return Font.fromEnum(Enum.Font.Arcade) end, 0.75 },
  { "michroma", "Michroma", function() return Font.fromName("Michroma") end, 0.85 },
  { "jura", "Jura", function() return Font.fromName("Jura") end, 1.05 },
  { "sarpanch", "Sarpanch", function() return Font.fromName("Sarpanch") end, 1.05 },
  { "titillium", "Titillium", function() return Font.fromName("TitilliumWeb") end, 1.02 },
}
U.FONTS = FONTS
-- Every label and box drawn here, with its size at 100%. Kept STRONG and swept: a weak-keyed table
-- of Instances loses entries while they are still on screen (their Lua handle is collected and a new
-- one made later), and those labels never took a newly picked font. That was the "fonts don't
-- change fully" bug: whatever had been collected kept the old letters.
local typed = {}
local bolded = {}
local factor = 1
U.fontChanged = B.Signal.new()
local function fontSpec(id)
  for _, spec in ipairs(FONTS) do if spec[1] == id then return spec end end
  return FONTS[1]
end
local function sizeOf(base) return math.max(6, math.floor(base * factor + 0.5)) end
local function pickFont()
  local spec = fontSpec(Config.get("app.unnamed.font"))
  local ok, face = pcall(spec[3])
  FONT = (ok and typeof(face) == "Font") and face or Font.fromEnum(Enum.Font.RobotoMono)
  local okBold, bold = pcall(Font.new, FONT.Family, Enum.FontWeight.Bold, FONT.Style)
  BOLD = okBold and bold or FONT
  factor = spec[4] * ((Config.get("app.unnamed.textSize") or 100) / 100)
end
-- a label or a box takes the menu's letters, and keeps them when they change
local function letters(item, base, bold)
  if not FONT then pickFont() end
  typed[item] = base
  if bold then bolded[item] = true end
  item.FontFace = bold and BOLD or FONT
  item.TextSize = sizeOf(base)
  return item
end
local function refont()
  pickFont()
  for item, base in pairs(typed) do
    if item.Parent then
      item.FontFace = bolded[item] and BOLD or FONT
      item.TextSize = sizeOf(base)
    else
      typed[item], bolded[item] = nil, nil
    end
  end
  U.fontChanged:fire()
end
-- (gone ones swept now and then, so a menu rebuilt many times does not keep them all)
local function sweepTyped()
  for item in pairs(typed) do
    if not item.Parent then typed[item], bolded[item] = nil, nil end
  end
end
U.sweepTyped = sweepTyped
function U.font() if not FONT then pickFont() end return FONT, BOLD end
-- (drawn in this look's letters: the BASED font setting leaves it alone)
function U.owns(item) return typed[item] ~= nil end
-- how wide a text is at a size of this menu (their tabs and key boxes are as wide as their words)
local function measure(value, base)
  local size = sizeOf(base)
  local ok, bounds = pcall(function() return S.TextService:GetTextSize(value, size, Enum.Font.RobotoMono, Vector2.new(100000, 1000)) end)
  if ok and typeof(bounds) == "Vector2" then return math.ceil(bounds.X) end
  return math.ceil(#value * size * 0.6)
end

-- ---------------------------------------------------------------- the accent, kept on everything that wears it
local accented = {}
local painters = {}
local function accent() return Config.get("app.unnamed.accent") or ACCENT end
-- (their "darker colour": the same hue, two thirds as bright. The line round what is filled with the accent)
local function darker(color)
  local h, s, v = color:ToHSV()
  return Color3.fromHSV(h, s, v / 1.5)
end
local function wear(instance, property, dark)
  accented[#accented + 1] = { instance, property, dark == true }
  instance[property] = dark and darker(accent()) or accent()
  return instance
end
-- (what paints itself from the accent in more than one way: a ticked square)
local function onAccent(owner, paint) painters[#painters + 1] = { owner, paint } end
local function repaint()
  local color = accent()
  local deep = darker(color)
  for index = #accented, 1, -1 do
    local entry = accented[index]
    if entry[1].Parent then entry[1][entry[2]] = entry[3] and deep or color else table.remove(accented, index) end
  end
  for index = #painters, 1, -1 do
    local entry = painters[index]
    if entry[1].Parent then B.try("unnamed.repaint", entry[2]) else table.remove(painters, index) end
  end
end

-- ---------------------------------------------------------------- pieces
local function box(parent, props)
  local frame = Instance.new("Frame")
  frame.BorderSizePixel = 0
  frame.BackgroundColor3 = C.box
  if props then
    for key, value in pairs(props) do frame[key] = value end
  end
  frame.Parent = parent
  return frame
end
-- a 1 px line inside its edge
local function lined(frame, color)
  frame.BorderSizePixel = 1
  frame.BorderMode = Enum.BorderMode.Inset
  frame.BorderColor3 = color or C.edge
  return frame
end
-- a 1 px line outside its edge (black unless told)
local function ringed(frame, color, thick)
  frame.BorderSizePixel = thick or 1
  frame.BorderMode = Enum.BorderMode.Outline
  frame.BorderColor3 = color or C.black
  return frame
end
-- their text: a black line 1 px round every letter
local function stroke(item)
  item.TextStrokeTransparency = 1
  local line = Instance.new("UIStroke")
  line.Color = C.black
  line.Thickness = 1
  line.LineJoinMode = Enum.LineJoinMode.Miter
  line.Parent = item
  return item
end
local function text(parent, value, props, bold)
  local label = Instance.new("TextLabel")
  label.BackgroundTransparency = 1
  label.BorderSizePixel = 0
  label.TextSize = 14
  label.TextColor3 = C.text
  label.TextXAlignment = Enum.TextXAlignment.Left
  label.Text = value or ""
  if props then
    for key, v in pairs(props) do label[key] = v end
  end
  letters(label, label.TextSize, bold)
  stroke(label)
  label.Parent = parent
  return label
end
-- a box to type in, in the menu's letters
local function entryBox(parent, size)
  local entry = Instance.new("TextBox")
  entry.BackgroundTransparency, entry.BorderSizePixel = 1, 0
  entry.TextColor3, entry.PlaceholderColor3 = C.text, C.hint
  entry.TextXAlignment, entry.ClearTextOnFocus, entry.ClipsDescendants = Enum.TextXAlignment.Left, false, true
  letters(entry, size or 14)
  stroke(entry)
  entry.Parent = parent
  return entry
end
-- Their field, which every control is made of: a black frame with a black line outside it, and in it a frame in the
-- main colour with the line colour on its inner edge. Returns both: the outer one is what lights under the mouse.
local function well(parent, props, fill)
  local outer = ringed(box(parent, props))
  outer.BackgroundColor3 = C.black
  local inner = lined(box(outer, { Name = "Inner", Size = UDim2.fromScale(1, 1), BackgroundColor3 = fill or C.main }), C.line)
  return outer, inner
end
-- (and the fall of light on a button, a list box and a box to type in: white at the top to 212 at the bottom)
local function shade(frame)
  local fall = Instance.new("UIGradient")
  fall.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1)), ColorSequenceKeypoint.new(1, rgb(212, 212, 212)) })
  fall.Rotation = 90
  fall.Parent = frame
  return fall
end
-- under the mouse a control changes its outer line and nothing else: to the line colour, or to the accent (a bar)
local function hover(button, outer, bright)
  button.MouseEnter:Connect(function() outer.BorderColor3 = bright and accent() or C.line end)
  button.MouseLeave:Connect(function() outer.BorderColor3 = C.black end)
end
local function hit(parent, props)
  local button = Instance.new("TextButton")
  button.Text = ""
  button.BackgroundTransparency = 1
  button.BorderSizePixel = 0
  button.AutoButtonColor = false
  button.Size = UDim2.fromScale(1, 1)
  button.ZIndex = 8
  if props then
    for key, value in pairs(props) do button[key] = value end
  end
  button.Parent = parent
  return button
end
local function lower(value) return string.lower(tostring(value or "")) end
local function list(parent, gap, horizontal)
  local layout = Instance.new("UIListLayout")
  layout.FillDirection = horizontal and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical
  layout.Padding = UDim.new(0, gap or 0)
  layout.SortOrder = Enum.SortOrder.LayoutOrder
  layout.Parent = parent
  return layout
end
local function pad(parent, top, right, bottom, left)
  local padding = Instance.new("UIPadding")
  padding.PaddingTop, padding.PaddingRight = UDim.new(0, top or 0), UDim.new(0, right or top or 0)
  padding.PaddingBottom, padding.PaddingLeft = UDim.new(0, bottom or top or 0), UDim.new(0, left or right or top or 0)
  padding.Parent = parent
  return padding
end
local function options(spec)
  local out = {}
  for _, option in ipairs(spec or {}) do
    if type(option) == "table" then out[#out + 1] = { value = option.value or option[1], label = option.label or option[2] or tostring(option.value or option[1]) }
    else out[#out + 1] = { value = option, label = tostring(option) } end
  end
  return out
end

-- ---------------------------------------------------------------- the floating bits: a tip, a list, a colour
-- (all inside the window, so they scale with it; placed from where the thing they belong to is)
local function within(gui)
  local scale = U.sizer and U.sizer.Scale or 1
  return (gui.AbsolutePosition - U.holder.AbsolutePosition) / scale, gui.AbsoluteSize / scale
end
local tip, tipFor
local function hideTip()
  tipFor = nil
  if tip then tip.Visible = false end
end
-- the window's size in design pixels (it can be dragged bigger)
local function frameSize()
  local scale = U.sizer and U.sizer.Scale or 1
  return U.holder and U.holder.AbsoluteSize / scale or Vector2.new(W, H)
end
-- theirs: at the mouse, 15 right and 12 down, and with it while it is up
local function placeTip()
  if not (tip and tip.Visible and U.holder) then return end
  local scale = U.sizer and U.sizer.Scale or 1
  local at = (UI.mouse() - U.holder.AbsolutePosition) / scale
  tip.Position = UDim2.fromOffset(at.X + 15, at.Y + 12)
end
-- `label`, when given: a name that may be cut short on its row; cut, the tip says it whole
local function tooltip(button, desc, label)
  if (not desc or desc == "") and not label then return end
  button.MouseEnter:Connect(function()
    if not (U.open and button.Parent and tip) then return end
    local value = desc or ""
    if label and label.Parent and not label.TextFits then value = label.Text .. (value ~= "" and ("  -  " .. value) or "") end
    if value == "" then return end
    tipFor = button
    tip.Text = value
    tip.Visible = true
    placeTip()
  end)
  button.MouseLeave:Connect(function() if tipFor == button then hideTip() end end)
end
local popup                           -- the open list or colour picker: { frame, anchor, close }
local function closePopup()
  if popup then
    local open = popup
    popup = nil
    open.frame:Destroy()
    if open.locked and open.locked.Parent then open.locked.ScrollingEnabled = true end
    if open.closed then open.closed() end
  end
end
-- The page an open list or colour sits on stays where it is until it closes: the wheel over the
-- list scrolls the list alone. (Before, the wheel went through to the page, the page moved, and
-- moving closed the list.) A click anywhere else closes it and the page scrolls again.
local function lockPage(anchor)
  for _, entry in pairs(U.pages) do
    local scroller = entry.scroller
    if scroller and anchor and anchor:IsDescendantOf(scroller) then
      scroller.ScrollingEnabled = false
      return scroller
    end
  end
  return nil
end
U.closePopup = closePopup
-- a list under `anchor`: items = { { label, checked } }, pick(index) -> keep open?
-- Theirs: 8 rows of 20 px at the most, 1 px under the box and as wide, a black line round it, the picked one in the accent.
local function openList(anchor, items, pick, multi)
  closePopup()
  local at, size = within(anchor)
  local rows = math.min(#items, 8)
  local tall = rows * 20 + 1
  -- (under it, or over it when the window ends first)
  local y = at.Y + size.Y + 1
  if y + tall > frameSize().Y - 2 and at.Y - tall - 1 >= 2 then y = at.Y - tall - 1 end
  local frame = ringed(box(U.holder, { Name = "List", Position = UDim2.fromOffset(at.X, y), Size = UDim2.fromOffset(size.X, tall),
    BackgroundColor3 = C.black, ZIndex = 60 }))
  local inner = box(frame, { Name = "Inner", Size = UDim2.fromScale(1, 1), BackgroundColor3 = C.main, ZIndex = 61 })
  local scroller = Instance.new("ScrollingFrame")
  scroller.BackgroundTransparency, scroller.BorderSizePixel = 1, 0
  scroller.Size = UDim2.fromScale(1, 1)
  scroller.CanvasSize = UDim2.fromOffset(0, #items * 20 + 1)
  scroller.ScrollBarThickness = 3
  scroller.TopImage, scroller.BottomImage = "rbxasset://textures/ui/Scroll/scroll-middle.png", "rbxasset://textures/ui/Scroll/scroll-middle.png"
  scroller.ScrollingDirection = Enum.ScrollingDirection.Y
  scroller.ZIndex = 61
  wear(scroller, "ScrollBarImageColor3")
  scroller.Parent = inner
  for index, item in ipairs(items) do
    local row = box(scroller, { Name = "Item", Position = UDim2.fromOffset(0, (index - 1) * 20), Size = UDim2.new(1, -1, 0, 20), BackgroundColor3 = C.main, ZIndex = 62 })
    row.BorderSizePixel, row.BorderMode, row.BorderColor3 = 1, Enum.BorderMode.Middle, C.line
    local label = text(row, item[1], { Position = UDim2.fromOffset(6, 0), Size = UDim2.new(1, -6, 1, 0), ZIndex = 63, TextTruncate = Enum.TextTruncate.AtEnd })
    if item[2] then wear(label, "TextColor3") end
    local button = hit(row, { ZIndex = 64 })
    button.Activated:Connect(B.safe("unnamed.list", function()
      local checked = pick(index)
      if multi then
        item[2] = checked
        if checked then wear(label, "TextColor3") else label.TextColor3 = C.text end
      else
        closePopup()
      end
    end))
  end
  popup = { frame = frame, anchor = anchor, locked = lockPage(anchor) }
  return frame
end
local function hexOf(color)
  return string.format("#%02x%02x%02x", math.floor(color.R * 255 + 0.5), math.floor(color.G * 255 + 0.5), math.floor(color.B * 255 + 0.5))
end
-- A colour, in their window: 230 x 253, a line of the accent on top and its name, a 200 x 200 square of saturation and
-- value, a strip of hue 15 wide down its right, and under them the colour as hex and as red, green, blue to type.
-- (Their square is a picture; this one is the same fade made of two gradients, so it needs no asset.)
local function openColor(anchor, initial, set, title)
  closePopup()
  local at = within(anchor)
  local h, s, v = initial:ToHSV()
  local room = frameSize()
  local x = math.max(4, math.min(at.X, room.X - 234))
  local y = at.Y + 18
  if y + 255 > room.Y - 2 and at.Y - 257 >= 2 then y = at.Y - 257 end
  local frame = ringed(box(U.holder, { Name = "Colour", Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(230, 253),
    BackgroundColor3 = Color3.new(1, 1, 1), ZIndex = 60 }))
  local inner = lined(box(frame, { Name = "Inner", Size = UDim2.fromScale(1, 1), BackgroundColor3 = C.page, ZIndex = 61 }), C.line)
  wear(box(inner, { Name = "Line", Size = UDim2.new(1, 0, 0, 2), ZIndex = 62 }), "BackgroundColor3")
  text(inner, lower(title or "color picker"), { Name = "Title", Position = UDim2.fromOffset(5, 5), Size = UDim2.new(1, -10, 0, 14), ZIndex = 62,
    TextTruncate = Enum.TextTruncate.AtEnd })
  local mapOuter = ringed(box(inner, { Name = "Map", Position = UDim2.fromOffset(4, 25), Size = UDim2.fromOffset(200, 200), BackgroundColor3 = C.black, ZIndex = 62 }))
  local square = lined(box(mapOuter, { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.fromHSV(h, 1, 1), ZIndex = 63 }), C.line)
  local white = box(square, { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1), ZIndex = 64 })
  local fade = Instance.new("UIGradient"); fade.Transparency = NumberSequence.new(0, 1); fade.Parent = white
  local black = box(square, { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), ZIndex = 65 })
  local down = Instance.new("UIGradient"); down.Rotation = 90; down.Transparency = NumberSequence.new(1, 0); down.Parent = black
  local dot = ringed(box(square, { Name = "Dot", Size = UDim2.fromOffset(4, 4), AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = Color3.new(1, 1, 1), ZIndex = 66 }))
  local hueOuter = ringed(box(inner, { Name = "Hue", Position = UDim2.fromOffset(208, 25), Size = UDim2.fromOffset(15, 200), BackgroundColor3 = Color3.new(1, 1, 1), ZIndex = 62 }))
  local stops = {}
  for i = 0, 10 do stops[#stops + 1] = ColorSequenceKeypoint.new(i / 10, Color3.fromHSV(i / 10, 1, 1)) end
  local rainbow = Instance.new("UIGradient"); rainbow.Color = ColorSequence.new(stops); rainbow.Rotation = 90; rainbow.Parent = hueOuter
  local mark = ringed(box(hueOuter, { Name = "Mark", Size = UDim2.new(1, 0, 0, 1), AnchorPoint = Vector2.new(0, 0.5), BackgroundColor3 = Color3.new(1, 1, 1), ZIndex = 63 }))
  local hexOuter, hexInner = well(inner, { Name = "Hex", Position = UDim2.fromOffset(4, 228), Size = UDim2.new(0.5, -6, 0, 20), ZIndex = 62 })
  shade(hexInner)
  local hexBox = entryBox(hexInner, 14)
  hexBox.Position, hexBox.Size, hexBox.PlaceholderText = UDim2.fromOffset(5, 0), UDim2.new(1, -5, 1, 0), "hex color"
  local rgbOuter, rgbInner = well(inner, { Name = "Rgb", Position = UDim2.new(0.5, 2, 0, 228), Size = UDim2.new(0.5, -6, 0, 20), ZIndex = 62 })
  shade(rgbInner)
  local rgbBox = entryBox(rgbInner, 14)
  rgbBox.Position, rgbBox.Size, rgbBox.PlaceholderText = UDim2.fromOffset(5, 0), UDim2.new(1, -5, 1, 0), "rgb color"
  local function show()
    local color = Color3.fromHSV(h, s, v)
    square.BackgroundColor3 = Color3.fromHSV(h, 1, 1)
    dot.Position = UDim2.fromScale(s, 1 - v)
    mark.Position = UDim2.fromScale(0, h)
    if not hexBox:IsFocused() then hexBox.Text = hexOf(color) end
    if not rgbBox:IsFocused() then
      rgbBox.Text = string.format("%d, %d, %d", math.floor(color.R * 255 + 0.5), math.floor(color.G * 255 + 0.5), math.floor(color.B * 255 + 0.5))
    end
  end
  show()
  local function emit() show(); set(Color3.fromHSV(h, s, v)) end
  local squareHit = hit(square, { ZIndex = 67 })
  local function onSquare(point)
    s = util.clamp01((point.X - square.AbsolutePosition.X) / math.max(square.AbsoluteSize.X, 1))
    v = 1 - util.clamp01((point.Y - square.AbsolutePosition.Y) / math.max(square.AbsoluteSize.Y, 1))
    emit()
  end
  UI.drag(squareHit, onSquare, onSquare)
  local hueHit = hit(hueOuter, { ZIndex = 67 })
  local function onHue(point)
    h = util.clamp01((point.Y - hueOuter.AbsolutePosition.Y) / math.max(hueOuter.AbsoluteSize.Y, 1))
    emit()
  end
  UI.drag(hueHit, onHue, onHue)
  hexBox.FocusLost:Connect(B.safe("unnamed.color.hex", function()
    local digits = string.gsub(hexBox.Text, "[^%x]", "")
    if #digits == 6 then
      local number = tonumber(digits, 16)
      if number then
        h, s, v = Color3.fromRGB(math.floor(number / 65536) % 256, math.floor(number / 256) % 256, number % 256):ToHSV()
        emit()
        return
      end
    end
    show()
  end))
  rgbBox.FocusLost:Connect(B.safe("unnamed.color.rgb", function()
    local r, g, b = string.match(rgbBox.Text, "(%d+)%D+(%d+)%D+(%d+)")
    if r and g and b then
      h, s, v = Color3.fromRGB(math.clamp(tonumber(r), 0, 255), math.clamp(tonumber(g), 0, 255), math.clamp(tonumber(b), 0, 255)):ToHSV()
      emit()
      return
    end
    show()
  end))
  popup = { frame = frame, anchor = anchor, locked = lockPage(anchor), hex = hexOuter, rgb = rgbOuter }
  return frame
end

-- ---------------------------------------------------------------- a key for a flag (right click on a control)
-- Their key box: 28 x 15 (wider when the key's name needs it), a black line outside, the page colour with the line
-- colour inside, the key's name at 13. It sits at the right end of the row, 1 px over it above and below.
local function keyChip(row, y)
  local outer, inner = well(row, { Name = "Key", AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -6, 0, y or -1), Size = UDim2.fromOffset(28, 15),
    Visible = false, ZIndex = 4 }, C.page)
  local label = text(inner, "", { Size = UDim2.fromScale(1, 1), TextSize = 13, TextXAlignment = Enum.TextXAlignment.Center })
  local chip = { frame = outer, label = label, wide = 28 }
  function chip.set(value)
    label.Text = value
    chip.wide = math.max(28, measure(value, 13) + 8)
    outer.Size = UDim2.fromOffset(chip.wide, 15)
  end
  function chip.show(on) outer.Visible = on == true end
  function chip.shown() return outer.Visible end
  return chip
end
local function bindKey(id, label, chip, refresh)
  if not id then return end
  chip.show(true)
  chip.set("...")
  Controls.captureKey(function(key, cancelled)
    if not cancelled then
      Config.bind(id, key)
      Window.toast({ title = key and ("Bound to " .. Config.keyLabel(key)) or "Key cleared", text = label, icon = "keyboard", time = 2 })
    end
    refresh()
  end)
end
-- right click: a short list under the row (bind / hold to use / clear / back to default)
local function keyMenu(id, label, kind, line, chip, refresh)
  if not id then return end
  local bind = Config.bindOf(id)
  local items, runs = {}, {}
  local function add(value, run, checked) items[#items + 1] = { value, checked == true }; runs[#items] = run end
  add(bind and bind.key and ("change key (" .. lower(Config.keyLabel(bind.key)) .. ")") or "bind a key", function() bindKey(id, label, chip, refresh) end)
  if bind and bind.key then
    if kind == "toggle" then add("hold to use", function() Config.bind(id, bind.key, bind.mode == "hold" and "toggle" or "hold") end, bind.mode == "hold") end
    add("clear the key", function() Config.bind(id, nil) end)
  end
  if kind ~= "button" and Config.get(id) ~= nil then add("back to default", function() Config.reset(id) end) end
  openList(line, items, function(index)
    local run = runs[index]
    if run then task.defer(run) end
    return false
  end, false)
end

-- ---------------------------------------------------------------- a section and its controls
-- No gap between rows: as theirs, each control is followed by a blank of its own (7 under a tick, 6 under a bar, 5 under
-- a list, a button, a label, a box to type in). Here the blank is the bottom of the control's own row, so a row the
-- search hides takes its blank with it.
local Section = {}
Section.__index = Section
local function row(section, height)
  section.count += 1
  return box(section.body, { Name = "Row", Size = UDim2.new(1, 0, 0, height), BackgroundTransparency = 1, LayoutOrder = section.count })
end
local function sub(section, holder)
  return setmetatable({ body = holder, count = 0, page = section.page, card = section.card }, Section)
end
-- a row the search box can find, by its name and what it says it does
local function findable(section, frame, label, desc)
  local page = section.page
  if not (page and page.rows) then return end
  page.rows[#page.rows + 1] = { frame = frame, card = section.card, text = lower(tostring(label or "") .. " " .. tostring(desc or "")) }
end

-- A box to tick: 13 x 13, its name 19 px in at 14, white ticked or not. Ticked, the square is the accent with a darker
-- line. The row is 13 + 7.
function Section:toggle(spec)
  local id = spec.id
  local bindable = spec.bindable ~= false
  local value = initial(id, spec.default == true)
  local line = row(self, 20)
  findable(self, line, spec.label, spec.desc)
  local square, fill = well(line, { Name = "Box", Size = UDim2.fromOffset(13, 13) })
  local label = text(line, lower(spec.label), { Position = UDim2.fromOffset(19, 0), Size = UDim2.new(1, -25, 0, 13), TextTruncate = Enum.TextTruncate.AtEnd })
  local chip = keyChip(line)
  local children
  local function paint()
    fill.BackgroundColor3 = value and accent() or C.main
    fill.BorderColor3 = value and darker(accent()) or C.line
    if children then children.Visible = value end
  end
  onAccent(line, paint)
  local function showKey()
    local bind = id and Config.bindOf(id)
    local on = bind ~= nil and bind.key ~= nil
    chip.show(on)
    if on then chip.set(Config.keyLabel(bind.key) .. (bind.mode == "hold" and "*" or "")) end
    -- (the name has the whole row when there is no key on it)
    label.Size = UDim2.new(1, on and -(chip.wide + 29) or -25, 0, 13)
  end
  if spec.children then
    -- (theirs: what a tick brings up comes in place, at the same left edge)
    self.count += 1
    children = box(self.body, { Name = "Sub", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, LayoutOrder = self.count })
    list(children, 0)
    B.try("unnamed.children", spec.children, sub(self, children))
  end
  paint()
  showKey()
  if id then
    Config.on(id, function(next)
      value = next == true
      if line.Parent then paint() end
      if spec.changed then spec.changed(value) end
    end)
    Config.bindsChanged:connect(function(changed) if changed == id and chip.frame.Parent then showKey() end end)
    if bindable then Controls.bindables[id] = Controls.bindables[id] or { label = spec.label or id, kind = "toggle", page = self.page.source } end
  end
  local button = hit(line, { Size = UDim2.new(1, -4, 0, 13) })
  hover(button, square)
  button.Activated:Connect(B.safe("unnamed.toggle", function()
    if id then Config.set(id, Config.get(id) ~= true) else
      value = not value
      paint()
      if spec.changed then B.try("toggle", spec.changed, value) end
    end
  end))
  button.MouseButton2Click:Connect(function() if bindable then keyMenu(id, spec.label, "toggle", line, chip, showKey) end end)
  tooltip(button, (spec.tip or spec.desc) and ((spec.tip or spec.desc) .. (bindable and id and "  (right click: its key)" or "")) or nil, label)
  return { row = { frame = line, label = label }, id = id, get = function() return value end, set = function(next) if id then Config.set(id, next == true) end end, open = function() end }
end

-- A bar: its name above it (10 px, at the bottom of them), 3 px, the bar 13 px with the value written in its middle as
-- value/max, 6 px. The fill takes 0.2 s to get to a new value. The name and the value are both children of the row.
function Section:slider(spec)
  local id = spec.id
  local min, max, step = spec.min or 0, spec.max or 100, spec.step or 1
  -- (2026-11-14: as many decimals as the step has: a step of 0.25 kept one, and 6.25 became 6.2. And a TYPED number may go
  -- as far as the hard range, as in the BASED slider: the bar keeps to min..max)
  local decimals = spec.decimals
  if not decimals then
    decimals = 4
    for places = 0, 4 do
      local scaled = step * 10 ^ places
      if math.abs(scaled - math.floor(scaled + 0.5)) < 1e-6 then decimals = places; break end
    end
  end
  local hardMin, hardMax = spec.hardMin or min, spec.hardMax or max
  local curve = spec.curve or 1
  local value = initial(id, spec.default or min)
  local line = row(self, 32)
  findable(self, line, spec.label, spec.desc)
  local label = text(line, lower(spec.label), { Size = UDim2.new(1, -4, 0, 10), TextYAlignment = Enum.TextYAlignment.Bottom, TextTruncate = Enum.TextTruncate.AtEnd })
  local bar, inner = well(line, { Name = "Bar", Position = UDim2.fromOffset(0, 13), Size = UDim2.new(1, -6, 0, 13) })
  local fill = ringed(box(inner, { Name = "Fill", Size = UDim2.fromScale(0, 1), ZIndex = 2 }))
  wear(fill, "BackgroundColor3")
  wear(fill, "BorderColor3", true)
  local edge = wear(box(fill, { Name = "Edge", Position = UDim2.fromScale(1, 0), Size = UDim2.new(0, 1, 1, 0), ZIndex = 3 }), "BackgroundColor3")
  local amount = text(line, "", { Name = "Value", Position = UDim2.fromOffset(0, 13), Size = UDim2.new(1, -6, 0, 13), TextXAlignment = Enum.TextXAlignment.Center,
    ZIndex = 4, TextTruncate = Enum.TextTruncate.AtEnd })
  local function one(v) return util.format(v, decimals) .. (spec.suffix or "") end
  local function shown(v) return (spec.format and spec.format(v)) or (one(v) .. "/" .. one(max)) end
  local moving
  local function place(animate)
    local share = util.clamp01((value - min) / math.max(max - min, 1e-9)) ^ (1 / curve)
    local goal = UDim2.fromScale(share, 1)
    if moving then pcall(function() moving:Cancel() end); moving = nil end
    if animate and not Motion.reduced then
      moving = S.TweenService:Create(fill, FILL, { Size = goal })
      moving:Play()
    else
      fill.Size = goal
    end
    edge.Visible = share > 0 and share < 1
    amount.Text = shown(value)
  end
  place(false)
  local function set(next, _, typed)
    next = math.clamp(util.round(next, step), typed and math.min(hardMin, min) or min, typed and math.max(hardMax, max) or max)
    if decimals > 0 then next = tonumber(string.format("%." .. decimals .. "f", next)) or next end
    if next == value then return end
    if id then Config.set(id, next) else
      value = next
      place(true)
      if spec.changed then B.try("slider", spec.changed, value) end
    end
  end
  if id then
    Config.on(id, function(next)
      value = next
      if bar.Parent then place(true) end
      if spec.changed then spec.changed(next) end
    end)
  end
  local button = hit(line, { Position = UDim2.fromOffset(0, 13), Size = UDim2.new(1, -6, 0, 13) })
  local function at(point) set(min + util.clamp01((point.X - bar.AbsolutePosition.X) / math.max(bar.AbsoluteSize.X, 1)) ^ curve * (max - min)) end
  UI.drag(button, function(point) at(point) end, function(point) at(point) end)
  -- (right click: type a number, for the far end of a long range)
  button.MouseButton2Click:Connect(function()
    local field = entryBox(line, 14)
    field.BackgroundTransparency, field.BackgroundColor3 = 0, C.main
    field.Size, field.Position, field.ZIndex = UDim2.new(1, -6, 0, 13), UDim2.fromOffset(0, 13), 9
    field.TextXAlignment = Enum.TextXAlignment.Center
    field.Text, field.ClearTextOnFocus, field.PlaceholderText = "", true, lower(spec.label) .. "..."
    field.FocusLost:Connect(B.safe("unnamed.slider.type", function()
      local typed = tonumber((string.gsub(field.Text, "[^%d%.%-eE]", "")))
      field:Destroy()
      if typed then set(typed, nil, true) end
    end))
    field:CaptureFocus()
  end)
  hover(button, bar, true)
  tooltip(button, ((spec.tip or spec.desc) and ((spec.tip or spec.desc) .. "  ") or "") .. "(right click: type a number)", label)
  local api = { row = { frame = line, label = label }, id = id, get = function() return value end, set = set }
  -- (the hard range changed while the hub runs: the Resolver tab's Unlock limits)
  function api.range(low, high)
    hardMin, hardMax = low or min, high or max
  end
  return api
end

-- a box that opens a list: one value (dropdown, segmented) or several (multi)
-- Its name above it (10 px), 3 px, the box 20 px with what is picked 5 px in and a ">" at its right that turns down while
-- the list is open, 5 px.
local function chooser(section, spec, many)
  local id = spec.id
  local choices = options(spec.options)
  local first = choices[1] and choices[1].value
  local value
  if many then value = initial(id, spec.default or {})
  else value = initial(id, orDefault(spec.default, first)) end
  local line = row(section, 38)
  findable(section, line, spec.label, spec.desc)
  text(line, lower(spec.label), { Size = UDim2.new(1, -4, 0, 10), TextYAlignment = Enum.TextYAlignment.Bottom, TextTruncate = Enum.TextTruncate.AtEnd })
  local outer, inner = well(line, { Name = "Field", Position = UDim2.fromOffset(0, 13), Size = UDim2.new(1, -4, 0, 20) })
  shade(inner)
  local label = text(inner, "", { Position = UDim2.new(0, 5, 0, -1), Size = UDim2.new(1, -24, 1, 0), TextTruncate = Enum.TextTruncate.AtEnd })
  local arrow = text(inner, ">", { Name = "Arrow", AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(1, -16, 0.5, 0), Size = UDim2.fromOffset(12, 12), TextSize = 13,
    TextXAlignment = Enum.TextXAlignment.Center })
  local function has(v) return table.find(value, v) ~= nil end
  local function summary()
    if not many then
      for _, option in ipairs(choices) do if option.value == value then return option.label end end
      if value == nil or value == "" then return "..." end
      return tostring(value)
    end
    if #value == 0 then return spec.empty or "..." end
    local names = {}
    for _, option in ipairs(choices) do if has(option.value) then names[#names + 1] = option.label end end
    return table.concat(names, ", ")
  end
  label.Text = summary()
  local function set(next)
    if id then Config.set(id, next) else
      value = next
      label.Text = summary()
      if spec.changed then B.try("chooser", spec.changed, value) end
    end
  end
  if id then
    Config.on(id, function(next)
      value = next
      if label.Parent then label.Text = summary() end
      if spec.changed then spec.changed(next) end
    end)
  end
  local button = hit(outer)
  hover(button, outer)
  button.Activated:Connect(B.safe("unnamed.choose", function()
    if popup and popup.anchor == outer then closePopup(); return end
    local items = {}
    for index, option in ipairs(choices) do items[index] = { option.label, many and has(option.value) or option.value == value } end
    openList(outer, items, function(index)
      local option = choices[index]
      if not many then set(option.value); return false end
      local next = table.clone(value)
      local at = table.find(next, option.value)
      if at then table.remove(next, at) else next[#next + 1] = option.value end
      local ordered = {}
      for _, o in ipairs(choices) do if table.find(next, o.value) then ordered[#ordered + 1] = o.value end end
      set(ordered)
      return at == nil
    end, many)
    arrow.Rotation = 90
    popup.closed = function() if arrow.Parent then arrow.Rotation = 0 end end
  end))
  tooltip(button, spec.tip or spec.desc)
  return { row = { frame = line, label = label }, id = id, get = function() return value end, set = set, has = has,
    options = function(next) choices = options(next); label.Text = summary() end,
    -- (what it shows, put from outside without a change of its own: an id-less one kept in step)
    show = function(next) value = next; if label.Parent then label.Text = summary() end end }
end
function Section:dropdown(spec) return chooser(self, spec, false) end
function Section:segmented(spec) return chooser(self, spec, false) end
function Section:multi(spec) return chooser(self, spec, true) end

-- their colour on a row: 28 x 14, the colour itself, with the same colour two thirds as bright on its inner edge
local function swatchOn(line, name, right, value)
  local swatch = lined(box(line, { Name = name, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -right, 0, 0), Size = UDim2.fromOffset(28, 14),
    BackgroundColor3 = value }), darker(value))
  return swatch
end
local function tint(swatch, color)
  swatch.BackgroundColor3 = color
  swatch.BorderColor3 = darker(color)
end
function Section:color(spec)
  local id = spec.id
  local value = initial(id, spec.default or Color3.new(1, 1, 1))
  local line = row(self, 20)
  findable(self, line, spec.label, spec.desc)
  text(line, lower(spec.label), { Size = UDim2.new(1, -40, 0, 15), TextColor3 = C.text, TextTruncate = Enum.TextTruncate.AtEnd })
  local swatch = swatchOn(line, "Swatch", 4, value)
  local function set(next) if id then Config.set(id, next) else value = next; tint(swatch, next); if spec.changed then spec.changed(next) end end end
  if id then
    Config.on(id, function(next)
      value = next
      if swatch.Parent then tint(swatch, next) end
      if spec.changed then spec.changed(next) end
    end)
  end
  local button = hit(swatch)
  button.Activated:Connect(B.safe("unnamed.color", function()
    if popup and popup.anchor == swatch then closePopup(); return end
    openColor(swatch, value, set, spec.label)
  end))
  tooltip(button, spec.tip or spec.desc)
  return { row = { frame = line }, id = id, get = function() return value end, set = set }
end

-- up to three colours on one row (a run of colours: a gradient's ends and its middle): the BASED menu's `colors`
function Section:colors(spec)
  local ids = spec.ids or {}
  local line = row(self, 20)
  findable(self, line, spec.label, spec.desc)
  text(line, lower(spec.label), { Size = UDim2.new(1, -(32 * #ids + 8), 0, 15), TextColor3 = C.text, TextTruncate = Enum.TextTruncate.AtEnd })
  local api = { row = { frame = line }, ids = ids, swatches = {} }
  for index, id in ipairs(ids) do
    local value = Config.define(id, (spec.defaults and spec.defaults[index]) or Color3.new(1, 1, 1))
    local swatch = swatchOn(line, "Swatch" .. index, 4 + (#ids - index) * 32, value)
    api.swatches[index] = swatch
    Config.on(id, function(next)
      value = next
      if swatch.Parent then tint(swatch, next) end
    end)
    local button = hit(swatch)
    button.Activated:Connect(B.safe("unnamed.colors", function()
      if popup and popup.anchor == swatch then closePopup(); return end
      openColor(swatch, value, function(next) Config.set(id, next) end, spec.label)
    end))
    tooltip(button, spec.tip or spec.desc)
  end
  return api
end

function Section:keybind(spec)
  local id = spec.id
  local value = initial(id, spec.default or "None")
  local line = row(self, 20)
  findable(self, line, spec.label, spec.desc)
  text(line, lower(spec.label), { Size = UDim2.new(1, -70, 0, 15), TextTruncate = Enum.TextTruncate.AtEnd })
  local chip = keyChip(line, 0)
  chip.frame.Position = UDim2.new(1, -4, 0, 0)
  local function show() chip.show(true); chip.set(Config.keyLabel(value ~= "None" and value or nil)) end
  show()
  if id then
    Config.on(id, function(next)
      value = next
      if chip.frame.Parent then show() end
      if spec.changed then spec.changed(next) end
    end)
  end
  local button = hit(chip.frame)
  button.Activated:Connect(B.safe("unnamed.key", function()
    chip.set("...")
    Controls.captureKey(function(key, cancelled)
      if not cancelled then
        local next = key or "None"
        if id then Config.set(id, next) else value = next; if spec.changed then spec.changed(next) end end
      end
      show()
    end)
  end))
  tooltip(button, spec.tip or spec.desc)
  return { row = { frame = line }, id = id, get = function() return value end }
end

-- a button: 20 px, its words in the middle at 14, the fall of light on it; 5 px under it
function Section:button(spec)
  local id = spec.id
  local line = row(self, 25)
  findable(self, line, spec.label or spec.text, spec.desc)
  local outer, inner = well(line, { Name = "Field", Size = UDim2.new(1, -4, 0, 20) })
  shade(inner)
  local label = text(inner, lower(spec.label or spec.text), { Size = UDim2.new(1, 0, 1, -1), TextXAlignment = Enum.TextXAlignment.Center, TextTruncate = Enum.TextTruncate.AtEnd })
  local chip = keyChip(line, 2)
  chip.frame.Position = UDim2.new(1, -7, 0, 2)
  local function showKey()
    local bind = id and Config.bindOf(id)
    local on = bind ~= nil and bind.key ~= nil
    chip.show(on)
    if on then chip.set(Config.keyLabel(bind.key)) end
  end
  showKey()
  if id then
    Config.action(id, function() if spec.run then spec.run() end end)
    Config.bindsChanged:connect(function(changed) if changed == id and chip.frame.Parent then showKey() end end)
    if spec.bindable ~= false then Controls.bindables[id] = Controls.bindables[id] or { label = spec.label or id, kind = "button", page = self.page.source } end
  end
  local button = hit(outer)
  hover(button, outer)
  button.Activated:Connect(B.safe("unnamed.button", function()
    if spec.run then B.try("button." .. (spec.label or "?"), spec.run) end
  end))
  button.MouseButton2Click:Connect(function() if id and spec.bindable ~= false then keyMenu(id, spec.label, "button", line, chip, showKey) end end)
  tooltip(button, spec.tip or spec.desc)
  return { row = { frame = line, label = label }, button = outer, setText = function(value) label.Text = lower(value) end }
end

-- a box to type in: its name 15 px, 1 px, the box 20 px with the words 5 px in, 5 px
function Section:input(spec)
  local id = spec.id
  local value = initial(id, spec.default or "")
  local line = row(self, 41)
  findable(self, line, spec.label, spec.desc)
  text(line, lower(spec.label), { Size = UDim2.new(1, -4, 0, 15), TextTruncate = Enum.TextTruncate.AtEnd })
  local outer, inner = well(line, { Name = "Field", Position = UDim2.fromOffset(0, 16), Size = UDim2.new(1, -4, 0, 20) })
  shade(inner)
  local entry = entryBox(inner, 14)
  entry.Position, entry.Size = UDim2.fromOffset(5, 0), UDim2.new(1, -5, 1, 0)
  entry.Text, entry.PlaceholderText = tostring(value), lower(spec.placeholder or "")
  hover(entry, outer)
  entry.FocusLost:Connect(B.safe("unnamed.input", function()
    local typed = entry.Text
    if spec.numeric then
      local number = tonumber(typed)
      if not number then entry.Text = tostring(value); return end
      typed = number
    end
    if id then Config.set(id, typed) else
      value = typed
      if spec.changed then B.try("input", spec.changed, typed) end
    end
  end))
  if id then
    Config.on(id, function(next)
      value = next
      if entry.Parent and not entry:IsFocused() then entry.Text = tostring(next) end
      if spec.changed then spec.changed(next) end
    end)
  end
  return { row = { frame = line }, id = id, box = entry, get = function() return value end }
end

-- words: 14, white, as theirs; wrapped (ours: a note may be longer than a row); 5 px under them
function Section:note(spec)
  self.count += 1
  local holder = box(self.body, { Name = "NoteRow", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, LayoutOrder = self.count })
  pad(holder, 0, 4, 5, 0)
  local label = text(holder, spec.text or "", { Name = "Note", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, TextWrapped = true,
    TextColor3 = C.text, RichText = spec.rich == true })
  return { frame = label, set = function(value) label.Text = value end }
end
function Section:custom(spec)
  self.count += 1
  local frame = box(self.body, { Name = spec.name or "Custom", Size = UDim2.new(1, -4, 0, spec.height or 100), BackgroundTransparency = 1, LayoutOrder = self.count })
  if spec.height == nil then frame.AutomaticSize = Enum.AutomaticSize.Y end
  B.try("unnamed.custom", spec.build, frame)
  return frame
end
-- for a tab's own version of itself: a line of text, two buttons side by side, a box to type in
function Section:label(value)
  local note = self:note({ text = value })
  note.frame.TextColor3 = C.text
  return note
end
function Section:pair(a, b)
  local line = row(self, 25)
  local out = {}
  for index, item in ipairs({ a, b }) do
    if item then
      -- (theirs: two on a row are each half of it less 2, 3 px apart)
      local outer, inner = well(line, { Name = "Field", Position = UDim2.new((index - 1) * 0.5, index == 2 and 1 or 0, 0, 0),
        Size = UDim2.new(b and 0.5 or 1, b and (index == 2 and -5 or -2) or -4, 0, 20) })
      shade(inner)
      local label = text(inner, lower(item[1]), { Size = UDim2.new(1, 0, 1, -1), TextXAlignment = Enum.TextXAlignment.Center, TextTruncate = Enum.TextTruncate.AtEnd })
      local button = hit(outer)
      hover(button, outer)
      button.Activated:Connect(B.safe("unnamed.pair", function() if item[2] then item[2]() end end))
      out[index] = { field = outer, label = label }
    end
  end
  return out
end
function Section:field(placeholder, changed)
  local line = row(self, 25)
  local outer, inner = well(line, { Name = "Field", Size = UDim2.new(1, -4, 0, 20) })
  shade(inner)
  local entry = entryBox(inner, 14)
  entry.Position, entry.Size = UDim2.fromOffset(5, 0), UDim2.new(1, -5, 1, 0)
  entry.Text, entry.PlaceholderText = "", placeholder or ""
  hover(entry, outer)
  if changed then entry:GetPropertyChangedSignal("Text"):Connect(function() changed(entry.Text) end) end
  return entry
end
U.Section = Section

-- ---------------------------------------------------------------- a tab
local Page = {}
Page.__index = Page
local function band(page, full)
  page.bands += 1
  local frame = box(page.content, { Name = full and "Full" or "Columns", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1,
    LayoutOrder = page.bands })
  if full then
    list(frame, 8)
    return { full = true, frame = frame }
  end
  -- (theirs: two columns, each half the page less 4, 8 px apart, their boxes 8 px apart)
  local columns = {}
  for index = 1, 2 do
    local column = box(frame, { Name = "Column" .. index, Size = UDim2.new(0.5, -4, 0, 0), Position = UDim2.new(index == 1 and 0 or 0.5, index == 1 and 0 or 4, 0, 0),
      AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1 })
    list(column, 8)
    columns[index] = { frame = column, count = 0 }
  end
  return { full = false, frame = frame, columns = columns }
end
local function host(page, spec)
  local current = page.band
  if spec.full then
    current = band(page, true)
    page.band = nil
  elseif not current or current.full then
    current = band(page, false)
    page.band = current
  end
  if current.full then return current.frame end
  local column = spec.column and current.columns[spec.column]
    or (current.columns[1].count <= current.columns[2].count and current.columns[1] or current.columns[2])
  column.count += spec.weight or 1
  return column.frame
end
-- Their box: the page colour with the line colour on its inner edge; 1 px in, a second frame with a black line round
-- it; on that a 2 px line of the accent, the title 18 px high at 14 in the middle, and from 20 px down what it holds,
-- 4 px in from the left. It is 20 + what it holds + 2 + 2 high, and what it holds starts with a 3 px blank.
local function group(page, spec)
  page.sections += 1
  local frame = lined(box(host(page, spec), { Name = spec.title or "Box", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = C.box,
    LayoutOrder = page.sections }), C.edge)
  pad(frame, 0, 0, 1, 0)
  local inner = ringed(box(frame, { Name = "Inner", Position = UDim2.fromOffset(1, 1), Size = UDim2.new(1, -2, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
    BackgroundColor3 = C.box }))
  pad(inner, 0, 0, 2, 0)
  wear(box(inner, { Name = "Line", Size = UDim2.new(1, 0, 0, 2), ZIndex = 2 }), "BackgroundColor3")
  if spec.title then
    text(inner, lower(spec.title), { Name = "Title", Position = UDim2.fromOffset(4, 2), Size = UDim2.new(1, 0, 0, 18), TextXAlignment = Enum.TextXAlignment.Center })
  end
  local body = box(inner, { Name = "Body", Position = UDim2.fromOffset(4, spec.title and 20 or 6), Size = UDim2.new(1, -4, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
    BackgroundTransparency = 1 })
  list(body, 0)
  if page.cards then page.cards[#page.cards + 1] = { frame = frame, title = lower(spec.title) } end
  local section = setmetatable({ body = body, count = 0, page = page, card = frame }, Section)
  row(section, 3).Name = "Blank"
  return section
end
function Page:section(spec) return group(self, spec or {}) end
function Page:custom(height, build, alt)
  if alt then
    local section = group(self, { full = true })
    B.try("unnamed.alt", alt, section)
    return section.body
  end
  self.band = nil
  local section = group(self, { full = true })
  local frame = box(section.body, { Name = "Custom", Size = UDim2.new(1, -4, 0, height or 0), BackgroundTransparency = 1, LayoutOrder = 2 })
  if not height then frame.AutomaticSize = Enum.AutomaticSize.Y end
  B.try("unnamed.custom", build, frame)
  return frame
end
function Page:empty(_, title, value)
  local section = group(self, { full = true, title = title or "nothing here yet" })
  section:note({ text = value or "" })
end

-- ---------------------------------------------------------------- the window
local function tabsWanted()
  local out = {}
  for _, page in ipairs(Window.order) do
    if not page.hidden and page.id ~= "home" and page.build then out[#out + 1] = page end
  end
  return out
end
local query = ""                      -- what the search box holds, lower case
-- Show only the rows of a tab that match the search (and the boxes they are in). Rows hidden for
-- reasons of their own are left as they are: only what the search hid is shown again.
local function filter(entry)
  if not (entry and entry.rows) then return false end
  local any, cards = false, {}
  for _, item in ipairs(entry.rows) do
    if item.frame.Parent then
      local found = query == "" or string.find(item.text, query, 1, true) ~= nil
      if found then
        if item.hidden then item.frame.Visible = true; item.hidden = nil end
        if item.card then cards[item.card] = true end
        any = true
      elseif item.frame.Visible then
        item.frame.Visible, item.hidden = false, true
      end
    end
  end
  for _, card in ipairs(entry.cards or {}) do
    local named = card.title ~= "" and string.find(card.title, query, 1, true) ~= nil
    local shown = query == "" or cards[card.frame] == true or named
    if shown and card.hidden then card.frame.Visible = true; card.hidden = nil
    elseif not shown and card.frame.Visible then card.frame.Visible, card.hidden = false, true end
    -- (a box found by its own title shows all it holds)
    if query ~= "" and named and not cards[card.frame] then
      for _, item in ipairs(entry.rows) do
        if item.card == card.frame and item.hidden then item.frame.Visible = true; item.hidden = nil end
      end
      any = true
    end
  end
  return any
end
local function buildPage(source)
  local entry = U.pages[source.id]
  if entry and entry.built then return entry end
  if not entry then
    -- (theirs: 7 px in from the left and the top, 5 from the right, and no bar drawn for the scrolling)
    local scroller = Instance.new("ScrollingFrame")
    scroller.Name = source.id
    scroller.BackgroundTransparency, scroller.BorderSizePixel = 1, 0
    scroller.Position, scroller.Size = UDim2.fromOffset(7, 7), UDim2.new(1, -12, 1, -14)
    scroller.CanvasSize = UDim2.new()
    scroller.AutomaticCanvasSize = Enum.AutomaticSize.Y
    scroller.ScrollingDirection = Enum.ScrollingDirection.Y
    scroller.ScrollBarThickness = 0
    scroller.TopImage, scroller.BottomImage = "", ""
    scroller.Visible = false
    scroller.Parent = U.body
    -- (an open list or tip belongs where it was opened: scrolled away, it goes)
    scroller:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
      if popup and popup.anchor and popup.anchor:IsDescendantOf(scroller) then closePopup() end
      hideTip()
    end)
    local content = box(scroller, { Name = "Content", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1 })
    list(content, 8)
    entry = setmetatable({ source = source, scroller = scroller, content = content, bands = 0, sections = 0, rows = {}, cards = {} }, Page)
    U.pages[source.id] = entry
  end
  entry.built = true
  B.try("unnamed.page." .. source.id, source.build, entry)
  if entry.sections == 0 then entry:empty(nil, "nothing here yet", "This tab is ready for its controls.") end
  if B.Keys and B.Keys.repaint then B.Keys.repaint() end
  return entry
end
local function unwear(instance)
  for index = #accented, 1, -1 do if accented[index][1] == instance then table.remove(accented, index) end end
end
local found = nil                      -- tab id -> true, for the tabs the search finds something on
-- Theirs: the tab in use has the window's own grey, white letters, a black line and the 1 px line of the accent on top;
-- the others the page's grey, letters two thirds as bright and a line of 25. (Ours: a tab the search found is in the accent.)
local function paintTabs()
  for _, tab in ipairs(U.tabs) do
    local on = tab.id == U.current
    tab.button.BackgroundColor3 = on and C.tabOn or C.tab
    tab.stroke.Color = on and C.black or C.tabEdge
    tab.line.Visible = on
    if found and found[tab.id] and not on then wear(tab.label, "TextColor3")
    else
      unwear(tab.label)
      tab.label.TextColor3 = on and C.text or C.dim
    end
  end
end
function U.go(id)
  local source = Window.pages[id]
  if not (source and U.built) then return end
  closePopup()
  hideTip()
  local entry = buildPage(source)
  for _, other in pairs(U.pages) do other.scroller.Visible = other == entry end
  U.current = id
  filter(entry)
  paintTabs()
end
-- the search: this tab first; if nothing here, the first tab that has it
function U.search(value)
  query = lower(value or "")
  query = string.gsub(query, "^%s+", "")
  query = string.gsub(query, "%s+$", "")
  if not U.built then return end
  found = nil
  if query ~= "" then
    found = {}
    for _, source in ipairs(tabsWanted()) do
      if filter(buildPage(source)) then found[source.id] = true end
    end
    if U.current and not found[U.current] then
      for _, source in ipairs(tabsWanted()) do
        if found[source.id] then U.go(source.id); return end
      end
    end
  else
    for _, entry in pairs(U.pages) do filter(entry) end
  end
  if U.current then U.go(U.current) end
end
-- Theirs: each tab as wide as its name at 16 plus 12, three quarters of the 29 px bar high, 8 px apart, from the left.
-- Their own seven names just fill a 550 px window. Ours are more: when they do not fit, the gaps close first and then the
-- letters go down a size at a time (to 12), so every tab stays in sight; past that the bar scrolls sideways, as theirs.
local FITS = { { 8, 16 }, { 6, 16 }, { 4, 16 }, { 4, 15 }, { 4, 14 }, { 3, 14 }, { 3, 13 }, { 2, 13 }, { 2, 12 } }
function U.rebuildTabs()
  if not U.built then return end
  for _, tab in ipairs(U.tabs) do tab.button:Destroy() end
  table.clear(U.tabs)
  local wanted = tabsWanted()
  local scale = U.sizer and U.sizer.Scale or 1
  local room = U.tabBar.AbsoluteSize.X / scale
  if room < 1 then room = frameSize().X - 26 end
  local gap, size = 8, 16
  for _, fit in ipairs(FITS) do
    gap, size = fit[1], fit[2]
    local sum = gap
    for _, page in ipairs(wanted) do sum += measure(lower(page.title), size) + 12 + 4 + gap end
    if sum <= room then break end
  end
  U.tabFit = { gap = gap, size = size }
  U.tabList.Padding = UDim.new(0, gap)
  for index, page in ipairs(wanted) do
    local name = lower(page.title)
    local button = ringed(box(U.tabBar, { Name = page.id, Size = UDim2.new(0, measure(name, size) + 12, 0.75, 0), BackgroundColor3 = C.tab, LayoutOrder = index }), C.line, 2)
    local line = wear(box(button, { Name = "Line", Size = UDim2.new(1, 0, 0, 1), Visible = false, ZIndex = 4 }), "BackgroundColor3")
    local rim = box(button, { Name = "Rim", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 2 })
    local stroke = Instance.new("UIStroke")
    stroke.Color, stroke.Thickness, stroke.LineJoinMode = C.tabEdge, 1, Enum.LineJoinMode.Miter
    stroke.Parent = rim
    local label = text(button, name, { Size = UDim2.new(1, 0, 1, -1), TextXAlignment = Enum.TextXAlignment.Center, TextSize = size, TextColor3 = C.dim, ZIndex = 3 })
    local click = hit(button)
    click.Activated:Connect(B.safe("unnamed.tab", function() UI.sfx("tab", 0.4); U.go(page.id) end))
    U.tabs[#U.tabs + 1] = { id = page.id, button = button, label = label, line = line, stroke = stroke }
  end
  if not (U.current and Window.pages[U.current]) and wanted[1] then U.current = (Window.startPage and Window.pages[Window.startPage] and Window.startPage) or wanted[1].id end
  paintTabs()
end
-- (theirs is drawn pixel for pixel; the one thing that scales it is the user's own Scale setting)
local function scaleNow()
  return (Config.get("app.scale") or 100) / 100
end
U.scaleNow = scaleNow
local MIN_W, MIN_H, MAX_W, MAX_H = 550, 300, 1100, 960
local function sizeWanted()
  local w, h = Config.get("app.unnamed.w"), Config.get("app.unnamed.h")
  return math.clamp(type(w) == "number" and w or W, MIN_W, MAX_W), math.clamp(type(h) == "number" and h or H, MIN_H, MAX_H)
end
-- their cursor while the menu is up: an arrow in the accent, turned 45 degrees, on a black one 2 px bigger; the game's own is hidden
local arrow, arrowBack
local function cursor(on)
  on = on and Config.get("app.unnamed.cursor") ~= false
  if on then
    if not arrow and U.gui then
      arrowBack = Instance.new("ImageLabel")
      arrowBack.Name, arrowBack.Image, arrowBack.ImageColor3 = "CursorBack", CURSOR, Color3.new(0, 0, 0)
      arrowBack.BackgroundTransparency, arrowBack.BorderSizePixel, arrowBack.Size, arrowBack.Rotation, arrowBack.ZIndex = 1, 0, UDim2.fromOffset(19, 19), -45, 124
      arrowBack.Parent = U.gui
      arrow = Instance.new("ImageLabel")
      arrow.Name, arrow.Image = "Cursor", CURSOR
      arrow.BackgroundTransparency, arrow.BorderSizePixel, arrow.Size, arrow.Rotation, arrow.ZIndex = 1, 0, UDim2.fromOffset(17, 17), -45, 125
      arrow.Parent = U.gui
      wear(arrow, "ImageColor3")
    end
    if arrow then arrow.Visible, arrowBack.Visible = true, true end
    if U.mouseIcon == nil then U.mouseIcon = UIS.MouseIconEnabled end
  else
    if arrow then arrow.Visible, arrowBack.Visible = false, false end
    if U.mouseIcon ~= nil then
      UIS.MouseIconEnabled = U.mouseIcon
      U.mouseIcon = nil
    end
  end
end
-- (each frame while it is up: the tip and the arrow go with the mouse, and the game's cursor stays hidden)
local function eachFrame()
  if not U.open then return end
  placeTip()
  if arrow and arrow.Visible then
    local mouse = UIS:GetMouseLocation()
    arrow.Position = UDim2.fromOffset(mouse.X, mouse.Y - 1)
    arrowBack.Position = UDim2.fromOffset(mouse.X - 1, mouse.Y - 2)
    -- (the game's own is hidden only once the arrow's picture is there: a picture that never comes would leave no cursor at all)
    if arrow.IsLoaded and UIS.MouseIconEnabled then UIS.MouseIconEnabled = false end
  end
end
-- an outline in the accent where the window will be: what moves while it is dragged or made bigger (theirs)
local function ghost()
  local frame = box(U.gui, { Name = "Ghost", BackgroundTransparency = 1, ZIndex = 100 })
  local line = Instance.new("UIStroke")
  line.Thickness = 1
  line.Color = accent()
  line.Parent = frame
  local at, size = U.holder.AbsolutePosition, U.holder.AbsoluteSize
  frame.Position = UDim2.fromOffset(at.X, at.Y + UI.inset().Y)
  frame.Size = UDim2.fromOffset(size.X, size.Y)
  return frame
end
function U.build()
  if U.built then return end
  U.built = true
  pickFont()
  local gui = B.screen(9050)
  gui:SetAttribute("OwnLetters", true)
  U.gui = gui
  U.modal = Instance.new("TextButton")
  U.modal.Text, U.modal.BackgroundTransparency, U.modal.Size, U.modal.Modal, U.modal.Visible = "", 1, UDim2.fromOffset(0, 0), true, false
  U.modal.Parent = gui
  local width, height = sizeWanted()
  -- theirs: a black frame, and 1 px to its right a frame in the main colour with the accent on its inner edge
  local holder = box(gui, { Name = "Unnamed", Size = UDim2.fromOffset(width, height), AnchorPoint = Vector2.new(0.5, 0.5),
    Position = UDim2.fromScale(Config.get("app.unnamed.x") or 0.5, Config.get("app.unnamed.y") or 0.5), BackgroundColor3 = C.black, Visible = false })
  U.holder = holder
  U.sizer = Instance.new("UIScale")
  U.sizer.Scale = scaleNow()
  U.sizer.Parent = holder
  local inner = lined(box(holder, { Name = "Inner", Position = UDim2.fromOffset(1, 0), Size = UDim2.fromScale(1, 1), BackgroundColor3 = C.main }))
  wear(inner, "BorderColor3")
  -- the title row, 25 px: the hub's name in the middle, the game at the right in the accent. Ours, at its left: the search
  -- box and the way back to the other look. Held anywhere else, it drags the window.
  local top = box(inner, { Name = "Top", Size = UDim2.new(1, 0, 0, 25), BackgroundTransparency = 1 })
  text(top, "based", { Name = "Title", Size = UDim2.fromScale(1, 1), TextSize = 18, TextXAlignment = Enum.TextXAlignment.Center })
  local status = B.Registry and B.Registry.status and B.Registry.status() or {}
  local where = text(top, lower(status.name or "universal"), { Name = "Version", Position = UDim2.fromOffset(-8, 0), Size = UDim2.fromScale(1, 1), TextSize = 16,
    TextXAlignment = Enum.TextXAlignment.Right })
  wear(where, "TextColor3")
  local seek, seekInner = well(top, { Name = "Search", Position = UDim2.fromOffset(8, 5), Size = UDim2.fromOffset(110, 15), ZIndex = 3 }, C.page)
  local seekBox = entryBox(seekInner, 13)
  seekBox.Position, seekBox.Size, seekBox.ZIndex = UDim2.fromOffset(4, 0), UDim2.new(1, -8, 1, 0), 9
  seekBox.PlaceholderText, seekBox.Text = "search...", ""
  U.seekBox = seekBox
  local seekToken = 0
  seekBox:GetPropertyChangedSignal("Text"):Connect(function()
    seekToken += 1
    local mine = seekToken
    task.delay(0.12, function() if mine == seekToken then B.try("unnamed.search", U.search, seekBox.Text) end end)
  end)
  seekBox.Focused:Connect(function() seek.BorderColor3 = accent() end)
  seekBox.FocusLost:Connect(function() seek.BorderColor3 = C.black end)
  local swap, swapInner = well(top, { Name = "Swap", Position = UDim2.fromOffset(124, 5), Size = UDim2.fromOffset(78, 15), ZIndex = 3 }, C.page)
  text(swapInner, "based look", { Size = UDim2.fromScale(1, 1), TextXAlignment = Enum.TextXAlignment.Center, TextSize = 13 })
  local swapHit = hit(swap, { ZIndex = 9 })
  hover(swapHit, swap)
  swapHit.Activated:Connect(B.safe("unnamed.swap", function() Config.set("app.gui", "based") end))
  tooltip(swapHit, "Back to the BASED window. Settings has this too.")
  -- the page area: the page colour with the line colour round it and black inside that; on it the tab bar, and the body
  local area = ringed(box(inner, { Name = "Area", Position = UDim2.fromOffset(8, 25), Size = UDim2.new(1, -16, 1, -33), BackgroundColor3 = C.page }), C.line)
  local areaInner = lined(box(area, { Name = "Inner", Size = UDim2.fromScale(1, 1), BackgroundColor3 = C.page }), C.black)
  local tabBar = Instance.new("ScrollingFrame")
  tabBar.Name = "Tabs"
  tabBar.BackgroundTransparency, tabBar.BorderSizePixel = 1, 0
  tabBar.Position, tabBar.Size = UDim2.fromOffset(0, 4), UDim2.new(1, -10, 0, 29)
  tabBar.ScrollingDirection = Enum.ScrollingDirection.X
  tabBar.CanvasSize = UDim2.new()
  tabBar.AutomaticCanvasSize = Enum.AutomaticSize.X
  tabBar.ScrollBarThickness = 0
  tabBar.Parent = areaInner
  U.tabBar = tabBar
  U.tabList = list(tabBar, 8, true)
  U.tabList.VerticalAlignment = Enum.VerticalAlignment.Center
  local tabPad = Instance.new("UIPadding")
  tabPad.PaddingTop = UDim.new(0, 1)
  tabPad.Parent = tabBar
  box(tabBar, { Name = "First", Size = UDim2.fromOffset(0, 0), BackgroundTransparency = 1, LayoutOrder = -1 })
  ringed(box(areaInner, { Name = "BodyLine", Position = UDim2.fromOffset(8, 38), Size = UDim2.new(1, -16, 1, -47), BackgroundColor3 = C.main }), C.line, 2)
  U.body = ringed(box(areaInner, { Name = "Body", Position = UDim2.fromOffset(8, 38), Size = UDim2.new(1, -16, 1, -47), BackgroundColor3 = C.main, ClipsDescendants = true,
    ZIndex = 2 }))
  -- the tip, theirs: the main colour with the line colour round it, one line at 14, as big as its words plus 5 and 4
  tip = ringed(text(holder, "", { Name = "Tip", Size = UDim2.fromOffset(0, 0), AutomaticSize = Enum.AutomaticSize.XY, BackgroundColor3 = C.main,
    BackgroundTransparency = 0, Visible = false, ZIndex = 100 }), C.line)
  pad(tip, 1, 2, 3, 3)
  -- dragging by the top 25 px: the outline moves, the window goes to it when the mouse is let go
  local grab = hit(top, { ZIndex = 1 })
  local from, start, outline
  UI.drag(grab, function(point)
    from, start = point, holder.AbsolutePosition
    if outline then outline:Destroy() end
    outline = ghost()
  end, function(point)
    if not outline then return end
    local at = start + (point - from)
    outline.Position = UDim2.fromOffset(at.X, at.Y + UI.inset().Y)
  end, function()
    if not outline then return end
    local at = Vector2.new(outline.Position.X.Offset, outline.Position.Y.Offset)
    outline:Destroy()
    outline = nil
    local camera = workspace.CurrentCamera
    local view = camera and camera.ViewportSize or Vector2.new(1920, 1080)
    local centre = at + holder.AbsoluteSize / 2
    holder.Position = UDim2.fromScale(util.clamp01(centre.X / view.X), util.clamp01(centre.Y / view.Y))
    Config.set("app.unnamed.x", holder.Position.X.Scale)
    Config.set("app.unnamed.y", holder.Position.Y.Scale)
  end)
  -- the corner it is made bigger or smaller by: theirs, a quarter of a disc in the accent, 25 px, half seen through.
  -- The outline shows the new size; the window takes it when the mouse is let go (the top left stays where it is).
  local corner = box(holder, { Name = "Resize", Position = UDim2.new(1, -25, 1, -25), Size = UDim2.fromOffset(25, 25), BackgroundTransparency = 1, ClipsDescendants = true,
    ZIndex = 20 })
  local disc = wear(box(corner, { Name = "Disc", Size = UDim2.fromScale(2, 2), BackgroundTransparency = 0.5, ZIndex = 21 }), "BackgroundColor3")
  local round = Instance.new("UICorner")
  round.CornerRadius = UDim.new(0.5, 0)
  round.Parent = disc
  local cornerHit = hit(corner, { ZIndex = 22 })
  local fromPoint, fromSize, fromCorner, sized, wantW, wantH
  UI.drag(cornerHit, function(point)
    local scale = U.sizer.Scale
    fromPoint, fromSize = point, holder.AbsoluteSize / scale
    fromCorner = holder.AbsolutePosition
    wantW, wantH = fromSize.X, fromSize.Y
    closePopup()
    hideTip()
    if sized then sized:Destroy() end
    sized = ghost()
  end, function(point)
    if not sized then return end
    local scale = U.sizer.Scale
    local camera = workspace.CurrentCamera
    local view = camera and camera.ViewportSize or Vector2.new(1920, 1080)
    local wanted = fromSize + (point - fromPoint) / scale
    wantW = math.clamp(wanted.X, MIN_W, math.max(MIN_W, math.min(MAX_W, view.X / scale)))
    wantH = math.clamp(wanted.Y, MIN_H, math.max(MIN_H, math.min(MAX_H, view.Y / scale)))
    sized.Size = UDim2.fromOffset(wantW * scale, wantH * scale)
  end, function()
    if not sized then return end
    sized:Destroy()
    sized = nil
    local scale = U.sizer.Scale
    local camera = workspace.CurrentCamera
    local view = camera and camera.ViewportSize or Vector2.new(1920, 1080)
    holder.Size = UDim2.fromOffset(wantW, wantH)
    -- (held by its centre: keep the top left corner where it was)
    local inset = UI.inset()
    local centre = fromCorner + Vector2.new(wantW, wantH) * scale / 2
    holder.Position = UDim2.fromScale(util.clamp01(centre.X / view.X), util.clamp01((centre.Y + inset.Y) / view.Y))
    Config.set("app.unnamed.w", math.floor(holder.Size.X.Offset + 0.5))
    Config.set("app.unnamed.h", math.floor(holder.Size.Y.Offset + 0.5))
    Config.set("app.unnamed.x", holder.Position.X.Scale)
    Config.set("app.unnamed.y", holder.Position.Y.Scale)
    U.rebuildTabs()
  end)
  tooltip(cornerHit, "Drag to resize.")
  -- a click anywhere outside an open list closes it
  B.connect(UIS.InputBegan, function(input)
    if not popup then return end
    if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
    local point = UI.point(input)
    if not (UI.inside(popup.frame, point) or (popup.anchor and popup.anchor.Parent and UI.inside(popup.anchor, point))) then closePopup() end
  end, "unnamed.outside")
  Config.on("app.unnamed.accent", repaint)
  Config.on("app.scale", function() if U.sizer then U.sizer.Scale = scaleNow() end end)
  Motion.every(eachFrame, nil, "unnamed.frame")
  B.onUnload:connect(function() cursor(false) end)
  U.rebuildTabs()
end
function U.show(on)
  if on and not U.built then U.build() end
  if not U.built or U.open == on then return end
  U.open = on
  closePopup()
  hideTip()
  -- (theirs: up or gone at once, nothing moves)
  U.holder.Visible = on
  U.modal.Visible = on and Config.get("app.freeCursor") ~= false
  cursor(on)
  if on then
    U.rebuildTabs()
    if U.current then U.go(U.current) end
    -- (all of it on the screen: one put half off it, or kept from a bigger screen, comes back in)
    task.defer(function()
      if not (U.open and U.holder) then return end
      local camera = workspace.CurrentCamera
      local view = camera and camera.ViewportSize or Vector2.new(1920, 1080)
      local size = U.holder.AbsoluteSize
      local inset = UI.inset()
      local centre = U.holder.AbsolutePosition + size / 2 + Vector2.new(0, inset.Y)
      local x = math.clamp(centre.X, size.X / 2 + 4, math.max(size.X / 2 + 4, view.X - size.X / 2 - 4))
      local y = math.clamp(centre.Y, size.Y / 2 + 4, math.max(size.Y / 2 + 4, view.Y - size.Y / 2 - 4))
      if math.abs(x - centre.X) > 1 or math.abs(y - centre.Y) > 1 then
        U.holder.Position = UDim2.fromScale(x / view.X, y / view.Y)
      end
    end)
    UI.sfx("open", 0.35)
  else
    if U.seekBox and U.seekBox:IsFocused() then U.seekBox:ReleaseFocus() end
    UI.sfx("close", 0.3)
  end
  if Window.onShow then Window.onShow:fire(Window.anyOpen()) end
end
function U.toggle() U.show(not U.open) end
-- the one that is in use: this, or the BASED window
function U.active() return Config.get("app.gui") == "unnamed" end
function U.toggleActive() Window.toggleActive() end

-- ---------------------------------------------------------------- the key list, drawn this way
-- What Keys puts on screen while the hub is hidden, in their look: the main colour with the line colour inside and
-- black outside, the 2 px line of the accent on top, "keybinds" in the middle, at least 210 wide, and a row a key,
-- 18 px at 13: [key] name (how it is used), in the accent while it is on.
function U.keyPanel(parent)
  local panel = lined(box(parent, { Name = "KeysUnnamed", Size = UDim2.fromOffset(0, 0), AutomaticSize = Enum.AutomaticSize.XY, BackgroundColor3 = C.main }), C.line)
  local ring = Instance.new("UIStroke")
  ring.Color, ring.Thickness, ring.LineJoinMode = C.black, 1, Enum.LineJoinMode.Miter
  ring.Parent = panel
  local least = Instance.new("UISizeConstraint")
  least.MinSize = Vector2.new(210, 0)
  least.Parent = panel
  wear(box(panel, { Name = "Line", Size = UDim2.new(1, 0, 0, 2), ZIndex = 2 }), "BackgroundColor3")
  local title = text(panel, "keybinds", { Name = "Title", Position = UDim2.fromOffset(0, 2), Size = UDim2.new(1, 0, 0, 20), TextXAlignment = Enum.TextXAlignment.Center,
    TextSize = 16 })
  local body = box(panel, { Name = "Body", Position = UDim2.fromOffset(0, 20), Size = UDim2.fromOffset(0, 0), AutomaticSize = Enum.AutomaticSize.XY, BackgroundTransparency = 1 })
  pad(body, 0, 5, 3, 5)
  list(body, 0)
  local api = { frame = panel, rows = {}, shape = nil }
  -- (lit: the whole row in the accent, at once, as theirs)
  local function light(row, on)
    row.on = on
    unwear(row.label)
    if on then wear(row.label, "TextColor3") else row.label.TextColor3 = C.text end
  end
  function api.forget() api.shape = nil end
  function api.render(binds, moving)
    local shape = B.Keys.shape(binds, moving, 12)
    if shape == api.shape then
      for _, bind in ipairs(binds) do
        local row = api.rows[bind.id]
        if row and row.on ~= bind.on then light(row, bind.on) end
      end
      return
    end
    api.shape = shape
    local before = {}
    for id, row in pairs(api.rows) do before[id] = row.on end
    table.clear(api.rows)
    for _, child in ipairs(body:GetChildren()) do
      if child:IsA("GuiObject") then child:Destroy() end
    end
    title.Text = moving and "keybinds  (drag, then lock)" or "keybinds"
    if moving then wear(title, "TextColor3") else unwear(title); title.TextColor3 = C.text end
    if #binds == 0 then
      text(body, "nothing bound yet", { Size = UDim2.fromOffset(0, 18), AutomaticSize = Enum.AutomaticSize.X, TextColor3 = C.dim, TextSize = 13, LayoutOrder = 1 })
      return
    end
    for index, bind in ipairs(binds) do
      if index > 12 then
        text(body, "+" .. (#binds - 12) .. " more", { Size = UDim2.fromOffset(0, 18), AutomaticSize = Enum.AutomaticSize.X, TextColor3 = C.dim, TextSize = 13, LayoutOrder = index })
        break
      end
      local words = "[" .. Config.keyLabel(bind.key) .. "] " .. lower(bind.label)
      if bind.kind == "toggle" then words = words .. (bind.mode == "hold" and " (hold)" or " (toggle)") end
      local label = text(body, words, { Name = "Bind_" .. bind.id, Size = UDim2.fromOffset(0, 18), AutomaticSize = Enum.AutomaticSize.X, TextSize = 13, LayoutOrder = index })
      local row = { label = label, key = label, name = label, hold = bind.mode == "hold" }
      api.rows[bind.id] = row
      local was = before[bind.id]
      light(row, (was == nil and bind.on or was) == true)
      if was ~= nil and was ~= bind.on then light(row, bind.on == true) end
    end
  end
  return api
end

-- ---------------------------------------------------------------- the kit (src/07): tabs that draw themselves, in this look
local function unwearOne(instance, property)
  for index = #accented, 1, -1 do
    local entry = accented[index]
    if entry[1] == instance and entry[2] == property then table.remove(accented, index) end
  end
end
local KIT_ROLES = { card = C.box, field = C.field, hover = C.fieldHi, line = C.edge, back = C.back, text = C.text, dim = C.dim, faint = C.faint,
  onAccent = Color3.new(1, 1, 1), good = rgb(82, 214, 160), bad = rgb(255, 101, 119) }
local kit = { look = "unnamed", radius = 0, small = 0, size = 12 }
function kit.owns(frame) return U.gui ~= nil and frame:IsDescendantOf(U.gui) end
function kit.color(role)
  if role == "accent" then return accent(), 0 end
  return KIT_ROLES[role] or C.text, 0
end
function kit.paint(instance, property, role)
  unwearOne(instance, property)
  if role == "accent" then wear(instance, property) else instance[property] = KIT_ROLES[role] or C.text end
end
function kit.fill(instance, role)
  kit.paint(instance, "BackgroundColor3", role)
  instance.BackgroundTransparency = 0
end
function kit.clear(instance) instance.BackgroundTransparency = 1 end
function kit.font(bold) if not FONT then pickFont() end return bold and BOLD or FONT end
function kit.text(parent, value, props, bold, size)
  local all = { TextSize = size or 12, TextTruncate = Enum.TextTruncate.AtEnd }
  if props then for key, v in pairs(props) do all[key] = v end end
  return text(parent, value, all, bold)
end
function kit.entry(parent, size) return entryBox(parent, size or 12) end
function kit.outline(frame) return lined(frame, C.edge) end
function kit.corner() return nil end
-- a short list under `anchor` (inside this menu): items as UI.menu takes them
function kit.menu(anchor, items)
  local rows, map = {}, {}
  for _, item in ipairs(items) do
    if type(item) == "table" then
      rows[#rows + 1] = { lower(item.label), item.checked == true }
      map[#rows] = item
    end
  end
  if #rows == 0 then return end
  openList(anchor, rows, function(index)
    local item = map[index]
    if item and item.run then B.try("unnamed.menu", item.run) end
    return item ~= nil and item.keepOpen == true
  end, false)
end
U.kit = kit
Window.kits.unnamed = kit

-- ---------------------------------------------------------------- the watermark
-- This look's version of the island: top left, under the game's own buttons. The hub's name, who
-- is playing, the game, frames a second, ping and the time; a click opens the menu.
-- Drawn as theirs: black outside, the main colour with the accent on its inner edge, a fill that is
-- darker at the bottom, the words at 14 from 5 px in, as high as the words and half again plus 3.
local mark
local function watermarkWanted() return U.active() and Config.get("app.unnamed.watermark") ~= false and Config.get("app.island") ~= false end
function U.watermark()
  if not Window.hud then return end
  if not watermarkWanted() then
    if mark then mark.frame.Visible = false end
    return
  end
  if not mark then
    local frame = lined(box(Window.hud, { Name = "Watermark", Size = UDim2.fromOffset(0, 24), AutomaticSize = Enum.AutomaticSize.X, BackgroundColor3 = C.main }))
    wear(frame, "BorderColor3")
    local ring = Instance.new("UIStroke")
    ring.Color, ring.Thickness, ring.LineJoinMode = C.black, 1, Enum.LineJoinMode.Miter
    ring.Parent = frame
    local sizer = Instance.new("UIScale"); sizer.Parent = frame
    local fill = box(frame, { Name = "Fill", Position = UDim2.fromOffset(1, 1), Size = UDim2.new(1, -2, 1, -2), BackgroundColor3 = Color3.new(1, 1, 1) })
    local fall = Instance.new("UIGradient")
    fall.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, darker(C.main)), ColorSequenceKeypoint.new(1, C.main) })
    fall.Rotation = -90
    fall.Parent = fill
    local line = box(frame, { Name = "Words", Size = UDim2.new(0, 0, 1, 0), AutomaticSize = Enum.AutomaticSize.X, BackgroundTransparency = 1, ZIndex = 2 })
    pad(line, 0, 10, 0, 5)
    list(line, 0, true)
    wear(text(line, "based", { Size = UDim2.new(0, 0, 1, 0), AutomaticSize = Enum.AutomaticSize.X, LayoutOrder = 1 }), "TextColor3")
    local rest = text(line, "", { Size = UDim2.new(0, 0, 1, 0), AutomaticSize = Enum.AutomaticSize.X, LayoutOrder = 2 })
    local click = hit(frame, { ZIndex = 9 })
    click.Activated:Connect(B.safe("unnamed.watermark", function() U.show(true) end))
    local status = B.Registry and B.Registry.status and B.Registry.status() or {}
    local where = lower(status.name or "universal")
    local who = lower(B.LP.Name)
    local function seat()
      local inset = UI.inset()
      sizer.Scale = scaleNow()
      frame.Position = UDim2.fromOffset(12, math.max(inset.Y, 0) + 10)
    end
    seat()
    mark = { frame = frame, seat = seat }
    Motion.every(function()
      if not frame.Visible then return end
      local hud = B.Hud
      local fps = hud and hud.fps and math.floor(hud.fps() + 0.5) or 0
      local ping = hud and hud.ping and math.floor(hud.ping() + 0.5) or 0
      rest.Text = string.format("  |  %s  |  %s  |  %d fps  |  %d ms  |  %s", who, where, fps, ping, os.date("%H:%M"))
    end, 2, "unnamed.watermark")
    Config.on("app.scale", function() if mark then mark.seat() end end)
  end
  mark.frame.Visible = true
end

-- switching looks: the other one is closed and this one opened where it was
function U.start()
  Config.define("app.gui", "based")
  Config.define("app.unnamed.accent", ACCENT)
  Config.define("app.unnamed.x", 0.5)
  Config.define("app.unnamed.y", 0.5)
  Config.define("app.unnamed.w", W)
  Config.define("app.unnamed.h", H)
  Config.define("app.unnamed.font", "roboto")
  Config.define("app.unnamed.textSize", 100)
  Config.define("app.unnamed.watermark", true)
  Config.define("app.unnamed.cursor", true)
  Config.on("app.gui", function(look)
    if look == "unnamed" then
      Window.show(false)
      U.show(true)
    else
      U.show(false)
      -- (the Novoline look opens itself: src/53)
      if look ~= "novoline" or not B.Novoline then Window.show(true) end
    end
    U.watermark()
  end)
  -- (the tabs are as wide as their names: new letters, new widths)
  local function relettered()
    refont()
    if U.built then U.rebuildTabs() end
  end
  Config.on("app.unnamed.font", relettered)
  Config.on("app.unnamed.textSize", relettered)
  Config.on("app.unnamed.cursor", function() if U.built then cursor(U.open) end end)
  Motion.every(sweepTyped, 0.1, "unnamed.sweep")
  Config.on("app.unnamed.watermark", function() U.watermark() end)
  Config.on("app.island", function() U.watermark() end)
  -- a tab added or taken away later (a game's tabs) shows up here as well
  local rebuildNav = Window.rebuildNav
  Window.rebuildNav = function(...)
    rebuildNav(...)
    if U.built then U.rebuildTabs() end
  end
end
end
do -- aotr.lua
-- ============================================================================
--  Attack on Titan Revolution   the mission, the nape, and round again
--
--  Read from the game and measured on 2026-11-12 (universe 4658598196; the
--  lobby "Town Central", place 14916516914 v9325, 110 scripts; the mission
--  "Shiganshina", place 13379349730 v1658, 515 scripts; one account, level 1).
--  What this module rests on:
--
--   * The game's client lives in an Actor (the lobby's under PlayerScripts, a
--     mission's inside the character). It talks to the server over two remotes,
--     ReplicatedStorage.Assets.Remotes.POST (an event: module, function, ...)
--     and GET (a function, the same shape). No key, no counter in either.
--   * A blade hit is the client's to report: Hitboxes / Register (the part of
--     Titan.Hitboxes.Hit that the body's Hitbox touched, the time the swing was
--     held). The server takes it only from a swing the game's own code made:
--     the same two calls sent by hand were refused four times out of four, at
--     rest and at speed. So the swing is the game's (ODMG.M1, then Input.Slash,
--     run inside its Actor) and the hit is its own Touched handler's.
--   * Damage grows with the body's velocity: the number beside it was 0.30 to
--     0.79 at 210 studs a second and 1 at 400. At 400 a nape hit on Easy kills.
--   * The server takes a hit straight after a jump of 1,700 studs: the body is
--     put behind the titan, not flown there.
--   * A blade is seven segments; a hit breaks one nineteen times in twenty.
--     Three spare sets (Blades / Reload), and a refill at a gas tank
--     (Attacks / Reload with the tank's Refill part: 5 s, ten a mission).
--   * A grab is a row of keys on the screen, and at its end the client sends
--     Attacks / Slash_Escape. It needs one unbroken segment. Sent 0.3 s after
--     the grab began, the server let go.
--   * The mission ends with workspace.Rewarded. Functions / Retry / Add starts
--     the same mission on a new server about fifteen seconds later.
--   * From the lobby: S_Missions / Create { Name, Type, Difficulty, Objective }
--     and S_Missions / Start.
--   * Nothing in either place's client kicks, bans or watches for a script.
--     What the server does about one is not known.
--
--  Not run live, and said so on the page: any map but Shiganshina, any
--  objective but Skirmish, raids, waves, spears, a party of more than one.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion = B.S, B.Config, B.Window, B.Motion

local AOT = { log = {}, kills = 0, passes = 0, hits = 0, missions = 0, grabs = 0, reloads = 0, refills = 0, status = nil }
B.AoTR = AOT
AOT.UNIVERSE, AOT.LOBBY, AOT.SHIGANSHINA = 4658598196, 14916516914, 13379349730
-- how long the blade is held, and how long the swing stays open after it (the game's own Air_Hit_1)
AOT.HOLD, AOT.WINDOW = 0.12, 0.45
AOT.MAPS = { "Shiganshina", "Trost", "Outskirts", "Forest", "Utgard", "Docks", "Stohess", "Chapel" }
AOT.DIFFICULTIES = { "Easy", "Normal", "Hard", "Severe", "Aberrant", "Freedom" }
AOT.STATS = {
  Blades = { "ODM_Damage", "ODM_Speed", "ODM_Control", "ODM_Gas", "ODM_Range", "Blade_Durability", "Crit_Chance", "Crit_Damage" },
  Spears = { "TS_Damage", "TS_Speed", "TS_Control", "TS_Gas", "TS_Range", "Blast_Radius", "Crit_Chance", "Crit_Damage" },
}

local O = {}
AOT.grab = { held = false, since = 0, sent = 0 }

-- ---------------------------------------------------------------- the two remotes
local function remotes()
  local assets = S.ReplicatedStorage:FindFirstChild("Assets")
  local folder = assets and assets:FindFirstChild("Remotes")
  if not folder then return nil, nil end
  return folder:FindFirstChild("POST"), folder:FindFirstChild("GET")
end
AOT.remotes = remotes
function AOT.send(...)
  local post = remotes()
  if not post then return false end
  post:FireServer(...)
  return true
end
-- Asks and waits no longer than `limit` s. The game's server answers with the remote itself for "nothing".
function AOT.invoke(limit, ...)
  local _, get = remotes()
  if not get then return nil end
  local args, done, out = table.pack(...), false, nil
  task.spawn(function()
    local got = table.pack(pcall(get.InvokeServer, get, table.unpack(args, 1, args.n)))
    B.identity()
    out, done = got, true
  end)
  local started = os.clock()
  while not done and B.alive and os.clock() - started < (limit or 6) do task.wait() end
  if not (done and out and out[1]) or out[2] == get then return nil end
  return table.unpack(out, 2, out.n)
end

function AOT.where()
  if workspace:FindFirstChild("Titans") and workspace:GetAttribute("Type") ~= nil then return "mission" end
  local map = workspace:GetAttribute("Map")
  if map == "Lobby" then return "lobby" end
  if map == "Trade" then return "trade" end
  return nil
end
function AOT.note(text)
  if AOT.status == text then return end
  local log = AOT.log
  log[#log + 1] = { at = os.clock(), text = text }
  if #log > 60 then table.remove(log, 1) end
  AOT.status = text
end
function AOT.toast(title, text, tone)
  if Config.get("aotr.toasts") == false then return end
  Window.toast({ title = title, text = text, icon = "swords", tone = tone or "accent", time = 4 })
end

-- ---------------------------------------------------------------- the game's own client
-- A few lines that live in the game's Actor: they find the client's table once, and on a count
-- written to PlayerScripts they swing as a press and a release of the key do. (After a call into
-- the game's modules a thread can no longer touch the hub's own instances: PlayerScripts it can.)
local AGENT = [==[
local lp = game:GetService("Players").LocalPlayer
local box = lp:FindFirstChildOfClass("PlayerScripts")
local G = getgenv()
if G.__BASED_AOT then pcall(function() G.__BASED_AOT:Disconnect() end) end
local host
local function find()
  local character = lp.Character
  if host and type(rawget(host, "Modules")) == "table" and type(rawget(host, "Cache")) == "table" and host.Cache.Character == character then return host end
  host = nil
  for _, value in ipairs(getgc(true)) do
    if type(value) == "table" then
      local ok, fits = pcall(function()
