    local got = scripts:GetAttribute("BASED_agent")
    if got == token then
      armed.actor, armed.token = actor, token
      return true
    elseif got == "nohost" then
      return false, "the game is still loading"
    end
    task.wait(0.05)
  end
  return false, "no answer"
end
local asked = 0
-- Has the game's client raise the blade. `keep` is called every frame of the wait. "held" when it is up.
function AOT.swing(keep)
  local scripts = box()
  if not scripts then return "nobox" end
  asked += 1
  local n = asked
  scripts:SetAttribute("BASED_slash", "")
  scripts:SetAttribute("BASED_cmd", n)
  local started = os.clock()
  while B.alive and os.clock() - started < 2.5 do
    local got = scripts:GetAttribute("BASED_slash")
    if type(got) == "string" and got ~= "" then
      local state, id = string.match(got, "^(%a+):(%d+)")
      if tonumber(id) == n then
        -- (let go, not only raised: a touch before the blade is let go counts for nothing)
        if state == "released" then return "released" end
        if state ~= "held" then return state end
      end
    end
    if keep then keep() end
    task.wait()
  end
  return "silent"
end

-- ---------------------------------------------------------------- the body
local function frame()
  local beat = S.RunService.Heartbeat
  local ok, dt = pcall(beat.Wait, beat)
  if ok and type(dt) == "number" and dt > 0 then return dt end
  return task.wait() or 1 / 60
end
local function place(root, cframe, velocity)
  root.CFrame = cframe
  root.AssemblyLinearVelocity = velocity or Vector3.zero
end
AOT.place = place
-- Through walls while the hub has the body: the spot behind a nape is often inside a house.
local softened = {}
local function soften()
  local character = B.character()
  if not character then return end
  for _, part in ipairs(character:GetChildren()) do
    if part:IsA("BasePart") and part.CanCollide then
      softened[part] = true
      part.CanCollide = false
    end
  end
end
local function harden()
  for part in pairs(softened) do
    if part.Parent then part.CanCollide = true end
  end
  table.clear(softened)
end
AOT.harden = harden
-- holds the body at `at` for `seconds`
local function rest(seconds, at)
  local started = os.clock()
  while B.alive and os.clock() - started < seconds do
    local root = B.root()
    if root and at then place(root, at) end
    frame()
  end
end
-- above the place the mission put the body down: out of every hand's reach
function AOT.perch()
  local points = workspace:FindFirstChild("Points")
  local main = points and points:FindFirstChild("Main")
  local base = main and main:IsA("BasePart") and main.Position or (B.root() and B.root().Position) or Vector3.zero
  return CFrame.new(base + Vector3.new(0, 160, 0))
end

-- ---------------------------------------------------------------- titans
local function napeOf(titan)
  local boxes = titan:FindFirstChild("Hitboxes")
  local hit = boxes and boxes:FindFirstChild("Hit")
  return hit and hit:FindFirstChild("Nape") or nil
end
AOT.napeOf = napeOf
function AOT.titans()
  local folder = workspace:FindFirstChild("Titans")
  local list = {}
  if not folder then return list end
  for _, titan in ipairs(folder:GetChildren()) do
    local root = titan:FindFirstChild("HumanoidRootPart")
    if root and titan:GetAttribute("Dead") ~= true and napeOf(titan) then list[#list + 1] = titan end
  end
  return list
end
-- The next one, by the order asked for: nearest (the quickest clear), farthest, smallest or biggest first.
local function weigh(titan, from, order)
  local root = titan.HumanoidRootPart
  if order == "far" then return -(root.Position - from).Magnitude end
  if order == "small" then return root.Size.Y end
  if order == "big" then return -root.Size.Y end
  return (root.Position - from).Magnitude
end
function AOT.pick(from, skip, order)
  local best, bestWeight = nil, math.huge
  for _, titan in ipairs(AOT.titans()) do
    if not (skip and skip[titan]) then
      local weight = weigh(titan, from, order)
      if weight < bestWeight then best, bestWeight = titan, weight end
    end
  end
  return best
end
function AOT.nearest(from, skip) return AOT.pick(from, skip, "near") end

-- ---------------------------------------------------------------- blades
function AOT.blades()
  local character = B.character()
  local rig = character and character:FindFirstChild("Rig_" .. character.Name)
  local hand = rig and rig:FindFirstChild("LeftHand")
  if not hand then return nil, nil end
  local segments, sets = 0, 0
  for n = 1, 7 do
    local blade = hand:FindFirstChild("Blade_" .. n)
    if blade and blade:GetAttribute("Broken") == nil then segments += 1 end
  end
  for n = 1, 3 do
    local spare = rig:FindFirstChild("Left_" .. n, true)
    if spare and spare:GetAttribute("Used") == nil then sets += 1 end
  end
  return segments, sets
end
function AOT.reload()
  local segments = AOT.blades()
  if segments and segments > 0 then AOT.invoke(3, "Blades", "Drop") end
  local ok = AOT.invoke(3, "Blades", "Reload")
  local now = AOT.blades()
  if ok == true or (now and now >= 7) then
    AOT.reloads += 1
    return true
  end
  return false
end
function AOT.tanks()
  local list = {}
  for _, item in ipairs(workspace:GetDescendants()) do
    if item.Name == "Refill" and item:IsA("BasePart") then list[#list + 1] = item end
  end
  return list
end
-- The nearest tank that no titan stands within 150 studs of (a refill is five seconds of standing still);
-- with none like that, the one whose nearest titan is farthest off.
function AOT.station(from)
  local titans = AOT.titans()
  local best, bestDistance, calm, calmest = nil, math.huge, nil, -math.huge
  for _, item in ipairs(AOT.tanks()) do
    local nearestTitan = math.huge
    for _, titan in ipairs(titans) do
      nearestTitan = math.min(nearestTitan, (titan.HumanoidRootPart.Position - item.Position).Magnitude)
    end
    local distance = (item.Position - from).Magnitude
    if nearestTitan >= 150 and distance < bestDistance then best, bestDistance = item, distance end
    if nearestTitan > calmest then calm, calmest = item, nearestTitan end
  end
  return best or calm
end
-- Stands in a gas tank's refill and asks for it as the R key there does. About five seconds.
function AOT.refill()
  local root = B.root()
  if not root then return false, "no body" end
  if (tonumber(B.LP:GetAttribute("Refills")) or 0) <= 0 then return false, "no refills left" end
  local tank = AOT.station(root.Position)
  if not tank then return false, "no tank" end
  local at = CFrame.new(tank.Position + Vector3.new(0, 3, 0))
  AOT.note("Refilling at a gas tank.")
  rest(0.35, at)
  AOT.send("Attacks", "Reload", tank)
  local started = os.clock()
  while B.alive and os.clock() - started < 9 do
    rest(0.25, at)
    -- (caught at the tank: the refill is lost, and the hand comes first)
    if AOT.grab.held then return false, "caught at the tank" end
    local segments, sets = AOT.blades()
    if segments and segments >= 7 and sets and sets >= 3 then
      AOT.refills += 1
      return true
    end
  end
  return false, "the tank gave nothing"
end

-- ---------------------------------------------------------------- one cut at one nape
-- The nape is the only part of a titan that a blade kills through, so it is always the nape; what
-- changes from one try to the next is the side it is come at from. The body is put a short flight
-- off the nape (no travel: the server took hits straight after a jump of 1,700 studs), the game's
-- client raises and lets go the blade, and only then is the body given its speed and let fly: the
-- engine carries it through the nape as it carries any flying body, and the game's own Touched
-- handler reports the hit. Measured over five missions: a body held at the nape and nudged was heard
-- four times in ten, one that flew in before the blade was let go five in ten, one that flew in
-- after it nine in ten. The speed the server reads is the body's velocity: at 400 the damage is whole.
local SIDES = {
  function(back, right) return (back * 0.82 + Vector3.new(0, 0.57, 0)).Unit end,      -- behind and above
  function(back, right) return (back * 0.3 + Vector3.new(0, 0.95, 0)).Unit end,       -- from the sky
  function(back, right) return (back * 0.7 + right * 0.6 + Vector3.new(0, 0.4, 0)).Unit end,   -- behind, to its right
  function(back, right) return (back * 0.7 - right * 0.6 + Vector3.new(0, 0.4, 0)).Unit end,   -- behind, to its left
}
AOT.SIDES = SIDES
AOT.RUN = 55
local function reachAlong(nape, axis)
  local inside = nape.CFrame:VectorToObjectSpace(axis)
  local size = nape.Size
  return math.abs(inside.X) * size.X / 2 + math.abs(inside.Y) * size.Y / 2 + math.abs(inside.Z) * size.Z / 2
end
-- how far ahead of the body's middle its Hitbox ends
local function bladeFront(character, root)
  local hitbox = character and character:FindFirstChild("Hitbox")
  if hitbox and hitbox:IsA("BasePart") then
    local offset = root.CFrame:ToObjectSpace(hitbox.CFrame).Position
    return math.clamp(-offset.Z + hitbox.Size.Z / 2, 1, 14)
  end
  return 5
end
AOT.bladeFront = bladeFront
-- where the body stands to come at this nape from side `try`, `gap` studs off it: its CFrame, and the way out of the nape
function AOT.spot(titan, try, gap)
  local nape = napeOf(titan)
  local root = B.root()
  if not (nape and root) then return nil end
  local side = SIDES[((try or 1) - 1) % #SIDES + 1]
  local frameOf = titan.HumanoidRootPart.CFrame
  local way = side(-frameOf.LookVector, frameOf.RightVector)
  local front = bladeFront(B.character(), root)
  return CFrame.lookAt(nape.Position + way * (reachAlong(nape, way) + front + (gap or AOT.RUN)), nape.Position), way
end
local grab = AOT.grab
local lastSwing = -math.huge
function AOT.strike(titan, try)
  local root, nape = B.root(), napeOf(titan)
  if not (root and nape and titan.Parent) then return false, "gone" end
  local speed = math.clamp(tonumber(O.speed) or 400, 200, 600)
  -- (No sooner than the server takes one. Measured: at 0.3 s four cuts in ten were heard, at 0.65 nine, at 0.8 all.)
  local due = lastSwing + (tonumber(O.cadence) or 0.7) - os.clock()
  if due > 0 then rest(due, AOT.perch()) end
  soften()
  local first = AOT.spot(titan, try)
  if not first then return false, "gone" end
  place(root, first)
  local state = AOT.swing(function()
    local now, at = B.root(), AOT.spot(titan, try)
    if now and at then place(now, at) end
  end)
  if state ~= "released" then return false, state end
  lastSwing = os.clock()
  AOT.passes += 1
  -- let fly: only the velocity is set, and the engine does the moving
  local started, before, landed = os.clock(), AOT.hits, false
  local limit = AOT.RUN / speed + 0.2
  while B.alive and os.clock() - started < math.min(limit, AOT.WINDOW) do
    root = B.root()
    if not (root and nape.Parent) or grab.held or titan:GetAttribute("Dead") == true then break end
    if AOT.hits > before then
      landed = true
      break
    end
    local delta = nape.Position - root.Position
    if delta.Magnitude < 3 then break end
    local way = delta.Unit
    place(root, CFrame.lookAt(root.Position, root.Position + way), way * speed)
    frame()
  end
  -- off its back at once: a hand takes most of a second to close
  root = B.root()
  if root and nape.Parent and not grab.held then place(root, CFrame.new(nape.Position + Vector3.new(0, 140, 0))) end
  local waited = os.clock()
  while B.alive and os.clock() - waited < 0.2 and titan.Parent and titan:GetAttribute("Dead") ~= true do
    if AOT.hits > before then landed = true end
    root = B.root()
    if root and nape.Parent and not grab.held then place(root, CFrame.new(nape.Position + Vector3.new(0, 140, 0))) end
    task.wait()
  end
  if titan:GetAttribute("Dead") == true or not titan.Parent then
    AOT.kills += 1
    return true
  end
  if grab.held then return false, "grabbed" end
  if not (landed or AOT.hits > before) then return false, "missed" end
  -- The blade went in and it still stands. Into the nape: that side works and it is cut there again.
  -- Into an arm or a leg that was in the way: this line is no good, and the next try comes from another.
  local struck = AOT.struck
  if struck and struck.titan == titan and os.clock() - struck.at < 1.5 and struck.part ~= nil and struck.part ~= "Nape" then return false, "glanced" end
  return false, "hurt"
end

-- ---------------------------------------------------------------- the mission
function AOT.over()
  if workspace:GetAttribute("Rewarded") == true then return true end
  local gui = B.LP:FindFirstChildOfClass("PlayerGui")
  local interface = gui and gui:FindFirstChild("Interface")
  local rewards = interface and interface:FindFirstChild("Rewards")
  return rewards ~= nil and rewards.Visible == true
end
function AOT.objective()
  local folder = S.ReplicatedStorage:FindFirstChild("Objectives")
  local slay = folder and folder:FindFirstChild("Slay")
  if not slay then return nil, nil end
  return tonumber(slay.Value), tonumber(slay:GetAttribute("Requirement"))
end
local ended = { at = nil, asked = false, home = false }
local began = nil
-- what the rewards screen says of the mission: true when it was not won
function AOT.lost()
  local gui = B.LP:FindFirstChildOfClass("PlayerGui")
  local interface = gui and gui:FindFirstChild("Interface")
  local rewards = interface and interface:FindFirstChild("Rewards")
  local state = rewards and rewards:FindFirstChild("State", true)
  if state and state:IsA("TextLabel") and state.Text ~= "" then
    return string.find(string.upper(state.Text), "COMPLET", 1, true) == nil
  end
  local humanoid = B.humanoid()
  return humanoid ~= nil and humanoid.Health <= 0
end
-- Growing by itself. Missions are run one after another on the same server-side settings (a retry), and every
-- few of them the hub goes home instead: the lobby is where gold becomes gear, and gear is what unlocks the
-- next difficulty (the average gear level: 2 for Normal, 5 Hard, 9 Severe, 12 Aberrant, 15 Freedom). From there
-- the hardest mission the server will make is made. A mission that was lost is not asked for again: the hub
-- goes home and stays one difficulty lower until the gear has grown.
local function finish()
  if not ended.at then
    ended.at = os.clock()
    AOT.missions += 1
    AOT.took = began and (ended.at - began) or nil
    local lost = AOT.lost()
    local streak = (tonumber(Config.get("aotr.streak")) or 0) + 1
    local every = math.clamp(tonumber(O.progressEvery) or 5, 1, 50)
    ended.home = O.progress == true and O.missions == true and (lost or streak >= every)
    if lost and O.progress then
      local now = table.find(AOT.DIFFICULTIES, workspace:GetAttribute("Difficulty")) or 1
      Config.set("aotr.cap", math.max(1, now - 1))
    end
    Config.set("aotr.streak", ended.home and 0 or streak)
    AOT.note(lost and "Mission lost." or "Mission over.")
    AOT.toast(lost and "Mission lost" or "Mission over", string.format("%d kills in %d cuts%s.", AOT.kills, AOT.passes, AOT.took and string.format(", %.0f s", AOT.took) or ""), lost and "warn" or "ok")
  end
  local root = B.root()
  if root then place(root, AOT.perch()) end
  -- (the rewards are counted out first: two seconds is what the screen takes to show them)
  if ended.asked or os.clock() - ended.at < 2 then return end
  if ended.home then
    ended.asked = true
    Config.flush()
    AOT.send("Functions", "Teleport")
    AOT.note("Going home to upgrade and move up.")
  elseif O.retry then
    ended.asked = true
    Config.flush()
    local ok = AOT.invoke(5, "Functions", "Retry", "Add")
    AOT.note(ok and "Asked for the same mission again." or "The retry was refused.")
    if not ok then
      task.delay(6, function() ended.asked = false end)
    end
  elseif O.leave then
    ended.asked = true
    Config.flush()
    AOT.send("Functions", "Teleport")
    AOT.note("Going back to the lobby.")
  end
end
AOT.cool, AOT.tries = setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" })
-- Out of a titan's hand: the row of keys on the screen ends in one call, and it is made here. It needs
-- an unbroken segment. Asked again every half second for as long as the hand holds.
function AOT.escape()
  if not grab.held then return false end
  local now = os.clock()
  if now - grab.since < (tonumber(O.escapeAfter) or 0.3) or now - grab.sent < 0.5 then return false end
  if now - grab.since > 8 then
    grab.held = false
    return false
  end
  grab.sent = now
  AOT.send("Attacks", "Slash_Escape")
  return true
end
local function missionStep()
  local character, humanoid, root = B.character(), B.humanoid(), B.root()
  if not (character and humanoid and root) then return 0.25 end
  if AOT.over() then
    finish()
    return 0.2
  end
  if humanoid.Health <= 0 then
    AOT.note("Down. Waiting for the mission to say so.")
    return 0.5
  end
  if not AOT.canReach() then
    AOT.note("This executor cannot reach the game's own client (run_on_actor).")
    return 2
  end
  local ok, why = AOT.arm()
  if not ok then
    AOT.note("Waiting for the game's client: " .. tostring(why) .. ".")
    return 0.5
  end
  began = began or os.clock()
  -- in a hand: nothing is done with the body until it is out
  if grab.held then
    AOT.note("Caught. Breaking out.")
    return 0.05
  end
  soften()
  -- hurt: sit high until it mends
  local floor = math.clamp(tonumber(O.restAt) or 30, 0, 90) / 100
  if humanoid.Health < humanoid.MaxHealth * floor then
    AOT.note("Hurt. Resting out of reach.")
    rest(1, AOT.perch())
    return 0
  end
  -- A segment or more is kept back: a grab cannot be broken with none. A new set, or a gas tank when the spares are gone.
  local keep = math.clamp(tonumber(O.keep) or 1, 0, 3)
  local segments, sets = AOT.blades()
  if segments ~= nil and segments <= keep and os.clock() - (AOT.bladeFailed or -math.huge) > 3 then
    local fixed, reason
    if sets > 0 then
      place(root, AOT.perch())
      fixed, reason = AOT.reload(), "the reload was refused"
    elseif O.refill ~= false then
      fixed, reason = AOT.refill()
    else
      fixed, reason = false, "refills are off"
    end
    if fixed then return 0 end
    AOT.bladeFailed = os.clock()
    if segments == 0 then AOT.note("Out of blades: " .. tostring(reason) .. ".") end
  end
  if segments == 0 then
    rest(0.5, AOT.perch())
    return 0
  end
  -- The next titan that has not just shrugged off a try: one that did is left for a moment and
  -- another is taken, so the same back is never worked over and over while a hand closes on the body.
  local now = os.clock()
  for titan, untilWhen in pairs(AOT.cool) do
    if untilWhen < now or not titan.Parent then AOT.cool[titan] = nil end
  end
  local titan = AOT.pick(root.Position, AOT.cool, O.order)
  if not titan then titan = AOT.pick(root.Position, nil, O.order) end
  if not titan then
    AOT.note("No titan standing. Waiting for the next.")
    rest(0.3, AOT.perch())
    return 0
  end
  local done, total = AOT.objective()
  AOT.note(done and total and string.format("Hunting: %d of %d.", done, total) or "Hunting.")
  local tries = AOT.tries[titan] or 1
  local killed, what = AOT.strike(titan, tries)
  if killed then
    AOT.tries[titan], AOT.cool[titan] = nil, nil
  elseif what == "hurt" then
    -- the blade went in and it still stands: this side works, and it is cut again at once
    AOT.cool[titan] = nil
  else
    -- (the next try at it comes from another side, and not before others have had theirs)
    if O.sides ~= false then AOT.tries[titan] = tries + 1 end
    AOT.cool[titan] = os.clock() + (tries % #SIDES == 0 and 3 or 1)
    if what == "nohost" or what == "silent" or what == "err" then armed.token = nil end
  end
  return 0
end

-- ---------------------------------------------------------------- the lobby
local lobby = { since = nil, login = false, upgraded = false, tried = 0, started = false }
function AOT.party()
  local folder = S.ReplicatedStorage:FindFirstChild("Missions")
  if not folder then return nil end
  for _, item in ipairs(folder:GetDescendants()) do
    if item.Name == "Leader" and item:IsA("StringValue") and item.Value == B.LP.Name then return item.Parent end
  end
  return nil
end
local function order()
  local wanted = O.difficulty
  if wanted ~= "Auto" and table.find(AOT.DIFFICULTIES, wanted) then return { wanted } end
  local list = {}
  local cap = O.progress and math.clamp(tonumber(O.cap) or #AOT.DIFFICULTIES, 1, #AOT.DIFFICULTIES) or #AOT.DIFFICULTIES
  for index = cap, 1, -1 do list[#list + 1] = AOT.DIFFICULTIES[index] end
  return list
end
function AOT.create()
  local maps = {}
  local boosted = workspace:GetAttribute("Boosted_Mission")
  if O.boosted and type(boosted) == "string" and table.find(AOT.MAPS, boosted) then maps[#maps + 1] = boosted end
  if not table.find(maps, O.map) then maps[#maps + 1] = table.find(AOT.MAPS, O.map) and O.map or "Shiganshina" end
  for _, map in ipairs(maps) do
    for _, difficulty in ipairs(order()) do
      if not B.alive then return nil end
      local made = AOT.invoke(5, "S_Missions", "Create", { Name = map, Type = "Missions", Difficulty = difficulty, Objective = "Skirmish" })
      if typeof(made) == "Instance" then
        AOT.note(string.format("Mission made: %s, %s.", map, difficulty))
        return made
      end
      task.wait(0.35)
    end
  end
  return nil
end
function AOT.claimLogin()
  local data, kind = AOT.invoke(5, "Functions", "Login")
  if data ~= nil and kind ~= nil then
    AOT.toast("Daily reward", tostring(kind) .. " claimed.", "ok")
    return true
  end
  return false
end
function AOT.buyUpgrades()
  local bought = 0
  for _ = 1, 16 do
    if not B.alive then break end
    local data = AOT.invoke(5, "S_Equipment", "Upgrade", table.clone(AOT.STATS.Blades))
    if data == nil then break end
    bought += 1
    task.wait(0.3)
  end
  if bought > 0 then AOT.toast("Gear upgraded", string.format("%d rounds of upgrades bought.", bought), "ok") end
  return bought
end
local function lobbyStep()
  lobby.since = lobby.since or os.clock()
  -- (the lobby loads the player's data first: nothing is asked of it before that)
  if os.clock() - lobby.since < 5 or B.LP:GetAttribute("Teleporting") == true then return 0.5 end
  if O.login and not lobby.login then
    lobby.login = true
    AOT.claimLogin()
  end
  if O.upgrade and not lobby.upgraded then
    lobby.upgraded = true
    -- (stronger gear: the difficulty a lost mission ruled out is tried again)
    if AOT.buyUpgrades() > 0 then Config.set("aotr.cap", #AOT.DIFFICULTIES) end
  end
  -- (a start that led nowhere in 45 s was a teleport that failed: it is asked again)
  if lobby.started and os.clock() - (lobby.startedAt or 0) > 45 then lobby.started = false end
  if not O.missions or lobby.started then return 1 end
  if os.clock() - (lobby.last or -math.huge) < 6 then return 0.5 end
  lobby.last = os.clock()
  lobby.tried += 1
  local party = AOT.party() or AOT.create()
  if not party then
    AOT.note("The lobby would not make a mission. Trying again.")
    return 1
  end
  local code = AOT.invoke(8, "S_Missions", "Start")
  if code ~= nil then
    lobby.started, lobby.startedAt = true, os.clock()
    AOT.note("Mission starting.")
  else
    AOT.note("The mission would not start. Trying again.")
  end
  return 1
end

-- ---------------------------------------------------------------- what is drawn
-- A box on every nape and a mark on every gas tank: the hub's own instances, in its own folder, seen by no one else.
local marks = { napes = {}, tanks = {}, folder = nil }
AOT.marks = marks
local function markFolder()
  if marks.folder and marks.folder.Parent then return marks.folder end
  local folder = Instance.new("Folder")
  folder.Name = "AoTR"
  folder.Parent = (type(gethui) == "function" and gethui()) or S.CoreGui
  B.own(folder)
  marks.folder = folder
  return folder
end
local function clearMarks(kind)
  for key, item in pairs(marks[kind]) do
    item:Destroy()
    marks[kind][key] = nil
  end
end
local function drawMarks()
  if AOT.where() ~= "mission" then
    clearMarks("napes"); clearMarks("tanks")
    return
  end
  if O.showNapes then
    local seen = {}
    local colour = typeof(O.napeColor) == "Color3" and O.napeColor or Color3.fromRGB(255, 70, 70)
    for _, titan in ipairs(AOT.titans()) do
      local nape = napeOf(titan)
      seen[nape] = true
      local mark = marks.napes[nape]
      if not mark then
        mark = Instance.new("BoxHandleAdornment")
        mark.Name = "Nape"
        mark.AlwaysOnTop, mark.ZIndex, mark.Transparency = true, 5, 0.55
        mark.Adornee = nape
        mark.Parent = markFolder()
        marks.napes[nape] = mark
      end
      mark.Size, mark.Color3 = nape.Size, colour
    end
    for nape, mark in pairs(marks.napes) do
      if not seen[nape] then
        mark:Destroy()
        marks.napes[nape] = nil
      end
    end
  else
    clearMarks("napes")
  end
  if O.showTanks then
    if next(marks.tanks) == nil then
      for _, tank in ipairs(AOT.tanks()) do
        local mark = Instance.new("BoxHandleAdornment")
        mark.Name = "Tank"
        mark.AlwaysOnTop, mark.ZIndex, mark.Transparency = true, 4, 0.6
        mark.Color3, mark.Size, mark.Adornee = Color3.fromRGB(90, 200, 255), tank.Size, tank
        mark.Parent = markFolder()
        marks.tanks[tank] = mark
      end
    end
  else
    clearMarks("tanks")
  end
end
AOT.drawMarks = drawMarks

-- ---------------------------------------------------------------- travel
-- The body, put somewhere at once. Never while the farm has it.
function AOT.go(where)
  if O.farm then return false, "The farm has the body." end
  local root = B.root()
  if not root or AOT.where() ~= "mission" then return false, "Only in a mission." end
  if where == "perch" then
    place(root, AOT.perch())
  elseif where == "tank" then
    local tank = AOT.station(root.Position)
    if not tank then return false, "No gas tank here." end
    place(root, CFrame.new(tank.Position + Vector3.new(0, 3, 0)))
  elseif where == "titan" then
    local titan = AOT.nearest(root.Position)
    local at = titan and AOT.spot(titan, 1, 30)
    if not at then return false, "No titan standing." end
    place(root, at)
  else
    return false, "Nowhere."
  end
  return true
end

-- ---------------------------------------------------------------- start
local FULL = { "farm", "retry", "missions", "login", "upgrade", "escape", "progress" }
function AOT.preset(on)
  for _, id in ipairs(FULL) do Config.set("aotr." .. id, on == true) end
end
local DEFAULTS = {
  farm = false, retry = true, leave = false, missions = false, map = "Shiganshina", difficulty = "Auto", boosted = true, login = false, upgrade = false,
  escape = true, escapeAfter = 0.3, speed = 400, cadence = 0.7, sides = true, order = "near", keep = 1, refill = true, restAt = 30,
  showNapes = false, showTanks = false, napeColor = Color3.fromRGB(255, 70, 70), follow = true, toasts = true,
  progress = false, progressEvery = 5, streak = 0, cap = 6, minimise = true,
}
AOT.DEFAULTS = DEFAULTS
local function start(hub)
  local map = {}
  for id, default in pairs(DEFAULTS) do
    Config.define("aotr." .. id, default)
    map[id] = "aotr." .. id
  end
  O = Config.mirror(map)
  AOT.O = O

  -- what the server says of a grab and of a hit
  local post = remotes()
  if post then
    B.connect(post.OnClientEvent, function(module, fn, what, ...)
      if module == "Titans" and fn == "Grab_Event" then
        if what == "Start" then
          AOT.grabs += 1
          grab.held, grab.since, grab.sent = true, os.clock(), 0
        elseif what == nil then
          grab.held = false
        end
      elseif module == "ODMG" and (fn == "Escaping" or fn == "Fling") then
        grab.held = false
      elseif module == "Effects" and fn == "Hit" and what == "Hit" then
        -- (Effects / Hit / "Hit", the titan, the part of it the blade went into)
        local titan, part = ...
        AOT.struck = { titan = titan, part = typeof(part) == "Instance" and part.Name or nil, at = os.clock() }
      elseif module == "Zones" and fn == "Damage_Check" and type(what) == "number" and what > 0 then
        AOT.hits += 1
        AOT.lastDamage = what
      end
    end, "aotr.post")
  end
  -- Out of a hand whether the farm is on or the player flies by hand: it is its own switch.
  Motion.every(function()
    if grab.held and O.escape and AOT.where() == "mission" then AOT.escape() end
  end, 20, "aotr.escape")
  Motion.every(function() B.try("aotr.marks", drawMarks) end, 4, "aotr.marks")

  -- the body is the farm's only while the farm is on
  Config.on("aotr.farm", function(on)
    if not on then harden() end
  end)

  task.spawn(function()
    while B.alive do
      local pause = 0.5
      if AOT.started then
        local where = AOT.where()
        local ok, value = true, nil
        if where == "mission" and O.farm then
          ok, value = pcall(missionStep)
        elseif where == "lobby" and (O.missions or O.login or O.upgrade) then
          ok, value = pcall(lobbyStep)
        else
          AOT.status = nil
        end
        B.identity()
        if ok then pause = tonumber(value) or 0.5 else AOT.note("Fault: " .. tostring(value)); pause = 1 end
      end
      if pause > 0 then task.wait(pause) end
    end
  end)

  -- The hub comes back on the other side of every teleport. Once a session: what is queued stacks.
  local function follow()
    local World = B.World
    local file = type(B.genv.BASED_FILE) == "string" and B.genv.BASED_FILE or "BasedHub.lua"
    -- (the mark names the file queued: the same file is not queued twice, another one run after it is, and comes back)
    if (World and World.queued) or AOT.queued or B.genv.BASED_FOLLOWING == file or not Config.get("aotr.follow") or type(queue_on_teleport) ~= "function" then return end
    AOT.queued = true
    B.genv.BASED_FOLLOWING = file
    if World then World.queued = true end
    local carry = string.format('getgenv().BASED_FILE = %q; getgenv().BASED_INTRO = "off"', file)
    -- (and it comes up minimised there: a farm that goes from mission to mission does not open its window on each)
    if Config.get("aotr.minimise") ~= false then carry = carry .. "; getgenv().BASED_MINIMISED = true" end
    pcall(queue_on_teleport, World and World.followText and World.followText(file, carry) or string.format('pcall(function() %s; loadstring(readfile(%q))() end)', carry, file))
  end
  Config.on("aotr.follow", follow)
  follow()
end

-- ---------------------------------------------------------------- the tabs
local function statusLine()
  local where = AOT.where()
  local parts = {}
  parts[#parts + 1] = where == "mission" and "In a mission" or where == "lobby" and "In the lobby" or where == "trade" and "In the trade hub" or "Loading"
  local level, prestige = B.LP:GetAttribute("Level"), B.LP:GetAttribute("Prestige")
  if level then parts[#parts + 1] = "Level " .. tostring(level) end
  if prestige and prestige ~= 0 then parts[#parts + 1] = "Prestige " .. tostring(prestige) end
  parts[#parts + 1] = string.format("%d kills", AOT.kills)
  if AOT.missions > 0 then parts[#parts + 1] = string.format("%d missions", AOT.missions) end
  local segments, sets = AOT.blades()
  if segments then parts[#parts + 1] = string.format("blade %d/7, %d spare", segments, sets) end
  return table.concat(parts, "  ·  ")
end
AOT.statusLine = statusLine
local function told(ok, why, done)
  if ok then
    Window.toast({ title = done or "Done", icon = "circle-check", tone = "ok", time = 3 })
  else
    Window.toast({ title = "Not now", text = tostring(why or ""), icon = "info", time = 3 })
  end
end

local function farmPage(hub)
  hub:page({ id = "farm", title = "Farm", icon = "repeat", build = function(page)
    local you = page:section({ title = "You", icon = "user", full = true })
    local line = you:note({ icon = "activity", text = statusLine() })
    local doing = you:note({ icon = "info", text = "" })
    you:button({ id = "aotr.full", label = "Full auto", desc = "Missions, kills, retry, daily reward, gear upgrades and moving up: all on.", text = "Switch on", run = function()
      AOT.preset(true)
      Window.toast({ title = "Full auto is on", text = "Gold is spent on gear upgrades only.", icon = "repeat", tone = "ok", time = 4 })
    end })
    you:button({ id = "aotr.stop", label = "Stop", desc = "Everything off. The body is yours again.", text = "Switch off", run = function()
      AOT.preset(false)
      Window.toast({ title = "The farm is off", icon = "circle-pause", time = 3 })
    end })
    Motion.every(function()
      if not (line.frame.Parent and Window.anyOpen()) then return end
      line.set(statusLine())
      doing.set(AOT.status or "Idle.")
    end, 2, "aotr.status")

    local mission = page:section({ title = "Mission", icon = "swords" })
    mission:toggle({ id = "aotr.farm", label = "Kill titans", desc = "Jumps behind each titan and cuts its nape.", default = false })
    mission:toggle({ id = "aotr.retry", label = "Retry when it ends", desc = "Asks for the same mission again.", default = true })
    mission:toggle({ id = "aotr.leave", label = "Or go back to the lobby", desc = "Only when Retry is off.", default = false })
    mission:note({ icon = "info", text = "Run live on Shiganshina, Skirmish, blades. Other maps and raids are untested." })

    local session = page:section({ title = "Session", icon = "plug" })
    session:toggle({ id = "aotr.follow", label = "Come back after teleports", desc = "Starts BASED again in the mission and the lobby.", default = true, bindable = false })
    session:toggle({ id = "aotr.minimise", label = "Stay minimised after teleports", desc = "The window stays down in each new mission. The menu key opens it.", default = true, bindable = false })
    session:toggle({ id = "aotr.toasts", label = "Say what it did", desc = "A note for a mission, a reward, an upgrade.", default = true, bindable = false })
  end })
end
local function bladePage(hub)
  hub:page({ id = "blade", title = "Blade", icon = "sword", build = function(page)
    local cut = page:section({ title = "The cut", icon = "zap" })
    cut:slider({ id = "aotr.speed", label = "Speed", tip = "400 is full damage. Slower hits weaker.", min = 250, max = 600, step = 10, default = 400, suffix = " studs/s" })
    cut:slider({ id = "aotr.cadence", label = "A cut every", tip = "The server takes one about every 0.7 s. Faster ones are refused.", min = 0.4, max = 1.5, step = 0.05, default = 0.7, suffix = " s" })
    cut:toggle({ id = "aotr.sides", label = "New side after a miss", desc = "Behind, the sky, right, left: never the same line twice.", default = true })

    local targets = page:section({ title = "Targets", icon = "scan-line" })
    targets:dropdown({ id = "aotr.order", label = "Order", options = { { "near", "Nearest first" }, { "far", "Farthest first" }, { "small", "Smallest first" }, { "big", "Biggest first" } }, default = "near" })
    targets:note({ icon = "info", text = "Only the nape kills, so it is always the nape." })

    local supply = page:section({ title = "Blades", icon = "package" })
    supply:slider({ id = "aotr.keep", label = "Segments kept", tip = "Reloads before the blade is gone. One is needed to break a grab.", min = 0, max = 3, step = 1, default = 1 })
    supply:toggle({ id = "aotr.refill", label = "Refill at gas tanks", desc = "When the spare sets are gone. Five seconds.", default = true })

    local safe = page:section({ title = "Safety", icon = "shield" })
    safe:toggle({ id = "aotr.escape", label = "Break out of grabs", desc = "Works with the farm off too.", default = true })
    safe:slider({ id = "aotr.escapeAfter", label = "Break out after", tip = "0.3 s worked every time.", min = 0.2, max = 1.5, step = 0.05, default = 0.3, suffix = " s" })
    safe:slider({ id = "aotr.restAt", label = "Rest under", tip = "Sits out of reach until health is back above this.", min = 0, max = 90, step = 5, default = 30, suffix = "%" })
  end })
end
local function titansPage(hub)
  hub:page({ id = "titans", title = "Titans", icon = "binoculars", build = function(page)
    local see = page:section({ title = "See", icon = "aperture" })
    see:toggle({ id = "aotr.showNapes", label = "Show napes", desc = "A box on every weak spot, through walls.", default = false })
    see:color({ id = "aotr.napeColor", label = "Nape colour", default = Color3.fromRGB(255, 70, 70) })
    see:toggle({ id = "aotr.showTanks", label = "Show gas tanks", desc = "Where blades and gas are refilled.", default = false })
    local count = see:note({ icon = "activity", text = "" })
    Motion.every(function()
      if not (count.frame.Parent and Window.anyOpen()) then return end
      local done, total = AOT.objective()
      count.set(string.format("%d standing%s", #AOT.titans(), done and total and string.format("  ·  %d of %d slain", done, total) or ""))
    end, 2, "aotr.count")

    local go = page:section({ title = "Go", icon = "plane" })
    go:button({ id = "aotr.goPerch", label = "Safe spot", desc = "High above the start, out of reach.", text = "Go", run = function() told(AOT.go("perch")) end })
    go:button({ id = "aotr.goTank", label = "Nearest gas tank", desc = "Stand in it and press your reload key.", text = "Go", run = function() told(AOT.go("tank")) end })
    go:button({ id = "aotr.goTitan", label = "Above the nearest titan", desc = "Thirty studs off its nape.", text = "Go", run = function() told(AOT.go("titan")) end })
    go:note({ icon = "info", text = "Only with the farm off: the farm has the body while it runs." })
  end })
end
local function missionsPage(hub)
  hub:page({ id = "missions", title = "Missions", icon = "rocket", build = function(page)
    local town = page:section({ title = "From the lobby", icon = "rocket" })
    town:toggle({ id = "aotr.missions", label = "Start missions", desc = "Makes a Skirmish mission and starts it.", default = false })
    local maps = {}
    for _, map in ipairs(AOT.MAPS) do maps[#maps + 1] = { map, map } end
    town:dropdown({ id = "aotr.map", label = "Map", options = maps, default = "Shiganshina" })
    town:dropdown({ id = "aotr.difficulty", label = "Difficulty", options = { { "Auto", "Hardest I can" }, { "Easy", "Easy" }, { "Normal", "Normal" }, { "Hard", "Hard" },
      { "Severe", "Severe" }, { "Aberrant", "Aberrant" }, { "Freedom", "Freedom" } }, default = "Auto" })
    town:toggle({ id = "aotr.boosted", label = "Prefer the boosted map", desc = "Tries the map with the reward boost first.", default = true })

    local grow = page:section({ title = "Progress", icon = "sprout" })
    grow:toggle({ id = "aotr.progress", label = "Move up by itself", desc = "Goes home every few missions, upgrades, then takes the hardest mission it can.", default = false })
    grow:slider({ id = "aotr.progressEvery", label = "Missions per trip", tip = "How many are run before it goes home to upgrade.", min = 1, max = 20, step = 1, default = 5 })
    grow:note({ icon = "info", text = "Needs Start missions on. After a lost mission it steps down one difficulty until the gear grows." })

    local gear = page:section({ title = "Rewards and gear", icon = "gem" })
    gear:toggle({ id = "aotr.login", label = "Claim the daily reward", desc = "Once each time you reach the lobby.", default = false })
    gear:toggle({ id = "aotr.upgrade", label = "Upgrade my gear", desc = "Spends gold on gear levels. They unlock harder missions.", default = false })
    gear:button({ id = "aotr.claimNow", label = "Daily reward", desc = "Claims it now. Lobby only.", text = "Claim", run = function()
      if AOT.where() ~= "lobby" then return told(false, "Only in the lobby.") end
      task.spawn(function() told(AOT.claimLogin(), "Nothing to claim.", "Claimed") end)
    end })
    gear:button({ id = "aotr.upgradeNow", label = "Upgrades", desc = "Buys every gear level the gold allows. Lobby only.", text = "Buy", run = function()
      if AOT.where() ~= "lobby" then return told(false, "Only in the lobby.") end
      task.spawn(function() told(AOT.buyUpgrades() > 0, "Not enough gold.", "Upgraded") end)
    end })
    gear:note({ icon = "info", text = "Quests, achievements and the battle pass are not claimed yet." })
  end })
end

B.game({
  id = "aotr",
  name = "Attack on Titan Revolution",
  tagline = "One cut. One nape.",
  universes = { 4658598196 },
  places = { 14916516914, 13379349730 },
  icon = "swords",
  tabs = function(hub)
    start(hub)
    AOT.started = true
    farmPage(hub)
    bladePage(hub)
    titansPage(hub)
    missionsPage(hub)
  end,
})
end
do -- beeswarm.lua
-- ============================================================================
--  Bee Swarm Simulator   collect, convert, hatch, quest, and again
--
--  Read from the game on 2026-11-18 (place 1537690962, universe 601130232, version 1993: 1,313
--  client scripts decompiled, and the live state of a fresh account). What this module rests on,
--  each measured on the client unless it says "read":
--
--   * Every call to the server goes through ReplicatedStorage.Events.ClientCall(name, ...): it
--     invokes a RemoteFunction or fires a RemoteEvent of that name (all in ReplicatedStorage.Events).
--     The hub calls the same function, with the same arguments the game's own code passes.
--   * The swing is Collectors.LocalCollect.Run(): it keeps to the collector's cooldown (Scooper
--     0.8 s) and sends ToolCollect. 8 swings in 6 s at Dandelion Field took pollen 0 -> 48.
--   * ClaimHive(id) and GiveQuest(name) work from anywhere (70 and 187 studs away). Honey is made
--     only at the hive pad: ToggleHoneyMaking from the field did nothing, at the pad it started at once.
--   * A token is picked up by the server when the body is within 5 studs of it (read: Collectibles,
--     squared distance < 25). Each client is sent only the tokens it may take, so everything in
--     workspace.Collectibles is ours. A token's kind is its picture: the names come from the game's
--     own icons (EggTypes decals, Buffs, BeeAbilityDefs).
--   * What the server holds of the player: ClientStatCache:Get() (eggs, bees, quests, toy times ...)
--     and the CoreStats folder (Honey, Pollen, Capacity), both read, never written.
--   * Trading, Robux and the game's paid boards are never called from here (NEVER below).
--
--  The parts (games/beeswarm_*.lua) each own one thing: the farm, the hive and the shop, the
--  quests, the free things. This file is what they share.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util

local BS = { parts = {}, log = {}, calls = 0, refused = 0, started = false, reasons = {} }
B.BeeSwarm = BS
BS.PLACE, BS.UNIVERSE, BS.VERSION = 1537690962, 601130232, 1993

-- ---------------------------------------------------------------- the game's own modules
local mods = {}
-- require of a game module by its path under ReplicatedStorage ("Collectors.LocalCollect"): the game's own table
function BS.mod(path)
  local cached = mods[path]
  if cached then return cached end
  if type(require) ~= "function" then return nil end
  local node = S.ReplicatedStorage
  for name in string.gmatch(path, "[^%.]+") do
    node = node and node:FindFirstChild(name)
  end
  if not (node and node:IsA("ModuleScript")) then return nil end
  local ok, value = pcall(require, node)
  B.identity()
  if ok and type(value) == "table" then
    mods[path] = value
    return value
  end
  return nil
end
-- (a call into the game's code: its answer, or nil when it threw)
function BS.ask(fn, ...)
  if type(fn) ~= "function" then return nil end
  local out = table.pack(pcall(fn, ...))
  B.identity()
  if not out[1] then return nil end
  return table.unpack(out, 2, out.n)
end

-- ---------------------------------------------------------------- remotes
-- trading, Robux, the boost market, the game's own challenge rounds and its admin event: never sent from here
local NEVER = { TradePlayerRequestStart = true, TradePlayerDenyRequest = true, TradePlayerCancel = true, PlayerPurchase = true,
  BoostMarketEvent = true, AdminFeedback = true, RoboBearRoundStart = true, RoboBearReroll = true, RetroChallengeBeeSelect = true,
  ClientAcceptAmulet = true, ClientRejectAmulet = true }
BS.NEVER = NEVER
-- The game's own ClientCall, waited on no longer than `limit` s. Returns ok, ... (the server's answer).
function BS.call(name, limit, ...)
  if NEVER[name] then return false, "never" end
  local events = BS.mod("Events")
  if not (events and type(events.ClientCall) == "function") then return false, "no events" end
  local args = table.pack(...)
  local box = { done = false }
  BS.calls += 1
  task.spawn(function()
    local out = table.pack(pcall(events.ClientCall, name, table.unpack(args, 1, args.n)))
    box.out, box.done = out, true
  end)
  local started = os.clock()
  limit = limit or 10
  while not box.done do
    if not B.alive then return false, "unloaded" end
    if os.clock() - started > limit then
      BS.reasons[name .. ":timeout"] = (BS.reasons[name .. ":timeout"] or 0) + 1
      return false, "timeout"
    end
    task.wait()
  end
  B.identity()
  local out = box.out
  if not out[1] then
    BS.refused += 1
    BS.reasons[name .. ":error"] = (BS.reasons[name .. ":error"] or 0) + 1
    return false, tostring(out[2])
  end
  return true, table.unpack(out, 2, out.n)
end

-- ---------------------------------------------------------------- what the server holds
function BS.cache() return BS.mod("ClientStatCache") end
function BS.stats()
  local cache = BS.cache()
  if not cache then return nil end
  local stats = BS.ask(cache.Get, cache)
  return type(stats) == "table" and stats or nil
end
-- asks the server for the whole table again (the game does it after a purchase): not more than every 3 s
local refreshed = 0
function BS.refresh()
  if os.clock() - refreshed < 3 then return end
  refreshed = os.clock()
  local cache = BS.cache()
  if cache and type(cache.Update) == "function" then
    task.spawn(function() pcall(cache.Update, cache); B.identity() end)
  end
end
local function coreValue(name)
  local core = B.LP:FindFirstChild("CoreStats")
  local value = core and core:FindFirstChild(name)
  return value and tonumber(value.Value) or 0
end
function BS.pollen() return coreValue("Pollen") end
function BS.capacity() return math.max(coreValue("Capacity"), 1) end
function BS.honey() return coreValue("Honey") end
function BS.full() return BS.pollen() / BS.capacity() end

-- ---------------------------------------------------------------- the hive
function BS.hive()
  local ref = B.LP:FindFirstChild("Honeycomb")
  local hive = ref and ref.Value
  return hive and hive.Parent and hive or nil
end
-- the pad in front of a hive (HivePlatforms.Platform, whose Hive value is that hive)
function BS.pad(hive)
  hive = hive or BS.hive()
  local folder = workspace:FindFirstChild("HivePlatforms")
  if not (hive and folder) then return nil end
  for _, platform in ipairs(folder:GetChildren()) do
    local ref = platform:FindFirstChild("Hive")
    if ref and ref.Value == hive then return platform:FindFirstChild("Platform") end
  end
  return nil
end
-- the hives no one holds: { id, pad }
function BS.freeHives()
  local out = {}
  local folder = workspace:FindFirstChild("HivePlatforms")
  if not folder then return out end
  for _, platform in ipairs(folder:GetChildren()) do
    local owner, ref, pad = platform:FindFirstChild("PlayerRef"), platform:FindFirstChild("Hive"), platform:FindFirstChild("Platform")
    local hive = ref and ref.Value
    local id = hive and hive:FindFirstChild("HiveID")
    if owner and not owner.Value and id and pad then out[#out + 1] = { id = id.Value, pad = pad } end
  end
  return out
end
-- Claims the free hive nearest the body (the server takes the claim from anywhere: measured). True once a hive is ours.
function BS.claim()
  if BS.hive() then return true end
  local root = B.root()
  local best, bestDistance = nil, math.huge
  for _, free in ipairs(BS.freeHives()) do
    local distance = root and (free.pad.Position - root.Position).Magnitude or free.id
    if distance < bestDistance then best, bestDistance = free, distance end
  end
  if not best then return false, "no free hive" end
  BS.call("ClaimHive", 6, best.id)
  local started = os.clock()
  while not BS.hive() and os.clock() - started < 4 do task.wait(0.1) end
  if BS.hive() then BS.note("Claimed hive " .. tostring(best.id) .. ".") end
  return BS.hive() ~= nil
end
-- The cells of our hive: { x, y, kind ("Empty", "BasicBee" ...), locked, cell }
function BS.cells()
  local out = {}
  local hive = BS.hive()
  local cells = hive and hive:FindFirstChild("Cells")
  if not cells then return out end
  for _, cell in ipairs(cells:GetChildren()) do
    local x, y, kind, locked = cell:FindFirstChild("CellX"), cell:FindFirstChild("CellY"), cell:FindFirstChild("CellType"), cell:FindFirstChild("CellLocked")
    if x and y then
      out[#out + 1] = { x = x.Value, y = y.Value, kind = kind and kind.Value or "Empty", locked = locked and locked.Value == true, cell = cell }
    end
  end
  table.sort(out, function(a, b) if a.y ~= b.y then return a.y < b.y end return a.x < b.x end)
  return out
end
-- the bees in the hive, from the server's table: { x, y, kind, level, file }
function BS.bees()
  local out = {}
  local stats = BS.stats()
  local comb = stats and stats.Honeycomb
  if type(comb) ~= "table" then return out end
  for xKey, column in pairs(comb) do
    if type(column) == "table" then
      for yKey, file in pairs(column) do
        if type(file) == "table" and file.Type then
          local x = tonumber(tostring(xKey):match("%d+"))
          local y = tonumber(tostring(yKey):match("%d+"))
          out[#out + 1] = { x = x, y = y, kind = file.Type, level = tonumber(file.Lvl) or 1, file = file }
        end
      end
    end
  end
  return out
end
function BS.beeCount() return #BS.bees() end

-- ---------------------------------------------------------------- fields
-- The fields a player farms, with the bees each one's gate asks for (the 5/10/15/25/35 bee gates of the map).
BS.FIELDS = {
  { name = "Sunflower Field", need = 0 }, { name = "Dandelion Field", need = 0 }, { name = "Mushroom Field", need = 0 },
  { name = "Blue Flower Field", need = 0 }, { name = "Clover Field", need = 0 },
  { name = "Spider Field", need = 5 }, { name = "Strawberry Field", need = 5 }, { name = "Bamboo Field", need = 5 },
  { name = "Pineapple Patch", need = 10 }, { name = "Stump Field", need = 10 },
  { name = "Cactus Field", need = 15 }, { name = "Pumpkin Patch", need = 15 }, { name = "Pine Tree Forest", need = 15 }, { name = "Rose Field", need = 15 },
  { name = "Mountain Top Field", need = 25 },
  { name = "Coconut Field", need = 35 }, { name = "Pepper Patch", need = 35 },
}
BS.NEED = {}
for _, field in ipairs(BS.FIELDS) do BS.NEED[field.name] = field.need end
function BS.zone(name)
  local zones = workspace:FindFirstChild("FlowerZones")
  local zone = zones and zones:FindFirstChild(name)
  return zone and zone:IsA("BasePart") and zone or nil
end
-- { white, blue, red } shares of a field's flowers (the zone's own values)
function BS.colors(name)
  local zone = BS.zone(name)
  local function share(key)
    local value = zone and zone:FindFirstChild(key)
    return value and tonumber(value.Value) or 0
  end
  return { White = share("White"), Blue = share("Blue"), Red = share("Red") }
end
function BS.unlocked(name)
  return BS.zone(name) ~= nil and BS.beeCount() >= (BS.NEED[name] or 0)
end
-- a point's place in a field: local x, z and the half sizes (the zone part may be turned)
function BS.inField(position, name, margin)
  local zone = BS.zone(name)
  if not (zone and position) then return false end
  local relative = zone.CFrame:PointToObjectSpace(position)
  margin = margin or 0
  -- (height kept tight: Mushroom Field's caps and the trees stand 25+ studs over a field, and a body up there collects nothing)
  return math.abs(relative.X) <= zone.Size.X / 2 + margin and math.abs(relative.Z) <= zone.Size.Z / 2 + margin
    and relative.Y > -6 and relative.Y < 12
end
-- the top of a field's flowers (every field is flat: its zone part lies on it)
function BS.fieldY(name)
  local zone = BS.zone(name)
  return zone and zone.Position.Y + zone.Size.Y / 2 or nil
end
-- where the ground is under a point (the map, not bodies, bees or tokens): Y, or nil
local rayParams = RaycastParams.new()
rayParams.FilterType = Enum.RaycastFilterType.Exclude
function BS.ground(position)
  local ignore = {}
  local character = B.LP.Character
  if character then ignore[#ignore + 1] = character end
  for _, name in ipairs({ "Collectibles", "Bees", "Monsters", "Particles", "Camera", "Balloons", "Planters" }) do
    local folder = workspace:FindFirstChild(name)
    if folder then ignore[#ignore + 1] = folder end
  end
  local players = S.Players:GetPlayers()
  for _, player in ipairs(players) do
    if player.Character and player ~= B.LP then ignore[#ignore + 1] = player.Character end
  end
  rayParams.FilterDescendantsInstances = ignore
  -- (from just over the point, not from high up: a ray from above lands on roofs, caps and treetops)
  local hit = workspace:Raycast(position + Vector3.new(0, 4, 0), Vector3.new(0, -40, 0), rayParams)
  return hit and hit.Position.Y or nil
end
-- a standing spot in a field: its middle, or `u`, `v` in -1..1 across it (kept `inset` studs inside the edge)
function BS.spot(name, u, v, inset)
  local zone = BS.zone(name)
  if not zone then return nil end
  inset = inset or 6
  local halfX = math.max(zone.Size.X / 2 - inset, 1)
  local halfZ = math.max(zone.Size.Z / 2 - inset, 1)
  local point = zone.CFrame:PointToWorldSpace(Vector3.new((u or 0) * halfX, 0, (v or 0) * halfZ))
  return Vector3.new(point.X, BS.fieldY(name) + 3, point.Z)
end

-- ---------------------------------------------------------------- the body
-- One body, one part with it at a time: the farm does not have it walked to a dispenser under it.
BS.owner, BS.queue = nil, {}
function BS.take(who)
  if who == "farm" and BS.owner ~= "farm" then
    for other in pairs(BS.queue) do
      if other ~= who then return false end
    end
  end
  if BS.owner == nil or BS.owner == who then
    BS.owner = who
    return true
  end
  return false
end
function BS.release(who)
  if BS.owner == who then BS.owner = nil end
end
-- Glides the body to `target` at `speed` studs a second, a frame at a time (no tween left behind to fight),
-- and stands it there. False when the body went, the hub unloaded, `stop()` said so, or it took far too long.
BS.speed = 80
-- Noclip for the length of a glide: every part of the body stops colliding before each physics step (the engine
-- turns some back on), and gets back what it had once the glide ends. Without it a wall pushes the body back
-- every frame and a long trip crawls (seen live on the map-token runs).
local function noclip()
  local character = B.LP.Character
  if not character then return function() end end
  local saved = {}
  local function off()
    for _, part in ipairs(character:GetDescendants()) do
      if part:IsA("BasePart") then
        if saved[part] == nil then saved[part] = part.CanCollide end
        if part.CanCollide then part.CanCollide = false end
      end
    end
  end
  off()
  local connection = S.RunService.Stepped:Connect(off)
  return function()
    connection:Disconnect()
    for part, was in pairs(saved) do
      if part.Parent then pcall(function() part.CanCollide = was end) end
    end
  end
end
function BS.go(target, speed, stop)
  local root = B.root()
  if not (root and target) then return false end
  speed = math.max(tonumber(speed) or BS.speed, 4)
  local started = os.clock()
  local limit = (target - root.Position).Magnitude / speed * 2.5 + 2
  BS.moving = true
  local arrived = false
  local restore = (BS.O == nil or BS.O.noclip ~= false) and noclip() or nil
  while B.alive do
    root = B.root()
    if not root then break end
    local delta = target - root.Position
    local distance = delta.Magnitude
    if distance < 0.5 then arrived = true break end
    if (stop and stop()) or os.clock() - started > limit then break end
    local dt = S.RunService.Heartbeat:Wait()
    root = B.root()
    if not root then break end
    delta = target - root.Position
    distance = delta.Magnitude
    if distance < 0.5 then arrived = true break end
    local position = root.Position + delta.Unit * math.min(distance, speed * math.min(dt, 0.1))
    local flat = Vector3.new(delta.X, 0, delta.Z)
    if flat.Magnitude > 0.05 then
      root.CFrame = CFrame.lookAt(position, position + flat)
    else
      root.CFrame = root.CFrame.Rotation + position
    end
    root.AssemblyLinearVelocity = Vector3.zero
    root.AssemblyAngularVelocity = Vector3.zero
  end
  root = B.root()
  if arrived and root then
    root.CFrame = root.CFrame.Rotation + target
    root.AssemblyLinearVelocity = Vector3.zero
  end
  if restore then restore() end
  BS.moving = false
  return arrived
end
-- Takes the body (waits for it up to `limit` s), runs fn, gives it back.
function BS.errand(who, fn, limit)
  local had = BS.owner == who
  if not had then
    local started = os.clock()
    BS.queue[who] = started
    while BS.paused() or not BS.take(who) do
      if not B.alive or os.clock() - started > (limit or 30) then
        BS.queue[who] = nil
        return false, "busy"
      end
      task.wait(0.05)
    end
    BS.queue[who] = nil
  end
  local ok, a, b = pcall(fn)
  if not had then BS.release(who) end
  B.identity()
  if not ok then
    BS.note("Error in " .. who .. ": " .. tostring(a))
    return false, tostring(a)
  end
  return a, b
end
-- The player's own hand: a move key or a click in the world. Everything that moves the body steps aside
-- for a few seconds after the last one (when "Pause while you play" is on).
local MOVES = { [Enum.KeyCode.W] = true, [Enum.KeyCode.A] = true, [Enum.KeyCode.S] = true, [Enum.KeyCode.D] = true,
  [Enum.KeyCode.Up] = true, [Enum.KeyCode.Down] = true, [Enum.KeyCode.Left] = true, [Enum.KeyCode.Right] = true, [Enum.KeyCode.Space] = true }
BS.played = -math.huge
function BS.paused()
  local O = BS.O
  return O ~= nil and O.yield == true and os.clock() - BS.played < (O.yieldFor or 6)
end
-- A part's loop: `body` is one turn (it waits itself). A turn that throws is noted and the loop goes on a second
-- later: one bad read of the game must not stop the farm for good.
function BS.loop(name, body)
  task.spawn(function()
    local faults = 0
    while B.alive do
      local ok, err = pcall(body)
      B.identity()
      if not ok then
        faults += 1
        BS.reasons["loop:" .. name] = faults
        BS.note(string.format("%s hiccup: %s", name, tostring(err):sub(1, 120)))
        if faults <= 3 then warn("[BASED bss." .. name .. "] " .. tostring(err)) end
        task.wait(1)
      end
    end
  end)
end
function BS.ready()
  if not BS.stats() then return false, "data" end
  local humanoid = B.humanoid()
  if not humanoid or humanoid.Health <= 0 or not B.root() then return false, "body" end
  return true
end

-- ---------------------------------------------------------------- tokens
-- The name of each token picture, from the game's own icons.
local icons
function BS.icons()
  if icons then return icons end
  local map = {}
  local function add(texture, name)
    local id = tostring(texture or ""):match("(%d+)")
    if id and name and not map[id] then map[id] = name end
  end
  local eggTypes = S.ReplicatedStorage:FindFirstChild("EggTypes")
  if eggTypes then
    for _, decal in ipairs(eggTypes:GetChildren()) do
      if decal:IsA("Decal") or decal:IsA("Texture") then add(decal.Texture, (decal.Name:gsub("IconSquare$", ""):gsub("Icon$", ""))) end
    end
  end
  local function scan(tbl, label, depth, seen)
    if type(tbl) ~= "table" or depth > 6 or seen[tbl] then return end
    seen[tbl] = true
    local icon = rawget(tbl, "Icon")
    if type(icon) == "string" then add(icon, label) end
    for key, value in pairs(tbl) do
      if type(value) == "table" then scan(value, type(key) == "string" and key or label, depth + 1, seen) end
    end
  end
  for _, path in ipairs({ "Buffs", "Buffs.Init.BuffDefs", "BeeAbilityDefs", "Items", "Collectibles" }) do
    local module = BS.mod(path)
    if module then pcall(scan, module, path, 0, {}) end
  end
  local count = 0
  for _ in pairs(map) do count += 1 end
  if count > 20 then icons = map end
  return map
end
function BS.tokenName(part)
  local decal = part:FindFirstChild("FrontDecal")
  local id = decal and tostring(decal.Texture):match("(%d+)")
  return id and BS.icons()[id] or "Token", id
end
-- How much a token is worth chasing, 0..100: what the player picked first, then the rare ones, then the rest.
BS.RARE = { Ticket = 90, StarJelly = 95, RoyalJelly = 80, Gold = 90, Diamond = 95, Silver = 85, Mythic = 100, StarTreat = 95,
  Glitter = 70, Glue = 60, Oil = 60, Enzymes = 60, CloudVial = 70, MagicBean = 70, MoonCharm = 60, SmoothDice = 60, LoadedDice = 70,
  ["Token Link"] = 88, ["Inspire"] = 50, Treat = 55, Blueberry = 55, Strawberry = 55, Pineapple = 55, SunflowerSeed = 55,
  Gumdrops = 55, Coconut = 55, Stinger = 70, AntPass = 75, RoboPass = 75, BearEgg = 70 }
function BS.tokenValue(name)
  local O = BS.O
  local picked = O and O.tokenFirst
  if picked and table.find(picked, name) then return 100 end
  return BS.RARE[name] or 20
end
-- the tokens in a field (and `margin` studs past its edge): { part, position, name, value }
function BS.tokensIn(name, margin)
  local out = {}
  local folder = workspace:FindFirstChild("Collectibles")
  if not folder then return out end
  for _, part in ipairs(folder:GetChildren()) do
    if part:IsA("BasePart") and part.Transparency < 0.9 and BS.inField(part.Position, name, margin or 4) then
      local kind = BS.tokenName(part)
      out[#out + 1] = { part = part, position = part.Position, name = kind, value = BS.tokenValue(kind) }
    end
  end
  return out
end

-- ---------------------------------------------------------------- monsters
-- the live monsters near a point: { model, name, position, distance, health }
function BS.monsters(around, radius)
  local out = {}
  local folder = workspace:FindFirstChild("Monsters")
  if not folder then return out end
  for _, model in ipairs(folder:GetChildren()) do
    local ok, pivot = pcall(function() return model:GetPivot().Position end)
    if ok and pivot then
      local distance = around and (pivot - around).Magnitude or 0
      if not radius or distance <= radius then
        local humanoid = model:FindFirstChildOfClass("Humanoid")
        out[#out + 1] = { model = model, name = model.Name, position = pivot, distance = distance, health = humanoid and humanoid.Health or 0 }
      end
    end
  end
  table.sort(out, function(a, b) return a.distance < b.distance end)
  return out
end

-- ---------------------------------------------------------------- numbers, the log, the line on the page
function BS.short(n)
  n = tonumber(n) or 0
  local units = { { 1e15, "Qa" }, { 1e12, "T" }, { 1e9, "B" }, { 1e6, "M" }, { 1e3, "K" } }
  for _, unit in ipairs(units) do
    if math.abs(n) >= unit[1] then return string.format("%.2f%s", n / unit[1], unit[2]):gsub("%.?0+([A-Za-z]+)$", "%1") end
  end
  return util.comma(math.floor(n))
end
function BS.note(text)
  local log = BS.log
  log[#log + 1] = { at = os.clock(), text = text }
  if #log > 40 then table.remove(log, 1) end
  BS.status = text
end
function BS.toast(title, text, icon, tone)
  if Config.get("bss.toasts") == false then return end
  Window.toast({ title = title, text = text, icon = icon or "sprout", tone = tone or "accent", time = 4 })
end

local function statusLine()
  if not BS.stats() then return "Waiting for the game's data." end
  local parts = {
    "Honey " .. BS.short(BS.honey()),
    string.format("Pollen %s/%s", BS.short(BS.pollen()), BS.short(BS.capacity())),
    string.format("%d bees", BS.beeCount()),
  }
  local zone = B.LP:GetAttribute("CurrentZone")
  if zone then parts[#parts + 1] = tostring(zone) end
  if not BS.hive() then parts[#parts + 1] = "no hive yet" end
  return table.concat(parts, "  ·  ")
end
BS.statusLine = statusLine

-- ---------------------------------------------------------------- the tabs
-- A part adds its cards to a tab by naming it: { id, start = fn(hub), farm = fn(page), hive = fn(page), quests = fn(page), extra = fn(page) }
local function extend(kind, page)
  for _, part in ipairs(BS.parts) do
    if part[kind] then B.try("bss." .. part.id .. "." .. kind, part[kind], page) end
  end
end
local function has(kind)
  for _, part in ipairs(BS.parts) do
    if part[kind] then return true end
  end
  return false
end

-- The whole game in one press: farm, convert, claim and fill the hive, buy the next tool and bag,
-- quests, dispensers, map tokens. Robux and trading are never touched.
local FULL = { "farm", "tokens", "claim", "hatch", "buyEggs", "ticketEggs", "buyGear", "equipBest", "quests", "followQuests", "toys",
  "instant", "mapTokens", "feed" }
BS.FULL = FULL
function BS.preset(on)
  for _, id in ipairs(FULL) do Config.set("bss." .. id, on == true) end
end

local function farmPage(hub)
  hub:page({ id = "farm", title = "Farm", icon = "sprout", build = function(page)
    local you = page:section({ title = "You", icon = "user", full = true })
    local line = you:note({ icon = "activity", text = statusLine() })
    local doing = you:note({ icon = "info", text = "" })
    you:button({ id = "bss.full", label = "Full auto", desc = "Farms, converts, hatches, buys, quests.", text = "Switch on", run = function()
      BS.preset(true)
      Window.toast({ title = "Full auto is on", text = "Robux and trades are never touched.", icon = "repeat", tone = "ok", time = 4 })
    end })
    you:button({ id = "bss.stop", label = "Stop", desc = "Everything off.", text = "Switch off", run = function()
      BS.preset(false)
      Window.toast({ title = "Everything is off", icon = "circle-pause", time = 3 })
    end })
    Motion.every(function()
      if not (line.frame.Parent and Window.anyOpen()) then return end
      line.set(statusLine())
      doing.set(BS.status or "Idle.")
    end, 1, "bss.status")
    extend("farm", page)
    local session = page:section({ title = "Session", icon = "plug" })
    session:toggle({ id = "bss.toasts", label = "Notes on screen", desc = "A note for rare tokens and new bees.", default = true, bindable = false })
    session:toggle({ id = "bss.closePopups", label = "Close pop-ups", desc = "Closes the game's new-bee pop-up by itself.", default = true })
    session:slider({ id = "bss.popupDelay", label = "Close after", min = 0, max = 5, step = 0.5, default = 1, suffix = " s" })
    session:toggle({ id = "bss.yield", label = "Pause while you play", desc = "Steps aside while you move or click.", default = false })
    session:slider({ id = "bss.yieldFor", label = "Pause for", desc = "After your last key or click.", min = 2, max = 60, step = 1, default = 6, suffix = " s" })
  end })
end

-- The game's pop-up for a new bee ("You hatched a ... Basic Bee!") closed the game's own way (BeePopUp.Close),
-- a moment after it opens, so a farm that hatches all night does not leave a stack of them on the screen.
local function watchPopups()
  local gui = B.LP:FindFirstChild("PlayerGui")
  local screen = gui and gui:WaitForChild("ScreenGui", 30)
  local frame = screen and screen:WaitForChild("BeePopUp", 30)
  if not frame then return end
  local function check()
    if not (frame.Visible and BS.O and BS.O.closePopups) then return end
    task.delay(math.max(BS.O.popupDelay or 1, 0), function()
      if not (B.alive and frame.Visible and BS.O.closePopups) then return end
      local popup = BS.mod("Gui.BeePopUp")
      if popup and type(popup.Close) == "function" then
        BS.ask(popup.Close)
      else
        frame.Visible = false
      end
      BS.popupsClosed = (BS.popupsClosed or 0) + 1
    end)
  end
  B.connect(frame:GetPropertyChangedSignal("Visible"), check, "bss.popup")
  check()
end

local function start(hub)
  Config.define("bss.toasts", true)
  Config.define("bss.yield", false)
  Config.define("bss.yieldFor", 6)
  Config.define("bss.noclip", true)
  Config.define("bss.closePopups", true)
  Config.define("bss.popupDelay", 1)
  BS.O = Config.mirror({ yield = "bss.yield", yieldFor = "bss.yieldFor", tokenFirst = "bss.tokenFirst", noclip = "bss.noclip",
    closePopups = "bss.closePopups", popupDelay = "bss.popupDelay" })
  task.spawn(B.safe("bss.popups", watchPopups))
  B.connect(S.UserInputService.InputBegan, function(input, processed)
    if processed then return end
    local kind = input.UserInputType
    if (kind == Enum.UserInputType.Keyboard and MOVES[input.KeyCode]) or kind == Enum.UserInputType.MouseButton1 or kind == Enum.UserInputType.Touch then
      BS.played = os.clock()
    end
  end, "bss.played")
end

B.game({
  id = "beeswarm",
  name = "Bee Swarm Simulator",
  short = "Bee Swarm",
  tagline = "Collect. Convert. Hatch. Again.",
  universes = { BS.UNIVERSE },
  places = { BS.PLACE },
  icon = "sprout",
  tabs = function(hub)
    start(hub)
    for _, part in ipairs(BS.parts) do
      if part.start then B.try("bss." .. part.id, part.start, hub) end
    end
    -- (every part is here now: until this, none of them acts)
    BS.started = true
    farmPage(hub)
    if has("hive") then
      hub:page({ id = "hive", title = "Hive", icon = "box", build = function(page) extend("hive", page) end })
    end
    if has("quests") then
      hub:page({ id = "quests", title = "Quests", icon = "list", build = function(page) extend("quests", page) end })
    end
    if has("extra") then
      hub:page({ id = "extra", title = "Extras", icon = "gem", build = function(page) extend("extra", page) end })
    end
  end,
})
end
do -- beeswarm_extra.lua
-- ============================================================================
--  Bee Swarm Simulator   the free things: dispensers, boosters, converters, map tokens
--
--   * Toys (workspace.Toys): a model with a Platform, a Cooldown in seconds, maybe Requirements (a
--     StatReqs list) and a ServerEffect. The game's button checks the requirements and the cooldown
--     (stats.ToyTimes[name] against OsTime), then sends ToyEvent(name). The game shows the button only
--     within 12 studs of the Platform: the hub stands there too. Read from the code; the test account
--     met none of the requirements yet, so a use is not measured.
--   * Instant converters are toys too: used in place of the walk to the hive when one is ready.
--   * Map tokens: tickets, jellies, treats ... lying around the map, outside every field. Each client
--     is sent only what it may take, so they are ours: the hub walks over them now and then.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util
local BS = B.BeeSwarm

local extra = { used = 0, tokens = 0, wait = {}, uses = {} }
BS.extra = extra
local O

local TOYS = { "Wealth Clock", "Honey Dispenser", "Treat Dispenser", "Blueberry Dispenser", "Strawberry Dispenser", "Coconut Dispenser",
  "Glue Dispenser", "Free Royal Jelly Dispenser", "Free Ant Pass Dispenser", "Free Robo Pass Dispenser", "Blue Field Booster",
  "Red Field Booster", "Field Booster", "Honeystorm", "Sprout Summoner", "Mythic Meteor Shower" }
local CONVERTERS = { "Instant Converter", "Instant Converter B", "Instant Converter C" }

local function due(key, seconds)
  local now = os.clock()
  if now < (extra.wait[key] or 0) then return false end
  extra.wait[key] = now + seconds
  return true
end

-- the toy models by name (the Main place's, as the game's own search keeps them)
local function toys()
  local out = {}
  local root = workspace:FindFirstChild("Toys")
  if not root then return out end
  local function walk(node)
    for _, child in ipairs(node:GetChildren()) do
      if child:IsA("Model") then
        local place = child:FindFirstChild("PlaceType")
        if (place and place.Value or "Main") == "Main" then out[child.Name] = child end
      elseif child:IsA("Folder") then
        walk(child)
      end
    end
  end
  walk(root)
  return out
end
-- OsTime is a function module (require returns a function): asked through require, not BS.mod
local osTime
local function now()
  if not osTime then
    local module = S.ReplicatedStorage:FindFirstChild("OsTime")
    local ok, fn = pcall(require, module)
    B.identity()
    osTime = ok and type(fn) == "function" and fn or false
  end
  if osTime then
    local ok, value = pcall(osTime)
    if ok and type(value) == "number" then return value end
  end
  return os.time()
end
-- a toy can be used now: its requirements met and off its cooldown (the game's own two checks)
local function ready(toy)
  local stats = BS.stats()
  if not (stats and toy and toy:FindFirstChild("ServerEffect") and toy:FindFirstChild("Platform")) then return false end
  local busy = toy:FindFirstChild("Busy")
  if busy and busy.Value then return false end
  local requirements = toy:FindFirstChild("Requirements")
  if requirements then
    local reqs = BS.mod("StatReqs")
    local ok, list = pcall(require, requirements)
    B.identity()
    if not (ok and reqs and BS.ask(reqs.Check, stats, list)) then return false end
  end
  local cooldown = toy:FindFirstChild("Cooldown")
  if cooldown then
    local times = stats.ToyTimes or {}
    if now() - (tonumber(times[toy.Name]) or 0) < cooldown.Value then return false end
  end
  return true
end
extra.ready = ready

-- Stands at the toy and uses it, the way its button does. True when the server took it (its time moved on).
local function use(toy)
  local platform = toy:FindFirstChild("Platform")
  if not platform then return false end
  local done = BS.errand("toy", function()
    if not BS.go(platform.Position + Vector3.new(0, 3.5, 0), BS.speed) then return false end
    task.wait(0.35)
    local ok = BS.call("ToyEvent", 8, toy.Name)
    task.wait(0.6)
    return ok
  end, 40)
  if done then
    local stats = BS.stats()
    if stats then
      stats.ToyTimes = stats.ToyTimes or {}
      stats.ToyTimes[toy.Name] = math.floor(now())
    end
    extra.used += 1
    extra.uses[toy.Name] = (extra.uses[toy.Name] or 0) + 1
    BS.note("Used the " .. toy.Name .. ".")
    BS.refresh()
    return true
  end
  return false
end

-- An instant converter in place of the walk to the hive: true when the pollen went.
function BS.instantConvert()
  if not (O and O.instant) then return false end
  local all = toys()
  for _, name in ipairs(CONVERTERS) do
    local toy = all[name]
    if toy and ready(toy) then
      local before = BS.pollen()
      if use(toy) then
        local started = os.clock()
        while BS.pollen() >= before and os.clock() - started < 3 do task.wait(0.1) end
        if BS.pollen() < before then return true end
      end
    end
  end
  return false
end

-- ---------------------------------------------------------------- map tokens
-- Most of them are TREASURES (TreasureManager: Permanent, IsTreasure): one per account for good, its id kept in
-- stats.Treasures, and its picture STAYS on the map after it is taken. Measured: a sweep that waited for the pictures
-- to go "failed" 13 of 13, while the account went from 0 to 13 treasures and 0 to 18 tickets. So a take is read
-- from stats.Treasures, and every spot looked at is kept on disk for this account, so it is not walked to again.
local seenFile = "BasedHub/cache/beeswarm_seen_" .. tostring(B.LP.UserId) .. ".json"
local seen = nil
local function spotKey(position)
  return string.format("%d,%d,%d", math.floor(position.X + 0.5), math.floor(position.Y + 0.5), math.floor(position.Z + 0.5))
end
local function seenSpots()
  if seen then return seen end
  seen = {}
  local ok, text = pcall(function() return isfile(seenFile) and readfile(seenFile) or nil end)
  if ok and type(text) == "string" then
    local decoded, data = pcall(function() return S.HttpService:JSONDecode(text) end)
    if decoded and type(data) == "table" then
      for _, key in ipairs(data) do seen[key] = true end
    end
  end
  return seen
end
local function saveSeen()
  local list = {}
  for key in pairs(seen or {}) do list[#list + 1] = key end
  pcall(function()
    if not isfolder("BasedHub/cache") then makefolder("BasedHub/cache") end
    writefile(seenFile, S.HttpService:JSONEncode(list))
  end)
end
local function treasures()
  local stats = BS.stats()
  return stats and type(stats.Treasures) == "table" and #stats.Treasures or 0
end
extra.treasures = treasures
-- the tokens outside every field, of the kinds worth a trip, not looked at yet: { part, position, name }
local function mapTokens()
  local out = {}
  local folder = workspace:FindFirstChild("Collectibles")
  local root = B.root()
  if not (folder and root) then return out end
  for _, part in ipairs(folder:GetChildren()) do
    if part:IsA("BasePart") and part.Transparency < 0.9 then
      local position = part.Position
      local inField = false
      for _, field in ipairs(BS.FIELDS) do
        if BS.inField(position, field.name, 6) then inField = true break end
      end
      -- (the main map only: not the far places the game keeps far away, like the hive hub or the gummy lair)
      if not inField and not seenSpots()[spotKey(position)] and math.abs(position.X) < 800 and math.abs(position.Z) < 900
        and position.Y > -50 and position.Y < 400 then
        local name = BS.tokenName(part)
        if table.find(O.mapKinds or {}, name) or (#(O.mapKinds or {}) == 0 and BS.RARE[name]) then
          out[#out + 1] = { part = part, position = position, name = name, distance = (position - root.Position).Magnitude }
        end
      end
    end
  end
  table.sort(out, function(a, b) return a.distance < b.distance end)
  return out
end
extra.mapTokens = mapTokens
local function sweep()
  local list = mapTokens()
  if #list == 0 then return 0 end
  local took = 0
  BS.errand("map", function()
    BS.note(string.format("Map tokens: %d to take.", #list))
    local began = os.clock()
    -- (each next one: worth the most for the way to it, from where the body is now; a run is kept to a minute so
    -- the farm is not left waiting, and a token still there after the body stood on it is left for good)
    while #list > 0 and B.alive and O.mapTokens and os.clock() - began < 45 do
      local root = B.root()
      if not root then break end
      local function score(t) return BS.tokenValue(t.name) * 2 - (t.position - root.Position).Magnitude / 8 end
      table.sort(list, function(a, b) return score(a) > score(b) end)
      local token = table.remove(list, 1)
      if token.part.Parent then
        local before = treasures()
        -- (150 st/s at least: measured, a Gold egg treasure was taken 0.2 s after a 150 st/s glide)
        BS.go(token.position + Vector3.new(0, 0.5, 0), math.max(BS.speed, 150), function() return not token.part.Parent end)
        local started = os.clock()
        -- (taken: the picture went (a plain token), or the account has one treasure more)
        while token.part.Parent and treasures() <= before and os.clock() - started < 1 do task.wait(0.05) end
        if not token.part.Parent or treasures() > before then
          took += 1
          extra.tokens += 1
        end
        seenSpots()[spotKey(token.position)] = true
      end
    end
    saveSeen()
  end, 60)
  if took > 0 then
    BS.note(string.format("Took %d map tokens.", took))
    BS.toast("Map tokens", string.format("%d taken", took), "sparkles", "ok")
  end
  return took
end

local function start(hub)
  for id, default in pairs({ ["bss.toys"] = false, ["bss.toyList"] = TOYS, ["bss.instant"] = false, ["bss.mapTokens"] = false,
    ["bss.mapKinds"] = {}, ["bss.mapEvery"] = 5 }) do
    Config.define(id, default)
  end
  O = Config.mirror({ toys = "bss.toys", toyList = "bss.toyList", instant = "bss.instant", mapTokens = "bss.mapTokens",
    mapKinds = "bss.mapKinds", mapEvery = "bss.mapEvery" })
  extra.options = O
  BS.loop("extra", function()
    do
      if BS.started and BS.ready() and BS.hive() and not BS.paused() then
        if O.toys and due("toys", 10) then
          local all = toys()
          for _, name in ipairs(O.toyList or TOYS) do
            local toy = all[name]
            if toy and ready(toy) and due("toy." .. name, 30) then
              B.try("bss.toy", use, toy)
            end
          end
        end
        if O.mapTokens and due("map", math.max((O.mapEvery or 5) * 60, 30)) then
          B.try("bss.map", sweep)
        end
      end
      task.wait(1)
    end
  end)
end

local MAP_OPTIONS = { "Ticket", "StarJelly", "RoyalJelly", "Treat", "Blueberry", "Strawberry", "Pineapple", "SunflowerSeed", "Gumdrops",
  "Glitter", "Glue", "Enzymes", "Oil", "CloudVial", "MagicBean", "Coconut", "Stinger", "AntPass", "RoboPass", "SmoothDice", "LoadedDice" }

local function extraCards(page)
  local box = page:section({ title = "Dispensers", icon = "star", desc = "Free things, as soon as they are ready." })
  box:toggle({ id = "bss.toys", label = "Use dispensers", desc = "Clocks, dispensers, boosters you have unlocked.", default = false })
  box:multi({ id = "bss.toyList", label = "Which", options = TOYS, default = TOYS })
  box:toggle({ id = "bss.instant", label = "Instant converters", desc = "In place of the walk to the hive, when ready.", default = false })
  local line = box:note({ icon = "info", text = "" })

  local map = page:section({ title = "Map tokens", icon = "map", desc = "Tickets and jellies lying around the map." })
  map:toggle({ id = "bss.mapTokens", label = "Collect map tokens", desc = "Walks over them now and then.", default = false })
  map:multi({ id = "bss.mapKinds", label = "Kinds", options = MAP_OPTIONS, default = {}, empty = "The rare ones" })
  map:slider({ id = "bss.mapEvery", label = "Look every", min = 1, max = 60, step = 1, default = 5, suffix = " min" })
  local mapLine = map:note({ icon = "info", text = "" })

  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    local all = toys()
    local readyNow, unlocked = {}, 0
    for _, name in ipairs(TOYS) do
      local toy = all[name]
      if toy then
        if ready(toy) then readyNow[#readyNow + 1] = name end
      end
    end
    for _, name in ipairs(CONVERTERS) do
      local toy = all[name]
      if toy and ready(toy) then readyNow[#readyNow + 1] = name end
    end
    local _ = unlocked
    line.set(string.format("%d used  ·  ready now: %s", extra.used, #readyNow > 0 and table.concat(readyNow, ", ") or "none"))
    local list = mapTokens()
    local kinds = {}
    for _, token in ipairs(list) do kinds[token.name] = (kinds[token.name] or 0) + 1 end
    local text = {}
    for name, n in pairs(kinds) do text[#text + 1] = string.format("%s %d", name, n) end
    table.sort(text)
    mapLine.set(string.format("%d taken  ·  on the map now: %s", extra.tokens, #text > 0 and table.concat(text, ", ") or "none"))
  end, 3, "bss.extra.line")
end

BS.parts[#BS.parts + 1] = { id = "extra", start = start, extra = extraCards }
end
do -- beeswarm_farm.lua
-- ============================================================================
--  Bee Swarm Simulator   the farm: a field, the swing, the tokens, the hive and back
--
--   * The swing is the game's own (Collectors.LocalCollect.Run), at the collector's own cooldown:
--     nothing is sent faster than the game sends it when the player holds the mouse down.
--   * Honey is made at the pad only (measured): the body goes there, ToggleHoneyMaking is sent once
--     while the hive is Idle (a second one would STOP it), and the farm waits for the pollen to run out.
--   * "Best" learns: the pollen a second each picked field really gives (the bees' share included),
--     each one tried for 45 s first, then the best one, tried again now and then.
--   * Tokens: the most worth chasing first (what the player picked, then the rare ones), nearest
--     among equals, within reach of the field, never past its edge. The server takes one within 5 studs.
--   * Sprinklers (the game's "Sprinkler Builder", PlayerActivesCommand): as many as the equipped
--     set has, spread over the field, once a field. Read from the code, not run live (no sprinkler on the test account).
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util
local BS = B.BeeSwarm

local farm = { swings = 0, trips = 0, converts = 0, tokens = 0, field = nil, rates = {}, tried = {}, state = "off", placed = nil }
BS.farm = farm
local O

-- ---------------------------------------------------------------- the swing
local function swing()
  local collect = BS.mod("Collectors.LocalCollect")
  if not collect then return false end
  local wait = BS.ask(collect.GetCooldownNow)
  if wait and wait > 0 then return false end
  BS.ask(collect.Run)
  farm.swings += 1
  return true
end
farm.swing = swing

-- ---------------------------------------------------------------- which field
local function open()
  local out = {}
  for _, field in ipairs(BS.FIELDS) do
    if BS.unlocked(field.name) then out[#out + 1] = field.name end
  end
  return out
end
local function candidates()
  local picked = O.fields or {}
  local out = {}
  for _, field in ipairs(BS.FIELDS) do
    if table.find(picked, field.name) and BS.unlocked(field.name) then out[#out + 1] = field.name end
  end
  -- (nothing picked, or none of it open yet: every open field)
  if #out == 0 then out = open() end
  return out
end
-- pollen a second a field gave, and for how long it was measured
local function rate(name)
  local r = farm.rates[name]
  if not r or r.seconds <= 0 then return nil, 0 end
  return r.pollen / r.seconds, r.seconds
end
farm.rate = rate
local function choose()
  if O.followQuests and BS.questField then
    local wanted, why = BS.questField()
    if wanted and BS.unlocked(wanted) then return wanted, why or "quest" end
  end
  local list = candidates()
  if #list == 0 then return nil end
  local mode = O.pick or "best"
  if mode == "first" then return list[1], "first" end
  if mode == "rotate" then
    local period = math.max((O.rotateMins or 10) * 60, 30)
    local index = math.floor(os.clock() / period) % #list + 1
    return list[index], "rotate"
  end
  -- best: each field measured 45 s first (in the player's order), then the highest rate; a field not measured for
  -- 20 min is tried again (bees, gear and boosts change what a field is worth)
  for _, name in ipairs(list) do
    local _, seconds = rate(name)
    local last = farm.tried[name]
    if seconds < 45 or (last and os.clock() - last > 1200) then return name, "trying" end
  end
  local best, bestRate = list[1], -1
  for _, name in ipairs(list) do
    local value = rate(name) or 0
    if value > bestRate then best, bestRate = name, value end
  end
  return best, "best"
end
farm.choose = choose

-- ---------------------------------------------------------------- moving in a field
-- a ring of points across the field, walked in order (flowers regrow behind the body)
local RING = {}
for i = 0, 7 do
  local angle = i / 8 * math.pi * 2
  RING[#RING + 1] = { math.cos(angle) * 0.6, math.sin(angle) * 0.6 }
end
RING[#RING + 1] = { 0, 0 }
local function bestToken(field, from)
  if not O.tokens then return nil end
  local list = BS.tokensIn(field, 2)
  local best, bestScore = nil, -math.huge
  local reach = O.tokenRange or 60
  for _, token in ipairs(list) do
    local distance = (token.position - from).Magnitude
    local skip = farm.skip and farm.skip[token.part]
    if distance <= reach and not (skip and os.clock() < skip) then
      local score = token.value * 4 - distance
      if score > bestScore then best, bestScore = token, score end
    end
  end
  return best
end
-- One step of work in the field: a token if one is worth it, else the next point of the pattern. Short hops, so
-- the loop looks again (the bag, the health, the player) between them.
local function fieldStep(field)
  local root = B.root()
  if not root then return end
  local token = bestToken(field, root.Position)
  if token then
    local target = Vector3.new(token.position.X, (BS.fieldY(field) or token.position.Y - 3) + 3, token.position.Z)
    -- (a token that is still there 1.5 s after the body stood on it is not ours to take: let it be. A strong table,
    -- swept of gone tokens: a weak one drops Instances that are still there)
    farm.skip = farm.skip or {}
    if next(farm.skip) and math.random() < 0.05 then
      for part in pairs(farm.skip) do
        if not part.Parent then farm.skip[part] = nil end
      end
    end
    farm.skip[token.part] = os.clock() + 1.5
    if BS.go(target, O.fieldSpeed or 35, function() return not token.part.Parent end) then
      task.wait(0.08)
    end
    if not token.part.Parent then
      farm.tokens += 1
      if token.value >= 80 then BS.note("Took a " .. token.name .. " token.") end
    end
    return
  end
  local pattern = O.pattern or "walk"
  if pattern == "still" then
    local spot = BS.spot(field, 0, 0)
    if spot and (root.Position - spot).Magnitude > 4 then BS.go(spot, O.fieldSpeed or 35) end
    task.wait(0.15)
    return
  end
  if pattern == "tokens" then
    -- (no token in reach: stand in the middle and swing until one comes)
    local spot = BS.spot(field, 0, 0)
    if spot and (root.Position - spot).Magnitude > 10 then BS.go(spot, O.fieldSpeed or 35) end
    task.wait(0.15)
    return
  end
  farm.ring = (farm.ring or 0) % #RING + 1
  local point = RING[farm.ring]
  local spot = BS.spot(field, point[1], point[2])
  if spot then BS.go(spot, math.min(O.fieldSpeed or 35, 30)) end
end

-- ---------------------------------------------------------------- sprinklers
local function sprinklers(field)
  if not O.sprinklers or farm.placed == field then return end
  local stats = BS.stats()
  local kind = stats and stats.EquippedSprinkler
  if not kind or kind == "None" then farm.placed = field return end
  local defs = BS.mod("Sprinklers")
  local def = defs and (BS.ask(defs.Get, kind) or (type(defs[kind]) == "table" and defs[kind]))
  local count = math.clamp(def and tonumber(def.Count) or 1, 1, 6)
  local spots = count == 1 and { { 0, 0 } } or {}
  for i = 1, count do
    if count > 1 then
      local angle = i / count * math.pi * 2
      spots[#spots + 1] = { math.cos(angle) * 0.35, math.sin(angle) * 0.35 }
    end
  end
  for _, point in ipairs(spots) do
    local spot = BS.spot(field, point[1], point[2])
    if spot and BS.go(spot, O.fieldSpeed or 35) then
      task.wait(0.25)
      BS.call("PlayerActivesCommand", 5, { Name = "Sprinkler Builder" })
      task.wait(1.1)
    end
  end
  farm.placed = field
  BS.note(string.format("Placed %d sprinkler%s in %s.", #spots, #spots == 1 and "" or "s", field))
end

-- ---------------------------------------------------------------- the hive
local function idle(hive)
  local phase = hive and hive:FindFirstChild("Phase")
  return not phase or phase.Value == "Idle"
end
-- Takes the body to the pad and makes honey until the pollen is gone (or it stops moving for 20 s).
local function convert()
  local pad = BS.pad()
  if not pad then return false end
  farm.state = "converting"
  -- (an instant converter that is ready saves the walk: the extras part says whether it took the pollen)
  if BS.instantConvert and BS.pollen() > 0 then
    BS.release("farm")
    local took = BS.instantConvert()
    BS.take("farm")
    if took and BS.full() < 0.05 then
      farm.converts += 1
      return true
    end
  end
  local spot = pad.Position + Vector3.new(0, 3.5, 0)
  BS.note("Making honey.")
  if not BS.go(spot, O.speed) then return false end
  local hive = BS.hive()
  local honey0 = BS.honey()
  local last, changed, asked = BS.pollen(), os.clock(), -math.huge
  while B.alive and O.farm and BS.pollen() > 0 do
    local root = B.root()
    if not root then break end
    if (root.Position - spot).Magnitude > 7 then BS.go(spot, O.speed) end
    if idle(hive) and os.clock() - asked > 2.5 then
      BS.call("PlayerHiveCommand", 5, "ToggleHoneyMaking")
      asked = os.clock()
    end
    local pollen = BS.pollen()
    if pollen < last then last, changed = pollen, os.clock() end
    if os.clock() - changed > 20 then break end
    -- (the farm's own errands that need the body away, like a dispenser coming off cooldown, can wait for this)
    task.wait(0.25)
  end
  farm.converts += 1
  farm.madeHoney = (farm.madeHoney or 0) + math.max(BS.honey() - honey0, 0)
  return true
end
farm.convert = convert

-- health below the player's line: leave the field (the monsters keep to their territory) and stand at the hive
local function hurt()
  local humanoid = B.humanoid()
  if not humanoid or (O.leaveAt or 0) <= 0 then return false end
  return humanoid.Health < humanoid.MaxHealth * (O.leaveAt / 100)
end

-- ---------------------------------------------------------------- the loop
local function measure(field, dt, gained)
  local r = farm.rates[field] or { pollen = 0, seconds = 0 }
  r.pollen += gained
  r.seconds += dt
  farm.rates[field] = r
  farm.tried[field] = os.clock()
end

local function start(hub)
  for id, default in pairs({ ["bss.farm"] = false, ["bss.dig"] = false, ["bss.fields"] = {}, ["bss.pick"] = "best", ["bss.rotateMins"] = 10,
    ["bss.convertAt"] = 100, ["bss.tokens"] = true, ["bss.tokenFirst"] = {}, ["bss.tokenRange"] = 60, ["bss.pattern"] = "walk",
    ["bss.speed"] = 80, ["bss.fieldSpeed"] = 35, ["bss.sprinklers"] = true, ["bss.leaveAt"] = 30, ["bss.followQuests"] = true }) do
    Config.define(id, default)
  end
  O = Config.mirror({ farm = "bss.farm", dig = "bss.dig", fields = "bss.fields", pick = "bss.pick", rotateMins = "bss.rotateMins",
    convertAt = "bss.convertAt", tokens = "bss.tokens", tokenRange = "bss.tokenRange", pattern = "bss.pattern", speed = "bss.speed",
    fieldSpeed = "bss.fieldSpeed", sprinklers = "bss.sprinklers", leaveAt = "bss.leaveAt", followQuests = "bss.followQuests" })
  farm.options = O
  Config.on("bss.speed", function(value) BS.speed = tonumber(value) or 80 end)
  BS.speed = O.speed or 80

  -- The swing, on its own clock: the farm in a field, or Auto swing with the body in any field. Not with a full bag.
  BS.loop("swing", function()
    do
      if BS.started and (O.farm and farm.digging or (O.dig and B.LP:GetAttribute("CurrentZone") ~= nil)) and BS.full() < 1 then
        swing()
      end
      task.wait(0.05)
    end
  end)

  BS.loop("farm", function()
    do
      local ok = BS.started and BS.ready()
      farm.digging = false
      if not O.farm then
        if farm.state ~= "off" then BS.release("farm") end
        farm.state = "off"
        task.wait(0.4)
      elseif not ok then
        farm.state = "waiting"
        task.wait(0.5)
      elseif BS.paused() then
        if farm.state ~= "paused" then BS.note("Paused: you are playing.") end
        farm.state = "paused"
        BS.release("farm")
        task.wait(0.25)
      elseif not BS.hive() then
        farm.state = "hive"
        if not BS.claim() then BS.note("No hive yet: none free in this server.") task.wait(3) end
      elseif (next(BS.queue) ~= nil and BS.owner == "farm" and not BS.release("farm")) or not BS.take("farm") then
        -- (another part has the body for a moment: a dispenser, a shop, a map token)
        farm.state = "lent"
        task.wait(0.2)
      else
        if not farm.since then farm.since, farm.startHoney = os.clock(), BS.honey() end
        local full = BS.full() >= math.clamp((O.convertAt or 100) / 100, 0.05, 1) - 1e-6
        if full or hurt() then
          if hurt() and not full then BS.note("Hurt: resting at the hive.") end
          convert()
          -- (resting: wait on the pad until health is back over 80%)
          local humanoid = B.humanoid()
          local rested = os.clock()
          while B.alive and O.farm and humanoid and humanoid.Health < humanoid.MaxHealth * 0.8 and os.clock() - rested < 40 do task.wait(0.5) end
          farm.trips += 1
          BS.release("farm")
          task.wait(0.1)
        else
          local field, why = choose()
          if not field then
            BS.note("No open field.")
            task.wait(2)
          else
            if field ~= farm.field then
              farm.field = field
              BS.note(string.format("Farming %s (%s).", field, why or "picked"))
            end
            local root = B.root()
            if root and not BS.inField(root.Position, field, 2) then
              farm.state = "travelling"
              local spot = BS.spot(field, 0, 0)
              if spot then BS.go(spot, O.speed) end
              sprinklers(field)
            else
              farm.state = "collecting"
              farm.digging = true
              local before, t0 = BS.pollen(), os.clock()
              fieldStep(field)
              local gained = BS.pollen() - before
              if gained >= 0 then measure(field, os.clock() - t0, gained) end
            end
          end
        end
      end
    end
  end)
  B.own(function() BS.release("farm") end)
end

-- ---------------------------------------------------------------- the cards
local FIELD_OPTIONS = {}
for _, field in ipairs(BS.FIELDS) do
  FIELD_OPTIONS[#FIELD_OPTIONS + 1] = { field.name, field.need > 0 and string.format("%s (%d bees)", field.name, field.need) or field.name }
end
local TOKEN_OPTIONS = { "Ticket", "StarJelly", "RoyalJelly", "Token Link", "Treat", "Blueberry", "Strawberry", "Pineapple", "SunflowerSeed",
  "Gumdrops", "Glitter", "Glue", "Enzymes", "Oil", "CloudVial", "MagicBean", "Stinger", "Coconut" }

local function farmCards(page)
  local box = page:section({ title = "Farm", icon = "sprout", desc = "Collects, converts at your hive, again." })
  box:toggle({ id = "bss.farm", label = "Auto farm", desc = "Collects in your fields, makes honey when full.", default = false })
  box:multi({ id = "bss.fields", label = "Fields", desc = "None picked: every field you have unlocked.", options = FIELD_OPTIONS, default = {}, empty = "Any open" })
  box:segmented({ id = "bss.pick", label = "Pick", desc = "Best: learns which field gives the most.",
    options = { { "best", "Best" }, { "rotate", "Rotate" }, { "first", "First" } }, default = "best", width = 210 })
  box:slider({ id = "bss.rotateMins", label = "Rotate every", min = 1, max = 60, step = 1, default = 10, suffix = " min" })
  box:slider({ id = "bss.convertAt", label = "Make honey at", desc = "How full the bag is.", min = 10, max = 100, step = 5, default = 100, suffix = "%" })
  box:toggle({ id = "bss.dig", label = "Auto swing", desc = "Swings your tool in any field, even by hand.", default = false })
  local line = box:note({ icon = "activity", text = "" })
  local fields = box:note({ icon = "list", text = "" })

  local tok = page:section({ title = "Tokens", icon = "sparkles", desc = "The server takes one within 5 studs." })
  tok:toggle({ id = "bss.tokens", label = "Collect tokens", desc = "Rare ones first, then the nearest.", default = true })
  tok:multi({ id = "bss.tokenFirst", label = "Go first for", options = TOKEN_OPTIONS, default = {}, empty = "Rare ones" })
  tok:slider({ id = "bss.tokenRange", label = "Chase within", min = 10, max = 150, step = 5, default = 60, suffix = " studs" })
  tok:segmented({ id = "bss.pattern", label = "Between tokens", options = { { "walk", "Walk" }, { "tokens", "Wait" }, { "still", "Stand" } },
    default = "walk", width = 210 })

  local move = page:section({ title = "Moving", icon = "move" })
  move:slider({ id = "bss.speed", label = "Travel speed", desc = "Field to hive and back.", min = 20, max = 300, step = 5, default = 80, suffix = " st/s" })
  move:slider({ id = "bss.fieldSpeed", label = "Speed in a field", desc = "Token runs.", min = 10, max = 120, step = 5, default = 35, suffix = " st/s" })
  move:toggle({ id = "bss.noclip", label = "Noclip while moving", desc = "Through walls on every trip.", default = true })
  move:toggle({ id = "bss.sprinklers", label = "Place sprinklers", desc = "Your set, spread over the field.", default = true })
  move:slider({ id = "bss.leaveAt", label = "Rest when health under", desc = "0 = never.", min = 0, max = 90, step = 5, default = 30, suffix = "%" })

  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    local minutes = farm.since and (os.clock() - farm.since) / 60 or 0
    local made = farm.since and math.max(BS.honey() - (farm.startHoney or 0), 0) or 0
    local perHour = minutes > 0.5 and made / minutes * 60 or 0
    line.set(string.format("%s  ·  %d trips  ·  %s honey (%s/h)  ·  %d tokens  ·  %d swings", farm.state, farm.trips, BS.short(made),
      BS.short(perHour), farm.tokens, farm.swings))
    local rows = {}
    for name, r in pairs(farm.rates) do
      if r.seconds > 5 then rows[#rows + 1] = { name = name, rate = r.pollen / r.seconds } end
    end
    table.sort(rows, function(a, b) return a.rate > b.rate end)
    local text = {}
    for i = 1, math.min(4, #rows) do text[#text + 1] = string.format("%s %s/s", rows[i].name:gsub(" Field", ""):gsub(" Patch", ""), BS.short(rows[i].rate)) end
    fields.set(#text > 0 and ("Measured: " .. table.concat(text, "  ·  ")) or "Fields are measured as you farm them.")
  end, 1, "bss.farm.line")
end

BS.parts[#BS.parts + 1] = { id = "farm", start = start, farm = farmCards }
end
do -- beeswarm_hive.lua
-- ============================================================================
--  Bee Swarm Simulator   the hive: claim it, fill it, feed it, and the next tool and bag
--
--   * ConstructHiveCellFromEgg(x, y, item, amount, untilGifted, mythicChoice) is what the game's egg
--     menu sends: an egg into an empty cell (measured: Basic into C1,1 from the field), or treats
--     fed to the bee in a cell. The game puts the server's answer into its own cache after it: so does the hub.
--   * Shops (workspace.Shops) sell for honey: ItemPackageEvent("Purchase", {Category, Type, Amount}),
--     then ("Equip", {Category, Type}). The hub buys only what costs honey alone (no tickets, no
--     items, never Robux), cheapest first, never below the reserve the player keeps.
--   * What a thing costs and whether the player has it: ItemPackages.GetCost / PlayerHas, the game's own.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util
local BS = B.BeeSwarm

local hive = { hatched = 0, bought = {}, fed = 0, wait = {} }
BS.hiveParts = hive
local O

local function due(key, seconds)
  local now = os.clock()
  if now < (hive.wait[key] or 0) then return false end
  hive.wait[key] = now + seconds
  return true
end
local function count(item)
  local stats = BS.stats()
  return stats and stats.Eggs and tonumber(stats.Eggs[item]) or 0
end
hive.count = count

-- ---------------------------------------------------------------- eggs into empty cells
local EGGS = { "Basic", "Silver", "Gold", "Diamond", "Mythic", "Star" }
local function emptyCells()
  local out = {}
  for _, cell in ipairs(BS.cells()) do
    if not cell.locked and cell.kind == "Empty" then out[#out + 1] = cell end
  end
  return out
end
hive.emptyCells = emptyCells
local function hatch()
  local cells = emptyCells()
  if #cells == 0 then return 0 end
  local done = 0
  local picked = O.hatchEggs or {}
  -- (the best egg first: Star, Mythic, Diamond, Gold, Silver, Basic)
  for i = #EGGS, 1, -1 do
    local egg = EGGS[i]
    if table.find(picked, egg) then
      while count(egg) > 0 and #cells > 0 and B.alive do
        local cell = table.remove(cells, 1)
        local ok, left, took, comb, discovered, uses = BS.call("ConstructHiveCellFromEgg", 8, cell.x, cell.y, egg, 1, false)
        if not (ok and took) then
          BS.note(string.format("The %s egg was not taken (%s).", egg, tostring(left)))
          return done
        end
        local cache = BS.cache()
        if cache then
          BS.ask(cache.Set, cache, { "Eggs", egg }, left)
          if discovered then BS.ask(cache.Set, cache, "DiscoveredBees", discovered) end
          if comb then BS.ask(cache.Set, cache, "Honeycomb", comb) end
          if uses then BS.ask(cache.Set, cache, { "Totals", "EggUses" }, uses) end
        end
        done += 1
        hive.hatched += 1
        task.wait(1.2)
        local kind = cell.cell:FindFirstChild("CellType")
        BS.note(string.format("Hatched a %s egg: %s.", egg, kind and kind.Value or "a bee"))
        BS.toast("New bee", string.format("%s egg: %s", egg, kind and kind.Value or "a bee"), "sparkles", "ok")
      end
    end
  end
  return done
end

-- ---------------------------------------------------------------- shops
-- every honey-only item of the map's shops: { shop, item, pack, cost, category, type }
local function catalogue()
  local out = {}
  local shops = workspace:FindFirstChild("Shops")
  local packages = BS.mod("ItemPackages")
  local stats = BS.stats()
  if not (shops and packages and stats) then return out end
  for _, shop in ipairs(shops:GetChildren()) do
    local items = shop:FindFirstChild("Items")
    if items then
      for _, item in ipairs(items:GetChildren()) do
        local category, kind, amount = item:FindFirstChild("ItemCategory"), item:FindFirstChild("ItemType"), item:FindFirstChild("ItemAmount")
        if category and kind then
          local pack = { Category = category.Value, Type = kind.Value, Amount = amount and amount.Value or nil }
          local cost = BS.ask(packages.GetCost, pack, stats)
          -- (one currency only: honey { Category = "Honey", Amount = n } or tickets { Category = "Eggs", Type = "Ticket", Amount = n };
          -- a list of costs means other items too, and is never bought here)
          local currency = type(cost) == "table" and tonumber(cost.Amount) and (cost.Category == "Honey" and "Honey"
            or (cost.Category == "Eggs" and cost.Type == "Ticket" and "Ticket")) or nil
          if currency then
            out[#out + 1] = { shop = shop, item = item, pack = pack, cost = tonumber(cost.Amount), category = pack.Category, type = pack.Type, currency = currency }
          end
        end
      end
    end
  end
  table.sort(out, function(a, b) return a.cost < b.cost end)
  return out
end
hive.catalogue = catalogue
local function owns(entry)
  local packages = BS.mod("ItemPackages")
  local stats = BS.stats()
  return packages and stats and BS.ask(packages.PlayerHas, entry.pack, stats) == true
end
-- where to stand to buy: on the shop's floor (the game shows a shop only there)
local function shopSpot(shop)
  local floor = shop:FindFirstChild("Floor")
  local part = floor and (floor:IsA("ObjectValue") and floor.Value or floor)
  if not (part and part:IsA("BasePart")) then
    local terrain = shop:FindFirstChild("Terrain")
    part = terrain and (terrain:IsA("ObjectValue") and terrain.Value or terrain)
  end
  if not (part and part:IsA("BasePart")) then return nil end
  return part.Position + Vector3.new(0, part.Size.Y / 2 + 3, 0)
end
-- Buys one thing: the server is asked from where the player stands first; if it says no, from the shop's floor.
local function buy(entry)
  local ok, answer = BS.call("ItemPackageEvent", 10, "Purchase", entry.pack)
  if not (ok and answer) then
    local spot = shopSpot(entry.shop)
    if spot then
      local done = BS.errand("shop", function()
        BS.go(spot, BS.speed)
        task.wait(0.4)
        local ok2, answer2 = BS.call("ItemPackageEvent", 10, "Purchase", entry.pack)
        return ok2 and answer2
      end, 20)
      ok, answer = done ~= false and done ~= nil, done
    end
  end
  if ok and answer then
    BS.refresh()
    hive.bought[#hive.bought + 1] = entry.type
    BS.note(string.format("Bought %s for %s honey.", entry.type, BS.short(entry.cost)))
    BS.toast("Bought", entry.type, "shopping-cart", "ok")
    return true
  end
  return false
end
local function spendable()
  return BS.honey() * (1 - math.clamp((O.reserve or 0) / 100, 0, 0.95))
end
-- the next collector and the next bag: the cheapest one not owned yet, when the honey over the reserve covers it
local GEAR = { Collector = true, Accessory = true }
local BAGS = { Jar = true, Backpack = true, Canister = true, ["Mega-Jug"] = true, Compressor = true, ["Elite Barrel"] = true, ["Port-O-Hive"] = true }
local function gearKind(entry)
  if entry.currency ~= "Honey" then return nil end
  if entry.category == "Collector" then return "collector" end
  if entry.category == "Accessory" and BAGS[entry.type] then return "bag" end
  return nil
end
local function buyGear()
  local list = catalogue()
  local wanted = {}
  for _, entry in ipairs(list) do
    local kind = gearKind(entry)
    if kind and not wanted[kind] and not owns(entry) then wanted[kind] = entry end
  end
  for _, kind in ipairs({ "collector", "bag" }) do
    local entry = wanted[kind]
    if entry and entry.cost <= spendable() then
      if buy(entry) then return true end
      hive.wait.gear = os.clock() + 60
    end
  end
  return false
end
-- the best of what is owned, worn: the dearest honey item of each kind
local function equipBest()
  local stats = BS.stats()
  if not stats then return end
  local best = {}
  for _, entry in ipairs(catalogue()) do
    local kind = gearKind(entry)
    if kind and owns(entry) and (not best[kind] or entry.cost > best[kind].cost) then best[kind] = entry end
  end
  -- (what is worn, the game's own way: PlayerHasEquipped. A bag is in EquippedAccessories.Container, measured: the old
  -- EquippedBackpack field still said "Pouch" with the Jar on, and the hub put the Jar on again every 10 s)
  local packages = BS.mod("ItemPackages")
  local accessories = type(stats.EquippedAccessories) == "table" and stats.EquippedAccessories or {}
  local worn = { collector = stats.EquippedCollector, bag = accessories.Container or stats.EquippedBackpack }
  for kind, entry in pairs(best) do
    local on = packages and BS.ask(packages.PlayerHasEquipped, { Category = entry.category, Type = entry.type }, stats)
    if on == nil then on = worn[kind] == entry.type end
    if not on then
      local ok, answer = BS.call("ItemPackageEvent", 8, "Equip", { Category = entry.category, Type = entry.type })
      if ok and answer then
        if packages then BS.ask(packages.Equip, { Category = entry.category, Type = entry.type, Mute = false }, stats) end
        BS.refresh()
        BS.note("Wearing " .. entry.type .. ".")
      end
    end
  end
end
-- a Basic egg for an empty cell, when the honey over the reserve covers it
local function buyEgg()
  if #emptyCells() == 0 or count("Basic") > 0 then return false end
  for _, entry in ipairs(catalogue()) do
    if entry.type == "Basic" and entry.category == "Eggs" and entry.currency == "Honey" then
      if entry.cost <= spendable() then return buy(entry) end
      return false
    end
  end
  return false
end
-- An egg bought with tickets for an empty cell: the best of the picked kinds the tickets over the kept number cover.
local function buyTicketEgg()
  if #emptyCells() == 0 then return false end
  for _, egg in ipairs(EGGS) do
    if count(egg) > 0 and table.find(O.hatchEggs or {}, egg) then return false end
  end
  local tickets = count("Ticket") - (O.keepTickets or 0)
  local best = nil
  for _, entry in ipairs(catalogue()) do
    if entry.currency == "Ticket" and entry.category == "Eggs" and table.find(O.ticketEggKinds or {}, entry.type)
      and (tonumber(entry.pack.Amount) or 1) == 1 and entry.cost <= tickets and (not best or entry.cost > best.cost) then
      best = entry
    end
  end
  return best ~= nil and buy(best)
end

-- ---------------------------------------------------------------- treats
local TREATS = { "Treat", "Blueberry", "Strawberry", "Pineapple", "SunflowerSeed" }
local function feed()
  local bees = BS.bees()
  if #bees == 0 then return false end
  table.sort(bees, function(a, b) return a.level < b.level end)
  local bee = bees[1]
  for _, treat in ipairs(O.feedWith or { "Treat", "SunflowerSeed" }) do
    local have = count(treat) - (O.feedKeep or 0)
    if have > 0 then
      local amount = math.min(have, 25)
      local ok, left, took, comb = BS.call("ConstructHiveCellFromEgg", 8, bee.x, bee.y, treat, amount, false)
      if ok and took then
        local cache = BS.cache()
        if cache then
          BS.ask(cache.Set, cache, { "Eggs", treat }, left)
          if comb then BS.ask(cache.Set, cache, "Honeycomb", comb) end
        end
        hive.fed += amount
        BS.note(string.format("Fed %d %s to the %s bee (level %d).", amount, treat, tostring(bee.kind), bee.level))
        return true
      end
    end
  end
  return false
end

-- A quest that asks for a treat fed ("Use Items", Item = "Treat"): one bought if none is left (honey only), then fed
-- to the lowest bee. Runs with Auto quests.
local function questFeed()
  local list = BS.quests and BS.quests.active and BS.quests.active() or {}
  for _, quest in ipairs(list) do
    for _, row in ipairs(quest.tasks) do
      local item = row.task and row.task.Item
      if row.share < 1 and row.kind == "Use Items" and type(item) == "string" and table.find(TREATS, item) then
        if count(item) <= 0 then
          local cheapest = nil
          for _, entry in ipairs(catalogue()) do
            if entry.type == item and (not cheapest or entry.cost < cheapest.cost) then cheapest = entry end
          end
          if not (cheapest and cheapest.cost <= spendable() and buy(cheapest)) then return false end
          task.wait(1)
        end
        local bees = BS.bees()
        table.sort(bees, function(a, b) return a.level < b.level end)
        local bee = bees[1]
        if bee and count(item) > 0 then
          local ok, left, took, comb = BS.call("ConstructHiveCellFromEgg", 8, bee.x, bee.y, item, 1, false)
          if ok and took then
            local cache = BS.cache()
            if cache then
              BS.ask(cache.Set, cache, { "Eggs", item }, left)
              if comb then BS.ask(cache.Set, cache, "Honeycomb", comb) end
            end
            hive.fed += 1
            BS.note(string.format("Fed a %s for %s.", item, quest.name))
            return true
          end
        end
        return false
      end
    end
  end
  return false
end

local function start(hub)
  for id, default in pairs({ ["bss.claim"] = false, ["bss.hatch"] = false, ["bss.hatchEggs"] = { "Basic", "Silver", "Gold", "Diamond" },
    ["bss.buyEggs"] = false, ["bss.buyGear"] = false, ["bss.equipBest"] = false, ["bss.reserve"] = 0, ["bss.feed"] = false,
    ["bss.feedWith"] = { "Treat", "SunflowerSeed" }, ["bss.feedKeep"] = 0, ["bss.ticketEggs"] = false, ["bss.ticketEggKinds"] = { "Silver", "Gold" },
    ["bss.keepTickets"] = 0 }) do
    Config.define(id, default)
  end
  O = Config.mirror({ claim = "bss.claim", hatch = "bss.hatch", hatchEggs = "bss.hatchEggs", buyEggs = "bss.buyEggs", buyGear = "bss.buyGear",
    equipBest = "bss.equipBest", reserve = "bss.reserve", feed = "bss.feed", feedWith = "bss.feedWith", feedKeep = "bss.feedKeep",
    ticketEggs = "bss.ticketEggs", ticketEggKinds = "bss.ticketEggKinds", keepTickets = "bss.keepTickets" })
  hive.options = O
  BS.loop("hive", function()
    do
      if BS.started and BS.ready() then
        if O.claim and not BS.hive() and due("claim", 5) then BS.claim() end
        if BS.hive() then
          if O.hatch and due("hatch", 4) then B.try("bss.hatch", hatch) end
          if O.buyEggs and due("egg", 6) then B.try("bss.egg", buyEgg) end
          if O.ticketEggs and due("ticketEgg", 8) then B.try("bss.ticketEgg", buyTicketEgg) end
          if O.buyGear and due("gear", 8) then B.try("bss.gear", buyGear) end
          if O.equipBest and due("equip", 10) then B.try("bss.equip", equipBest) end
          if O.feed and due("feed", 15) then B.try("bss.feed", feed) end
          if Config.get("bss.quests") and due("questFeed", 10) then B.try("bss.questFeed", questFeed) end
        end
      end
      task.wait(0.5)
    end
  end)
end

local function hiveCards(page)
  local box = page:section({ title = "Hive", icon = "box", desc = "Your hive and the bees in it." })
  box:toggle({ id = "bss.claim", label = "Claim a hive", desc = "The nearest free one, at once.", default = false })
  box:toggle({ id = "bss.hatch", label = "Hatch eggs", desc = "Into every empty cell, the best egg first.", default = false })
  box:multi({ id = "bss.hatchEggs", label = "Eggs to hatch", options = EGGS, default = { "Basic", "Silver", "Gold", "Diamond" } })
  box:toggle({ id = "bss.buyEggs", label = "Buy Basic eggs", desc = "While a cell is empty.", default = false })
  box:toggle({ id = "bss.ticketEggs", label = "Buy eggs with tickets", desc = "The best picked egg your tickets cover.", default = false })
  box:multi({ id = "bss.ticketEggKinds", label = "Ticket eggs", options = { "Silver", "Gold", "Diamond", "Mythic" }, default = { "Silver", "Gold" } })
  box:slider({ id = "bss.keepTickets", label = "Keep tickets", min = 0, max = 1000, step = 10, default = 0 })
  box:toggle({ id = "bss.feed", label = "Feed treats", desc = "To the lowest-level bee.", default = false })
  box:multi({ id = "bss.feedWith", label = "Feed with", options = TREATS, default = { "Treat", "SunflowerSeed" } })
  box:slider({ id = "bss.feedKeep", label = "Keep at least", min = 0, max = 500, step = 5, default = 0 })
  local line = box:note({ icon = "info", text = "" })

  local shop = page:section({ title = "Shop", icon = "shopping-cart", desc = "Honey only. Never Robux or tickets." })
  shop:toggle({ id = "bss.buyGear", label = "Buy the next tool and bag", desc = "The cheapest one you lack, when you can.", default = false })
  shop:toggle({ id = "bss.equipBest", label = "Wear the best", desc = "Your dearest tool and bag.", default = false })
  shop:slider({ id = "bss.reserve", label = "Keep honey", desc = "Never spends below this share.", min = 0, max = 90, step = 5, default = 0, suffix = "%" })
  local next = shop:note({ icon = "shopping-cart", text = "" })

  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    local cells = BS.cells()
    local empty, locked = 0, 0
    for _, cell in ipairs(cells) do
      if cell.locked then locked += 1 elseif cell.kind == "Empty" then empty += 1 end
    end
    local eggs = {}
    for _, egg in ipairs(EGGS) do
      local n = count(egg)
      if n > 0 then eggs[#eggs + 1] = string.format("%s %d", egg, n) end
    end
    line.set(string.format("%d bees  ·  %d empty  ·  %d locked  ·  eggs: %s  ·  %d hatched  ·  %d fed", BS.beeCount(), empty, locked,
      #eggs > 0 and table.concat(eggs, ", ") or "none", hive.hatched, hive.fed))
    local wanted = {}
    for _, entry in ipairs(catalogue()) do
      local kind = gearKind(entry)
      if kind and not wanted[kind] and not owns(entry) then wanted[kind] = entry end
    end
    local rows = {}
    for _, kind in ipairs({ "collector", "bag" }) do
      local entry = wanted[kind]
      if entry then rows[#rows + 1] = string.format("%s %s", entry.type, BS.short(entry.cost)) end
    end
    next.set(#rows > 0 and ("Next: " .. table.concat(rows, "  ·  ")) or "Every honey tool and bag is yours.")
  end, 2, "bss.hive.line")
end

BS.parts[#BS.parts + 1] = { id = "hive", start = start, hive = hiveCards }
end
do -- beeswarm_quests.lua
-- ============================================================================
--  Bee Swarm Simulator   quests: take them, follow them, turn them in
--
--   * Each NPC is a list of events (NPCs.Get(name).Events): "Single Quest" (Quest = its name), "Repeat
--     Quest" (QuestPool), "Dialogue", "Options". Where the player stands in it is NPCs.UpdateEventPhase
--     (Start / Ongoing / Finish / Cooldown / Unready). NPCs.ResolveEventPhase is what the game runs when
--     the player talks to an NPC: it works the phase out and tells the server (UpdatePlayerNPCState).
--     The hub runs the same, then sends what the dialogue would at its end: GiveQuest / CompleteQuest,
--     or GiveQuestFromPool / CompleteQuestFromPool. Measured: GiveQuest("Sunflower Start") taken from
--     187 studs away. "Options" events need the player's own choice and are left to them.
--   * A quest's tasks and progress are the game's own (Quests:Progress -> {share, have, goal} a task).
--     "Follow quests" sends the farm to the field a task names, or the open field with the most of the
--     colour it asks for, or where the monster it asks for lives.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util
local BS = B.BeeSwarm

local quests = { given = 0, done = 0, wait = {}, last = {} }
BS.quests = quests
local O

local NPC_OPTIONS = { "Black Bear", "Mother Bear", "Brown Bear", "Panda Bear", "Science Bear", "Polar Bear", "Spirit Bear",
  "Bucko Bee", "Riley Bee", "Honey Bee", "Onett", "Stick Bug", "Bubble Bee Man 2", "Gummy Bear", "Dapper Bear" }
local NPC_DEFAULT = { "Black Bear", "Mother Bear", "Brown Bear", "Panda Bear", "Science Bear", "Polar Bear", "Spirit Bear",
  "Bucko Bee", "Riley Bee", "Honey Bee", "Onett" }

local function due(key, seconds)
  local now = os.clock()
  if now < (quests.wait[key] or 0) then return false end
  quests.wait[key] = now + seconds
  return true
end

-- One NPC, one step, the way a talk with them would go. Returns what was done, or nil.
local function step(name)
  local npcs, list = BS.mod("NPCs"), BS.mod("Quests")
  local stats = BS.stats()
  if not (npcs and list and stats) then return nil end
  local npc = BS.ask(npcs.Get, name)
  if type(npc) ~= "table" or type(npc.Events) ~= "table" then return nil end
  local event, phase = BS.ask(npcs.ResolveEventPhase, name)
  if not event then return nil end
  local data = npc.Events[event]
  if type(data) ~= "table" then return nil end
  local kind = data.Type
  local function after(what)
    BS.refresh()
    quests.last[name] = what
    return what
  end
  if kind == "Single Quest" and type(data.Quest) == "string" then
    if phase == "Start" then
      local ok = BS.call("GiveQuest", 8, data.Quest)
      if ok then
        quests.given += 1
        BS.note(string.format("Quest from %s: %s.", name, data.Quest))
        return after("took " .. data.Quest)
      end
    elseif phase == "Finish" then
      local ok = BS.call("CompleteQuest", 8, data.Quest)
      if ok then
        quests.done += 1
        BS.note(string.format("Turned in %s to %s.", data.Quest, name))
        BS.toast("Quest done", data.Quest, "list", "ok")
        return after("finished " .. data.Quest)
      end
    end
  elseif kind == "Repeat Quest" and type(data.QuestPool) == "string" then
    if phase == "Start" then
      local ok = BS.call("GiveQuestFromPool", 8, data.QuestPool)
      if ok then
        quests.given += 1
        BS.note(string.format("A %s quest.", name))
        return after("took a quest")
      end
    elseif phase == "Finish" then
      local ok = BS.call("CompleteQuestFromPool", 8, data.QuestPool)
      if ok then
        quests.done += 1
        BS.note(string.format("Turned in a %s quest.", name))
        BS.toast("Quest done", name, "list", "ok")
        return after("finished a quest")
      end
    end
  elseif kind == "Dialogue" then
    -- (ResolveEventPhase moved it on: Start -> Ongoing -> the next event)
    return "talked"
  end
  return nil
end
quests.step = step

-- The active quests and their tasks: { name, npc, tasks = { { kind, text, have, goal, share, task } } }
function quests.active()
  local out = {}
  local list, stats = BS.mod("Quests"), BS.stats()
  if not (list and stats and stats.Quests and type(stats.Quests.Active) == "table") then return out end
  for _, active in ipairs(stats.Quests.Active) do
    local def = BS.ask(list.Get, list, active.Name)
    if def then
      local tasks = BS.ask(list.ResolveTasks, def, stats) or {}
      local progress = BS.ask(list.Progress, list, active.Name, stats) or {}
      local rows = {}
      for i, task in ipairs(tasks) do
        local p = progress[i] or { 0, 0, 1 }
        local text = type(task.Description) == "function" and BS.ask(task.Description, stats) or task.Description
        rows[#rows + 1] = { kind = task.Type, text = tostring(text or task.Type), have = tonumber(p[2]) or 0, goal = tonumber(p[3]) or 1,
          share = tonumber(p[1]) or 0, task = task }
      end
      out[#out + 1] = { name = active.Name, npc = def.NPC, tasks = rows }
    end
  end
  return out
end

-- the open field with the most of a colour
local function colourField(colour)
  local best, bestShare = nil, 0
  for _, field in ipairs(BS.FIELDS) do
    if BS.unlocked(field.name) then
      local share = BS.colors(field.name)[colour] or 0
      if share > bestShare then best, bestShare = field.name, share end
    end
  end
  return best
end
-- the open field a monster lives in, the weakest spawner of that kind first: field, level
local function monsterField(kind)
  local spawners = workspace:FindFirstChild("MonsterSpawners")
  if not spawners then return nil end
  local best, bestLevel = nil, math.huge
  -- (a value object's value, or nil: some spawners keep a ModuleScript under the same name, the Commando Chick's level)
  local function read(node, key)
    local child = node:FindFirstChild(key)
    return child and child:IsA("ValueBase") and child.Value or nil
  end
  for _, spawner in ipairs(spawners:GetChildren()) do
    local monster = read(spawner, "MonsterType")
    local level = tonumber(read(spawner, "MonsterLevel")) or 1
    if monster == kind and spawner:IsA("BasePart") and level < bestLevel then
      local territory = read(spawner, "Territory")
      local name = territory and tostring(territory)
      local field = nil
      if name and BS.NEED[name] and BS.unlocked(name) then
        field = name
      else
        -- (a territory that is not a field, "MushroomZone": the open field nearest the spawner)
        local bestDistance = 120
        for _, entry in ipairs(BS.FIELDS) do
          local zone = BS.zone(entry.name)
          if zone and BS.unlocked(entry.name) then
            local distance = (zone.Position - spawner.Position).Magnitude
            if distance < bestDistance then field, bestDistance = entry.name, distance end
          end
        end
      end
      if field then best, bestLevel = field, level end
    end
  end
  return best, bestLevel
end
quests.monsterField = monsterField
-- Where the quests want the farm: of every unfinished task that names a field, a colour or a monster, the one
-- that should take the least time (pollen left over the field's measured rate; a monster ~2 min a level), skipping
-- what would take more than an hour and monsters stronger than the hive.
function BS.questField()
  if not O then return nil end
  local farm = BS.farm
  local fallback = 4
  if farm and farm.rates then
    for _, r in pairs(farm.rates) do
      if r.seconds > 20 then fallback = math.max(fallback, r.pollen / r.seconds) end
    end
  end
  local function seconds(field, left)
    local rate = farm and farm.rate and farm.rate(field)
    return left / math.max(rate or fallback, 0.5)
  end
  local best, bestTime, bestWhy = nil, 3600, nil
  for _, quest in ipairs(quests.active()) do
    if not quest.npc or table.find(O.npcs or NPC_DEFAULT, quest.npc) then
      for _, row in ipairs(quest.tasks) do
        if row.share < 1 then
          local task = row.task
          local left = math.max(row.goal - row.have, 0)
          local field, time = nil, math.huge
          if row.kind == "Collect Pollen" or row.kind == "Collect Goo" then
            if type(task.Zone) == "string" and BS.unlocked(task.Zone) then
              field = task.Zone
            elseif type(task.Color) == "string" then
              field = colourField(task.Color)
            end
            if field then time = seconds(field, left) * (type(task.Color) == "string" and 1.3 or 1) end
          elseif row.kind == "Defeat Monsters" and type(task.MonsterType) == "string" then
            local where, level = monsterField(task.MonsterType)
            if where and BS.beeCount() >= (level or 1) then field, time = where, left * 120 * (level or 1) end
          end
          if field and time < bestTime then best, bestTime, bestWhy = field, time, quest.name end
        end
      end
    end
  end
  return best, bestWhy
end

local function start(hub)
  for id, default in pairs({ ["bss.quests"] = false, ["bss.npcs"] = NPC_DEFAULT }) do Config.define(id, default) end
  O = Config.mirror({ quests = "bss.quests", npcs = "bss.npcs" })
  quests.options = O
  BS.loop("quests", function()
    do
      if O.quests and BS.started and BS.ready() and BS.hive() then
        for _, name in ipairs(O.npcs or NPC_DEFAULT) do
          if not B.alive or not O.quests then break end
          -- (an NPC is asked again soon after it did something, else every 6 s)
          if due("npc." .. name, 6) then
            local did = step(name)
            if did and did ~= "talked" then quests.wait["npc." .. name] = os.clock() + 1.5 end
            if did == "talked" then quests.wait["npc." .. name] = os.clock() + 0.6 end
          end
        end
      end
      task.wait(0.5)
    end
  end)
end

local function questCards(page)
  local box = page:section({ title = "Quests", icon = "list", desc = "Taken and turned in from anywhere." })
  box:toggle({ id = "bss.quests", label = "Auto quests", desc = "Takes, follows and turns in quests.", default = false })
  box:multi({ id = "bss.npcs", label = "From", options = NPC_OPTIONS, default = NPC_DEFAULT })
  box:toggle({ id = "bss.followQuests", label = "Farm for quests", desc = "The farm goes where a quest needs it.", default = true })
  local line = box:note({ icon = "activity", text = "" })
  local list = page:section({ title = "Active", icon = "list" })
  local rows = list:note({ icon = "list", text = "No quest yet." })
  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    local field, why = BS.questField()
    line.set(string.format("%d taken  ·  %d turned in%s", quests.given, quests.done, field and string.format("  ·  farming %s for %s", field, tostring(why)) or ""))
    local text = {}
    for _, quest in ipairs(quests.active()) do
      local parts = {}
      for _, row in ipairs(quest.tasks) do
        parts[#parts + 1] = string.format("%s %d%%", row.text, math.floor(math.min(row.share, 1) * 100))
      end
      text[#text + 1] = string.format("%s (%s): %s", quest.name, tostring(quest.npc or "?"), table.concat(parts, "; "))
      if #text >= 6 then break end
    end
    rows.set(#text > 0 and table.concat(text, "\n") or "No quest yet.")
  end, 2, "bss.quests.line")
end

BS.parts[#BS.parts + 1] = { id = "quests", start = start, quests = questCards }
end
do -- bloxfruits.lua
-- ============================================================================
--  Blox Fruits     the engine: one body, many jobs, and a watch over both
--
--  Read from the game and measured on 2026-11-13 (universe 994732206, First Sea
--  place 2753915549 v4630, 6,232 client scripts read; one account, level 1).
--  The numbers and where each came from are in _work/bloxfruits-1113/NOTES.md.
--
--   * The game's own tables are readable: Quests (every quest, its level, its
--     mobs, its reward) and GuideModule's NPCList (who gives which, and where).
--     Nothing about quests is written down here: the game is asked.
--   * A hit is the client's to report, through the game's own door:
--     Net "RegisterAttack" (the swing's real length, the combo step), then
--     Global.SendHitsToServer(part, others), which adds the session's token.
--     The server takes about three a second, from up to 60 studs above.
--   * A body is moved by writing where it is, every frame, with no speed of
--     its own: never anchored (an anchored body's hits are refused).
--
--  How this is built. There is ONE body, so one job at a time owns it: the
--  director picks the job that wants it most. A job is a plain loop that reads
--  the game afresh each round and says "I am alive" as it goes. The director
--  watches: a job that falls silent, errors or stops making progress is taken
--  off the body and put right by steps that grow (stand still and re-arm, drop
--  the quest and the target, start the body again, rest) and never by doing
--  the same thing again for ever.
-- ============================================================================
local B = B or ...
local S, util, Config, Window, Motion = B.S, B.util, B.Config, B.Window, B.Motion

local BF = { parts = {}, jobs = {}, events = {}, count = { kills = 0, quests = 0, repairs = 0, lagbacks = 0, deaths = 0, calls = 0 }, pilot = { mode = "idle" } }
B.BloxFruits = BF
BF.UNIVERSE = 994732206
BF.SEAS = { [2753915549] = 1, [4442272183] = 2, [7449423635] = 3 }
BF.PACE = 0.34            -- seconds between hits the server takes (measured)
BF.keepQuests = { BartiloQuest = true, CitizenQuest = true }      -- story quests no farm may drop (a part adds its own)
-- jobs of opportunity, and the farms they may interrupt (a part adds its own ids)
BF.casual = { chestNear = true, berries = true }
BF.farmJobs = { level = true, mob = true, nearest = true, material = true, bones = true }
-- the tabs, in the order they stand in the sidebar after Farm (Fighting is the engine's own)
BF.TABS = {
  { id = "boss", title = "Bosses", icon = "skull" }, { id = "loot", title = "Loot", icon = "package" }, { id = "mastery", title = "Mastery", icon = "trophy" },
  { id = "fruit", title = "Fruits", icon = "apple" }, { id = "quest", title = "Quests", icon = "flag" }, { id = "raid", title = "Raids", icon = "flame" },
  { id = "sea", title = "Sea", icon = "anchor" }, { id = "race", title = "Race", icon = "crown" }, { id = "fight", title = "Fighting", icon = "swords" },
  { id = "player", title = "Stats", icon = "gauge" }, { id = "shop", title = "Shop", icon = "gem" }, { id = "travel", title = "Travel", icon = "navigation" },
  { id = "esp", title = "ESP", icon = "scan-eye" }, { id = "server", title = "Server", icon = "server" }, { id = "misc", title = "Extras", icon = "sparkles" },
}
local O = {}
BF.O = O

-- ---------------------------------------------------------------- small things
local function now() return os.clock() end
-- Which sea this is. The game is asked (its own Util.Realm, once, at start: see `start`), so a place the hub has
-- never heard of is still the right sea; until it has answered, the place's number says.
function BF.sea() return BF.seaAsked or BF.SEAS[game.PlaceId] or 1 end
-- State kept against an Instance (a mob set aside, a chest tried twice, the way a tool hits). These are plain
-- tables: a weak key can lose its entry while the Instance is still in the game, and "set aside" is forgotten.
-- They are swept instead: an entry goes when its Instance has left the game.
local kept = {}
function BF.keep(t)
  kept[#kept + 1] = t
  return t
end
local function sweep()
  for _, t in ipairs(kept) do
    for key in pairs(t) do
      if typeof(key) == "Instance" and key.Parent == nil then t[key] = nil end
    end
  end
end
function BF.char() return B.LP.Character end
function BF.root()
  local c = B.LP.Character
  return c and c:FindFirstChild("HumanoidRootPart")
end
function BF.hum()
  local c = B.LP.Character
  return c and c:FindFirstChildOfClass("Humanoid")
end
function BF.alive()
  local h, r = BF.hum(), BF.root()
  return h ~= nil and r ~= nil and h.Health > 0
end
-- a value of the player's saved data (Level, Beli, Fragments, Race, DevilFruit, Points, ...)
function BF.data(name)
  local data = B.LP:FindFirstChild("Data")
  local value = data and data:FindFirstChild(name)
  return value and value.Value
end
function BF.level() return tonumber(BF.data("Level")) or 1 end
-- what happened, newest last (the Farm tab shows the tail)
function BF.say(text)
  local events = BF.events
  events[#events + 1] = string.format("%s  %s", os.date("%H:%M:%S"), text)
  if #events > 60 then table.remove(events, 1) end
end
-- A call into the game's own code. Such a call can leave this thread without the right to touch the hub's
-- own windows: the right is taken back before anything else is done.
local function restore()
  if type(setthreadidentity) == "function" then pcall(setthreadidentity, 8) end
end
function BF.game(fn, ...)
  local out = table.pack(pcall(fn, ...))
  restore()
  return table.unpack(out, 1, out.n)
end
local modules = {}
function BF.mod(...)
  local key = table.concat({ ... }, "/")
  local got = modules[key]
  if got ~= nil then return got or nil end
  local at = S.ReplicatedStorage
  for _, name in ipairs({ ... }) do
    at = at and at:FindFirstChild(name)
  end
  local ok, result = false, nil
  if at then ok, result = BF.game(require, at) end
  modules[key] = ok and result or false
  return ok and result or nil
end

-- ---------------------------------------------------------------- the command bus
-- One call to the server with an end to the wait: a call that never answers costs `timeout` seconds, not the job.
function BF.invoke(timeout, ...)
  local remotes = S.ReplicatedStorage:FindFirstChild("Remotes")
  local bus = remotes and remotes:FindFirstChild("CommF_")
  if not bus then return false, "no CommF_" end
  local args = table.pack(...)
  local done, out = false, nil
  BF.count.calls += 1
  local thread = task.spawn(function()
    out = table.pack(pcall(bus.InvokeServer, bus, table.unpack(args, 1, args.n)))
    done = true
  end)
  local started = now()
  while not done and now() - started < (timeout or 6) do task.wait() end
  if not done then
    -- (the wait ends here, and so does the thread that asked: a server that has gone silent does not leave one
    -- more waiting thread behind for every call made meanwhile)
    pcall(task.cancel, thread)
    return false, "timeout"
  end
  if not out[1] then return false, tostring(out[2]) end
  return true, table.unpack(out, 2, out.n)
end

-- ---------------------------------------------------------------- the pilot: where the body is
-- One Heartbeat hand on the body. "hold" pins it at a point; "fly" walks that point toward a goal at a speed.
-- A pull-back by the server shows as the body not being where it was put: the pilot notes it, takes the
-- server's place as true, waits and goes on slower.
local pilot = BF.pilot
local function release()
  if pilot.mode ~= "idle" then
    -- (the body's own collisions come back: the root's is the one nothing else puts back)
    local root = B.LP.Character and B.LP.Character:FindFirstChild("HumanoidRootPart")
    if root then pcall(function() root.CanCollide = true end) end
  end
  pilot.mode, pilot.at, pilot.goal, pilot.long = "idle", nil, nil, nil
end
BF.release = release
function BF.holdAt(point, face)
  pilot.mode, pilot.at, pilot.face, pilot.goal = "hold", point, face, nil
  pilot.put = nil
end
local function pilotStep(dt)
  if pilot.mode == "idle" then return end
  local root, hum = BF.root(), BF.hum()
  if not (root and hum and hum.Health > 0) then
    -- (no living body: the hand comes off. The next body is then neither pinned where the last one fought nor
    -- counted as pulled back the moment it appears)
    pilot.mode, pilot.at, pilot.goal, pilot.put, pilot.long = "idle", nil, nil, nil, nil
    return
  end
  local at = pilot.at or root.Position
  local put = pilot.put
  if put and (root.Position - put).Magnitude > math.max(O.lagback or 40, (pilot.speed or 0) * dt * 6) then
    -- not where it was put: the server moved it
    BF.count.lagbacks += 1
    pilot.lagbacks = (pilot.lagbacks or 0) + 1
    pilot.pausedUntil = now() + 0.6
    pilot.speed = math.max(80, (pilot.speed or 200) * 0.8)
    at = root.Position
    pilot.put = nil
  end
  if pilot.mode == "fly" and pilot.goal and not (pilot.pausedUntil and now() < pilot.pausedUntil) then
    local to = pilot.goal - at
    local gap = to.Magnitude
    local step = (pilot.speed or 200) * dt
    if gap <= step then at = pilot.goal; pilot.arrived = true else at = at + to / gap * step end
  end
  pilot.at = at
  local face = pilot.face
  if face and (Vector3.new(face.X, at.Y, face.Z) - at).Magnitude > 0.5 then
    root.CFrame = CFrame.new(at, Vector3.new(face.X, at.Y, face.Z))
  else
    root.CFrame = CFrame.new(at) * (root.CFrame - root.CFrame.Position)
  end
  root.AssemblyLinearVelocity = Vector3.zero
  root.AssemblyAngularVelocity = Vector3.zero
  pilot.put = at
end
local function pilotClip()
  if pilot.mode == "idle" then return end
  local character = BF.char()
  if not character then return end
  for _, part in ipairs(character:GetChildren()) do
    if part:IsA("BasePart") and part.CanCollide then part.CanCollide = false end
  end
end
-- ---------------------------------------------------------------- gates
-- A far part of a sea that the game reaches through a portal. Measured 2026-11-13 in the First Sea (the whirlpool to
-- the Underwater City, 57,000 studs off): standing at the pad and asking the server for the far point
-- ("requestEntrance", the point) is answered with that point, and the body is there; the same on the way back.
-- The four parts are the game's own, read live: Map.TeleportSpawn.Entrance / EntrancePoint / Exit / ExitPoint.
function BF.gates()
  local out = {}
  local map = workspace:FindFirstChild("Map")
  local spawn = map and map:FindFirstChild("TeleportSpawn")
  if spawn then
    local pad, point, back, home = spawn:FindFirstChild("Entrance"), spawn:FindFirstChild("EntrancePoint"), spawn:FindFirstChild("Exit"), spawn:FindFirstChild("ExitPoint")
    if pad and point and back and home and pad:IsA("BasePart") and point:IsA("BasePart") and back:IsA("BasePart") and home:IsA("BasePart") then
      out[#out + 1] = { name = "the whirlpool", nearPad = pad.Position, farPoint = point.Position, farPad = back.Position, nearPoint = home.Position }
    end
  end
  return out
end
local function beyond(gate, point) return (point - gate.farPoint).Magnitude < (O.gateZone or 9000) end
-- How long a trip is as the body would make it: through a gate when its two ends are on different sides of one.
-- Returns the length, and the gate and whether it is taken inward.
function BF.trip(from, to)
  -- (a gate that would not answer twice running is left alone for five minutes: the long way is then the only way,
  -- and a quest behind the gate is simply too far, so nothing goes round and round a pad that does not work)
  if O.gates ~= false and not (BF.gateDown and now() < BF.gateDown) then
    for _, gate in ipairs(BF.gates()) do
      local a, b = beyond(gate, from), beyond(gate, to)
      if a ~= b then
        if b then return (gate.nearPad - from).Magnitude + (to - gate.farPoint).Magnitude, gate, true end
        return (gate.farPad - from).Magnitude + (to - gate.nearPoint).Magnitude, gate, false
      end
    end
  end
  return (to - from).Magnitude
end

-- The speed this server has been seen to take. A trip that was pulled back lowers it for the next trips; a long
-- clean trip lets it climb back, a little at a time, to what the player asked for. It is judged the moment a
-- trip ends, however it ends: the trips given up half way are the ones with the most to teach.
local function judge(asked, learned, flat, whole)
  if (pilot.lagbacks or 0) > 0 then
    BF.speedCap = math.max(120, learned * 0.88)
  elseif whole and BF.speedCap and flat > 300 then
    BF.speedCap = math.min(asked, BF.speedCap * 1.04)
  end
end
-- Through a gate: to its pad, the server asked, and the body seen on the far side. A gate that does not answer,
-- or answers and leaves the body where it was, fails the trip: the long way round (57,000 studs of open sea, for
-- the whirlpool) is never flown by mistake.
local function throughGate(gate, inward, ctx, opts)
  local pad, ask = inward and gate.nearPad or gate.farPad, inward and gate.farPoint or gate.nearPoint
  local ok, why = BF.fly(pad + Vector3.new(0, 8, 0), ctx, { noGate = true, note = "To " .. gate.name, speed = opts.speed })
  if not ok then return false, why end
  local entered, answer = BF.enter(ask)
  if not entered then
    -- (once more from the pad's own height: a body a little too high is not "at" the pad)
    BF.holdAt(pad + Vector3.new(0, 3, 0))
    task.wait(0.4)
    entered, answer = BF.enter(ask)
  end
  local there = false
  if entered then
    local untilAt = now() + 4
    while now() < untilAt do
      local body = BF.root()
      if body and (body.Position - ask).Magnitude < 80 then there = true; break end
      if ctx then ctx:beat("Through " .. gate.name) end
      task.wait(0.1)
    end
  end
  if not there then
    release()
    BF.gateFails = (BF.gateFails or 0) + 1
    if BF.gateFails >= 2 then
      BF.gateDown, BF.gateFails = now() + 300, 0
      BF.say(gate.name .. " would not take the body: not used for five minutes")
    end
    return false, entered and (gate.name .. " did not take the body") or (gate.name .. " did not answer (" .. tostring(answer) .. ")")
  end
  BF.gateFails = 0
  BF.count.gates = (BF.count.gates or 0) + 1
  return true
end

-- Fly the body to a point. Far trips rise first, cross, then come down: a straight line under the sea or
-- through a cliff is where bodies die. A trip to the far side of a gate goes through the gate. Returns true,
-- or false and why.
function BF.fly(goal, ctx, opts)
  opts = opts or {}
  local root = BF.root()
  if not root then return false, "no body" end
  if not opts.noGate then
    local _, gate, inward = BF.trip(root.Position, goal)
    if gate then
      local ok, why = throughGate(gate, inward, ctx, opts)
      if not ok then return false, why end
      root = BF.root()
      if not root then return false, "no body" end
    end
  end
  local legs = {}
  local start = root.Position
  local flat = Vector3.new(goal.X - start.X, 0, goal.Z - start.Z).Magnitude
  if flat > 350 and not opts.direct then
    local cruise = math.max(start.Y, goal.Y) + (O.cruise or 60)
    legs[#legs + 1] = Vector3.new(start.X, cruise, start.Z)
    legs[#legs + 1] = Vector3.new(goal.X, cruise, goal.Z)
  end
  legs[#legs + 1] = goal
  pilot.lagbacks = 0
  -- (a long trip, such as a farm's flight to its next island: the director lets no chest cut into one)
  pilot.long = flat > (O.longTrip or 2000) or nil
  local asked = opts.speed or O.speed or 250
  local learned = math.min(asked, BF.speedCap or asked)
  for _, leg in ipairs(legs) do
    local from = (BF.root() or root).Position
    local budget = (leg - from).Magnitude / math.max(learned * 0.4, 40) + 8
    pilot.mode, pilot.at, pilot.goal, pilot.speed, pilot.arrived, pilot.face, pilot.put = "fly", from, leg, learned, false, opts.face, nil
    local started, seen = now(), pilot.lagbacks or 0
    while not pilot.arrived do
      local why
      if not B.alive or (ctx and ctx.stop) then
        why = "stopped"
      elseif not BF.alive() then
        why = "dead"
      elseif (pilot.lagbacks or 0) > 8 then
        why = "pulled back too often"
      elseif now() - started > budget then
        why = "the trip took too long"
      end
      if why then
        release()
        judge(asked, learned, flat, false)
        return false, why
      end
      if (pilot.lagbacks or 0) > seen then
        -- (a pull-back pauses the leg and slows the rest of it: the time allowed is worked out again from here)
        seen = pilot.lagbacks
        local mine = BF.root()
        local left = mine and (leg - mine.Position).Magnitude or 0
        budget = (now() - started) + left / math.max((pilot.speed or learned) * 0.4, 40) + 8
      end
      if ctx then ctx:beat(opts.note or "Travelling") end
      task.wait(0.05)
    end
  end
  judge(asked, learned, flat, true)
  -- (it stays held where it arrived: the caller lets go, or holds somewhere else)
  pilot.mode, pilot.goal, pilot.long = "hold", nil, nil
  return true
end

-- A portal, the way the game's own client takes one (PlayerScripts.AnimateEntrance): the server is asked with
-- the point, and the body is put where the server ANSWERS. Measured 2026-11-13: asked from across the map the
-- answer is nil; asked from the portal's own pad it is the point, and the body is there (the whirlpool, both ways).
function BF.enter(point)
  local ok, answer = BF.invoke(8, "requestEntrance", point)
  if not ok or typeof(answer) ~= "Vector3" then return false, answer end
  if not BF.root() then return false, "no body" end
  pilot.mode, pilot.at, pilot.goal, pilot.put, pilot.face = "hold", answer, nil, nil, nil
  return true, answer
end

-- ---------------------------------------------------------------- weapons and hits
-- (measured live 2026-11-13: a fruit's tool says "Demon Fruit"; "Blox Fruit" is only the name on the stats screen)
local TYPES = { melee = "Melee", sword = "Sword", fruit = "Demon Fruit", gun = "Gun" }
local function kindOf(tool)
  local kind = tool:GetAttribute("WeaponType") or tool.ToolTip
  if kind == "Blox Fruit" then kind = "Demon Fruit" end
  return type(kind) == "string" and kind or ""
end
-- the tool to fight with: the one named, else the first of the kind asked for, else a real weapon (melee first)
local WEAPON = { Melee = true, Sword = true, ["Demon Fruit"] = true, Gun = true }
function BF.weapon()
  local character, pack = BF.char(), B.LP:FindFirstChild("Backpack")
  if not character then return nil end
  local want, named = TYPES[O.weapon or "melee"], O.weaponName
  -- (a part that trains one weapon names it here for as long as it does: nothing of the player's is written over)
  local over = BF.weaponOverride
  if type(over) == "string" and over ~= "" then named = over end
  local held, melee, any
  local function scan(from)
    for _, tool in ipairs(from:GetChildren()) do
      -- (a fruit that can be eaten is never a weapon: it is only ever carried to be stored)
      if tool:IsA("Tool") and not tool:FindFirstChild("EatRemote") then
        if named and named ~= "" and string.lower(tool.Name) == string.lower(named) then return tool end
        local kind = kindOf(tool)
        if not held and want and kind == want then held = tool end
        -- (a torch, a cup, a relic carried for a quest is not a weapon: only the four kinds are ever fought with)
        if WEAPON[kind] then
          if not melee and kind == "Melee" then melee = tool end
          any = any or tool
        end
      end
    end
  end
  local exact = scan(character) or (pack and scan(pack))
  return exact or held or melee or any
end
function BF.equip()
  local character, hum = BF.char(), BF.hum()
  local tool = BF.weapon()
  if not (character and hum and tool) then return nil end
  if tool.Parent ~= character then
    pcall(function() hum:EquipTool(tool) end)
  end
  return tool
end
-- the real length of the first swing of what is held (the server is told it with every swing)
local lengths = BF.keep({})
local function swingLength(tool)
  local known = lengths[tool]
  if known then return known end
  local length = 0.5
  local util2 = BF.mod("Modules", "CombatUtil")
  local hum = BF.hum()
  if util2 and hum then
    BF.game(function()
      local anims = util2:GetLoadedAnimsFor(util2:GetWeaponName(tool), hum)
      for key, track in pairs(anims or {}) do
        if string.find(tostring(key), "basic1", 1, true) and typeof(track) == "Instance" and track.Length > 0 then
          length = track.Length / (track:GetAttribute("SpeedMult") or 1)
        end
      end
    end)
  end
  lengths[tool] = length
  return length
end
-- How a weapon's hit is sent. "direct": the swing and the hit told to the server (proven on Combat: three a
-- second, from 60 studs up). "own": the game's own Attack, from beside the mob (measured 2026-11-13: with a
-- fruit in the hand the direct way took no health off in 40 s).
--
-- THE BODY STAYS ABOVE THE MOBS (the owner's word, 2026-11-13, with a clip of the body dropping into a stack of
-- four Toga Warriors and dying there). "own" is the only way that goes down, so it is used only when the player
-- has switched "May go down beside a mob" on (closeIn, off by default). With it off: melee, swords and a fruit
-- that has a basic attack are sent directly from above; a weapon whose direct hits do not land fights with its
-- skills from above; a mob that will not lose health is left alone, never gone down to.
local methods = BF.keep({})
local directFails = BF.keep({})      -- tool -> mobs in a row the direct way took no health off
function BF.method(tool)
  if not tool then return "direct" end
  local way = methods[tool]
  if not way then
    local kind = kindOf(tool)
    if kind == "Gun" then
      -- (a gun's own shot wants a real click and goes where the mouse points: read from the game's CombatController
      -- (shootGun reads the input's UserInputType and the mouse's Hit), not built. Until it is, a gun fights the
      -- way a fruit with no basic attack does: with its skills)
      way = "skills"
    elseif kind == "Demon Fruit" and not tool:FindFirstChild("LeftClickRemote") then
      -- (measured live 2026-11-13: most fruits have NO basic attack at all, only skills. The ones that have one
      -- carry a LeftClickRemote in the tool: Dark and Rubber do not, Blade and T-Rex do)
      way = "skills"
    else
      -- (melee and swords: proven. A fruit with a basic attack goes through the same door in the game's own code,
      -- attackMelee: sent directly first, not yet proven; the fight moves it to its skills if nothing lands)
      way = "direct"
    end
  end
  if way == "own" and O.closeIn ~= true then return "skills" end
  return way
end
-- a weapon that can only hurt with its skills: the fight holds it over the mob and lets the skills part cast
function BF.skillsOnly(tool) return tool ~= nil and BF.method(tool) == "skills" end
function BF.otherMethod(tool)
  if not tool then return end
  methods[tool] = BF.method(tool) == "direct" and "own" or "direct"
  BF.say(string.format("%s: hits were not landing, now sent %s", tool.Name, methods[tool] == "own" and "by the game's own attack, from beside the mob" or "directly, from above"))
end
-- One hit on `first` (a mob) and, with it, on `others`. Sent no faster than the pace the server takes.
local lastHit, combo = 0, 0
function BF.hit(first, others)
  local t = now()
  if t - lastHit < (O.pace or BF.PACE) then return false end
  -- (a part that is holding a skill key says until when: no swing and no re-arming under it)
  if BF.casting and BF.casting > t then return false end
  local tool = BF.equip()
  if tool and BF.method(tool) == "skills" then return false end
  if tool and BF.method(tool) == "own" then
    local controller = BF.mod("Controllers", "CombatController")
    if not controller then return false end
    lastHit = t
    local ok, err = BF.game(function() controller:Attack(tool) end)
    if not ok and t - (BF.ownSaidAt or 0) > 30 then
      BF.ownSaidAt = t
      BF.say("the game's own attack failed: " .. string.sub(tostring(err), 1, 80))
    end
    return ok
  end
  local net, global = BF.mod("Modules", "Net"), BF.mod("Global")
  if not (tool and net and global and type(global.SendHitsToServer) == "function") then return false end
  local part = first:FindFirstChild("UpperTorso") or first:FindFirstChild("HumanoidRootPart")
  if not part then return false end
  -- the rest of the swing: only mobs that really stand with the first one (a far one would be refused), and no
  -- more than the player allows in one swing
  local list = {}
  local reach, most = O.multiReach or 60, O.multiMax or 8
  for _, mob in ipairs(others or {}) do
    if #list >= most then break end
    local piece = mob:FindFirstChild("UpperTorso") or mob:FindFirstChild("HumanoidRootPart")
    if piece and mob ~= first and (piece.Position - part.Position).Magnitude <= reach then list[#list + 1] = { mob, piece } end
  end
  lastHit = t
  combo = combo % 4 + 1
  local length = swingLength(tool)
  local ok, err = BF.game(function()
    net:RemoteEvent("RegisterAttack"):FireServer(length, combo)
    global.SendHitsToServer(part, list)
  end)
  if not ok then BF.say("hit failed: " .. string.sub(tostring(err), 1, 80)) end
  return ok
end

-- ---------------------------------------------------------------- mobs
local function living(mob)
  local hum = mob:FindFirstChildOfClass("Humanoid")
  local root = mob:FindFirstChild("HumanoidRootPart")
  return hum ~= nil and root ~= nil and hum.Health > 0 and mob.Parent ~= nil
end
BF.living = living
BF.shunned = BF.keep({})      -- mob -> until when it is left alone (it would not die)
-- Where mobs of a name have been seen standing: some (the Marine start's Trainees) have no spawn mark of the
-- game's, and the place a mob was seen is where the next one will be.
BF.seen = {}
function BF.learn(mob)
  local root = mob:FindFirstChild("HumanoidRootPart")
  if not root then return end
  local list = BF.seen[mob.Name]
  if not list then list = {}; BF.seen[mob.Name] = list end
  if #list >= 16 then return end
  local at = root.Position
  for _, point in ipairs(list) do
    if (point - at).Magnitude < 40 then return end
  end
  list[#list + 1] = at
end
-- the living mobs of a name (or any, with nil), nearest to a point first
function BF.mobs(name, from)
  local folder = workspace:FindFirstChild("Enemies")
  local out = {}
  if not folder then return out end
  local t = now()
  for _, mob in ipairs(folder:GetChildren()) do
    if (name == nil or mob.Name == name) and living(mob) and not (BF.shunned[mob] and BF.shunned[mob] > t) then
      out[#out + 1] = mob
      BF.learn(mob)
    end
  end
  if from then
    table.sort(out, function(a, b) return (a.HumanoidRootPart.Position - from).Magnitude < (b.HumanoidRootPart.Position - from).Magnitude end)
  end
  return out
end
-- where a mob of that name comes back to life: the game's own spawn marks
function BF.spawns(name)
  local origin = workspace:FindFirstChild("_WorldOrigin")
  local folder = origin and origin:FindFirstChild("EnemySpawns")
  local out, boss = {}, false
  if not folder then return out, boss end
  local head = name .. " [Lv."
  for _, mark in ipairs(folder:GetChildren()) do
    if mark:IsA("BasePart") and string.sub(mark.Name, 1, #head) == head then
      out[#out + 1] = mark.Position
      if string.find(mark.Name, "[Boss]", 1, true) then boss = true end
    end
  end
  if #out == 0 then
    -- (no mark there: the game's second list, Parts named after the mob at its spawn points, seen 2026-11-13 with 393
    -- of them in the First Sea, the Saber Expert among them)
    local second = S.ReplicatedStorage:FindFirstChild("FortBuilderReplicatedSpawnPositionsFolder")
    for _, mark in ipairs(second and second:GetChildren() or {}) do
      if mark:IsA("BasePart") and mark.Name == name then out[#out + 1] = mark.Position end
    end
  end
  if #out == 0 then
    -- (no mark of the game's at all: where they are standing now, or were last seen)
    BF.mobs(name)
    for _, point in ipairs(BF.seen[name] or {}) do out[#out + 1] = point end
  end
  return out, boss
end
-- Pull the other mobs of the fight onto the first one, while this client owns them: one swing then reaches all.
-- A mob that cannot be pulled (the server owns it, or it broke away further than the pull reaches) is a
-- STRAY: it is remembered, left where it is, and fought on its own once the pack is down.
BF.strays = BF.keep({})
function BF.gather(first, others)
  if not O.gather or type(isnetworkowner) ~= "function" then return 0 end
  local anchor = first:FindFirstChild("HumanoidRootPart")
  if not anchor then return 0 end
  local pulled = 0
  local reach = O.multiReach or 60
  for _, mob in ipairs(others) do
    local root, hum = mob:FindFirstChild("HumanoidRootPart"), mob:FindFirstChildOfClass("Humanoid")
    if root and hum and mob ~= first then
      local gap = (root.Position - anchor.Position).Magnitude
      local ok, mine = pcall(isnetworkowner, root)
      if gap <= (O.gatherRadius or 250) and ok and mine then
        -- (already with the pack: left be, so it is not re-written every frame for nothing)
        if gap > (O.gatherTight or 4) then
          root.CFrame = anchor.CFrame
          root.AssemblyLinearVelocity = Vector3.zero
        end
        if root.CanCollide then root.CanCollide = false end
        BF.strays[mob] = nil
        pulled += 1
      elseif gap > reach then
        BF.strays[mob] = true
      end
    end
  end
  return pulled
end
-- Which mob to fight next, out of a list that is nearest-first. The pack first (in the order the player
-- chose: nearest, weakest or strongest), and only then the strays, nearest first.
function BF.choose(mobs)
  local first = mobs[1]
  if not first then return nil end
  local order = O.targetOrder or "near"
  local best, key, stray
  local anchor = first.HumanoidRootPart.Position
  for _, mob in ipairs(mobs) do
    local hum, root = mob:FindFirstChildOfClass("Humanoid"), mob:FindFirstChild("HumanoidRootPart")
    if hum and root then
      if BF.strays[mob] then
        stray = stray or mob
      elseif order == "near" then
        return mob
      elseif (root.Position - anchor).Magnitude <= (O.multiReach or 60) then
        local health = hum.Health
        if not key or (order == "weak" and health < key) or (order == "strong" and health > key) then best, key = mob, health end
      end
    end
  end
  return best or stray or first, best == nil and stray ~= nil
end
local function fightLoop(mob, ctx, pack, opts, state)
  local hum, root = mob:FindFirstChildOfClass("Humanoid"), mob:FindFirstChild("HumanoidRootPart")
  if not (hum and root) then return "gone" end
  local lowest, lowestAt = hum.Health, now()
  local started = now()
  local swapped = false
  while true do
    if not B.alive or ctx.stop then return "stopped" end
    if not BF.alive() then return "died" end
    if not living(mob) then
      BF.count.kills += 1
      ctx:progress()
      return "dead"
    end
    -- (who is being fought, and as of when: read by parts that act on the same mob, such as skills)
    BF.target, BF.targetAt = mob, now()
    local height = (opts and opts.height) or O.height or 25
    -- The body stays at its height. Only when the player has said it may go down (closeIn) is a mob that will
    -- not lose health fought from closer, and then by the game's own attack from beside it; otherwise it is
    -- simply left alone for a while once the patience is gone.
    local closeIn = O.closeIn == true
    local stale = now() - lowestAt
    if closeIn and stale > 4 then height = math.max(6, height * 0.4) end
    local tool = BF.weapon()
    local own = BF.method(tool) == "own"
    local skillsOnly = BF.method(tool) == "skills"
    if tool and not own and not skillsOnly then state.directTool = tool end
    if closeIn and stale > (O.stuckMob or 10) * 0.5 and not swapped and tool and not own and not skillsOnly then
      -- (half the patience gone with no health off: the game's own attack is tried before the mob is given up on)
      swapped = true
      state.swapped = tool
      BF.otherMethod(tool)
      lowestAt = now()
      stale = 0
    end
    if skillsOnly and stale > 6 and now() - (BF.skillsSaidAt or 0) > 120 then
      -- (said in plain words, now and then: with no skills being cast this weapon takes no health off at all)
      BF.skillsSaidAt = now()
      BF.say(tostring(tool and tool.Name) .. " only hurts with its skills: switch Auto skills on (Mastery), or fight with melee")
    end
    -- (a weapon with only skills waits on their cooldowns: four times the patience before the mob is given up on)
    if stale > (O.stuckMob or 10) * (skillsOnly and 4 or 1) then
      BF.shunned[mob] = now() + 45
      BF.say(mob.Name .. " would not lose health: left alone for 45 s")
      return "stuck"
    end
    -- Low on health (it happens beside a mob, where fruits and guns have to stand): up out of reach until it is back
    local me = BF.hum()
    if me and O.retreat ~= false and me.Health / math.max(me.MaxHealth, 1) < (O.retreatAt or 30) / 100 then
      BF.count.retreats = (BF.count.retreats or 0) + 1
      BF.fly(root.Position + Vector3.new(0, O.retreatHeight or 120, 0), ctx, { direct = true, note = "Low health: resting above" })
      local untilAt = now() + (O.retreatMax or 30)
      while BF.alive() and me.Health / math.max(me.MaxHealth, 1) < (O.retreatBack or 70) / 100 and now() < untilAt and not ctx.stop do
        ctx:beat("Low health: resting above")
        task.wait(0.2)
      end
      lowestAt = now()
    end
    local above = root.Position + Vector3.new(0, height, 0)
    -- (the game's own attack has the weapon's real reach: stood beside the mob, facing it)
    if own then above = root.Position + Vector3.new(O.ownReach or 3.5, 0.5, 0) end
    local mine = BF.root()
    if mine and (mine.Position - above).Magnitude > 40 then
      -- (too far to be put there in one frame: flown, so the server sees a trip and not a jump)
      local ok, why = BF.fly(above, ctx, { direct = (mine.Position - above).Magnitude < 350, note = "To " .. mob.Name })
      if not ok then return why == "dead" and "died" or (why == "stopped" and "stopped" or "stuck") end
      lowestAt = now()
    else
      BF.holdAt(above, root.Position)
    end
    local others = pack and pack() or {}
    BF.gather(mob, others)
    BF.hit(mob, O.multi and others or nil)
    if hum.Health < lowest - 0.01 then
      lowest, lowestAt = hum.Health, now()
      if state.swapped then state.ownHurt = true elseif tool and not own and not skillsOnly then state.directHurt = tool end
    end
    ctx:beat(string.format("Fighting %s  %d%%", mob.Name, math.floor(hum.Health / math.max(hum.MaxHealth, 1) * 100 + 0.5)))
    if now() - started > 240 then BF.shunned[mob] = now() + 60; return "stuck" end
    task.wait(0.05)
  end
end
-- Fight one mob to the end from above it. Returns "dead", or why not ("gone", "stuck", "stopped", "died").
function BF.fight(mob, ctx, pack, opts)
  local state = {}
  local result = fightLoop(mob, ctx, pack, opts, state)
  local tool = state.swapped
  if tool then
    -- The swap to the game's own attack was for this mob. It stays only when the direct way has now failed on
    -- three mobs running AND the game's own way did take health off: one odd mob no longer leaves every later
    -- fight slow, close and single (the own way hits one mob, at half the pace, from beside it).
    local fails = (directFails[tool] or 0) + 1
    directFails[tool] = fails
    if not (fails >= 3 and state.ownHurt) then methods[tool] = nil end
  elseif state.directHurt then
    directFails[state.directHurt] = 0
  elseif result == "stuck" and state.directTool then
    -- (sent directly from above and nothing came off this mob. Melee and swords are proven: the mob is the odd
    -- one, and it has been set aside. Any other weapon that fails on three mobs running has no hit of its own
    -- that lands from up here: it fights with its skills from now on, and says so)
    local direct = state.directTool
    local fails = (directFails[direct] or 0) + 1
    directFails[direct] = fails
    local kind = kindOf(direct)
    if fails >= 3 and kind ~= "Melee" and kind ~= "Sword" then
      methods[direct], directFails[direct] = "skills", 0
      BF.say(direct.Name .. ": its hits do not land from above. It fights with its skills from now on.")
    end
  end
  return result
end

-- ---------------------------------------------------------------- the quest on screen
-- The quest in hand, as the game's own guide holds it (GuideModule.GuideData.Data.QuestData), or nil:
-- { InternalQuestName, Info = { Name, Task, Reward, LevelReq }, Progress = { [mob] = killed }, TimeStarted, UID }.
-- (The old Main.Quest frame is still in the tree, hidden, with a stale text: it is not read.)
function BF.quest()
  local guide = BF.mod("GuideModule", "GuideData")
  local data = guide and type(guide.Data) == "table" and guide.Data.QuestData
  if type(data) ~= "table" or type(data.Info) ~= "table" then return nil end
  return data
end

-- ---------------------------------------------------------------- jobs and the director
-- job = { id, label, priority, want = fn() -> bool, run = fn(ctx), quiet = seconds a job may say nothing }
function BF.job(spec)
  spec.fails, spec.restAt = 0, 0
  BF.jobs[#BF.jobs + 1] = spec
  table.sort(BF.jobs, function(a, b) return (a.priority or 0) > (b.priority or 0) end)
  return spec
end
local Ctx = {}
Ctx.__index = Ctx
function Ctx:beat(note)
  self.beatAt = now()
  if note then BF.status = note end
end
function Ctx:progress()
  self.beatAt, self.progressAt = now(), now()
  self.job.fails = 0
end
function Ctx:sleep(seconds, note)
  local untilAt = now() + seconds
  while now() < untilAt and not self.stop and B.alive do
    self:beat(note)
    task.wait(0.1)
  end
  return not self.stop
end
-- wait for a living body (after a death, a reset, a teleport): true once it stands
function Ctx:body(seconds)
  local untilAt = now() + (seconds or 30)
  local waited = false
  while not BF.alive() do
    if self.stop or not B.alive or now() > untilAt then return false end
    waited = true
    self:beat("Waiting for the body")
    task.wait(0.2)
  end
  if waited then
    BF.count.deaths += 1
    release()
    self:sleep(1.2, "Back on its feet")
  end
  return true
end
-- Drop the quest in hand, unless it is a story's (those are never dropped by a farm or by a repair). Sent
-- without waiting: neither the director nor the frame loop ever stands still for the server.
function BF.dropQuest()
  local held = BF.quest()
  if not held or BF.keepQuests[held.InternalQuestName] then return false end
  task.spawn(BF.invoke, 4, "AbandonQuest")
  return true
end
local current           -- { job, ctx, thread }
local function stop(reason)
  if not current then return end
  current.ctx.stop = true
  local thread = current.thread
  current = nil
  release()
  if thread and coroutine.status(thread) ~= "dead" then pcall(task.cancel, thread) end
  if reason then BF.say(reason) end
  BF.status = "Idle"
end
BF.stop = stop
-- Putting a job right. Each time in a row the step is a bigger one; a job that keeps failing is rested, not looped.
local function repair(job, why)
  job.fails += 1
  BF.count.repairs += 1
  local step = job.fails
  release()
  local gentle = job.gentle
  if gentle == nil then gentle = not BF.farmJobs[job.id] end
  if gentle then
    -- (not a farm: a trip, a chest, a chain, a boss, something done beside the player's own hands. It is rested,
    -- longer each time, and nothing else is touched: no tool put away, no quest dropped, no body started again)
    local rest = math.min(300, 5 * step * step)
    BF.say(string.format("%s: %s. Resting it %d s.", job.label, why, rest))
    job.restAt = now() + rest
  elseif step == 1 then
    BF.say(string.format("%s: %s. Standing still and arming again.", job.label, why))
    local hum = BF.hum()
    if hum then pcall(function() hum:UnequipTools() end) end
    job.restAt = now() + 1
  elseif step == 2 then
    job.restAt = now() + 2
    local dropped = BF.dropQuest()
    BF.say(string.format("%s: %s again. %s", job.label, why, dropped and "Dropping the quest and the target." or "Letting go of the target."))
  elseif step == 3 then
    BF.say(string.format("%s: %s a third time. Starting the body again.", job.label, why))
    local hum = BF.hum()
    if hum and O.reset ~= false then pcall(function() hum.Health = 0 end) end
    job.restAt = now() + 8
  else
    local rest = math.min(300, 30 * (step - 3))
    BF.say(string.format("%s: %s, %d times in a row. Resting it %d s.", job.label, why, step, rest))
    job.restAt = now() + rest
  end
  if job.repair then B.try("bloxfruits.repair", job.repair, step, why) end
end
local function direct()
  local t = now()
  -- the job that wants the body most
  local pick
  local asked = {}
  local function wants(job)
    local known = asked[job]
    if known == nil then
      local ok, value = pcall(job.want)
      known = (ok and value) and true or false
      asked[job] = known
    end
    return known
  end
  -- A job of opportunity, such as a chest on the way, may take the body from a FARM, which loses nothing by it;
  -- never while a quest chain, a trip, a raid or a boss fight wants it, running or resting after a repair: it
  -- would only keep that one from ever getting there.
  -- (so: whose body would it be with no job of opportunity about? The first that wants it, resting or not. If
  -- that is a farm, a chest may cut in; if it is anything else, none may.)
  local serious = false
  for _, job in ipairs(BF.jobs) do
    if not BF.casual[job.id] and wants(job) then
      serious = not BF.farmJobs[job.id]
      break
    end
  end
  -- (nor into a farm's long flight to its next island: seen live 2026-11-13, a 12,000-stud trip cut into by one
  -- chest after another, each a climb down and up again. Chests are for between fights, once it has arrived.)
  if current and BF.farmJobs[current.job.id] and pilot.mode == "fly" and pilot.long then serious = true end
  for _, job in ipairs(BF.jobs) do
    if t >= job.restAt and not (serious and BF.casual[job.id]) and wants(job) then pick = job; break end
  end
  if current then
    local job, ctx, thread = current.job, current.ctx, current.thread
    if pick ~= job and not (pick == nil and t < job.restAt) then
      stop(pick and (job.label .. " gives way to " .. pick.label) or (job.label .. " is off"))
    elseif coroutine.status(thread) == "dead" then
      local why = ctx.error and ("it broke: " .. string.sub(tostring(ctx.error), 1, 120)) or "it ended by itself"
      current = nil
      repair(job, why)
    elseif t - ctx.beatAt > (job.quiet or 20) then
      stop()
      repair(job, "it went silent")
    elseif t - ctx.progressAt > (job.patience or 180) then
      stop()
      repair(job, string.format("no progress for %d s", job.patience or 180))
    end
  end
  if not current and pick and t >= pick.restAt then
    local ctx = setmetatable({ job = pick, beatAt = t, progressAt = t, stop = false }, Ctx)
    local thread = task.spawn(function()
      local ok, err = xpcall(pick.run, function(e) return tostring(e) .. "\n" .. debug.traceback("", 2) end, ctx)
      restore()
      if not ok and not ctx.stop then
        ctx.error = err
        B.fault("bloxfruits." .. pick.id, err)
      end
    end)
    current = { job = pick, ctx = ctx, thread = thread }
    BF.say(pick.label .. " has the body")
  end
end
function BF.running() return current and current.job or nil end
-- Everything off, by one hand: the planner first (or it would switch the farms straight back on), then every
-- job's own switch, then the switches parts have named that are not a job's (BF.offToo), and the body let go.
BF.offToo = {}
function BF.stopAll(reason)
  local function off(id)
    local ok, value = pcall(Config.get, id)
    if ok and value == true then pcall(Config.set, id, false) end
  end
  off("bloxfruits.autopilot")
  for _, job in ipairs(BF.jobs) do
    if job.switch then off(job.switch) end
  end
  for _, id in ipairs(BF.offToo) do off(id) end
  stop(reason or "Stopped by hand")
end
-- the running job's own context (for a helper deep in a part that has to fly and has not been handed it)
function BF.ctx() return current and current.ctx or nil end
-- An island's map is in the workspace only while the body is near it (measured 2026-11-13: Map.Desert was not there
-- from Skylands). Fly to the island and wait for it. `island` is the folder's name under workspace.Map; the place to
-- fly to is the game's own Location of that name (or of the name given as `place`).
function BF.nearIsland(ctx, island, place)
  local map = workspace:FindFirstChild("Map")
  if map and map:FindFirstChild(island) then return true end
  local origin = workspace:FindFirstChild("_WorldOrigin")
  local places = origin and origin:FindFirstChild("Locations")
  local root = BF.root()
  local best, gap
  for _, part in ipairs(places and places:GetChildren() or {}) do
    if part:IsA("BasePart") and (part.Name == (place or island) or string.find(part.Name, place or island, 1, true)) then
      local away = root and (part.Position - root.Position).Magnitude or 0
      if not gap or away < gap then best, gap = part, away end
    end
  end
  if not best then return false, "no place called " .. tostring(place or island) .. " in this sea" end
  local ok, why = BF.fly(best.Position + Vector3.new(0, 60, 0), ctx, { note = "To " .. tostring(place or island) })
  if not ok then return false, why end
  local untilAt = now() + 15
  while now() < untilAt and B.alive and not (ctx and ctx.stop) do
    map = workspace:FindFirstChild("Map")
    if map and map:FindFirstChild(island) then return true end
    if ctx then ctx:beat("Waiting for " .. island .. " to load") end
    task.wait(0.25)
  end
  return false, island .. " did not load"
end

-- ---------------------------------------------------------------- where an NPC is
-- An NPC's model is in the workspace only near its island (measured 2026-11-13: the Rich Man was nowhere from the
-- Frozen Village). So every NPC seen is remembered, and one never seen is looked for: island by island, nearest
-- first, until its model turns up. What was learned on the way is kept for the rest of the session.
BF.npcSeen = {}
-- (kept on disk, a file a sea: the next session knows where everyone is before it has moved)
local function npcFile() return "BasedHub/bloxfruits/npcs_sea" .. tostring(BF.sea()) .. ".json" end
local npcDirty, npcSavedAt = false, 0
local function loadNpcs()
  if type(isfile) ~= "function" or type(readfile) ~= "function" then return end
  pcall(function()
    if not isfile(npcFile()) then return end
    local data = S.HttpService:JSONDecode(readfile(npcFile()))
    for name, at in pairs(type(data) == "table" and data or {}) do
      if type(at) == "table" and tonumber(at[1]) and BF.npcSeen[name] == nil then BF.npcSeen[name] = Vector3.new(at[1], at[2], at[3]) end
    end
  end)
end
local function saveNpcs()
  if not npcDirty or now() - npcSavedAt < 20 or type(writefile) ~= "function" then return end
  npcDirty, npcSavedAt = false, now()
  pcall(function()
    local out = {}
    for name, at in pairs(BF.npcSeen) do out[name] = { math.floor(at.X + 0.5), math.floor(at.Y + 0.5), math.floor(at.Z + 0.5) } end
    if type(makefolder) == "function" then
      if not isfolder("BasedHub") then makefolder("BasedHub") end
      if not isfolder("BasedHub/bloxfruits") then makefolder("BasedHub/bloxfruits") end
    end
    writefile(npcFile(), S.HttpService:JSONEncode(out))
  end)
end
local function noteNpcs()
  for _, holder in ipairs({ workspace:FindFirstChild("NPCs"), S.ReplicatedStorage:FindFirstChild("NPCs") }) do
    for _, model in ipairs(holder and holder:GetChildren() or {}) do
      if model:IsA("Model") then
        local ok, pivot = pcall(model.GetPivot, model)
        if ok and pivot and pivot.Position.Magnitude > 1 then
          local known = BF.npcSeen[model.Name]
          if not known or (known - pivot.Position).Magnitude > 5 then npcDirty = true end
          BF.npcSeen[model.Name] = pivot.Position
        end
      end
    end
  end
  saveNpcs()
end
BF.noteNpcs = noteNpcs
function BF.findNpc(ctx, name, first)
  noteNpcs()
  if BF.npcSeen[name] then return BF.npcSeen[name] end
  local origin = workspace:FindFirstChild("_WorldOrigin")
  local places = origin and origin:FindFirstChild("Locations")
  local root = BF.root()
  if not (places and root) then return nil end
  local list, far = {}, {}
  local from = root.Position
  for _, part in ipairs(places:GetChildren()) do
    if part:IsA("BasePart") and part.Name ~= "Sea" then
      -- (as the body would travel there: an island behind a gate is as near as the gate)
      local trip = BF.trip(from, part.Position)
      if trip <= (O.maxTrip or 30000) then
        list[#list + 1] = part
        far[part] = trip
      end
    end
  end
  -- (the island named as a hint first, then the nearest)
  table.sort(list, function(a, b)
    local ha, hb = first ~= nil and a.Name == first, first ~= nil and b.Name == first
    if ha ~= hb then return ha end
    return far[a] < far[b]
  end)
  BF.say(string.format("Looking for %s: %d islands to look at", name, #list))
  -- An NPC's model only appears within a couple of hundred studs of it (measured: not from 290). So each island is
  -- looked at from its middle and from four points round it.
  local ring = O.npcRing or 220
  local spots = { Vector3.new(0, 60, 0), Vector3.new(ring, 40, 0), Vector3.new(0, 40, ring), Vector3.new(-ring, 40, 0), Vector3.new(0, 40, -ring) }
  for index, part in ipairs(list) do
    for _, offset in ipairs(spots) do
      if (ctx and ctx.stop) or not B.alive then return nil end
      local how = { direct = offset.X ~= 0 or offset.Z ~= 0, note = string.format("Looking for %s (%d of %d)", name, index, #list) }
      local ok, why = BF.fly(part.Position + offset, ctx, how)
      if not ok and (why == "dead" or why == "no body") then
        -- (died on the way: the look goes on from the new body, not past every island left in one frame)
        local untilAt = now() + 40
        while not BF.alive() and now() < untilAt and B.alive and not (ctx and ctx.stop) do
          if ctx then ctx:beat("Waiting for the body") end
          task.wait(0.2)
        end
        if not BF.alive() then return nil end
        BF.count.deaths += 1
        task.wait(1.2)
        ok = BF.fly(part.Position + offset, ctx, how)
      end
      if ok then
        local untilAt = now() + 1.2
        while now() < untilAt and not (ctx and ctx.stop) do
          noteNpcs()
          if BF.npcSeen[name] then
            BF.say(name .. " found at " .. part.Name)
            return BF.npcSeen[name]
          end
          if ctx then ctx:beat("Looking for " .. name) end
          task.wait(0.2)
        end
      end
    end
  end
  BF.say(name .. " was not found on any island within reach")
  return nil
end

-- ---------------------------------------------------------------- start
local function start(hub)
  local defaults = { speed = 250, cruise = 60, lagback = 40, height = 25, pace = 0.34, weapon = "melee", weaponName = "", gather = false, gatherRadius = 250,
    gatherTight = 4, multi = false, multiMax = 8, multiReach = 60, targetOrder = "near", stuckMob = 10, reset = true, ownReach = 3.5, closeIn = false, gates = true, gateZone = 9000, retreat = true, retreatAt = 30, retreatBack = 70,
    retreatHeight = 120, retreatMax = 30 }
  local map = {}
  for key, value in pairs(defaults) do
    Config.define("bloxfruits." .. key, value)
    map[key] = "bloxfruits." .. key
  end
  BF.map = map
  for _, part in ipairs(BF.parts) do
    for key, value in pairs(part.defaults or {}) do
      Config.define("bloxfruits." .. key, value)
      map[key] = "bloxfruits." .. key
    end
  end
  setmetatable(O, { __index = Config.mirror(map) })
  BF.status = "Idle"
  B.connect(S.RunService.Heartbeat, function(dt)
    local ok, err = pcall(pilotStep, dt)
    if not ok then B.fault("bloxfruits.pilot", err); release() end
  end, "bloxfruits.pilot")
  B.connect(S.RunService.Stepped, function() pcall(pilotClip) end, "bloxfruits.clip")
  Motion.every(function()
    local ok, err = pcall(direct)
    if not ok then B.fault("bloxfruits.director", err) end
  end, 4, "bloxfruits.director")
  B.own(function() stop(); release() end)
  pcall(loadNpcs)
  Motion.every(function() pcall(noteNpcs) end, 0.5, "bloxfruits.npcs")
  Motion.every(function() pcall(sweep) end, 0.05, "bloxfruits.sweep")
  -- (the sea, from the game's own Util.Realm: it asks its server once and remembers)
  task.spawn(function()
    local realm = BF.mod("Util", "Realm")
    if type(realm) ~= "table" or type(realm.safeGetCurrentSeaAsync) ~= "function" then return end
    local ok, name = BF.game(realm.safeGetCurrentSeaAsync)
    local sea = ok and tonumber(string.match(tostring(name), "^Sea(%d)$"))
    if sea then
      if sea ~= BF.sea() then BF.say("This place is the game's Sea " .. sea) end
      BF.seaAsked = sea
    end
  end)
  for _, part in ipairs(BF.parts) do
    if part.start then B.try("bloxfruits." .. part.id, part.start, hub) end
  end
  BF.started = true
end

-- ---------------------------------------------------------------- the tabs
local function extend(kind, page)
  for _, part in ipairs(BF.parts) do
    if part[kind] then B.try("bloxfruits." .. part.id .. "." .. kind, part[kind], page) end
  end
end
local function has(kind)
  for _, part in ipairs(BF.parts) do
    if part[kind] then return true end
  end
  return false
end
function BF.statusLine()
  local job = current and current.job
  return (job and (job.label .. ":  ") or "") .. tostring(BF.status or "Idle")
end
function BF.countLine()
  local c = BF.count
  return string.format("Level %d  ·  %d kills  ·  %d quests  ·  %d repairs  ·  %d pull-backs  ·  %d deaths", BF.level(), c.kills, c.quests, c.repairs, c.lagbacks, c.deaths)
end
local function farmPage(hub)
  hub:page({ id = "farm", title = "Farm", icon = "repeat", build = function(page)
    local live = page:section({ title = "Right now", icon = "activity", full = true })
    local line = live:note({ icon = "activity", text = BF.statusLine() })
    local counts = live:note({ icon = "gauge", text = BF.countLine() })
    local last = live:note({ icon = "history", text = "" })
    live:button({ id = "bloxfruits.stopAll", label = "Stop everything", desc = "Every farm switch off. The body is let go where it is.", text = "Stop", run = function()
      BF.stopAll("Stopped by hand")
    end })
    Motion.every(function()
      if not (line.frame.Parent and Window.anyOpen()) then return end
      line.set(BF.statusLine())
      counts.set(BF.countLine())
      local events = BF.events
      last.set(events[#events] or "Nothing yet.")
    end, 3, "bloxfruits.status")
    extend("farm", page)
  end })
end
local function fightPage(hub)
  hub:page({ id = "fight", title = "Fighting", icon = "swords", build = function(page)
    local arm = page:section({ title = "Weapon", icon = "sword" })
    arm:segmented({ id = "bloxfruits.weapon", label = "Fight with", options = { { "melee", "Melee" }, { "sword", "Sword" }, { "fruit", "Fruit" }, { "gun", "Gun" } }, width = 260 })
    arm:input({ id = "bloxfruits.weaponName", label = "Or this one by name", placeholder = "e.g. Katana" })
    local hits = page:section({ title = "Hits", icon = "zap" })
    hits:slider({ id = "bloxfruits.pace", label = "Time between hits", tip = "The server takes about three a second: 0.34.", min = 0.2, max = 1.2, step = 0.02, default = 0.34, suffix = " s" })
    hits:toggle({ id = "bloxfruits.closeIn", label = "May go down beside a mob", desc = "Off: the body always stays above the mobs.", default = false, bindable = false, children = function(sub)
      sub:slider({ id = "bloxfruits.ownReach", label = "How close", tip = "Only for a mob that hits from above do not hurt.", min = 2, max = 12, step = 0.5, default = 3.5, suffix = " st" })
    end })
    hits:slider({ id = "bloxfruits.height", label = "Height above the mob", tip = "They cannot reach you up there. Hits land from 60 at least.", min = 0, max = 60, step = 1, default = 25, suffix = " st" })
    hits:toggle({ id = "bloxfruits.gather", label = "Bring mobs together", desc = "Pulls the pack onto the one being hit.", default = false, children = function(sub)
      sub:slider({ id = "bloxfruits.gatherRadius", label = "From within", min = 50, max = 350, step = 10, default = 250, suffix = " st" })
      sub:slider({ id = "bloxfruits.gatherTight", label = "How tight the stack is", tip = "A mob this close to the one being hit is left where it is.", min = 1, max = 20, step = 1, default = 4,
        suffix = " st" })
      sub:toggle({ id = "bloxfruits.multi", label = "One swing hits them all", desc = "Sends the whole pack with each hit.", default = false, bindable = false })
      sub:slider({ id = "bloxfruits.multiMax", label = "Most mobs in one swing", min = 1, max = 20, step = 1, default = 8 })
      sub:slider({ id = "bloxfruits.multiReach", label = "A swing reaches", tip = "Mobs further than this from the one being hit are strays.", min = 10, max = 120, step = 5, default = 60,
        suffix = " st" })
    end })
    hits:dropdown({ id = "bloxfruits.targetOrder", label = "Fight first", options = { { "near", "The nearest" }, { "weak", "The weakest of the pack" }, { "strong", "The strongest of the pack" } } })
    hits:note({ icon = "info", text = "A mob that breaks away from the stack is fought on its own as soon as the pack is down." })
    local move = page:section({ title = "Travel", icon = "navigation", column = 2 })
    move:slider({ id = "bloxfruits.speed", label = "Flight speed", tip = "Slower is pulled back less.", min = 80, max = 400, step = 10, default = 250, suffix = " st/s" })
    move:toggle({ id = "bloxfruits.gates", label = "Use the game's portals", desc = "The whirlpool to the Underwater City and back.", default = true, bindable = false })
    move:slider({ id = "bloxfruits.cruise", label = "Cruise height", tip = "How far above the islands a long trip flies.", min = 20, max = 300, step = 10, default = 60, suffix = " st" })
    local mend = page:section({ title = "When something breaks", icon = "wrench", column = 2 })
    mend:slider({ id = "bloxfruits.stuckMob", label = "Give up on a mob after", tip = "Seconds without its health going down.", min = 4, max = 30, step = 1, default = 10, suffix = " s" })
    mend:toggle({ id = "bloxfruits.retreat", label = "Rest above when health is low", desc = "Lifts out of reach until health is back.", default = true, children = function(sub)
      sub:slider({ id = "bloxfruits.retreatAt", label = "Leave at", min = 5, max = 80, step = 5, default = 30, suffix = "%" })
      sub:slider({ id = "bloxfruits.retreatBack", label = "Come back at", min = 20, max = 100, step = 5, default = 70, suffix = "%" })
      sub:slider({ id = "bloxfruits.retreatHeight", label = "How high", min = 40, max = 400, step = 10, default = 120, suffix = " st" })
      sub:slider({ id = "bloxfruits.retreatMax", label = "For at most", min = 5, max = 120, step = 5, default = 30, suffix = " s" })
    end })
    mend:toggle({ id = "bloxfruits.reset", label = "May start the body again", desc = "The third repair in a row resets the character.", default = true, bindable = false })
    mend:note({ icon = "info", text = "A job that stalls is put right in steps: re-arm, drop the quest, reset, then rest. Never the same loop twice." })
    extend("fight", page)
  end })
end

B.game({
  id = "bloxfruits",
  name = "Blox Fruits",
  tagline = "One body. Every grind.",
  universes = { 994732206 },
  places = { 2753915549, 4442272183, 7449423635 },
  icon = "swords",
  -- (only Visuals is kept from Universal: its Combat, Movement, Players and Server tabs are not started in this game)
  universal = { "visuals" },
  tabs = function(hub)
    start(hub)
    farmPage(hub)
    -- (a tab is there once any part has something for it: a part adds its cards with part[<tab id>] = function(page))
    for _, tab in ipairs(BF.TABS) do
      if tab.id == "fight" then
        fightPage(hub)
      elseif has(tab.id) then
        hub:page({ id = tab.id, title = tab.title, icon = tab.icon, build = function(page) extend(tab.id, page) end })
      end
    end
  end,
})
end
do -- bloxfruits_auto.lua
-- ============================================================================
--  Blox Fruits     autopilot: one switch for the whole account, and the books
--
--  This part sends NOTHING to the server and never moves the body. It reads
--  the game (Player.Data, a few attributes, what lies in workspace) and the
--  other parts' own tables on BF, and it only sets the hub's own settings.
--  Written offline on 2026-11-13 and NEVER RUN LIVE: all of it is unproven.
--
--   * Autopilot is a planner: a table of stages, each a plain list of
--     { setting, value } and a condition. Every setting it sets is set
--     QUIETLY (Config.set(id, value, true): never saved as the player's own
--     choice) and is put back to exactly what the player had when Autopilot
--     goes off or the hub unloads. A setting the player (or a part) changes
--     while Autopilot holds it is theirs from then on: never touched again
--     until Autopilot is switched off and on.
--   * By the rule in NOTES.md it switches on by itself only what was run live
--     (Auto level, auto stats, Keep Buso on, buying abilities, fruit pick-up
--     and store, chests between farming, Bring mobs, Farm every boss with its
--     quest). The sea chains were never run live: they are an option, off.
--   * Experience is counted from Player.Data.Exp and Level with the game's
--     own EXPFunction (ReplicatedStorage/EXPFunction.luau:2-6: the experience
--     a level needs; the bar shows Exp out of EXPFunction(Level),
--     React/Components/HUD/ExpAndLevel/ExpBar.luau:116-132), so a level-up
--     does not lose what was earned.
--   * 2x EXP: the LocalPlayer attribute ExpBoost is SECONDS left as of the
--     attribute ExpBoostTick, a tick() (ExpBar.luau:71-77; both set by
--     PlayerScripts/Comm.luau:76-82).
-- ============================================================================
local B = B or ...
local S, util, Config, Window, Motion = B.S, B.util, B.Config, B.Window, B.Motion
local BF = B.BloxFruits
local O = BF.O
local fs = B.fs
local function now() return os.clock() end
local function id(key) return "bloxfruits." .. key end

-- this part's own settings (also: the keys a setup never carries)
local DEFAULTS = { autopilot = false, autoUse = { "stats", "haki", "abilities", "fruits", "chests", "seas" }, autoNoSpend = false, autoNoSea = false,
  autoStop = false, autoStopLevel = 0, autoStopBeli = 0, autoStopFrags = 0, autoStopMinutes = 0, autoStopRarities = {},
  setupPick = "b:Leveller", setupName = "", learnKeep = false }

-- ---------------------------------------------------------------- small things
local function same(a, b)
  if type(a) ~= "table" or type(b) ~= "table" then return a == b end
  for k, v in pairs(a) do if not same(v, b[k]) then return false end end
  for k in pairs(b) do if a[k] == nil then return false end end
  return true
end
local function short(n)
  n = tonumber(n) or 0
  local sign = n < 0 and "-" or ""
  n = math.abs(n)
  if n >= 1e9 then return sign .. string.format("%.2fB", n / 1e9) end
  if n >= 1e6 then return sign .. string.format("%.2fM", n / 1e6) end
  if n >= 1e4 then return sign .. string.format("%.1fk", n / 1e3) end
  return sign .. util.comma(n)
end
local function clock(seconds)
  seconds = math.max(0, math.floor(seconds))
  if seconds >= 3600 then return string.format("%dh %02dm", seconds // 3600, (seconds % 3600) // 60) end
  return string.format("%dm %02ds", seconds // 60, seconds % 60)
end
local SEA_NAMES = { "First", "Second", "Third" }
local LABELS = {
  level = "Auto level", takeQuest = "Take the quest", stats = "Auto stats", haki = "Keep Buso on", autoAbilities = "Buy abilities",
  fruitCollect = "Fruit pick-up", fruitStore = "Fruit store", chestFarm = "Chests", chestMode = "Chest mode", gather = "Bring mobs",
  multi = "One swing hits all", bossAll = "Every boss", bossQuest = "Boss quests", questSea2 = "Second Sea chain", questSea3 = "Third Sea chain",
  questFirst = "Chains before levelling", fruitEsp = "Fruit radar", fruitNotify = "Fruit toasts", espRadarBoss = "Boss toasts", skipBoss = "Skip boss quests",
  speed = "Flight speed", reset = "May reset",
}
local function label(key) return LABELS[key] or key end

-- ---------------------------------------------------------------- reading the account
local function hasData() return B.LP:FindFirstChild("Data") ~= nil end
-- the body owns Buso when it carries the tag "Buso" (StarterCharacterScripts/Aura; NOTES.md, measured)
local function hasBuso()
  local character, has = BF.char(), false
  if character then pcall(function() has = character:HasTag("Buso") end) end
  return has
end
-- the player attribute LevelCap (NOTES.md: 2800, read live)
local function levelCap()
  local cap = tonumber(B.LP:GetAttribute("LevelCap"))
  return cap and cap > 0 and cap or 2800
end
-- "Sand-Sand" -> "Sand" with the game's own Modules.Asset.GetFruitName (as bloxfruits_fruit.lua display() does)
local fruitNames = {}
local function fruitName(key)
  if type(key) ~= "string" or key == "" then return "none" end
  if fruitNames[key] then return fruitNames[key] end
  local fn, ok, name = BF.mod("Modules", "Asset", "GetFruitName"), false, nil
  if type(fn) == "function" then ok, name = BF.game(fn, key) end
  name = (ok and type(name) == "string") and name or (string.match(key, "^(.-)%-") or key)
  fruitNames[key] = name
  return name
end
-- FruitInfo.DATA[key].Rarity = { Value, Name } (FruitInfo.luau:94, :125; read the same way by bloxfruits_fruit.lua rarityOf)
local function rarityName(key)
  local info = BF.mod("FruitInfo")
  local data = type(info) == "table" and type(info.DATA) == "table" and type(key) == "string" and info.DATA[key]
  local rarity = type(data) == "table" and data.Rarity
  return type(rarity) == "table" and rarity.Name and tostring(rarity.Name) or nil
end
local function account()
  return { level = BF.level(), sea = BF.sea(), beli = tonumber(BF.data("Beli")) or 0, frags = tonumber(BF.data("Fragments")) or 0,
    fruit = tostring(BF.data("DevilFruit") or ""), buso = hasBuso(), cap = levelCap() }
end
-- Bosses alive: IsBoss bodies (not raid bosses) near, in workspace.Enemies, or parked directly under ReplicatedStorage
-- (Controllers/BossCutsceneController.luau:30; the same look as bloxfruits_boss.lua scan()). Kept 4 s.
local bossView, bossViewAt = {}, -1e9
local function bossesAlive()
  if now() - bossViewAt < 4 then return bossView end
  local out, seen = {}, {}
  local function look(model)
    if not model:IsA("Model") or model:GetAttribute("IsBoss") ~= true or model:GetAttribute("RaidBoss") or seen[model.Name] then return end
    local hum = model:FindFirstChildOfClass("Humanoid")
    if not (hum and hum.Health > 0) then return end
    seen[model.Name] = true
    out[#out + 1] = { name = model.Name, level = tonumber(model:GetAttribute("Level")) or 0 }
  end
  local folder = workspace:FindFirstChild("Enemies")
  for _, model in ipairs(folder and folder:GetChildren() or {}) do look(model) end
  for _, model in ipairs(S.ReplicatedStorage:GetChildren()) do look(model) end
  table.sort(out, function(a, b) return a.level < b.level end)
  bossView, bossViewAt = out, now()
  return out
end
-- a boss this body may fight is up: alive and no more levels above it than the boss part allows (bossMargin, its own rule).
-- Held true a minute after the last one, so "Every boss" is not switched on and off with each kill.
local bossSeenAt = -1e9
local function bossesNear(st)
  for _, boss in ipairs(bossesAlive()) do
    if boss.level <= st.level + (tonumber(O.bossMargin) or 0) then bossSeenAt = now(); return true end
  end
  return now() - bossSeenAt < 60
end
-- the fruits in the bag (a Tool with an EatRemote: bloxfruits_fruit.lua bagFruits)
local function bagFruits()
  if BF.fruit and type(BF.fruit.bag) == "function" then
    local ok, list = pcall(BF.fruit.bag)
    if ok and type(list) == "table" then return list end
  end
  local out = {}
  for _, holder in ipairs({ BF.char(), B.LP:FindFirstChild("Backpack") }) do
    for _, tool in ipairs(holder and holder:GetChildren() or {}) do
      if tool:IsA("Tool") and tool:FindFirstChild("EatRemote", true) then out[#out + 1] = tool end
    end
  end
  return out
end

-- ============================================================================ 1. the planner
local function uses(name)
  local list = O.autoUse
  return type(list) == "table" and table.find(list, name) ~= nil
end
-- What every stage keeps on. `use` = only when ticked under "It may use"; `spends` = never with "Never spend Beli";
-- `when` = only while that is true. Only features run live are here without a `use` the player must tick.
local BASE = {
  { "level", true },                                      -- Auto level (bloxfruits_farm.lua; run live 1 -> 113)
  { "takeQuest", true },
  { "stats", true, use = "stats" },                       -- auto stats, the player's own plan (bloxfruits_player.lua)
  { "haki", true, use = "haki" },                         -- Keep Buso on: does nothing until the body owns it
  { "autoAbilities", true, use = "abilities", spends = true },   -- Geppo, Buso, Soru, Ken as Beli allows (bloxfruits_world.lua)
  { "fruitCollect", true, use = "fruits" },               -- fruit pick-up and store (bloxfruits_fruit.lua; never eats)
  { "fruitStore", true, use = "fruits" },
  { "chestFarm", true, use = "chests" },                  -- chests between farming (bloxfruits_loot.lua; "only" was not run live)
  { "chestMode", "between", use = "chests" },
  { "gather", true, use = "bring" },                      -- Bring mobs + One swing hits them all (the engine; run live)
  { "multi", true, use = "bring" },
  { "bossAll", true, use = "bosses", when = bossesNear }, -- Farm every boss with its quest (bloxfruits_boss.lua; run live on the Yeti)
  { "bossQuest", true, use = "bosses", when = bossesNear },
}
local function with(extra)
  local rows = table.clone(BASE)
  for _, row in ipairs(extra) do rows[#rows + 1] = row end
  return rows
end
-- The stages, first match wins. Add one by adding a row: { id, label, when(st), why(st), rows }.
local STAGES = {
  -- (the chain itself is started by "Go to the next sea by itself", which tries again ten minutes after a chain has
  --  stopped itself: a switch the chain turned off is then never mistaken for the player's own hand)
  { id = "sea2", label = "Second Sea chain", rows = with({ { "questNextSea", true }, { "questFirst", true } }),
    when = function(st) return st.sea == 1 and st.level >= 700 and uses("seas") and not O.autoNoSea end,
    why = function(st) return string.format("Level %d in the First Sea: the Second Sea chain goes before levelling.", st.level) end },
  { id = "sea3", label = "Third Sea chain", rows = with({ { "questNextSea", true }, { "questFirst", true } }),
    when = function(st) return st.sea == 2 and st.level >= 1500 and uses("seas") and not O.autoNoSea end,
    why = function(st) return string.format("Level %d in the Second Sea: the Third Sea chain goes before levelling.", st.level) end },
  { id = "cap", label = "At the level cap", rows = BASE,
    when = function(st) return st.level >= st.cap end,
    why = function(st) return string.format("Level %d is the cap: quests for Beli, fruits and chests.", st.level) end },
  { id = "level", label = "Levelling", rows = BASE,
    when = function() return true end,
    why = function(st) return string.format("Level %d in the %s Sea: levelling with quests.", st.level, SEA_NAMES[st.sea] or "?") end },
}
BF.AUTO_STAGES = STAGES

local P = { on = false, owned = {}, handsOff = {}, stage = nil, st = nil, offs = {} }
BF.autopilot = P
-- the settings this stage wants now: key -> value
local function wanted(st, stage)
  local out = {}
  for _, row in ipairs(stage.rows) do
    local key = row[1]
    local ok = (not row.use or uses(row.use)) and not (row.spends and O.autoNoSpend) and (not row.when or row.when(st))
    -- (a key of a part that is not in this build has no default: skipped)
    if ok and out[key] == nil and Config.defaults[id(key)] ~= nil then out[key] = row[2] end
  end
  return out
end
-- put one setting back as the player had it (only if it is still what the planner set: else it is theirs already)
local function give(key)
  local own = P.owned[key]
  P.owned[key] = nil
  if own and same(Config.get(id(key)), own.set) then Config.set(id(key), util.copy(own.orig), true) end
end
local function take(key, value)
  local own = P.owned[key]
  if not own then
    own = { orig = util.copy(Config.get(id(key))) }
    P.owned[key] = own
  end
  own.set = util.copy(value)
  if not same(Config.get(id(key)), value) then Config.set(id(key), util.copy(value), true) end
end
local report               -- (the session report, below: Autopilot's own window starts with it)
local function startPilot()
  P.on, P.owned, P.handsOff, P.stage, P.since = true, {}, {}, nil, now()
  if report then report.autoStart() end
  BF.say("Autopilot on")
end
local function stopPilot()
  local keys = {}
  for key in pairs(P.owned) do keys[#keys + 1] = key end
  for _, key in ipairs(keys) do give(key) end
  P.on, P.handsOff, P.stage = false, {}, nil
  BF.say(string.format("Autopilot off: %d settings put back as you had them", #keys))
end
local function pickStage(st)
  for _, stage in ipairs(STAGES) do
    local ok, yes = pcall(stage.when, st)
    if ok and yes then return stage end
  end
  return STAGES[#STAGES]
end
local function plan()
  if not O.autopilot then
    if P.on then stopPilot() end
    return
  end
  if not hasData() then return end
  if not P.on then startPilot() end
  -- a setting changed by someone else while the planner held it: theirs now
  local lost = {}
  for key, own in pairs(P.owned) do
    if not same(Config.get(id(key)), own.set) then lost[#lost + 1] = key end
  end
  for _, key in ipairs(lost) do
    P.owned[key], P.handsOff[key] = nil, true
    BF.say("Autopilot: " .. label(key) .. " was changed by hand: left to you")
  end
  local st = account()
  local stage = pickStage(st)
  if P.stage ~= stage then
    P.stage, P.stageAt = stage, now()
    BF.say("Autopilot: " .. stage.label)
  end
  P.st = st
  local want = wanted(st, stage)
  local drop = {}
  for key in pairs(P.owned) do
    if want[key] == nil then drop[#drop + 1] = key end
  end
  for _, key in ipairs(drop) do give(key) end
  for key, value in pairs(want) do
    if not P.handsOff[key] then take(key, value) end
  end
end
-- what it is waiting for, in one line
local function waiting(st, stage)
  local parts = {}
  if stage.id == "sea2" or stage.id == "sea3" then
    parts[#parts + 1] = P.handsOff.questNextSea and "Going to the next sea was switched off by hand: see the Quests tab." or "The chain runs: see the Quests tab."
  elseif stage.id == "cap" then
    parts[#parts + 1] = "Nothing more to level."
  else
    local gate = (st.sea == 1 and 700) or (st.sea == 2 and 1500) or nil
    if not gate then
      parts[#parts + 1] = string.format("Level %s is the cap (now %d)", util.comma(st.cap), st.level)
    elseif st.level < gate then
      parts[#parts + 1] = string.format("Level %s opens the %s Sea (now %d)", util.comma(gate), SEA_NAMES[st.sea + 1], st.level)
    elseif O.autoNoSea then
      parts[#parts + 1] = string.format("Level %s: Never change sea is on", util.comma(gate))
    else
      parts[#parts + 1] = string.format("Level %s: tick Sea chains to sail on", util.comma(gate))
    end
  end
  -- (Buso is the one ability whose ownership can be read: the tag. Its price is the teacher's, NPCs/HakiTeacher.luau:59)
  if uses("abilities") and not O.autoNoSpend and not st.buso and st.beli < 25000 then
    parts[#parts + 1] = string.format("Buso at $25,000 (you have $%s)", short(st.beli))
  end
  if uses("bosses") and not bossesNear(st) then parts[#parts + 1] = "no boss in reach" end
  return table.concat(parts, "  ·  ")
end
local function cardLines()
  if not O.autopilot then return "Off. Switch it on and it takes over from where the account stands.", "", "" end
  local st, stage = P.st, P.stage
  if not (st and stage) then return "Starting: waiting for the player's data.", "", "" end
  local ok, why = pcall(stage.why, st)
  local first = string.format("%s: %s  ·  $%s, %s F, fruit %s", stage.label, ok and why or "", short(st.beli), short(st.frags), fruitName(st.fruit))
  local on, options = {}, 0
  for key, own in pairs(P.owned) do
    if own.set == true then on[#on + 1] = label(key) elseif own.set ~= false then options += 1 end
  end
  table.sort(on)
  local second = #on > 0 and ("Switched on: " .. table.concat(on, ", ") .. (options > 0 and string.format(" (+%d options)", options) or "")) or "Switched on: nothing"
  local mine = {}
  for key in pairs(P.handsOff) do mine[#mine + 1] = label(key) end
  if #mine > 0 then table.sort(mine); second ..= "  ·  left to you: " .. table.concat(mine, ", ") end
  return first, second, "Waiting for: " .. waiting(st, stage)
end

-- ============================================================================ 2. the session report
-- R.exp etc. are running totals since the hub started; a window is a snapshot of them taken at its start.
local R = { exp = 0, beliUp = 0, fragsUp = 0, found = 0, picked = 0, stored = 0, seenFruit = BF.keep({}) }
local expFn, expCache = nil, {}
-- the experience a level needs (ReplicatedStorage.EXPFunction, called as the game's bar calls it; its formula as the fallback)
local function expFor(level)
  if expCache[level] then return expCache[level] end
  if expFn == nil then
    local fn = BF.mod("EXPFunction")
    expFn = type(fn) == "function" and fn or false
  end
  local need
  if expFn then
    local ok, n = BF.game(expFn, level)
    need = ok and tonumber(n) or nil
  end
  need = need or (math.ceil(2 * level ^ 2.3 + 30) + 54)          -- EXPFunction.luau:5
  expCache[level] = need
  return need
end
local last
local function track()
  if not hasData() then return end
  local level, exp = BF.level(), tonumber(BF.data("Exp")) or 0
  local beli, frags = tonumber(BF.data("Beli")) or 0, tonumber(BF.data("Fragments")) or 0
  if last then
    if level == last.level then
      if exp > last.exp then R.exp += exp - last.exp end
    elseif level > last.level and level - last.level <= 100 then
      -- (what was left of the old level, every level passed whole, then what is in the new one)
      local gained = math.max(0, expFor(last.level) - last.exp) + exp
      for passed = last.level + 1, level - 1 do gained += expFor(passed) end
      R.exp += gained
    end
    if beli > last.beli then R.beliUp += beli - last.beli end
    if frags > last.frags then R.fragsUp += frags - last.frags end
  end
  last = { level = level, exp = exp, beli = beli, frags = frags }
  if BF.fruit and type(BF.fruit.list) == "function" then
    local ok, list = pcall(BF.fruit.list)
    for _, entry in ipairs(ok and type(list) == "table" and list or {}) do
      if entry.inst and not R.seenFruit[entry.inst] then R.seenFruit[entry.inst] = true; R.found += 1 end
    end
  end
end
local function snapshot()
  local c = BF.count
  return { at = now(), level = BF.level(), exp = R.exp, beliUp = R.beliUp, fragsUp = R.fragsUp, kills = c.kills, quests = c.quests, deaths = c.deaths,
    repairs = c.repairs, lagbacks = c.lagbacks, chests = BF.loot and BF.loot.chests or 0, found = R.found, picked = R.picked, stored = R.stored }
end
report = { hub = nil, auto = nil }
function report.autoStart() report.auto = hasData() and snapshot() or nil end
local function windowLines(title, s)
  if not s then return { title .. ": not started.", "", "" } end
  local t = math.max(1, now() - s.at)
  local c = BF.count
  local exp, kills = R.exp - s.exp, c.kills - s.kills
  local chests = (BF.loot and BF.loot.chests or 0) - s.chests
  return {
    string.format("%s: %s  ·  level %d -> %d (+%d)  ·  %s exp, %s an hour", title, clock(t), s.level, BF.level(), BF.level() - s.level, short(exp),
      short(exp / (t / 3600))),
    string.format("Beli +%s  ·  Fragments +%s  ·  %d kills (%.1f a minute)  ·  %d quests paid", short(R.beliUp - s.beliUp), short(R.fragsUp - s.fragsUp), kills,
      kills / (t / 60), c.quests - s.quests),
    string.format("Fruits %d found, %d picked up, %d stored  ·  %d chests  ·  %d deaths, %d repairs, %d pull-backs", R.found - s.found, R.picked - s.picked,
      R.stored - s.stored, chests, c.deaths - s.deaths, c.repairs - s.repairs, c.lagbacks - s.lagbacks),
  }
end
local function boostLine()
  -- ExpBoost = seconds of 2x left as of ExpBoostTick, a tick() (ExpBar.luau:71-77; Comm.luau:76-82)
  local left, at = tonumber(B.LP:GetAttribute("ExpBoost")), tonumber(B.LP:GetAttribute("ExpBoostTick"))
  if not left or left <= 0 then return "2x EXP: off" end
  if at then left -= tick() - at end
  if left <= 0 then return "2x EXP: ended" end
  return "2x EXP: " .. clock(left) .. " left"
end
local function reportText()
  local out = { string.format("BASED Hub · Blox Fruits · %s · %s Sea · level %d", os.date("%Y-%m-%d %H:%M"), SEA_NAMES[BF.sea()] or "?", BF.level()) }
  for _, line in ipairs(windowLines("Since the hub started", report.hub)) do out[#out + 1] = line end
  if report.auto then
    for _, line in ipairs(windowLines("Since Autopilot started", report.auto)) do out[#out + 1] = line end
  end
  out[#out + 1] = boostLine()
  return table.concat(out, "\n")
end
-- Fruits picked up and stored are counted from the fruit part's own log lines ("Picked up ...", bloxfruits_fruit.lua:279;
-- "Stored ...", :326): that part keeps no counter. BF.say is wrapped and put back on unload.
local function countSays()
  local say = BF.say
  if type(say) ~= "function" or BF.autoSayWrapped then return end
  BF.autoSayWrapped = true
  BF.say = function(text, ...)
    if type(text) == "string" then
      if string.sub(text, 1, 7) == "Stored " then R.stored += 1
      elseif string.sub(text, 1, 10) == "Picked up " then R.picked += 1 end
    end
    return say(text, ...)
  end
  B.own(function() BF.say = say; BF.autoSayWrapped = nil end)
end

-- ============================================================================ 3. stop conditions
-- switches that are farms but not a job's `switch`: the quest chains (bloxfruits_quest.lua), mastery and skills (bloxfruits_mastery.lua)
local EXTRA_OFF = { "questSea2", "questSea3", "questSaber", "questCitizen", "masteryFarm", "autoSkills" }
local RARITIES = { "Common", "Uncommon", "Rare", "Legendary", "Mythical", "Premium" }     -- FruitInfo Rarity.Name, as bloxfruits_fruit.lua:28
local stopState = { since = nil, fired = setmetatable({}, { __mode = "k" }) }
local function stopAll(why)
  -- (the engine's one stop-all: Autopilot first, every job's switch, every switch a part has named, the body let go)
  for _, key in ipairs(EXTRA_OFF) do
    if Config.get(id(key)) == true then Config.set(id(key), false) end
  end
  BF.stopAll("Stop condition: " .. why)
  -- (the condition is spent: switched off, so a farm switched on again by hand is not stopped at once)
  Config.set(id("autoStop"), false)
  BF.say("Every farm stopped: " .. why)
  Window.toast({ title = "Farming stopped", text = why, icon = "circle-alert", tone = "ok", time = 10 })
end
local function stopCheck()
  if not O.autoStop then stopState.since = nil; return end
  stopState.since = stopState.since or now()
  if not hasData() then return end
  local level, beli, frags = BF.level(), tonumber(BF.data("Beli")) or 0, tonumber(BF.data("Fragments")) or 0
  local atLevel, atBeli, atFrags, minutes = tonumber(O.autoStopLevel) or 0, tonumber(O.autoStopBeli) or 0, tonumber(O.autoStopFrags) or 0,
    tonumber(O.autoStopMinutes) or 0
  if atLevel > 0 and level >= atLevel then return stopAll(string.format("Level %d reached.", level)) end
  if atBeli > 0 and beli >= atBeli then return stopAll(string.format("$%s reached.", short(beli))) end
  if atFrags > 0 and frags >= atFrags then return stopAll(string.format("%s Fragments reached.", short(frags))) end
  if minutes > 0 and now() - stopState.since >= minutes * 60 then return stopAll(string.format("%d minutes are up.", minutes)) end
  local ranks = O.autoStopRarities
  if type(ranks) == "table" and #ranks > 0 then
    for _, tool in ipairs(bagFruits()) do
      local key = tool:GetAttribute("OriginalName")
      local rank = rarityName(key)
      if rank and table.find(ranks, rank) and not stopState.fired[tool] then
        stopState.fired[tool] = true
        return stopAll(string.format("%s (%s) is in your bag: too good to lose.", fruitName(key), rank))
      end
    end
  end
end

-- ============================================================================ 4. setups
local SETUP_FILE = fs.path("bloxfruits/setups.json")
-- built in: a few settings on top of the defaults, only features that were run live (NOTES.md)
local BUILT_IN = {
  { name = "Leveller", values = { level = true, stats = true, haki = true, autoAbilities = true, gather = true, multi = true } },
  { name = "Fruit hunter", values = { level = true, fruitCollect = true, fruitStore = true, fruitNotify = true, fruitEsp = true } },
  { name = "Boss hunter", values = { level = true, bossAll = true, bossQuest = true, espRadarBoss = true, stats = true, haki = true } },
  { name = "Chests", values = { level = true, chestFarm = true, chestMode = "between" } },
  -- (slower flight: "Slower is pulled back less", the engine's own tip; boss quests skipped; nothing bought)
  { name = "AFK and safe", values = { level = true, skipBoss = true, stats = true, haki = true, fruitStore = true, speed = 200, reset = true } },
}
-- a Color3 or an EnumItem as JSON, the way the hub's own profiles keep them (src/05_config.lua:22-46)
local function encode(value)
  local kind = typeof(value)
  if kind == "Color3" then return { __c = util.toHex(value) } end
  if kind == "EnumItem" then return { __e = tostring(value.EnumType), v = value.Name } end
  if kind == "table" then
    local out = {}
    for k, v in pairs(value) do out[k] = encode(v) end
    return out
  end
  return value
end
local function decode(value)
  if type(value) ~= "table" then return value end
  if type(value.__c) == "string" then
    local ok, color = pcall(util.hex, value.__c)
    return ok and color or nil
  end
  if value.__e then
    local ok, item = pcall(function() return Enum[value.__e][value.v] end)
    return ok and item or nil
  end
  local out = {}
  for k, v in pairs(value) do out[k] = decode(v) end
  return out
end
-- every bloxfruits.* setting of every part (and the engine's own), read at run time; this part's are left out
local function settingKeys()
  local keys, seen = {}, {}
  local function put(key)
    if not seen[key] and DEFAULTS[key] == nil and Config.defaults[id(key)] ~= nil then seen[key] = true; keys[#keys + 1] = key end
  end
  for _, part in ipairs(BF.parts) do
    for key in pairs(part.defaults or {}) do put(key) end
  end
  for key in pairs(BF.map or {}) do put(key) end
  table.sort(keys)
  return keys
end
local saved
local function setups()
  if saved then return saved end
  local data = fs.readJson(SETUP_FILE)
  saved = type(data) == "table" and type(data.setups) == "table" and data.setups or {}
  return saved
end
local function writeSetups()
  return fs.writeJson(SETUP_FILE, { version = 1, game = BF.UNIVERSE, saved = os.time(), setups = setups() })
end
local function builtIn(name)
  for _, setup in ipairs(BUILT_IN) do
    if setup.name == name then return setup end
  end
  return nil
end
local function setupOptions()
  local out = {}
  for _, setup in ipairs(BUILT_IN) do out[#out + 1] = { "b:" .. setup.name, setup.name } end
  local names = {}
  for name in pairs(setups()) do names[#names + 1] = name end
  table.sort(names)
  for _, name in ipairs(names) do out[#out + 1] = { "u:" .. name, name .. "  ·  yours" } end
  return out
end
-- key -> value, every setting, of the setup picked
local function targetOf(pick)
  if type(pick) ~= "string" then return nil end
  local kind, name = string.match(pick, "^(%a):(.+)$")
  local setup = kind == "b" and builtIn(name) or nil
  local entry = kind == "u" and setups()[name] or nil
  if not (setup or (type(entry) == "table" and type(entry.values) == "table")) then return nil end
  local out = {}
  for _, key in ipairs(settingKeys()) do
    local default = Config.defaults[id(key)]
    local value
    if setup then value = setup.values[key] else value = decode(entry.values[key]) end
    if value == nil or typeof(value) ~= typeof(default) then value = default end
    out[key] = util.copy(value)
  end
  return out
end
local function changes(values)
  local out = {}
  for key, value in pairs(values) do
    if not same(Config.get(id(key)), value) then out[#out + 1] = key end
  end
  -- (switches that would come on first: they matter most)
  table.sort(out, function(a, b)
    local onA, onB = values[a] == true, values[b] == true
    if onA ~= onB then return onA end
    return a < b
  end)
  return out
end
local function show(value)
  if value == true then return "on" end
  if value == false then return "off" end
  if type(value) == "number" then return util.comma(value) end
  if type(value) == "table" then return #value .. " ticked" end
  if typeof(value) == "Color3" then return "#" .. util.toHex(value) end
  return string.format("%q", tostring(value))
end
local function previewText()
  local values = targetOf(O.setupPick)
  if not values then return "Pick a setup." end
  local diff = changes(values)
  if #diff == 0 then return "Loading it would change nothing." end
  local bits = {}
  for index = 1, math.min(#diff, 5) do bits[#bits + 1] = label(diff[index]) .. " " .. show(values[diff[index]]) end
  return string.format("%d would change: %s%s", #diff, table.concat(bits, ", "), #diff > 5 and string.format(" and %d more", #diff - 5) or "")
end
local function loadSetup()
  local values = targetOf(O.setupPick)
  if not values then Window.toast({ title = "Setups", text = "Pick a setup first.", icon = "layers", time = 4 }); return end
  if O.autopilot then Config.set(id("autopilot"), false) end
  local diff = changes(values)
  -- (set as the player's own choice: a setup is what they picked, and it is saved)
  for _, key in ipairs(diff) do Config.set(id(key), util.copy(values[key])) end
  local name = string.match(O.setupPick, "^%a:(.+)$") or "Setup"
  BF.say(string.format("Setup %s loaded: %d settings changed", name, #diff))
  Window.toast({ title = "Setup loaded", text = string.format("%s: %d settings changed.", name, #diff), icon = "layers", tone = "ok", time = 5 })
end
local function saveSetup(refresh)
  local name = string.sub((string.gsub(string.gsub(tostring(O.setupName or ""), "^%s+", ""), "%s+$", "")), 1, 32)
  if name == "" then Window.toast({ title = "Setups", text = "Type a name first.", icon = "layers", time = 4 }); return end
  if builtIn(name) then Window.toast({ title = "Setups", text = "That name is a built-in setup's.", icon = "layers", time = 4 }); return end
  if not fs.ok then Window.toast({ title = "Setups", text = "This executor cannot write files.", icon = "layers", time = 4 }); return end
  local values = {}
  for _, key in ipairs(settingKeys()) do values[key] = encode(util.copy(Config.get(id(key)))) end
  setups()[name] = { values = values, saved = os.time() }
  local ok = writeSetups()
  if refresh then refresh() end
  Config.set(id("setupPick"), "u:" .. name)
  Window.toast({ title = "Setups", text = ok and (name .. " saved.") or "The file could not be written.", icon = "save", tone = ok and "ok" or nil, time = 4 })
end
local function deleteSetup(refresh)
  local name = string.match(tostring(O.setupPick or ""), "^u:(.+)$")
  if not name or not setups()[name] then
    Window.toast({ title = "Setups", text = "Only your own setups can be deleted.", icon = "layers", time = 4 })
    return
  end
  setups()[name] = nil
  local ok = writeSetups()
  Config.set(id("setupPick"), DEFAULTS.setupPick)
  if refresh then refresh() end
  Window.toast({ title = "Setups", text = ok and (name .. " deleted.") or "The file could not be written.", icon = "trash-2", time = 4 })
end

-- ============================================================================ 5. learned places, kept on disk
-- BF.seen (the engine: mob name -> up to 16 points at least 40 studs apart, bloxfruits.lua:316-330), one file per sea.
local learn = { savedAt = nil, loaded = 0, lastCount = -1, nextSave = 0 }
local function seenFile() return fs.path(string.format("bloxfruits/seen_sea%d.json", BF.sea())) end
local function seenCount()
  local mobs, points = 0, 0
  for _, list in pairs(BF.seen or {}) do
    mobs += 1
    points += #list
  end
  return mobs, points
end
local function saveSeen()
  if not fs.ok or type(BF.seen) ~= "table" then return false end
  local mobs = {}
  for name, list in pairs(BF.seen) do
    local points = {}
    for _, point in ipairs(list) do
      if typeof(point) == "Vector3" then points[#points + 1] = { math.floor(point.X + 0.5), math.floor(point.Y + 0.5), math.floor(point.Z + 0.5) } end
    end
    if #points > 0 then mobs[name] = points end
  end
  local ok = fs.writeJson(seenFile(), { version = 1, place = game.PlaceId, saved = os.time(), mobs = mobs })
  if ok then learn.savedAt = os.date("%H:%M") end
  return ok
end
local function loadSeen()
  local data = fs.readJson(seenFile())
  if type(data) ~= "table" or type(data.mobs) ~= "table" or data.place ~= game.PlaceId or type(BF.seen) ~= "table" then return 0 end
  local added = 0
  for name, points in pairs(data.mobs) do
    if type(name) == "string" and type(points) == "table" then
      local list = BF.seen[name]
      if not list then list = {}; BF.seen[name] = list end
      for _, raw in ipairs(points) do
        local x, y, z = type(raw) == "table" and tonumber(raw[1]), type(raw) == "table" and tonumber(raw[2]), type(raw) == "table" and tonumber(raw[3])
        if x and y and z and #list < 16 then
          local at, near = Vector3.new(x, y, z), false
          for _, point in ipairs(list) do
            if (point - at).Magnitude < 40 then near = true; break end
          end
          if not near then list[#list + 1] = at; added += 1 end
        end
      end
    end
  end
  learn.loaded = added
  return added
end
local function learnTick()
  if not O.learnKeep or now() < learn.nextSave then return end
  learn.nextSave = now() + 180
  local _, points = seenCount()
  if points ~= learn.lastCount and points > 0 then
    learn.lastCount = points
    saveSeen()
  end
end
local function learnLine()
  local mobs, points = seenCount()
  return string.format("%d mobs, %d places known  ·  %d read from disk  ·  saved %s", mobs, points, learn.loaded, learn.savedAt or "not yet")
end

-- ============================================================================ 6. server news
-- the rare islands, as the ESP part tells them (bloxfruits_esp.lua:40, :249-265): Locations parts by name, the Mirage's fog zone,
-- and the Kitsune / Prehistoric island models under workspace.Map
local SPECIAL = { ["Mirage Island"] = true, ["Kitsune Island"] = true, ["Prehistoric Island"] = true, ["Frozen Dimension"] = true }
local function rareIslands()
  local out, seen = {}, {}
  local function put(name) if not seen[name] then seen[name] = true; out[#out + 1] = name end end
  local origin = workspace:FindFirstChild("_WorldOrigin")
  local places = origin and origin:FindFirstChild("Locations")
  for _, zone in ipairs(places and places:GetChildren() or {}) do
    local name = string.gsub(zone.Name, "%d+$", "")
    if SPECIAL[name] then put(name) end
  end
  local zones = origin and origin:FindFirstChild("LightingZones")
  if zones and zones:FindFirstChild("MirageIsland") then put("Mirage Island") end
  local map = workspace:FindFirstChild("Map")
  if map and map:FindFirstChild("KitsuneIsland") then put("Kitsune Island") end
  if map and map:FindFirstChild("PrehistoricIsland") then put("Prehistoric Island") end
  table.sort(out)
  return out
end
local function newsLines()
  local fruits = {}
  if BF.fruit and type(BF.fruit.list) == "function" then
    local ok, list = pcall(BF.fruit.list)
    for _, entry in ipairs(ok and type(list) == "table" and list or {}) do fruits[#fruits + 1] = tostring(entry.name or "Fruit") end
  end
  table.sort(fruits)
  local bosses = {}
  for _, boss in ipairs(bossesAlive()) do bosses[#bosses + 1] = boss.level > 0 and string.format("%s (%d)", boss.name, boss.level) or boss.name end
  local islands = rareIslands()
  -- Lighting attributes MoonPhase (5 = full) and IsBlueMoon (bloxfruits_esp.lua:302-304)
  local phase, blue = S.Lighting:GetAttribute("MoonPhase"), S.Lighting:GetAttribute("IsBlueMoon") == true
  local moon = phase == 5 and "full" or (phase ~= nil and ("phase " .. tostring(phase) .. " of 5") or "unknown")
  return {
    #fruits > 0 and string.format("Fruits in the world: %s", table.concat(fruits, ", ", 1, math.min(#fruits, 8))) or "Fruits in the world: none seen",
    #bosses > 0 and string.format("Bosses alive: %s", table.concat(bosses, ", ", 1, math.min(#bosses, 6))) or "Bosses alive: none seen",
    #islands > 0 and ("Rare islands: " .. table.concat(islands, ", ")) or "Rare islands: none",
    string.format("Moon: %s%s  ·  %d / %d players", moon, blue and " (blue moon)" or "", #S.Players:GetPlayers(), S.Players.MaxPlayers),
  }
end

-- ============================================================================ start
local function start()
  countSays()
  -- the planner: twice a second is plenty for settings
  Motion.every(function() B.try("bloxfruits.autopilot", plan) end, 0.5, "bloxfruits.autopilot")
  B.own(Config.on(id("autopilot"), function(value)
    if value == true then B.try("bloxfruits.autopilot", plan) elseif P.on then stopPilot() end
  end))
  -- The engine's "Stop everything" sets every farm switch off by hand: three held switches going off within half a second
  -- is read as that, and Autopilot goes off too (else it would only lose those switches and keep the rest).
  local link = Config.changed:connect(function(changed, value)
    if not P.on or value ~= false or type(changed) ~= "string" then return end
    local key = string.sub(changed, 12)
    if not P.owned[key] then return end
    local t = now()
    local offs = {}
    for _, at in ipairs(P.offs) do if t - at < 0.5 then offs[#offs + 1] = at end end
    offs[#offs + 1] = t
    P.offs = offs
    if #offs >= 3 then
      P.offs = {}
      BF.say("Autopilot: farms were stopped by hand, so it goes off too")
      Config.set(id("autopilot"), false)
    end
  end)
  B.own(function() link.disconnect() end)
  B.own(function() if P.on then stopPilot() end end)
  -- the books and the stop conditions, once a second
  Motion.every(function()
    B.try("bloxfruits.autoTrack", function()
      track()
      if not report.hub and hasData() then report.hub = snapshot() end
      if P.on and not report.auto then report.autoStart() end
    end)
    B.try("bloxfruits.autoStop", stopCheck)
    B.try("bloxfruits.autoLearn", learnTick)
  end, 1, "bloxfruits.autoBooks")
  -- learned places: read at start, written every 3 min while they grow, and as the hub ends or teleports
  if O.learnKeep then B.try("bloxfruits.autoLearn", loadSeen) end
  B.own(Config.on(id("learnKeep"), function(value)
    if value == true then B.try("bloxfruits.autoLearn", loadSeen) end
  end))
  B.own(function() if O.learnKeep then pcall(saveSeen) end end)
  pcall(function()
    B.connect(B.LP.OnTeleport, function(state)
      if O.learnKeep and state == Enum.TeleportState.Started then saveSeen() end
    end, "bloxfruits.autoLearnTeleport")
  end)
end

-- ============================================================================ the tabs
local USE_OPTIONS = { { "stats", "Stat points" }, { "haki", "Keep Buso on" }, { "abilities", "Buy abilities" }, { "fruits", "Pick up and store fruits" },
  { "chests", "Chests between fights" }, { "bring", "Bring mobs together" }, { "bosses", "Bosses too" }, { "seas", "Sea chains (not tried live)" } }
local function pilotCard(page)
  local s = page:section({ title = "Autopilot", icon = "compass", full = true, desc = "One switch, the whole account." })
  s:toggle({ id = id("autopilot"), label = "Autopilot", desc = "Keeps the right farms on for where the account stands.", default = false, children = function(sub)
    sub:multi({ id = id("autoUse"), label = "It may use", options = USE_OPTIONS, default = DEFAULTS.autoUse })
    sub:toggle({ id = id("autoNoSpend"), label = "Never spend Beli", desc = "Abilities are not bought.", default = false, bindable = false })
    sub:toggle({ id = id("autoNoSea"), label = "Never change sea", desc = "The sea chains are never started.", default = false, bindable = false })
  end })
  local first, second, third = cardLines()
  local stage = s:note({ icon = "flag", text = first })
  local on = s:note({ icon = "power", text = second })
  local wait = s:note({ icon = "clock", text = third })
  Motion.every(function()
    if not (stage.frame.Parent and Window.anyOpen()) then return end
    local a, b, c = cardLines()
    stage.set(a)
    on.set(b)
    wait.set(c)
  end, 1, "bloxfruits.autoCard")
end
local function reportCard(page)
  local s = page:section({ title = "Session report", icon = "history", desc = "Since the hub started, and since Autopilot did." })
  local notes = {}
  for index = 1, 7 do notes[index] = s:note({ icon = index <= 3 and "gauge" or (index <= 6 and "compass" or "timer"), text = "" }) end
  local function fill()
    local lines = windowLines("Hub", report.hub)
    local auto = report.auto and windowLines("Autopilot", report.auto) or { "Autopilot: not on this session.", "", "" }
    for index = 1, 3 do
      notes[index].set(lines[index])
      notes[index + 3].set(auto[index])
    end
    notes[7].set(boostLine())
  end
  B.try("bloxfruits.autoReport", fill)
  s:button({ id = id("autoCopy"), label = "Copy report", desc = "The lines above, as text.", text = "Copy", run = function()
    local ok = B.clipboard(reportText())
    Window.toast({ title = "Session report", text = ok and "Copied." or "This executor cannot copy.", icon = "clipboard", tone = ok and "ok" or nil, time = 4 })
  end })
  Motion.every(function()
    if not (notes[1].frame.Parent and Window.anyOpen()) then return end
    B.try("bloxfruits.autoReport", fill)
  end, 1, "bloxfruits.autoReportCard")
end
local function stopCard(page)
  local s = page:section({ title = "Stop conditions", icon = "circle-alert", column = 2, desc = "Every farm off when one is met." })
  local ranks = {}
  for _, name in ipairs(RARITIES) do ranks[#ranks + 1] = { name, name } end
  s:toggle({ id = id("autoStop"), label = "Stop when", desc = "Switches itself off once it has stopped the farms.", default = false, children = function(sub)
    sub:slider({ id = id("autoStopLevel"), label = "Level reached", tip = "0 = never.", min = 0, max = 2800, step = 25, default = 0 })
    sub:slider({ id = id("autoStopBeli"), label = "Beli reached", tip = "0 = never.", min = 0, max = 50000000, step = 100000, default = 0, suffix = " Beli" })
    sub:slider({ id = id("autoStopFrags"), label = "Fragments reached", tip = "0 = never.", min = 0, max = 100000, step = 500, default = 0 })
    sub:slider({ id = id("autoStopMinutes"), label = "After", tip = "Minutes from switching this on. 0 = never.", min = 0, max = 720, step = 5, default = 0,
      suffix = " min" })
    sub:multi({ id = id("autoStopRarities"), label = "A fruit in the bag of", options = ranks, default = {} })
  end })
end
local function farm(page)
  pilotCard(page)
  reportCard(page)
  stopCard(page)
end

local function setupCard(page)
  local s = page:section({ title = "Setups", icon = "layers", desc = "Every Blox Fruits setting at once." })
  local pick = s:dropdown({ id = id("setupPick"), label = "Setup", options = setupOptions() })
  local preview = s:note({ icon = "info", text = previewText() })
  local function refresh()
    if pick and type(pick.options) == "function" then pick.options(setupOptions()) end
    preview.set(previewText())
  end
  s:button({ id = id("setupLoad"), label = "Load it", desc = "Autopilot goes off first.", text = "Load", run = function()
    B.try("bloxfruits.setupLoad", loadSetup)
    preview.set(previewText())
  end })
  s:input({ id = id("setupName"), label = "Name for mine", placeholder = "e.g. Night farm" })
  s:button({ id = id("setupSave"), label = "Save my settings", desc = "Under the name above.", text = "Save", run = function()
    B.try("bloxfruits.setupSave", saveSetup, refresh)
  end })
  s:button({ id = id("setupDelete"), label = "Delete it", desc = "Only your own setups.", text = "Delete", run = function()
    B.try("bloxfruits.setupDelete", deleteSetup, refresh)
  end })
  B.own(Config.on(id("setupPick"), function() if preview.frame.Parent then preview.set(previewText()) end end))
  Motion.every(function()
    if not (preview.frame.Parent and Window.anyOpen()) then return end
    preview.set(previewText())
  end, 0.5, "bloxfruits.setupPreview")
end
local function learnCard(page)
  local s = page:section({ title = "Learned places", icon = "database", column = 2, desc = "Where mobs were seen, kept on disk per sea." })
  s:toggle({ id = id("learnKeep"), label = "Keep between sessions", desc = "A fresh server knows where mobs stand.", default = false, bindable = false })
  local line = s:note({ icon = "map-pin", text = learnLine() })
  s:button({ id = id("learnSaveNow"), label = "Save now", desc = "Writes this sea's file.", text = "Save", run = function()
    local ok = saveSeen()
    Window.toast({ title = "Learned places", text = ok and "Saved." or "This executor cannot write files.", icon = "database", tone = ok and "ok" or nil, time = 4 })
  end })
  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    line.set(learnLine())
  end, 0.5, "bloxfruits.learnLine")
end
local function newsCard(page)
  local s = page:section({ title = "Server news", icon = "radio", column = 2, desc = "Read from the game, never sent." })
  local first = newsLines()
  local notes = {}
  for index, icon in ipairs({ "apple", "skull", "mountain", "moon" }) do notes[index] = s:note({ icon = icon, text = first[index] }) end
  Motion.every(function()
    if not (notes[1].frame.Parent and Window.anyOpen()) then return end
    local lines = newsLines()
    for index, note in ipairs(notes) do note.set(lines[index]) end
  end, 0.33, "bloxfruits.news")
end
local function misc(page)
  setupCard(page)
  learnCard(page)
  newsCard(page)
end

BF.parts[#BF.parts + 1] = { id = "auto", start = start, farm = farm, misc = misc, defaults = DEFAULTS }
end
do -- bloxfruits_boss.lua
-- ============================================================================
--  Blox Fruits     bosses: one boss, every boss, the elite, the Cake Prince,
--                  the Factory and the pirate raid
--
--  Read from the game's own code (dump 2753915549 v4630, `fast\` folder), never
--  tried live: every line below is unproven until measured.
--
--   * A boss is a Model in workspace.Enemies with the attribute IsBoss = true;
--     a raid's boss also has RaidBoss and is not one of them
--     (Controllers/BossCutsceneController.luau:30, 558, 636). Far ones are
--     parked as Models directly under ReplicatedStorage (NOTES.md, measured).
--     Spawn marks of bosses are named "Chef [Lv. 55] [Boss]" (NOTES.md).
--   * A boss quest is a one-kill quest of the game's Quests table (Quests.luau:5-51),
--     taken with CommF_ "StartQuest", group, index -> 0 = taken (DialoguesList/Util.luau:170).
--   * Elite Hunter: CommF_ "EliteHunter" gives the quest and answers a sentence
--     (DialoguesList.luau:4808); "EliteHunter", "Progress" answers the count
--     (DialoguesList.luau:4827-4830). The elite's NAME is not in the dump: it is
--     read from the quest in hand once the server gives it.
--   * Cake Prince: CommF_ "CakePrinceSpawner", true answers a sentence; when it
--     holds "open the portal now", CommF_ "CakePrinceSpawner" opens it
--     (DialoguesList.luau:4283-4294, NPC "drip_mama", NPCList.luau:1603).
--   * Soul Reaper, rip_indra, Darkbeard: the dump has the items (ItemConfig) and
--     no command that calls them. Not built; the tab says why.
--   * Factory (Second Sea) and the pirate raid (Third Sea): nothing in the dump
--     announces them. They are seen from what is alive: a "Core" (a name from
--     public hubs only) and mobs at the Castle on the Sea that have no spawn there.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion = B.S, B.Config, B.Window, B.Motion
local BF = B.BloxFruits
local O = BF.O
local function now() return os.clock() end

local BOSS = { kills = 0, elites = 0, cakes = 0, cores = 0, raiders = 0, deaths = 0 }
BF.boss = BOSS
local aside, why = {}, {}          -- boss name -> until when it is left alone, and the reason
local streak = {}                  -- what killed the body -> deaths in a row
local questAside = {}              -- "group/index" -> until when a boss quest is not asked again
local elite = { nextAt = 0, last = "Not asked yet." }
local cake = { nextAt = 0, askedAt = -1e9, last = "Not asked yet.", tries = 0 }
local factory = { nextAt = 0 }
local pirates = { nextAt = 0 }

-- ---------------------------------------------------------------- what is alive
-- One look at the enemies near (workspace.Enemies) and the far ones parked under ReplicatedStorage, kept 1.5 s.
local view, viewAt = nil, -1e9
local function isBoss(model)
  -- BossCutsceneController.luau:30 (the game's own isBoss)
  return model:GetAttribute("IsBoss") == true and not model:GetAttribute("RaidBoss")
end
local function add(map, name, model)
  local list = map[name]
  if not list then list = {}; map[name] = list end
  list[#list + 1] = model
end
local function scan()
  if view and now() - viewAt < 1.5 then return view end
  local out, t = { enemies = {}, parked = {}, bosses = {} }, now()
  local folder = workspace:FindFirstChild("Enemies")
  for _, model in ipairs(folder and folder:GetChildren() or {}) do
    if model:IsA("Model") and BF.living(model) and not ((BF.shunned[model] or 0) > t) then
      add(out.enemies, model.Name, model)
      if isBoss(model) then add(out.bosses, model.Name, model) end
    end
  end
  for _, model in ipairs(S.ReplicatedStorage:GetChildren()) do
    local hum = model:IsA("Model") and model:FindFirstChildOfClass("Humanoid")
    if hum and hum.Health > 0 then
      add(out.parked, model.Name, model)
      if isBoss(model) then add(out.bosses, model.Name, model) end
    end
  end
  view, viewAt = out, now()
  return out
end
local function pivotOf(model)
  local ok, pivot = pcall(model.GetPivot, model)
  return ok and pivot.Position or nil
end

-- ---------------------------------------------------------------- the bosses of this sea
-- { list = { { name, level, quest } }, byName }: spawn marks with "[Boss]", one-kill quests, and IsBoss bodies seen. Kept 30 s.
local catalogue, catalogueAt = nil, -1e9
local function bossCatalogue()
  if catalogue and now() - catalogueAt < 30 then return catalogue end
  local list, byName = {}, {}
  local function entry(name, level)
    local row = byName[name]
    if not row then row = { name = name, level = 0 }; byName[name] = row; list[#list + 1] = row end
    if (row.level or 0) == 0 and level then row.level = level end
    return row
  end
  local origin = workspace:FindFirstChild("_WorldOrigin")
  local marks = origin and origin:FindFirstChild("EnemySpawns")
  for _, mark in ipairs(marks and marks:GetChildren() or {}) do
    if string.find(mark.Name, "[Boss]", 1, true) then
      local name, level = string.match(mark.Name, "^(.-) %[Lv%. (%d+)%]")
      if name then entry(name, tonumber(level)) end
    end
  end
  for _, quest in ipairs(BF.quests and BF.quests() or {}) do
    if quest.need == 1 then entry(quest.mob, quest.level).quest = quest end
  end
  for name, models in pairs(scan().bosses) do entry(name, tonumber(models[1]:GetAttribute("Level"))) end
  table.sort(list, function(a, b) return a.level < b.level end)
  catalogue, catalogueAt = { list = list, byName = byName }, now()
  return catalogue
end

local function questFor(name)
  local row = bossCatalogue().byName[name]
  return row and row.quest
end
-- Where a parked boss is to be met: its spawn (the game's marks, the second list, learned places), else its quest's
-- spawn, and its parked pivot only when neither is known. (The pivot of a body parked under ReplicatedStorage is no
-- place to fly to: the body comes into workspace.Enemies when the player is near its SPAWN, NOTES.md.) Kept 30 s.
local meetCache = {}
local function meetPoint(name, model)
  local cached = meetCache[name]
  if cached and now() - cached.t < 30 then return cached.at or (model and pivotOf(model)) end
  local at = BF.spawns(name)[1]
  local quest = not at and questFor(name)
  if quest and quest.spawns and quest.spawns[1] then at = quest.spawns[1] end
  meetCache[name] = { at = at, t = now() }
  return at or (model and pivotOf(model))
end
-- Where a boss is now: "here" (in workspace.Enemies, with the mob), "far" (parked), or "down" (with its spawn, if any).
local function locate(name)
  local root = BF.root()
  local here = BF.mobs(name, root and root.Position)[1]
  if here then return { state = "here", at = here.HumanoidRootPart.Position, mob = here } end
  local parked = scan().parked[name]
  local at = parked and meetPoint(name, parked[1])
  if at then return { state = "far", at = at } end
  local spawns = BF.spawns(name)
  return { state = "down", at = spawns[1], spawns = spawns }
end
-- An NPC's place: its model when it is near, else where the engine last saw it (kept on disk).
local function npcAt(name)
  for _, folder in ipairs({ workspace:FindFirstChild("NPCs"), S.ReplicatedStorage:FindFirstChild("NPCs") }) do
    local npc = folder and folder:FindFirstChild(name)
    local at = npc and pivotOf(npc)
    if at then return at end
  end
  return BF.npcSeen and BF.npcSeen[name] or nil
end

-- ---------------------------------------------------------------- deaths
-- Every death of the body, from the Humanoid's own Died (the engine's count rises only when a job's wait for the body
-- sees it come back in time). A guard takes the larger of the two, so a slow respawn is counted all the same.
local lives, watched = 0, nil
local BODY_WAIT = 90                 -- seconds to wait for the body after a death (a slow respawn is not a lost job)
local function watchBody(char)
  if not char or char == watched then return end
  watched = char
  local hum = char:WaitForChild("Humanoid", 10)
  -- (a plain connection: it goes with the Humanoid when the body is gone)
  if hum and watched == char then hum.Died:Connect(function() lives += 1 end) end
end
local function deathMark() return { lives, BF.count.deaths } end
local function deathsSince(mark) return math.max(lives - mark[1], BF.count.deaths - mark[2]) end

-- ---------------------------------------------------------------- fighting one
-- Go to the body of that name and fight it to the end. "dead" / "gone" / "unreached" / "stuck" / "stopped" / "died".
local function engage(ctx, name)
  local where = locate(name)
  if where.state == "down" then return "gone" end
  if where.state == "far" then
    -- (a parked body comes into workspace.Enemies when the body is near its spawn: where.at is that spawn, and the
    -- move into the folder is given some time, not the 5 s that left far bosses "unreached")
    local ok, whyNot = BF.fly(where.at + Vector3.new(0, O.height or 25, 0), ctx, { note = "To " .. name })
    if not ok then return whyNot == "dead" and "died" or (whyNot == "stopped" and "stopped" or "unreached") end
    local untilAt = now() + 15
    while now() < untilAt and not BF.mobs(name)[1] do
      if ctx.stop then return "stopped" end
      ctx:beat("Looking for " .. name)
      task.wait(0.2)
    end
  end
  local root = BF.root()
  local mob = BF.mobs(name, root and root.Position)[1]
  if not mob then return where.state == "far" and "unreached" or "gone" end
  return BF.fight(mob, ctx, function() return {} end)
end
-- After a fight: wait for the body if it died, and count deaths in a row on the same foe (`before` is a deathMark()).
-- True when that foe has now killed the body `bossDeaths` times in a row: the caller sets it aside.
local function guard(ctx, key, result, before)
  if result == "died" or not BF.alive() then ctx:body(BODY_WAIT) end
  if result == "dead" then streak[key] = 0; return false end
  local died = deathsSince(before)
  if died <= 0 then return false end
  BOSS.deaths += died
  streak[key] = (streak[key] or 0) + died
  if streak[key] < (O.bossDeaths or 3) then return false end
  BF.say(string.format("%s killed the body %d times in a row: left alone for 30 min", key, streak[key]))
  streak[key] = 0
  return true
end
-- Fight a boss by name with every guard: deaths in a row, a boss that will not die, one that cannot be reached.
local function duel(ctx, name)
  local before = deathMark()
  local result = engage(ctx, name)
  if guard(ctx, name, result, before) then
    aside[name], why[name] = now() + 1800, "too strong"
    return "too strong"
  end
  if result == "dead" then
    BOSS.kills += 1
    BF.say(string.format("%s down (%d bosses)", name, BOSS.kills))
  elseif result == "stuck" or result == "unreached" or result == "gone" then
    -- (never the same failing thing again at once: the boss is left alone a little while)
    local rest = result == "gone" and 30 or 120
    aside[name], why[name] = now() + rest, result == "stuck" and "would not lose health" or (result == "gone" and "gone" or "could not be reached")
  end
  return result
end

-- ---------------------------------------------------------------- the boss's quest
local function questKey(quest) return quest.group .. "/" .. quest.index end
local function takeQuest(ctx, quest)
  if quest.level > BF.level() or (questAside[questKey(quest)] or 0) > now() then return false end
  local held = BF.quest()
  if held and held.InternalQuestName == quest.group and held.Info.Name == quest.name then return true end
  if held then
    -- (a story quest in hand is never dropped for a boss quest: the boss is then fought without its quest)
    if not BF.dropQuest() then return false, "a story quest is in hand" end
    ctx:sleep(0.4, "Dropping another quest")
  end
  local ok, whyNot = BF.fly(quest.at + Vector3.new(0, 5, 0), ctx, { note = "To " .. quest.giver })
  if not ok then return false, whyNot end
  local sent, answer = BF.invoke(6, "StartQuest", quest.group, quest.index)    -- DialoguesList/Util.luau:170 (0 = taken)
  if sent and answer == 0 then
    local untilAt = now() + 3
    while not BF.quest() and now() < untilAt and not ctx.stop do
      ctx:beat("Quest taken: " .. quest.name)
      task.wait(0.1)
    end
    return true
  end
  questAside[questKey(quest)] = now() + 300
  BF.say(string.format("%s was not given (%s): not asked again for 5 min", quest.name, tostring(answer)))
  return false
end

-- ---------------------------------------------------------------- farm one boss
local function hover(ctx, at, note)
  local over = at + Vector3.new(0, O.height or 25, 0)
  local root = BF.root()
  if root and (root.Position - over).Magnitude > 30 then
    BF.fly(over, ctx, { note = note })
  else
    BF.holdAt(over)
  end
end
local function oneLoop(ctx)
  local waitedSince
  while B.alive and not ctx.stop do
    if not ctx:body(BODY_WAIT) then return end
    local name = O.bossName or ""
    if name == "" or (aside[name] or 0) > now() then BF.release(); return end
    local where = locate(name)
    if where.state ~= "down" then
      waitedSince = nil
      local quest = O.bossQuest == true and questFor(name)
      if quest then takeQuest(ctx, quest) end
      local result = duel(ctx, name)
      if result == "too strong" then Config.set("bloxfruits.bossOne", false); BF.release(); return end
      if result == "stopped" then return end
    elseif O.bossIdle ~= "wait" then
      -- (its want is false while the boss is down: the body goes back to the level farm)
      BF.release()
      return
    elseif not where.at then
      aside[name], why[name] = now() + 120, "no spawn known"
      BF.say(name .. " is down and no spawn of it is known: left alone for 2 min")
      return
    else
      waitedSince = waitedSince or now()
      if now() - waitedSince > (O.bossWaitMax or 600) then
        aside[name], why[name] = now() + 120, "waited long enough"
        BF.say(string.format("%s did not come back in %d s: the body is free for 2 min", name, O.bossWaitMax or 600))
        return
      end
      hover(ctx, where.at, "To where " .. name .. " comes back")
      ctx:sleep(2, "Waiting for " .. name)
      -- (here the waiting IS the work, bounded by bossWaitMax above: the director is not to call it a stall)
      ctx:progress()
    end
    task.wait()
  end
end
local function oneWanted()
  local name = O.bossName or ""
  if O.bossOne ~= true or name == "" or (aside[name] or 0) > now() then return false end
  return O.bossIdle == "wait" or locate(name).state ~= "down"
end

-- ---------------------------------------------------------------- farm every boss
-- the bosses alive in this server that this body may fight, in the order asked for. A parked one is measured to the
-- place the body would fly to (its spawn), as the trip is made (through the portals when shorter), and one further
-- than `bossMaxTrip` is not wanted: a boss across the sea does not keep the body from the level farm.
local function aliveBosses()
  local out, seen = {}, {}
  local root = BF.root()
  if not root then return out end
  local known, level, margin, t = bossCatalogue().byName, BF.level(), O.bossMargin or 0, now()
  local reach = O.bossMaxTrip or 12000
  local function consider(name, model, near)
    if seen[name] or (aside[name] or 0) > t or model:GetAttribute("RaidBoss") then return end
    if not (known[name] or isBoss(model)) then return end
    local lv = tonumber(model:GetAttribute("Level")) or (known[name] and known[name].level) or 0
    local at = near and pivotOf(model) or (not near and meetPoint(name, model))
    if lv > level + margin or not at then return end
    local gap = BF.trip(root.Position, at)
    if gap > reach then return end
    seen[name] = true
    out[#out + 1] = { name = name, level = lv, gap = gap }
  end
  local v = scan()
  for name, models in pairs(v.enemies) do consider(name, models[1], true) end
  for name, models in pairs(v.parked) do consider(name, models[1], false) end
  if O.bossOrder == "level" then
    table.sort(out, function(a, b) return a.level > b.level end)
  else
    table.sort(out, function(a, b) return a.gap < b.gap end)
  end
  return out
end
local function allLoop(ctx)
  while B.alive and not ctx.stop do
    if not ctx:body(BODY_WAIT) then return end
    local target = aliveBosses()[1]
    if not target then BF.release(); return end
    local quest = O.bossQuest == true and questFor(target.name)
    if quest then takeQuest(ctx, quest) end
    local result = duel(ctx, target.name)
    if result == "stopped" then return end
    if result == "dead" then
      -- (a boss just killed rests: it is not fought again at each respawn, and the level farm, and its quest, get the body back)
      aside[target.name], why[target.name] = now() + (O.bossRest or 120), "killed, resting"
      ctx:progress()
    end
    task.wait()
  end
end

-- ---------------------------------------------------------------- elite hunter (Third Sea)
-- The elite quest in hand: one mob, one kill, of a group no giver of this sea hands out (no elite group is in Quests.luau).
local function heldElite()
  local held = BF.quest()
  if not held then return nil end
  local name, count, kinds = nil, 0, 0
  for mob, need in pairs(type(held.Info.Task) == "table" and held.Info.Task or {}) do name, count, kinds = mob, tonumber(need) or 0, kinds + 1 end
  if kinds ~= 1 or count ~= 1 then return nil, held end
  if held.InternalQuestName == elite.group then return name, held end
  for _, quest in ipairs(BF.quests and BF.quests() or {}) do
    if quest.group == held.InternalQuestName then return nil, held end
  end
  return name, held
end
local function eliteProgress()
  local ok, count = BF.invoke(6, "EliteHunter", "Progress")              -- DialoguesList.luau:4827 (a count)
  local text = ok and string.format("%s elites so far.", tostring(count)) or ("No answer: " .. tostring(count))
  elite.last = text
  return text
end
-- One ask of the Elite Hunter, then up to 3 s for his quest to be in hand. Returns sent, answer, elite name, quest held.
local function eliteAnswer(ctx)
  local sent, answer = BF.invoke(8, "EliteHunter")                      -- DialoguesList.luau:4808 (answers a sentence)
  elite.last = sent and string.sub(tostring(answer), 1, 140) or ("No answer: " .. tostring(answer))
  local untilAt = now() + 3
  while sent and not heldElite() and now() < untilAt and not ctx.stop do
    ctx:beat("Asking the Elite Hunter")
    task.wait(0.1)
  end
  local name, held = heldElite()
  return sent, answer, name, held
end
local function askElite(ctx)
  -- (dialogue commands on CommF_ answer from afar, measured: he is asked from where the body is, and only flown to
  -- when that ask gets no answer at all; the name is NPCManager/NPCList.luau:1255)
  local sent, answer, name, held = eliteAnswer(ctx)
  if not sent and not ctx.stop then
    local at = npcAt("Elite Hunter") or BF.findNpc(ctx, "Elite Hunter", "Castle on the Sea")
    if not at then elite.last = "The Elite Hunter was not found."; elite.nextAt = now() + 120; return false end
    local ok, whyNot = BF.fly(at + Vector3.new(0, 3, 4), ctx, { note = "To the Elite Hunter" })
    if not ok then elite.last = "Could not reach the Elite Hunter: " .. tostring(whyNot); elite.nextAt = now() + 60; return false end
    sent, answer, name, held = eliteAnswer(ctx)
  end
  -- The quest in hand is dropped only when his answer names a quest as what stands in the way. His sentences are made
  -- by the server: the dump has only the call (DialoguesList.luau:4808-4816, the answer shown as it comes), never their
  -- words, so "names a quest" is read from the answer itself and is UNPROVEN until his answers are seen live.
  local blocked = not name and sent and BF.quest() ~= nil and type(answer) == "string" and string.find(string.lower(answer), "quest", 1, true) ~= nil
  if blocked and BF.dropQuest() then
    ctx:sleep(0.5, "Dropping another quest")
    sent, answer, name, held = eliteAnswer(ctx)
  end
  if name then
    elite.group, elite.name = held.InternalQuestName, name
    BF.say("Elite quest: " .. name)
    ctx:progress()
    return true
  end
  BF.say("Elite Hunter: " .. elite.last)
  elite.nextAt = now() + (O.bossEliteWait or 300)
  return false
end
local function eliteFight(ctx, target)
  local before = deathMark()
  local result = engage(ctx, target)
  if guard(ctx, target, result, before) then elite.nextAt = now() + 1800; return false end
  if result == "dead" then
    BOSS.elites += 1
    BF.say("Elite down: " .. target .. ". " .. eliteProgress())
    elite.group = nil
    ctx:sleep(2, "Elite paid")
  elseif result ~= "died" and result ~= "stopped" then
    elite.nextAt = now() + 60
    return false
  end
  return result ~= "stopped"
end
local function eliteLoop(ctx)
  local lookSince
  while B.alive and not ctx.stop do
    if not ctx:body(BODY_WAIT) then return end
    local target = heldElite()
    if not target then
      lookSince = nil
      if not askElite(ctx) then BF.release(); return end
    elseif locate(target).state == "down" then
      lookSince = lookSince or now()
      if now() - lookSince > 120 then
        BF.say(target .. " was nowhere for 2 min: the elite quest is dropped")
        BF.dropQuest()
        elite.group, elite.nextAt = nil, now() + (O.bossEliteWait or 300)
        BF.release()
        return
      end
      ctx:sleep(2, "Looking for " .. target)
    else
      lookSince = nil
      if not eliteFight(ctx, target) then BF.release(); return end
    end
    task.wait()
  end
end

-- ---------------------------------------------------------------- Cake Prince / Dough King (Third Sea)
-- The kills left, from the game's own sentence (DialoguesList.luau:4283); "open the portal now" = he can be called (line 4286).
local function cakeAsk()
  local ok, text = BF.invoke(8, "CakePrinceSpawner", true)
  cake.askedAt = now()
  if not ok or type(text) ~= "string" then cake.last = "No answer: " .. tostring(text); return end
  cake.ready = string.find(text, "open the portal now", 1, true) ~= nil
  cake.left = tonumber(string.match(text, "%d+"))
  cake.last = cake.ready and "The portal can be opened now." or (cake.left and string.format("%d kills left.", cake.left) or string.sub(text, 1, 140))
end
-- The cake mobs: the mobs of the Cake island quests of the game's table (Quests.luau:41-42). That their kills count is from public hubs.
local function cakeMobs()
  local out = {}
  for _, quest in ipairs(BF.quests and BF.quests() or {}) do
    if string.sub(quest.group, 1, 9) == "CakeQuest" and #quest.spawns > 0 then out[#out + 1] = quest end
  end
  return out
end
-- The Prince or the King alive: by the names public hubs use, else any IsBoss body near the cake mobs' spawns.
local CAKE_BOSSES = { "Cake Prince", "Dough King" }
local function cakeBoss()
  local bosses = scan().bosses
  for _, name in ipairs(CAKE_BOSSES) do
    if (bosses[name] or scan().enemies[name]) and not ((aside[name] or 0) > now()) then return name end
  end
  local quests = cakeMobs()
  local centre = quests[1] and quests[1].spawns[1]
  if not centre then return nil end
  for name, models in pairs(bosses) do
    local at = pivotOf(models[1])
    if at and (at - centre).Magnitude < 2500 and not ((aside[name] or 0) > now()) then return name end
  end
  return nil
end
local function cakeSummon(ctx)
  cake.tries += 1
  if cake.tries > 3 then
    cake.tries, cake.nextAt = 0, now() + 300
    BF.say("The Cake Prince did not come after 3 calls: tried again in 5 min")
    return false
  end
  local at = npcAt("drip_mama")                                         -- NPCManager/NPCList.luau:1603
  if at then
    local ok = BF.fly(at + Vector3.new(0, 3, 4), ctx, { note = "To drip_mama" })
    if not ok then return false end
  end
  local sent, answer = BF.invoke(8, "CakePrinceSpawner")                -- DialoguesList.luau:4294
  cake.last = sent and string.sub(tostring(answer), 1, 140) or ("No answer: " .. tostring(answer))
  BF.say("Cake Prince: " .. cake.last)
  local untilAt = now() + 20
  while now() < untilAt and not ctx.stop do
    if cakeBoss() then cake.tries = 0; ctx:progress(); return true end
    ctx:beat("Waiting for the Cake Prince")
    task.wait(0.5)
  end
  cake.askedAt = -1e9
  return true
end
-- the nearest living cake mob, fought; with none, over their spawns in turn
local function cakeHunt(ctx, quests, state)
  local root = BF.root()
  if not root then return "none" end
  local best, bestGap
  for _, quest in ipairs(quests) do
    local mob = BF.mobs(quest.mob, root.Position)[1]
    local gap = mob and (mob.HumanoidRootPart.Position - root.Position).Magnitude
    if mob and (not bestGap or gap < bestGap) then best, bestGap = mob, gap end
  end
  if best then
    local name = best.Name
    return BF.fight(best, ctx, function()
      local mine = BF.root()
      return BF.mobs(name, mine and mine.Position)
    end)
  end
  state.mark = (state.mark or 0) % #quests + 1
  local quest = quests[state.mark]
  if BF.fly(quest.spawns[1] + Vector3.new(0, O.height or 25, 0), ctx, { note = "To the cake mobs" }) then
    ctx:sleep(O.spawnWait or 3, "Waiting for cake mobs")
  end
  return "none"
end
local function cakeLoop(ctx)
  local state = {}
  while B.alive and not ctx.stop do
    if not ctx:body(BODY_WAIT) then return end
    if now() - cake.askedAt > 30 then cakeAsk() end
    local boss = cakeBoss()
    local quests = cakeMobs()
    local before = deathMark()
    local result
    if boss then
      result = engage(ctx, boss)
      if result == "dead" then BOSS.cakes += 1; cake.askedAt = -1e9; BF.say(boss .. " down") end
      if result == "stuck" or result == "unreached" then aside[boss], why[boss] = now() + 120, result end
      -- (gone before the fight: set aside a little, like the other bosses, so the loop does not spin on it unheard)
      if result == "gone" then aside[boss], why[boss] = now() + 30, "gone" end
      ctx:beat("After " .. boss)
    elseif cake.ready and O.bossCakeSummon == true then
      cakeSummon(ctx)
    elseif #quests == 0 then
      cake.last, cake.nextAt = "No cake mob spawns here (Third Sea, Cake island).", now() + 300
      BF.release()
      return
    else
      result = cakeHunt(ctx, quests, state)
      -- (no cake mob alive for 2 min: not waited for for ever)
      if result == "none" then state.emptySince = state.emptySince or now() else state.emptySince = nil end
      if state.emptySince and now() - state.emptySince > 120 then
        cake.nextAt, state.emptySince = now() + 300, nil
        BF.say("No cake mob alive for 2 min: the Cake Prince farm rests 5 min")
      end
    end
    if guard(ctx, boss or "the cake mobs", result, before) then cake.nextAt = now() + 1800; BF.release(); return end
    if result == "stopped" or now() < cake.nextAt then BF.release(); return end
    task.wait()
  end
end

-- ---------------------------------------------------------------- Factory (Second Sea)
-- The Factory's target. "Core" is the name public hubs use (research/scripts.md, S5): NOT in the dump.
local CORE = "Core"
local function coreAlive()
  local v = scan()
  return v.enemies[CORE] ~= nil or v.parked[CORE] ~= nil
end
local function factoryLoop(ctx)
  while B.alive and not ctx.stop do
    if not ctx:body(BODY_WAIT) then return end
    if not coreAlive() then BF.release(); return end
    local before = deathMark()
    local result = engage(ctx, CORE)
    if guard(ctx, "the Factory's Core", result, before) then factory.nextAt = now() + 1800; BF.release(); return end
    if result == "dead" then BOSS.cores += 1; BF.say("The Factory's Core is down") end
    if result == "stopped" then return end
    if result ~= "dead" and result ~= "died" then
      factory.nextAt = now() + 60
      BF.say("The Core: " .. tostring(result) .. ". Tried again in 1 min")
      BF.release()
      return
    end
    task.wait()
  end
end

-- ---------------------------------------------------------------- pirate raid (Third Sea, Castle on the Sea)
-- The castle: the game's own island mark (_WorldOrigin.Locations; the name is in Modules/IslandLocationLookup.luau:6).
local function castle()
  local origin = workspace:FindFirstChild("_WorldOrigin")
  local places = origin and origin:FindFirstChild("Locations")
  local mark = places and places:FindFirstChild("Castle on the Sea")
  return mark and mark:IsA("BasePart") and mark.Position or nil
end
-- the names of mobs that live at the castle anyway (a spawn mark near it): those are not raiders. Kept 60 s.
local locals, localsAt = {}, -1e9
local function residents(at, radius)
  if now() - localsAt < 60 then return locals end
  locals, localsAt = {}, now()
  local origin = workspace:FindFirstChild("_WorldOrigin")
  local marks = origin and origin:FindFirstChild("EnemySpawns")
  for _, mark in ipairs(marks and marks:GetChildren() or {}) do
    local name = mark:IsA("BasePart") and string.match(mark.Name, "^(.-) %[Lv%.")
    if name and (mark.Position - at).Magnitude < radius + 300 then locals[name] = true end
  end
  return locals
end
-- living bodies near the castle with no spawn there: { model, at, near }
local function raiders()
  local at = castle()
  if not at then return {} end
  local radius = O.bossRaidRadius or 750
  local home, out = residents(at, radius), {}
  local v = scan()
  for _, group in ipairs({ v.enemies, v.parked }) do
    for name, models in pairs(group) do
      if not home[name] then
        for _, model in ipairs(models) do
          local spot = pivotOf(model)
          if spot and (spot - at).Magnitude < radius then out[#out + 1] = { model = model, at = spot, near = group == v.enemies } end
        end
      end
    end
  end
  local root = BF.root()
  if root then table.sort(out, function(a, b) return (a.at - root.Position).Magnitude < (b.at - root.Position).Magnitude end) end
  return out
end
local function raidOne(ctx, list)
  local first = list[1]
  if not first.near then
    -- (a parked raider comes into workspace.Enemies when the body is near the castle)
    local ok, whyNot = BF.fly(first.at + Vector3.new(0, O.height or 25, 0), ctx, { note = "To the Castle on the Sea" })
    if not ok then return whyNot == "dead" and "died" or (whyNot == "stopped" and "stopped" or "unreached") end
    ctx:sleep(2, "At the castle")
    return "moved"
  end
  local name = first.model.Name
  return BF.fight(first.model, ctx, function()
    local others = {}
    for _, row in ipairs(raiders()) do
      if row.near and row.model.Name == name then others[#others + 1] = row.model end
    end
    return others
  end)
end
local function piratesLoop(ctx)
  local moves = 0
  while B.alive and not ctx.stop do
    if not ctx:body(BODY_WAIT) then return end
    local list = raiders()
    if #list == 0 then BF.release(); return end
    local before = deathMark()
    local result = raidOne(ctx, list)
    if guard(ctx, "the pirate raid", result, before) then pirates.nextAt = now() + 1800; BF.release(); return end
    if result == "dead" then BOSS.raiders += 1; moves = 0 end
    if result == "moved" then moves += 1 end
    if result == "stopped" then return end
    if result == "unreached" or moves > 3 then
      -- (flown there and still none of them came near: not tried again at once)
      pirates.nextAt = now() + 120
      BF.say("The raiders could not be reached: tried again in 2 min")
      BF.release()
      return
    end
    task.wait()
  end
end

-- ---------------------------------------------------------------- start
local function start()
  -- (every death of the body is counted from its Humanoid, for the guard's deaths in a row)
  task.spawn(watchBody, B.LP.Character)
  B.connect(B.LP.CharacterAdded, watchBody, "bloxfruits.bossDeaths")
  BF.job({ id = "bossFactory", label = "Factory raid", priority = 66, switch = "bloxfruits.bossFactory", quiet = 25, patience = 400,
    want = function() return O.bossFactory == true and BF.sea() == 2 and now() >= factory.nextAt and coreAlive() end, run = factoryLoop })
  BF.job({ id = "bossPirates", label = "Pirate raid", priority = 65, switch = "bloxfruits.bossPirates", quiet = 25, patience = 400,
    want = function() return O.bossPirates == true and BF.sea() == 3 and now() >= pirates.nextAt and #raiders() > 0 end, run = piratesLoop })
  BF.job({ id = "bossElite", label = "Elite hunter", priority = 54, switch = "bloxfruits.bossElite", quiet = 25, patience = 400,
    want = function() return O.bossElite == true and BF.sea() == 3 and now() >= elite.nextAt end, run = eliteLoop })
  BF.job({ id = "bossCake", label = "Cake Prince", priority = 53, switch = "bloxfruits.bossCake", quiet = 25, patience = 400,
    want = function() return O.bossCake == true and BF.sea() == 3 and now() >= cake.nextAt end, run = cakeLoop })
  BF.job({ id = "bossOne", label = "Farm one boss", priority = 52, switch = "bloxfruits.bossOne", quiet = 25, patience = 400, want = oneWanted, run = oneLoop })
  BF.job({ id = "bossAll", label = "Farm every boss", priority = 51, switch = "bloxfruits.bossAll", quiet = 25, patience = 400,
    want = function() return O.bossAll == true and #aliveBosses() > 0 end, run = allLoop })
end

-- ---------------------------------------------------------------- the tab
local function countLine()
  return string.format("%d bosses  ·  %d elites  ·  %d cake bosses  ·  %d cores  ·  %d raiders  ·  %d deaths in these fights", BOSS.kills, BOSS.elites,
    BOSS.cakes, BOSS.cores, BOSS.raiders, BOSS.deaths)
end
local function whereLine()
  local name = O.bossName or ""
  if name == "" then return "Pick a boss." end
  local left = (aside[name] or 0) - now()
  if left > 0 then return string.format("%s: left alone %d s more (%s).", name, math.ceil(left), why[name] or "") end
  local where, root = locate(name), BF.root()
  local gap = where.at and root and math.floor((where.at - root.Position).Magnitude) or 0
  if where.state == "here" then return string.format("%s is alive, %d studs away.", name, gap) end
  if where.state == "far" then return string.format("%s is alive, far off (%d studs).", name, gap) end
  return string.format("%s is not alive. %s", name, where.at and "Its spawn is known." or "No spawn of it is known.")
end
-- the summon items in the backpack or the hand (names: ItemConfig/Data/Index.luau:1190, 1210, 1230, "Storage Key")
local ITEMS = { "Hallow Essence", "Fist of Darkness", "God's Chalice" }
local function carried()
  local have = {}
  for _, name in ipairs(ITEMS) do
    local pack, body = B.LP:FindFirstChild("Backpack"), BF.char()
    if (pack and pack:FindFirstChild(name)) or (body and body:FindFirstChild(name)) then have[#have + 1] = name end
  end
  return #have > 0 and ("You carry: " .. table.concat(have, ", ") .. ".") or "You carry none of their items."
end
local function bossOptions()
  local out = {}
  for _, row in ipairs(bossCatalogue().list) do
    out[#out + 1] = { row.name, row.level > 0 and string.format("%s (Lv. %d)", row.name, row.level) or row.name }
  end
  if #out == 0 then out[1] = { "", "None found" } end
  return out
end
local function checkElite()
  task.spawn(function()
    local text = eliteProgress()
    Window.toast({ title = "Elite hunter", text = text, icon = "crown", time = 6 })
  end)
end
local function checkCake()
  task.spawn(function()
    cakeAsk()
    Window.toast({ title = "Cake Prince", text = cake.last, icon = "flame", time = 6 })
  end)
end

local function liveCard(page)
  local live = page:section({ title = "Bosses so far", icon = "activity", full = true })
  local counts = live:note({ icon = "gauge", text = countLine() })
  local where = live:note({ icon = "map-pin", text = "Pick a boss." })
  Motion.every(function()
    if not (counts.frame.Parent and Window.anyOpen()) then return end
    counts.set(countLine())
    local ok, text = pcall(whereLine)
    where.set(ok and text or "Pick a boss.")
  end, 2, "bloxfruits.bossStatus")
end
local function farmCards(page)
  local one = page:section({ title = "One boss", icon = "skull", desc = "Bosses of this sea, read from the game." })
  one:toggle({ id = "bloxfruits.bossOne", label = "Farm one boss", desc = "Flies to it and fights it, again and again.", default = false, children = function(sub)
    sub:dropdown({ id = "bloxfruits.bossName", label = "Boss", options = bossOptions() })
    sub:segmented({ id = "bloxfruits.bossIdle", label = "While it is down", options = { { "level", "Level farm" }, { "wait", "Wait at spawn" } }, width = 260 })
    sub:slider({ id = "bloxfruits.bossWaitMax", label = "Wait at most", tip = "Then the body is free for 2 min.", min = 60, max = 1800, step = 30, default = 600,
      suffix = " s" })
  end })
  local all = page:section({ title = "Every boss", icon = "swords" })
  all:toggle({ id = "bloxfruits.bossAll", label = "Farm every boss", desc = "Any boss alive in this server.", default = false, children = function(sub)
    sub:segmented({ id = "bloxfruits.bossOrder", label = "First", options = { { "near", "Nearest" }, { "level", "Highest level" } }, width = 260 })
    sub:slider({ id = "bloxfruits.bossMargin", label = "Up to this many levels above me", min = 0, max = 1000, step = 25, default = 0 })
    sub:slider({ id = "bloxfruits.bossRest", label = "Rest after a kill", tip = "That boss is left alone this long.", min = 0, max = 1800, step = 30,
      default = 120, suffix = " s" })
    sub:slider({ id = "bloxfruits.bossMaxTrip", label = "Farthest trip", tip = "Bosses further away are left alone.", min = 1000, max = 30000, step = 500,
      default = 12000, suffix = " st" })
  end })
  local rules = page:section({ title = "For every boss", icon = "shield", column = 2 })
  rules:toggle({ id = "bloxfruits.bossQuest", label = "Take its quest", desc = "When the boss has a quest you can take.", default = false, bindable = false })
  rules:slider({ id = "bloxfruits.bossDeaths", label = "Give up after deaths in a row", tip = "That boss is then left alone 30 min.", min = 1, max = 10, step = 1,
    default = 3 })
end
local function thirdSeaCards(page)
  local hunt = page:section({ title = "Elite hunter", icon = "crown", column = 2, desc = "Third Sea." })
  hunt:toggle({ id = "bloxfruits.bossElite", label = "Elite hunter", desc = "Takes his quest, finds the elite, kills it.", default = false, children = function(sub)
    sub:slider({ id = "bloxfruits.bossEliteWait", label = "Ask again after a no", min = 60, max = 1800, step = 30, default = 300, suffix = " s" })
  end })
  hunt:button({ id = "bloxfruits.bossEliteCheck", label = "Elites so far", desc = "Asks the game, takes nothing.", text = "Check", run = checkElite })
  local eliteNote = hunt:note({ icon = "info", text = elite.last })
  local prince = page:section({ title = "Cake Prince", icon = "flame", column = 2, desc = "Third Sea, Cake island." })
  prince:toggle({ id = "bloxfruits.bossCake", label = "Cake Prince", desc = "Farms the cake mobs, then fights him.", default = false, children = function(sub)
    sub:toggle({ id = "bloxfruits.bossCakeSummon", label = "Open the portal", desc = "Calls him when the game says it can.", default = false, bindable = false })
  end })
  prince:button({ id = "bloxfruits.bossCakeCheck", label = "Kills left", desc = "Asks the game, calls nothing.", text = "Check", run = checkCake })
  local cakeNote = prince:note({ icon = "info", text = cake.last })
  local raid = page:section({ title = "Pirate raid", icon = "anchor", column = 2, desc = "Castle on the Sea." })
  raid:toggle({ id = "bloxfruits.bossPirates", label = "Pirate raid", desc = "Fights raiders at the castle while they last.", default = false, children = function(sub)
    sub:slider({ id = "bloxfruits.bossRaidRadius", label = "Around the castle", min = 300, max = 2000, step = 50, default = 750, suffix = " st" })
  end })
  Motion.every(function()
    if not (eliteNote.frame.Parent and Window.anyOpen()) then return end
    eliteNote.set("Elite: " .. elite.last)
    cakeNote.set("Cake Prince: " .. cake.last)
  end, 1, "bloxfruits.bossThird")
end
local function eventCards(page)
  local sea = BF.sea()
  if sea == 3 then
    thirdSeaCards(page)
  else
    local note = page:section({ title = "Third Sea", icon = "crown", column = 2 })
    note:note({ icon = "info", text = "Elite hunter, Cake Prince and the pirate raid work in the Third Sea." })
  end
  local works = page:section({ title = "Factory raid", icon = "cpu", column = 2, desc = "Second Sea." })
  if sea == 2 then
    works:toggle({ id = "bloxfruits.bossFactory", label = "Factory raid", desc = "Fights the Core while it is up.", default = false, bindable = false })
  else
    works:note({ icon = "info", text = "The Factory raid works in the Second Sea." })
  end
end
local function summonCard(page)
  local s = page:section({ title = "Summoned bosses", icon = "ghost", column = 2, desc = "Not built: the game's code has no call for them." })
  s:note({ icon = "info", text = "Soul Reaper: called with a Hallow Essence; no command for it in the game's code." })
  s:note({ icon = "info", text = "rip_indra: his talk only switches a sword skin; no call that brings him." })
  s:note({ icon = "info", text = "Darkbeard: called with the Fist of Darkness; no command for it in the game's code." })
  s:note({ icon = "info", text = "Once one is alive, Farm every boss fights it." })
  local items = s:note({ icon = "package", text = carried() })
  Motion.every(function()
    if not (items.frame.Parent and Window.anyOpen()) then return end
    items.set(carried())
  end, 0.5, "bloxfruits.bossItems")
end
local function boss(page)
  liveCard(page)
  farmCards(page)
  eventCards(page)
  summonCard(page)
end

BF.parts[#BF.parts + 1] = { id = "boss", start = start, boss = boss,
  defaults = { bossOne = false, bossName = "", bossIdle = "level", bossWaitMax = 600, bossAll = false, bossOrder = "near", bossMargin = 0, bossRest = 120, bossMaxTrip = 12000, bossQuest = false,
    bossDeaths = 3, bossElite = false, bossEliteWait = 300, bossCake = false, bossCakeSummon = false, bossFactory = false, bossPirates = false,
    bossRaidRadius = 750 } }
end
do -- bloxfruits_combat.lua
-- ============================================================================
--  Blox Fruits     combat and comfort: kill aura, aim help, Ken, panic, safe
--                  mode, and the client-side extras (performance, sight,
--                  movement, session)
--
--  Read from the game's own code (dump 2753915549 v4630, `fast\` folder, paths
--  below are under it), never tried live: every line here is unproven until
--  measured. "instances" = the instances.json beside the dump.
--
--   * Who the game protects, read the way the game reads it: the player
--     attributes InSafeZone and PvpDisabled and the character's TempSafeZone
--     value (bloxfruits_esp.lua:138-144; CombatUtil.luau:1624-1628), allies as
--     the tag "Ally<name>" either way and two Marines as one side
--     (ObservationManager.luau:285), the crew as Data.CrewID (esp:129).
--   * A hit is the engine's BF.hit (Net RegisterAttack + Global.SendHitsToServer):
--     this part only chooses whom, and never moves the body to do it.
--   * Observation: owned = the character carries the tag "Ken"; on = the game's
--     ObservationManager (Global.OM).active; the game's own key handler does
--     OM:setActive(true) then CommE:FireServer("Ken", true)
--     (StarterCharacterScripts/Observation.luau:13, 59-63, 134; ObservationManager.luau:222).
--   * The extras send nothing to the server; each one is undone when switched
--     off and when the hub unloads.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion = B.S, B.Config, B.Window, B.Motion
local BF = B.BloxFruits
local O = BF.O
local function now() return os.clock() end

local WHITE = Color3.new(1, 1, 1)
local SEA_LEVEL = -4                 -- ReplicatedStorage/Modules/World/Water.luau:2 (SEA_LEVEL = -4), the open sea's surface

-- ---------------------------------------------------------------- small readers
local function value(parent, name)
  local item = parent and parent:FindFirstChild(name)
  return item and item.Value
end
local function hasTag(inst, tag)
  local ok, yes = pcall(function() return inst:HasTag(tag) end)
  return ok and yes == true
end
local function teamName(player)
  local team = player.Team
  return team and team.Name or ""
end
local function toast(title, text, good)
  BF.say(title .. ": " .. text)
  Window.toast({ title = title, text = text, icon = "info", tone = good and "ok" or nil, time = 5 })
end
local function commE()
  local remotes = S.ReplicatedStorage:FindFirstChild("Remotes")
  return remotes and remotes:FindFirstChild("CommE")
end

-- ---------------------------------------------------------------- who may be fought
-- On our side, as the game itself decides it: an ally tag either way, or two Marines
-- (ObservationManager.luau:285, 309-312; UIController.luau:2516), the same crew (Data.CrewID,
-- ReplicatedPlayerData.luau:230 via bloxfruits_esp.lua:129), or a friend on the hub's own list.
local function onMySide(player)
  local me = B.LP
  if hasTag(player, "Ally" .. me.Name) or hasTag(me, "Ally" .. player.Name) then return "ally" end
  local crew = value(player:FindFirstChild("Data"), "CrewID")
  if crew and crew ~= "" and crew == value(me:FindFirstChild("Data"), "CrewID") then return "crew" end
  if teamName(player) == "Marines" and teamName(me) == "Marines" then return "marine" end
  local Roster = B.Roster
  local entry = Roster and Roster.byPlayer and Roster.byPlayer[player]
  if entry and Roster.isFriend(entry) then return "friend" end
  return nil
end
-- why a player may not be fought, or nil
local function shielded(player)
  local character = player.Character
  -- InSafeZone: player attribute every client gets (instances); TempSafeZone: BoolValue in the character (TempSafeZones.luau:32)
  if player:GetAttribute("InSafeZone") == true or (character and value(character, "TempSafeZone") == true) then return "safe zone" end
  -- PvpDisabled: read off the other player by the game's own hit code (CombatUtil.luau:1628)
  if player:GetAttribute("PvpDisabled") == true then return "PvP off" end
  -- (a fresh spawn's shield takes nothing: not worth a swing)
  if character and character:FindFirstChildOfClass("ForceField") then return "spawn shield" end
  return onMySide(player)
end
-- Our own side of it: from inside a safe zone (Global.InSafeZone, Comm.luau:16) no player hit counts
-- (CombatUtil.luau:1624), and with our own PvP off no player is fought either.
local function mayFightPlayers()
  local me = B.LP
  local global = BF.mod("Global")
  if me:GetAttribute("InSafeZone") == true or (type(global) == "table" and global.InSafeZone == true) then return false end
  return me:GetAttribute("PvpDisabled") ~= true
end

-- a straight line from the body to the target with nothing solid on it (the two characters left out)
local WATER = { part = nil, height = SEA_LEVEL, at = -1e9 }
local rays = RaycastParams.new()
rays.FilterType = Enum.RaycastFilterType.Exclude
rays.RespectCanCollide = true        -- (the game's zone parts do not collide: they do not stop a swing either)
local function inSight(from, model, point)
  local skip = { model }
  local mine = BF.char()
  if mine then skip[#skip + 1] = mine end
  if WATER.part then skip[#skip + 1] = WATER.part end
  rays.FilterDescendantsInstances = skip
  return workspace:Raycast(from, point - from, rays) == nil
end

-- Every living body that may be fought from `from` within `radius`, nearest first: { model, root, hum, away, player }.
-- opts = { npcs, players, sight, skipBoss }
local function candidates(from, radius, opts)
  local out = {}
  if opts.npcs then
    -- workspace.Enemies, nearest first (the engine's BF.mobs); IsBoss: Enemies.<mob> attribute (BossCutsceneController.luau:30 via esp:89)
    for _, mob in ipairs(BF.mobs(nil, from)) do
      local root, hum = mob:FindFirstChild("HumanoidRootPart"), mob:FindFirstChildOfClass("Humanoid")
      local away = root and (root.Position - from).Magnitude
      if away and away > radius then break end
      if root and hum and not (opts.skipBoss and mob:GetAttribute("IsBoss") == true) then
        out[#out + 1] = { model = mob, root = root, hum = hum, away = away }
      end
    end
  end
  if opts.players and mayFightPlayers() then
    for _, player in ipairs(S.Players:GetPlayers()) do
      local character = player ~= B.LP and player.Character
      local root = character and character:FindFirstChild("HumanoidRootPart")
      local hum = character and character:FindFirstChildOfClass("Humanoid")
      -- (a player the aura left alone is skipped too: BF.mobs does that only for mobs)
      if root and hum and hum.Health > 0 and not ((BF.shunned[character] or 0) > now()) then
        local away = (root.Position - from).Magnitude
        if away <= radius and not shielded(player) then out[#out + 1] = { model = character, root = root, hum = hum, away = away, player = player } end
      end
    end
  end
  table.sort(out, function(a, b) return a.away < b.away end)
  if not opts.sight then return out end
  local seen = {}
  for index = 1, math.min(#out, 12) do
    local item = out[index]
    if inSight(from, item.model, item.root.Position) then seen[#seen + 1] = item end
  end
  return seen
end

-- ============================================================================ 1. kill aura
-- (a strong table the engine prunes: a weak key could vanish while the mob still stands, and its count start again)
local AURA = { hits = 0, kills = 0, last = "Nothing fought yet.", struck = BF.keep({}), toldSkills = false }
local AURA_NO_LOSS = 10              -- seconds struck with no health lost before a body is left alone
local AURA_SHUN = 45                 -- and for how long
-- A weapon that can only hurt with its skills: BF.hit sends nothing with it (bloxfruits.lua BF.hit), so the aura has nothing to do.
local function auraCanSwing()
  if BF.method(BF.weapon()) ~= "skills" then
    AURA.toldSkills = false
    return true
  end
  if not AURA.toldSkills then
    AURA.toldSkills = true
    BF.say("Kill aura: this weapon only hurts with its skills, so the aura waits. Hold a melee or a sword.")
    AURA.last = "Waiting: the weapon has no basic attack."
  end
  return false
end
local function auraList()
  local root = BF.root()
  if not root then return {} end
  return candidates(root.Position, O.auraRadius or 40,
    { npcs = O.auraNpcs ~= false, players = O.auraPlayers == true, sight = O.auraSight ~= false, skipBoss = O.auraSkipBoss == true })
end
local function mark(item)
  local got = AURA.struck[item.model]
  -- (`lost` = when it last lost health, or when it was first struck)
  if got then got.at = now() else AURA.struck[item.model] = { hum = item.hum, health = item.hum.Health, at = now(), lost = now() } end
end
-- what the hits did: a kill or lost health is progress; a body struck for 10 s that lost nothing is left alone for 45 s
-- (it is out of the swing's reach, or the server does not take it), and one not struck for 10 s is forgotten
local function settle(ctx)
  for model, entry in pairs(AURA.struck) do
    if not model.Parent or entry.hum.Health <= 0 then
      if now() - entry.at < 4 then
        AURA.kills += 1
        BF.count.kills += 1
        AURA.last = "Down: " .. model.Name
        ctx:progress()
      end
      AURA.struck[model] = nil
    elseif entry.hum.Health < entry.health - 0.01 then
      entry.health, entry.lost = entry.hum.Health, now()
      ctx:progress()
    elseif now() - entry.at > 10 then
      AURA.struck[model] = nil
    elseif now() - entry.lost > AURA_NO_LOSS then
      BF.shunned[model] = now() + AURA_SHUN
      AURA.struck[model] = nil
      AURA.last = "Left alone: " .. model.Name
      BF.say(string.format("Kill aura: %s lost no health in %d s: left alone for %d s", model.Name, AURA_NO_LOSS, AURA_SHUN))
    end
  end
end
-- (never moves the body: the pilot is let go, and the player walks where they like while it swings)
local function auraRun(ctx)
  BF.release()
  while B.alive and not ctx.stop do
    if not ctx:body(40) then return end
    -- (`want` is false too then, so the director takes this as an end, not a failure)
    if not auraCanSwing() then return end
    local list = auraList()
    local first = list[1]
    if first then
      local others = {}
      -- (the whole pack only when the engine's own "One swing hits them all" is on; the game allows up to 10, NOTES.md)
      if O.multi then
        for index = 2, math.min(#list, 10) do others[#others + 1] = list[index].model end
      end
      if BF.hit(first.model, others) then
        AURA.hits += 1
        for index = 1, 1 + #others do mark(list[index]) end
      end
      ctx:beat(string.format("Kill aura: %s  %d st", first.model.Name, math.floor(first.away + 0.5)))
    else
      ctx:beat("Kill aura: nothing in reach")
    end
    settle(ctx)
    task.wait(0.05)
  end
end

-- ============================================================================ 2. aim help
-- The game's Mouse casts its Hit from the camera through the real cursor every frame (ReplicatedStorage/Mouse.luau:137-147,
-- the same reading bloxfruits_mastery.lua:379-394 relies on). So the camera is turned until the cursor's ray goes through the
-- target: the cursor itself is never moved, and nothing is sent.
local AIM = { target = nil, pickedAt = -1e9, step = "BASED.bfAimHelp", circle = nil }
local function aimPick(camera)
  local root = BF.root()
  if not root then return nil end
  local mouse = S.UserInputService:GetMouseLocation()
  local list = candidates(root.Position, O.aimRadius or 300, { npcs = O.aimNpcs ~= false, players = O.aimPlayers == true, sight = false })
  local best, bestGap
  local circle = O.aimCircle or 150
  for _, item in ipairs(list) do
    local point, onScreen = camera:WorldToViewportPoint(item.root.Position)
    if onScreen and point.Z > 0 then
      local gap = (Vector2.new(point.X, point.Y) - mouse).Magnitude
      if gap <= circle and (not bestGap or gap < bestGap) then best, bestGap = item, gap end
    end
  end
  return best
end
local function aimStep()
  if O.aimHelp ~= true or not Config.keyDown(O.aimKey) then
    AIM.target = nil
    return
  end
  local camera = workspace.CurrentCamera
  if not camera then return end
  local item = AIM.target
  if not item or not item.root.Parent or item.hum.Health <= 0 or now() - AIM.pickedAt > 0.1 then
    item = aimPick(camera)
    AIM.target, AIM.pickedAt = item, now()
  end
  if not item then return end
  -- the cursor's ray in the camera's own frame, then the camera turned so that ray points at the target
  local mouse = S.UserInputService:GetMouseLocation()
  local ray = camera:ViewportPointToRay(mouse.X, mouse.Y)
  local at = camera.CFrame
  local inCamera = at:VectorToObjectSpace(ray.Direction.Unit)
  camera.CFrame = CFrame.lookAt(at.Position, item.root.Position) * CFrame.fromRotationBetweenVectors(inCamera, Vector3.new(0, 0, -1))
end
local function circleStep()
  local ring = AIM.circle
  if not ring then return end
  local show = O.aimHelp == true and O.aimShowCircle ~= false
  if ring.Visible ~= show then ring.Visible = show end
  if not show then return end
  local mouse = S.UserInputService:GetMouseLocation()
  local size = (O.aimCircle or 150) * 2
  ring.Position = UDim2.fromOffset(mouse.X, mouse.Y)
  if ring.Size.X.Offset ~= size then ring.Size = UDim2.fromOffset(size, size) end
end
local function makeCircle()
  local screen = B.screen(60)
  local ring = Instance.new("Frame")
  ring.Name = "AimCircle"
  ring.AnchorPoint = Vector2.new(0.5, 0.5)
  ring.BackgroundTransparency = 1
  ring.Visible = false
  ring.Parent = screen
  local corner = Instance.new("UICorner")
  corner.CornerRadius = UDim.new(1, 0)
  corner.Parent = ring
  local stroke = Instance.new("UIStroke")
  stroke.Color = WHITE
  stroke.Transparency = 0.4
  stroke.Thickness = 1.5
  stroke.Parent = ring
  AIM.circle = ring
end

-- ============================================================================ 3. Observation (Ken)
-- Owned: the character carries the CollectionService tag "Ken" (Observation.luau:134; useInstinct.luau:24).
-- On: Global.OM.active (Observation.luau:13, 145). The game's own switch: OM.radius = 0, OM:setActive(not active), then
-- CommE:FireServer("Ken", active) (Observation.luau:59-63; ObservationManager.luau:222). The game refuses it with "KenDisabled"
-- in the character (:59, :153) and turns it off itself through Remotes.DisableKen for 5 s (:29-46).
-- Dodges: player attributes KenDodgesLeft / KenMaxDodges, 8 when unset (Observation.luau:83-84).
local KEN = { tryAt = -1e9, quietUntil = 0, refused = 0 }
local function kenOm()
  local global = BF.mod("Global")
  local om = type(global) == "table" and global.OM
  return type(om) == "table" and om or nil
end
local function kenTick()
  if O.autoKen ~= true or now() < KEN.quietUntil then return end
  local character = BF.char()
  if not (character and BF.alive() and hasTag(character, "Ken")) or character:FindFirstChild("KenDisabled") then return end
  local om = kenOm()
  if not om or om.active == true or now() - KEN.tryAt < 1.5 then return end
  KEN.tryAt = now()
  local ok = BF.game(function()
    om.radius = 0
    om:setActive(true)
  end)
  local remote = commE()
  if ok and remote then pcall(remote.FireServer, remote, "Ken", true) end      -- Observation.luau:63
end
-- the game said no (DisableKen soon after our ask): wait as the game does, and after five in a row stop asking for 2 min
local function kenRefused()
  KEN.quietUntil = math.max(KEN.quietUntil, now() + 5)
  if now() - KEN.tryAt < 3 then
    KEN.refused += 1
    if KEN.refused >= 5 then
      KEN.refused = 0
      KEN.quietUntil = now() + 120
      BF.say("Auto Ken: the game turned it off five times in a row: not asked again for 2 min")
    end
  end
end
local function kenLine()
  local character = BF.char()
  if not (character and hasTag(character, "Ken")) then return "This body does not know Observation." end
  local om = kenOm()
  local me = B.LP
  local most = tonumber(me:GetAttribute("KenMaxDodges")) or 8
  local left = tonumber(me:GetAttribute("KenDodgesLeft")) or most
  return string.format("Observation %s  ·  dodges left %d/%d", (om and om.active) and "on" or "off", left, most)
end

-- ============================================================================ 4. panic
-- Panic is the engine's own Stop everything (Autopilot off first, every job switch and every BF.offToo id off, the body
-- let go), then a short job of its own that flies the body 300 studs up and holds it there. As a job it owns the body the
-- director's way: nothing else (a chain, a trip) can fly the same body at the same time.
local PANIC = { active = false, up = nil, deadline = 0, hold = 15, line = "Bind a key, or use the button." }
local SAFE = { anchor = nil, up = nil, who = "", quietUntil = 0, warned = false, hop = false, hopAt = -1e9, line = "Off." }
local function panicEnd(line)
  PANIC.active, PANIC.up = false, nil
  PANIC.line = line
end
-- (only while it rises and holds; a deadline so a panic the director never started does not stay wanted)
local function panicWanted()
  return PANIC.active and now() < PANIC.deadline
end
local function panic()
  if panicWanted() then return end
  BF.stopAll("Panic")
  local hold = math.clamp(O.panicHold or 15, 1, 120)
  SAFE.anchor, SAFE.up, SAFE.hop, SAFE.quietUntil = nil, nil, false, now() + hold + 5
  local root = BF.root()
  if not (root and BF.alive()) then
    panicEnd("Done. Everything is off (no body to lift).")
    Window.toast({ title = "Panic", text = "Everything off.", icon = "triangle-alert", time = 5 })
    return
  end
  PANIC.up, PANIC.hold = root.Position + Vector3.new(0, 300, 0), hold
  PANIC.active, PANIC.deadline = true, now() + hold + 60
  PANIC.line = "Rising 300 studs."
  Window.toast({ title = "Panic", text = "Everything off. Rising 300 studs.", icon = "triangle-alert", time = 5 })
end
local function panicRun(ctx)
  local up = PANIC.up
  if not up then panicEnd("Done. Everything is off."); return end
  -- (flown straight up, not put there in one frame: the engine's rule for anything over 40 studs)
  local ok, why = BF.fly(up, ctx, { direct = true, note = "Panic" })
  if not ok then
    if why ~= "stopped" then panicEnd("Could not rise (" .. tostring(why) .. "). Everything is off.") end
    return
  end
  ctx:progress()
  local untilAt = now() + PANIC.hold
  while B.alive and not ctx.stop and now() < untilAt and BF.alive() do
    BF.holdAt(up)
    PANIC.line = string.format("Holding high up: %d s left.", math.ceil(untilAt - now()))
    ctx:sleep(0.2, "Panic: holding high up")
  end
  if not ctx.stop then panicEnd("Done. Everything is off.") end
end

-- ============================================================================ 5. safe mode
-- the nearest other player within `dist` of a point who is not on our side (an ally, the crew, a Marine with us, a friend)
local function threat(point, dist)
  local best, bestAway
  for _, player in ipairs(S.Players:GetPlayers()) do
    local character = player ~= B.LP and player.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    local hum = character and character:FindFirstChildOfClass("Humanoid")
    if root and hum and hum.Health > 0 then
      local away = (root.Position - point).Magnitude
      if away <= dist and (not bestAway or away < bestAway) and not onMySide(player) then best, bestAway = player, away end
    end
  end
  return best, bestAway
end
-- The game's own client refuses a hop while the character carries "InCombat" (StarterGui/ServerBrowser/LocalScript.luau:394-397);
-- the same read as bloxfruits_world.lua's inCombat.
local function inCombat()
  local character = BF.char()
  return character ~= nil and character:GetAttribute("InCombat") and true or false
end
local function farmRunning()
  local job = BF.running()
  return job ~= nil and job.switch ~= nil and job.id ~= "killAura" and job.id ~= "safeMode"
end
local function safeTick()
  if O.safeMode ~= true then
    SAFE.anchor, SAFE.up, SAFE.hop, SAFE.line = nil, nil, false, "Off."
    return
  end
  local dist = O.safeDist or 200
  if SAFE.anchor then
    local player = threat(SAFE.anchor, dist)
    if player then
      SAFE.who = player.Name
    else
      BF.say("Safe mode: " .. SAFE.who .. " left; the farm goes on")
      SAFE.anchor, SAFE.up, SAFE.hop, SAFE.line = nil, nil, false, SAFE.who .. " left. The farm goes on."
    end
    return
  end
  if now() < SAFE.quietUntil or not farmRunning() then return end
  local root = BF.root()
  if not root then return end
  local player, away = threat(root.Position, dist)
  if not player then return end
  SAFE.who = player.Name
  -- The world part's server hop (BF.hop, bloxfruits_world.lua). A farm keeps the body "InCombat", and the hop is refused
  -- then, so the body always rises first; safeRun asks for the hop once InCombat has gone.
  local hop = rawget(BF, "hop")
  SAFE.hop = O.safeAction == "hop" and type(hop) == "function"
  if O.safeAction == "hop" and not SAFE.hop and not SAFE.warned then
    SAFE.warned = true
    BF.say("Safe mode: no server hop in this build; rising instead")
  end
  SAFE.anchor, SAFE.up, SAFE.hopAt = root.Position, nil, -1e9
  SAFE.line = player.Name .. (SAFE.hop and " came close: rising, then hopping server." or " came close: waiting up high.")
  BF.say(string.format("Safe mode: %s within %d st: the farm waits 200 studs up%s", player.Name, math.floor(away), SAFE.hop and ", then a server hop" or ""))
end
-- the hop, once the game would allow it (asked again at most once a minute while the body still waits here)
local function safeHop()
  local hop = rawget(BF, "hop")
  if not (SAFE.hop and type(hop) == "function") or inCombat() or now() - SAFE.hopAt < 60 then return end
  SAFE.hopAt = now()
  SAFE.line = SAFE.who .. " came close: hopping server."
  BF.say("Safe mode: out of combat, asking for a server hop")
  task.spawn(function() B.try("bloxfruits.safeHop", hop) end)
end
-- The job that pauses the farm: it has a higher priority, so the director gives it the body; when they leave, `want`
-- turns false, the director lets it go and the farm takes the body back by itself.
-- (the body somewhere else than where safe mode left it: another job took it away, a trip say. The old anchor is
-- dropped and the threat measured again from where the body is now, so it never flies back to the old place)
local function safeReanchor()
  local root = BF.root()
  if not root then return false end
  if SAFE.up and (root.Position - SAFE.up).Magnitude < 30 then return true end       -- (still up there: the same wait)
  local player = threat(root.Position, O.safeDist or 200)
  if not player then
    SAFE.anchor, SAFE.up, SAFE.hop, SAFE.line = nil, nil, false, "Nobody close any more. The farm goes on."
    return false
  end
  SAFE.who, SAFE.anchor, SAFE.up = player.Name, root.Position, nil
  return true
end
local function safeRun(ctx)
  if not (SAFE.anchor and safeReanchor()) then return end
  local up = SAFE.up or (SAFE.anchor + Vector3.new(0, 200, 0))
  SAFE.up = up
  local ok, why = BF.fly(up, ctx, { direct = true, note = "Safe mode: rising" })
  if not ok then
    if why ~= "stopped" then
      SAFE.anchor, SAFE.up, SAFE.hop, SAFE.quietUntil = nil, nil, false, now() + 60
      BF.say("Safe mode: could not rise (" .. tostring(why) .. "): not tried again for 1 min")
    end
    return
  end
  ctx:progress()
  local started = now()
  while B.alive and not ctx.stop and SAFE.anchor do
    BF.holdAt(up)
    safeHop()
    if now() - started > (O.safeMax or 300) then
      -- (never for ever: after the longest wait the farm goes on, and safe mode keeps quiet for 2 min)
      BF.say(string.format("Safe mode: %s stayed %d s; the farm goes on", SAFE.who, O.safeMax or 300))
      SAFE.anchor, SAFE.up, SAFE.hop, SAFE.quietUntil, SAFE.line = nil, nil, false, now() + 120, SAFE.who .. " stayed too long. The farm goes on."
      return
    end
    ctx:sleep(0.5, (SAFE.hop and inCombat()) and "Safe mode: waiting to be out of combat to hop" or ("Safe mode: waiting for " .. SAFE.who .. " to leave"))
  end
end

-- ============================================================================ 6-8. the extras (client only)
-- Lighting values held by this part: the game's own value is kept (and follows the game when it writes a new one),
-- and is put back when the switch is off.
local LIGHT = BF.keep({})      -- instance -> { [prop] = { game, wrote, seen } } (strong: the game's own value must not be lost)
local tickId = 0
local function same(a, b)
  if type(a) == "number" and type(b) == "number" then return math.abs(a - b) < 1e-3 end
  if typeof(a) == "Color3" and typeof(b) == "Color3" then return math.abs(a.R - b.R) + math.abs(a.G - b.G) + math.abs(a.B - b.B) < 1e-3 end
  return a == b
end
local function hold(inst, prop, want)
  local ok, current = pcall(function() return inst[prop] end)
  if not ok then return end
  local props = LIGHT[inst]
  if not props then props = {}; LIGHT[inst] = props end
  local rec = props[prop]
  if not rec then rec = { game = current }; props[prop] = rec end
  if rec.wrote ~= nil and not same(current, rec.wrote) then rec.game = current end     -- (the game wrote a new one)
  if not same(current, want) then pcall(function() inst[prop] = want end) end
  rec.wrote, rec.seen = want, tickId
end
local function letGo(inst, prop, rec)
  pcall(function()
    if same(inst[prop], rec.wrote) then inst[prop] = rec.game end
  end)
end
local function letGoAll(onlyStale)
  for inst, props in pairs(LIGHT) do
    for prop, rec in pairs(props) do
      if not onlyStale or rec.seen ~= tickId then
        letGo(inst, prop, rec)
        props[prop] = nil
      end
    end
  end
end
local function lightTick()
  tickId += 1
  local L = S.Lighting
  if O.fullBright == true then
    hold(L, "Ambient", WHITE)
    hold(L, "OutdoorAmbient", WHITE)
    hold(L, "Brightness", 2)
  end
  if O.noFog == true then
    hold(L, "FogEnd", 100000)
    -- Lighting.BaseAtmosphere (instances; TeleportLoadingFX.luau:78 clones it). LightingLayers are left alone: the game's
    -- movement reads them (Movement + Swim.luau:344-350, "LeviathanFog").
    for _, child in ipairs(L:GetChildren()) do
      if child:IsA("Atmosphere") then
        hold(child, "Density", 0)
        hold(child, "Haze", 0)
      end
    end
  end
  if O.fixTime == true then hold(L, "ClockTime", math.clamp(O.timeOfDay or 12, 0, 24)) end
  if O.perfShadows == true then hold(L, "GlobalShadows", false) end
  letGoAll(true)
end

-- (`particles`: effect -> the watch on its Enabled, only for effects this part switched off; `shakeWas`: the game's own
-- camera shake state when this part turned it off)
local EX = { fast = false, quality = nil, particlesOn = false, particles = BF.keep({}), particleConn = nil, cover = nil, coverMode = "off", cap = 0,
  capSaved = nil, shake = false, shakeWas = true, hidden = BF.keep({}), clip = BF.keep({}), hideAt = -1e9 }
-- The game's own Fast Mode (its settings menu: Settings/LocalScript.luau:453-483 calls Util.FastModeToggle(true/false)).
-- It sets map materials to SmoothPlastic (put back on false) and DESTROYS textures (FastModeToggle.luau:30-42), then tells
-- its own OptimizerClientActor (client only: no FireServer in OptimizerClient.luau). Already on by the player: left alone.
local function fastTick()
  local want = O.perfFast == true
  if want and not EX.fast then
    local toggle, global = BF.mod("Util", "FastModeToggle"), BF.mod("Global")
    if type(toggle) ~= "function" then return end
    if type(global) == "table" and global.FastMode == true then EX.fast = "theirs"; return end
    EX.fast = true
    task.spawn(function() BF.game(toggle, true) end)
  elseif not want and EX.fast then
    local toggle = BF.mod("Util", "FastModeToggle")
    if EX.fast == true and type(toggle) == "function" then task.spawn(function() BF.game(toggle, false) end) end
    EX.fast = false
  end
end
local function rendering()
  local ok, r = pcall(function() return settings().Rendering end)
  return ok and r or nil
end
local function qualityTick()
  local r = rendering()
  if not r then return end
  if O.perfQuality == true and EX.quality == nil then
    local ok, level = pcall(function() return r.QualityLevel end)
    if ok then
      EX.quality = level
      pcall(function() r.QualityLevel = Enum.QualityLevel.Level01 end)
    end
  elseif O.perfQuality ~= true and EX.quality ~= nil then
    pcall(function() r.QualityLevel = EX.quality end)
    EX.quality = nil
  end
end
local FX = { ParticleEmitter = true, Trail = true, Beam = true, Smoke = true, Fire = true, Sparkles = true }
-- Only an effect that was on is switched off, and it is remembered with a watch on its Enabled: if the game turns it
-- on again itself, it is no longer off because of this part and is forgotten. So the put-back turns on only effects
-- that are still off because of this part, never one the game switched off since.
local function quiet(inst)
  local kept = EX.particles
  if not EX.particlesOn or not FX[inst.ClassName] or B.owns(inst) or kept[inst] ~= nil or not inst.Enabled then return end
  inst.Enabled = false
  kept[inst] = inst:GetPropertyChangedSignal("Enabled"):Connect(function()
    local watch = kept[inst]
    if watch and inst.Enabled then
      kept[inst] = nil
      pcall(function() watch:Disconnect() end)
    end
  end)
end
local function particlesBack()
  local kept = EX.particles
  for inst, watch in pairs(kept) do
    pcall(function() watch:Disconnect() end)
    if inst.Parent and not inst.Enabled then pcall(function() inst.Enabled = true end) end
  end
  table.clear(kept)
end
local function particlesTick()
  if O.perfParticles == true and not EX.particlesOn then
    EX.particlesOn = true
    EX.particleConn = B.connect(workspace.DescendantAdded, function(inst)
      if FX[inst.ClassName] then task.defer(function() pcall(quiet, inst) end) end
    end, "bloxfruits.noParticles")
    task.spawn(function()
      for index, inst in ipairs(workspace:GetDescendants()) do
        if not EX.particlesOn then return end
        if FX[inst.ClassName] then pcall(quiet, inst) end
        if index % 3000 == 0 then task.wait() end
      end
    end)
  elseif O.perfParticles ~= true and EX.particlesOn then
    EX.particlesOn = false
    if EX.particleConn then pcall(function() EX.particleConn:Disconnect() end) end
    EX.particleConn = nil
    particlesBack()
  end
end
-- "White screen" / "Black screen": no 3D drawn at all, and a plain colour over the game (the hub's window stays above it)
local function coverTick()
  local mode = O.afkScreen or "off"
  if mode == EX.coverMode then return end
  EX.coverMode = mode
  if mode == "off" then
    pcall(function() S.RunService:Set3dRenderingEnabled(true) end)
    if EX.cover then EX.cover.Visible = false end
    return
  end
  if not EX.cover then
    local frame = Instance.new("Frame")
    frame.Name = "AfkScreen"
    frame.Size = UDim2.fromScale(1, 1)
    frame.BorderSizePixel = 0
    frame.Parent = B.screen(5)
    EX.cover = frame
  end
  EX.cover.BackgroundColor3 = mode == "white" and WHITE or Color3.new(0, 0, 0)
  EX.cover.Visible = true
  pcall(function() S.RunService:Set3dRenderingEnabled(false) end)
end
local UNCAPPED = 9999                -- what src/25_world.lua:529 sets for "no cap"
local function capTick()
  if type(setfpscap) ~= "function" then return end
  local want = math.floor(tonumber(O.fpsCap) or 0)
  if want == EX.cap then return end
  if want > 0 then
    if EX.capSaved == nil then
      local ok, cap = false, nil
      if type(getfpscap) == "function" then ok, cap = pcall(getfpscap) end
      -- (unknown, or no cap at all: put back "uncapped", the hub's own way, src/25_world.lua:529, never 60)
      cap = ok and tonumber(cap)
      EX.capSaved = (cap and cap > 0) and cap or UNCAPPED
    end
    pcall(setfpscap, want)
  else
    pcall(setfpscap, EX.capSaved or UNCAPPED)
    EX.capSaved = nil
  end
  EX.cap = want
end
-- other players' bodies drawn see-through on this screen only (LocalTransparencyModifier is never replicated)
local function hideTick()
  if O.hidePlayers == true then
    if now() - EX.hideAt < 0.5 then return end
    EX.hideAt = now()
    for _, player in ipairs(S.Players:GetPlayers()) do
      local character = player ~= B.LP and player.Character
      for _, inst in ipairs(character and character:GetDescendants() or {}) do
        if (inst:IsA("BasePart") or inst:IsA("Decal")) and inst.LocalTransparencyModifier ~= 1 then
          EX.hidden[inst] = true
          inst.LocalTransparencyModifier = 1
        end
      end
    end
  elseif next(EX.hidden) then
    for inst in pairs(EX.hidden) do pcall(function() inst.LocalTransparencyModifier = 0 end) end
    table.clear(EX.hidden)
  end
end
-- The game's own camera shake switch: its settings menu calls Util.CameraShake:SetEnabled and Util.CameraShaker:SetEnabled
-- (Settings/LocalScript.luau:519-533) and also saves it with ChangeSetting:FireServer (:559, :575): only the two client calls
-- are made here. At load the game applies the player's SAVED choice (:536-545), so the put-back is the game's own state as
-- read when this part turned it off, never a plain "on".
local function setShake(on)
  for _, name in ipairs({ "CameraShake", "CameraShaker" }) do
    local mod = BF.mod("Util", name)
    if type(mod) == "table" and type(mod.SetEnabled) == "function" then BF.game(mod.SetEnabled, mod, on) end
  end
end
-- The game's own state, or nil if it cannot be read. First the module's own flag: SetEnabled's only upvalue (u1, set by
-- SetEnabled, read by the shake callback: Util/CameraShake.luau:4, 7-18, 22-28). Else the settings row the game paints
-- from it: SecondButton red = off, FirstButton green = on (Main.SettingsMenu, Settings/LocalScript.luau:15, 289-336, 544).
local OFF_RED, ON_GREEN = Color3.fromRGB(255, 79, 79), Color3.fromRGB(50, 185, 65)
local function gameShake()
  local mod = BF.mod("Util", "CameraShake")
  local getUp = type(debug) == "table" and rawget(debug, "getupvalue")
  if type(mod) == "table" and type(mod.SetEnabled) == "function" and type(getUp) == "function" then
    local ok, flag = pcall(getUp, mod.SetEnabled, 1)
    if ok and type(flag) == "boolean" then return flag end
  end
  local gui = B.LP:FindFirstChildOfClass("PlayerGui")
  local main = gui and gui:FindFirstChild("Main")
  local menu = main and main:FindFirstChild("SettingsMenu")
  local row = menu and menu:FindFirstChild("CameraShake", true)
  local first, second = row and row:FindFirstChild("FirstButton"), row and row:FindFirstChild("SecondButton")
  if not (first and second) then return nil end
  if same(second.BackgroundColor3, OFF_RED) then return false end
  if same(first.BackgroundColor3, ON_GREEN) then return true end
  return nil
end
local function shakeTick()
  if O.noShake == true and not EX.shake then
    -- (unreadable: the modules' own start value, CameraShake.luau:4)
    local was = gameShake()
    EX.shake, EX.shakeWas = true, was ~= false
    setShake(false)
  elseif O.noShake == true and EX.shake and gameShake() == true then
    -- (the player turned it on in the game's own menu meanwhile: that is now the choice to put back, and it goes off again)
    EX.shakeWas = true
    setShake(false)
  elseif O.noShake ~= true and EX.shake then
    EX.shake = false
    setShake(EX.shakeWas)
  end
end
local function extrasTick()
  lightTick()
  fastTick()
  qualityTick()
  particlesTick()
  coverTick()
  capTick()
  hideTick()
  shakeTick()
end

-- ---------------------------------------------------------------- movement
-- No-clip for walking: the body's own parts stop colliding while it is on, and get it back after.
local function clipStep()
  if O.noclip == true then
    local character = BF.char()
    for _, part in ipairs(character and character:GetChildren() or {}) do
      if part:IsA("BasePart") and part.CanCollide then
        EX.clip[part] = true
        part.CanCollide = false
      end
    end
  elseif next(EX.clip) then
    for part in pairs(EX.clip) do pcall(function() part.CanCollide = true end) end
    table.clear(EX.clip)
  end
end
-- Walk on water: a client-only floor kept under the body at the water's surface. The surface is the game's own:
-- Util.GetWaterHeightAtLocation (a water volume's surface, else the legacy height, else Water.SEA_LEVEL = -4;
-- GetWaterHeightAtLocation.luau:15-41, Modules/World/Water.luau:2). Its swim code floors a water-walker the same way
-- (Movement + Swim.luau:168-191, the character attribute "WaterWalking").
local function surfaceAt(point)
  local lookup = BF.mod("Util", "GetWaterHeightAtLocation")
  if lookup then
    local ok, height = BF.game(lookup, point)
    if ok and type(height) == "number" and height > -9000 then return height end
  end
  local water = BF.mod("Modules", "World", "Water")
  return type(water) == "table" and tonumber(water.SEA_LEVEL) or SEA_LEVEL
end
local function hideFloor()
  if WATER.part and WATER.part.Parent then WATER.part.Parent = nil end
end
local function waterStep()
  if O.walkWater ~= true then hideFloor(); return end
  local root = BF.root()
  -- (while the engine's pilot holds the body it is put by CFrame: no floor is needed under it)
  if not root or BF.pilot.mode ~= "idle" then hideFloor(); return end
  if now() - WATER.at > 0.2 then
    WATER.height, WATER.at = surfaceAt(root.Position), now()
  end
  local surface, y = WATER.height, root.Position.Y
  -- (below the surface, already diving: no floor over the head; far above: nothing to stand on yet)
  if y < surface + 0.5 or y > surface + 40 then hideFloor(); return end
  local part = WATER.part
  if not part then
    part = Instance.new("Part")
    part.Name = "WaterFloor"
    part.Size = Vector3.new(24, 1, 24)
    part.Transparency = 1
    part.Anchored = true
    part.CanCollide = true
    part.CanTouch = false
    part.CanQuery = false
    WATER.part = B.own(part)
  end
  part.CFrame = CFrame.new(root.Position.X, surface - 0.5, root.Position.Z)
  if part.Parent ~= workspace then part.Parent = workspace end
end

-- ============================================================================ 9. session
-- Roblox's own "disconnected" prompt: GuiService.ErrorMessageChanged, and CoreGui.RobloxPromptGui.promptOverlay.ErrorPrompt.
-- Only a lost connection is answered: GuiService:GetErrorCode() is one of the ConnectionError codes named "Disconnect..."
-- (a failed teleport, a place-launch error and any other message are not). Not among them: a kick by the game itself
-- (DisconnectLuaKick), the same account joining elsewhere (DisconnectDuplicatePlayer: a rejoin would throw that one out),
-- and the group marker DisconnectErrors.
local REJOIN = { busy = false, tries = 0, windowAt = -1e9 }
local NO_REJOIN = { DisconnectLuaKick = "Disconnected by the game itself", DisconnectDuplicatePlayer = "This account joined somewhere else",
  DisconnectErrors = false }
-- the Disconnect* code that is showing, or nil and why not
local function disconnectCode()
  local ok, code = pcall(function() return S.GuiService:GetErrorCode() end)
  if not (ok and typeof(code) == "EnumItem") then return nil end
  local name = code.Name
  if string.sub(name, 1, 10) ~= "Disconnect" then return nil end
  if NO_REJOIN[name] ~= nil then return nil, NO_REJOIN[name] or nil end
  return name
end
local function teleportHere(sameServer)
  local TS, me = S.TeleportService, B.LP
  if sameServer and game.JobId ~= "" then
    if pcall(function() TS:TeleportToPlaceInstance(game.PlaceId, game.JobId, me) end) then return true end
  end
  return (pcall(function() TS:Teleport(game.PlaceId, me) end))
end
local function lostConnection(message)
  if O.autoRejoin ~= true or REJOIN.busy or message == "" then return end
  local code, why = disconnectCode()
  if not code then
    if why then BF.say(why .. ": no auto-rejoin") end
    return
  end
  if now() - REJOIN.windowAt > 600 then REJOIN.windowAt, REJOIN.tries = now(), 0 end
  if REJOIN.tries >= 6 then return end
  REJOIN.busy = true
  BF.say("Connection lost (" .. code .. "): rejoining")
  task.spawn(function()
    -- (three asks, 20 s apart, at most six in ten minutes)
    for _ = 1, 3 do
      REJOIN.tries += 1
      task.wait(5)
      if not B.alive then break end
      teleportHere(false)
      task.wait(15)
    end
    REJOIN.busy = false
  end)
end
local function watchPrompt()
  pcall(function()
    local overlay = S.CoreGui:FindFirstChild("RobloxPromptGui")
    overlay = overlay and overlay:FindFirstChild("promptOverlay")
    if not overlay then return end
    B.connect(overlay.ChildAdded, function(child)
      -- (a moment later: the box can show before the error code is set)
      if child.Name == "ErrorPrompt" then task.delay(0.5, function() B.try("bloxfruits.rejoin", lostConnection, nil) end) end
    end, "bloxfruits.rejoinPrompt")
  end)
end

-- ============================================================================ start
local function undoAll()
  pcall(S.RunService.UnbindFromRenderStep, S.RunService, AIM.step)
  letGoAll(false)
  -- (each extra's own "off" path, run as if every switch were off)
  if EX.fast == true then
    local toggle = BF.mod("Util", "FastModeToggle")
    if type(toggle) == "function" then BF.game(toggle, false) end
  end
  EX.fast = false
  if EX.quality ~= nil then
    local r = rendering()
    if r then pcall(function() r.QualityLevel = EX.quality end) end
    EX.quality = nil
  end
  EX.particlesOn = false
  particlesBack()
  if EX.coverMode ~= "off" then pcall(function() S.RunService:Set3dRenderingEnabled(true) end) end
  if EX.capSaved ~= nil and type(setfpscap) == "function" then pcall(setfpscap, EX.capSaved) end
  for inst in pairs(EX.hidden) do pcall(function() inst.LocalTransparencyModifier = 0 end) end
  for part in pairs(EX.clip) do pcall(function() part.CanCollide = true end) end
  if EX.shake then setShake(EX.shakeWas) end
  if WATER.part then pcall(function() WATER.part:Destroy() end) end
end
local function start()
  -- (gentle, and never "no progress": the player walks by hand while it swings, so a repair must never unequip,
  -- drop the quest or reset the body; a mob that will not lose health is left alone by settle instead)
  BF.job({ id = "killAura", label = "Kill aura", priority = 35, switch = "bloxfruits.killAura", quiet = 25, patience = math.huge, gentle = true,
    want = function() return O.killAura == true and BF.alive() and auraCanSwing() and #auraList() > 0 end, run = auraRun })
  BF.job({ id = "panic", label = "Panic", priority = 99, quiet = 25, patience = math.huge, gentle = true, want = panicWanted, run = panicRun })
  BF.job({ id = "safeMode", label = "Safe mode", priority = 90, quiet = 25, patience = 1800,
    want = function() return O.safeMode == true and SAFE.anchor ~= nil end, run = safeRun })
  makeCircle()
  S.RunService:BindToRenderStep(AIM.step, Enum.RenderPriority.Camera.Value + 1, function()
    local ok, err = pcall(aimStep)
    if not ok then B.fault("bloxfruits.aimHelp", err) end
  end)
  B.connect(S.RunService.RenderStepped, circleStep, "bloxfruits.aimCircle")
  -- the panic key: never while typing in a text box (the game's own chat), nor the press that binds a key
  B.connect(S.UserInputService.InputBegan, function(input, typing)
    if typing or Config.capturing then return end
    local key = O.panicKey
    if key and key ~= "None" and Config.keyName(input) == key then panic() end
  end, "bloxfruits.panicKey")
  local remotes = S.ReplicatedStorage:FindFirstChild("Remotes")
  local disable = remotes and remotes:FindFirstChild("DisableKen")          -- Observation.luau:8, :29
  if disable and disable:IsA("RemoteEvent") then B.connect(disable.OnClientEvent, kenRefused, "bloxfruits.kenRefused") end
  Motion.every(function() B.try("bloxfruits.ken", kenTick) end, 2, "bloxfruits.ken")
  Motion.every(function() B.try("bloxfruits.safe", safeTick) end, 4, "bloxfruits.safe")
  Motion.every(function() B.try("bloxfruits.extras", extrasTick) end, 4, "bloxfruits.extras")
  B.connect(S.RunService.Stepped, clipStep, "bloxfruits.noclip")
  B.connect(S.RunService.Heartbeat, waterStep, "bloxfruits.walkWater")
  B.connect(S.GuiService.ErrorMessageChanged, lostConnection, "bloxfruits.rejoin")
  watchPrompt()
  B.own(undoAll)
end

-- ============================================================================ the tabs
local function live(note, fn, scope)
  Motion.every(function()
    if not (note.frame.Parent and Window.anyOpen()) then return end
    note.set(fn())
  end, 2, scope)
end
local function fight(page)
  local aura = page:section({ title = "Kill aura", icon = "swords", desc = "Hits what is close. The body stays put." })
  aura:toggle({ id = "bloxfruits.killAura", label = "Kill aura", desc = "The nearest one in reach, without moving.", default = false, children = function(sub)
    sub:slider({ id = "bloxfruits.auraRadius", label = "Reach", min = 10, max = 60, step = 1, default = 40, suffix = " st" })
    sub:toggle({ id = "bloxfruits.auraNpcs", label = "NPC enemies", default = true, bindable = false })
    sub:toggle({ id = "bloxfruits.auraPlayers", label = "Other players", desc = "Never protected ones, allies, crew or friends.", default = false, bindable = false })
    sub:toggle({ id = "bloxfruits.auraSkipBoss", label = "Leave bosses alone", default = false, bindable = false })
    sub:toggle({ id = "bloxfruits.auraSight", label = "Only in line of sight", desc = "Nothing behind a wall.", default = true, bindable = false })
  end })
  local auraNote = aura:note({ icon = "activity", text = AURA.last })
  live(auraNote, function() return string.format("%d hits sent  ·  %d down  ·  %s", AURA.hits, AURA.kills, AURA.last) end, "bloxfruits.auraStatus")
  aura:note({ icon = "info", text = "Waits while a farm with a higher place has the body." })

  local aim = page:section({ title = "Aim help", icon = "crosshair", column = 2, desc = "Skills and guns land where the camera looks." })
  aim:toggle({ id = "bloxfruits.aimHelp", label = "Aim help", desc = "Hold the key: the camera stays on the target.", default = false, children = function(sub)
    sub:keybind({ id = "bloxfruits.aimKey", label = "Hold to aim", default = "None" })
    sub:slider({ id = "bloxfruits.aimRadius", label = "Within", min = 50, max = 1000, step = 10, default = 300, suffix = " st" })
    sub:slider({ id = "bloxfruits.aimCircle", label = "Circle size", min = 30, max = 500, step = 10, default = 150, suffix = " px" })
    sub:toggle({ id = "bloxfruits.aimShowCircle", label = "Show the circle", default = true, bindable = false })
    sub:toggle({ id = "bloxfruits.aimNpcs", label = "NPC enemies", default = true, bindable = false })
    sub:toggle({ id = "bloxfruits.aimPlayers", label = "Other players", desc = "Same rules as the kill aura.", default = false, bindable = false })
  end })

  local ken = page:section({ title = "Observation", icon = "eye", column = 2 })
  ken:toggle({ id = "bloxfruits.autoKen", label = "Auto Ken", desc = "Keeps Observation on, the game's own way.", default = false })
  local kenNote = ken:note({ icon = "eye", text = kenLine() })
  live(kenNote, kenLine, "bloxfruits.kenStatus")

  local stop = page:section({ title = "Panic", icon = "triangle-alert" })
  stop:keybind({ id = "bloxfruits.panicKey", label = "Panic key", default = "None" })
  stop:slider({ id = "bloxfruits.panicHold", label = "Stay up for", min = 1, max = 120, step = 1, default = 15, suffix = " s" })
  stop:button({ id = "bloxfruits.panicNow", label = "Panic now", desc = "Everything off, then 300 studs straight up.", text = "Panic", run = panic })
  local panicNote = stop:note({ icon = "info", text = PANIC.line })
  live(panicNote, function() return PANIC.line end, "bloxfruits.panicStatus")

  local safe = page:section({ title = "Safe mode", icon = "shield", column = 2 })
  safe:toggle({ id = "bloxfruits.safeMode", label = "Safe mode", desc = "When a player comes close to a farm.", default = false, children = function(sub)
    sub:slider({ id = "bloxfruits.safeDist", label = "Closer than", min = 50, max = 1000, step = 10, default = 200, suffix = " st" })
    sub:segmented({ id = "bloxfruits.safeAction", label = "Then", options = { { "rise", "Wait up high" }, { "hop", "Hop server" } }, width = 240 })
    sub:slider({ id = "bloxfruits.safeMax", label = "Wait at most", min = 30, max = 900, step = 10, default = 300, suffix = " s" })
  end })
  local safeNote = safe:note({ icon = "shield", text = SAFE.line })
  live(safeNote, function() return SAFE.line end, "bloxfruits.safeStatus")
end

local function misc(page)
  local perf = page:section({ title = "Performance", icon = "gauge", desc = "On this screen only. Nothing is sent." })
  perf:toggle({ id = "bloxfruits.perfFast", label = "The game's Fast Mode", desc = "Its own setting. Textures return on rejoin.", default = false })
  perf:toggle({ id = "bloxfruits.perfQuality", label = "Lowest quality", desc = "Roblox graphics level 1.", default = false })
  perf:toggle({ id = "bloxfruits.perfParticles", label = "No particles", desc = "Effects, trails and beams off.", default = false })
  perf:toggle({ id = "bloxfruits.perfShadows", label = "No shadows", default = false })
  perf:segmented({ id = "bloxfruits.afkScreen", label = "AFK screen", options = { { "off", "Off" }, { "white", "White" }, { "black", "Black" } }, width = 240 })
  if type(setfpscap) == "function" then
    perf:slider({ id = "bloxfruits.fpsCap", label = "FPS cap", tip = "0 = leave it.", min = 0, max = 240, step = 5, default = 0 })
  else
    perf:note({ icon = "info", text = "This executor has no FPS cap." })
  end

  local sight = page:section({ title = "Sight", icon = "sun", column = 2 })
  sight:toggle({ id = "bloxfruits.fullBright", label = "Full bright", default = false })
  sight:toggle({ id = "bloxfruits.noFog", label = "No fog", default = false })
  sight:toggle({ id = "bloxfruits.fixTime", label = "Fixed time of day", desc = "Your screen only.", default = false, children = function(sub)
    sub:slider({ id = "bloxfruits.timeOfDay", label = "Hour", min = 0, max = 24, step = 0.5, default = 12 })
  end })
  sight:toggle({ id = "bloxfruits.hidePlayers", label = "Hide other players", desc = "See-through on your screen only.", default = false })
  sight:toggle({ id = "bloxfruits.noShake", label = "No camera shake", desc = "The game's own switch.", default = false })

  local move = page:section({ title = "Movement", icon = "footprints" })
  move:toggle({ id = "bloxfruits.walkWater", label = "Walk on water", desc = "A floor under you at the sea's surface.", default = false })
  move:toggle({ id = "bloxfruits.noclip", label = "No-clip", desc = "Walk through walls.", default = false })
  move:note({ icon = "info", text = "No infinite Geppo: the game counts each jump and tells the server." })

  local session = page:section({ title = "Session", icon = "refresh-cw", column = 2 })
  session:toggle({ id = "bloxfruits.autoRejoin", label = "Auto rejoin", desc = "When the disconnected box shows.", default = false })
  session:button({ id = "bloxfruits.rejoinNow", label = "Rejoin now", desc = "Back into this server.", text = "Rejoin", run = function()
    if not teleportHere(true) then toast("Rejoin", "Roblox refused the teleport.", false) else toast("Rejoin", "Teleport asked for.", true) end
  end })
end

BF.parts[#BF.parts + 1] = { id = "combat", start = start, fight = fight, misc = misc,
  defaults = { killAura = false, auraRadius = 40, auraNpcs = true, auraPlayers = false, auraSkipBoss = false, auraSight = true,
    aimHelp = false, aimKey = "None", aimRadius = 300, aimCircle = 150, aimShowCircle = true, aimNpcs = true, aimPlayers = false,
    autoKen = false, panicKey = "None", panicHold = 15, safeMode = false, safeDist = 200, safeAction = "rise", safeMax = 300,
    perfFast = false, perfQuality = false, perfParticles = false, perfShadows = false, afkScreen = "off", fpsCap = 0,
    fullBright = false, noFog = false, fixTime = false, timeOfDay = 12, hidePlayers = false, noShake = false,
    walkWater = false, noclip = false, autoRejoin = false } }
end
do -- bloxfruits_esp.lua
-- ============================================================================
--  Blox Fruits     ESP: what the game tells every client, drawn and announced
--
--  Read only. This part sends nothing to the server and never moves the body.
--  Every place, tag and attribute below was read from the game's own client
--  code or from the instance dump of 2026-11-13 (First Sea, v4630); the file
--  and line are beside each read. "dump" = Volt\workspace\dumps\2753915549\
--  4630\fast\, "instances" = the instances.json beside it (12 players seen).
--
--   * Players: Data.Level, Data.DevilFruit, Data.CrewID and leaderstats
--     "Bounty/Honor" replicate for everyone; so do the attributes InSafeZone,
--     PvpDisabled, KenActive (player) and InCombat (character), and the
--     character's TempSafeZone value. Allies are the tag "Ally<name>" both ways.
--   * The world is tracked by events, never walked: chests by their tag, the
--     rest by ChildAdded / ChildRemoved on the folders the game itself uses.
--     A slow pass (4 a second) picks the nearest few; the frame only projects
--     those, and writes a property only when it changed.
--   * Far mobs are parked by the game directly under ReplicatedStorage with
--     their attributes (IsBoss, Level): that is how a boss on the far side of
--     the sea is known to be alive.
-- ============================================================================
local B = B or ...
local S, util, UI, Window, Motion = B.S, B.util, B.UI, B.Window, B.Motion
local BF = B.BloxFruits
local O = BF.O
local Esp = B.Esp
local function now() return os.clock() end

-- the kinds of world mark: its switch and its colour (keys of O)
local KINDS = {
  chest = { on = "espChests", color = "espChestColor" }, npc = { on = "espNpcs", color = "espNpcColor" },
  island = { on = "espIslands", color = "espIslandColor" }, boss = { on = "espBosses", color = "espBossColor" },
  sea = { on = "espSea", color = "espSeaColor" }, boat = { on = "espBoats", color = "espBoatColor" },
  special = { on = "espSpecial", color = "espSpecialColor" }, mob = { on = "espMobs", color = "espMobColor" },
}
-- Location names of the rare islands. The client's CurrentLocation is the Name of a part of
-- _WorldOrigin.Locations (AmbientMusic.luau:719, 166-168), and the game compares it with these:
-- "Kitsune Island" / "Prehistoric Island" (WeatherStuff.luau:443-444), "Frozen Dimension"
-- (WaterCFrame/Fireflies.luau:33), "Mirage Island" (React/Components/PlayerProfile/CONSTANTS.luau:18).
local SPECIAL = { ["Mirage Island"] = true, ["Kitsune Island"] = true, ["Prehistoric Island"] = true, ["Frozen Dimension"] = true }
-- an NPC whose name has one of these is a giver or a dealer (names read under ReplicatedStorage.NPCs, instances)
local GIVER_WORDS = { "quest giver", "dealer", "teacher", "recruiter", "master", "merchant", "blacksmith", "gacha" }

-- ---------------------------------------------------------------- small readers
local function short(n)
  n = tonumber(n) or 0
  if n >= 1e6 then return string.format("%.2fM", n / 1e6) end
  if n >= 1e4 then return string.format("%.1fk", n / 1e3) end
  return util.comma(n)
end
-- "Buddha-Buddha" -> "Buddha", "T-Rex-T-Rex" -> "T-Rex" (Data.DevilFruit values, instances)
local function fruitName(value)
  local text = tostring(value or "")
  local half = (#text - 1) / 2
  if half >= 1 and half == math.floor(half) and string.sub(text, 1, half) == string.sub(text, half + 2) then return string.sub(text, 1, half) end
  return text
end
local function value(parent, name)
  local item = parent and parent:FindFirstChild(name)
  return item and item.Value
end
-- the part a model is drawn at (the game's own BossIndicatorV2.luau:106 rootOf, same order)
local function rootOf(model)
  local root = model:FindFirstChild("HumanoidRootPart")
  if root and root:IsA("BasePart") then return root end
  if model:IsA("Model") and model.PrimaryPart then return model.PrimaryPart end
  return model:FindFirstChildWhichIsA("BasePart")
end
-- A body's health share. Sea beasts keep it in "FakeHumanoid" (a Humanoid, or a value with
-- MaxValue), raid bosses in a "Health" value (LocalScriptBossBar.luau:24-29, 54-60).
local function healthOf(model)
  local fake = model:FindFirstChild("FakeHumanoid")
  if not fake then
    -- (a rig's "Health" is often Roblox's own regen Script: only a value counts)
    local stored = model:FindFirstChild("Health")
    if stored and stored:IsA("ValueBase") then fake = stored end
  end
  local hum = model:FindFirstChildOfClass("Humanoid")
  if fake and not fake:IsA("Humanoid") then
    local ok, share = pcall(function() return fake.Value / math.max(fake.MaxValue, 1) end)
    return ok and share or nil
  end
  hum = (fake and fake:IsA("Humanoid")) and fake or hum
  if hum then return hum.Health / math.max(hum.MaxHealth, 1), hum end
  return nil
end
-- a boss as the game's own cut-scene code tells one (BossCutsceneController.luau:30): raid bosses are not
local function isBoss(model)
  return model:IsA("Model") and model:GetAttribute("IsBoss") == true and not model:GetAttribute("RaidBoss")
end
-- "Mob Boss [Lv. 120] [Boss]" -> "Mob Boss" (spawn marks are named from DisplayName, ObservationManager.luau:509)
local function markName(text)
  return string.match(text, "^(.-)%s*%[Lv") or text
end
local function clean(text)
  return (string.gsub(tostring(text), "%d+$", ""))
end

-- ---------------------------------------------------------------- 1. what the player ESP reads
local function teamOf(player)
  local team = player.Team
  return team and team.Name or ""
end
-- "Lv 382  ·  Buddha  ·  bounty 2.52M"
local function playerLine(entry)
  local player = entry.player
  if not player then return nil end
  local data = player:FindFirstChild("Data")
  local parts = {}
  local level = value(data, "Level")                              -- Players.X.Data.Level IntValue (instances; ReplicatedPlayerData.luau "Data/...")
  if level then parts[#parts + 1] = "Lv " .. util.comma(tonumber(level) or 0) end
  local fruit = value(data, "DevilFruit")                         -- Data.DevilFruit StringValue (instances; ReplicatedPlayerData.luau:249)
  if fruit and fruit ~= "" then parts[#parts + 1] = fruitName(fruit) end
  local worth = value(player:FindFirstChild("leaderstats"), "Bounty/Honor")   -- leaderstats."Bounty/Honor" IntValue (instances)
  if worth and worth > 0 then
    -- (one value for both: a Marine's is honor; team names from DialoguesList.luau:319, TopbarController.luau:44)
    parts[#parts + 1] = (teamOf(player) == "Marines" and "honor " or "bounty ") .. short(worth)
  end
  if #parts == 0 then return nil end
  return table.concat(parts, "  ·  ")
end
-- friend or foe, as the game decides it (KitsuneFix.luau:41: allies both ways, or two Marines)
local function sideOf(player)
  local me = B.LP
  if player == me then return nil end
  local okA, theirs = pcall(function() return player:HasTag("Ally" .. me.Name) end)
  local okB, mine = pcall(function() return me:HasTag("Ally" .. player.Name) end)
  if okA and okB and theirs and mine then return "ALLY" end
  local crew = value(player:FindFirstChild("Data"), "CrewID")     -- Data.CrewID StringValue (instances; ReplicatedPlayerData.luau:230)
  if crew and crew ~= "" and crew == value(me:FindFirstChild("Data"), "CrewID") then return "SAME CREW" end
  if teamOf(player) == "Marines" and teamOf(me) == "Marines" then return "FELLOW MARINE" end
  return nil
end
local function playerFlags(entry)
  local player, character = entry.player, entry.character
  if not player then return nil end
  local out = {}
  -- InSafeZone: a player attribute every client gets (instances: Players.Hail_Jermany InSafeZone false); TempSafeZone:
  -- a BoolValue in the character (instances: Workspace.Characters.Hail_Jermany.TempSafeZone; TempSafeZones.luau:32)
  if player:GetAttribute("InSafeZone") == true or (character and value(character, "TempSafeZone") == true) then out[#out + 1] = "SAFE ZONE" end
  -- InCombat: read off other players' characters by the game itself (Dodge.luau:404-412)
  if character and character:GetAttribute("InCombat") then out[#out + 1] = "IN COMBAT" end
  -- PvpDisabled / KenActive: read off another player by the game's hit code (CombatUtil.luau:1628, 1632)
  if player:GetAttribute("PvpDisabled") == true then out[#out + 1] = "PVP OFF" end
  if player:GetAttribute("KenActive") == true then out[#out + 1] = "KEN ON" end
  local side = sideOf(player)
  if side then out[#out + 1] = side end
  if #out == 0 then return nil end
  return table.concat(out, "\n", 1, math.min(#out, 4))
end

-- ---------------------------------------------------------------- 2. the world, tracked by events
local tracked = {}
for kind in pairs(KINDS) do tracked[kind] = {} end
local homes = {}                                   -- kind -> { [folder] = true }: where an item of that kind may live
local announced = BF.keep({})
local namedAt = {}                                 -- name -> when it was last announced (one island seen from two folders is said once)
local quietUntil = 0
local moon = { phase = nil, blue = false }

local function on(kind) return O[KINDS[kind].on] == true end
local function anyOn()
  for kind in pairs(KINDS) do
    if on(kind) then return true end
  end
  return O.espRadarBoss or O.espRadarSea or O.espRadarIsland or O.espRadarMoon
end

-- something rare appeared: a toast and a line in the event log, if that kind is asked for
local function notice(kind, item)
  local name = item.name or "?"
  if namedAt[name] and now() - namedAt[name] < 120 then return end
  local title, icon, wanted
  if kind == "boss" then
    if item.mark then return end
    wanted = O.espRadarBoss and (O.espBossWhich ~= "ticked" or table.find(type(O.espBossPick) == "table" and O.espBossPick or {}, name) ~= nil)
    title, icon = "Boss in the server", "skull"
  elseif kind == "sea" then
    wanted, title, icon = O.espRadarSea, "Sea event", "anchor"
  elseif kind == "special" then
    wanted, title, icon = O.espRadarIsland, "Rare island", "mountain"
  end
  if not wanted then return end
  namedAt[name] = now()
  local level = item.level and ("  Lv " .. tostring(item.level)) or ""
  BF.say(title .. ": " .. name .. level)
  Window.toast({ title = title, text = name .. level, icon = icon, tone = "ok", time = 8 })
end
local function add(kind, inst, item, initial)
  local set = tracked[kind]
  local had = set[inst]
  item.kind, item.inst = kind, inst
  set[inst] = item
  if had or announced[inst] then return end
  announced[inst] = true
  if not initial and now() > quietUntil then notice(kind, item) end
end
-- out of its folder: dropped, unless it only moved to another folder of the same kind (parked <-> near)
local function drop(kinds, inst)
  local held = false
  for _, kind in ipairs(kinds) do
    if tracked[kind][inst] then held = true end
  end
  if not held then return end         -- (ReplicatedStorage loses children all the time: only ours are looked at)
  task.defer(function()
    for _, kind in ipairs(kinds) do
      local parent = inst.Parent
      if not (parent and homes[kind] and homes[kind][parent]) then tracked[kind][inst] = nil end
    end
  end)
end

-- the sorters: each looks at one new child of a watched folder
local function onEnemy(child, initial)
  if not child:IsA("Model") then return end
  -- workspace.Enemies.<name>: Humanoid, HumanoidRootPart, attributes Level, ID, IsBoss (instances; NOTES.md)
  if isBoss(child) then add("boss", child, { name = child.Name, model = child, level = child:GetAttribute("Level"), body = true }, initial) end
  add("mob", child, { name = child.Name, model = child }, true)
end
local function onStore(child, initial)
  -- a far mob, parked by the game under ReplicatedStorage with its attributes (instances: ReplicatedStorage.Wysper IsBoss true, Level 500)
  if child:IsA("Model") and isBoss(child) then add("boss", child, { name = child.Name, model = child, level = child:GetAttribute("Level"), body = true }, initial) end
end
-- A spawn mark whose spawn the game has switched off. The game parents a mark back into EnemySpawns whenever its mob leaves
-- Enemies, a death included (ObservationManager.luau:523-534, the "line: 327" handler), and takes it out only when the mark's
-- attribute "Active" turns false (:536-555; a mark that is not Active at load is taken out at once, :581-582). So a mark in the
-- folder with Active == false is a boss that is not alive. (Read at every 4 Hz pass and every status line: a change shows within a pass.)
local function markOff(inst)
  return inst:GetAttribute("Active") == false
end
local function onSpawnMark(child, initial)
  -- A spawn mark sits in EnemySpawns while its mob is not near (ObservationManager.luau:510-555), dead or alive: see markOff;
  -- a boss's is named "... [Boss]" and carries the mob's ID.
  if child:IsA("BasePart") and string.find(child.Name, "[Boss]", 1, true) then
    add("boss", child, { name = markName(child.Name), part = child, mark = true, level = tonumber(string.match(child.Name, "%[Lv%.%s*(%d+)")) }, initial)
  end
end
local function onSea(child, initial)
  -- workspace.SeaBeasts: every child is a beast (SyncLeviathan.luau:34, LocalScriptBossBar.luau:136)
  if child:IsA("Model") then add("sea", child, { name = clean(child.Name), model = child }, initial) end
end
local function onSeaEvent(child, initial)
  -- workspace.SeaEvents also holds the client's own tornado props (TornadoComponent.luau:57, 75): only bodies count
  if child:IsA("Model") and (child:FindFirstChildOfClass("Humanoid") or child:FindFirstChild("FakeHumanoid") or child:GetAttribute("IsBoss")) then
    add("sea", child, { name = clean(child.Name), model = child }, initial)
  end
end
local function onBoat(child, initial)
  -- workspace.Boats.<name>: attributes IsBoat, MaxHealth; children Humanoid (IntValue), Owner (ObjectValue -> Player) (instances; ShipClient.luau:53)
  if child:IsA("Model") then add("boat", child, { name = clean(child.Name), model = child }, initial) end
end
local function onNpc(child, initial)
  -- NPC models: near ones in workspace.NPCs, every one in ReplicatedStorage.NPCs (instances)
  if child:IsA("Model") then add("npc", child, { name = child.Name, model = child }, initial) end
end
local function onLocation(child, initial)
  -- _WorldOrigin.Locations: one part per island, named by it ("Sea" is the open water) (IslandDistance.luau:8-14)
  if not child:IsA("BasePart") or child.Name == "Sea" then return end
  local name = clean(child.Name)
  if SPECIAL[name] then add("special", child, { name = name, part = child }, initial) else add("island", child, { name = name, part = child }, initial) end
end
local function onZone(child, initial)
  -- the Mirage's fog zone: a part "MirageIsland" under _WorldOrigin.LightingZones (WeatherStuff.luau:43, 412)
  if child.Name == "MirageIsland" and child:IsA("BasePart") then add("special", child, { name = "Mirage Island", part = child }, initial) end
end
local function onMap(child, initial)
  -- workspace.Map.KitsuneIsland (BlueMoonClient.luau:237), workspace.Map.PrehistoricIsland (WeatherStuff.luau:633, PrehistoricIslandClient.luau:78)
  local name = child.Name == "KitsuneIsland" and "Kitsune Island" or (child.Name == "PrehistoricIsland" and "Prehistoric Island") or nil
  if not name then return end
  local ok, at = pcall(function() return child:GetPivot().Position end)
  add("special", child, { name = name, model = child, at = ok and at or nil }, initial)
end

-- Watch one folder: what is in it now (quietly), then what comes and goes. A folder that is not there
-- yet (a sea without SeaBeasts, say) is looked for again every few seconds.
local function watch(kinds, find, sorter, scope)
  task.spawn(function()
    local folder
    while B.alive do
      folder = find()
      if folder then break end
      task.wait(5)
    end
    if not folder then return end
    for _, kind in ipairs(kinds) do
      homes[kind] = homes[kind] or {}
      homes[kind][folder] = true
    end
    B.connect(folder.ChildAdded, function(child) sorter(child, false) end, scope)
    B.connect(folder.ChildRemoved, function(child) drop(kinds, child) end, scope)
    for _, child in ipairs(folder:GetChildren()) do B.try(scope, sorter, child, true) end
  end)
end
local function origin(name)
  local root = workspace:FindFirstChild("_WorldOrigin")
  return root and root:FindFirstChild(name)
end
local function watchChests()
  -- every world chest carries the tag "_ChestTagged" (ChestSettings.luau:5; ChestListenerOld.luau:51-57; instances: 37 tagged)
  local tag = "_ChestTagged"
  local function chest(inst, initial)
    if inst:IsA("BasePart") then add("chest", inst, { name = inst.Name, part = inst }, initial) end
  end
  B.connect(S.CollectionService:GetInstanceAddedSignal(tag), function(inst) chest(inst, false) end, "bloxfruits.espChests")
  B.connect(S.CollectionService:GetInstanceRemovedSignal(tag), function(inst) tracked.chest[inst] = nil end, "bloxfruits.espChests")
  for _, inst in ipairs(S.CollectionService:GetTagged(tag)) do chest(inst, true) end
end
local function watchMoon()
  -- Lighting attributes MoonPhase (5 = full: DialoguesList.luau:5226, Gravity/V.luau:544-549) and IsBlueMoon (BlueMoonClient.luau:52)
  local lighting = S.Lighting
  moon.phase, moon.blue = lighting:GetAttribute("MoonPhase"), lighting:GetAttribute("IsBlueMoon") == true
  B.connect(lighting:GetAttributeChangedSignal("MoonPhase"), function()
    local phase = lighting:GetAttribute("MoonPhase")
    if phase == 5 and moon.phase ~= 5 and O.espRadarMoon then
      BF.say("Full moon")
      Window.toast({ title = "Full moon", text = "The moon is full in this server.", icon = "moon", tone = "ok", time = 8 })
    end
    moon.phase = phase
  end, "bloxfruits.espMoon")
  B.connect(lighting:GetAttributeChangedSignal("IsBlueMoon"), function()
    local blue = lighting:GetAttribute("IsBlueMoon") == true
    if blue and not moon.blue and O.espRadarMoon then
      BF.say("Blue moon")
      Window.toast({ title = "Blue moon", text = "A blue moon is up: Kitsune's shrine is awake.", icon = "moon", tone = "ok", time = 8 })
    end
    moon.blue = blue
  end, "bloxfruits.espMoon")
end
local watching = false
local function ensureWatching()
  if watching then return end
  watching = true
  quietUntil = now() + 3           -- (what replicates in the first moments was there before: not news)
  local RS = S.ReplicatedStorage
  watchChests()
  watchMoon()
  watch({ "mob", "boss" }, function() return workspace:FindFirstChild("Enemies") end, onEnemy, "bloxfruits.espEnemies")
  watch({ "boss" }, function() return RS end, onStore, "bloxfruits.espParked")
  watch({ "boss" }, function() return origin("EnemySpawns") end, onSpawnMark, "bloxfruits.espMarks")
  watch({ "sea" }, function() return workspace:FindFirstChild("SeaBeasts") end, onSea, "bloxfruits.espSea")
  watch({ "sea" }, function() return workspace:FindFirstChild("SeaEvents") end, onSeaEvent, "bloxfruits.espSeaEvents")
  watch({ "boat" }, function() return workspace:FindFirstChild("Boats") end, onBoat, "bloxfruits.espBoats")
  watch({ "npc" }, function() return workspace:FindFirstChild("NPCs") end, onNpc, "bloxfruits.espNpcs")
  watch({ "npc" }, function() return RS:FindFirstChild("NPCs") end, onNpc, "bloxfruits.espNpcs")
  watch({ "island", "special" }, function() return origin("Locations") end, onLocation, "bloxfruits.espIslands")
  watch({ "special" }, function() return origin("LightingZones") end, onZone, "bloxfruits.espZones")
  watch({ "special" }, function() return workspace:FindFirstChild("Map") end, onMap, "bloxfruits.espMap")
end

-- ---------------------------------------------------------------- which marks are worth drawing
-- quest givers of this sea, from the game's guide (GuideModule.Data.NPCList[].NPCName: NOTES.md, read live)
local givers, giversAt = {}, -100
local function isGiver(name)
  if now() - giversAt > 60 then
    giversAt = now()
    table.clear(givers)
    local guide = BF.mod("GuideModule")
    local list = guide and type(guide.Data) == "table" and guide.Data.NPCList
    for _, giver in pairs(type(list) == "table" and list or {}) do
      if type(giver) == "table" and giver.NPCName then givers[tostring(giver.NPCName)] = true end
    end
  end
  if givers[name] then return true end
  local lower = string.lower(name)
  for _, word in ipairs(GIVER_WORDS) do
    if string.find(lower, word, 1, true) then return true end
  end
  return false
end
local function npcWanted(name)
  if O.espNpcGivers and not isGiver(name) then return false end
  local filter = tostring(O.espNpcFilter or "")
  if filter == "" then return true end
  local lower = string.lower(name)
  for word in string.gmatch(string.lower(filter), "[^,]+") do
    word = string.match(word, "^%s*(.-)%s*$")
    if word ~= "" and string.find(lower, word, 1, true) then return true end
  end
  return false
end
local function posOf(item)
  local part = item.part
  if part and part.Parent then return part.Position end
  local model = item.model
  if model and model.Parent and not item.at then
    part = rootOf(model)
    item.part = part
    if part then return part.Position end
  end
  return item.at
end
local bodyIds = {}
local nearNpcs = {}             -- names of the NPCs tracked in workspace.NPCs, this pass
local function keep(item)
  local kind, inst = item.kind, item.inst
  if kind == "chest" then return inst:GetAttribute("IsDisabled") ~= true end   -- opened (ClientChest.luau:153, 172)
  if kind == "npc" then
    -- (one NPC can be both near, in workspace.NPCs, and in ReplicatedStorage.NPCs: the near one is the mark, the other is dropped)
    local near = workspace:FindFirstChild("NPCs")
    if inst.Parent ~= near and nearNpcs[item.name] then return false end
    return npcWanted(item.name)
  end
  if kind == "mob" then
    local hum = inst:FindFirstChildOfClass("Humanoid")
    if not (hum and hum.Health > 0) then return false end
    return not (on("boss") and isBoss(inst))
  end
  if kind == "boss" and item.mark then
    if markOff(inst) then return false end
    local id = inst:GetAttribute("ID")
    return not (id and bodyIds[id])      -- (the body is marked already: the mark carries the mob's ID, ObservationManager.luau:517)
  end
  return true
end

local shown = {}
local textOf                    -- (below, with the drawing: the gather builds the text with it)
local function nearer(a, b) return a.away < b.away end
local function gather()
  table.clear(shown)
  local camera = workspace.CurrentCamera
  if not camera then return end
  local from = camera.CFrame.Position
  local range = O.espRange or 5000
  table.clear(bodyIds)
  if on("boss") then
    for _, item in pairs(tracked.boss) do
      local id = item.body and item.inst:GetAttribute("ID")
      if id then bodyIds[id] = true end
    end
  end
  table.clear(nearNpcs)
  if on("npc") then
    local near = workspace:FindFirstChild("NPCs")
    for inst, item in pairs(tracked.npc) do
      if near and inst.Parent == near then nearNpcs[item.name] = true end
    end
  end
  for kind in pairs(KINDS) do
    if on(kind) then
      for _, item in pairs(tracked[kind]) do
        local at = posOf(item)
        if at and keep(item) then
          local away = (at - from).Magnitude
          if away <= range then
            item.away = away
            shown[#shown + 1] = item
          end
        end
      end
    end
  end
  table.sort(shown, nearer)
  for index = #shown, (O.espMax or 40) + 1, -1 do shown[index] = nil end
  -- (the text, with its health and distance, is built here at 4 a second; the frame only places the marks)
  for _, item in ipairs(shown) do item.text = textOf(item, item.away) end
end

-- ---------------------------------------------------------------- drawing
local function hp(share)
  return share and string.format("%d%%", math.floor(share * 100 + 0.5)) or nil
end
local chestNames
local function chestName(raw)
  -- the chest's shown name from the game's table: Chest1 = "Silver Chest" ... (ChestConfiguration/ChestTypes.luau:3-8)
  if not chestNames then
    chestNames = {}
    local types = BF.mod("ChestConfiguration", "ChestTypes")
    for key, row in pairs(type(types) == "table" and types or {}) do
      if type(row) == "table" and row.DisplayName then chestNames[key] = tostring(row.DisplayName) end
    end
  end
  return chestNames[raw] or raw
end
function textOf(item, away)
  local kind, inst = item.kind, item.inst
  local far = util.studs(away) .. " st"
  local bits = { item.name }
  if kind == "chest" then
    bits[1] = chestName(inst:GetAttribute("IsChristmasChest") and "XmasChest" or item.name)   -- (ChestListener.luau:50)
  elseif kind == "boss" then
    if item.level then bits[#bits + 1] = "Lv " .. tostring(item.level) end
    if item.mark then
      bits[#bits + 1] = "spawn"
    else
      bits[#bits + 1] = hp((healthOf(inst)))
      if inst.Parent ~= workspace:FindFirstChild("Enemies") then bits[#bits + 1] = "last seen" end
    end
  elseif kind == "mob" then
    local level = inst:GetAttribute("Level")                      -- (Enemies.<mob> attribute Level: instances; CombatUtil.luau:1639)
    if level then bits[#bits + 1] = "Lv " .. tostring(level) end
    local hum = inst:FindFirstChildOfClass("Humanoid")
    if hum then bits[#bits + 1] = string.format("%s/%s", short(hum.Health), short(hum.MaxHealth)) end
  elseif kind == "sea" then
    bits[#bits + 1] = hp((healthOf(inst)))
  elseif kind == "boat" then
    local owner = value(inst, "Owner")
    if typeof(owner) == "Instance" then bits[#bits + 1] = owner.Name end
    local health, max = value(inst, "Humanoid"), inst:GetAttribute("MaxHealth")
    if type(health) == "number" and type(max) == "number" and max > 0 then bits[#bits + 1] = hp(health / max) end
  end
  bits[#bits + 1] = far
  return table.concat(bits, "  ·  ")
end

-- wrote[i]: what label i shows now (text, colour, position, shown), so a property is written only when it changed,
-- without reading the label's own properties back every frame
local layer, pool, wrote, used = nil, {}, {}, 0
local function label()
  used += 1
  local item = pool[used]
  if not item then
    item = UI.new("TextLabel", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(240, 14), FontFace = B.F.mono500, TextSize = 11,
      TextStrokeColor3 = Color3.new(0, 0, 0), TextStrokeTransparency = 0.45, Text = "", Visible = false, Parent = layer })
    pool[used] = item
    wrote[used] = { visible = false }
  end
  return item, wrote[used]
end
local function draw()
  used = 0
  local camera = workspace.CurrentCamera
  if camera and #shown > 0 then
    for _, item in ipairs(shown) do
      local at = item.text and item.inst.Parent and posOf(item)
      if at then
        local point = camera:WorldToViewportPoint(at)
        if point.Z > 0 then
          local mark, memo = label()
          if memo.text ~= item.text then memo.text = item.text; mark.Text = item.text end
          local color = O[KINDS[item.kind].color]
          if memo.color ~= color then memo.color = color; mark.TextColor3 = color end
          local x, y = math.floor(point.X + 0.5), math.floor(point.Y + 0.5)
          if memo.x ~= x or memo.y ~= y then
            memo.x, memo.y = x, y
            mark.Position = UDim2.fromOffset(x, y)
          end
          if not memo.visible then memo.visible = true; mark.Visible = true end
        end
      end
    end
  end
  for index = used + 1, #pool do
    local memo = wrote[index]
    if memo.visible then memo.visible = false; pool[index].Visible = false end
  end
end

-- ---------------------------------------------------------------- 3. what is in the server right now
local function listOf(kind, withLevel)
  local names, seen = {}, {}
  for _, item in pairs(tracked[kind]) do
    local name = item.name
    -- (a spawn mark the game has switched off is a boss that is not alive: not listed as alive)
    if item.mark and markOff(item.inst) then name = nil end
    if name and not seen[name] then
      seen[name] = true
      names[#names + 1] = (withLevel and item.level) and string.format("%s (%s)", name, tostring(item.level)) or name
    end
  end
  table.sort(names)
  return names
end
local function statusLines()
  local bosses, sea, rare = listOf("boss", true), listOf("sea"), listOf("special")
  local lines = {}
  lines[1] = #bosses > 0 and ("Bosses alive: " .. table.concat(bosses, ", ", 1, math.min(#bosses, 6))) or "Bosses alive: none seen"
  lines[2] = #sea > 0 and ("At sea: " .. table.concat(sea, ", ", 1, math.min(#sea, 6))) or "At sea: nothing"
  lines[3] = #rare > 0 and ("Rare islands: " .. table.concat(rare, ", ")) or "Rare islands: none"
  local clock = S.Lighting.ClockTime
  local phase = moon.phase
  local sky = phase == 5 and "full" or (phase and ("phase " .. tostring(phase)) or "unknown")
  lines[4] = string.format("Moon: %s%s  ·  game time %02d:%02d", sky, moon.blue and " (blue moon)" or "", math.floor(clock), math.floor((clock % 1) * 60))
  return lines
end

-- ---------------------------------------------------------------- start
local function start()
  if Esp then
    local extras = Esp.extras
    extras.money = playerLine
    extras.flags = playerFlags
    extras.sample = { money = "Lv 1,850  ·  Dragon  ·  bounty 2.52M", flags = "IN COMBAT\nALLY" }
  end
  layer = UI.frame(B.screen(7985), { Name = "World", Size = UDim2.fromScale(1, 1) })
  -- (nothing is watched until a switch of this part is on, or the ESP tab's status card is opened)
  Motion.every(function()
    B.try("bloxfruits.espWake", function()
      if not watching and anyOn() then ensureWatching() end
    end)
  end, 1, "bloxfruits.espWake")
  Motion.every(function()
    B.try("bloxfruits.espGather", function()
      if watching then gather() else table.clear(shown) end
    end)
  end, 4, "bloxfruits.espGather")
  B.connect(S.RunService.RenderStepped, draw, "bloxfruits.espDraw")
end

-- ---------------------------------------------------------------- the ESP tab
local function marks(page)
  local s = page:section({ title = "World marks", icon = "map-pin", desc = "Name and distance, nearest first." })
  local function kind(id, label, desc, color, children)
    s:toggle({ id = "bloxfruits." .. id, label = label, desc = desc, default = false, children = function(sub)
      sub:color({ id = "bloxfruits." .. id .. "Color", label = "Colour", default = color })
      if children then children(sub) end
    end })
  end
  kind("espChests", "Chests", "Every chest not yet opened.", Color3.fromRGB(255, 209, 102))
  kind("espNpcs", "NPCs", "Quest givers, dealers and teachers by name.", Color3.fromRGB(170, 200, 255), function(sub)
    sub:toggle({ id = "bloxfruits.espNpcGivers", label = "Only givers and dealers", desc = "Hides the rest.", default = false, bindable = false })
    sub:input({ id = "bloxfruits.espNpcFilter", label = "Only names with", placeholder = "e.g. dealer, teacher" })
  end)
  kind("espIslands", "Islands", "Every island of this sea.", Color3.fromRGB(126, 231, 135))
  kind("espBosses", "Bosses", "Living bosses, near or far.", Color3.fromRGB(255, 99, 99))
  kind("espSea", "Sea beasts and sea events", "Whatever is out on the water.", Color3.fromRGB(88, 166, 255))
  kind("espBoats", "Boats", "Each boat, its owner and its health.", Color3.fromRGB(205, 170, 125))
  kind("espSpecial", "Rare islands", "Mirage, Kitsune, Prehistoric, Frozen Dimension.", Color3.fromRGB(215, 120, 255))
  local mobs = page:section({ title = "Enemy levels", icon = "skull", column = 2 })
  mobs:toggle({ id = "bloxfruits.espMobs", label = "Level tags", desc = "Name, level and health over each mob.", default = false, children = function(sub)
    sub:color({ id = "bloxfruits.espMobColor", label = "Colour", default = Color3.fromRGB(235, 235, 235) })
  end })
  local reach = page:section({ title = "Reach", icon = "radar", column = 2 })
  reach:slider({ id = "bloxfruits.espRange", label = "Within", tip = "Marks things this close.", min = 100, max = 30000, step = 100, default = 5000, curve = 2, suffix = " st" })
  reach:slider({ id = "bloxfruits.espMax", label = "At most", tip = "The nearest this many.", min = 5, max = 150, step = 5, default = 40 })
end
-- the bosses that can be ticked: this sea's boss quests (one kill: BF.quests) and any seen alive
local function bossOptions()
  local names, seen = {}, {}
  local function put(name)
    if name and name ~= "" and not seen[name] then seen[name] = true; names[#names + 1] = name end
  end
  local ok, catalogue = pcall(BF.quests)
  for _, quest in ipairs(ok and type(catalogue) == "table" and catalogue or {}) do
    if quest.boss then put(quest.mob) end
  end
  for _, item in pairs(tracked.boss) do put(item.name) end
  for _, name in ipairs(type(O.espBossPick) == "table" and O.espBossPick or {}) do put(name) end
  table.sort(names)
  local options = {}
  for _, name in ipairs(names) do options[#options + 1] = { name, name } end
  return options
end
local function radar(page)
  local card = page:section({ title = "In this server now", icon = "activity", column = 2, desc = "Read from the game, never sent." })
  local notes = {}
  local first = statusLines()
  for index, icon in ipairs({ "skull", "anchor", "mountain", "moon" }) do notes[index] = card:note({ icon = icon, text = first[index] }) end
  ensureWatching()
  Motion.every(function()
    if not (notes[1].frame.Parent and Window.anyOpen()) then return end
    local lines = statusLines()
    for index, note in ipairs(notes) do note.set(lines[index]) end
  end, 1, "bloxfruits.espStatus")
  local tell = page:section({ title = "Tell me when", icon = "bell", desc = "A toast and a line in the Farm log." })
  tell:toggle({ id = "bloxfruits.espRadarBoss", label = "A boss appears", desc = "Its body joins the server.", default = false, children = function(sub)
    sub:segmented({ id = "bloxfruits.espBossWhich", label = "Which", options = { { "all", "Every boss" }, { "ticked", "Ticked only" } }, width = 220 })
    local options = bossOptions()
    if #options > 0 then
      sub:multi({ id = "bloxfruits.espBossPick", label = "Ticked bosses", options = options, default = {} })
    else
      sub:note({ icon = "info", text = "No boss known yet in this sea." })
    end
  end })
  tell:toggle({ id = "bloxfruits.espRadarSea", label = "A sea event starts", desc = "A sea beast or a sea event body.", default = false })
  tell:toggle({ id = "bloxfruits.espRadarIsland", label = "A rare island rises", desc = "Mirage, Kitsune, Prehistoric, Frozen Dimension.", default = false })
  tell:toggle({ id = "bloxfruits.espRadarMoon", label = "The moon is full", desc = "Also a blue moon.", default = false })
end
local function esp(page)
  marks(page)
  radar(page)
end

-- its own notes on the Visuals tab, beside the hub's player ESP
if Esp then
  Esp.sections[#Esp.sections + 1] = function(page)
    if not (B.Registry and B.Registry.active and B.Registry.active.id == "bloxfruits") then return end
    local s = page:section({ title = "Blox Fruits ESP", icon = "scan-eye", column = 2, weight = 4, desc = "Tick these two under Elements." })
    s:note({ icon = "tag", text = "Cash and wanted: level, fruit eaten, bounty or honor." })
    s:note({ icon = "flag", text = "State flags: safe zone, in combat, PvP off, Ken on, ally, crew." })
    s:note({ icon = "map-pin", text = "Chests, bosses, islands and sea events: the ESP tab." })
  end
end

BF.parts[#BF.parts + 1] = { id = "esp", start = start, esp = esp,
  defaults = { espChests = false, espChestColor = Color3.fromRGB(255, 209, 102), espNpcs = false, espNpcColor = Color3.fromRGB(170, 200, 255), espNpcGivers = false,
    espNpcFilter = "", espIslands = false, espIslandColor = Color3.fromRGB(126, 231, 135), espBosses = false, espBossColor = Color3.fromRGB(255, 99, 99),
    espSea = false, espSeaColor = Color3.fromRGB(88, 166, 255), espBoats = false, espBoatColor = Color3.fromRGB(205, 170, 125), espSpecial = false,
    espSpecialColor = Color3.fromRGB(215, 120, 255), espMobs = false, espMobColor = Color3.fromRGB(235, 235, 235), espRange = 5000, espMax = 40,
    espRadarBoss = false, espBossWhich = "all", espBossPick = {}, espRadarSea = false, espRadarIsland = false, espRadarMoon = false } }
end
do -- bloxfruits_farm.lua
-- ============================================================================
--  Blox Fruits     levelling: the quest worth taking, taken, fought, again
--
--  Every quest comes from the game's own tables (Quests, and the guide's list
--  of who gives which and where), so a new island or a moved quest is known
--  the day the game ships it. A quest is worth: its experience for each kill,
--  less for a long trip, nothing if its mobs have no spawn here.
-- ============================================================================
local B = B or ...
local S, Config, Window = B.S, B.Config, B.Window
local BF = B.BloxFruits
local O = BF.O
local function now() return os.clock() end

-- ---------------------------------------------------------------- the quests of this sea
-- { group, index, name, level, mob, need, exp, beli, at (the giver), giver, spawns, boss }
local catalogue, catalogueAt
function BF.quests()
  if catalogue and now() - catalogueAt < 60 then return catalogue end
  local quests, guide = BF.mod("Quests"), BF.mod("GuideModule")
  local givers = guide and type(guide.Data) == "table" and guide.Data.NPCList
  local list = {}
  if type(quests) == "table" and type(givers) == "table" then
    for _, giver in pairs(givers) do
      local group = type(giver) == "table" and quests[giver.InternalQuestName]
      if type(group) == "table" and typeof(giver.Position) == "Vector3" then
        for index, quest in ipairs(group) do
          local mob, need, kinds = nil, 0, 0
          for name, count in pairs(type(quest.Task) == "table" and quest.Task or {}) do
            mob, need, kinds = name, tonumber(count) or 1, kinds + 1
          end
          if kinds == 1 and type(quest.Reward) == "table" then
            local spawns, boss = BF.spawns(mob)
            list[#list + 1] = { group = giver.InternalQuestName, index = index, name = tostring(quest.Name), level = tonumber(quest.LevelReq) or 0, mob = mob,
              need = need, exp = tonumber(quest.Reward.Exp) or 0, beli = tonumber(quest.Reward.Beli) or 0, at = giver.Position, giver = tostring(giver.NPCName),
              spawns = spawns, boss = boss or need == 1 }
          end
        end
      end
    end
  end
  -- One quest, one giver. The game lists some givers twice (seen live 2026-11-13: Mole, in the lower Skylands by
  -- the God's Guards and again 4,400 studs up by the Shandas, and both hand out both quests). The one nearest the
  -- quest's own mobs is the one gone to: with both in the list the body climbed to the far Mole after every quest.
  local kept, byKey = {}, {}
  for _, quest in ipairs(list) do
    local gap = math.huge
    for _, point in ipairs(quest.spawns) do gap = math.min(gap, (point - quest.at).Magnitude) end
    quest.gap = gap
    local id = quest.group .. "/" .. quest.index
    local had = byKey[id]
    if not had then
      byKey[id] = #kept + 1
      kept[#kept + 1] = quest
    elseif gap < kept[had].gap then
      kept[had] = quest
    end
  end
  list = kept
  table.sort(list, function(a, b) return a.level < b.level end)
  catalogue, catalogueAt = list, now()
  return list
end
BF.barred = {}            -- "group/index" -> until when a quest is not offered (it could not be taken, or had no mobs)
local function key(quest) return quest.group .. "/" .. quest.index end
-- what a quest is worth to this body, standing where it stands
local function worth(quest, level, from)
  if quest.level > level then return nil end
  if O.skipBoss and quest.boss then return nil end
  if #quest.spawns == 0 then return nil end
  if (BF.barred[key(quest)] or 0) > now() then return nil end
  -- (as the body would travel it: through the whirlpool for a quest in the Underwater City)
  local trip = BF.trip(from, quest.at)
  if trip > (O.maxTrip or 30000) then return nil end
  local each = quest.exp / math.max(quest.need, 1)
  local mode = O.questMode or "fast"
  -- (of two quests of one level, the nearer)
  if mode == "fast" then return quest.level * 1000 + each - trip / 1000 end
  if mode == "easy" then
    -- the best one a notch below what the level allows
    if quest.level > level * 0.85 and quest.level > 10 then return nil end
    return quest.level * 1000 + each - trip / 1000
  end
  -- balanced: experience a kill, less for the trip and for a thin spawn
  return each * math.min(1, #quest.spawns / 4) / (1 + trip / 4000)
end
local chosen, chosenAt = nil, 0
function BF.pickQuest()
  local root = BF.root()
  if not root then return nil end
  local level, from = BF.level(), root.Position
  if chosen then
    -- (the list is read afresh every minute: the quest being fought is found again in the new one, so "the same
    -- quest" below means the same quest and not the same table)
    local mine = key(chosen)
    for _, quest in ipairs(BF.quests()) do
      if key(quest) == mine then chosen = quest; break end
    end
  end
  -- (a quest in hand is finished first: dropping it half done throws its kills away, and the pay is most of it)
  local held = BF.quest()
  if held then
    for _, quest in ipairs(BF.quests()) do
      if quest.group == held.InternalQuestName and quest.name == held.Info.Name then
        if worth(quest, level, from) then
          if chosen ~= quest then chosen, chosenAt = quest, now() end
          return quest
        end
        break
      end
    end
  end
  local best, bestWorth
  for _, quest in ipairs(BF.quests()) do
    local value = worth(quest, level, from)
    if value and (not bestWorth or value > bestWorth) then best, bestWorth = quest, value end
  end
  -- Between quests. A quest of a higher level is always taken (a small step up used to be lost for good behind
  -- the "better by" rule). Of two of one level the one being fought stays unless the other is clearly better:
  -- no flying back and forth between two islands for the same pay.
  if chosen and best and best ~= chosen then
    local was = worth(chosen, level, from)
    if was then
      if best.level <= chosen.level and bestWorth < was * (1 + (O.switchGain or 15) / 100) then return chosen end
      -- (with no quest taken there is nothing to finish first: the mobs being fought are kept for a while)
      if O.takeQuest == false and now() - chosenAt < (O.recheck or 60) then return chosen end
    end
  end
  if best ~= chosen then chosen, chosenAt = best, now() end
  return best
end

-- is the quest in hand this one? (and the quest in hand, whatever it is)
local function onScreen(quest)
  local held = BF.quest()
  if not held then return false, nil end
  return held.InternalQuestName == quest.group and held.Info.Name == quest.name, held
end

-- ---------------------------------------------------------------- the three farms
-- fight the mobs of one name until none is left here; when there is none, wait over where they come back
local function hunt(ctx, name, spawns, state)
  local root = BF.root()
  if not root then return end
  local mobs = BF.mobs(name, root.Position)
  if #mobs > 0 then
    state.emptySince = nil
    -- (the pack first, in the order the player chose; a mob that broke away from the stack only once the pack is down)
    local mob, stray = BF.choose(mobs)
    if stray and state.strayOf ~= mob then
      state.strayOf = mob
      BF.count.strays = (BF.count.strays or 0) + 1
      ctx:beat("Going after a stray " .. tostring(name))
    end
    local result = BF.fight(mob, ctx, function()
      local mine = BF.root()
      return BF.mobs(name, mine and mine.Position)
    end)
    if result == "died" then ctx:body(40) end
    return result
  end
  state.emptySince = state.emptySince or now()
  if #spawns == 0 then ctx:sleep(1, "No " .. tostring(name) .. " here"); return "none" end
  -- over the next spawn mark in turn, a few seconds at each
  state.mark = (state.mark or 0) % #spawns + 1
  local ok = BF.fly(spawns[state.mark] + Vector3.new(0, O.height or 25, 0), ctx, { note = "To where " .. name .. " comes back" })
  if ok then ctx:sleep(O.spawnWait or 3, "Waiting for " .. name) end
  return "none"
end

local function levelLoop(ctx)
  local state = {}
  local hadQuest = false
  while B.alive and not ctx.stop do
    if not ctx:body(40) then return end
    local target = O.stopLevel or 0
    if target > 0 and BF.level() >= target then
      BF.say("Level " .. target .. " reached: auto level is off")
      Config.set("bloxfruits.level", false)
      return
    end
    local quest = BF.pickQuest()
    if not quest then
      ctx:sleep(3, "No quest this body can take in this sea")
    else
      local mine, text = onScreen(quest)
      if hadQuest and not text then hadQuest = false end
      -- (a quest that belongs to a story chain is never dropped: the level farm fights with no quest of its own until it is done)
      if text and not mine and not BF.keepQuests[text.InternalQuestName] then
        BF.invoke(4, "AbandonQuest")
        ctx:sleep(0.4, "Dropping another quest")
        text = nil
      end
      if not text and O.takeQuest ~= false then
        local ok, why = BF.fly(quest.at + Vector3.new(0, 5, 0), ctx, { note = "To " .. quest.giver })
        if ok and BF.pickQuest() ~= quest then
          -- (seen live at level 298 -> 301: the pay of the quest before raises the level a moment after the next
          -- quest was chosen. Asked again here, so a quest of the tier below is not taken for one more round)
          ctx:beat("A better quest has opened")
        elseif ok then
          local sent, answer = BF.invoke(6, "StartQuest", quest.group, quest.index)
          if sent and answer == 0 then
            hadQuest = true
            state.emptySince = nil
            -- (the game's guide learns of it a moment later: waited for, so it is not taken twice)
            local untilAt = now() + 3
            while not BF.quest() and now() < untilAt and not ctx.stop do
              ctx:beat("Quest taken: " .. quest.name)
              task.wait(0.1)
            end
          elseif sent and answer == 2 then
            -- (the game's own answers, DialoguesList/Util.luau:171-190: 0 given, 1 an error, 2 already completed,
            -- any other number the level it wants. A quest that is done is never asked for again this session)
            BF.barred[key(quest)] = math.huge
            BF.say(quest.name .. " is already completed: not asked again")
            chosen = nil
          else
            local long = sent and type(answer) == "number" and answer > 2
            BF.barred[key(quest)] = now() + (long and 600 or 120)
            BF.say(string.format("%s was not given (%s): not asked again for %d min", quest.name, long and ("it wants level " .. answer) or tostring(answer), long and 10 or 2))
            chosen = nil
          end
          state.unreached = nil
        elseif why ~= "stopped" then
          BF.say("Could not reach " .. quest.giver .. ": " .. tostring(why))
          -- (a giver that cannot be got to is set aside after two trips: the same trip is not flown again and
          -- again until the director has to step in. A death on the way is not the giver's fault)
          if why ~= "dead" then
            state.unreached = state.unreached or {}
            local times = (state.unreached[key(quest)] or 0) + 1
            state.unreached[key(quest)] = times
            if times >= 2 then
              state.unreached[key(quest)] = nil
              BF.barred[key(quest)] = now() + 300
              BF.say(quest.name .. ": its giver could not be reached twice, set aside for 5 min")
              chosen = nil
            end
          end
          ctx:sleep(1)
        end
      else
        hadQuest = hadQuest or (text ~= nil and mine)
        hunt(ctx, quest.mob, quest.spawns, state)
        if state.emptySince and now() - state.emptySince > (O.emptyWait or 60) then
          BF.barred[key(quest)] = now() + 300
          BF.say(string.format("No %s for %d s: that quest is set aside for 5 min", quest.mob, O.emptyWait or 60))
          -- (only the farm's own quest is dropped: a story's quest it was fighting beside stays in hand)
          if (onScreen(quest)) then BF.dropQuest() end
          state.emptySince, chosen, hadQuest = nil, nil, false
        end
      end
    end
    task.wait()
  end
end

local function nearestLoop(ctx)
  while B.alive and not ctx.stop do
    if not ctx:body(40) then return end
    local root = BF.root()
    local mobs = root and BF.mobs(nil, root.Position) or {}
    local mob = mobs[1]
    if mob and (mob.HumanoidRootPart.Position - root.Position).Magnitude <= (O.nearRadius or 1500) then
      local result = BF.fight(mob, ctx, function() return {} end)
      if result == "died" then ctx:body(40) end
    else
      BF.release()
      ctx:sleep(1, "Nothing to fight nearby")
    end
    task.wait()
  end
end

local function mobLoop(ctx)
  local state = {}
  while B.alive and not ctx.stop do
    if not ctx:body(40) then return end
    local name = O.mobName or ""
    if name == "" then
      ctx:sleep(1, "Pick a mob first")
    else
      hunt(ctx, name, (BF.spawns(name)), state)
    end
    task.wait()
  end
end

-- the mobs that have a spawn in this sea, for the picker
local function mobNames()
  local origin = workspace:FindFirstChild("_WorldOrigin")
  local folder = origin and origin:FindFirstChild("EnemySpawns")
  local seen, out = {}, {}
  for _, mark in ipairs(folder and folder:GetChildren() or {}) do
    local name = string.match(mark.Name, "^(.-) %[Lv%.")
    if name and not seen[name] then seen[name] = true; out[#out + 1] = name end
  end
  table.sort(out)
  return out
end
BF.mobNames = mobNames

local function start()
  -- a quest paid: the game says so itself (QuestUpdate, Context "Complete")
  local remotes = S.ReplicatedStorage:FindFirstChild("Remotes")
  local update = remotes and remotes:FindFirstChild("QuestUpdate")
  if update and update:IsA("RemoteEvent") then
    B.connect(update.OnClientEvent, function(_, info)
      if type(info) == "table" and info.Context == "Complete" then
        BF.count.quests += 1
        BF.say("Quest paid: " .. tostring(info.Name))
      end
    end, "bloxfruits.quest")
  end
  BF.job({ id = "level", label = "Auto level", priority = 50, switch = "bloxfruits.level", quiet = 25, patience = 240, want = function() return O.level == true end, run = levelLoop })
  BF.job({ id = "mob", label = "Farm a mob", priority = 40, switch = "bloxfruits.mobFarm", quiet = 25, patience = 300, want = function() return O.mobFarm == true end, run = mobLoop })
  BF.job({ id = "nearest", label = "Farm nearest", priority = 30, switch = "bloxfruits.nearest", quiet = 25, patience = 300, want = function() return O.nearest == true end, run = nearestLoop })
end

local function farm(page)
  local level = page:section({ title = "Auto level", icon = "arrow-up", desc = "Takes the quest worth most, fights its mobs, hands it in, again." })
  level:toggle({ id = "bloxfruits.level", label = "Auto level", desc = "Quests and mobs come from the game's own tables.", default = false, children = function(sub)
    sub:dropdown({ id = "bloxfruits.questMode", label = "Which quest", options = { { "fast", "Fastest XP" }, { "balanced", "Balanced" }, { "easy", "Easy enemies" } } })
    sub:toggle({ id = "bloxfruits.takeQuest", label = "Take the quest", desc = "Off: fights the quest's mobs with no quest.", default = true, bindable = false })
    sub:toggle({ id = "bloxfruits.skipBoss", label = "Skip boss quests", default = true, bindable = false })
    sub:slider({ id = "bloxfruits.stopLevel", label = "Stop at level", tip = "0 = never.", min = 0, max = 2800, step = 25, default = 0 })
    sub:slider({ id = "bloxfruits.switchGain", label = "Switch quest only if better by", min = 0, max = 100, step = 5, default = 15, suffix = "%" })
    sub:slider({ id = "bloxfruits.recheck", label = "Look for a better quest every", min = 10, max = 600, step = 10, default = 60, suffix = " s" })
    sub:slider({ id = "bloxfruits.maxTrip", label = "Longest trip to a quest", tip = "A trip is made once for each new quest. Portals count as short.", min = 1000, max = 60000, step = 1000, default = 30000,
      suffix = " st" })
  end })
  local wait = page:section({ title = "When the mobs are gone", icon = "clock" })
  wait:slider({ id = "bloxfruits.spawnWait", label = "Wait at each spawn", min = 1, max = 15, step = 1, default = 3, suffix = " s" })
  wait:slider({ id = "bloxfruits.emptyWait", label = "Set the quest aside after", tip = "Seconds with none of its mobs alive.", min = 20, max = 300, step = 10, default = 60, suffix = " s" })
  local other = page:section({ title = "Other farms", icon = "target", column = 2 })
  other:toggle({ id = "bloxfruits.nearest", label = "Farm nearest", desc = "Whatever is alive close by, no quest.", default = false, children = function(sub)
    sub:slider({ id = "bloxfruits.nearRadius", label = "Within", min = 100, max = 5000, step = 100, default = 1500, suffix = " st" })
  end })
  local names = {}
  for _, name in ipairs(mobNames()) do names[#names + 1] = { name, name } end
  if #names == 0 then names[1] = { "", "None found" } end
  other:toggle({ id = "bloxfruits.mobFarm", label = "Farm one mob", desc = "Only the mob picked below, at its own spawns.", default = false, children = function(sub)
    sub:dropdown({ id = "bloxfruits.mobName", label = "Mob", options = names })
  end })
  local _ = Window
end

BF.parts[#BF.parts + 1] = { id = "farm", start = start, farm = farm,
  defaults = { level = false, questMode = "fast", takeQuest = true, skipBoss = true, stopLevel = 0, switchGain = 15, recheck = 60, maxTrip = 30000, spawnWait = 3,
    emptyWait = 60, nearest = false, nearRadius = 1500, mobFarm = false, mobName = "" } }
local _ = S
end
do -- bloxfruits_fruit.lua
-- ============================================================================
--  Blox Fruits     fruits: seen, picked up, stored, bought
--
--  Read from the game's own code (dump 2753915549 v4630, fast/), NOT run live.
--   * A fruit on the ground is a Tool directly under workspace ("Sand Fruit")
--     with an EatRemote; a natural spawn is named "Fruit " (the game's own
--     Comm script waits for workspace."Fruit ", StarterPlayerScripts/Comm:158).
--     Its real name is the attribute OriginalName ("Sand-Sand"), the key of
--     every fruit table of the game (FruitInfo, StoreFruit, GetFruits).
--   * Store: CommF_ "StoreFruit", OriginalName, the tool (EatFruit:150). The
--     server answers true (stored), a number (full: that many of each fruit
--     already) or false. Nothing here ever calls an EatRemote.
--   * The dealer: CommF_ "GetFruits", advanced? (useServerData:57) and
--     "PurchaseRawFruit", name, advanced?, dragonType (FruitShop/StateUtil:67).
--     A purchase is NOT a fruit in the bag: "Buying here will grant you the
--     powers ... Buying a new fruit will directly replace your existing one"
--     (DialoguesList/NPCs/FruitShop:23). So buying always eats.
--   * Random fruit (Zioles, "Blox Fruit Gacha"): GachaClient.CheckGachaAsync /
--     PurchaseGachaAsync("ZiolesGacha") (RandomFruitSeller:146, GachaWindow:299).
--     That one IS a physical fruit, so the store picks it up after.
-- ============================================================================
local B = B or ...
local S, util, UI, Config, Window, Motion = B.S, B.util, B.UI, B.Config, B.Window, B.Motion
local BF = B.BloxFruits
local O = BF.O
local function now() return os.clock() end

local RARITIES = { "Common", "Uncommon", "Rare", "Legendary", "Mythical", "Premium" }
-- (Rarity.Value in FruitInfo: Common 0 ... Premium 5)
local RARITY_COLOR = { [0] = Color3.fromRGB(205, 205, 205), [1] = Color3.fromRGB(126, 231, 135), [2] = Color3.fromRGB(110, 170, 255),
  [3] = Color3.fromRGB(190, 130, 255), [4] = Color3.fromRGB(255, 95, 95), [5] = Color3.fromRGB(255, 210, 90) }
local GACHA_BOX, GACHA_NPC = "ZiolesGacha", "Blox Fruit Gacha"   -- RandomFruitSeller.luau:146

-- Set-aside and tries are kept apart for storing and for picking up: a pick-up that failed is no reason not to store that
-- fruit, and a fruit the storage refused may still be picked up again once dropped. Strong tables the engine prunes
-- (BF.keep): a weak Instance key can vanish while the fruit is still in the game, and "never again" would be lost.
local function kept() return BF.keep and BF.keep({}) or {} end
local Fruit = { world = {}, pickAside = kept(), pickTries = kept(), pickDeaths = kept(), storeAside = kept(), storeTries = kept(), ui = {} }
BF.fruit = Fruit

-- ---------------------------------------------------------------- names and rarities, from the game's own tables
local names = {}
-- "Sand-Sand" -> "Sand" (ReplicatedStorage.Modules.Asset.GetFruitName, a plain function)
local function display(key)
  if type(key) ~= "string" or key == "" then return "none" end
  local known = names[key]
  if known then return known end
  local fn = BF.mod("Modules", "Asset", "GetFruitName")
  local ok, name = false, nil
  if type(fn) == "function" then ok, name = BF.game(fn, key) end
  name = (ok and type(name) == "string") and name or (string.match(key, "^(.-)%-") or key)
  names[key] = name
  return name
end
-- FruitInfo.DATA[key].Rarity = { Value, Name } (ReplicatedStorage/FruitInfo.luau:94, :125)
local function rarityOf(key)
  local info = BF.mod("FruitInfo")
  local data = type(info) == "table" and type(info.DATA) == "table" and key and info.DATA[key]
  return type(data) == "table" and type(data.Rarity) == "table" and data.Rarity or nil
end
-- Which fruits the pick-up goes for (the owner's ask, 2026-11-13: "which fruit I want it to target and not go
-- pick up"): every one, only the ticked ones, or all but the ticked ones. A fruit is ticked by its name or by
-- its rarity. One whose name cannot be read is its own choice: it could be anything.
local function collectTicked(key)
  local picked = O.fruitCollectNames
  if type(picked) == "table" and table.find(picked, key) then return true end
  local rarity, ranks = rarityOf(key), O.fruitCollectRarities
  return rarity ~= nil and type(ranks) == "table" and table.find(ranks, rarity.Name) ~= nil
end
local function collectWanted(entry)
  local mode = O.fruitCollectMode or "all"
  if mode == "all" then return true end
  if not entry.key then return O.fruitCollectHidden ~= false end
  if mode == "only" then return collectTicked(entry.key) end
  return not collectTicked(entry.key)
end
-- every fruit the game knows, rarest last, for the pickers
local function fruitOptions()
  local info = BF.mod("FruitInfo")
  local list = {}
  for key, data in pairs(type(info) == "table" and type(info.DATA) == "table" and info.DATA or {}) do
    local rarity = type(data) == "table" and data.Rarity or {}
    list[#list + 1] = { key = key, value = tonumber(rarity.Value) or 0, rank = tostring(rarity.Name or "?") }
  end
  table.sort(list, function(a, b) if a.value ~= b.value then return a.value < b.value end return a.key < b.key end)
  local out = {}
  for _, item in ipairs(list) do out[#out + 1] = { item.key, display(item.key) .. "  ·  " .. item.rank } end
  if #out == 0 then out[1] = { "", "The game's fruit list is not readable" } end
  return out
end
local function money(n)
  local text = tostring(math.floor(tonumber(n) or 0))
  local out = text:reverse():gsub("(%d%d%d)", "%1,"):reverse()
  return (out:gsub("^,", ""))
end
local function clock(seconds)
  seconds = math.max(0, math.floor(seconds))
  if seconds >= 3600 then return string.format("%dh %02dm", seconds // 3600, (seconds % 3600) // 60) end
  return string.format("%dm %02ds", seconds // 60, seconds % 60)
end
-- a call into game code that also gives up: a server call that never answers costs `seconds`, not the caller
local function timed(seconds, fn, ...)
  local args = table.pack(...)
  local done, out = false, nil
  task.spawn(function()
    out = table.pack(BF.game(fn, table.unpack(args, 1, args.n)))
    done = true
  end)
  local started = now()
  while not done and now() - started < seconds do task.wait() end
  if not done then return false, "timeout" end
  return table.unpack(out, 1, out.n)
end

-- ---------------------------------------------------------------- fruits in the world
local function partOf(inst)
  if not inst or not inst.Parent then return nil end
  local handle = inst:FindFirstChild("Handle", true)
  if handle and handle:IsA("BasePart") then return handle end
  if inst:IsA("Model") and inst.PrimaryPart then return inst.PrimaryPart end
  return inst:FindFirstChildWhichIsA("BasePart", true)
end
-- a fruit lying in the world: a Tool with the fruit's EatRemote or name, or the natural spawn model "Fruit "
local function isFruit(inst)
  if inst:IsA("Tool") then
    return inst:FindFirstChild("EatRemote", true) ~= nil or inst:GetAttribute("OriginalName") ~= nil or string.find(inst.Name, "Fruit", 1, true) ~= nil
  end
  return inst:IsA("Model") and string.match(inst.Name, "^Fruit%s*$") ~= nil
end
local function keyOf(inst)
  local key = inst:GetAttribute("OriginalName")
  if type(key) == "string" then return key end
  -- (a spawn model may carry its tool, and the name, one level down)
  for _, child in ipairs(inst:GetChildren()) do
    local inner = child:GetAttribute("OriginalName")
    if type(inner) == "string" then return inner end
  end
  return nil
end
local function describe(inst)
  local key = keyOf(inst)
  if key then return display(key), key end
  local plain = string.gsub(inst.Name, "%s+$", "")
  if plain ~= "Fruit" then return plain, nil end
  return "Fruit (name hidden)", nil
end
local function away(part)
  local root = BF.root()
  return root and part and (part.Position - root.Position).Magnitude or nil
end
local function found(inst)
  if Fruit.world[inst] or inst.Parent ~= workspace or not isFruit(inst) then return end
  local name, key = describe(inst)
  local rarity = rarityOf(key)
  Fruit.world[inst] = { inst = inst, name = name, key = key, rarity = rarity, since = now() }
  local distance = away(partOf(inst))
  local where = distance and (util.studs(distance) .. " st away") or "somewhere"
  -- (said at once when the pick-up will not go for it, so a fruit left lying is never a puzzle)
  local left = O.fruitCollect == true and not collectWanted(Fruit.world[inst])
  BF.say(string.format("Fruit in the world: %s%s, %s%s", name, rarity and (" (" .. tostring(rarity.Name) .. ")") or "", where, left and ": not on your pick-up list, left there" or ""))
  if O.fruitNotify then
    Window.toast({ title = "A fruit appeared", text = name .. ", " .. where, icon = "apple", tone = "ok", time = 7 })
  end
end
local function watchWorld()
  for _, child in ipairs(workspace:GetChildren()) do
    if child:IsA("Tool") or child:IsA("Model") then pcall(found, child) end
  end
  B.connect(workspace.ChildAdded, function(child)
    if not (child:IsA("Tool") or child:IsA("Model")) then return end
    pcall(found, child)
    -- (a tool can arrive before its EatRemote and name: looked at once more a moment later)
    if child:IsA("Tool") and not Fruit.world[child] then
      task.delay(0.6, function() pcall(found, child) end)
    end
  end, "bloxfruits.fruitAdded")
  B.connect(workspace.ChildRemoved, function(child)
    Fruit.world[child] = nil
  end, "bloxfruits.fruitRemoved")
end
function Fruit.list()
  local out = {}
  for inst, entry in pairs(Fruit.world) do
    if inst.Parent == workspace then out[#out + 1] = entry else Fruit.world[inst] = nil end
  end
  return out
end

-- the marks on screen: a pooled layer of labels, drawn every frame only while the radar is on
local function marks()
  local gui = B.screen(7980)
  local layer = UI.frame(gui, { Name = "Fruits", Size = UDim2.fromScale(1, 1) })
  local pool, wrote, used = {}, {}, 0      -- wrote[i]: what label i shows now, so its text is built only when that changes
  local function label()
    used += 1
    local item = pool[used]
    if not item then
      item = UI.new("TextLabel", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(220, 14), FontFace = B.F.mono500, TextSize = 12,
        TextStrokeColor3 = Color3.new(0, 0, 0), TextStrokeTransparency = 0.4, Text = "", Visible = false, Parent = layer })
      pool[used] = item
      wrote[used] = {}
    end
    return item
  end
  local shown = false
  local function step()
    used = 0
    local camera = workspace.CurrentCamera
    if O.fruitEsp and camera then
      local from = camera.CFrame.Position
      for _, entry in ipairs(Fruit.list()) do
        -- (the part is looked up once, not searched for every frame)
        local part = entry.part
        if not (part and part.Parent) then
          part = partOf(entry.inst)
          entry.part = part
        end
        if part then
          local distance = (part.Position - from).Magnitude
          local point = camera:WorldToViewportPoint(part.Position)
          if point.Z > 0 and distance <= (O.fruitEspRange or 30000) then
            local item = label()
            -- (the distance is written in whole studs of ten: the text is rebuilt only when that changes, not every frame)
            local step10 = math.floor(distance / 10)
            local memo = wrote[used]
            if memo.at ~= step10 or memo.name ~= entry.name then
              memo.at, memo.name = step10, entry.name
              local text = string.format("%s  %s st", entry.name, util.studs(step10 * 10))
              if item.Text ~= text then item.Text = text end
            end
            -- (a property written only when it changed: a write every frame is a cost even with the same value)
            local color = RARITY_COLOR[entry.rarity and tonumber(entry.rarity.Value) or 0] or RARITY_COLOR[0]
            if item.TextColor3 ~= color then item.TextColor3 = color end
            local position = UDim2.fromOffset(math.floor(point.X + 0.5), math.floor(point.Y + 0.5))
            if item.Position ~= position then item.Position = position end
            if not item.Visible then item.Visible = true end
          end
        end
      end
    end
    if used == 0 and not shown then return end
    shown = used > 0
    for index = used + 1, #pool do
      if pool[index].Visible then pool[index].Visible = false end
    end
  end
  B.connect(S.RunService.RenderStepped, step, "bloxfruits.fruitMarks")
end

-- ---------------------------------------------------------------- fruits in the bag
local function bagFruits()
  local out = {}
  for _, holder in ipairs({ BF.char(), B.LP:FindFirstChild("Backpack") }) do
    for _, tool in ipairs(holder and holder:GetChildren() or {}) do
      if tool:IsA("Tool") and tool:FindFirstChild("EatRemote", true) then out[#out + 1] = tool end
    end
  end
  return out
end
Fruit.bag = bagFruits

-- ---------------------------------------------------------------- auto collect (a job: it needs the body)
local function nearestFruit()
  local root = BF.root()
  if not root then return nil end
  local best, bestAway
  local t = now()
  for _, entry in ipairs(Fruit.list()) do
    local part = partOf(entry.inst)
    if part and (Fruit.pickAside[entry.inst] or 0) <= t and collectWanted(entry) then
      -- (the trip as the body makes it, through a portal when that is shorter: a fruit across the whirlpool is near or far by that)
      local distance = BF.trip(root.Position, part.Position)
      if distance <= (O.fruitCollectRange or 12000) and (not bestAway or distance < bestAway) then best, bestAway = entry, distance end
    end
  end
  return best
end
local function mine(entry, before)
  local inst = entry.inst
  local character, pack = BF.char(), B.LP:FindFirstChild("Backpack")
  if (character and inst:IsDescendantOf(character)) or (pack and inst:IsDescendantOf(pack)) then return true end
  return #bagFruits() > before
end
-- One try: fly over it, then stand the body on its Handle (a Tool in the world is picked up by touching its Handle,
-- the engine's own pick-up; no prompt or remote for it is in the game's code). Returns "got", "gone", "dead", "stopped" or "missed".
local function tryPick(ctx, entry)
  local part = partOf(entry.inst)
  if not part then return "gone" end
  local ok, why = BF.fly(part.Position + Vector3.new(0, 4, 0), ctx, { note = "To " .. entry.name })
  if not ok then return why == "stopped" and "stopped" or (why == "dead" and "dead" or "missed") end
  local before = #bagFruits()
  for _, lift in ipairs({ 0, -1.5, 1.5 }) do
    part = partOf(entry.inst)
    if not part or entry.inst.Parent ~= workspace then break end
    if not BF.alive() then return "dead" end
    BF.holdAt(part.Position + Vector3.new(0, lift, 0))
    local untilAt = now() + 0.8
    while now() < untilAt and not ctx.stop do
      if mine(entry, before) then return "got" end
      -- (killed while standing on it: not the fruit's fault, so no try is counted against it)
      if not BF.alive() then return "dead" end
      ctx:beat("Picking up " .. entry.name)
      task.wait(0.05)
    end
  end
  if ctx.stop then return "stopped" end
  if mine(entry, before) then return "got" end
  if not BF.alive() then return "dead" end
  return entry.inst.Parent ~= workspace and "gone" or "missed"
end
local function collectLoop(ctx)
  while B.alive and not ctx.stop do
    if not ctx:body(40) then return end
    local entry = nearestFruit()
    if not entry then BF.release(); return end
    local result = tryPick(ctx, entry)
    if result == "stopped" then return end
    if result == "dead" then
      BF.release()
      -- (a death is not a try; but a fruit someone guards must not cost a life for ever: three deaths set it aside)
      local deaths = (Fruit.pickDeaths[entry.inst] or 0) + 1
      Fruit.pickDeaths[entry.inst] = deaths
      if deaths >= 3 then
        Fruit.pickAside[entry.inst] = now() + 600
        Fruit.pickDeaths[entry.inst] = nil
        BF.say(string.format("Died %d times going for %s: set aside for 10 min", deaths, entry.name))
        ctx:progress()
      else
        BF.say("Died going for " .. entry.name .. ": waiting for the body, then again")
      end
      ctx:body(40)
    elseif result == "got" then
      Fruit.world[entry.inst] = nil
      BF.say("Picked up " .. entry.name)
      Window.toast({ title = "Fruit picked up", text = entry.name, icon = "apple", tone = "ok", time = 5 })
      ctx:progress()
    elseif result == "gone" then
      Fruit.world[entry.inst] = nil
      BF.say(entry.name .. " was gone before it was reached")
      ctx:progress()
    else
      local tries = (Fruit.pickTries[entry.inst] or 0) + 1
      Fruit.pickTries[entry.inst] = tries
      if tries >= (O.fruitCollectTries or 4) then
        Fruit.pickAside[entry.inst] = now() + 600
        Fruit.pickTries[entry.inst] = nil
        BF.say(string.format("%s could not be picked up in %d tries: set aside for 10 min", entry.name, tries))
        ctx:progress()
      else
        ctx:sleep(0.5, "Trying " .. entry.name .. " again")
      end
    end
    BF.release()
    task.wait()
  end
end

-- ---------------------------------------------------------------- auto store (no body needed)
local storing = false
local function storeWanted(key)
  if O.fruitStoreMode ~= "ticked" then return true end
  local picked = O.fruitStoreNames
  if type(picked) == "table" and table.find(picked, key) then return true end
  local rarity, ranks = rarityOf(key), O.fruitStoreRarities
  return rarity ~= nil and type(ranks) == "table" and table.find(ranks, rarity.Name) ~= nil
end
local function storeOne(tool, key)
  local hum = BF.hum()
  if not hum then return end
  local name = display(key)
  -- The game's own Store option sends the fruit while it is held out (EatFruit.luau:141-150): it is held the same way.
  -- A running farm re-arms its weapon every swing (BF.hit -> BF.equip), which would put the fruit back in the bag before
  -- StoreFruit is sent: BF.casting holds the farm's swings and re-arming off until the store is done (1.5 s + 8 s at most).
  local hold = now() + 10
  if (BF.casting or 0) < hold then BF.casting = hold end
  local ok, answer
  local done, err = pcall(function()
    if tool.Parent ~= BF.char() then
      pcall(function() hum:EquipTool(tool) end)
      local untilAt = now() + 1.5
      while tool.Parent ~= BF.char() and now() < untilAt do task.wait(0.05) end
    end
    ok, answer = BF.invoke(8, "StoreFruit", key, tool)            -- DialoguesList/NPCs/EatFruit.luau:150
    -- (put away again only if the fruit is still what is held: a weapon some other part armed meanwhile is left in the hand)
    local character = BF.char()
    if character and tool.Parent == character then pcall(function() hum:UnequipTools() end) end
  end)
  -- (let go only if no other part has asked for longer meanwhile)
  if BF.casting == hold then BF.casting = 0 end
  if not done then error(err, 0) end
  if ok and answer == true then
    Fruit.storeTries[tool] = nil
    BF.say("Stored " .. name)
    Window.toast({ title = "Fruit stored", text = name, icon = "package", tone = "ok", time = 5 })
  elseif ok and typeof(answer) == "number" then
    -- (EatFruit.luau:151: a number is the capacity for each fruit, already reached: this fruit is stored already)
    Fruit.storeAside[tool] = math.huge
    BF.say(string.format("%s not stored: you already store %d of it (the server says the storage is full)", name, answer))
  else
    local tries = (Fruit.storeTries[tool] or 0) + 1
    Fruit.storeTries[tool] = tries
    if tries >= 3 then
      Fruit.storeAside[tool] = now() + 600
      Fruit.storeTries[tool] = nil
      BF.say(string.format("%s was not stored 3 times (%s): left alone for 10 min", name, tostring(answer)))
    end
  end
end
local function storeRound()
  if not O.fruitStore or storing or not BF.alive() then return end
  local t = now()
  for _, tool in ipairs(bagFruits()) do
    if (Fruit.storeAside[tool] or 0) <= t then
      local key = tool:GetAttribute("OriginalName")
      if type(key) ~= "string" then
        Fruit.storeAside[tool] = math.huge
        BF.say(tool.Name .. " has no OriginalName: it cannot be stored by name")
      elseif storeWanted(key) then
        storing = true
        task.spawn(function()
          local ok, err = pcall(storeOne, tool, key)
          if not ok then BF.say("Store failed: " .. string.sub(tostring(err), 1, 80)) end
          task.wait(1)
          storing = false
        end)
        return
      end
    end
  end
end

-- ---------------------------------------------------------------- the dealer: stock and the sniper
-- bought: every fruit a purchase was sent for this session (never sent twice); boughtAt: the last confirmed purchase
local snipe = { busy = false, at = -1e9, was = false, stock = "Not checked yet.", last = "Nothing bought.", barred = {}, bought = {}, boughtAt = nil }
-- the dealer restocks on the hour mark of every 4 h (advanced: 2 h) (React/Hooks/Fruit/useRestockTime.luau:11, :20)
local function restockIn(advanced)
  local period = advanced and 7200 or 14400
  local t = os.time()
  return (t - t % period + period) - t
end
-- { { key, price, rarity, onSale } } of one dealer, or nil and why
local function stock(advanced)
  local ok, answer = BF.invoke(10, "GetFruits", advanced)           -- React/Hooks/Fruit/useServerData.luau:57
  if not ok then return nil, tostring(answer) end
  if type(answer) ~= "table" then return nil, "no list" end
  local out = {}
  -- (every fruit is in the answer, OnSale says which are in stock; Name, Price and Rarity are integers the game itself checks:
  -- useServerData.luau:9-19. A row without a real price is left out, so nothing is ever bought at an unknown price)
  for _, item in pairs(answer) do
    if type(item) == "table" and type(item.Name) == "string" and type(item.Price) == "number" and item.Price > 0 then
      out[#out + 1] = { key = item.Name, price = item.Price, rarity = tonumber(item.Rarity) or 0, onSale = item.OnSale == true }
    end
  end
  table.sort(out, function(a, b) return a.price < b.price end)
  return out
end
local function stockText(label, list, advanced)
  local parts = {}
  for _, item in ipairs(list) do
    if item.onSale then parts[#parts + 1] = string.format("%s $%s", display(item.key), money(item.price)) end
  end
  return string.format("%s: %s  (restock in %s)", label, #parts > 0 and table.concat(parts, ", ") or "nothing", clock(restockIn(advanced)))
end
local function buy(item, advanced)
  local before = BF.data("DevilFruit")
  -- (remembered BEFORE the call, for the whole session, confirmed or not: a purchase whose confirmation was only slow is never
  -- sent a second time, and with "May replace my fruit" on two ticked fruits can never be bought back and forth)
  snipe.bought[item.key] = true
  local ok, answer = BF.invoke(10, "PurchaseRawFruit", item.key, advanced, nil)   -- Controllers/UI/FruitShop/StateUtil.luau:67
  -- (confirmed when the eaten fruit becomes the one bought: buying gives the powers, FruitShop dialogue :23)
  local untilAt = now() + 4
  while BF.data("DevilFruit") ~= item.key and now() < untilAt do task.wait(0.1) end
  local confirmed = BF.data("DevilFruit") == item.key and before ~= item.key
  snipe.last = string.format("%s  %s for $%s: %s", os.date("%H:%M"), display(item.key), money(item.price),
    confirmed and "the server confirmed it" or ("not confirmed (" .. (ok and "answer " or "") .. tostring(answer) .. ")"))
  BF.say("Dealer: " .. snipe.last)
  if confirmed then
    snipe.boughtAt = now()
    Window.toast({ title = "Fruit bought", text = display(item.key), icon = "apple", tone = "ok", time = 6 })
    if O.fruitSnipeOnce then Config.set("bloxfruits.fruitSnipe", false) end
  end
  return confirmed
end
-- rarity first, then price: is a ranked strictly above b?
local function above(a, b)
  if a.rarity ~= b.rarity then return a.rarity > b.rarity end
  return a.price > b.price
end
-- The eaten fruit's rank, from the dealers' own answer (it lists every fruit, in stock or not: useServerData.luau:9-19).
-- nil when it is not in either list: then nothing counts as better than it.
local function rankOf(key, lists)
  for _, list in pairs(lists) do          -- (pairs: the first dealer may be missing)
    for _, item in ipairs(list) do
      if item.key == key then return item end
    end
  end
  return nil
end
-- what to buy of one dealer's stock now, or nil and why not
local function pick(list, lists)
  local wanted = type(O.fruitSnipeNames) == "table" and O.fruitSnipeNames or {}
  local eaten = BF.data("DevilFruit") or ""
  local beli = tonumber(BF.data("Beli")) or 0
  -- (with Replace on, the fruit now eaten, if ticked itself, is the bar: only a fruit ranked strictly above it is bought,
  -- so two ticked fruits in stock are never bought in turn)
  local bar = nil
  if eaten ~= "" and table.find(wanted, eaten) then
    bar = rankOf(eaten, lists)
    if not bar then return nil, display(eaten) .. " is eaten and ticked, but its rank is not in the dealer's list" end
  end
  -- (with Replace on, one purchase then a 10 min rest: whatever was just bought is used before anything replaces it)
  if O.fruitSnipeReplace and snipe.boughtAt and now() - snipe.boughtAt < 600 then
    return nil, "a fruit was bought " .. clock(now() - snipe.boughtAt) .. " ago: no other for 10 min"
  end
  local best, why
  for _, item in ipairs(list) do
    if item.onSale and table.find(wanted, item.key) and (snipe.barred[item.key] or 0) <= now() then
      if item.key == eaten then
        why = why or (display(item.key) .. " is already your fruit")
      elseif snipe.bought[item.key] then
        why = why or (display(item.key) .. " was bought once this session: not again")
      elseif item.key == "Dragon-Dragon" then
        -- (the game asks East or West first: FruitShop.luau:564-567; not chosen here)
        why = why or "Dragon needs a choice the hub does not make"
      elseif eaten ~= "" and not O.fruitSnipeReplace then
        why = why or ("in stock, but buying would replace your " .. display(eaten))
      elseif bar and not above(item, bar) then
        why = why or string.format("%s does not rank above your %s", display(item.key), display(eaten))
      elseif beli - item.price < (O.fruitSnipeReserve or 0) then
        why = why or string.format("%s costs $%s: that would go under your reserve", display(item.key), money(item.price))
      elseif not best or above(item, best) then
        best = item
      end
    end
  end
  return best, why
end
local function snipeRound(buying)
  if snipe.busy then return end
  snipe.busy = true
  task.spawn(function()
    local ok, err = pcall(function()
      local normal, whyNormal = stock(false)
      local lines = { normal and stockText("Dealer", normal, false) or ("Dealer: not read (" .. tostring(whyNormal) .. ")") }
      local advanced = O.fruitSnipeAdvanced and stock(true) or nil
      if O.fruitSnipeAdvanced then
        lines[#lines + 1] = advanced and stockText("Advanced dealer", advanced, true) or "Advanced dealer: none here"
      end
      snipe.stock = table.concat(lines, "\n")
      if not buying then return end
      for _, dealer in ipairs({ { normal, false }, { advanced, true } }) do
        if dealer[1] then
          local item, why = pick(dealer[1], { normal, advanced })
          if item then buy(item, dealer[2]); return end
          if why then snipe.stock = snipe.stock .. "\nNot bought: " .. why end
        end
      end
    end)
    if not ok then snipe.stock = "Stock check failed: " .. string.sub(tostring(err), 1, 80) end
    snipe.at = now()
    snipe.busy = false
  end)
end
local function snipeTick()
  if not O.fruitSnipe then snipe.was = false; return end
  -- once when switched on, then every interval
  if not snipe.was or now() - snipe.at >= (O.fruitSnipeEvery or 120) then
    snipe.was = true
    snipeRound(true)
  end
end

-- ---------------------------------------------------------------- random fruit (Zioles' gacha)
local gacha = { busy = false, next = 0, line = "Not checked yet." }
local function gachaClient()
  local client = BF.mod("Controllers", "GachaClient")
  return type(client) == "table" and client or nil
end
-- the server's own answer: { Cooldown = { RequirementMet, TimeEnds }, Price = { RequirementMet, Value }, Keys = { Silver = { .. } },
-- Level = { RequirementMet, Value, Current }, PaidRandomItemsRestricted = { Value } } (GachaWindow/Controllers/Cousin.luau:36-42, :117)
local function gachaCheck()
  local client = gachaClient()
  if not client or type(client.CheckGachaAsync) ~= "function" then return nil, "the game's GachaClient is not readable" end
  local ok, answer = timed(8, client.CheckGachaAsync, GACHA_BOX, GACHA_NPC)    -- DialoguesList/NPCs/RandomFruitSeller.luau:146
  if not ok or type(answer) ~= "table" then return nil, tostring(answer) end
  return answer
end
local function field(info, name, key)
  local part = type(info) == "table" and info[name]
  if type(part) ~= "table" then return nil end
  return part[key]
end
-- can it be bought right now, by the game's own rule and the player's: true, or false and why
-- the answer's shape, as the game's own window reads it: Price.Value (RandomFruitSeller.luau:151, :174), Cooldown.RequirementMet /
-- TimeEnds (Cousin.luau:36, :117-118), Keys.Silver.RequirementMet / Value (Cousin.luau:39, :87-90). Anything else: nothing is bought.
local function gachaShape(info)
  if type(info) ~= "table" then return "no answer" end
  local missing = {}
  if type(info.Price) ~= "table" or type(info.Price.Value) ~= "number" then missing[#missing + 1] = "Price" end
  if type(info.Cooldown) ~= "table" then missing[#missing + 1] = "Cooldown" end
  if type(info.Keys) ~= "table" or type(info.Keys.Silver) ~= "table" then missing[#missing + 1] = "Keys" end
  if #missing == 0 then return nil end
  local got = {}
  for key in pairs(info) do got[#got + 1] = tostring(key) end
  table.sort(got)
  return string.format("unexpected answer (no %s; got %s)", table.concat(missing, ", "), #got > 0 and table.concat(got, ", ", 1, math.min(#got, 6)) or "nothing")
end
local function gachaReady(info)
  local bad = gachaShape(info)
  if bad then return false, bad end
  if field(info, "Level", "RequirementMet") == false then return false, "needs level " .. tostring(field(info, "Level", "Value")) end
  if field(info, "PaidRandomItemsRestricted", "Value") then return false, "the game does not allow it on this account" end
  -- With a Silver Key the server takes the key, not Beli, and skips the cooldown (Cousin.luau:39, :87-90): so with a key in
  -- hand there is no buying with Beli at all. Keys are spent only with the switch on, and never below the number kept.
  local keys = info.Keys.Silver
  if keys.RequirementMet == true then
    if not O.fruitRandomKeys then return false, "it would spend a Silver Key (keys are off)" end
    local count = tonumber(keys.Value)
    if not count then return false, "the number of Silver Keys is not readable" end
    local keep = math.max(0, math.floor(tonumber(O.fruitRandomKeysKeep) or 0))
    if count <= keep then return false, string.format("%d Silver Key%s, keeping %d", count, count == 1 and "" or "s", keep) end
    return true
  end
  if info.Cooldown.RequirementMet ~= true then
    local ends = tonumber(info.Cooldown.TimeEnds) or 0
    return false, ends > os.time() and ("next in " .. clock(ends - os.time())) or "the cooldown is not over"
  end
  local price = info.Price.Value
  if info.Price.RequirementMet ~= true then return false, "not enough Beli ($" .. money(price) .. ")" end
  if (tonumber(BF.data("Beli")) or 0) - price < (O.fruitRandomReserve or 0) then return false, "$" .. money(price) .. " would go under your reserve" end
  return true
end
local function gachaRound(buying)
  if gacha.busy then return end
  gacha.busy = true
  task.spawn(function()
    local ok, err = pcall(function()
      local info, why = gachaCheck()
      if not info then
        gacha.line, gacha.next = "Not read: " .. tostring(why), now() + 120
        return
      end
      local price = tonumber(field(info, "Price", "Value")) or 0
      local ready, reason = gachaReady(info)
      gacha.line = string.format("Random fruit $%s  ·  %s", money(price), ready and "ready" or reason)
      if not ready then
        local ends = tonumber(field(info, "Cooldown", "TimeEnds")) or 0
        local wait = ends > os.time() and (ends - os.time() + 3) or 120
        gacha.next = now() + math.clamp(wait, 20, 900)
        return
      end
      if not buying then gacha.next = now() + 30; return end
      local client = gachaClient()
      local done, bought, failure = timed(10, client.PurchaseGachaAsync, GACHA_BOX)      -- Controllers/UI/GachaWindow.luau:299
      if done and bought then
        gacha.line = os.date("%H:%M") .. "  random fruit bought: the server confirmed it"
        BF.say("Random fruit bought")
        Window.toast({ title = "Random fruit", text = "Bought. It is in your bag.", icon = "apple", tone = "ok", time = 6 })
      else
        local message = type(failure) == "table" and failure.ErrorMessage or failure
        gacha.line = "Not bought: " .. tostring(message or bought or "no answer")
        BF.say("Random fruit " .. string.lower(gacha.line))
      end
      gacha.next = now() + 60
    end)
    if not ok then gacha.line, gacha.next = "Check failed: " .. string.sub(tostring(err), 1, 80), now() + 120 end
    gacha.busy = false
  end)
end
local function gachaTick()
  if O.fruitRandom and now() >= gacha.next then gachaRound(true) end
end

-- ---------------------------------------------------------------- the fruits you own
-- stored counts: ItemReplication.Quantity of each fruit's physical item (ItemConfig "PhysicalMoveset", as FruitShop.luau:142-148 reads ownership)
local stored = { busy = false, line = "Press Show." }
local function storedRound()
  if stored.busy then return end
  stored.busy = true
  task.spawn(function()
    local ok, err = pcall(function()
      local info, config, rep = BF.mod("FruitInfo"), BF.mod("ItemConfig"), BF.mod("Util", "ItemReplication")
      if not (type(info) == "table" and type(config) == "table" and type(rep) == "table" and type(rep.Quantity) == "table") then
        stored.line = "The game's item tables are not readable."
        return
      end
      local have = {}
      for key in pairs(info.DATA or {}) do
        local got, item = BF.game(config.tryGet, key, "PhysicalMoveset")
        local id = got and type(item) == "table" and type(item.Index) == "table" and item.Index.ItemId
        if id then
          local read, count = timed(2, rep.Quantity.readClient, id)
          count = read and tonumber(count) or 0
          if count > 0 then have[#have + 1] = string.format("%s x%d", display(key), count) end
        end
      end
      table.sort(have)
      stored.line = #have > 0 and table.concat(have, ", ") or "None stored."
    end)
    if not ok then stored.line = "Not read: " .. string.sub(tostring(err), 1, 80) end
    stored.busy = false
  end)
end

-- ---------------------------------------------------------------- start
local function start()
  watchWorld()
  marks()
  Motion.every(function() B.try("bloxfruits.fruitStore", storeRound) end, 1, "bloxfruits.fruitStore")
  Motion.every(function() B.try("bloxfruits.fruitSnipe", snipeTick) end, 1, "bloxfruits.fruitSnipe")
  Motion.every(function() B.try("bloxfruits.fruitRandom", gachaTick) end, 1, "bloxfruits.fruitRandom")
  BF.job({ id = "fruitCollect", label = "Fruit pick-up", priority = 80, switch = "bloxfruits.fruitCollect", quiet = 25, patience = 180,
    want = function() return O.fruitCollect == true and BF.alive() and nearestFruit() ~= nil end, run = collectLoop })
end

-- ---------------------------------------------------------------- the tab
local function worldLine()
  local list = Fruit.list()
  if #list == 0 then return "No fruit in the world right now." end
  local parts = {}
  for _, entry in ipairs(list) do
    local distance = away(partOf(entry.inst))
    parts[#parts + 1] = entry.name .. (distance and (" " .. util.studs(distance) .. " st") or "")
  end
  return string.format("%d in the world: %s", #list, table.concat(parts, ", "))
end
local function fruit(page)
  local options = fruitOptions()
  local ranks = {}
  for _, name in ipairs(RARITIES) do ranks[#ranks + 1] = { name, name } end

  local radar = page:section({ title = "In the world", icon = "radar", desc = "Seen the moment one lands or spawns." })
  radar:toggle({ id = "bloxfruits.fruitEsp", label = "Fruit radar", desc = "Name and distance on screen, coloured by rarity.", default = false, children = function(sub)
    sub:slider({ id = "bloxfruits.fruitEspRange", label = "Show within", min = 500, max = 60000, step = 500, default = 30000, suffix = " st" })
  end })
  radar:toggle({ id = "bloxfruits.fruitNotify", label = "Tell me when one appears", desc = "A toast with its name and distance.", default = false, bindable = false })
  local seen = radar:note({ icon = "map-pin", text = worldLine() })

  local pick = page:section({ title = "Pick up", icon = "navigation", desc = "Flies to it, picks it up, then the farm goes on." })
  pick:toggle({ id = "bloxfruits.fruitCollect", label = "Auto collect", desc = "Goes before any farm while a fruit is out.", default = false, children = function(sub)
    sub:segmented({ id = "bloxfruits.fruitCollectMode", label = "Pick up", options = { { "all", "Every fruit" }, { "only", "Only ticked" }, { "skip", "All but ticked" } }, width = 330 })
    sub:multi({ id = "bloxfruits.fruitCollectRarities", label = "Ticked rarities", options = ranks, default = {} })
    sub:multi({ id = "bloxfruits.fruitCollectNames", label = "Ticked fruits", options = options, default = {} })
    sub:toggle({ id = "bloxfruits.fruitCollectHidden", label = "A fruit with no name shown too", desc = "Off: one whose name cannot be read is left.", default = true, bindable = false })
    sub:slider({ id = "bloxfruits.fruitCollectRange", label = "Only within", min = 500, max = 60000, step = 500, default = 12000, suffix = " st" })
    sub:slider({ id = "bloxfruits.fruitCollectTries", label = "Tries before setting it aside", min = 1, max = 10, step = 1, default = 4 })
  end })

  local store = page:section({ title = "Store", icon = "package", column = 2, desc = "Never eats a fruit." })
  store:toggle({ id = "bloxfruits.fruitStore", label = "Auto store", desc = "Puts fruits from your bag into the fruit storage.", default = false, children = function(sub)
    sub:segmented({ id = "bloxfruits.fruitStoreMode", label = "Store", options = { { "all", "Every fruit" }, { "ticked", "Only ticked" } }, width = 240 })
    sub:multi({ id = "bloxfruits.fruitStoreRarities", label = "Rarities", options = ranks, default = {} })
    sub:multi({ id = "bloxfruits.fruitStoreNames", label = "Fruits", options = options, default = {} })
  end })

  local dealer = page:section({ title = "Dealer sniper", icon = "target", full = true, desc = "Buying from the dealer gives the powers at once: it eats the fruit." })
  dealer:toggle({ id = "bloxfruits.fruitSnipe", label = "Fruit sniper", desc = "Buys a ticked fruit when the dealer has it.", default = false, children = function(sub)
    sub:multi({ id = "bloxfruits.fruitSnipeNames", label = "Fruits to buy", options = options, default = {} })
    sub:slider({ id = "bloxfruits.fruitSnipeReserve", label = "Keep at least", tip = "Beli left after buying.", min = 0, max = 10000000, step = 25000, default = 0, suffix = " Beli" })
    sub:slider({ id = "bloxfruits.fruitSnipeEvery", label = "Check every", min = 30, max = 1800, step = 30, default = 120, suffix = " s" })
    sub:toggle({ id = "bloxfruits.fruitSnipeOnce", label = "Stop after one purchase", default = false, bindable = false })
    sub:toggle({ id = "bloxfruits.fruitSnipeReplace", label = "May replace my fruit", desc = "Off: buys only while no fruit is eaten.", default = false, bindable = false })
    sub:toggle({ id = "bloxfruits.fruitSnipeAdvanced", label = "Advanced dealer too", desc = "Only where that dealer exists.", default = false, bindable = false })
  end })
  dealer:button({ id = "bloxfruits.fruitStockNow", label = "Check stock now", desc = "Reads the stock; buys only if the sniper is on.", text = "Check", run = function()
    snipeRound(O.fruitSnipe == true)
  end })
  local stockNote = dealer:note({ icon = "tag", text = snipe.stock })
  local lastNote = dealer:note({ icon = "history", text = snipe.last })

  local random = page:section({ title = "Random fruit", icon = "gem", column = 2, desc = "Zioles' gacha: a real fruit, into your bag." })
  random:button({ id = "bloxfruits.fruitRandomNow", label = "Buy a random fruit", desc = "Only when the game says it is ready.", text = "Buy", run = function()
    gachaRound(true)
  end })
  random:toggle({ id = "bloxfruits.fruitRandom", label = "As soon as it is ready", desc = "Waits out the cooldown the server gives.", default = false, children = function(sub)
    sub:toggle({ id = "bloxfruits.fruitRandomKeys", label = "May spend Silver Keys", desc = "A key skips the cooldown, so keys go fast.", default = false, bindable = false,
      children = function(keys)
        keys:slider({ id = "bloxfruits.fruitRandomKeysKeep", label = "Keys to keep", tip = "Never spends below this many.", min = 0, max = 100, step = 1, default = 0 })
      end })
    sub:slider({ id = "bloxfruits.fruitRandomReserve", label = "Keep at least", min = 0, max = 10000000, step = 25000, default = 0, suffix = " Beli" })
  end })
  random:button({ id = "bloxfruits.fruitRandomCheck", label = "Check the cooldown", text = "Check", run = function() gachaRound(false) end })
  local gachaNote = random:note({ icon = "clock", text = gacha.line })

  local own = page:section({ title = "Your fruits", icon = "apple", column = 2 })
  local eatenNote = own:note({ icon = "apple", text = "" })
  own:button({ id = "bloxfruits.fruitStoredNow", label = "Stored fruits", desc = "Reads what the fruit storage holds.", text = "Show", run = storedRound })
  local storedNote = own:note({ icon = "package", text = stored.line })

  Motion.every(function()
    if not (seen.frame.Parent and Window.anyOpen()) then return end
    seen.set(worldLine())
    stockNote.set(snipe.stock)
    lastNote.set(snipe.last)
    gachaNote.set(gacha.line)
    storedNote.set(stored.line)
    local bag = {}
    for _, tool in ipairs(bagFruits()) do bag[#bag + 1] = display(tool:GetAttribute("OriginalName")) end
    eatenNote.set(string.format("Eaten: %s  ·  in the bag: %s", display(BF.data("DevilFruit")), #bag > 0 and table.concat(bag, ", ") or "none"))
  end, 2, "bloxfruits.fruitTab")
  local _ = Config
end

BF.parts[#BF.parts + 1] = { id = "fruit", start = start, fruit = fruit,
  defaults = { fruitEsp = false, fruitEspRange = 30000, fruitNotify = false, fruitCollect = false, fruitCollectRange = 12000, fruitCollectTries = 4,
    fruitCollectMode = "all", fruitCollectRarities = {}, fruitCollectNames = {}, fruitCollectHidden = true, fruitStore = false, fruitStoreMode = "all", fruitStoreRarities = {}, fruitStoreNames = {}, fruitSnipe = false, fruitSnipeNames = {}, fruitSnipeReserve = 0,
    fruitSnipeEvery = 120, fruitSnipeOnce = false, fruitSnipeReplace = false, fruitSnipeAdvanced = false, fruitRandom = false, fruitRandomKeys = false,
    fruitRandomKeysKeep = 0, fruitRandomReserve = 0 } }
end
do -- bloxfruits_loot.lua
-- ============================================================================
--  Blox Fruits     loot: chests, berries, materials, bones
--
--  Read from the game's own code (dump 2753915549 v4630, `fast\` folder), never
--  tried live: every line below is unproven until measured.
--
--   * A chest is a server part (ChestTypes names: Chest1/2/3, FragChest,
--     DiamondChest) that the server streams to the client with
--     Remotes.Chest(part, true/false), or that carries the tag "_ChestTagged".
--     It is taken by TOUCHING it: the client's own touch only plays the lid
--     (ClientChest.luau:304-319), the server confirms by setting the chest's
--     "IsDisabled" attribute to true, and the client gives up on a pick-up the
--     server has not confirmed after 3 s (ClientChest.luau:88-100). No chest
--     cooldown is in the client's code: the server's own limit is unknown, so
--     the pace is a setting and a chest that is not confirmed is set aside.
--     The chests of islands far from the body are parked under
--     ReplicatedStorage.Unloaded (ClientChest.luau:331-337) and come back to
--     workspace.Map as their island loads.
--   * A berry is claimed with Net "RF/ClaimBerry" (bush model name, slot key),
--     from within the game's prompt reach (15 studs), no faster than its own
--     0.3 s debounce (BerryBushClient.luau:83, 99, 104).
--   * Materials are counted with Net "RF/GetCraftPlayerData" (the craft
--     window's own call): its answer's EtcItems[name] is the count
--     (CraftWindow.luau:27, 101, 558). The client holds NO table of which mob
--     drops what: that table below is from public guides, unverified.
--   * Bones: CommF_ "Bones", "Check" -> bones, offers, purchases left, minutes
--     to wait, purchases per 2 hours; "Bones", "Buy", 1, option -> 1 done, 2 not
--     enough bones, 3 already owned, or a sentence (Halloween1.luau:28-85).
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion = B.S, B.Config, B.Window, B.Motion
local BF = B.BloxFruits
local O = BF.O
local function now() return os.clock() end
-- the distance on the ground: a trip climbs before it crosses, and a height change is not "further away"
local function flat(a, b) return Vector3.new(a.X - b.X, 0, a.Z - b.Z).Magnitude end
-- how long a trip may take before what it went for is given up (generous: the pilot slows itself after pull-backs)
local function tripBudget(to)
  local root = BF.root()
  if not root then return 30 end
  return (BF.trip(root.Position, to)) / 120 + 20
end
-- (the leeway a running job of opportunity has over its own reach: with none, the edge of the reach flapped)
local MARGIN = 1.25

local LOOT = { chests = 0, beli = 0, frags = 0, berries = 0, rolls = 0, failed = 0 }
BF.loot = LOOT
local jobs = {}             -- this part's job specs, by id (the wants ask whether their own job holds the body)

-- ---------------------------------------------------------------- calls
-- A Net remote of the game's, through its own module. The folder is checked first: Net's `get` waits up to 99 s for a
-- remote that is not there (Modules/Net.luau:219).
local remotes = {}
local function netRF(name)
  local got = remotes[name]
  if got then return got end
  local modules = S.ReplicatedStorage:FindFirstChild("Modules")
  local folder = modules and modules:FindFirstChild("Net")
  if not (folder and folder:FindFirstChild("RF/" .. name)) then return nil end
  local net = BF.mod("Modules", "Net")
  if not net then return nil end
  local ok, remote = BF.game(net.RemoteFunction, net, name)      -- Modules/Net.luau:252 (Net:RemoteFunction(name))
  if not ok or remote == nil then return nil end
  remotes[name] = remote
  return remote
end
-- One InvokeServer on a Net remote with an end to the wait (a virtual remote is game code: it goes through BF.game).
local function ask(timeout, remote, ...)
  local args = table.pack(...)
  local done, out = false, nil
  BF.count.calls += 1
  task.spawn(function()
    out = table.pack(BF.game(function() return remote:InvokeServer(table.unpack(args, 1, args.n)) end))
    done = true
  end)
  local started = now()
  while not done and now() - started < (timeout or 6) do task.wait() end
  if not done then return false, "timeout" end
  return table.unpack(out, 1, out.n)
end

-- the materials in the stash: { [name] = count }, asked at most every 8 s
local etc, etcAt = nil, -1e9
function BF.etcItems(fresh)
  if etc and not fresh and now() - etcAt < 8 then return etc end
  local remote = netRF("GetCraftPlayerData")
  if not remote then return etc end
  -- CraftWindow.luau:101  u2:InvokeServer()  (u2 = Net:RemoteFunction("GetCraftPlayerData"), line 27); EtcItems read at line 558
  local ok, data = ask(8, remote)
  etcAt = now()
  if ok and type(data) == "table" and type(data.EtcItems) == "table" then etc = data.EtcItems end
  return etc
end
local function etcCount(name, fresh)
  local items = BF.etcItems(fresh)
  if not items then return nil end
  return tonumber(items[name]) or 0
end

-- ---------------------------------------------------------------- chests: which exist
local CHEST_NAMES = { Chest1 = true, Chest2 = true, Chest3 = true, DiamondChest = true, FragChest = true }    -- ChestTypes.luau:3-7
-- (plain tables the engine prunes of chests no longer in the game: a weak key could vanish while the chest still exists, and lose "set aside")
local known = BF.keep({})      -- chest part -> true
local aside = BF.keep({})      -- chest part -> until when it is not tried
local function learnChest(part)
  if typeof(part) == "Instance" and part:IsA("BasePart") then known[part] = true end
end
-- named as a chest type, a part, and chest-sized (a wall named "Chest1" is not a chest)
local function isChest(item)
  return CHEST_NAMES[item.Name] == true and item:IsA("BasePart") and item.Size.Magnitude < 15
end
local function unloadedFolder() return S.ReplicatedStorage:FindFirstChild("Unloaded") end
local function inWorld(part) return part.Parent ~= nil and part:IsDescendantOf(workspace) end
-- Parked: under ReplicatedStorage.Unloaded, where the game keeps the chests of far islands (ClientChest.luau:331-337). The part and its
-- position are still there; it goes back under workspace.Map when its island loads near the body.
local function parked(part)
  local folder = unloadedFolder()
  return folder ~= nil and part.Parent ~= nil and part:IsDescendantOf(folder)
end
-- the server's word that a chest is taken: the attribute the client itself reads (ClientChest.luau:153-161, ChestSettings.luau:5 UPDATE_ATTRIBUTE)
local function disabled(part) return part:GetAttribute("IsDisabled") == true end
-- Free to take: in the world and not disabled. A parked chest counts only for the chest-only farm, which flies to its island.
local function open(part, parkedOk)
  if disabled(part) then return false end
  return inWorld(part) or (parkedOk == true and parked(part))
end
-- the free chests within `range` (on the ground) of a point, the shortest trip first; with `first`, the first one found and no more
local function chestsNear(from, range, parkedOk, first)
  local list, t = {}, now()
  for part in pairs(known) do
    if not ((aside[part] or 0) > t) and open(part, parkedOk) then
      local gap = flat(part.Position, from)
      if gap <= range then
        if first then return { { part = part, gap = gap } } end
        list[#list + 1] = { part = part, gap = gap }
      end
    end
  end
  -- (a far island may be nearer through a portal: the chest-only farm orders by the trip as the body makes it)
  if parkedOk then
    for _, entry in ipairs(list) do entry.gap = (BF.trip(from, entry.part.Position)) end
  end
  table.sort(list, function(a, b) return a.gap < b.gap end)
  return list
end
-- Where chests are learned: the stream remote and the tag (in `start`), and the chest-named parts of workspace.Map and
-- ReplicatedStorage.Unloaded. Those two are walked once, a few hundred instances a frame, then followed by their DescendantAdded
-- (an island moving between them fires it for every part in it). One GetDescendants of the whole map every minute was a hitch.
local function walk(folder)
  task.spawn(function()
    local stack, seen = { folder }, 0
    while #stack > 0 and B.alive do
      local node = table.remove(stack)
      for _, child in ipairs(node:GetChildren()) do
        if CHEST_NAMES[child.Name] and isChest(child) then known[child] = true end
        stack[#stack + 1] = child
        seen += 1
      end
      if seen >= 400 then seen = 0; task.wait() end
    end
  end)
end
local watching = {}         -- "map" / "unloaded" -> { folder, connection }
local function watch(key, folder)
  local held = watching[key]
  if held and held.folder == folder then return end
  if held then pcall(function() held.connection:Disconnect() end) end
  watching[key] = nil
  if not folder then return end
  local connection = B.connect(folder.DescendantAdded, function(item)
    if CHEST_NAMES[item.Name] and isChest(item) then known[item] = true end
  end, "bloxfruits.lootWatch")
  watching[key] = { folder = folder, connection = connection }
  walk(folder)
end

-- ---------------------------------------------------------------- chests: taking one
-- The chest the job is on its way to. Once picked it stays wanted until it is taken, refused, set aside or its time runs out:
-- a distance check alone flapped (the trip climbs first, which pushed the chest out of reach and stopped the job every 2 s).
local chase = nil           -- { part, untilAt, trips }
local function asideFor(part, seconds)
  aside[part] = now() + seconds
  if chase and chase.part == part then chase = nil end
end
local function chaseOpen(parkedOk)
  if not chase then return false end
  local part = chase.part
  if now() > chase.untilAt then
    asideFor(part, O.chestRetry or 90)
    BF.say("A chest took too long to reach: set aside")
    return false
  end
  if (aside[part] or 0) > now() or not open(part, parkedOk) then chase = nil; return false end
  return true
end
-- (how long a parked chest's island is waited for once the body is over it)
local LOAD_WAIT = 6
-- Fly onto the chest and stay on it until the server says it is taken, at most the game's own 3 s.
-- Returns "taken", "refused" (the server did not confirm it), "unreachable", "gone" (it left the world, or someone else took it),
-- "died" or "stopped", and a reason.
local function takeChest(ctx, part)
  local beli, frags = tonumber(BF.data("Beli")) or 0, tonumber(BF.data("Fragments")) or 0
  local speed = O.chestSpeed or 200
  local function failed(why) return why == "stopped" and "stopped" or (why == "dead" and "died" or "unreachable"), why end
  if not inWorld(part) then
    -- (parked: flown to above it, and its island waited for; the chest moves back into the world as the island loads)
    local ok, why = BF.fly(part.Position + Vector3.new(0, 30, 0), ctx, { speed = speed, note = "To a far chest" })
    if not ok then return failed(why) end
    local untilAt = now() + LOAD_WAIT
    while now() < untilAt and not inWorld(part) do
      if ctx.stop or not B.alive then return "stopped" end
      if not BF.alive() then return "died" end
      ctx:beat("Waiting for the island to load")
      task.wait(0.2)
    end
    if not inWorld(part) then return "gone", "its island did not load" end
  end
  if disabled(part) then return "gone", "taken by someone else" end
  local ok, why = BF.fly(part.Position, ctx, { speed = speed, note = "To a chest" })
  if not ok then return failed(why) end
  local untilAt = now() + 3
  while now() < untilAt and inWorld(part) and not disabled(part) do
    if ctx.stop or not B.alive then return "stopped" end
    if not BF.alive() then return "died" end
    -- (on its centre, then a stud lower: the touch needs the body inside the chest's part)
    local low = now() > untilAt - 1.5 and Vector3.new(0, -1, 0) or Vector3.zero
    BF.holdAt(part.Position + low)
    ctx:beat("Opening a chest")
    task.wait(0.1)
  end
  -- (only the server's IsDisabled is a chest taken: a chest whose island unloaded under the body left the world untaken)
  if not disabled(part) then
    if inWorld(part) then return "refused", "not confirmed" end
    return "gone", "it left the world"
  end
  -- (the money lands a moment after the lid: waited for a little)
  ctx:sleep(0.4, "Chest taken")
  LOOT.chests += 1
  LOOT.beli += math.max(0, (tonumber(BF.data("Beli")) or 0) - beli)
  LOOT.frags += math.max(0, (tonumber(BF.data("Fragments")) or 0) - frags)
  ctx:progress()
  return "taken"
end
local function chestRange()
  return O.chestMode == "only" and (O.chestRoam or 5000) or (O.chestRange or 1500)
end
-- Does this chest job (chestNear or chestOnly) want the body: its chest on the way, or a free chest within reach (a little further
-- while it holds the body). The chest-only farm also goes to parked chests.
local function chestWants(job)
  if O.chestFarm ~= true then return false end
  local only = O.chestMode == "only"
  if (job.id == "chestOnly") ~= only then return false end
  if chaseOpen(only) then return true end
  local root = BF.root()
  if not root then return false end
  local range = chestRange() * (BF.running() == job and MARGIN or 1)
  return #chestsNear(root.Position, range, only, true) > 0
end
local function chestLoop(ctx)
  local misses = 0
  local only = ctx.job.id == "chestOnly"
  while B.alive and not ctx.stop do
    if not ctx:body(40) then
      if ctx.stop or not B.alive then return end
      -- (never returned while it is still wanted: the director would count that as a failure)
      ctx:sleep(2, "Waiting for the body")
      continue
    end
    if not chestWants(ctx.job) then
      -- (nothing left in reach: the job ends, its want is false now and the body goes back to the farm)
      BF.release()
      return
    end
    if not chase then
      local root = BF.root()
      local pick = root and chestsNear(root.Position, chestRange() * MARGIN, only)[1]
      if pick then chase = { part = pick.part, untilAt = now() + tripBudget(pick.part.Position) + LOAD_WAIT, trips = 0 } end
    end
    if not chase then
      ctx:sleep(1, "Looking for a chest")
      continue
    end
    local part = chase.part
    -- (a trip cut short by a job that needs the body never comes back here: so trips are counted as they begin.
    -- Two cut short and the third is not made, the chest is left for a while)
    chase.trips += 1
    if chase.trips > 2 then
      BF.say("A chest was interrupted twice on the way: set aside")
      asideFor(part, O.chestRetry or 90)
      continue
    end
    local result, why = takeChest(ctx, part)
    if result == "stopped" then return end
    if result == "died" then
      -- (a death on the way is not a miss: the body is waited for at the top and the same chest tried again)
      if chase and chase.part == part then chase.trips -= 1 end
    elseif result == "taken" then
      chase, misses = nil, 0
    else
      asideFor(part, O.chestRetry or 90)
      if result == "refused" then
        LOOT.failed += 1
        BF.say(string.format("The server did not take a chest (%s): not tried again for %d s", part.Name, O.chestRetry or 90))
      else
        BF.say(string.format("A chest was not taken (%s): set aside", tostring(why)))
      end
      if result ~= "gone" then misses += 1 end
    end
    if misses >= 5 then
      -- (five in a row not taken: the server may be refusing chests for now. Not hammered)
      BF.say("Five chests in a row were not taken: chests rest for 3 min")
      for each in pairs(known) do aside[each] = now() + 180 end
      chase, misses = nil, 0
      continue
    end
    ctx:sleep(O.chestGap or 1, "Next chest")
  end
end

-- ---------------------------------------------------------------- berries
-- A bush: the part tagged "BerryBush" (BerryBushOctree.luau:85); its parent model holds the slots as attributes
-- "_BerryCFrame..." (a CFrame from the model's "CFrame" attribute); the tagged part names the berry in a slot (BerryBushClient.luau:47-79).
local CollectionService = game:GetService("CollectionService")
local berryAside = {}       -- "bush/slot" -> until when
-- the ripe berries within `range` (on the ground) of a point, nearest first; with `first`, the first one found and no more
local function berries(from, range, first)
  local list, t = {}, now()
  for _, tagged in ipairs(CollectionService:GetTagged("BerryBush")) do
    local bush = tagged.Parent
    local base = bush and bush:GetAttribute("CFrame")
    if typeof(base) == "CFrame" and flat(base.Position, from) <= range then
      for key, slot in pairs(bush:GetAttributes()) do
        if string.sub(key, 1, 12) == "_BerryCFrame" and typeof(slot) == "CFrame" and tagged:GetAttribute(key) then
          local id = bush.Name .. "/" .. key
          if not ((berryAside[id] or 0) > t) then
            local at = base:ToWorldSpace(slot).Position          -- BerryBushClient.luau:12 (loadCF)
            local entry = { bush = bush.Name, slot = key, tagged = tagged, at = at, id = id, gap = flat(at, from) }
            if first then return { entry } end
            list[#list + 1] = entry
          end
        end
      end
    end
  end
  table.sort(list, function(a, b) return a.gap < b.gap end)
  return list
end
-- the berry the job is on its way to (the same reason as the chest's: wanted until it is claimed, gone, set aside or late)
local berryChase = nil      -- a `berries` entry + untilAt, trips
local function berryChaseOpen()
  local berry = berryChase
  if not berry then return false end
  if now() > berry.untilAt then
    berryAside[berry.id], berryChase = now() + 120, nil
    return false
  end
  if (berryAside[berry.id] or 0) > now() or berry.tagged.Parent == nil or not berry.tagged:GetAttribute(berry.slot) then
    berryChase = nil
    return false
  end
  return true
end
local function berryWants(job)
  if O.berryFarm ~= true then return false end
  if berryChaseOpen() then return true end
  local root = BF.root()
  if not root then return false end
  local range = (O.berryRange or 2000) * (BF.running() == job and MARGIN or 1)
  return #berries(root.Position, range, true) > 0
end
local function berryLoop(ctx)
  while B.alive and not ctx.stop do
    if not ctx:body(40) then
      if ctx.stop or not B.alive then return end
      ctx:sleep(2, "Waiting for the body")
      continue
    end
    local remote = netRF("ClaimBerry")
    if not remote then
      BF.say("No ClaimBerry remote in this server: berries are off")
      Config.set("bloxfruits.berryFarm", false)
      BF.release()
      return
    end
    if not berryWants(ctx.job) then BF.release(); return end
    if not berryChase then
      local root = BF.root()
      local pick = root and berries(root.Position, (O.berryRange or 2000) * MARGIN)[1]
      if pick then
        pick.untilAt, pick.trips = now() + tripBudget(pick.at), 0
        berryChase = pick
      end
    end
    local berry = berryChase
    if not berry then
      ctx:sleep(1, "Looking for a berry")
      continue
    end
    -- (counted as the trip begins, as for chests: two cut short and it is left for a while)
    berry.trips += 1
    if berry.trips > 2 then
      BF.say("A berry was interrupted twice on the way: set aside for 2 min")
      berryAside[berry.id], berryChase = now() + 120, nil
      continue
    end
    -- (the game's prompt reaches 15 studs: stood 4 above the berry)
    local ok, why = BF.fly(berry.at + Vector3.new(0, 4, 0), ctx, { speed = O.chestSpeed or 200, note = "To a berry" })
    if not ok then
      if why == "stopped" then return end
      if why == "dead" then
        berry.trips -= 1                  -- (a death is not a miss: the body is waited for at the top)
      else
        berryAside[berry.id], berryChase = now() + 120, nil
      end
    else
      berryChase = nil
      -- BerryBushClient.luau:104  u1:InvokeServer(Parent.Name, key)  (u1 = Net:RemoteFunction("ClaimBerry"), line 3)
      local sent, answer = ask(6, remote, berry.bush, berry.slot)
      if sent and answer then
        LOOT.berries += 1
        ctx:progress()
      else
        berryAside[berry.id] = now() + 120
        BF.say("A berry was not given (" .. tostring(answer) .. "): set aside for 2 min")
      end
      -- (the game's own debounce is 0.3 s: BerryBushClient.luau:99)
      ctx:sleep(0.5, "Next berry")
    end
  end
end

-- ---------------------------------------------------------------- materials
-- Which mobs drop what: FROM PUBLIC GUIDES, UNVERIFIED. The client holds no drop table (searched: NPCDrop is a Beli pop-up,
-- Types/Material.luau only rarity and stack). A material is offered only if one of its mobs has a spawn in this server.
BF.MATERIALS = {
  { "Scrap Metal", { "Brute", "Pirate", "Swan Pirate", "Factory Staff", "Jungle Pirate", "Forest Pirate" } },
  { "Leather", { "Pirate", "Brute", "Marine Captain", "Jungle Pirate" } },
  { "Magma Ore", { "Military Soldier", "Military Spy", "Lava Pirate", "Magma Ninja" } },
  { "Angel Wings", { "Royal Soldier", "Royal Squad" } },
  { "Fish Tail", { "Fishman Warrior", "Fishman Commando", "Fishman Raider", "Fishman Captain" } },
  { "Radioactive Material", { "Factory Staff" } },
  { "Vampire Fang", { "Vampire" } },
  { "Mystic Droplet", { "Water Fighter", "Sea Soldier" } },
  { "Mini Tusk", { "Mythological Pirate" } },
  { "Gunpowder", { "Pistol Billionaire" } },
  { "Conjured Cocoa", { "Chocolate Bar Battler", "Cocoa Warrior", "Sweet Thief", "Candy Rebel" } },
  { "Dragon Scale", { "Dragon Crew Warrior", "Dragon Crew Archer" } },
  { "Ectoplasm", { "Ship Deckhand", "Ship Engineer", "Ship Steward", "Ship Officer" } },
  { "Demonic Wisp", { "Demonic Soul" } },
  { "Bones", { "Reborn Skeleton", "Living Zombie", "Demonic Soul", "Posessed Mummy", "Possessed Mummy" } },
  { "Yeti Fur", { "Snow Lurker", "Arctic Warrior" } },
}
local BONE_MOBS = BF.MATERIALS[15][2]
-- the mobs of a list that have a spawn here (or were seen here)
local function present(names)
  local out = {}
  for _, name in ipairs(names) do
    if #(BF.spawns(name)) > 0 then out[#out + 1] = name end
  end
  return out
end
local function mobsFor(material)
  for _, row in ipairs(BF.MATERIALS) do
    if row[1] == material then return present(row[2]) end
  end
  return {}
end
-- The living mobs of these names that are set aside as stuck: BF.mobs leaves them out, and "none alive" would be the wrong reason.
-- Returns how many, and when the first of them is let back in.
local function stuckAlive(names)
  local folder = workspace:FindFirstChild("Enemies")
  local wanted, count, soonest, t = {}, 0, nil, now()
  for _, name in ipairs(names) do wanted[name] = true end
  for _, mob in ipairs(folder and folder:GetChildren() or {}) do
    local untilAt = wanted[mob.Name] and BF.shunned[mob]
    if untilAt and untilAt > t and BF.living(mob) then
      count += 1
      soonest = math.min(soonest or untilAt, untilAt)
    end
  end
  return count, soonest
end
-- The next spawn point to wait at: the nearest on the island being worked (points within ISLAND studs of where it began), and only
-- once that island's points are all visited the nearest trip to another. In mob-name order the farm crossed the sea between every wait.
local ISLAND = 1500
local function pointKey(point) return string.format("%d,%d,%d", math.floor(point.X / 10), math.floor(point.Y / 10), math.floor(point.Z / 10)) end
local function nextSpawn(state, points, from)
  state.visited = state.visited or {}
  local left = {}
  for _, point in ipairs(points) do
    if not state.visited[pointKey(point)] then left[#left + 1] = point end
  end
  if #left == 0 then
    -- (every point visited: a new round, from wherever the body is)
    table.clear(state.visited)
    state.anchor, left = nil, points
  end
  local best, bestGap
  if state.anchor then
    for _, point in ipairs(left) do
      if flat(point, state.anchor) <= ISLAND then
        local gap = flat(point, from)
        if not bestGap or gap < bestGap then best, bestGap = point, gap end
      end
    end
  end
  if not best then
    for _, point in ipairs(left) do
      local gap = (BF.trip(from, point))
      if not bestGap or gap < bestGap then best, bestGap = point, gap end
    end
    state.anchor = best
  end
  state.visited[pointKey(best)] = true
  return best
end
-- Fight the nearest living mob of any of these names; with none alive, wait over their spawns, one island at a time.
local function huntAny(ctx, names, state)
  local root = BF.root()
  if not root then return "none" end
  local best, bestGap
  for _, name in ipairs(names) do
    local mob = BF.mobs(name, root.Position)[1]
    local gap = mob and (mob.HumanoidRootPart.Position - root.Position).Magnitude
    if mob and (not bestGap or gap < bestGap) then best, bestGap = mob, gap end
  end
  if best then
    state.emptySince, state.stuckSaid = nil, nil
    local name = best.Name
    local result = BF.fight(best, ctx, function()
      local mine = BF.root()
      return BF.mobs(name, mine and mine.Position)
    end)
    if result == "died" then ctx:body(40) end
    return result
  end
  local stuck, freeAt = stuckAlive(names)
  if stuck > 0 then
    -- (they are alive but set aside as stuck: a short wait for them to be let back in, or for new ones, and the true reason said)
    state.emptySince = nil
    if not state.stuckSaid then
      state.stuckSaid = true
      BF.say(string.format("%d of these mobs are set aside as stuck: waiting for them", stuck))
    end
    ctx:sleep(math.clamp((freeAt or now()) - now(), 1, 5), "Mobs set aside as stuck: waiting")
    return "stuck"
  end
  state.stuckSaid = nil
  state.emptySince = state.emptySince or now()
  local points = {}
  for _, name in ipairs(names) do
    for _, point in ipairs((BF.spawns(name))) do points[#points + 1] = point end
  end
  if #points == 0 then ctx:sleep(1, "No spawn known for these mobs"); return "none" end
  local point = nextSpawn(state, points, root.Position)
  if BF.fly(point + Vector3.new(0, O.height or 25, 0), ctx, { note = "To where they come back" }) then
    ctx:sleep(O.spawnWait or 3, "Waiting for them to come back")
  end
  return "none"
end
-- one farm for "a material to a target": the material farm and the bone farm are both this
local resting = {}          -- job id -> until when it is not wanted (its mobs were gone too long)
local function farmTo(ctx, id, material, names, target, switch)
  local state, checkedAt = {}, -1e9
  while B.alive and not ctx.stop do
    if not ctx:body(40) then
      if ctx.stop or not B.alive then return end
      -- (never returned while it is still wanted: the director would count that as a failure)
      ctx:sleep(2, "Waiting for the body")
      continue
    end
    if now() - checkedAt > 15 then
      checkedAt = now()
      local have = etcCount(material, true)
      if have and target > 0 and have >= target then
        BF.say(string.format("%s: %d of %d, done", material, have, target))
        Config.set(switch, false)
        BF.release()
        return
      end
      if have then ctx:beat(string.format("%s: %d of %d", material, have, target)) end
    end
    huntAny(ctx, names, state)
    if state.emptySince and now() - state.emptySince > 120 then
      resting[id] = now() + 300
      BF.say(string.format("No %s mob alive for 2 min: that farm rests 5 min", material))
      BF.release()
      return
    end
    task.wait()
  end
end
local function materialLoop(ctx)
  local material = O.material or ""
  local names = mobsFor(material)
  if #names == 0 then
    BF.say("No mob of this sea drops " .. (material ~= "" and material or "that") .. ": material farm off")
    Config.set("bloxfruits.matFarm", false)
    return
  end
  farmTo(ctx, "material", material, names, O.matTarget or 0, "bloxfruits.matFarm")
end
local function bonesLoop(ctx)
  local names = present(BONE_MOBS)
  if #names == 0 then
    BF.say("No bone mob here (Third Sea, Haunted Castle): bone farm off")
    Config.set("bloxfruits.bonesFarm", false)
    return
  end
  farmTo(ctx, "bones", "Bones", names, O.bonesTarget or 0, "bloxfruits.bonesFarm")
end

-- ---------------------------------------------------------------- the Death King's roll
local roll = { once = false, nextAt = 0, last = "Not asked yet." }
BF.boneRoll = roll
-- Halloween1.luau:28  CommF_:InvokeServer("Bones", "Check") -> bones, offers ({ [1] = { { label, cost }, ... } }), left, minutes, per 2 h.
-- An answer without a number of bones or a list of offers is taken as a refusal (from afar, maybe), never as "0 bones".
local function bonesCheck()
  local ok, bones, offers, left, minutes, most = BF.invoke(6, "Bones", "Check")
  if not ok then return nil, tostring(bones) end
  if tonumber(bones) == nil or type(offers) ~= "table" then return nil, "refused (" .. tostring(bones) .. ")" end
  return { bones = tonumber(bones) or 0, offers = type(offers[1]) == "table" and offers[1] or {}, left = tonumber(left) or 0, minutes = tonumber(minutes) or 0,
    most = tonumber(most) or 0 }
end
-- the offer that is the random roll, read from the Death King's own list (never guessed: none found = nothing bought)
local function rollOffer(info)
  for key, offer in pairs(info.offers) do
    local label = type(offer) == "table" and string.lower(tostring(offer[1])) or ""
    if string.find(label, "random", 1, true) or string.find(label, "surprise", 1, true) then return key, offer end
  end
  return nil
end
local function offersText(info)
  local parts = {}
  for key, offer in pairs(info.offers) do
    if type(offer) == "table" then parts[#parts + 1] = string.format("%s = %s (%s)", tostring(key), tostring(offer[1]), tostring(offer[2])) end
  end
  return table.concat(parts, ", ")
end
-- To the Death King: where he was seen, or looked for (his model is in the workspace only within about 200 studs of him: NOTES 11:26).
local function toDeathKing(ctx)
  local at = BF.npcSeen["Death King"] or BF.findNpc(ctx, "Death King", "Haunted Castle")
  if not at then return nil, "The Death King was not found (Third Sea, Haunted Castle)." end
  local ok, why = BF.fly(at + Vector3.new(0, 3, 4), ctx, { note = "To the Death King" })
  if not ok then return nil, "Could not reach the Death King: " .. tostring(why) end
  return at
end
local BUY_SAID = { [1] = "Trade completed.", [2] = "Not enough bones.", [3] = "You already have this item." }
local function rollOnce(ctx)
  -- (asked from where the body stands first: dialogue commands on CommF_ have worked from afar, NOTES 11:31. Only a refusal sends it to him)
  local near = false
  local info, err = bonesCheck()
  if not info then
    local at, why = toDeathKing(ctx)
    if not at then roll.last = why; return false, 120 end
    near = true
    info, err = bonesCheck()
    if not info then roll.last = "No answer: " .. tostring(err); return false, 60 end
  end
  if info.left <= 0 then
    roll.last = string.format("%d rolls left; come back in %d min (%d per 2 hours).", info.left, info.minutes, info.most)
    return false, math.max(60, info.minutes * 60)
  end
  local key, offer = rollOffer(info)
  if not key then roll.last = "No random roll among his offers: " .. offersText(info); return false, 600 end
  if info.bones < (tonumber(offer[2]) or 0) then
    roll.last = string.format("%d bones, the roll costs %s.", info.bones, tostring(offer[2]))
    return false, 300
  end
  -- Halloween1.luau:62  CommF_:InvokeServer("Bones", "Buy", 1, key) -> 1 done, 2 not enough bones, 3 already owned, else a sentence
  local sent, answer = BF.invoke(6, "Bones", "Buy", 1, key)
  if sent and not BUY_SAID[answer] and not near then
    -- (an answer that is none of the three, sent from afar: once more standing at him. A fresh check first, so a roll that went
    -- through after all is not bought twice. A call that timed out is not sent again: it may have been taken)
    local at = toDeathKing(ctx)
    if at then
      local again = bonesCheck()
      if again and again.bones < info.bones then
        answer = 1
      elseif again then
        sent, answer = BF.invoke(6, "Bones", "Buy", 1, key)
      end
    end
  end
  roll.last = sent and (BUY_SAID[answer] or tostring(answer)) or ("No answer: " .. tostring(answer))
  if sent and answer == 1 then LOOT.rolls += 1; ctx:progress() end
  BF.say("Death King: " .. roll.last)
  return sent and answer == 1, 2
end
local function rollLoop(ctx)
  while B.alive and not ctx.stop do
    if not ctx:body(40) then
      if ctx.stop or not B.alive then return end
      -- (no body: tried again in a little while, and its want is false until then, so returning is not a failure)
      roll.nextAt = now() + 30
      return
    end
    local done, wait = rollOnce(ctx)
    roll.once = false
    roll.nextAt = now() + (wait or 2)
    if not done then BF.say("Death King: " .. roll.last) end
    BF.release()
    -- (one roll per turn of the job: the director gives it back while rolls are wanted and allowed)
    return
  end
end

-- ---------------------------------------------------------------- start
local function start()
  -- chests: the server streams them (ChestListener.luau:55, Remotes.Chest(part, isRegistered)), older builds tag them (ChestListenerOld.luau:51-57)
  local remoteFolder = S.ReplicatedStorage:FindFirstChild("Remotes")
  local chestEvent = remoteFolder and remoteFolder:FindFirstChild("Chest")
  if chestEvent and chestEvent:IsA("RemoteEvent") then
    B.connect(chestEvent.OnClientEvent, function(part, registered)
      if registered then learnChest(part) end
    end, "bloxfruits.lootChest")
  end
  for _, part in ipairs(CollectionService:GetTagged("_ChestTagged")) do learnChest(part) end      -- ChestSettings.luau:5 (STREAM_TAG)
  B.connect(CollectionService:GetInstanceAddedSignal("_ChestTagged"), learnChest, "bloxfruits.lootTag")
  B.connect(CollectionService:GetInstanceRemovedSignal("_ChestTagged"), function(part)
    -- (forgotten, unless it is still a chest-named part of the map or of the parked islands, which the chest-only farm needs)
    if typeof(part) == "Instance" and not (isChest(part) and (inWorld(part) or parked(part))) then known[part] = nil end
  end, "bloxfruits.lootTagGone")
  -- (the map and the parked islands are followed only while the chest farm is on; a folder the game replaces is followed anew)
  Motion.every(function()
    B.try("bloxfruits.lootWatch", function()
      local on = O.chestFarm == true
      watch("map", on and workspace:FindFirstChild("Map") or nil)
      watch("unloaded", on and unloadedFolder() or nil)
    end)
  end, 0.5, "bloxfruits.lootWatch")

  jobs.chestNear = BF.job({ id = "chestNear", label = "Chests on the way", priority = 60, switch = "bloxfruits.chestFarm", quiet = 25, patience = 120,
    want = function() return chestWants(jobs.chestNear) end, run = chestLoop })
  jobs.chestOnly = BF.job({ id = "chestOnly", label = "Chest farm", priority = 55, switch = "bloxfruits.chestFarm", quiet = 25, patience = 120,
    want = function() return chestWants(jobs.chestOnly) end, run = chestLoop })
  jobs.berries = BF.job({ id = "berries", label = "Berries", priority = 58, switch = "bloxfruits.berryFarm", quiet = 25, patience = 120,
    want = function() return berryWants(jobs.berries) end, run = berryLoop })
  -- (patience 600: looking for the Death King island by island is slow and makes no progress on the way)
  jobs.boneRoll = BF.job({ id = "boneRoll", label = "Death King roll", priority = 72, switch = "bloxfruits.boneRoll", quiet = 25, patience = 600,
    want = function() return (O.boneRoll == true or roll.once) and BF.sea() == 3 and now() >= roll.nextAt end, run = rollLoop })
  jobs.material = BF.job({ id = "material", label = "Material farm", priority = 44, switch = "bloxfruits.matFarm", quiet = 25, patience = 300,
    want = function() return O.matFarm == true and now() >= (resting.material or 0) end, run = materialLoop })
  jobs.bones = BF.job({ id = "bones", label = "Bone farm", priority = 43, switch = "bloxfruits.bonesFarm", quiet = 25, patience = 300,
    want = function() return O.bonesFarm == true and BF.sea() == 3 and now() >= (resting.bones or 0) end, run = bonesLoop })
end

-- ---------------------------------------------------------------- the tab
local function countLine()
  return string.format("%d chests  ·  %d Beli  ·  %d Fragments  ·  %d berries  ·  %d rolls  ·  %d chests refused", LOOT.chests, LOOT.beli, LOOT.frags, LOOT.berries,
    LOOT.rolls, LOOT.failed)
end
local function materialOptions()
  local out = {}
  for _, row in ipairs(BF.MATERIALS) do
    if #present(row[2]) > 0 then out[#out + 1] = { row[1], row[1] } end
  end
  if #out == 0 then out[1] = { "", "None in this sea" } end
  return out
end
local function showStash()
  task.spawn(function()
    local items = BF.etcItems(true)
    if not items then
      Window.toast({ title = "Materials", text = "The game did not answer.", icon = "gem", time = 4 })
      return
    end
    local parts = {}
    for _, row in ipairs(BF.MATERIALS) do
      local count = tonumber(items[row[1]]) or 0
      if count > 0 then parts[#parts + 1] = row[1] .. " " .. count end
    end
    local text = #parts > 0 and table.concat(parts, ", ") or "None of the farmable ones."
    BF.say("Materials: " .. text)
    Window.toast({ title = "Materials", text = text, icon = "gem", tone = "ok", time = 8 })
  end)
end
local function checkBones()
  task.spawn(function()
    local info, err = bonesCheck()
    local text = info and string.format("%d bones, %d of %d rolls left (reset in %d min). Offers: %s", info.bones, info.left, info.most, info.minutes, offersText(info))
      or ("No answer: " .. tostring(err))
    roll.last = text
    BF.say("Death King: " .. text)
    Window.toast({ title = "Death King", text = text, icon = "bone", time = 8 })
  end)
end

local function loot(page)
  local live = page:section({ title = "Loot so far", icon = "activity", full = true })
  local counts = live:note({ icon = "gauge", text = countLine() })
  local rolled = live:note({ icon = "dices", text = roll.last })
  Motion.every(function()
    if not (counts.frame.Parent and Window.anyOpen()) then return end
    counts.set(countLine())
    rolled.set("Death King: " .. roll.last)
  end, 2, "bloxfruits.lootStatus")

  local chests = page:section({ title = "Chests", icon = "package", desc = "Flies onto each chest; the server confirms each one." })
  chests:toggle({ id = "bloxfruits.chestFarm", label = "Chest farm", desc = "Takes chests the way a touch does.", default = false, children = function(sub)
    sub:segmented({ id = "bloxfruits.chestMode", label = "When", options = { { "between", "Between farming" }, { "only", "Chest only" } }, width = 260 })
    sub:slider({ id = "bloxfruits.chestRange", label = "Between farming: within", min = 100, max = 3000, step = 50, default = 1500, suffix = " st" })
    sub:slider({ id = "bloxfruits.chestRoam", label = "Chest only: within", min = 500, max = 20000, step = 500, default = 5000, suffix = " st" })
    sub:slider({ id = "bloxfruits.chestSpeed", label = "Travel speed", tip = "Slower is pulled back less.", min = 80, max = 400, step = 10, default = 200, suffix = " st/s" })
    sub:slider({ id = "bloxfruits.chestRetry", label = "Retry a refused chest after", min = 15, max = 600, step = 15, default = 90, suffix = " s" })
    sub:slider({ id = "bloxfruits.chestGap", label = "Pause between chests", tip = "No limit is in the game's code: kept gentle.", min = 0, max = 5, step = 0.25, default = 1,
      suffix = " s" })
  end })

  local bushes = page:section({ title = "Berries", icon = "apple" })
  bushes:toggle({ id = "bloxfruits.berryFarm", label = "Collect berries", desc = "Claims ripe berries with the game's own call.", default = false, children = function(sub)
    sub:slider({ id = "bloxfruits.berryRange", label = "Within", min = 200, max = 5000, step = 100, default = 2000, suffix = " st" })
  end })

  local mats = page:section({ title = "Materials", icon = "gem", column = 2, desc = "Which mob drops what is from public guides." })
  mats:toggle({ id = "bloxfruits.matFarm", label = "Material farm", desc = "Hunts the mobs that drop it, stops at the target.", default = false, children = function(sub)
    sub:dropdown({ id = "bloxfruits.material", label = "Material", options = materialOptions() })
    sub:slider({ id = "bloxfruits.matTarget", label = "Stop at", tip = "0 = never.", min = 0, max = 1000, step = 5, default = 50 })
  end })
  mats:button({ id = "bloxfruits.matShow", label = "What I have", desc = "Asks the game for your materials.", text = "Check", run = showStash })

  local bones = page:section({ title = "Bones", icon = "bone", column = 2, desc = BF.sea() == 3 and "Haunted Castle." or "Third Sea only." })
  bones:toggle({ id = "bloxfruits.bonesFarm", label = "Bone farm", desc = "Skeletons, zombies, souls and mummies.", default = false, children = function(sub)
    sub:slider({ id = "bloxfruits.bonesTarget", label = "Stop at", tip = "0 = never.", min = 0, max = 5000, step = 50, default = 500 })
  end })
  bones:toggle({ id = "bloxfruits.boneRoll", label = "Random bone roll", desc = "Rolls whenever rolls are left and bones suffice.", default = false, bindable = false })
  bones:button({ id = "bloxfruits.boneRollOnce", label = "Roll once", desc = "Asks the Death King, going to him only if needed.", text = "Roll", run = function()
    roll.once, roll.nextAt = true, 0
  end })
  bones:button({ id = "bloxfruits.boneCheck", label = "Bones and rolls left", desc = "Asks the Death King, buys nothing.", text = "Check", run = checkBones })
end

BF.parts[#BF.parts + 1] = { id = "loot", start = start, loot = loot,
  defaults = { chestFarm = false, chestMode = "between", chestRange = 1500, chestRoam = 5000, chestSpeed = 200, chestRetry = 90, chestGap = 1,
    berryFarm = false, berryRange = 2000, matFarm = false, material = "", matTarget = 50, bonesFarm = false, bonesTarget = 500, boneRoll = false } }
end
do -- bloxfruits_mastery.lua
-- ============================================================================
--  Blox Fruits     mastery: which weapon the farm fights with, and skills
--
--  Read from the game's own code (dump 2753915549 v4630, `fast\` folder), never
--  tried live: every line below is unproven until measured.
--
--   * A weapon's mastery is the tool's own "Level" (attribute, else the
--     IntValue "Level" under it) and its experience "Exp"; the bar's goal is
--     MasteryEXPFunction(level); 600 is the most (PlayerGui/Main/UIController
--     .luau:1164-1175). The skill bar reads the same (SetUpSkills.luau:618).
--   * The mastery farm is not a body job: it names the trained tool in
--     BF.weaponOverride (BF.weapon takes it over the player's own choice) and
--     clears it on every way out. The player's weapon setting is never written,
--     so nothing it does can reach the disk. Mastery goes to the
--     weapon that lands the kill, so "finish with it" lets the usual weapon hit
--     and swaps the trained one in under a share of the mob's health.
--   * A skill is the game's own key handler: on equip every weapon binds Z X C
--     V F to one function (ContextActionService "DevilFruit",
--     MovesetClientRunner.luau:1720), which checks mastery, energy, cooldown,
--     then fires the tool's RemoteEvent with the mouse's Hit, again on release
--     (lines 894-1288). The arguments are made inside that function from the
--     game's Mouse module, which reads the real cursor (ReplicatedStorage/
--     Mouse.luau:137-147, 241). So the only faithful way is a key press with
--     the cursor on the mob: VirtualInputManager (or the executor's keypress).
--   * What a weapon has and when each key unlocks: PlayerGui.MovesetModules
--     [tool name].LegacyDataAggregate (Lvl, Cost, Cooldown per key), the same
--     module the handler requires (MovesetClientRunner.luau:1986-2024).
--   * The character's FruitZCooldown, AllCooldown, ... are cooldown CUTS (a
--     share taken off), not time left (MovesetClientRunner.luau:405-431). The
--     time left is from "<key><ToolTip without spaces>CooldownClient", the
--     tick() the skill ended (line 1653), and the full length (lines 662-680).
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion = B.S, B.Config, B.Window, B.Motion
local BF = B.BloxFruits
local O = BF.O
local function now() return os.clock() end

local MAX_MASTERY = 600                         -- UIController.luau:1168 ("(MAX)" at 600)
local TYPES = { melee = "Melee", sword = "Sword", fruit = "Demon Fruit", gun = "Gun" }      -- the engine's own map (bloxfruits.lua:225)
local LABEL = { Melee = "melee", Sword = "sword", ["Blox Fruit"] = "fruit", ["Demon Fruit"] = "fruit", Gun = "gun" }
local KEYS = { "Z", "X", "C", "V", "F" }        -- MovesetClientRunner.luau:6-10
local VK = { Z = 0x5A, X = 0x58, C = 0x43, V = 0x56, F = 0x46 }

-- ---------------------------------------------------------------- weapons and their mastery
local function kindOf(tool)
  local kind = tool:GetAttribute("WeaponType") or tool.ToolTip
  -- (as the engine does, bloxfruits.lua kindOf: a fruit's tool says "Demon Fruit", measured; "Blox Fruit" is the same kind)
  if kind == "Blox Fruit" then kind = "Demon Fruit" end
  return type(kind) == "string" and kind or ""
end
-- the tool's mastery as the game shows it: UIController.luau:1164  v60:GetAttribute("Level") or v60.Level.Value
local function masteryOf(tool)
  local level = tool:GetAttribute("Level")
  if level == nil then
    local value = tool:FindFirstChild("Level")
    level = value and value:IsA("ValueBase") and value.Value
  end
  return tonumber(level)
end
-- UIController.luau:1166  v60:GetAttribute("Exp") or v60.Exp.Value
local function expOf(tool)
  local exp = tool:GetAttribute("Exp")
  if exp == nil then
    local value = tool:FindFirstChild("Exp")
    exp = value and value:IsA("ValueBase") and value.Value
  end
  return tonumber(exp)
end
-- the experience the bar fills to at a level (ReplicatedStorage/MasteryEXPFunction.luau:2-6, called at UIController.luau:1171)
local function expGoal(level)
  local fn = BF.mod("MasteryEXPFunction")
  if type(fn) ~= "function" then return nil end
  local ok, goal = BF.game(fn, math.min(level, MAX_MASTERY - 1))
  return ok and tonumber(goal) or nil
end
-- Every weapon carried: in the hand, then the backpack. A tool with no mastery is not a weapon; a fruit that can
-- be eaten (EatRemote) is never one (the engine's own rule, bloxfruits.lua:239).
local function weapons()
  local out, seen = {}, {}
  local character, pack = BF.char(), B.LP:FindFirstChild("Backpack")
  for _, from in ipairs({ character, pack }) do
    for _, tool in ipairs(from and from:GetChildren() or {}) do
      if tool:IsA("Tool") and not tool:FindFirstChild("EatRemote") and not seen[tool.Name] then
        local level = masteryOf(tool)
        if level then
          seen[tool.Name] = true
          out[#out + 1] = { tool = tool, name = tool.Name, kind = kindOf(tool), level = level, held = from == character }
        end
      end
    end
  end
  return out
end
local function find(list, name)
  if not name or name == "" then return nil end
  for _, w in ipairs(list) do
    if string.lower(w.name) == string.lower(name) then return w end
  end
  return nil
end
-- the lowest-mastery weapon under the target, of a kind or of any
local function lowest(list, target, kind)
  local best
  for _, w in ipairs(list) do
    if w.level < target and (kind == nil or w.kind == kind) and (not best or w.level < best.level) then best = w end
  end
  return best
end
local function heldTool()
  local character = BF.char()
  local tool = character and character:FindFirstChildOfClass("Tool")
  if tool and not tool:FindFirstChild("EatRemote") then return tool end
  return nil
end

-- ---------------------------------------------------------------- the mob being fought
-- The engine does not say which mob BF.fight is on; its status line does ("Fighting <name>  <n>%", bloxfruits.lua:422).
-- The nearest living one of that name is taken. (If the engine ever sets BF.target, that is used instead.)
local function fightTarget()
  local target = rawget(BF, "target")
  if typeof(target) == "Instance" and BF.living(target) then return target end
  if not BF.running() then return nil end
  local name = string.match(tostring(BF.status or ""), "^Fighting (.-)  %d+%%$")
  local root = BF.root()
  if not (name and root) then return nil end
  return BF.mobs(name, root.Position)[1]
end
local function healthShare(mob)
  local hum = mob:FindFirstChildOfClass("Humanoid")
  if not hum then return 100 end
  return hum.Health / math.max(hum.MaxHealth, 1) * 100
end

-- ---------------------------------------------------------------- the mastery farm
local M = { active = false, applied = nil, training = nil, hand = nil, note = "Off.", resolvedAt = -1e9 }
BF.mastery = M
-- The tool the engine fights with, by name, or nil for the player's own choice. Only the engine's override is set:
-- the player's weapon setting (Config "bloxfruits.weaponName") is never touched, so a save can never write the
-- trained name to disk, and an edit the player makes meanwhile is simply theirs.
local function apply(name)
  if name == "" then name = nil end
  BF.weaponOverride = name
  M.applied = name
end
local function begin()
  M.active, M.training, M.resolvedAt = true, nil, -1e9
  apply(nil)
  local held = heldTool()
  M.hand = held and masteryOf(held) and held.Name or nil
  BF.say("Mastery farm on" .. (M.hand and (" (in hand: " .. M.hand .. ")") or ""))
end
local function finish(why, switchOff)
  apply(nil)
  M.active, M.training = false, nil
  M.note = why
  BF.say("Mastery: " .. why)
  if switchOff then
    Config.set("bloxfruits.masteryFarm", false)
    Window.toast({ title = "Mastery", text = why, icon = "trophy", tone = "ok", time = 6 })
  end
end
-- the weapon the rule asks for now, or nil, why not, and whether that means the work is done (every weapon the
-- rule covers is carried and at the target: only then may the farm switch itself off)
local function choose(list, target)
  local rule = O.masteryRule or "hand"
  if rule == "hand" then
    if not M.hand then
      local held = heldTool()
      M.hand = held and masteryOf(held) and held.Name or nil
    end
    if not M.hand then return nil, "Hold the weapon to train." end
    return find(list, M.hand) or nil, M.hand .. " is not carried."
  elseif rule == "name" then
    local name = O.masteryName or ""
    if name == "" then return nil, "Type the weapon's name." end
    return find(list, name) or nil, name .. " is not carried (or is a fruit to eat)."
  elseif rule == "lowest" then
    -- (resolve has made sure the list is not empty: nil here means every weapon is at the target)
    local w = lowest(list, target)
    return w, "Every weapon is at the target.", w == nil
  end
  local kind = TYPES[rule]
  if not kind then return nil, "Pick what to train." end
  local any = false
  for _, w in ipairs(list) do
    if w.kind == kind then any = true end
  end
  -- (none of that kind in the hand or the backpack: waited for, never called done)
  if not any then return nil, "No " .. rule .. " carried." end
  local w = lowest(list, target, kind)
  return w, "Every " .. rule .. " is at the target.", w == nil
end
-- the next one after a weapon reached the target, by the rotation picked
local function rotate(list, target)
  if O.masteryRotate == "swords" then return lowest(list, target, "Sword") end
  if O.masteryRotate == "all" then return lowest(list, target) end
  return nil
end
-- which weapon trains (checked once a second): returns the entry or nil (and stops the farm when all is done)
local function resolve()
  local list = weapons()
  -- (no body or an empty backpack, as after a death: nothing is decided until the tools are back)
  if not BF.alive() or #list == 0 then
    M.note = "Waiting for the body and its weapons."
    return M.training and { name = M.training } or nil
  end
  local target = math.clamp(O.masteryTarget or MAX_MASTERY, 1, MAX_MASTERY)
  local w = M.training and find(list, M.training)
  if not w then
    local why, done
    w, why, done = choose(list, target)
    if not w then
      if done then finish(why .. " Weapon put back.", true) else M.note = why end
      return nil
    end
  end
  if w.level >= target then
    local nxt = rotate(list, target)
    if not nxt then
      finish(string.format("%s reached mastery %d. Weapon put back.", w.name, w.level), true)
      return nil
    end
    BF.say(string.format("Mastery: %s reached %d, next %s (%d)", w.name, w.level, nxt.name, nxt.level))
    w = nxt
  end
  if M.training ~= w.name then BF.say(string.format("Mastery: training %s (%d)", w.name, w.level)) end
  M.training = w.name
  M.note = string.format("Training %s: mastery %d of %d.", w.name, w.level, target)
  return w
end
local function masteryTick()
  if O.masteryFarm ~= true then
    if M.active then finish("Switched off. Weapon put back.") end
    return
  end
  if not M.active then begin() end
  if now() - M.resolvedAt >= 1 then
    M.resolvedAt = now()
    if not resolve() then M.training = nil end
  end
  if not M.active then return end
  if not M.training then
    -- (nothing to train right now: the player's own weapon fights)
    apply(nil)
    return
  end
  -- A weapon with no basic attack (most fruits: only skills) cannot wear a mob down by itself in good time: the
  -- usual weapon does that, the trained one is swapped in for the kill, and its skills are cast whether or not
  -- Auto skills is switched on.
  local trained
  for _, from in ipairs({ BF.char(), B.LP:FindFirstChild("Backpack") }) do
    trained = trained or (from and from:FindFirstChild(M.training))
  end
  if not trained then
    -- (the tool is gone, as after a death or a drop: the override would name nothing, so the player's own weapon fights)
    M.noBasic = false
    apply(nil)
    return
  end
  local desired = M.training
  M.noBasic = BF.skillsOnly ~= nil and BF.skillsOnly(trained)
  if O.masteryFinish == true or M.noBasic then
    -- the usual weapon hits while the mob is healthy; the trained one is swapped in to land the kill
    local mob = fightTarget()
    if mob then
      -- A weak weapon (a fruit at mastery 1 with few points in it) may not be able to end a mob from where it is
      -- swapped in. Then the usual weapon takes this mob lower first: half of what it has left, each time.
      M.cut = M.cut or BF.keep({})
      local share = healthShare(mob)
      local cut = M.cut[mob] or (O.masteryFinishAt or 25)
      if share > cut then
        desired = nil
        M.swapMob, M.swapAt = nil, nil
      else
        if M.swapMob ~= mob then M.swapMob, M.swapAt = mob, now() end
        if now() - M.swapAt > (O.masteryFinishWait or 6) then
          M.cut[mob] = math.max(1, share * 0.5)
          M.swapMob, M.swapAt = nil, nil
          desired = nil
        end
      end
    end
  end
  -- (a skill key is held: the weapon is not changed under it, or the hold would end with the tool swapped out)
  if (BF.casting or 0) > now() then return end
  apply(desired)
end

-- ---------------------------------------------------------------- skills: what the weapon has
local datas = BF.keep({})   -- LegacyDataAggregate module -> its table (the engine drops a module no longer in the game)
-- The weapon's moves (Lvl / Cost / Cooldown per key), found the way the game finds them: the container named as the
-- tool whose MovesetToolUid matches the tool's (MovesetClientRunner.luau:1986-2024).
local function moveset(tool)
  local gui = B.LP:FindFirstChild("PlayerGui")
  local folder = gui and gui:FindFirstChild("MovesetModules")
  local box = folder and folder:FindFirstChild(tool.Name)
  local uid = tool:GetAttribute("MovesetToolUid")
  if not box or uid == nil or box:GetAttribute("MovesetToolUid") ~= uid then return nil end
  local module = box:FindFirstChild("LegacyDataAggregate")
  if not (module and module:IsA("ModuleScript")) then return nil end
  local got = datas[module]
  if got then return got end
  local ok, data = BF.game(require, module)
  if not (ok and type(data) == "table" and type(data.Lvl) == "table") then return nil end
  datas[module] = data
  return data
end
-- is this key awakened on the tool (MovesetClientRunner.luau:308-331)
local function awakened(tool, key, data)
  local moves = tool:FindFirstChild("AwakenedMoves")
  return moves ~= nil and moves:FindFirstChild(key) ~= nil and type(data.Awakening) == "table"
end
local function toolTip(tool)
  local tip = tool.ToolTip
  return (tip == "Blox Fruit" or tip == "Demon Fruit") and "Fruit" or tip
end
-- the cooldown cut the character carries for this weapon and key (MovesetClientRunner.luau:405-431)
local function speed(tool, key)
  local character = BF.char()
  if not character then return 1 end
  local tip = toolTip(tool)
  local kindCut = tonumber(character:GetAttribute(tip .. "Cooldown")) or 0
  local allCut = tonumber(character:GetAttribute("AllCooldown")) or 0
  local keyCut = tonumber(character:GetAttribute(tip .. key .. "Cooldown")) or 0
  local nsuns = B.LP:GetAttribute("NSUNS") and 0 or 1
  return (1 - (kindCut + allCut + keyCut)) * nsuns
end
-- the full cooldown of a key: (Cooldown[key] or 1) * tool's "Cooldown<key>" * 1.5 * speed (MovesetClientRunner.luau:662-680, 793)
local function cooldownOf(tool, key, data)
  local entry = data.Cooldown and data.Cooldown[key]
  if awakened(tool, key, data) and type(data.Awakening.Cooldown) == "table" then entry = data.Awakening.Cooldown[key] end
  if type(entry) == "function" then
    local ok, value = BF.game(entry, tool)
    entry = ok and value or nil
  end
  return (tonumber(entry) or 1) * (tonumber(tool:GetAttribute("Cooldown" .. key)) or 1) * 1.5 * speed(tool, key)
end
-- the weapon has this key, its mastery unlocks it, and there is energy for it (MovesetClientRunner.luau:952-987)
local function usable(tool, key, data)
  local need = tonumber(data.Lvl[key])
  local cost = data.Cost and data.Cost[key]
  if awakened(tool, key, data) and type(data.Awakening.Cost) == "table" then cost = data.Awakening.Cost[key] end
  if need == nil or cost == nil then return false end
  if (masteryOf(tool) or 0) < need then return false end
  local character = BF.char()
  if character and (character:GetAttribute("MasterpieceAll") or character:GetAttribute("Masterpiece" .. toolTip(tool))) then return true end
  local energy = character and character:FindFirstChild("Energy")
  return not (energy and tonumber(cost) and energy.Value < tonumber(cost))
end
local SK = { casts = 0, taken = 0, last = "Nothing cast yet.", busy = false, at = {}, lastCast = -1e9, how = nil }
BF.skills = SK
-- MovesetClientRunner.luau:1653  Character:SetAttribute(key .. ToolTip:gsub(" ", "") .. "CooldownClient", tick()) when a skill ends
local function stampOf(tool, key)
  local character = BF.char()
  return character and tonumber(character:GetAttribute(key .. (string.gsub(tool.ToolTip, " ", "")) .. "CooldownClient"))
end
-- off cooldown three ways: the game's own stamp, the skill bar's own fill, and this part's own record of its cast
local function ready(tool, key, data)
  if not BF.char() then return false end
  local full = cooldownOf(tool, key, data) + (O.skillSafety or 0.3)
  local stamp = stampOf(tool, key)
  if stamp and tick() - stamp < full then return false end
  -- MovesetClientRunner.luau:464-472  Main.Skills[tool][key].Cooldown is sized down to 0 as it cools
  local main = B.LP.PlayerGui:FindFirstChild("Main")
  local bar = main and main:FindFirstChild("Skills")
  local frame = bar and bar:FindFirstChild(tool.Name)
  local cell = frame and frame:FindFirstChild(key)
  local fill = cell and cell:FindFirstChild("Cooldown")
  if fill and fill:IsA("GuiObject") and fill.Size.X.Scale > 0.02 then return false end
  return now() - (SK.at[tool.Name .. "/" .. key] or -1e9) >= full + (O.skillHold or 0.15)
end
-- the handler would refuse now: no skill bar for the tool, a skill held, busy, stunned, sat, just equipped
-- (MovesetClientRunner.luau:901, 1007, 1036-1042, 1060)
local function free(tool)
  local main = B.LP.PlayerGui:FindFirstChild("Main")
  local bar = main and main:FindFirstChild("Skills")
  if not (bar and bar:FindFirstChild(tool.Name)) then return false end
  local holding = tool:FindFirstChild("Holding")
  if not holding or holding.Value ~= false then return false end
  local character, hum = BF.char(), BF.hum()
  local busy, stun = character:FindFirstChild("Busy"), character:FindFirstChild("Stun")
  if not (hum and busy and stun) or busy.Value ~= false or stun.Value ~= 0 or hum.Sit then return false end
  local global = BF.mod("Global")
  if type(global) == "table" then
    if global.busy then return false end
    if tick() - (tonumber(global.equipTimer) or 0) < 0.15 then return false end
  end
  return true
end

-- ---------------------------------------------------------------- skills: pressing a key
local vim
local function inputService()
  if vim == nil then
    local ok, service = pcall(game.GetService, game, "VirtualInputManager")
    vim = ok and service or false
  end
  return vim or nil
end
-- One key down or up. VirtualInputManager first (it reaches ContextActionService without the window's focus), else
-- the executor's own keypress / keyrelease. Returns false when neither exists.
local function press(key, down)
  local service = inputService()
  if service and pcall(service.SendKeyEvent, service, down, Enum.KeyCode[key], false, game) then
    SK.how = "VirtualInputManager"
    return true
  end
  local fn = down and keypress or keyrelease
  if type(fn) == "function" and pcall(fn, VK[key]) then
    SK.how = "keypress"
    return true
  end
  return false
end
local function moveCursor(x, y)
  local service = inputService()
  if service and pcall(service.SendMouseMoveEvent, service, x, y, game) then return true end
  if type(mousemoveabs) == "function" then return (pcall(mousemoveabs, x, y)) end
  return false
end
-- While a key is down the cursor sits on the mob (the game's Mouse module casts its Hit from the real cursor every
-- frame, Mouse.luau:312-324), and, if allowed, the camera looks at it so it is on screen.
local AIM = "BASED.bfSkillAim"
local aiming = false
local function aimOn(mob)
  local root = mob:FindFirstChild("HumanoidRootPart")
  if not root then return end
  aiming = true
  S.RunService:BindToRenderStep(AIM, Enum.RenderPriority.Camera.Value + 1, function()
    local camera = workspace.CurrentCamera
    -- (the hub window open: the cursor is the player's, never moved under them)
    if not (camera and root.Parent) or Window.anyOpen() then return end
    if O.skillLook ~= false then camera.CFrame = CFrame.lookAt(camera.CFrame.Position, root.Position) end
    local point, onScreen = camera:WorldToViewportPoint(root.Position)
    if onScreen and point.Z > 0 then moveCursor(point.X, point.Y) end
  end)
end
local function aimOff()
  if aiming then
    aiming = false
    pcall(S.RunService.UnbindFromRenderStep, S.RunService, AIM)
  end
end
-- Did the game's handler run the skill? It writes its stamp when the skill ends: watched for a few seconds, apart.
local function watchTaken(tool, key, before)
  task.spawn(function()
    local untilAt = now() + 6
    while now() < untilAt and B.alive do
      local stamp = stampOf(tool, key)
      if stamp and stamp ~= before then
        SK.taken += 1
        return
      end
      task.wait(0.2)
    end
  end)
end
-- The player is typing (the chat, a hub input) or has the hub window open: a key sent now would be typed into the
-- box ("Or this one by name" would change the weapon) and the cursor would be pulled from under them.
local function typing()
  return S.UserInputService:GetFocusedTextBox() ~= nil or Window.anyOpen()
end
local function cast(tool, key, mob)
  local hold = math.clamp(O.skillHold or 0.15, 0.05, 3)
  watchTaken(tool, key, stampOf(tool, key))
  -- (the engine sends no swing and equips nothing while this is ahead of the clock: a swap under the held key
  -- would end the hold early, tool.Parent ~= the body, and cut the skill short)
  BF.casting = now() + 0.08 + hold + 0.3
  local ok, err = pcall(function()
    aimOn(mob)
    task.wait(0.08)
    if typing() then return end
    BF.casting = now() + hold + 0.3
    if not press(key, true) then
      SK.last = "No way to press a key in this executor."
      return
    end
    local untilAt = now() + hold
    -- (let go at once if the player starts typing or opens the hub: a held key would type into the box)
    while now() < untilAt and B.alive and BF.alive() and tool.Parent == BF.char() and not typing() do task.wait() end
    press(key, false)
    SK.casts += 1
    SK.last = string.format("%s  %s on %s", key, tool.Name, mob.Name)
    task.wait(0.1)
  end)
  -- (a key must never stay down, the camera must never stay held, and the engine must never stay barred from swinging)
  press(key, false)
  aimOff()
  BF.casting = 0
  if not ok then SK.last = "Cast failed: " .. string.sub(tostring(err), 1, 80) end
  SK.busy = false
end
-- the mob to cast at: the one the job is fighting, alive and within reach of the body
local function skillMob()
  local job = BF.running()
  if not job or (O.skillOnlyLevel == true and job.id ~= "level") then return nil end
  if not string.find(tostring(BF.status or ""), "^Fighting ") then return nil end
  local mob, root = fightTarget(), BF.root()
  local mroot = mob and mob:FindFirstChild("HumanoidRootPart")
  if not (mroot and root) or (mroot.Position - root.Position).Magnitude > (O.skillRange or 60) then return nil end
  return mob
end
local function skillTick()
  -- (a cast under way checks the same each frame and lets its key go: so nothing is left held by this return)
  if typing() then return end
  local forced = M.active and M.noBasic == true
  if (O.autoSkills ~= true and not forced) or SK.busy or not BF.alive() then return end
  if now() - SK.lastCast < (O.skillGap or 0.6) then return end
  local mob = skillMob()
  local tool = mob and heldTool()
  if not (tool and free(tool)) then return end
  -- (cast only for the mastery farm's sake: then only with the trained weapon in the hand)
  if O.autoSkills ~= true and tool.Name ~= M.training then return end
  local data = moveset(tool)
  if not data then return end
  local picks = type(O.skillKeys) == "table" and O.skillKeys or {}
  for _, key in ipairs(KEYS) do
    -- (a key the weapon lacks, or not unlocked at its mastery, is passed over without a word)
    if table.find(picks, key) and usable(tool, key, data) and ready(tool, key, data) then
      SK.busy, SK.lastCast = true, now()
      SK.at[tool.Name .. "/" .. key] = now()
      task.spawn(cast, tool, key, mob)
      return
    end
  end
end

-- ---------------------------------------------------------------- start
local function start()
  Motion.every(function() B.try("bloxfruits.mastery", masteryTick) end, 8, "bloxfruits.mastery")
  Motion.every(function() B.try("bloxfruits.skills", skillTick) end, 10, "bloxfruits.skills")
  -- (neither is a job's switch: Stop everything / Panic switch them off through the engine's list)
  if type(BF.offToo) == "table" then
    for _, id in ipairs({ "bloxfruits.masteryFarm", "bloxfruits.autoSkills" }) do
      if not table.find(BF.offToo, id) then BF.offToo[#BF.offToo + 1] = id end
    end
  end
  B.own(function()
    aimOff()
    for _, key in ipairs(KEYS) do pcall(press, key, false) end
    BF.casting = 0
    BF.weaponOverride = nil
    M.active, M.applied = false, nil
  end)
end

-- ---------------------------------------------------------------- the tabs
local function weaponLine()
  local parts = {}
  for _, w in ipairs(weapons()) do
    local text = string.format("%s %d%s", w.name, w.level, w.level >= MAX_MASTERY and " (max)" or "")
    if w.level < MAX_MASTERY then
      local exp, goal = expOf(w.tool), expGoal(w.level)
      if exp and goal then text = text .. string.format(" (%d/%d)", exp, goal) end
    end
    parts[#parts + 1] = text .. " " .. (LABEL[w.kind] or "")
  end
  return #parts > 0 and table.concat(parts, "  ·  ") or "No weapon carried."
end
local function mastery(page)
  local live = page:section({ title = "Weapons", icon = "activity", full = true })
  local state = live:note({ icon = "trophy", text = M.note })
  local list = live:note({ icon = "sword", text = weaponLine() })
  Motion.every(function()
    if not (state.frame.Parent and Window.anyOpen()) then return end
    state.set(O.masteryFarm == true and M.note or "Off.")
    list.set(weaponLine())
  end, 2, "bloxfruits.masteryStatus")

  local farm = page:section({ title = "Mastery farm", icon = "trophy", desc = "Picks the weapon any farm fights with." })
  farm:toggle({ id = "bloxfruits.masteryFarm", label = "Mastery farm", desc = "Your own weapon setting is never changed.", default = false, children = function(sub)
    sub:dropdown({ id = "bloxfruits.masteryRule", label = "Train", options = { { "hand", "The one in my hand" }, { "lowest", "The lowest mastery" },
      { "name", "This name" }, { "melee", "Melee" }, { "sword", "Sword" }, { "fruit", "Fruit" }, { "gun", "Gun" } } })
    sub:input({ id = "bloxfruits.masteryName", label = "Name", placeholder = "e.g. Katana" })
    sub:slider({ id = "bloxfruits.masteryTarget", label = "Stop at mastery", tip = "600 is the most.", min = 1, max = MAX_MASTERY, step = 1, default = MAX_MASTERY })
    sub:dropdown({ id = "bloxfruits.masteryRotate", label = "Then", options = { { "off", "Stop there" }, { "swords", "Every sword in turn" },
      { "all", "Every weapon in turn" } } })
    sub:toggle({ id = "bloxfruits.masteryFinish", label = "Finish with it", desc = "Your usual weapon hits, this one kills.", default = false, bindable = false,
      children = function(inner)
        inner:slider({ id = "bloxfruits.masteryFinishAt", label = "Swap in under", min = 5, max = 90, step = 5, default = 25, suffix = "%" })
        inner:slider({ id = "bloxfruits.masteryFinishWait", label = "If it cannot end it in", tip = "The usual weapon then takes the mob lower first.", min = 2, max = 30, step = 1, default = 6,
          suffix = " s" })
      end })
  end })
  farm:note({ icon = "info", text = "Mastery goes to the weapon that lands the kill." })
end
local function fight(page)
  local card = page:section({ title = "Auto skills", icon = "zap", column = 2 })
  card:toggle({ id = "bloxfruits.autoSkills", label = "Auto skills", desc = "Presses the ticked keys at the mob being fought.", default = false, children = function(sub)
    sub:multi({ id = "bloxfruits.skillKeys", label = "Keys", options = { { "Z", "Z" }, { "X", "X" }, { "C", "C" }, { "V", "V" }, { "F", "F" } }, default = { "Z", "X", "C" } })
    sub:slider({ id = "bloxfruits.skillRange", label = "Mob within", min = 10, max = 200, step = 5, default = 60, suffix = " st" })
    sub:slider({ id = "bloxfruits.skillSafety", label = "Extra wait after a cooldown", min = 0, max = 3, step = 0.1, default = 0.3, suffix = " s" })
    sub:slider({ id = "bloxfruits.skillGap", label = "Time between casts", min = 0.2, max = 5, step = 0.1, default = 0.6, suffix = " s" })
    sub:slider({ id = "bloxfruits.skillHold", label = "Hold each key", tip = "Longer for skills that charge.", min = 0.05, max = 3, step = 0.05, default = 0.15, suffix = " s" })
    sub:toggle({ id = "bloxfruits.skillOnlyLevel", label = "Only during auto level", default = false, bindable = false })
    sub:toggle({ id = "bloxfruits.skillLook", label = "Turn the camera to the mob", desc = "Skills aim where the cursor is.", default = true, bindable = false })
  end })
  local line = card:note({ icon = "keyboard", text = SK.last })
  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    line.set(string.format("%d pressed, %d run by the game  ·  %s", SK.casts, SK.taken, SK.last))
  end, 2, "bloxfruits.skillsStatus")
end

BF.parts[#BF.parts + 1] = { id = "mastery", start = start, mastery = mastery, fight = fight,
  defaults = { masteryFarm = false, masteryRule = "hand", masteryName = "", masteryTarget = MAX_MASTERY, masteryRotate = "off", masteryFinish = false,
    masteryFinishAt = 25, masteryFinishWait = 6, autoSkills = false, skillKeys = { "Z", "X", "C" }, skillRange = 60, skillSafety = 0.3, skillGap = 0.6, skillHold = 0.15,
    skillOnlyLevel = false, skillLook = true } }
end
do -- bloxfruits_player.lua
-- ============================================================================
--  Blox Fruits     the body's upkeep: stat points, haki, and the known codes
--
--  None of these needs the body: they run beside whatever job has it.
--  Stat points: CommF_ "AddPoint", the stat's name, how many (the game's own
--  stats menu sends exactly that). Codes: Remotes.Redeem, the text.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion = B.S, B.Config, B.Window, B.Motion
local BF = B.BloxFruits
local O = BF.O

local STATS = { "Melee", "Defense", "Sword", "Gun", "Demon Fruit" }
BF.STATS = STATS
-- Listed as working on 7 or 8 of 8 code sites on 2026-11-13 (research/codes-and-data.md). kind: what it gives.
BF.CODES = {
  { "EASTEREXP", "exp" }, { "Axiore", "exp" }, { "Bluxxy", "exp" }, { "THEGREATACE", "exp" }, { "JCWK", "exp" }, { "kittgaming", "exp" }, { "Magicbus", "exp" },
  { "Sub2CaptainMaui", "exp" }, { "Sub2OfficialNoobie", "exp" }, { "Sub2Daigrock", "exp" }, { "SUB2NOOBMASTER123", "exp" }, { "StrawHatMaine", "exp" },
  { "TantaiGaming", "exp" }, { "Starcodeheo", "exp" }, { "SUB2GAMERROBOT_EXP1", "exp" }, { "Sub2Fer999", "exp" }, { "Enyu_is_Pro", "exp" },
  { "BIGNEWS", "title" }, { "FUDD10", "beli" }, { "fudd10_v2", "beli" }, { "CHANDLER", "beli" },
  { "Sub2UncleKizaru", "reset" }, { "SUB2GAMERROBOT_RESET1", "reset" }, { "KITT_RESET", "reset" },
}

local function statLevel(name)
  local data = B.LP:FindFirstChild("Data")
  local stats = data and data:FindFirstChild("Stats")
  local stat = stats and stats:FindFirstChild(name)
  local level = stat and stat:FindFirstChild("Level")
  return level and tonumber(level.Value) or 0
end
BF.statLevel = statLevel
-- Shares of the points, as weights. "Follow my weapon" works them out from what the body fights with: the
-- weapon's own stat first, Defense second, and Melee (energy, and the punch every body has) third.
local KEY = { Melee = "wMelee", Defense = "wDefense", Sword = "wSword", Gun = "wGun", ["Demon Fruit"] = "wFruit" }
local MAIN = { melee = "Melee", sword = "Sword", gun = "Gun", fruit = "Demon Fruit" }
local function weights()
  local out = {}
  if O.statMode == "smart" then
    for _, name in ipairs(STATS) do out[name] = tonumber(O[KEY[name]]) or 0 end
    return out
  end
  local main = MAIN[O.weapon or "melee"] or "Melee"
  out[main] = 5
  out.Defense = 3
  if main ~= "Melee" then out.Melee = 2 end
  return out
end
BF.statWeights = weights
-- Where the next points go. By shares: the stat furthest below its share of what has been spent. A stat at
-- its cap takes no more, and its share goes to the others.
local function nextStat()
  local cap = O.statCap or 2800
  if O.statMode == "one" then
    local one = O.statOne or "Melee"
    return statLevel(one) < cap and one or nil
  end
  if O.statMode == "spread" then
    local picks = type(O.statSpread) == "table" and O.statSpread or {}
    local best, low
    for _, name in ipairs(STATS) do
      if table.find(picks, name) then
        local level = statLevel(name)
        if level < cap and (not low or level < low) then best, low = name, level end
      end
    end
    return best
  end
  local share, total, spent = weights(), 0, 0
  for _, name in ipairs(STATS) do
    if (share[name] or 0) > 0 and statLevel(name) < cap then
      total += share[name]
      spent += statLevel(name) - 1
    end
  end
  if total <= 0 then return nil end
  local best, behind
  for _, name in ipairs(STATS) do
    local weight = share[name] or 0
    if weight > 0 and statLevel(name) < cap then
      -- how far this stat is below what its share of the spent points would be
      local gap = weight / total * (spent + 1) - (statLevel(name) - 1)
      if not behind or gap > behind then best, behind = name, gap end
    end
  end
  return best
end
BF.nextStat = nextStat
local lastSpend = 0
local function spend()
  if not O.stats then return end
  local points = tonumber(BF.data("Points")) or 0
  if points <= 0 or os.clock() - lastSpend < (O.statGap or 1) then return end
  local stat = nextStat()
  if not stat then return end
  lastSpend = os.clock()
  local amount = math.min(points, O.statStep or 3)
  local ok, answer = BF.invoke(5, "AddPoint", stat, amount)
  if not ok then BF.say("Stat points were not taken: " .. tostring(answer)) end
end

-- haki: switched on when the body owns it and it is off (the game's own key does the same call)
local lastHaki = 0
local function haki()
  if not O.haki or not BF.alive() then return end
  local character = BF.char()
  if not character or os.clock() - lastHaki < (O.hakiGap or 3) then return end
  local owns = false
  pcall(function() owns = character:HasTag("Buso") end)
  if not owns and not O.hakiTry then return end
  if character:FindFirstChild("HasBuso") then return end
  lastHaki = os.clock()
  BF.invoke(4, "Buso")
end

local redeeming = false
function BF.redeem(kinds)
  if redeeming then return end
  redeeming = true
  task.spawn(function()
    local remotes = S.ReplicatedStorage:FindFirstChild("Remotes")
    local remote = remotes and remotes:FindFirstChild("Redeem")
    local taken, refused = 0, 0
    if remote then
      for _, code in ipairs(BF.CODES) do
        if not B.alive then break end
        if kinds[code[2]] then
          local ok, answer = pcall(function() return remote:InvokeServer(code[1]) end)
          local text = tostring(answer)
          -- (the game answers with a sentence: a thank-you when it is taken)
          if ok and (string.find(string.lower(text), "success", 1, true) or string.find(string.lower(text), "redeemed", 1, true) and not string.find(string.lower(text), "already", 1, true)) then
            taken += 1
          else
            refused += 1
          end
          BF.say(code[1] .. ": " .. string.sub(text, 1, 70))
          task.wait(1.1)
        end
      end
    end
    redeeming = false
    Window.toast({ title = "Codes", text = string.format("%d taken, %d refused or used before.", taken, refused), icon = "tag", tone = taken > 0 and "ok" or nil, time = 5 })
  end)
end

local function start()
  Motion.every(function() B.try("bloxfruits.stats", spend) end, 2, "bloxfruits.stats")
  Motion.every(function() B.try("bloxfruits.haki", haki) end, 2, "bloxfruits.haki")
end

local function player(page)
  local stats = page:section({ title = "Stat points", icon = "gauge", desc = "Spent as they come, beside whatever is farming." })
  local options = {}
  for _, name in ipairs(STATS) do options[#options + 1] = { name, name == "Demon Fruit" and "Blox Fruit" or name } end
  stats:toggle({ id = "bloxfruits.stats", label = "Auto stats", desc = "Puts every new point where the plan says.", default = false, children = function(sub)
    sub:dropdown({ id = "bloxfruits.statMode", label = "Plan", options = { { "follow", "Follow my weapon" }, { "smart", "My own shares" }, { "spread", "Lowest of the ticked" },
      { "one", "One stat only" } } })
    sub:note({ icon = "info", text = "Follow my weapon: its stat 5 parts, Defense 3, Melee 2. A capped stat's share goes to the rest." })
    for _, name in ipairs(STATS) do
      sub:slider({ id = "bloxfruits." .. KEY[name], label = "Share: " .. (name == "Demon Fruit" and "Blox Fruit" or name), tip = "Used by My own shares. 0 = none.", min = 0, max = 10,
        step = 1, default = (name == "Melee" and 5) or (name == "Defense" and 3) or 0 })
    end
    sub:multi({ id = "bloxfruits.statSpread", label = "Ticked stats", options = options, default = { "Melee", "Defense" } })
    sub:dropdown({ id = "bloxfruits.statOne", label = "The one stat", options = options })
    sub:slider({ id = "bloxfruits.statStep", label = "Points at a time", min = 1, max = 100, step = 1, default = 3 })
    sub:slider({ id = "bloxfruits.statGap", label = "Seconds between", min = 0.3, max = 5, step = 0.1, default = 1, suffix = " s" })
    sub:slider({ id = "bloxfruits.statCap", label = "Stop a stat at", min = 100, max = 2800, step = 50, default = 2800 })
  end })
  local aura = page:section({ title = "Haki", icon = "shield", column = 2 })
  aura:toggle({ id = "bloxfruits.haki", label = "Keep Buso on", desc = "Switched back on whenever it drops.", default = false, children = function(sub)
    sub:toggle({ id = "bloxfruits.hakiTry", label = "Try even if it looks locked", default = false, bindable = false })
    sub:slider({ id = "bloxfruits.hakiGap", label = "Seconds between tries", min = 1, max = 15, step = 1, default = 3, suffix = " s" })
  end })
end

local function misc(page)
  local codes = page:section({ title = "Codes", icon = "tag", desc = string.format("%d codes that the code sites listed as working on 13 Nov 2026.", #BF.CODES) })
  codes:button({ id = "bloxfruits.codesExp", label = "2x EXP codes", desc = "Each adds minutes of double experience: use them when you farm.", text = "Redeem", run = function()
    BF.redeem({ exp = true })
  end })
  codes:button({ id = "bloxfruits.codesRest", label = "Titles, Beli and stat resets", desc = "A reset code gives a refund token; it does not reset by itself.", text = "Redeem", run = function()
    BF.redeem({ title = true, beli = true, reset = true })
  end })
  local _ = Config
end

BF.parts[#BF.parts + 1] = { id = "player", start = start, player = player, misc = misc,
  defaults = { stats = false, statMode = "follow", statSpread = { "Melee", "Defense" }, statOne = "Melee", statStep = 3, statGap = 1, statCap = 2800, haki = false,
    hakiTry = false, hakiGap = 3, wMelee = 5, wDefense = 3, wSword = 0, wGun = 0, wFruit = 0 } }
end
do -- bloxfruits_quest.lua
-- ============================================================================
--  Blox Fruits     quest chains: the seas, the Saber, the Citizen
--
--  ONE small engine and data. A chain is an ordered list of steps; each step
--  says whether it is done (asked from the game: a command's answer, a tool in
--  the backpack, the sea, the level) and makes ONE bounded attempt at it. A
--  job runs the first step that is not done, asking the game again every
--  round; a step that keeps failing stops its chain, which says where and why
--  and switches itself off. Nothing here was run on the live game.
--
--  Dump: Volt\workspace\dumps\2753915549\4630\fast\ (paths below are under it;
--  "state.json" / "instances.json" are the live passes one folder up). A step
--  the dump does not show is not guessed: the chain stops there with a note.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion = B.S, B.Config, B.Window, B.Motion
local BF = B.BloxFruits
local O = BF.O
local function now() return os.clock() end

-- ---------------------------------------------------------------- asking the game
-- Read-only progress commands are asked once a round and kept for that round (a round asks every
-- step's `done`, and four steps may read the same table).
local NONE = {}
local cache = {}
local function ask(...)
  local key = table.concat({ ... }, "|")
  local got = cache[key]
  if got ~= nil then
    if got == NONE then return nil end
    return got
  end
  local ok, answer = BF.invoke(6, ...)
  if not ok then answer = nil end
  cache[key] = answer == nil and NONE or answer
  return answer
end
local function fresh() table.clear(cache) end
-- (a table, or nil when the game did not answer: "unknown" is not "not done")
local function tableOf(...)
  local t = ask(...)
  return type(t) == "table" and t or nil
end
-- { TalkedDetective, UsedKey, KilledIceBoss }: ServerBrowser/LocalScript.luau:510-513, DressQuestPro.luau:41-44
local function dressrosa() return tableOf("DressrosaQuestProgress") end
-- { KilledBandits, KilledSpring, DidPlates }: StarterPlayerScripts/BartiloQuestPro.luau:45-48
local function bartilo() return tableOf("BartiloQuestProgress") end
-- { KilledBandits, KilledBoss, FoundTreasure }: StarterPlayerScripts/CitizenQuestPro.luau:44-47
local function citizen() return tableOf("CitizenQuestProgress") end
-- { Plates = { [1..5] = bool }, UsedTorch, UsedCup, KilledMob, UsedRelic }: StarterPlayerScripts/QuestPro.luau:367-375
local function saber() return tableOf("ProQuestProgress") end
-- 0 = King Red Head offers "Begin", 1 = done (Third Sea open), else level 1,500 / Don Swan missing
-- (ReplicatedStorage/DialoguesList.luau:881-906; ServerBrowser/LocalScript.luau:555-557 opens Sea 3 on 1)
local function zCheck() return ask("ZQuestProgress", "Check") end
-- a field of a progress table: true / false, or nil when the table did not come
local function flag(t, name)
  if not t then return nil end
  return t[name] == true
end

-- ---------------------------------------------------------------- the world
local function tool(name)
  local character, pack = BF.char(), B.LP:FindFirstChild("Backpack")
  local found = (character and character:FindFirstChild(name)) or (pack and pack:FindFirstChild(name))
  return found and found:IsA("Tool") and found or nil
end
-- put a quest item in the hand: the game's own touch handlers watch the HELD tool's Handle (DressQuestPro.luau:55, QuestPro.luau:514)
local function hold(name)
  local item, hum = tool(name), BF.hum()
  if item and hum and item.Parent ~= BF.char() then pcall(function() hum:EquipTool(item) end) end
  return item
end
-- An NPC's standing point: the NPC loader keeps FloorPos on each model (instances.json: ReplicatedStorage.NPCs.Military Detective
-- FloorPos (4875.6, 6.9, 715.2)); near ones stand in workspace.NPCs, the rest are parked in ReplicatedStorage.NPCs (bloxfruits_world.lua npcs()).
local function npcPoint(name)
  for _, folder in ipairs({ workspace:FindFirstChild("NPCs"), S.ReplicatedStorage:FindFirstChild("NPCs") }) do
    local model = folder and folder:FindFirstChild(name)
    if model then
      local floor = model:GetAttribute("FloorPos")
      if typeof(floor) == "Vector3" then return floor end
      local ok, pivot = pcall(model.GetPivot, model)
      if ok and pivot and pivot.Position.Magnitude > 1 then return pivot.Position end
    end
  end
  return nil
end
-- where an NPC of a chain lives, when that is known (the island looked at first when it has to be found).
-- Sick Man: seen at the Frozen Village on 2026-11-13 (1503, 77, -1297). Rich Man: Middle Town by every public guide (not yet seen).
local HOME = { ["Sick Man"] = "Frozen Village", ["Rich Man"] = "Middle Town" }
-- the map folder of an island, and the name of the place to fly to when the two differ
local PLACE = { Ice = "Frozen Village", Turtle = "Floating Turtle", Dressrosa = "Kingdom of Rose" }
local function mapPart(...)
  local names = { ... }
  -- (an island's map is only loaded near it: gone there first, once, when its folder is missing)
  local map = workspace:FindFirstChild("Map")
  if names[1] and not (map and map:FindFirstChild(names[1])) and BF.nearIsland then
    BF.nearIsland(BF.ctx and BF.ctx() or nil, names[1], PLACE[names[1]])
  end
  local at = workspace:FindFirstChild("Map")
  for _, name in ipairs(names) do at = at and at:FindFirstChild(name) end
  return at
end
local function pointOf(thing)
  if not thing then return nil end
  if thing:IsA("BasePart") then return thing.Position end
  local ok, pivot = pcall(thing.GetPivot, thing)
  return ok and pivot and pivot.Position or nil
end
-- Fly to an NPC, then send what its dialogue sends. Returns sent, answer (or false, why).
local function talk(ctx, npc, ...)
  -- (an NPC's model is only there near its island: one not seen yet is looked for, island by island)
  local point = npcPoint(npc) or (BF.npcSeen and BF.npcSeen[npc])
  if not point then
    -- Nobody has seen this NPC yet (its model only exists near it). What its dialogue sends is sent from where the body
    -- stands: abilities were bought that way from across the map (measured 2026-11-13), and the step's own check, asked
    -- of the game on the next round, says whether the server minded. Looking for it island by island comes second.
    local sent, answer = BF.invoke(8, ...)
    if sent then
      BF.say(string.format("%s has not been seen yet: asked from afar, the server answered %s", npc, tostring(answer)))
      return true, answer
    end
    point = BF.findNpc and BF.findNpc(ctx, npc, HOME[npc])
    if not point then return false, npc .. " is not among this sea's NPCs" end
  end
  local ok, why = BF.fly(point + Vector3.new(0, 4, 0), ctx, { note = "To " .. npc })
  if not ok then return false, "could not reach " .. npc .. " (" .. tostring(why) .. ")" end
  ctx:sleep(0.4, "At " .. npc)
  local sent, answer = BF.invoke(8, ...)
  if not sent then return false, npc .. " did not answer (" .. tostring(answer) .. ")" end
  return true, answer
end
-- Stand the body on (or in) a part a while, the way a player would to touch it. `inside` = the point itself (a door, a fire,
-- water: the held tool's Handle must touch it), else on top of it (a plate: a foot must touch it).
local function touch(ctx, part, seconds, note, inside)
  local at = pointOf(part)
  if not at then return false, "the part is not in the map" end
  if not inside and part:IsA("BasePart") then at = at + Vector3.new(0, part.Size.Y / 2 + 2.5, 0) end
  local ok, why = BF.fly(at, ctx, { note = note })
  if not ok then return false, why end
  BF.holdAt(at)
  ctx:sleep(seconds, note)
  return true
end
-- Is a boss up? Near, it stands in workspace.Enemies; far, the game parks its Model directly under ReplicatedStorage
-- (measured 2026-11-13 with the Mob Leader and the Saber Expert).
local function bossUp(name)
  local near = workspace:FindFirstChild("Enemies")
  local model = (near and near:FindFirstChild(name)) or S.ReplicatedStorage:FindFirstChild(name)
  if not (model and model:IsA("Model")) then return false end
  local hum = model:FindFirstChildOfClass("Humanoid")
  return hum == nil or hum.Health > 0
end
-- Fight one of a named mob (a boss, or one of a pack): where it stands, else over its nearest spawn mark a while.
-- A third value, true, says "not a failure: it is not up, wait" (a boss comes back on a timer).
local function slay(ctx, name, waitFor)
  local root = BF.root()
  if not root then return false, "no body" end
  local mobs = BF.mobs(name, root.Position)
  if #mobs == 0 then
    local spawns = BF.spawns(name)
    if #spawns == 0 then return false, "no " .. name .. " here and no spawn mark of it in this sea" end
    table.sort(spawns, function(a, b) return (a - root.Position).Magnitude < (b - root.Position).Magnitude end)
    local ok, why = BF.fly(spawns[1] + Vector3.new(0, O.height or 25, 0), ctx, { note = "To where " .. name .. " appears" })
    if not ok then return false, why end
    ctx:sleep(waitFor or 4, "Waiting for " .. name)
    root = BF.root()
    mobs = BF.mobs(name, root and root.Position)
    if #mobs == 0 then return false, name .. " is not up (a boss comes back on a timer)", true end
  end
  local result = BF.fight(mobs[1], ctx, function()
    local mine = BF.root()
    return BF.mobs(name, mine and mine.Position)
  end)
  if result == "died" then ctx:body(40) end
  if result == "dead" then return true end
  return false, name .. ": " .. result
end
-- A boss of a chain. While it is not up nothing is flown for it: the farm has the body back and the game is looked
-- at again shortly. Every eighth look the spawn is gone to anyway, in case the boss is up and not where the game
-- usually parks it.
local function slayBoss(ctx, name, memo)
  memo.looks = memo.looks or {}
  if #BF.mobs(name) == 0 and not bossUp(name) then
    local looks = (memo.looks[name] or 0) + 1
    memo.looks[name] = looks
    if looks % 8 ~= 0 then return false, name .. " is not up yet", true end
  end
  return slay(ctx, name, 8)
end
-- The kill quest of a chain in hand: asked of its giver, then StartQuest as the dialogue's own quest page does.
-- ("Yes" -> Util.generateQuest(group, { NoReturn = true }), DialoguesList.luau:780 / :834; it sends StartQuest, group, index at
-- DialoguesList/Util.luau:170, and these groups hold ONE quest: Quests.luau:74, :97, so the index is 1.)
local function takeQuest(ctx, group, npc, command)
  local held = BF.quest()
  if held and held.InternalQuestName == group then return true end
  if held then
    -- (a farm's quest is dropped for the chain's own; another story's quest is not: GuideModule/GuideData.luau:574)
    if not BF.dropQuest() then return false, "another story's quest is in hand (" .. tostring(held.InternalQuestName) .. ")" end
    ctx:sleep(0.6, "Dropping another quest")
  end
  local sent, answer = talk(ctx, npc, command, npc)                -- DialoguesList.luau:775 ("BartiloQuestProgress", "Bartilo") / :829 ("CitizenQuestProgress", "Citizen")
  if not sent then return false, answer end
  if answer ~= 0 then return false, npc .. " does not offer the quest (answered " .. tostring(answer) .. ")" end
  local ok, given = BF.invoke(8, "StartQuest", group, 1)          -- DialoguesList/Util.luau:170
  if not ok then return false, "StartQuest: " .. tostring(given) end
  if given == 2 then return false, "the game says this quest is done already" end
  if given ~= 0 then return false, "StartQuest answered " .. tostring(given) .. (given == 1 and " (an error)" or " (the level it needs)") end
  local untilAt = now() + 3
  while not BF.quest() and now() < untilAt and not ctx.stop do
    ctx:beat("Quest taken: " .. group)
    task.wait(0.1)
  end
  return true
end
-- the game's own client refuses a sea change in combat (ServerBrowser/LocalScript.luau:394-397)
local function inCombat()
  local character = BF.char()
  return character ~= nil and character:GetAttribute("InCombat") and true or false
end
-- A sea change the way the game's own server menu makes it: the button is live on the chain's flags alone and sends the
-- travel command, refused only in combat (ServerBrowser/LocalScript.luau:394-405; the Second Sea's flags :510-526, the
-- Third Sea's check :555-557). No captain is gone to and no second talk is needed.
local function travel(ctx, command)
  if inCombat() then
    -- (up and away from whatever was being fought, until the game says the fight is over)
    local root = BF.root()
    if root then BF.fly(root.Position + Vector3.new(0, 250, 0), ctx, { direct = true, note = "Out of combat first" }) end
    local untilAt = now() + 60
    while inCombat() and now() < untilAt and not ctx.stop do
      ctx:beat("Out of combat first")
      task.wait(0.5)
    end
    if inCombat() then return false, "still in combat (the game refuses a sea change)" end
  end
  local ok, said = BF.invoke(15, command)
  BF.say(command .. " -> " .. tostring(said))
  -- (a teleport follows; the world part brings the hub back on the far side)
  ctx:sleep(25, "Sailing")
  -- (still here 25 s later: the trip did not happen, whatever the answer was)
  return false, ok and ("no teleport came (" .. tostring(said) .. ")") or (command .. " was not answered")
end
local function levelStep(level)
  return { name = "Level " .. level, tries = 1,
    done = function() return BF.level() >= level end,
    act = function() return false, string.format("needs level %d (now %d)", level, BF.level()) end }
end

-- ============================================================================ the chains
-- step = { name, done = fn(memo) -> true / false / nil (nil = the game did not answer), act = fn(ctx, memo) -> ok, why,
--          tries = failures in a row before the chain stops, rest = seconds after a failure, cap = attempts in all }
local CHAINS = {}

-- ---------------------------------------------------------------- 1. the Second Sea (First Sea, level 700)
CHAINS[1] = { id = "sea2", switch = "bloxfruits.questSea2", title = "Second Sea", sea = 1,
  complete = function() return BF.sea() >= 2 end,
  steps = {
    levelStep(700),
    { name = "Military Detective: take the key", tries = 3,
      done = function() return flag(dressrosa(), "TalkedDetective") end,
      act = function(ctx)
        local sent, answer = talk(ctx, "Military Detective", "DressrosaQuestProgress", "Detective")   -- DialoguesList.luau:566
        if not sent then return false, answer end
        -- (0 = "Take this key", 1 = talked already, 2 = after the Ice Admiral, else under level 700: :567-586)
        if answer == 0 or answer == 1 or answer == 2 then return true end
        return false, "the Detective says you must be level 700"
      end },
    { name = "Open the Frozen Village door with the key", tries = 3, rest = 4,
      done = function() return flag(dressrosa(), "UsedKey") end,
      act = function(ctx)
        -- DressQuestPro.luau:52-77: with the Key held, its Handle touching Map.Ice.Door sends ("DressrosaQuestProgress", "UseKey").
        if not hold("Key") then return false, "no Key in the backpack (the Detective gives it once: DialoguesList.luau:570)" end
        local door = mapPart("Ice", "Door")                          -- DressQuestPro.luau:4, :8
        local ok, why = touch(ctx, door, 1.5, "At the Ice door", true)
        if not ok then return false, "the Ice door: " .. tostring(why) end
        fresh()
        if flag(dressrosa(), "UsedKey") then return true end
        hold("Key")
        local sent, answer = BF.invoke(8, "DressrosaQuestProgress", "UseKey")   -- DressQuestPro.luau:77 (what the touch sends)
        if sent and answer then return true end
        return false, "the door did not take the key (" .. tostring(answer) .. ")"
      end },
    { name = "Beat the Ice Admiral", tries = 8, rest = 15, cap = 60, wait = 20, waitMax = 2400,
      done = function() return flag(dressrosa(), "KilledIceBoss") end,
      act = function(ctx, memo) return slayBoss(ctx, "Ice Admiral", memo) end },   -- EnemySpawns "Ice Admiral [Lv. 700] [Boss]" (state.json)
    { name = "Sail to the Second Sea", tries = 6, rest = 10, cap = 20,
      done = function() return BF.sea() >= 2 end,
      -- (the game's own menu opens the Second Sea on the three flags above and sends "TravelDressrosa":
      --  ServerBrowser/LocalScript.luau:405, :510-526. The Detective's second talk and the captain are for the story only.)
      act = function(ctx) return travel(ctx, "TravelDressrosa") end },
  } }

-- ---------------------------------------------------------------- 2. the Third Sea (Second Sea, level 1,500)
local function bartiloPlates(ctx)
  -- BartiloQuestPro.luau:62-102: plates under Map.Dressrosa.BartiloPlates, numbered in their names; all eight touched in order 1..8
  -- make the client send ("BartiloQuestProgress", "DidPlates"); a wrong order resets them and blocks touches for 2 s (:85, :111-116).
  local folder = mapPart("Dressrosa", "BartiloPlates")
  if not folder then return false, "Map.Dressrosa.BartiloPlates is not in this map" end
  local plates = {}
  for _, plate in ipairs(folder:GetChildren()) do
    local n = tonumber(string.match(plate.Name, "%d+"))             -- BartiloQuestPro.luau:64
    if n and plate:IsA("BasePart") then plates[n] = plate end
  end
  for n = 1, 8 do
    if not plates[n] then return false, "plate " .. n .. " is missing" end
    local ok, why = touch(ctx, plates[n], 0.6, "Plate " .. n .. " of 8")
    if not ok then return false, "plate " .. n .. ": " .. tostring(why) end
  end
  ctx:sleep(1.5, "Plates pressed")
  fresh()
  if flag(bartilo(), "DidPlates") then return true end
  local sent, answer = BF.invoke(8, "BartiloQuestProgress", "DidPlates")   -- BartiloQuestPro.luau:102 (what the eighth touch sends)
  if sent and answer == true then return true end
  return false, "the plates were not taken (" .. tostring(answer) .. ")"
end
CHAINS[2] = { id = "sea3", switch = "bloxfruits.questSea3", title = "Third Sea", sea = 2,
  complete = function() return BF.sea() >= 3 end,
  steps = {
    levelStep(1500),
    { name = "Bartilo: beat 50 Swan Pirates", tries = 6, rest = 5, cap = 400,
      done = function() return flag(bartilo(), "KilledBandits") end,
      act = function(ctx)
        local ok, why = takeQuest(ctx, "BartiloQuest", "Bartilo", "BartiloQuestProgress")
        if not ok then return false, why end
        return slay(ctx, "Swan Pirate", 3)                          -- Quests.luau:53 (Task: Swan Pirate x50)
      end },
    { name = "Beat Jeremy", tries = 6, rest = 15, cap = 40,
      done = function() return flag(bartilo(), "KilledSpring") end,   -- DialoguesList.luau:784 "Find and defeat Jeremy"
      act = function(ctx, memo) return slayBoss(ctx, "Jeremy", memo) end },
    { name = "Free the gladiators: plates 1 to 8", tries = 3, rest = 3,
      done = function() return flag(bartilo(), "DidPlates") end,
      act = bartiloPlates },
    { name = "Beat Don Swan", tries = 4, rest = 20, cap = 30,
      done = function()
        local check = zCheck()
        if check == nil then return nil end
        return check == 0 or check == 1                             -- past "Come back when ... defeated Don Swan!" (DialoguesList.luau:900)
      end,
      act = function(ctx, memo)
        local ok, why, waiting = slayBoss(ctx, "Don Swan", memo)
        if ok then return true end
        if waiting then return false, why, true end
        -- (his room is behind the Flamingo entrance, which opens only with GetUnlockables().FlamingoAccess: AnimateEntrance.luau:477, :505)
        local unlocks = ask("GetUnlockables")
        local access = type(unlocks) == "table" and tostring(unlocks.FlamingoAccess) or "?"
        return false, why .. " (FlamingoAccess = " .. access .. ")"
      end },
    { name = "King Red Head: begin", tries = 3,
      done = function(memo)
        if memo.begun then return true end
        local check = zCheck()
        if check == nil then return nil end
        return check == 1
      end,
      act = function(ctx, memo)
        local sent, answer = talk(ctx, "King Red Head", "ZQuestProgress", "Check")   -- DialoguesList.luau:881
        if not sent then return false, answer end
        if answer == 1 then return true end
        if answer ~= 0 then return false, "King Red Head is busy (answered " .. tostring(answer) .. ")" end
        local ok, said = BF.invoke(8, "ZQuestProgress", "Begin")    -- DialoguesList.luau:893 ("Of course, admin")
        BF.say("King Red Head: Begin -> " .. tostring(said))
        if ok then memo.begun = true; return true end
        return false, "Begin was not answered (" .. tostring(said) .. ")"
      end },
    { name = "Beat rip_indra", tries = 4, rest = 15, cap = 20,
      done = function()
        local check = zCheck()
        if check == nil then return nil end
        return check == 1                                            -- "I'm currently sealed in the third sea" (DialoguesList.luau:904)
      end,
      -- NOT IN THE DUMP: what "Begin" starts and where rip_indra appears is server-side (ZQuestPro.luau:36-39 only shows the
      -- "KilledIndraBoss" letter after it). He is fought only if a mob of that name is seen; else the chain stops here.
      act = function(ctx, memo) return slayBoss(ctx, "rip_indra", memo) end },
    { name = "Sail to the Third Sea", tries = 6, rest = 10, cap = 20,
      done = function() return BF.sea() >= 3 end,
      -- (the game's own menu opens the Third Sea once ("ZQuestProgress", "Check") answers 1 and sends "TravelZou":
      --  ServerBrowser/LocalScript.luau:405, :555-557)
      act = function(ctx) return travel(ctx, "TravelZou") end },
  } }

-- ---------------------------------------------------------------- 3. the Saber (First Sea)
local function saberField(name) return flag(saber(), name) end
local function sickDone(memo)
  return memo.sick or memo.rich or tool("Relic") ~= nil or saberField("KilledMob") or saberField("UsedRelic")
end
local function platesDone()
  local p = saber()
  if not p then return nil end
  if type(p.Plates) ~= "table" then return false end
  for _, pressed in pairs(p.Plates) do
    if not pressed then return false end
  end
  return true
end
local function pressPlate(ctx)
  local p = saber()
  if not (p and type(p.Plates) == "table") then return false, "no plate list from ProQuestProgress" end
  for n, pressed in pairs(p.Plates) do
    if not pressed then
      -- QuestPro.luau:256-259: Map.Jungle.QuestPlates.Plate<n>.Button; a touch sends ("ProQuestProgress", "Plate", n) (:402)
      local button = mapPart("Jungle", "QuestPlates", "Plate" .. tostring(n), "Button")
      local ok, why = touch(ctx, button, 1.2, "Jungle plate " .. tostring(n))
      if not ok then return false, "plate " .. tostring(n) .. ": " .. tostring(why) end
      fresh()
      local again = saber()
      if again and type(again.Plates) == "table" and again.Plates[n] then return true end
      local sent = BF.invoke(8, "ProQuestProgress", "Plate", n)   -- QuestPro.luau:402 (what the touch sends)
      return sent, "plate " .. tostring(n) .. " was not answered"
    end
  end
  return true
end
local function burnTorch(ctx)
  if not hold("Torch") then return false, "no Torch in the backpack" end
  -- QuestPro.luau:453-471 (state.json: its target is Map.Desert.Burn.Fire): the held Torch's Handle touching the fire, 5 s, then
  -- ("ProQuestProgress", "DestroyTorch").
  local fire = mapPart("Desert", "Burn", "Fire")
  local ok, why = touch(ctx, fire, 6, "Torch in the desert fire", true)
  if not ok then return false, "the desert fire: " .. tostring(why) end
  fresh()
  if saberField("UsedTorch") then return true end
  local sent = BF.invoke(8, "ProQuestProgress", "DestroyTorch")    -- QuestPro.luau:471
  return sent, "DestroyTorch was not answered"
end
local function waterPart()
  -- QuestPro.luau:277-279: Map.Ice.ParticleDrop, child "Water" (state.json shows the live target only as "<Part> Water")
  local drop = mapPart("Ice", "ParticleDrop")
  local water = drop and drop:FindFirstChild("Water")
  if not water then
    local ice = mapPart("Ice")
    water = ice and ice:FindFirstChild("Water", true)
  end
  return water
end
local function fillCup(ctx, memo)
  local cup = hold("Cup")
  if not cup then return false, "no Cup in the backpack" end
  -- QuestPro.luau:517-531: the held Cup's Handle touching the water sends ("ProQuestProgress", "FillCup", cup)
  local ok, why = touch(ctx, waterPart(), 1.5, "Cup in the Frozen Village water", true)
  if not ok then return false, "the water: " .. tostring(why) end
  local sent, answer = BF.invoke(8, "ProQuestProgress", "FillCup", hold("Cup") or cup)   -- QuestPro.luau:531
  if not sent then return false, "FillCup was not answered" end
  memo.filled = true
  BF.say("Saber: FillCup -> " .. tostring(answer))
  return true
end
local function sickMan(ctx, memo)
  hold("Cup")
  local sent, answer = talk(ctx, "Sick Man", "ProQuestProgress", "SickMan")   -- DialoguesList.luau:479 (0 = "Thank you so much!")
  if not sent then return false, answer end
  if answer == 0 then memo.sick = true; return true end
  memo.filled = nil
  return false, "the Sick Man is still thirsty (answered " .. tostring(answer) .. ")"
end
local function richSon(ctx, memo, want)
  local sent, answer = talk(ctx, "Rich Man", "ProQuestProgress", "RichSon")   -- DialoguesList.luau:519
  if not sent then return false, answer end
  -- (0 = "a mob leader has stolen all my money", 1 = "keep this ancient relic", else "Get lost.": :520-534)
  if answer == 0 then memo.rich = true end
  if answer == 1 then memo.rich = true; memo.relic = true end
  if answer ~= 0 and answer ~= 1 then return false, "the Rich Man says \"Get lost.\" (" .. tostring(answer) .. ")" end
  if want == 1 and answer ~= 1 then return false, "no relic yet (answered 0)" end
  return true
end
local function placeRelic(ctx)
  if not hold("Relic") then return false, "no Relic in the backpack" end
  -- QuestPro.luau:115-120: the door is Map.Jungle's child "Final" with no "Invis" in it; the held Relic touching it sends
  -- ("ProQuestProgress", "PlaceRelic") (:603-604)
  local door
  local jungle = mapPart("Jungle")
  for _, child in ipairs(jungle and jungle:GetChildren() or {}) do
    if child.Name == "Final" and not child:FindFirstChild("Invis") then door = child end
  end
  if not door then return false, "the jungle door (Map.Jungle.Final) is not in the map" end
  local ok, why = touch(ctx, door, 1.5, "Relic at the jungle door", true)
  if not ok then return false, "the jungle door: " .. tostring(why) end
  fresh()
  if saberField("UsedRelic") then return true end
  hold("Relic")
  local sent, answer = BF.invoke(8, "ProQuestProgress", "PlaceRelic")   -- QuestPro.luau:604
  if sent and answer then return true end
  return false, "\"The entrance rejects you. You're not ready yet.\" (" .. tostring(answer) .. ")"   -- QuestPro.luau:609
end
CHAINS[3] = { id = "saber", switch = "bloxfruits.questSaber", title = "Saber", sea = 1,
  complete = function(memo) return tool("Saber") ~= nil or memo.expert == true end,
  steps = {
    { name = "Press the five jungle plates", tries = 3, rest = 3, cap = 15, done = platesDone, act = pressPlate },
    { name = "Take the torch", tries = 3, rest = 3,
      done = function()
        local used = saberField("UsedTorch")
        if used == nil then return nil end
        return used or tool("Torch") ~= nil
      end,
      act = function(ctx)
        -- QuestPro.luau:416-438: touching Map.Jungle.Torch sends ("ProQuestProgress", "GetTorch"), then a "Torch" tool comes
        local ok, why = touch(ctx, mapPart("Jungle", "Torch"), 1.5, "At the jungle torch")
        if not ok then return false, "the torch: " .. tostring(why) end
        if tool("Torch") then return true end
        BF.invoke(8, "ProQuestProgress", "GetTorch")                -- QuestPro.luau:438
        ctx:sleep(2, "Waiting for the torch")
        return tool("Torch") ~= nil, "no Torch came"
      end },
    { name = "Burn the torch in the desert", tries = 3, rest = 3, done = function() return saberField("UsedTorch") end, act = burnTorch },
    { name = "Take the cup", tries = 3, rest = 3,
      done = function(memo)
        local used = saberField("UsedCup")
        if used == nil then return nil end
        return used or tool("Cup") ~= nil or sickDone(memo)
      end,
      act = function(ctx)
        -- QuestPro.luau:275, :494-514: touching Map.Desert's "Cup" sends ("ProQuestProgress", "GetCup"), then a "Cup" tool comes
        local desert = mapPart("Desert")
        local ok, why = touch(ctx, desert and desert:FindFirstChild("Cup", true), 1.5, "At the desert cup")
        if not ok then return false, "the cup: " .. tostring(why) end
        if tool("Cup") then return true end
        BF.invoke(8, "ProQuestProgress", "GetCup")                  -- QuestPro.luau:511
        ctx:sleep(2, "Waiting for the cup")
        return tool("Cup") ~= nil, "no Cup came"
      end },
    { name = "Fill the cup at the Frozen Village", tries = 3, rest = 3,
      done = function(memo) return memo.filled == true or saberField("UsedCup") == true or sickDone(memo) end,
      act = fillCup },
    { name = "Sick Man: give him the water", tries = 2, rest = 3, done = sickDone, act = sickMan },
    { name = "Rich Man: talk to the son", tries = 3, rest = 3,
      done = function(memo) return memo.rich or tool("Relic") ~= nil or saberField("KilledMob") or saberField("UsedRelic") end,
      act = function(ctx, memo) return richSon(ctx, memo, 0) end },
    { name = "Beat the Mob Leader", tries = 6, rest = 15, cap = 30,
      done = function() return saberField("KilledMob") end,
      act = function(ctx, memo) return slayBoss(ctx, "Mob Leader", memo) end },    -- the son's line, DialoguesList.luau:523
    { name = "Rich Man: take the relic", tries = 3, rest = 3,
      done = function()
        local used = saberField("UsedRelic")
        if used == nil then return nil end
        return used or tool("Relic") ~= nil
      end,
      act = function(ctx, memo) return richSon(ctx, memo, 1) end },
    { name = "Place the relic at the jungle door", tries = 3, rest = 4, wait = 30, waitMax = 1e9, done = function() return saberField("UsedRelic") end,
      act = function(ctx)
        -- (the door answered "The entrance rejects you. You're not ready yet." at level 168, measured 2026-11-13; the
        --  Saber Expert behind it is level 200. Under 200 the chain waits for the level and the farm keeps the body.)
        if BF.level() < 200 then return false, string.format("the door wants level 200 (now %d)", BF.level()), true end
        return placeRelic(ctx)
      end },
    { name = "Beat the Saber Expert", tries = 6, rest = 15, cap = 30,
      done = function(memo) return tool("Saber") ~= nil or memo.expert == true end,
      act = function(ctx, memo)
        local ok, why, waiting = slayBoss(ctx, "Saber Expert", memo)   -- EnemySpawns "Saber Expert [Lv. 200] [Boss]" (state.json)
        if ok then memo.expert = true end
        return ok, why, waiting
      end },
  } }

-- ---------------------------------------------------------------- 4. the Citizen (Third Sea, level 1,800)
CHAINS[4] = { id = "citizen", switch = "bloxfruits.questCitizen", title = "Citizen", sea = 3,
  complete = function(memo) return memo.thanked == true end,
