      done = function() return flag(citizen(), "FoundTreasure") end,
      act = function(ctx)
        -- CitizenQuestPro.luau:5-9, :46-87: touching Map.Turtle.Treasure sends ("CitizenQuestProgress", "FoundTreasure")
        local ok, why = touch(ctx, mapPart("Turtle", "Treasure"), 1.5, "At the treasure")
        if not ok then return false, "the treasure: " .. tostring(why) end
        fresh()
        if flag(citizen(), "FoundTreasure") then return true end
