-- ============================================================================ the runner
for _, chain in ipairs(CHAINS) do
  chain.line, chain.memo, chain.state = "Off.", {}, {}
end
local gaveUp = {}            -- chain id -> until when "next sea by itself" leaves it alone
local function reset(chain)
  chain.memo, chain.state, chain.unknown, chain.waitUntil = {}, {}, 0, nil
end
local function stopChain(chain, text, failed)
  chain.line = text
  BF.say(chain.title .. ": " .. text)
  if failed then
    gaveUp[chain.id] = now() + 600
    Window.toast({ title = chain.title, text = text, icon = "flag", time = 8 })
  end
  reset(chain)
  Config.set(chain.switch, false)
end
local function activeChain()
  for _, chain in ipairs(CHAINS) do
    if Config.get(chain.switch) == true then return chain end
  end
  return nil
end
-- the first step not done: index, step; or nil when all are; or "unknown" when the game did not answer
local function firstOpen(chain)
  for index, step in ipairs(chain.steps) do
    local ok, done = pcall(step.done, chain.memo)
    if not ok or done == nil then return "unknown", index, step end
    if not done then return index, step end
  end
  return nil
end
local function round(ctx, chain)
  fresh()
  if chain.complete(chain.memo) then stopChain(chain, "done."); ctx:progress(); return end
  if BF.sea() ~= chain.sea then
    local seas = { "First", "Second", "Third" }
    stopChain(chain, "this chain runs in the " .. seas[chain.sea] .. " Sea.", true)
    return
  end
  local index, step, asked = firstOpen(chain)
  if index == "unknown" then
    chain.unknown = (chain.unknown or 0) + 1
    if chain.unknown >= 5 then
      stopChain(chain, string.format("stopped at step %d of %d (%s): the game does not answer its check", step, #chain.steps, asked.name), true)
    else
      ctx:sleep(3, chain.title .. ": the game did not answer")
    end
    return
  end
  chain.unknown = 0
  if not index then stopChain(chain, "done."); ctx:progress(); return end
  local state = chain.state[index] or { fails = 0, acts = 0 }
  chain.state[index] = state
  chain.line = string.format("step %d of %d: %s", index, #chain.steps, step.name)
  ctx:beat(chain.title .. ": " .. step.name)
  if state.acts >= (step.cap or 12) then
    stopChain(chain, string.format("stopped at step %d of %d (%s): %d tries without it done (%s)", index, #chain.steps, step.name, state.acts,
      tostring(state.why or "no reason given")), true)
    return
  end
  state.acts += 1
  local ok, okAct, why, waiting = pcall(step.act, ctx, chain.memo)
  if ctx.stop then return end
  if ok and okAct then
    state.fails, state.waitSince = 0, nil
    ctx:progress()
    return
  end
  if ok and waiting then
    -- Not a failure: the step waits on the game (a boss on its timer, a level). The chain lets the body go for a
    -- while, so the farm goes on meanwhile, and asks again. A wait is not a try; one that never ends still stops.
    state.acts -= 1
    state.waitSince = state.waitSince or now()
    if now() - state.waitSince > (step.waitMax or 2400) then
      stopChain(chain, string.format("stopped at step %d of %d (%s): waited %d min (%s)", index, #chain.steps, step.name,
        math.floor((now() - state.waitSince) / 60), tostring(why)), true)
      return
    end
    chain.line = string.format("step %d of %d: %s. Waiting: %s", index, #chain.steps, step.name, tostring(why))
    chain.waitUntil = now() + (step.wait or 20)
    ctx:progress()
    return
  end
  why = ok and why or ("it broke: " .. string.sub(tostring(okAct), 1, 100))
  state.fails += 1
  state.why = why
  if state.fails >= (step.tries or 3) then
    stopChain(chain, string.format("stopped at step %d of %d (%s): %s", index, #chain.steps, step.name, tostring(why)), true)
  else
    BF.say(string.format("%s, %s: %s (try %d of %d)", chain.title, step.name, tostring(why), state.fails, step.tries or 3))
    BF.release()
    ctx:sleep(step.rest or 3, chain.title .. ": resting after a failed try")
  end
end
local function run(ctx)
  while B.alive and not ctx.stop do
    if not ctx:body(40) then return end
    local chain = activeChain()
    if not chain then return end
    -- (waiting on the game: the job does not want the body until the wait is over)
    if chain.waitUntil and chain.waitUntil > now() then return end
    round(ctx, chain)
    task.wait(0.2)
  end
end
local function wanted(first)
  local chain = activeChain()
  return chain ~= nil and not (chain.waitUntil and chain.waitUntil > now()) and (O.questFirst == true) == first
end

-- "Go to the next sea by itself": the sea chain is switched on once the level allows (not again for 10 min after one stopped itself)
local function nextSea()
  if not O.questNextSea then return end
  local sea, level = BF.sea(), BF.level()
  local chain = (sea == 1 and level >= 700 and CHAINS[1]) or (sea == 2 and level >= 1500 and CHAINS[2]) or nil
  if chain and Config.get(chain.switch) ~= true and (gaveUp[chain.id] or 0) < now() then
    BF.say(chain.title .. ": level " .. level .. ", starting the chain by itself")
    Config.set(chain.switch, true)
  end
end

local function start()
  -- (two jobs, one runner: just under the level farm, or just over it when "before levelling" is ticked)
  BF.job({ id = "questChain", label = "Quest chain", priority = 48, quiet = 30, patience = 360, gentle = true, want = function() return wanted(false) end, run = run })
  BF.job({ id = "questChainFirst", label = "Quest chain", priority = 52, quiet = 30, patience = 360, gentle = true, want = function() return wanted(true) end, run = run })
  -- ("Stop everything" and Panic stop the chains too, and the switch that would start one again)
  if BF.offToo then
    BF.offToo[#BF.offToo + 1] = "bloxfruits.questNextSea"
    for _, chain in ipairs(CHAINS) do BF.offToo[#BF.offToo + 1] = chain.switch end
  end
  for _, chain in ipairs(CHAINS) do
    if type(Config.on) == "function" then
      Config.on(chain.switch, function()
        if Config.get(chain.switch) == true then
          reset(chain)
          chain.line = "Starting."
        elseif chain.line == "Starting." or string.sub(chain.line, 1, 5) == "step " then
          chain.line = "Off."
        end
      end)
    end
  end
  Motion.every(function() B.try("bloxfruits.questNextSea", nextSea) end, 0.2, "bloxfruits.questNextSea")
end

-- ============================================================================ the progress card
local function yes(value) return value and "yes" or "no" end
local function progressLines()
  fresh()
  local lines = {}
  local unlocks, number = nil, nil
  local ok, a, b = BF.invoke(8, "GetUnlockables")                   -- AnimateEntrance.luau:153 (.field), :315 (second value, a number)
  if ok then unlocks, number = a, b end
  if type(unlocks) == "table" then
    local open, shut = {}, {}
    for key, value in pairs(unlocks) do
      if value == true then open[#open + 1] = tostring(key) elseif value == false then shut[#shut + 1] = tostring(key) end
    end
    table.sort(open)
    table.sort(shut)
    lines[#lines + 1] = "Unlocked: " .. (#open > 0 and table.concat(open, ", ") or "nothing") .. (number and ("  ·  " .. tostring(number)) or "")
    lines[#lines + 1] = "Not yet: " .. (#shut > 0 and table.concat(shut, ", ") or "nothing")
  else
    lines[#lines + 1] = "Unlocked: no answer"
    lines[#lines + 1] = ""
  end
  local d = dressrosa()
  lines[#lines + 1] = d and string.format("Second Sea: detective %s, key %s, Ice Admiral %s", yes(d.TalkedDetective), yes(d.UsedKey), yes(d.KilledIceBoss))
    or "Second Sea: no answer"
  local z = zCheck()
  lines[#lines + 1] = "Third Sea: " .. (z == 1 and "open" or z == 0 and "King Red Head is waiting" or z == nil and "no answer" or "level 1,500 and Don Swan first")
  local bt = bartilo()
  lines[#lines + 1] = bt and string.format("Bartilo: pirates %s, Jeremy %s, plates %s", yes(bt.KilledBandits), yes(bt.KilledSpring), yes(bt.DidPlates))
    or "Bartilo: no answer"
  local p = saber()
  if p then
    local pressed, all = 0, 0
    for _, v in pairs(type(p.Plates) == "table" and p.Plates or {}) do all += 1; if v then pressed += 1 end end
    lines[#lines + 1] = string.format("Saber: plates %d/%d, torch %s, cup %s, Mob Leader %s, relic %s", pressed, all, yes(p.UsedTorch), yes(p.UsedCup),
      yes(p.KilledMob), yes(p.UsedRelic))
  else
    lines[#lines + 1] = "Saber: no answer"
  end
  local c = citizen()
  lines[#lines + 1] = c and string.format("Citizen: pirates %s, Captain Elephant %s, treasure %s", yes(c.KilledBandits), yes(c.KilledBoss), yes(c.FoundTreasure))
    or "Citizen: no answer"
  return lines
end

-- ============================================================================ the tab
local DESCS = {
  sea2 = "Detective, key, Ice Admiral, then it sails. Level 700.",
  sea3 = "Bartilo, Jeremy, plates, Don Swan, King Red Head. Level 1,500.",
  saber = "Plates, torch, cup, Sick Man, Mob Leader, relic, Saber Expert.",
  citizen = "Forest Pirates, Captain Elephant, the treasure. Level 1,800.",
}
local ICONS = { sea2 = "anchor", sea3 = "anchor", saber = "shield", citizen = "map-pin" }
local function questTab(page)
  local s = page:section({ title = "Quest chains", icon = "flag", desc = "One chain at a time. Each step is asked of the game." })
  local notes = {}
  for _, chain in ipairs(CHAINS) do
    s:toggle({ id = chain.switch, label = chain.title, desc = DESCS[chain.id], default = false, bindable = false })
    notes[chain.id] = s:note({ icon = ICONS[chain.id], text = chain.line })
  end
  local how = page:section({ title = "How", icon = "clock", column = 2 })
  how:toggle({ id = "bloxfruits.questFirst", label = "Before levelling", desc = "Chains get the body before Auto level.", default = false, bindable = false })
  how:toggle({ id = "bloxfruits.questNextSea", label = "Go to the next sea by itself", desc = "Starts the sea chain once the level allows.", default = false, bindable = false })
  local card = page:section({ title = "Progress", icon = "trophy", column = 2, desc = "What the server says. Reads only." })
  local rows = {}
  for i = 1, 7 do rows[i] = card:note({ icon = i <= 2 and "crown" or "flag", text = i == 1 and "Press Ask." or "" }) end
  local asking = false
  card:button({ id = "bloxfruits.questProgress", label = "Ask the game", desc = "Six progress commands, nothing changed.", text = "Ask", run = function()
    if asking then return end
    asking = true
    task.spawn(function()
      B.try("bloxfruits.questProgress", function()
        local lines = progressLines()
        for i, row in ipairs(rows) do row.set(lines[i] or "") end
      end)
      asking = false
    end)
  end })
  Motion.every(function()
    if not Window.anyOpen() then return end
    for _, chain in ipairs(CHAINS) do
      local note = notes[chain.id]
      if note and note.frame.Parent then note.set(chain.line) end
    end
  end, 2, "bloxfruits.questLines")
end

BF.parts[#BF.parts + 1] = { id = "quest", start = start, quest = questTab,
  defaults = { questSea2 = false, questSea3 = false, questSaber = false, questCitizen = false, questFirst = false, questNextSea = false } }
end
do -- bloxfruits_race.lua
-- ============================================================================
--  Blox Fruits     race: the card, V2, V3, V4, Draco, and the race skill
--
--  Read from the game's own code (dump 2753915549 v4630, `fast\` folder; the
--  First Sea place, but ReplicatedStorage holds the dialogue of every sea).
--  NOTHING here was run on the live game: every line is unproven until measured.
--
--   * Every race NPC's dialogue asks the server first and branches on a number
--     (Alchemist "1", Wenlocktoad "1", RaceV4Progress "Check", UpgradeRace
--     "Check"); that number is the stage, and the card shows it.
--   * The map scripts of the Second and Third Sea are NOT in the dump: how a
--     flower is found, the Great Tree, the lever, the gear on Mirage Island,
--     the mirror and the trial doors are not known here. A chain that reaches
--     such a step stops there and says so; nothing is guessed.
--   * Trials, Sea Beasts, Terrorsharks and anything against players are not
--     automated. Beli and Fragments are spent only when the player ticked it.
--
--  The chain runner is a copy of bloxfruits_quest.lua's (same behaviour, its own
--  locals): an ordered list of steps { name, done, act }, try limits, a cap, and
--  "stopped at step N of M (name): why", after which the chain switches itself off.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion = B.S, B.Config, B.Window, B.Motion
local BF = B.BloxFruits
local O = BF.O
local CollectionService = game:GetService("CollectionService")
local function now() return os.clock() end

-- ---------------------------------------------------------------- asking the game
-- A read-only CommF_ check is asked once a round and kept for that round (several steps read the same answer).
-- Some answer more than one value (UpgradeRace "Check" -> state, upgrades done, price): all are kept.
local NONE = {}
local cache = {}
local function ask(...)
  local parts = {}
  for i, v in ipairs({ ... }) do parts[i] = tostring(v) end
  local key = table.concat(parts, "|")
  local got = cache[key]
  if got == nil then
    local out = table.pack(BF.invoke(6, ...))
    got = out[1] and table.pack(table.unpack(out, 2, out.n)) or NONE
    cache[key] = got
  end
  if got == NONE then return nil end
  return table.unpack(got, 1, got.n)
end
local function fresh() table.clear(cache) end

-- Alchemist "1": -2 paid, -1 short of $500,000, 0 not begun, 1 looking for flowers, 2 flowers in, 5 "What are you?"
local function alchemist() return ask("Alchemist", "1") end                      -- DialoguesList/NPCs/Alchemist.luau:28 (branches :29-85)
-- Wenlocktoad "1": -2 done, -1 short of $2,000,000, 0 not begun, 1 task running, 2 task done, 5 "What are you?"
local function arowe() return ask("Wenlocktoad", "1") end                        -- DialoguesList/NPCs/Wenlocktoad.luau:28 (branches :29-84)
-- RaceV4Progress "Check": 0 asleep, 1 Begin, 2 Great Tree, 3 Continue, 4 full-moon trial, 5 at the temple
local function v4() return ask("RaceV4Progress", "Check") end                    -- DialoguesList/NPCs/SealedKing.luau:9 (branches :10-65)
-- UpgradeRace "Check" -> state, upgrades, price in Fragments; Draco asks it with a 2
local function upgrade(draco)
  if draco then return ask("UpgradeRace", "Check", 2) end                        -- DialoguesList/NPCs/DracoV4Upgrader.luau:10
  return ask("UpgradeRace", "Check")                                             -- DialoguesList/NPCs/RaceV4Upgrader.luau:12
end
-- { Race, RaceLevel, HadPoint, RaceDetails = { Gears = { "A"/"B"/.. }, A, B, C } }
local function clock()
  local t = ask("TempleClock", "Check")                                          -- StarterGui/TempleGui/LocalScriptTemple.luau:164 (fields :200-215)
  return type(t) == "table" and t or nil
end

-- A Net remote of the game's, through its own module (the folder is checked first: Net waits 99 s for a missing one).
local remotes = {}
local function netRF(name)
  local got = remotes[name]
  if got then return got end
  local modules = S.ReplicatedStorage:FindFirstChild("Modules")
  local folder = modules and modules:FindFirstChild("Net")
  if not (folder and folder:FindFirstChild("RF/" .. name)) then return nil end
  local net = BF.mod("Modules", "Net")
  if not net then return nil end
  local ok, remote = BF.game(net.RemoteFunction, net, name)                       -- as DojoTrainer.luau:5 / DragonHunter.luau:34 get theirs
  if not ok or remote == nil then return nil end
  remotes[name] = remote
  return remote
end
-- One InvokeServer on a Net remote, with an end to the wait. Returns answered, value1, value2.
local function netCall(timeout, name, payload)
  local remote = netRF(name)
  if not remote then return false, "no Net remote " .. name end
  local done, out = false, nil
  BF.count.calls += 1
  task.spawn(function()
    out = table.pack(BF.game(function() return remote:InvokeServer(payload) end))
    done = true
  end)
  local started = now()
  while not done and now() - started < (timeout or 6) do task.wait() end
  if not done then return false, "timeout" end
  if not out[1] then return false, tostring(out[2]) end
  return true, out[2], out[3]
end
local netCache = {}
local function netAsk(name, payload)
  local key = name .. "|" .. tostring(payload.NPC) .. "|" .. tostring(payload.Command) .. "|" .. tostring(payload.Context)
  local got = netCache[key]
  if got == nil then
    local ok, value = netCall(8, name, payload)
    got = ok and { value } or NONE
    netCache[key] = got
  end
  if got == NONE then return nil end
  return got[1]
end
local function freshAll() fresh(); table.clear(netCache) end
-- { CanTransform, CanTransformFree, CanLearnTether, TetherLearned, AvailableVQuest, FoundPrehistoric, V4, Race, Special, WantsBlizz }
local function wizard()
  local v = netAsk("InteractDragonQuest", { NPC = "Dragon Wizard", Command = "Speak" })   -- DialoguesList/NPCs/DragonWizard.luau:19
  return type(v) == "table" and v or nil
end

-- ---------------------------------------------------------------- the player's race, read from the client
-- Data.Race is a StringValue; the game shows Fishman as Shark, Skypiea as Angel, Mink as Rabbit (React/Hooks/Player/useRace.luau:37-46, :73)
local SHOWN = { Fishman = "Shark", Skypiea = "Angel", Mink = "Rabbit" }
local function race() return BF.data("Race") end
local function raceShown()
  local r = race()
  return r and (SHOWN[r] or r) or "?"
end
-- the race's own V3 skill tools: the skill key is bound only while one is held (StarterCharacterScripts/RaceAbility.luau:15-26)
local SKILLS = { "Last Resort", "Agility", "Water Body", "Heavenly Blood", "Heightened Senses", "Energy Core", "Primordial Reign" }
local function tool(name)
  local character, pack = BF.char(), B.LP:FindFirstChild("Backpack")
  local found = (character and character:FindFirstChild(name)) or (pack and pack:FindFirstChild(name))
  return found and found:IsA("Tool") and found or nil
end
local function skillTool()
  for _, name in ipairs(SKILLS) do
    if tool(name) then return name end
  end
  return nil
end
-- the V4 transform is offered only while an "Awakening" tool is held (Controllers/UI/RaceV4Button.luau:104-109)
local function awakened() return tool("Awakening") ~= nil end
local function charValue(name)
  local character = BF.char()
  local v = character and character:FindFirstChild(name)
  if v == nil then return nil end
  local ok, value = pcall(function() return v.Value end)
  return ok and value or true
end
-- the Ancient One talks only with a RaceTransformed child on the character (RaceV4Upgrader.luau:11)
local function transformedChild() local c = BF.char(); return c ~= nil and c:FindFirstChild("RaceTransformed") ~= nil end
local function moonPhase() return game:GetService("Lighting"):GetAttribute("MoonPhase") end   -- 5 = full: DialoguesList.luau:5226
local function raceValues()
  local data = B.LP:FindFirstChild("Data")
  local r = data and data:FindFirstChild("Race")
  if not r then return "no Data.Race" end
  -- (A / B are read by Dodge.luau:131, :163; Evolved by LocalScriptTemple.luau:87)
  local out = {}
  for _, child in ipairs(r:GetChildren()) do
    local ok, value = pcall(function() return child.Value end)
    out[#out + 1] = child.Name .. " " .. tostring(ok and value or "?")
  end
  table.sort(out)
  return #out > 0 and table.concat(out, ", ") or "none"
end
local function rerolls()
  local data = B.LP:FindFirstChild("Data")
  local v = data and data:FindFirstChild("RaceRerolls")                          -- React/Hooks/Player/useRaceRerolls.luau:26
  return v and v.Value or nil
end
local function beli() return tonumber(BF.data("Beli")) or 0 end
local function frags() return tonumber(BF.data("Fragments")) or 0 end

-- ---------------------------------------------------------------- the world
-- An NPC's standing point: FloorPos on the model (near ones in workspace.NPCs, the rest parked in ReplicatedStorage.NPCs).
-- The names are the game's own registry keys (NPCManager/NPCList.luau:843 Alchemist, :867 arowe, :1447 Mysterious Force,
-- :1507 Ancient One, :1543 Dragon Hunter, :1555 Dojo Trainer, :1579 Sealed King, :2281 Dragon Wizard).
local function npcPoint(name)
  for _, folder in ipairs({ workspace:FindFirstChild("NPCs"), S.ReplicatedStorage:FindFirstChild("NPCs") }) do
    local model = folder and folder:FindFirstChild(name)
    if model then
      local floor = model:GetAttribute("FloorPos")
      if typeof(floor) == "Vector3" then return floor end
      local ok, pivot = pcall(model.GetPivot, model)
      if ok and pivot and pivot.Position.Magnitude > 1 then return pivot.Position end
    end
  end
  return nil
end
local function goTo(ctx, npc)
  local point = npcPoint(npc)
  if not point then return false, npc .. " is not among this sea's NPCs" end
  local ok, why = BF.fly(point + Vector3.new(0, 4, 0), ctx, { note = "To " .. npc })
  if not ok then return false, "could not reach " .. npc .. " (" .. tostring(why) .. ")" end
  ctx:sleep(0.4, "At " .. npc)
  return true
end
-- Fly to an NPC, then send what its dialogue sends. Returns sent, answer (or false, why).
local function talk(ctx, npc, ...)
  local ok, why = goTo(ctx, npc)
  if not ok then return false, why end
  local sent, answer = BF.invoke(8, ...)
  if not sent then return false, npc .. " did not answer (" .. tostring(answer) .. ")" end
  return true, answer
end
local function netTalk(ctx, npc, payload)
  local ok, why = goTo(ctx, npc)
  if not ok then return false, why end
  local sent, answer, second = netCall(8, "InteractDragonQuest", payload)
  if not sent then return false, npc .. " did not answer (" .. tostring(answer) .. ")" end
  return true, answer, second
end

-- ---------------------------------------------------------------- fighting, with the death guard of bloxfruits_boss.lua
local streak, aside = {}, {}        -- foe -> deaths in a row; boss -> until when it is left alone
-- After a fight: wait for the body if it died, count deaths in a row on the same foe. True = that foe is set aside.
local function guard(ctx, key, result, before)
  if result == "died" or not BF.alive() then ctx:body(40) end
  if result == "dead" then streak[key] = 0; return false end
  local died = BF.count.deaths - before
  if died <= 0 then return false end
  streak[key] = (streak[key] or 0) + died
  if streak[key] < (O.raceDeaths or 3) then return false end
  BF.say(string.format("%s killed the body %d times in a row: left alone for 30 min", key, streak[key]))
  streak[key] = 0
  aside[key] = now() + 1800
  return true
end
local function slay(ctx, name)
  local root = BF.root()
  if not root then return false, "no body" end
  local mobs = BF.mobs(name, root.Position)
  if #mobs == 0 then
    local spawns = BF.spawns(name)
    if #spawns == 0 then return false, "no " .. name .. " here and no spawn mark of it" end
    table.sort(spawns, function(a, b) return (a - root.Position).Magnitude < (b - root.Position).Magnitude end)
    local ok, why = BF.fly(spawns[1] + Vector3.new(0, O.height or 25, 0), ctx, { note = "To where " .. name .. " appears" })
    if not ok then return false, why end
    ctx:sleep(5, "Waiting for " .. name)
    root = BF.root()
    mobs = BF.mobs(name, root and root.Position)
    if #mobs == 0 then aside[name] = now() + 120; return false, name .. " is not up" end
  end
  local before = BF.count.deaths
  local result = BF.fight(mobs[1], ctx, function() return {} end)
  if guard(ctx, name, result, before) then return false, name .. " is too strong (left alone 30 min)" end
  if result == "dead" then return true end
  if result == "stuck" then aside[name] = now() + 120 end
  return false, name .. ": " .. result
end
-- The bosses of this sea, from the game's spawn marks ("Chef [Lv. 55] [Boss]", NOTES.md), at or under the player's level,
-- up (in workspace.Enemies, or parked as a living model in ReplicatedStorage: NOTES.md), nearest first.
local function bossesUp()
  local origin = workspace:FindFirstChild("_WorldOrigin")
  local folder = origin and origin:FindFirstChild("EnemySpawns")
  local root = BF.root()
  if not (folder and root) then return {} end
  local list, seen, t = {}, {}, now()
  for _, mark in ipairs(folder:GetChildren()) do
    local name, level = string.match(mark.Name, "^(.-) %[Lv%.%s*(%d+)%]")
    if name and mark:IsA("BasePart") and string.find(mark.Name, "[Boss]", 1, true) and not seen[name] and tonumber(level) <= BF.level()
      and not ((aside[name] or 0) > t) then
      seen[name] = true
      local parked = S.ReplicatedStorage:FindFirstChild(name)
      local hum = parked and parked:IsA("Model") and parked:FindFirstChildOfClass("Humanoid")
      if BF.mobs(name)[1] or (hum and hum.Health > 0) then
        list[#list + 1] = { name = name, gap = (mark.Position - root.Position).Magnitude }
      end
    end
  end
  table.sort(list, function(a, b) return a.gap < b.gap end)
  return list
end

-- ---------------------------------------------------------------- chests (as bloxfruits_loot.lua takes them)
-- A chest is a part tagged "_ChestTagged" (ChestConfiguration/ChestSettings.luau:5), taken by touch; the server confirms
-- with its "IsDisabled" attribute (ChestSettings.luau:5 UPDATE_ATTRIBUTE; ClientChest.luau:153-161), within 3 s (:88-100).
local chestAside = BF.keep({})
local function nearestChest()
  local root = BF.root()
  if not root then return nil end
  local best, gap, t = nil, 5000, now()
  for _, part in ipairs(CollectionService:GetTagged("_ChestTagged")) do
    if part:IsA("BasePart") and part:IsDescendantOf(workspace) and part:GetAttribute("IsDisabled") ~= true and not ((chestAside[part] or 0) > t) then
      local d = (part.Position - root.Position).Magnitude
      if d < gap then best, gap = part, d end
    end
  end
  return best
end
local function takeChest(ctx)
  local part = nearestChest()
  if not part then return false, "no open chest within 5,000 studs (they stream in near the body)" end
  local ok, why = BF.fly(part.Position, ctx, { speed = 200, note = "To a chest" })
  if not ok then chestAside[part] = now() + 90; return false, "a chest: " .. tostring(why) end
  local untilAt = now() + 3
  while now() < untilAt and part:GetAttribute("IsDisabled") ~= true and part.Parent do
    if ctx.stop then return false, "stopped" end
    BF.holdAt(part.Position)
    ctx:beat("Opening a chest")
    task.wait(0.1)
  end
  if part:GetAttribute("IsDisabled") ~= true and part.Parent then
    chestAside[part] = now() + 90
    return false, "the server did not take a chest"
  end
  ctx:progress()
  return true
end

-- ---------------------------------------------------------------- a proximity prompt, pressed the way a player does
local vim
local function inputService()
  if vim == nil then
    local ok, service = pcall(game.GetService, game, "VirtualInputManager")
    vim = ok and service or false
  end
  return vim or nil
end
local VK = { T = 0x54, E = 0x45 }
-- One key down or up, exactly as bloxfruits_mastery.lua's press() (VirtualInputManager first, else keypress / keyrelease).
local function press(key, down)
  local service = inputService()
  if service and pcall(service.SendKeyEvent, service, down, Enum.KeyCode[key], false, game) then return true end
  local fn = down and keypress or keyrelease
  if type(fn) == "function" and VK[key] and pcall(fn, VK[key]) then return true end
  return false
end
local function holdPrompt(ctx, prompt)
  local key = prompt.KeyboardKeyCode and prompt.KeyboardKeyCode.Name or "E"
  if not press(key, true) then return false end
  ctx:sleep((tonumber(prompt.HoldDuration) or 0) + 0.3, "Holding " .. key)
  press(key, false)
  return true
end

-- ============================================================================ the chains
-- step = { name, done = fn(memo) -> true / false / nil (nil = the game did not answer),
--          act = fn(ctx, memo) -> ok, why, final (final = stop the chain now: the next move is not this hub's),
--          tries = failures in a row before the chain stops, rest = seconds after a failure, cap = attempts in all }
local CHAINS = {}
local function inSea(n)
  local seas = { "First", "Second", "Third" }
  return { name = "In the " .. seas[n] .. " Sea", tries = 1, done = function() return BF.sea() == n end,
    act = function() return false, "this chain runs in the " .. seas[n] .. " Sea (now the " .. seas[BF.sea()] .. ")", true end }
end
local function inList(value, ...)
  for _, v in ipairs({ ... }) do if value == v then return true end end
  return false
end
local function known(value, ...)
  if value == nil then return nil end
  return inList(value, ...)
end
local function pay(ctx, npc, cost, command, arg, doneValue, read)
  if O.raceSpendBeli ~= true then return false, string.format("%s wants $%s: tick \"May spend Beli\"", npc, cost), true end
  local need = tonumber((string.gsub(cost, ",", ""))) or 0
  if beli() < need then return false, string.format("%s wants $%s (you have $%d)", npc, cost, beli()), true end
  local sent, said = talk(ctx, npc, command, arg)
  BF.say(npc .. ": " .. command .. " " .. tostring(arg) .. " -> " .. tostring(said))
  if not sent then return false, said end
  fresh()
  if read() == doneValue then return true end
  return false, npc .. " answered " .. tostring(said)
end

-- ---------------------------------------------------------------- 1. Race V2: the Alchemist (Second Sea)
CHAINS[1] = { id = "v2", switch = "bloxfruits.raceV2", title = "Race V2", sea = 2,
  complete = function() return alchemist() == -2 end,
  steps = {
    inSea(2),
    { name = "Alchemist: take the quest", tries = 3,
      done = function() return known(alchemist(), 1, 2, -1, -2) end,
      act = function(ctx)
        local sent, answer = talk(ctx, "Alchemist", "Alchemist", "1")              -- Alchemist.luau:28
        if not sent then return false, answer end
        if answer == 0 then
          local ok, said = BF.invoke(8, "Alchemist", "2")                          -- Alchemist.luau:50 ("I'll do it.")
          BF.say("Alchemist: " .. tostring(said))
          return ok, "the Alchemist did not answer"
        end
        if inList(answer, 1, 2, -1, -2) then return true end
        return false, "the Alchemist says \"" .. (answer == 5 and "What are you?" or "I don't think you're ready yet.") .. "\" (" .. tostring(answer) .. ")", true
      end },
    { name = "Bring the three flowers", tries = 1,
      done = function() return known(alchemist(), 2, -1, -2) end,
      act = function(ctx)
        local held = (tool("Flower 1") and 1 or 0) + (tool("Flower 2") and 1 or 0) + (tool("Flower 3") and 1 or 0)
        if held == 3 then
          -- (all three are Tools named "Flower 1..3": Economy/ItemId/RawSource.luau:1153-1155; the Alchemist is asked again)
          local sent, answer = talk(ctx, "Alchemist", "Alchemist", "1")            -- Alchemist.luau:28
          if sent and inList(answer, 2, -1, -2) then return true end
          return false, "three flowers held, but the Alchemist answered " .. tostring(answer), true
        end
        -- NOT IN THE DUMP: the Second Sea map scripts that place the flowers and let one be picked
        return false, string.format("%d of 3 flowers held; where and how a flower is picked is not in the dump", held), true
      end },
    { name = "Alchemist: pay $500,000", tries = 2,
      done = function() return known(alchemist(), -2) end,
      act = function(ctx) return pay(ctx, "Alchemist", "500,000", "Alchemist", "3", -2, alchemist) end },   -- Alchemist.luau:71 ("Pay")
  } }

-- ---------------------------------------------------------------- 2. Race V3: arowe (Wenlocktoad, Second Sea)
local function v3Task(ctx, memo)
  -- (asked once per run, at arowe, as his dialogue does; later rounds go straight to the task)
  if not memo.info then
    local sent, info = talk(ctx, "arowe", "Wenlocktoad", "info")                   -- Wenlocktoad.luau:56 (the task, as the server words it)
    if not sent then return false, info end
    memo.info = type(info) == "table" and table.concat(info, " ") or tostring(info)
    BF.say("arowe: " .. memo.info)
  end
  local text = memo.info
  local low, short = string.lower(text), string.sub(text, 1, 90)
  -- (the words are the server's: read for what they ask, never guessed per race)
  if string.find(low, "player", 1, true) then return false, "the task is against players: not automated (\"" .. short .. "\")", true end
  if string.find(low, "sea beast", 1, true) or string.find(low, "seabeast", 1, true) then
    return false, "the task is a Sea Beast: not automated (\"" .. short .. "\")", true
  end
  if string.find(low, "chest", 1, true) then return takeChest(ctx) end
  if string.find(low, "boss", 1, true) then
    local up = bossesUp()
    if #up == 0 then return false, "no boss at or under your level is up now" end
    return slay(ctx, up[1].name)
  end
  return false, "the task (\"" .. short .. "\") is not one this hub does", true
end
CHAINS[2] = { id = "v3", switch = "bloxfruits.raceV3", title = "Race V3", sea = 2,
  complete = function() return arowe() == -2 end,
  steps = {
    inSea(2),
    { name = "arowe: take the task", tries = 3,
      done = function() return known(arowe(), 1, 2, -1, -2) end,
      act = function(ctx)
        local sent, answer = talk(ctx, "arowe", "Wenlocktoad", "1")                -- Wenlocktoad.luau:28
        if not sent then return false, answer end
        if answer == 0 then
          local ok, said = BF.invoke(8, "Wenlocktoad", "2")                        -- Wenlocktoad.luau:49 ("I'm interested")
          BF.say("arowe: " .. tostring(said))
          return ok, "arowe did not answer"
        end
        if inList(answer, 1, 2, -1, -2) then return true end
        return false, "arowe says \"" .. (answer == 5 and "What are you?" or "Come back when you're prepared enough.") .. "\" (" .. tostring(answer) .. ")", true
      end },
    { name = "Do the task", tries = 6, rest = 5, cap = 300,
      done = function() return known(arowe(), 2, -1, -2) end,
      act = v3Task },
    { name = "arowe: pay $2,000,000", tries = 2,
      done = function() return known(arowe(), -2) end,
      act = function(ctx) return pay(ctx, "arowe", "2,000,000", "Wenlocktoad", "3", -2, arowe) end },     -- Wenlocktoad.luau:70 ("Pay")
  } }

-- ---------------------------------------------------------------- 3. Race V4: the Sealed King and the Temple of Time (Third Sea)
local function atLeast(n)
  return function()
    local stage = v4()
    if type(stage) ~= "number" then return nil end
    return stage >= n
  end
end
-- The Mysterious Force's "Use it": the game first moves the stashed temple into the map (and back on the next spawn), then
-- asks the server for the trip (DialoguesList.luau:4041-4077).
local function enterTemple(ctx)
  local map, stash = workspace:FindFirstChild("Map"), S.ReplicatedStorage:FindFirstChild("MapStash")
  if map and map:FindFirstChild("Temple of Time") then
    return false, "inside the Temple of Time already; what moves stage 2 to 3 there is not in the dump", true
  end
  local sent, stage = talk(ctx, "Mysterious Force", "RaceV4Progress", "Check")     -- DialoguesList.luau:4041
  if not sent then return false, stage end
  if type(stage) ~= "number" or stage < 2 then return false, "the Force says \"you can't quite place it\" (" .. tostring(stage) .. ")", true end
  local temple = stash and stash:FindFirstChild("Temple of Time")
  if temple and map then
    pcall(function() temple.Parent = map end)                                       -- DialoguesList.luau:4050-4051
    B.LP.CharacterAdded:Once(function()                                             -- :4052-4073 (put back after the next spawn)
      if workspace:GetAttribute("RestartingTemple") then return end
      local inMap = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Temple of Time")
      if inMap and stash then pcall(function() inMap.Parent = stash end) end
    end)
  end
  local ok, said = BF.invoke(10, "RaceV4Progress", "Teleport")                      -- DialoguesList.luau:4077
  BF.say("Temple of Time: Teleport -> " .. tostring(type(said) == "table" and table.concat(said, " ") or said))
  ctx:sleep(6, "Into the Temple of Time")
  fresh()
  if atLeast(3)() then return true end
  return false, ok and "in the temple; what moves stage 2 to 3 is not in the dump (the lever: unknown)" or "Teleport was not answered", true
end
local function kingSays(ctx, want, command)
  local sent, stage = talk(ctx, "Sealed King", "RaceV4Progress", "Check")          -- SealedKing.luau:9
  if not sent then return false, stage end
  if stage ~= want then return false, "the Sealed King is at stage " .. tostring(stage) .. " (" .. want .. " was wanted)" end
  local ok, said = BF.invoke(8, "RaceV4Progress", command)                          -- SealedKing.luau:31 ("Begin") / :51 ("Continue")
  BF.say("Sealed King: " .. command .. " -> " .. tostring(said))
  return ok, command .. " was not answered"
end
CHAINS[3] = { id = "v4", switch = "bloxfruits.raceV4", title = "Race V4", sea = 3,
  complete = function() return v4() == 5 end,
  steps = {
    inSea(3),
    { name = "Not Draco (Draco has its own path)", tries = 1,
      done = function() return race() ~= "Draco" end,
      act = function() return false, "the Ancient One says Draco \"treads a different path\": use the Draco chain", true end },   -- RaceV4Upgrader.luau:140-142
    { name = "Wake the Sealed King", tries = 1, done = atLeast(1),
      -- (stage 0 -> 1 is "memory fragments from defeating that monster", SealedKing.luau:17: which monster is not in the dump)
      act = function() return false, "stage 0: the monster that wakes the Sealed King is not named in the dump", true end },
    { name = "Sealed King: begin", tries = 3, done = atLeast(2), act = function(ctx) return kingSays(ctx, 1, "Begin") end },
    { name = "Into the Temple of Time", tries = 1, cap = 2, done = atLeast(3), act = enterTemple },
    { name = "Sealed King: continue", tries = 3, done = atLeast(4), act = function(ctx) return kingSays(ctx, 3, "Continue") end },
    { name = "The trial under a full moon", tries = 1, done = atLeast(5),
      act = function()
        local phase = moonPhase()
        if phase == 5 then return false, "full moon now: the mirror and the trial of your race are yours to play (not automated)", true end
        return false, "the trial waits for a full moon (moon phase " .. tostring(phase) .. " of 5)", true
      end },
  } }

-- ---------------------------------------------------------------- 4. Race V4 training: the Ancient One (Third Sea)
local UPGRADE = {
  [0] = "ready for the next trial", [1] = "awakened: train first", [2] = "a gear for sale", [3] = "train more", [4] = "a limit upgrade for sale",
  [5] = "all done", [6] = "training sessions before the next trial", [7] = "the next upgrade for sale", [8] = "trials mastered: more sessions",
  [9] = "Draco: a different path",
}
local function ancientOne(ctx, memo)
  local sent, state = talk(ctx, "Ancient One", "UpgradeRace", "Check")              -- RaceV4Upgrader.luau:12
  if not sent then return false, state end
  local _, upgrades, price = ask("UpgradeRace", "Check")
  if state == 5 or state == 0 then memo.trained = true; return true end
  if inList(state, 2, 4, 7) then
    if O.raceSpendFrags ~= true then return false, string.format("%s for %s Fragments: tick \"May spend Fragments\"", UPGRADE[state], tostring(price)), true end
    if tonumber(price) and frags() < tonumber(price) then return false, string.format("%s costs %s Fragments (you have %d)", UPGRADE[state], tostring(price), frags()), true end
    local ok, bought = BF.invoke(8, "UpgradeRace", "Buy")                           -- RaceV4Upgrader.luau:37 / :73 / :113 ("Buy")
    BF.say("Ancient One: Buy -> " .. tostring(bought))
    fresh()
    if ok and bought then ctx:progress(); return true end
    return false, "\"You don't have enough.\" (" .. tostring(bought) .. ")", true
  end
  -- (1 / 3 / 6 / 8: "Come back when you've trained more" = fill the race energy in fights; not this hub's)
  return false, string.format("%s (%s, upgrades %s): training is not automated", UPGRADE[state] or "not yet great", tostring(state), tostring(upgrades)), true
end
CHAINS[4] = { id = "v4train", switch = "bloxfruits.raceTrain", title = "V4 training", sea = 3,
  complete = function(memo) return memo.trained == true end,
  steps = {
    inSea(3),
    { name = "Not Draco", tries = 1, done = function() return race() ~= "Draco" end,
      act = function() return false, "Draco trains in the Dojo's hidden room (DialoguesList.luau:5455): not automated", true end },
    { name = "Awakened (the Awakening tool)", tries = 1, done = awakened,
      act = function() return false, "no Awakening tool: the race is not awakened yet", true end },
    { name = "Transformed (the Ancient One talks only then)", tries = 1, done = transformedChild,
      act = function() return false, "transform first (the V4 key, when the energy is full): not automated", true end },
    { name = "Ancient One: buy what is for sale", tries = 2, cap = 10, done = function(memo) return memo.trained == true end, act = ancientOne },
  } }

-- ---------------------------------------------------------------- 5. Draco: the Dojo, the Dragon Wizard (Third Sea)
local function dojo(ctx, memo)
  local sent, answer = netTalk(ctx, "Dojo Trainer", { NPC = "Dojo Trainer", Command = "RequestQuest" })   -- DojoTrainer.luau:15
  if not sent then return false, answer end
  if type(answer) ~= "table" then
    return false, "\"come back once you become proficient with Dragon Talon\" (Uzoth teaches it: not automated)", true   -- DojoTrainer.luau:81
  end
  if answer.Completed then memo.dojo = true; return true end
  if answer.Timeout then return false, "\"That's enough training for today\": come back tomorrow", true end          -- DojoTrainer.luau:72
  local q = answer.Quest
  if type(q) ~= "table" then return false, "the Dojo Trainer gave no quest", true end
  if tonumber(q.Goal) and tonumber(q.Progress) and tonumber(q.Goal) <= tonumber(q.Progress) then
    local ok, claimed = netCall(8, "InteractDragonQuest", { NPC = "Dojo Trainer", Command = "ClaimQuest" })           -- DojoTrainer.luau:53
    BF.say("Dojo Trainer: " .. tostring(q.BeltName) .. " belt claimed -> " .. tostring(claimed))
    table.clear(netCache)
    if ok and claimed then ctx:progress(); return true end
    return false, "the claim was refused (" .. tostring(claimed) .. ")"
  end
  -- (the belt's task is the server's: "Today's teaching focuses on <QuestName>", DojoTrainer.luau:41)
  return false, string.format("%s belt: %s (%s / %s): belt tasks are not automated", tostring(q.BeltName), tostring(q.QuestName or q.Description),
    tostring(q.Progress), tostring(q.Goal)), true
end
local function tether(ctx)
  local w = wizard()
  if w and w.TetherLearned then return true end
  if not (w and w.CanLearnTether) then return false, "the Dragon Wizard does not teach Dragon Tether yet (the Dojo first)", true end
  local sent, ok = netTalk(ctx, "Dragon Wizard", { NPC = "Dragon Wizard", Command = "LearnTether" })                  -- DragonWizard.luau:229
  table.clear(netCache)
  if sent and ok then ctx:progress(); return true end
  return false, "LearnTether was refused (" .. tostring(ok) .. ")"
end
-- Prehistoric Island eggs carry the tag "PrehistoricIslandDragonEgg"; their prompt is kept only for a participant
-- (Controllers/PrehistoricIslandClient.luau:30-59).
local function egg(ctx)
  if not B.LP:GetAttribute("PrehistoricIslandParticipant") then
    return false, "no Prehistoric Island run of yours is on (its defence is not automated)", true
  end
  local root = BF.root()
  local best, gap
  for _, item in ipairs(CollectionService:GetTagged("PrehistoricIslandDragonEgg")) do
    local ok, pivot = pcall(item.GetPivot, item)
    if ok and root and item:IsDescendantOf(workspace) then
      local d = (pivot.Position - root.Position).Magnitude
      if not gap or d < gap then best, gap = item, d end
    end
  end
  if not best then return false, "no Dragon Egg on the island now" end
  local prompt = best:FindFirstChildWhichIsA("ProximityPrompt", true)              -- PrehistoricIslandClient.luau:55
  if not prompt then return false, "the egg has no prompt for you" end
  local ok, why = BF.fly(best:GetPivot().Position + Vector3.new(0, 3, 0), ctx, { note = "To a Dragon Egg" })
  if not ok then return false, "the egg: " .. tostring(why) end
  if not holdPrompt(ctx, prompt) then return false, "no way to press a key in this executor", true end
  ctx:sleep(1.5, "Taking the egg")
  if tool("Dragon Egg") then ctx:progress(); return true end                        -- a Tool "Dragon Egg": Economy/ItemId/RawSource.luau:1280
  return false, "no Dragon Egg came"
end
local function swap(ctx)
  if O.raceSwap ~= true then return false, "the Wizard can make you Draco: tick \"May change my race\"", true end
  local w = wizard()
  if not (w and w.CanTransform) then return false, "the Wizard cannot change your race now", true end
  local sent, ok = netTalk(ctx, "Dragon Wizard", { NPC = "Dragon Wizard", Command = "DragonRace" })                   -- DragonWizard.luau:40 / :62
  BF.say("Dragon Wizard: DragonRace -> " .. tostring(ok))
  table.clear(netCache)
  if sent and ok then ctx:progress(); return true end
  return false, "the race change was refused (" .. tostring(ok) .. ")"
end
local ASCEND = { V2TurnInReady = "1,000,000", V3TurnInReady = "3,000,000" }                                          -- DragonWizard.luau:141, :213
local function ascension(ctx, memo)
  local w = wizard()
  if not w then return false, "the Dragon Wizard did not answer" end
  local v = w.AvailableVQuest
  if v == "V2" or v == "V3" then
    local sent, ok = netTalk(ctx, "Dragon Wizard", { NPC = "Dragon Wizard", Action = "Begin", Command = "Ascension" }) -- DragonWizard.luau:93 / :161
    table.clear(netCache)
    return sent and ok, "Begin was refused (" .. tostring(ok) .. ")"
  end
  if ASCEND[v] then
    if O.raceSpendBeli ~= true then return false, "the Wizard wants $" .. ASCEND[v] .. ": tick \"May spend Beli\"", true end
    local sent, ok = netTalk(ctx, "Dragon Wizard", { NPC = "Dragon Wizard", Action = "Complete", Command = "Ascension" }) -- DragonWizard.luau:118 / :190
    table.clear(netCache)
    if sent and ok then ctx:progress(); return true end
    return false, "\"You don't have enough money.\"", true
  end
  if v == "V2InProgress" then return false, "five Fire Flowers wanted: not automated", true end                      -- DragonWizard.luau:145
  if v == "V3InProgress" then return false, "a Terrorshark to defeat: not automated", true end                         -- DragonWizard.luau:176
  if v == "V3CantStart" then return false, "\"Come back when you're a little stronger.\"", true end                    -- DragonWizard.luau:147
  memo.ascended = true
  return true
end
CHAINS[5] = { id = "draco", switch = "bloxfruits.raceDraco", title = "Draco", sea = 3,
  complete = function(memo) return race() == "Draco" and memo.ascended == true end,
  steps = {
    inSea(3),
    { name = "Dojo Trainer: the belts", tries = 2, cap = 12,
      done = function(memo) return memo.dojo == true or race() == "Draco" or (wizard() or {}).TetherLearned == true end, act = dojo },
    { name = "Dragon Wizard: Dragon Tether", tries = 2,
      done = function() return race() == "Draco" or (wizard() or {}).TetherLearned == true end, act = tether },
    { name = "A Dragon Egg", tries = 3, rest = 5, cap = 20,
      done = function() return race() == "Draco" or tool("Dragon Egg") ~= nil or (wizard() or {}).CanTransform == true end, act = egg },
    { name = "Dragon Wizard: become Draco", tries = 2, done = function() return race() == "Draco" end, act = swap },
    { name = "Dragon Wizard: ascension", tries = 2, cap = 6, done = function(memo) return memo.ascended == true end, act = ascension },
  } }

-- ============================================================================ the runner (a copy of bloxfruits_quest.lua's)
for _, chain in ipairs(CHAINS) do
  chain.line, chain.memo, chain.state = "Off.", {}, {}
end
local function reset(chain) chain.memo, chain.state, chain.unknown = {}, {}, 0 end
local function stopChain(chain, text, failed)
  chain.line = text
  BF.say(chain.title .. ": " .. text)
  if failed then Window.toast({ title = chain.title, text = text, icon = "crown", time = 8 }) end
  reset(chain)
  Config.set(chain.switch, false)
end
local function activeChain()
  for _, chain in ipairs(CHAINS) do
    if Config.get(chain.switch) == true then return chain end
  end
  return nil
end
-- the first step not done: index, step; nil when all are; "unknown" when the game did not answer
local function firstOpen(chain)
  for index, step in ipairs(chain.steps) do
    local ok, done = pcall(step.done, chain.memo)
    if not ok or done == nil then return "unknown", index, step end
    if not done then return index, step end
  end
  return nil
end
local function stopAt(chain, index, step, why)
  stopChain(chain, string.format("stopped at step %d of %d (%s): %s", index, #chain.steps, step.name, tostring(why)), true)
end
local function round(ctx, chain)
  freshAll()
  local okDone, isDone = pcall(chain.complete, chain.memo)
  if okDone and isDone then stopChain(chain, "done."); ctx:progress(); return end
  local index, step, asked = firstOpen(chain)
  if index == "unknown" then
    chain.unknown = (chain.unknown or 0) + 1
    if chain.unknown >= 5 then stopAt(chain, step, asked, "the game does not answer its check") else ctx:sleep(3, chain.title .. ": the game did not answer") end
    return
  end
  chain.unknown = 0
  if not index then stopChain(chain, "done."); ctx:progress(); return end
  local state = chain.state[index] or { fails = 0, acts = 0 }
  chain.state[index] = state
  chain.line = string.format("step %d of %d: %s", index, #chain.steps, step.name)
  ctx:beat(chain.title .. ": " .. step.name)
  if state.acts >= (step.cap or 12) then
    stopAt(chain, index, step, string.format("%d tries without it done (%s)", state.acts, tostring(state.why or "no reason given")))
    return
  end
  state.acts += 1
  local ok, okAct, why, final = pcall(step.act, ctx, chain.memo)
  if ctx.stop then return end
  if ok and okAct then state.fails = 0; ctx:progress(); return end
  why = ok and why or ("it broke: " .. string.sub(tostring(okAct), 1, 100))
  state.fails += 1
  state.why = why
  if (ok and final) or state.fails >= (step.tries or 3) then
    stopAt(chain, index, step, why)
  else
    BF.say(string.format("%s, %s: %s (try %d of %d)", chain.title, step.name, tostring(why), state.fails, step.tries or 3))
    BF.release()
    ctx:sleep(step.rest or 3, chain.title .. ": resting after a failed try")
  end
end
local function run(ctx)
  while B.alive and not ctx.stop do
    if not ctx:body(40) then return end
    local chain = activeChain()
    if not chain then return end
    round(ctx, chain)
    task.wait(0.2)
  end
end
local function wanted(first) return activeChain() ~= nil and (O.raceFirst == true) == first end

-- ============================================================================ the race skill
-- The skill key is T: RaceAbility.luau:41/45 binds it with ContextActionService, and its handler fires
-- CommE "ActivateAbility" (:39) only while the humanoid lives (:36). The server answers Events.UsedRaceSkill, after which the
-- game shows a 30 s cooldown (Controllers/UI/MobileUIController.luau:20, :1013-1020). So the key is pressed, never the remote.
local RA = { pressed = 0, taken = 0, misses = 0, readyAt = 0, last = "Off." }
local function hookSkill()
  if RA.hooked then return end
  local events = S.ReplicatedStorage:FindFirstChild("Events")
  local used = events and events:FindFirstChild("UsedRaceSkill")
  if not (used and used:IsA("RemoteEvent")) then return end
  RA.hooked = true
  B.connect(used.OnClientEvent, function()
    RA.taken += 1
    RA.misses = 0
    RA.readyAt = now() + 30
    RA.last = string.format("Race skill used (%d of %d presses)", RA.taken, RA.pressed)
  end, "bloxfruits.raceSkillUsed")
end
local function skillTick()
  if O.raceAbility ~= true then RA.last = "Off."; return end
  hookSkill()
  local t = now()
  if t < RA.readyAt or not BF.running() or not BF.alive() then return end
  local target = BF.target
  if not (target and BF.targetAt and t - BF.targetAt < 1.5 and BF.living(target)) then return end
  local skill = skillTool()
  if not skill then RA.last = "No race skill in the backpack (it comes with V3)."; return end
  if BF.casting and BF.casting > t then return end
  local pressedAt = t
  RA.readyAt = t + 4
  task.spawn(function()
    if not press("T", true) then RA.last = "No way to press a key in this executor."; return end
    task.wait(0.1)
    press("T", false)
    RA.pressed += 1
    task.wait(3)
    if RA.readyAt - 30 < pressedAt then
      -- (no UsedRaceSkill since the press: not taken; waited longer, and after five the switch goes off)
      RA.misses += 1
      RA.readyAt = now() + 15
      RA.last = string.format("%s pressed, no answer (%d in a row)", skill, RA.misses)
      if RA.misses >= 5 then
        BF.say("Race skill: five presses with no answer, switched off")
        Config.set("bloxfruits.raceAbility", false)
        RA.misses = 0
      end
    end
  end)
end

local function start()
  -- (two jobs, one runner: just under the level farm, or just over it when "before levelling" is ticked)
  BF.job({ id = "raceChain", label = "Race chain", priority = 47, quiet = 30, patience = 360, want = function() return wanted(false) end, run = run })
  BF.job({ id = "raceChainFirst", label = "Race chain", priority = 53, quiet = 30, patience = 360, want = function() return wanted(true) end, run = run })
  -- ("Stop everything" and Panic stop the race chains too: their switches are not a job's own)
  if BF.offToo then
    for _, chain in ipairs(CHAINS) do BF.offToo[#BF.offToo + 1] = chain.switch end
  end
  for _, chain in ipairs(CHAINS) do
    if type(Config.on) == "function" then
      Config.on(chain.switch, function()
        if Config.get(chain.switch) == true then
          reset(chain)
          chain.line = "Starting."
        elseif chain.line == "Starting." or string.sub(chain.line, 1, 5) == "step " then
          chain.line = "Off."
        end
      end)
    end
  end
  Motion.every(function() B.try("bloxfruits.raceSkill", skillTick) end, 4, "bloxfruits.raceSkill")
end

-- ============================================================================ the cards (read only)
local ALCH = { [-2] = "done", [-1] = "flowers in, short of $500,000", [0] = "not begun", [1] = "looking for the 3 flowers", [2] = "flowers in, $500,000 to pay",
  [5] = "\"What are you?\"" }
local AROWE = { [-2] = "done", [-1] = "task done, short of $2,000,000", [0] = "not begun", [1] = "task running", [2] = "task done, $2,000,000 to pay",
  [5] = "\"What are you?\"" }
local STAGE = { [0] = "the Sealed King sleeps", [1] = "the Sealed King has words (Begin)", [2] = "to the Great Tree / the Temple of Time",
  [3] = "the Sealed King has words (Continue)", [4] = "a trial under a full moon", [5] = "at the Temple of Time" }
local function said(map, value)
  if value == nil then return "no answer" end
  return (map[value] or "not ready") .. " (" .. tostring(value) .. ")"
end
local function raceLines()
  freshAll()
  local a, w, s = alchemist(), arowe(), v4()
  local skill = skillTool()
  local seen = awakened() and "V4" or (skill or w == -2) and "V3" or a == -2 and "V2" or (a ~= nil and "V1") or "?"
  return {
    string.format("Race: %s  ·  stage %s  ·  rerolls %s", raceShown(), seen, tostring(rerolls() or "?")),
    "Values: " .. raceValues() .. "  ·  skill " .. tostring(skill or "none"),
    "V2, the Alchemist: " .. said(ALCH, a),
    "V3, arowe: " .. said(AROWE, w),
    "V4, the Sealed King: " .. said(STAGE, s),
  }
end
local function v4Lines()
  freshAll()
  local draco = race() == "Draco"
  local state, upgrades, price = upgrade(draco)
  local c = clock()
  local d = c and type(c.RaceDetails) == "table" and c.RaceDetails or nil
  local gears = d and type(d.Gears) == "table" and table.concat(d.Gears, " ") or "?"
  return {
    "Stage: " .. said(STAGE, v4()),
    string.format("%s: %s  ·  upgrades %s  ·  price %s", draco and "Red Essence" or "Ancient One", state == nil and "no answer" or (UPGRADE[state] or "not yet great")
      .. " (" .. tostring(state) .. ")", tostring(upgrades), tostring(price)),
    c and string.format("Temple clock: race level %s, point %s, gears %s, A %s B %s C %s", tostring(c.RaceLevel), tostring(c.HadPoint), gears,
      tostring(d and d.A), tostring(d and d.B), tostring(d and d.C)) or "Temple clock: no answer",
    string.format("Moon %s of 5  ·  energy %s  ·  transformed %s  ·  Awakening %s", tostring(moonPhase()), tostring(charValue("RaceEnergy")),
      tostring(charValue("RaceTransformed")), awakened() and "yes" or "no"),
  }
end
local function dracoLines()
  freshAll()
  local w = wizard()
  local hunter = netAsk("DragonHunter", { Context = "Check" })                     -- DialoguesList/NPCs/DragonHunter.luau:82
  local state, upgrades = upgrade(true)
  local function yes(v) return v and "yes" or "no" end
  return {
    w and string.format("Wizard: tether %s, can learn %s, can become Draco %s, ascension %s", yes(w.TetherLearned), yes(w.CanLearnTether), yes(w.CanTransform),
      tostring(w.AvailableVQuest or "none")) or "Wizard: no answer",
    "Dragon Hunter: " .. (hunter == nil and "no answer" or hunter == "Locked" and "locked (the Dojo first)" or "open"),
    string.format("Red Essence: %s (%s), upgrades %s", state == nil and "no answer" or (UPGRADE[state] or "not yet great"), tostring(state), tostring(upgrades)),
    string.format("Dragon Egg %s  ·  Prehistoric run %s", tool("Dragon Egg") and "held" or "none", yes(B.LP:GetAttribute("PrehistoricIslandParticipant"))),
  }
end
local function card(page, spec)
  local s = page:section({ title = spec.title, icon = spec.icon, column = spec.column, desc = "What the server says. Reads only." })
  local rows = {}
  for i = 1, spec.rows do rows[i] = s:note({ icon = spec.icon, text = i == 1 and "Press Ask." or "" }) end
  local asking = false
  s:button({ id = spec.id, label = "Ask the game", desc = spec.desc, text = "Ask", run = function()
    if asking then return end
    asking = true
    task.spawn(function()
      B.try(spec.id, function()
        local lines = spec.lines()
        for i, row in ipairs(rows) do row.set(lines[i] or "") end
      end)
      asking = false
    end)
  end })
end

-- ============================================================================ the tab
local DESCS = {
  v2 = "The Alchemist's flowers, then $500,000. Second Sea.",
  v3 = "arowe's task for your race, then $2,000,000. Second Sea.",
  v4 = "Sealed King, Temple of Time, up to the full-moon trial.",
  v4train = "Buys the Ancient One's upgrades when you are transformed.",
  draco = "Dojo belts, Dragon Tether, an egg, the swap, ascension.",
}
local function raceTab(page)
  card(page, { title = "Race", icon = "crown", rows = 5, id = "bloxfruits.raceCard", desc = "Five checks, nothing changed.", lines = raceLines })
  local s = page:section({ title = "Race chains", icon = "flag", column = 2, desc = "One chain at a time. Each step is asked of the game." })
  local notes = {}
  for _, chain in ipairs(CHAINS) do
    s:toggle({ id = chain.switch, label = chain.title, desc = DESCS[chain.id], default = false, bindable = false })
    notes[chain.id] = s:note({ icon = "crown", text = chain.line })
  end
  local how = page:section({ title = "Rules", icon = "shield", column = 2 })
  how:toggle({ id = "bloxfruits.raceFirst", label = "Before levelling", desc = "Race chains get the body before Auto level.", default = false, bindable = false })
  how:toggle({ id = "bloxfruits.raceSpendBeli", label = "May spend Beli", desc = "Alchemist, arowe and the Wizard's prices.", default = false, bindable = false })
  how:toggle({ id = "bloxfruits.raceSpendFrags", label = "May spend Fragments", desc = "The Ancient One's upgrades.", default = false, bindable = false })
  how:toggle({ id = "bloxfruits.raceSwap", label = "May change my race to Draco", desc = "Only the Draco chain uses it.", default = false, bindable = false })
  how:slider({ id = "bloxfruits.raceDeaths", label = "Give up after deaths in a row", tip = "That foe is then left alone 30 min.", min = 1, max = 10, step = 1,
    default = 3 })
  card(page, { title = "Race V4", icon = "moon", rows = 4, id = "bloxfruits.raceV4Card", desc = "Stage, upgrades, temple clock, moon.", lines = v4Lines })
  card(page, { title = "Draco", icon = "flame", rows = 4, column = 2, id = "bloxfruits.raceDracoCard", desc = "Wizard, Hunter, Red Essence, egg.", lines = dracoLines })
  local skill = page:section({ title = "Race skill", icon = "zap" })
  skill:toggle({ id = "bloxfruits.raceAbility", label = "Auto race ability", desc = "Presses T while a job fights, when it is ready.", default = false, bindable = false })
  local skillLine = skill:note({ icon = "activity", text = RA.last })
  skill:note({ icon = "info", text = "Not automated: trials, the lever, the Mirage gear, the mirror, Sea Beasts, players." })
  Motion.every(function()
    if not Window.anyOpen() then return end
    for _, chain in ipairs(CHAINS) do
      local note = notes[chain.id]
      if note and note.frame.Parent then note.set(chain.line) end
    end
    if skillLine.frame.Parent then skillLine.set(RA.last) end
  end, 2, "bloxfruits.raceLines")
end

BF.parts[#BF.parts + 1] = { id = "race", start = start, race = raceTab,
  defaults = { raceV2 = false, raceV3 = false, raceV4 = false, raceTrain = false, raceDraco = false, raceFirst = false, raceSpendBeli = false,
    raceSpendFrags = false, raceSwap = false, raceDeaths = 3, raceAbility = false } }
end
do -- bloxfruits_raid.lua
-- ============================================================================
--  Blox Fruits     raids: the chip, the islands, the awakening, the dungeon
--
--  Read from the game's own code (dump 2753915549 v4630, `fast\` folder: a
--  First Sea place, but ReplicatedStorage carries every sea's dialogue and
--  modules). NEVER RUN LIVE: every line below is unproven until measured.
--
--   * The raids: ReplicatedStorage.Raids lists them (Raids.luau:2-6): nine
--     normal, two advanced (Phoenix, Dough).
--   * The chip: CommF_ "RaidsNpc", "Check" -> 0 (under level 1100) or a map of
--     the advanced raids unlocked (MysteriousScientist.luau:215-228);
--     "RaidsNpc", "Select", name -> 1 bought, 0 level 1100, or the server's
--     own sentence (MysteriousScientist.luau:52-70). The scientist's text says
--     a normal chip is $100,000, an advanced one 1,000 Fragments, once every
--     2 hours, OR a physical fruit traded (MysteriousScientist.luau:40): which
--     the server takes is not in the client, so nothing is bought while a
--     physical fruit is carried. The chip is the tool "Special Microchip"
--     (IdMap/GeneratedSource.luau:979).
--   * The raid's state: Remotes.Raids sends "StartTimer"(seconds, startedAt)
--     and "Finished" (Main/UIController.luau:3062-3084); while raiding, the
--     player carries the attribute "IslandRaiding" (Effect/Receiver.luau:48-49,
--     RockGenerator.luau:641). The raid map is workspace.Map.RaidMap, past
--     X 20000 (Fling and Underwater Glitching Fix.luau:14, 56).
--   * NOT in the client: the start button (a server part; no client code
--     sends anything for it) and the raid's islands (no client code reads
--     them). Both below come from public scripts (research/scripts.md 2.8),
--     marked LEAD, and are used only as said.
--   * Awakening: CommF_ "Awakener", "Check" -> 0 (not in its room), 1 (this
--     fruit cannot), { Key, Cost } (the next skill and its Fragments), or
--     nothing left; "Awakener", "Awaken" -> 1 done, 0 not enough Fragments;
--     "Awakener", "Teleport" -> 1 (back out) (MysteriousEntity.luau:28-93).
--     The skill is the server's pick: no call names one.
--   * Dungeon: Net "DungeonNPCNetworkFunction" ("TeleportToDungeonHub", false /
--     "GetDungeonEnergy" / "TeleportBack") (NPCCallbacks.luau:6-106), DataRemote
--     "GetData" (ReplicatedPlayerData.luau:16), the run's folder found from the
--     player's "ExplorerGUID" (DungeonClient.luau:26-65).
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion = B.S, B.Config, B.Window, B.Motion
local BF = B.BloxFruits
local O = BF.O
local function now() return os.clock() end

local RAID = { timerOn = false, endsAt = nil, finishedAt = nil, done = 0, frags = 0, streak = 0, last = "Not asked yet.", answer = "",
  unlocked = {}, levelOk = nil, restUntil = 0, buyAgainAt = 0, awaken = "Not asked yet.", unlock = "Not asked yet.", dungeon = "Not asked yet." }
BF.raid = RAID

-- ---------------------------------------------------------------- calls
-- A Net remote of the game's, through its own module, after checking it is there (Net's `get` waits up to 99 s for one that is not:
-- Modules/Net.luau:219). Same pattern as bloxfruits_loot.lua.
local remotes = {}
local function netRF(name)
  local got = remotes[name]
  if got then return got end
  local modules = S.ReplicatedStorage:FindFirstChild("Modules")
  local folder = modules and modules:FindFirstChild("Net")
  if not (folder and folder:FindFirstChild("RF/" .. name)) then return nil end
  local net = BF.mod("Modules", "Net")
  if not net then return nil end
  local ok, remote = BF.game(net.RemoteFunction, net, name)      -- Modules/Net.luau:252 (Net:RemoteFunction(name))
  if not ok or remote == nil then return nil end
  remotes[name] = remote
  return remote
end
-- A call into game code that may wait on the server, with an end to the wait. -> ok, results...
local function gameAsk(timeout, fn, ...)
  local args = table.pack(...)
  local done, out = false, nil
  BF.count.calls += 1
  task.spawn(function()
    out = table.pack(BF.game(fn, table.unpack(args, 1, args.n)))
    done = true
  end)
  local started = now()
  while not done and now() - started < (timeout or 6) do task.wait() end
  if not done then return false, "timeout" end
  return table.unpack(out, 1, out.n)
end
-- what a dialogue-style answer says: a sentence, a number, or a dialogue table's first line
local function said(answer)
  if type(answer) == "table" and type(answer.Text) == "table" then return tostring(answer.Text[1]) end
  if answer == nil then return "no answer" end
  return tostring(answer)
end

-- ---------------------------------------------------------------- what is held
local function tools()
  local list = {}
  for _, from in ipairs({ B.LP:FindFirstChild("Backpack"), BF.char() }) do
    for _, tool in ipairs(from and from:GetChildren() or {}) do
      if tool:IsA("Tool") then list[#list + 1] = tool end
    end
  end
  return list
end
local function holding(name)
  for _, tool in ipairs(tools()) do
    if tool.Name == name then return tool end
  end
  return nil
end
-- the raid chip (IdMap/GeneratedSource.luau:979; "Microchip" without "Special" is another raid's chip and is not counted)
local function chipHeld() return holding("Special Microchip") end
-- A physical fruit carried (it can be eaten: the engine's own test). The scientist may take one in trade for a chip
-- (MysteriousScientist.luau:40): while one is carried, no chip is bought.
local function fruitCarried()
  for _, tool in ipairs(tools()) do
    if tool:FindFirstChild("EatRemote") then return tool end
  end
  return nil
end

-- ---------------------------------------------------------------- the raid's state
local function raiding()
  local mark = B.LP:GetAttribute("IslandRaiding")          -- Effect/Receiver.luau:48 (set while raiding; compared between players)
  return (mark ~= nil and mark ~= false) or RAID.timerOn
end
local function timeLeft()
  if not (RAID.timerOn and RAID.endsAt) then return nil end
  return math.max(0, RAID.endsAt - now())
end
-- the raids, as the game lists them: { name, advanced }
local function raidList()
  local mod = BF.mod("Raids")                               -- Raids.luau:2-6 (raids, advancedRaids)
  local out = {}
  if type(mod) == "table" then
    for _, name in ipairs(type(mod.raids) == "table" and mod.raids or {}) do out[#out + 1] = { tostring(name), false } end
    for _, name in ipairs(type(mod.advancedRaids) == "table" and mod.advancedRaids or {}) do out[#out + 1] = { tostring(name), true } end
  end
  return out
end
local function isAdvanced(name)
  for _, row in ipairs(raidList()) do
    if row[1] == name then return row[2] end
  end
  return false
end
-- MysteriousScientist.luau:215  CommF_:InvokeServer("RaidsNpc", "Check") -> 0 (under level 1100) or truthy, and a map { [advanced raid] = unlocked }
local function raidCheck()
  local ok, status, map = BF.invoke(8, "RaidsNpc", "Check")
  if not ok then RAID.last = "No answer: " .. tostring(status); return nil end
  RAID.levelOk = status ~= 0 and status ~= nil and status ~= false
  RAID.unlocked = type(map) == "table" and map or {}
  return RAID.levelOk
end

-- ---------------------------------------------------------------- the chip
-- What one chip costs, from the scientist's own text (MysteriousScientist.luau:40): read, never measured.
local function price(advanced)
  if advanced then return "Fragments", 1000, O.raidKeepFrags or 0 end
  return "Beli", 100000, O.raidKeepBeli or 0
end
-- Why a chip cannot be bought now (nil = it can). Spends nothing unless "Buy the chip" is ticked.
local function cannotBuy(name)
  if O.raidBuy ~= true then return "buying is off" end
  if now() < RAID.buyAgainAt then return "the last purchase was refused, waiting" end
  if fruitCarried() then return "a physical fruit is carried (the scientist may take it): store it first" end
  local advanced = isAdvanced(name)
  if advanced and RAID.unlocked[name] == false then return name .. " is not unlocked" end
  local money, cost, keep = price(advanced)
  local have = tonumber(BF.data(money)) or 0
  if have < cost + keep then return string.format("%d %s, the chip costs %d and %d are kept", have, money, cost, keep) end
  return nil
end
local function buyChip(name)
  local why = cannotBuy(name)
  if why then RAID.last = "No chip bought: " .. why; return false end
  -- MysteriousScientist.luau:52  CommF_:InvokeServer("RaidsNpc", "Select", raidName) -> 1 bought, 0 level 1100, or a sentence
  local ok, answer = BF.invoke(8, "RaidsNpc", "Select", name)
  RAID.answer = ok and (answer == 1 and "Chip bought." or (answer == 0 and "You must be level 1100." or said(answer))) or ("No answer: " .. tostring(answer))
  RAID.last = name .. ": " .. RAID.answer
  BF.say("Raid chip: " .. RAID.last)
  if ok and answer == 1 then return true end
  -- (refused: the server's sentence is shown; asked again after 10 min, never in a loop)
  RAID.buyAgainAt = now() + 600
  return false
end

-- ---------------------------------------------------------------- the start button (LEAD, not in the client)
-- Public scripts press a ClickDetector under a model named RaidSummon2 / RaidSummon (research/scripts.md 2.8). Only that name is looked for,
-- only when "Press the start button" is ticked, and only with the executor's own fireclickdetector. Else the player presses it.
local button
local function findButton()
  if button and button.Parent then return button end
  local map = workspace:FindFirstChild("Map")
  for _, name in ipairs({ "RaidSummon2", "RaidSummon" }) do
    local model = map and map:FindFirstChild(name, true)
    local click = model and model:FindFirstChildWhichIsA("ClickDetector", true)
    if click and click.Parent and click.Parent:IsA("BasePart") then
      button = click
      return click
    end
  end
  return nil
end
local function pressStart(ctx)
  if O.raidPress ~= true then return false, "press the raid button by hand" end
  if type(fireclickdetector) ~= "function" then return false, "this executor cannot press it: press it by hand" end
  local click = findButton()
  if not click then return false, "no start button found here: press it by hand" end
  local part = click.Parent
  local ok, why = BF.fly(part.Position + Vector3.new(0, 4, 0), ctx, { note = "To the raid button" })
  if not ok then return false, "could not reach the button: " .. tostring(why) end
  local pressed = pcall(fireclickdetector, click)
  return pressed, pressed and "pressed" or "the press failed"
end

-- ---------------------------------------------------------------- inside a raid
-- The newest raid island (LEAD: public scripts read _WorldOrigin.Locations children named "Island 1".."Island 5"; no client code does).
local function newestIsland(from)
  local origin = workspace:FindFirstChild("_WorldOrigin")
  local folder = origin and origin:FindFirstChild("Locations")
  local best, bestN
  for _, child in ipairs(folder and folder:GetChildren() or {}) do
    local n = tonumber(string.match(child.Name, "^Island (%d+)$"))
    if n and child:IsA("BasePart") and (child.Position - from).Magnitude < 5000 and (not bestN or n > bestN) then best, bestN = child, n end
  end
  return best and best.Position, bestN
end
-- the living mobs within the kill aura, nearest first
local function inAura(from)
  local out, radius = {}, O.raidAura or 300
  for _, mob in ipairs(BF.mobs(nil, from)) do
    if (mob.HumanoidRootPart.Position - from).Magnitude <= radius then out[#out + 1] = mob end
  end
  return out
end
-- deaths are counted by the engine each time the body comes back (Ctx:body): three in a row in one raid end it
local function deathsHit(state)
  local deaths = BF.count.deaths
  if deaths > state.deaths then
    RAID.streak += deaths - state.deaths
    state.deaths = deaths
    BF.say(string.format("Died in the raid (%d in a row)", RAID.streak))
  end
  return RAID.streak >= 3
end
-- One round of clearing: fight what is near, else go to the newest island, else look further. -> nil, or why it ends
local function clearStep(ctx, state)
  local root = BF.root()
  if not root then return nil end
  local near = inAura(root.Position)
  if #near > 0 then
    local result = BF.fight(near[1], ctx, function()
      local mine = BF.root()
      return mine and inAura(mine.Position) or {}
    end)
    if result == "stopped" then return "stopped" end
    if result == "died" then ctx:body(40) end
    return nil
  end
  local island, n = newestIsland(root.Position)
  if n and n ~= state.island then
    -- (a new island: the death streak counts only deaths on one island after another without progress)
    state.island, RAID.streak = n, 0
    BF.say("Raid island " .. n)
  end
  local goal = island and (island + Vector3.new(0, O.raidHeight or 30, 0))
  if not goal then
    -- (no island known: the nearest mob of the raid map, within 3000)
    local far = BF.mobs(nil, root.Position)[1]
    if far and (far.HumanoidRootPart.Position - root.Position).Magnitude < 3000 then goal = far.HumanoidRootPart.Position + Vector3.new(0, O.raidHeight or 30, 0) end
  end
  if goal and (goal - root.Position).Magnitude > 8 then
    local ok, why = BF.fly(goal, ctx, { note = "Over the raid island" })
    if not ok and why == "stopped" then return "stopped" end
  else
    if goal then BF.holdAt(goal) end
    ctx:sleep(0.5, "Waiting for the next island")
  end
  return nil
end
local function clearRaid(ctx)
  local state = { deaths = BF.count.deaths, island = nil }
  RAID.streak = 0
  local lostSince
  while B.alive and not ctx.stop do
    if not ctx:body(40) then return "stopped" end
    if deathsHit(state) then return "deaths" end
    if not raiding() then
      -- (out of the raid: finished, or the body was put out. A moment is given for the "Finished" signal)
      lostSince = lostSince or now()
      if RAID.finishedAt and now() - RAID.finishedAt < 30 then return "done" end
      if now() - lostSince > 6 then return "lost" end
      ctx:sleep(0.5, "Raid over?")
    else
      lostSince = nil
      local why = clearStep(ctx, state)
      if why then return why end
    end
    task.wait()
  end
  return "stopped"
end

-- ---------------------------------------------------------------- awakening
-- One look and, if allowed, one awakening. -> true when a skill was awakened (another may follow)
local function awakenOnce(spend)
  -- MysteriousEntity.luau:28  CommF_:InvokeServer("Awakener", "Check")
  local ok, info = BF.invoke(6, "Awakener", "Check")
  if not ok then RAID.awaken = "No answer: " .. tostring(info); return false end
  if info == 0 then RAID.awaken = "Not in the awakening room (the server will not talk)."; return false end
  if info == 1 then RAID.awaken = "This fruit cannot awaken yet."; return false end
  if type(info) ~= "table" then RAID.awaken = "Everything is awakened."; return false end
  local cost, frags = tonumber(info.Cost) or 0, tonumber(BF.data("Fragments")) or 0
  local text = string.format("Next: %s for %d Fragments (you have %d).", tostring(info.Key), cost, frags)
  if not spend then RAID.awaken = text; return false end
  if frags < cost + (O.awakenKeep or 0) then RAID.awaken = text .. " Kept: not enough above the reserve."; return false end
  -- MysteriousEntity.luau:48  CommF_:InvokeServer("Awakener", "Awaken") -> 1 awakened, 0 not enough Fragments
  local sent, answer = BF.invoke(8, "Awakener", "Awaken")
  RAID.awaken = sent and (answer == 1 and ("Awakened " .. tostring(info.Key) .. ".") or (answer == 0 and "Not enough Fragments." or said(answer)))
    or ("No answer: " .. tostring(answer))
  BF.say("Awakening: " .. RAID.awaken)
  return sent and answer == 1
end
local function awakenAll()
  -- (at most six in one go: there are only five skills and a "1" more than that means something else is wrong)
  for _ = 1, 6 do
    if not awakenOnce(true) then return end
    task.wait(0.5)
  end
end

-- ---------------------------------------------------------------- the job
local function stopIfDone()
  if (O.raidCount or 0) > 0 and RAID.done >= O.raidCount then
    BF.say(string.format("%d raids done: auto raid is off", RAID.done))
    Config.set("bloxfruits.raid", false)
    return true
  end
  local frags = tonumber(BF.data("Fragments")) or 0
  if (O.raidFrags or 0) > 0 and frags >= O.raidFrags then
    BF.say(string.format("%d Fragments reached: auto raid is off", frags))
    Config.set("bloxfruits.raid", false)
    return true
  end
  return false
end
-- after a raid: the reward (Fragments rise), the awakening, the way back out
local function afterRaid(ctx, result, before)
  local untilAt = now() + 20
  while now() < untilAt and not ctx.stop and (tonumber(BF.data("Fragments")) or 0) <= before do
    ctx:beat("Waiting for the reward")
    task.wait(0.25)
  end
  local gained = math.max(0, (tonumber(BF.data("Fragments")) or 0) - before)
  RAID.frags += gained
  if result == "done" then RAID.done += 1 end
  RAID.last = string.format("Raid %s, +%d Fragments.", result == "done" and "cleared" or "lost", gained)
  BF.say(RAID.last)
  ctx:progress()
  if O.awaken == true then awakenAll() end
  -- MysteriousEntity.luau:83  CommF_:InvokeServer("Awakener", "Teleport") -> 1 (taken back); 0 = not in the room, nothing done
  if O.raidLeave == true then BF.invoke(6, "Awakener", "Teleport") end
end
local function waitForStart(ctx)
  local ok, why = pressStart(ctx)
  RAID.last = ok and "Start button pressed: waiting for the raid." or ("Chip held: " .. why .. ".")
  BF.say(RAID.last)
  BF.release()
  local untilAt = now() + (O.raidWaitStart or 120)
  while now() < untilAt and not ctx.stop and B.alive do
    if raiding() then return true end
    ctx:beat("Waiting for the raid to start")
    task.wait(0.25)
  end
  RAID.restUntil = now() + 300
  RAID.last = "The raid did not start: tried again in 5 min."
  BF.say(RAID.last)
  return false
end
local function raidLoop(ctx)
  while B.alive and not ctx.stop do
    if not ctx:body(40) then return end
    if raiding() then
      local before = tonumber(BF.data("Fragments")) or 0
      local result = clearRaid(ctx)
      BF.release()
      if result == "stopped" then return end
      if result == "deaths" then
        RAID.last = "Three deaths in a row in one raid: auto raid is off."
        BF.say(RAID.last)
        Window.toast({ title = "Raids", text = RAID.last, icon = "skull", time = 8 })
        Config.set("bloxfruits.raid", false)
        return
      end
      afterRaid(ctx, result, before)
      if stopIfDone() then return end
    elseif chipHeld() then
      if not waitForStart(ctx) then return end
    elseif not cannotBuy(O.raidName or "") then
      if not buyChip(O.raidName or "") then return end
      ctx:progress()
      ctx:sleep(1, "Chip bought")
    else
      -- (nothing to do: the want turns false, the body goes back)
      return
    end
    task.wait()
  end
end
local function raidWanted()
  if O.raid ~= true or BF.sea() < 2 or now() < RAID.restUntil then return false end
  return raiding() or chipHeld() ~= nil or cannotBuy(O.raidName or "") == nil
end

-- ---------------------------------------------------------------- unlocks (Phoenix, Dough)
local function checkUnlocks()
  task.spawn(function()
    raidCheck()
    -- SickScientist.luau:70  CommF_:InvokeServer("SickScientist", "Check") -> truthy while he still needs healing
    local okP, sick = BF.invoke(6, "SickScientist", "Check")
    -- CakeScientist.luau:60  CommF_:InvokeServer("CakeScientist", "Check") -> truthy once he is freed; the Red Key is then needed (line 61)
    local okD, cake = BF.invoke(6, "CakeScientist", "Check")
    local u = RAID.unlocked
    RAID.unlock = string.format("Level 1100: %s. Phoenix: %s%s. Dough: %s%s.", RAID.levelOk and "yes" or "no",
      u.Phoenix and "unlocked" or "locked", okP and sick and " (he needs healing)" or "",
      u.Dough and "unlocked" or "locked", okD and cake and (holding("Red Key") and " (freed, Red Key held)" or " (freed, no Red Key)") or "")
    BF.say(RAID.unlock)
    Window.toast({ title = "Raid unlocks", text = RAID.unlock, icon = "lock-open", time = 8 })
  end)
end
local function healScientist()
  task.spawn(function()
    -- SickScientist.luau:81  CommF_:InvokeServer("SickScientist", "Heal") -> 1 healed, else the server's sentence
    local ok, answer = BF.invoke(8, "SickScientist", "Heal")
    RAID.unlock = ok and (answer == 1 and "Healed: the Phoenix chip is now sold by him." or ("Heal: " .. said(answer))) or ("No answer: " .. tostring(answer))
    BF.say(RAID.unlock)
    Window.toast({ title = "Phoenix", text = RAID.unlock, icon = "flame", time = 8 })
  end)
end
-- The Dough unlock as the dialogue does it: Cake Scientist freed + Red Key held -> the Dough chip bought (CakeScientist.luau:60-74, 36).
-- It spends 1,000 Fragments: the reserve and the fruit guard apply.
local function unlockDough()
  task.spawn(function()
    local ok, cake = BF.invoke(6, "CakeScientist", "Check")
    if not (ok and cake) then RAID.unlock = "The Cake Scientist is not freed yet (beat the Dough King first)."
    elseif not holding("Red Key") then RAID.unlock = "No Red Key held."
    else
      local frags, keep = tonumber(BF.data("Fragments")) or 0, O.raidKeepFrags or 0
      if fruitCarried() then RAID.unlock = "A physical fruit is carried: store it first."
      elseif frags < 1000 + keep then RAID.unlock = string.format("%d Fragments: 1,000 needed above the %d kept.", frags, keep)
      else
        local sent, answer = BF.invoke(8, "RaidsNpc", "Select", "Dough")       -- CakeScientist.luau:36 (with the key held, line 74)
        RAID.unlock = sent and (answer == 1 and "Dough chip bought." or said(answer)) or ("No answer: " .. tostring(answer))
      end
    end
    BF.say("Dough: " .. RAID.unlock)
    Window.toast({ title = "Dough", text = RAID.unlock, icon = "key", time = 8 })
  end)
end

-- ---------------------------------------------------------------- dungeon (read and travel only)
local function inDungeon() return workspace:GetAttribute("MAP") == "Dungeons" end     -- NPCCallbacks.luau:14
-- the run's folder: ReplicatedStorage.DungeonReplicationObjects holds an object named the player's ExplorerGUID (DungeonClient.luau:26-29, 58-64)
local function runFolder()
  local guid = B.LP:GetAttribute("ExplorerGUID")
  local objects = S.ReplicatedStorage:FindFirstChild("DungeonReplicationObjects")
  local mark = guid and objects and objects:FindFirstChild(tostring(guid), true)
  return mark and mark.Parent and mark.Parent.Parent
end
local function runLine()
  local folder = runFolder()
  if not folder then return inDungeon() and "In the dungeon hub, no run." or "Not in a dungeon." end
  -- TopBar.luau:143, 158-159; Interface.luau:105
  return string.format("Floor %s  ·  %s / %s enemies  ·  %s s left", tostring(folder:GetAttribute("CurrentExploredLevel") or 1),
    tostring(folder:GetAttribute("DeadEnemies") or 0), tostring(folder:GetAttribute("TotalEnemies") or 0), tostring(folder:GetAttribute("TimeLeft") or "?"))
end
local function dungeonCheck()
  task.spawn(function()
    local parts = {}
    local shared = S.ReplicatedStorage:FindFirstChild("DungeonShared")
    local data = shared and shared:FindFirstChild("DataRemote")
    if data and data:IsA("RemoteFunction") then
      -- ReplicatedPlayerData.luau:16  DungeonShared.DataRemote:InvokeServer("GetData") -> { CurrentEnergy, DataForDungeonTypes = { [type] = { MaxFloorReached } } }
      local ok, info = gameAsk(8, function() return data:InvokeServer("GetData") end)
      if ok and type(info) == "table" then
        parts[#parts + 1] = "Energy " .. tostring(info.CurrentEnergy)
        for kind, row in pairs(type(info.DataForDungeonTypes) == "table" and info.DataForDungeonTypes or {}) do
          parts[#parts + 1] = string.format("%s: floor %s", tostring(kind), tostring(type(row) == "table" and row.MaxFloorReached or "?"))
        end
      else
        parts[#parts + 1] = "No dungeon data (" .. tostring(info) .. ")"
      end
    end
    local realm = BF.mod("Util", "Realm")
    if type(realm) == "table" and type(realm.getCurrentRealmDifficultyAsync) == "function" then
      -- Util/Realm.luau:92-113 (Net "GetRealmDifficulty")
      local ok, level = gameAsk(6, realm.getCurrentRealmDifficultyAsync)
      if ok then parts[#parts + 1] = "Realm difficulty " .. tostring(level) end
    end
    RAID.dungeon = #parts > 0 and table.concat(parts, "  ·  ") or "The game did not answer."
    BF.say("Dungeon: " .. RAID.dungeon)
  end)
end
local function dungeonCall(...)
  local args = table.pack(...)
  task.spawn(function()
    local remote = netRF("DungeonNPCNetworkFunction")
    if not remote then RAID.dungeon = "No DungeonNPCNetworkFunction in this server."; return end
    local ok, answer = gameAsk(10, function() return remote:InvokeServer(table.unpack(args, 1, args.n)) end)
    RAID.dungeon = ok and (tostring(args[1]) .. ": " .. said(answer)) or ("No answer: " .. tostring(answer))
    BF.say("Dungeon: " .. RAID.dungeon)
  end)
end

-- ---------------------------------------------------------------- start
local function start()
  local folder = S.ReplicatedStorage:FindFirstChild("Remotes")
  local event = folder and folder:FindFirstChild("Raids")
  if event and event:IsA("RemoteEvent") then
    -- Main/UIController.luau:3062-3084: "StartTimer"(seconds, serverTimeStarted) and "Finished"
    B.connect(event.OnClientEvent, function(kind, seconds, startedAt)
      if kind == "StartTimer" then
        local late = (type(startedAt) == "number") and (workspace:GetServerTimeNow() - startedAt) or 0
        RAID.timerOn, RAID.endsAt, RAID.finishedAt = true, now() + (tonumber(seconds) or 0) - late, nil
        BF.say("Raid started")
      elseif kind == "Finished" then
        RAID.timerOn, RAID.finishedAt = false, now()
        BF.say("Raid finished")
      end
    end, "bloxfruits.raidTimer")
  end
  BF.job({ id = "raid", label = "Auto raid", priority = 78, switch = "bloxfruits.raid", quiet = 25, patience = 300, want = raidWanted, run = raidLoop })
end

-- ---------------------------------------------------------------- the tab
local function raidStatus()
  local left = timeLeft()
  left = left and math.floor(left)
  local state = raiding() and (left and string.format("In a raid, %d:%02d left", left // 60, left % 60) or "In a raid") or "Not in a raid"
  return string.format("%s  ·  chip %s  ·  %d done  ·  +%d Fragments  ·  %s", state, chipHeld() and "held" or "none", RAID.done, RAID.frags, RAID.last)
end
local function raidOptions()
  local out = {}
  for _, row in ipairs(raidList()) do out[#out + 1] = { row[1], row[2] and (row[1] .. " (advanced)") or row[1] } end
  if #out == 0 then out[1] = { "", "The game's list was not read" } end
  return out
end
local function raidCards(page)
  local live = page:section({ title = "Raid now", icon = "activity", full = true })
  local line = live:note({ icon = "flame", text = raidStatus() })
  local awake = live:note({ icon = "sparkles", text = "Awakening: " .. RAID.awaken })
  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    line.set(raidStatus())
    awake.set("Awakening: " .. RAID.awaken)
  end, 1, "bloxfruits.raidStatus")
  local auto = page:section({ title = "Auto raid", icon = "flame", desc = "Clears the raid island by island. Never tried live." })
  auto:toggle({ id = "bloxfruits.raid", label = "Auto raid", desc = "Stops after three deaths in a row.", default = false, children = function(sub)
    sub:dropdown({ id = "bloxfruits.raidName", label = "Raid", options = raidOptions() })
    sub:toggle({ id = "bloxfruits.raidBuy", label = "Buy the chip", desc = "Spends Beli or Fragments when no chip is held.", default = false, bindable = false })
    sub:slider({ id = "bloxfruits.raidKeepBeli", label = "Keep at least", min = 0, max = 10000000, step = 50000, default = 0, suffix = " Beli" })
    sub:slider({ id = "bloxfruits.raidKeepFrags", label = "Keep at least", min = 0, max = 50000, step = 500, default = 0, suffix = " Frags" })
    sub:toggle({ id = "bloxfruits.raidPress", label = "Press the start button", desc = "Not proven: off means you press it.", default = false, bindable = false })
    sub:slider({ id = "bloxfruits.raidWaitStart", label = "Wait for the start", min = 30, max = 600, step = 15, default = 120, suffix = " s" })
    sub:slider({ id = "bloxfruits.raidAura", label = "Kill aura", tip = "Mobs within it are fought, nearest first.", min = 50, max = 1000, step = 25, default = 300, suffix = " st" })
    sub:slider({ id = "bloxfruits.raidHeight", label = "Height over the island", min = 10, max = 80, step = 5, default = 30, suffix = " st" })
    sub:slider({ id = "bloxfruits.raidCount", label = "Stop after", tip = "0 = never.", min = 0, max = 100, step = 1, default = 0, suffix = " raids" })
    sub:slider({ id = "bloxfruits.raidFrags", label = "Stop at", tip = "0 = never.", min = 0, max = 100000, step = 500, default = 0, suffix = " Frags" })
    sub:toggle({ id = "bloxfruits.raidLeave", label = "Leave the awakening room", desc = "Asks to be taken back after each raid.", default = false, bindable = false })
  end })
  auto:button({ id = "bloxfruits.raidCheck", label = "Level and unlocks", desc = "Asks the scientist, buys nothing.", text = "Check", run = checkUnlocks })

  local wake = page:section({ title = "Awakening", icon = "sparkles", column = 2, desc = "The server picks the next skill." })
  wake:toggle({ id = "bloxfruits.awaken", label = "Auto awaken", desc = "After each raid, while Fragments allow.", default = false, bindable = false })
  wake:slider({ id = "bloxfruits.awakenKeep", label = "Keep at least", min = 0, max = 50000, step = 500, default = 0, suffix = " Frags" })
  wake:button({ id = "bloxfruits.awakenCheck", label = "Next skill", desc = "Asks what comes next, spends nothing.", text = "Check", run = function()
    task.spawn(function() awakenOnce(false); BF.say("Awakening: " .. RAID.awaken) end)
  end })
  wake:button({ id = "bloxfruits.awakenNow", label = "Awaken the next", desc = "Only in the awakening room.", text = "Awaken", run = function()
    task.spawn(function() awakenOnce(true) end)
  end })

  local unlock = page:section({ title = "Phoenix and Dough", icon = "lock-open", column = 2, desc = "Only what their dialogue sends." })
  unlock:button({ id = "bloxfruits.unlockCheck", label = "Where I stand", desc = "Level, unlocks, both scientists.", text = "Check", run = checkUnlocks })
  unlock:button({ id = "bloxfruits.healSick", label = "Heal the Sick Scientist", desc = "Phoenix: the server says what it wants.", text = "Heal", run = healScientist })
  unlock:button({ id = "bloxfruits.unlockDough", label = "Dough chip", desc = "Freed scientist and Red Key: 1,000 Fragments.", text = "Buy", run = unlockDough })
  local note = unlock:note({ icon = "info", text = RAID.unlock })
  Motion.every(function()
    if note.frame.Parent and Window.anyOpen() then note.set(RAID.unlock) end
  end, 2, "bloxfruits.unlockStatus")
end
local function dungeonCard(page)
  local d = page:section({ title = "Dungeon", icon = "door-open", full = true, desc = "Level 1100. Status and travel only." })
  local run = d:note({ icon = "activity", text = runLine() })
  local info = d:note({ icon = "info", text = RAID.dungeon })
  Motion.every(function()
    if not (run.frame.Parent and Window.anyOpen()) then return end
    run.set(runLine())
    info.set(RAID.dungeon)
  end, 2, "bloxfruits.dungeonStatus")
  d:button({ id = "bloxfruits.dungeonCheck", label = "Energy and floors", desc = "Asks the game, changes nothing.", text = "Check", run = dungeonCheck })
  -- ServerBrowser LocalScript.luau:370, 407 and NPCCallbacks.luau:43: ("TeleportToDungeonHub", false); the button is active from level 1100 (line 594)
  d:button({ id = "bloxfruits.dungeonGo", label = "Go to the Dungeon Hub", desc = "The game's own teleport.", text = "Go", run = function()
    if BF.level() < 1100 then RAID.dungeon = "Level 1100 is needed."; return end
    dungeonCall("TeleportToDungeonHub", false)
  end })
  -- NPCCallbacks.luau:92 ("TeleportBack"), offered only on the dungeon map
  d:button({ id = "bloxfruits.dungeonBack", label = "Back to my sea", desc = "Only from the dungeon.", text = "Back", run = function()
    if not inDungeon() then RAID.dungeon = "Not in the dungeon."; return end
    dungeonCall("TeleportBack")
  end })
  d:note({ icon = "triangle-alert", text = "Not built: queueing a floor, buff cards, clearing floors." })
end
local function raid(page)
  if BF.sea() >= 2 then
    raidCards(page)
  else
    local here = page:section({ title = "Raids", icon = "flame", full = true })
    here:note({ icon = "info", text = "Raids and awakening are in the Second and Third Seas." })
  end
  dungeonCard(page)
end

BF.parts[#BF.parts + 1] = { id = "raid", start = start, raid = raid,
  defaults = { raid = false, raidName = "Flame", raidBuy = false, raidKeepBeli = 0, raidKeepFrags = 0, raidPress = false, raidWaitStart = 120, raidAura = 300,
    raidHeight = 30, raidCount = 0, raidFrags = 0, raidLeave = false, awaken = false, awakenKeep = 0 } }
end
do -- bloxfruits_sea.lua
-- ============================================================================
--  Blox Fruits     the sea: boat, sea events, Mirage, Kitsune, Prehistoric,
--                  fishing and crafting
--
--  Read from the game's own code (dump 2753915549 v4630, `fast\` folder: the
--  First Sea place, whose ReplicatedStorage holds the shared code of every sea),
--  never tried live: every line below is unproven until measured.
--
--   * A boat is bought with CommF_ "BuyBoat", key (1 bought, 0 money, 2 spawn
--     blocked, 3 game pass, 4 locked: DialoguesList/Library.luau:525-552). The
--     keys a dealer offers are BoatInfo.getForDealer(kind) (Modules/BoatInfo.luau:23),
--     kind = "Pirate"/"Marine" by team for the "Boat Dealer" (DialoguesList.luau:314-325).
--   * A boat is driven by its VehicleSeat's ThrottleFloat / SteerFloat: the game's
--     own ShipController reads them every frame and sets the seat's BodyVelocity /
--     BodyGyro from them and the seat's MaxSpeed (ShipController/Controllers/
--     Movement.luau:177-290). Roblox's VehicleController writes them from the keys
--     (PlayerModule/ControlModule/VehicleController.luau:211-217). This part writes
--     them after that, at Heartbeat, and never touches MaxSpeed, the body movers,
--     collisions or the boat's CFrame.
--   * Danger: the player attribute "DangerLevel" (set by the server), shown as
--     GetDangerLevel(raw).level - 1 = 0..6 (UIController/SeaExploration.luau:12, 76;
--     Util/GetDangerLevel.luau). The Second Sea shows 0 always (SeaExploration.luau:60).
--     Distance from land: require(ReplicatedStorage.IslandDistance)(point) (IslandDistance.luau:117).
--   * Sea creatures: workspace.SeaBeasts and workspace.SeaEvents (as the ESP part reads
--     them: bloxfruits_esp.lua onSea/onSeaEvent), and workspace.Enemies. A body whose
--     health is in a "FakeHumanoid" (LocalScriptBossBar.luau:24) cannot be fought with
--     BF.fight, which reads Humanoid.Health: sea beasts and the Leviathan are left out.
--   * Fishing is the game's own client (FishReplicated/FishingClient.luau), driven by
--     the mouse button it binds (line 832-868); the bite is read from its own Net
--     "FishingRemote" event (line 7, 41-85). Shop: Net "JobsRemoteFunction"
--     (JobsReplicated.luau:5, 102-108) and Net "Craft" (NPCFishClient.luau:10, 45).
--   * Craft: Net "Craft" "Check", key -> { Required, Result, ResultStats }, then
--     "Craft", Result.Recipe, amount, {} (Controllers/UI/CraftWindow.luau:488, 553, 964).
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion = B.S, B.Config, B.Window, B.Motion
local BF = B.BloxFruits
local O = BF.O
local function now() return os.clock() end

local SEA = { boats = 0, kills = 0, deaths = 0, mirage = 0, embers = 0, offers = 0, eggs = 0, casts = 0, bites = 0, reeled = 0, sold = 0, crafts = 0 }
BF.seaPart = SEA
local once = { buy = false, quest = false, craft = nil }      -- one-shot jobs asked for by a button
local last = { boat = "Not asked yet.", fish = "Not asked yet.", craft = "Pick something.", kitsune = "Nothing yet.", mirage = "Nothing yet." }

-- ---------------------------------------------------------------- small helpers
local function pivotOf(model)
  local ok, pivot = pcall(model.GetPivot, model)
  return ok and pivot.Position or nil
end
-- an NPC by name: near ones in workspace.NPCs, every one in ReplicatedStorage.NPCs (as the boss part reads them)
local function npcAt(name)
  for _, folder in ipairs({ workspace:FindFirstChild("NPCs"), S.ReplicatedStorage:FindFirstChild("NPCs") }) do
    local npc = folder and folder:FindFirstChild(name)
    local at = npc and pivotOf(npc)
    if at then return at end
  end
  return nil
end
local function toNpc(ctx, name)
  local at = npcAt(name)
  if not at then return false, name .. " was not found" end
  local ok, why = BF.fly(at + Vector3.new(0, 3, 4), ctx, { note = "To " .. name })
  if not ok then return false, tostring(why) end
  return true
end

-- ---------------------------------------------------------------- the game's Net remotes
local Net = { cache = {} }
-- A Net remote through the game's own module. The folder is checked first: Net's `get` waits 99 s for a missing one (Modules/Net.luau:215-221).
function Net.get(kind, name)
  local key = kind .. "/" .. name
  local got = Net.cache[key]
  if got then return got end
  local modules = S.ReplicatedStorage:FindFirstChild("Modules")
  local folder = modules and modules:FindFirstChild("Net")
  local prefix = kind == "RemoteEvent" and "RE/" or "RF/"
  if not (folder and folder:FindFirstChild(prefix .. name)) then return nil end
  local net = BF.mod("Modules", "Net")
  if not net then return nil end
  local ok, remote = BF.game(net[kind], net, name)               -- Net.luau:243-260 (Net:RemoteEvent(name) / Net:RemoteFunction(name))
  if not ok or remote == nil then return nil end
  Net.cache[key] = remote
  return remote
end
-- one InvokeServer with an end to the wait -> ok, answer...
function Net.ask(timeout, name, ...)
  local remote = Net.get("RemoteFunction", name)
  if not remote then return false, "no " .. name .. " remote" end
  local args = table.pack(...)
  local done, out = false, nil
  BF.count.calls += 1
  task.spawn(function()
    out = table.pack(BF.game(function() return remote:InvokeServer(table.unpack(args, 1, args.n)) end))
    done = true
  end)
  local started = now()
  while not done and now() - started < (timeout or 6) do task.wait() end
  if not done then return false, "timeout" end
  return table.unpack(out, 1, out.n)
end
function Net.fire(name, ...)
  local remote = Net.get("RemoteEvent", name)
  if not remote then return false, "no " .. name .. " remote" end
  BF.count.calls += 1
  local args = table.pack(...)
  return BF.game(function() remote:FireServer(table.unpack(args, 1, args.n)) end)
end
-- the fishing shop's door: JobsReplicated.InvokeServer(...) = Net "JobsRemoteFunction":InvokeServer(...) (JobsReplicated.luau:5, 102-108)
local function jobs(timeout, ...)
  return Net.ask(timeout, "JobsRemoteFunction", ...)
end

-- ---------------------------------------------------------------- boats
local Boat = { drive = nil, buyAt = 0 }
-- dealers and the list each sells (NPCManager/NPCList.luau:192, 204, 216; DialoguesList.luau:314-328)
Boat.DEALERS = { ["Boat Dealer"] = "team", ["Marines Boat Dealer"] = "Marine", ["Advanced Marines Boat Dealer"] = "Marine2" }
function Boat.teamKind()
  -- DialoguesList.luau:319: anything but the Pirates team buys from the Marine list
  local pirates = game:GetService("Teams"):FindFirstChild("Pirates")
  return (pirates and B.LP.Team == pirates) and "Pirate" or "Marine"
end
-- { key, label } of the boats the team's dealer lists, as the dealer builds them (Library.luau:599, 822-830; BoatInfo.luau:3-35)
function Boat.options()
  local info = BF.mod("Modules", "BoatInfo")
  local out = {}
  if not (info and type(info.getForDealer) == "function") then return { { "", "Not readable" } } end
  local ok, keys = BF.game(info.getForDealer, Boat.teamKind())
  for _, key in ipairs(ok and type(keys) == "table" and keys or {}) do
    local row = info.List and info.List[key]
    -- (a fast-boat one needs a game pass the dealer never offers here: Library.luau:601, 828)
    if type(row) == "table" and not row.RequiresFastBoat then
      out[#out + 1] = { key, string.format("%s (%s)", tostring(row.DisplayName), (row.Cost or 0) > 0 and ("$" .. tostring(row.Cost)) or "free") }
    end
  end
  if #out == 0 then out[1] = { "", "None" } end
  return out
end
-- this player's boat: workspace.Boats.<name> with Owner (ObjectValue) = me and boat health (IntValue "Humanoid") above 0
-- (bloxfruits_esp.lua onBoat; ShipService.luau:76-77; ShipHealthBarController.luau:66-67)
function Boat.mine()
  local folder = workspace:FindFirstChild("Boats")
  for _, boat in ipairs(folder and folder:GetChildren() or {}) do
    local owner = boat:FindFirstChild("Owner")
    if owner and owner:IsA("ObjectValue") and owner.Value == B.LP then
      local health = boat:FindFirstChild("Humanoid")
      local alive = not (health and health:IsA("ValueBase") and tonumber(health.Value) and health.Value <= 0)
      if alive and boat:FindFirstChild("VehicleSeat") then return boat end       -- Movement.luau:39 (the driver's seat)
    end
  end
  return nil
end
function Boat.seated(boat)
  local hum = BF.hum()
  local seat = boat and boat:FindFirstChild("VehicleSeat")
  return hum ~= nil and seat ~= nil and hum.SeatPart == seat
end
-- Stand up the way the game does it: its own SeatUtil.unseat (Util/SeatUtil.luau:69-82).
function Boat.standUp()
  local hum, character = BF.hum(), BF.char()
  if not (hum and character and hum.SeatPart) then return end
  local util = BF.mod("Util", "SeatUtil")
  if util and type(util.unseat) == "function" then
    BF.game(util.unseat, character)
  else
    pcall(function() hum.Sit = false end)
  end
end
-- Sit at the helm the way a player does: the body is put on the seat and the engine's own seat touch seats it.
function Boat.sit(ctx, boat)
  local seat = boat:FindFirstChild("VehicleSeat")
  local hum = BF.hum()
  if not (seat and hum) then return false, "no seat" end
  if hum.SeatPart == seat then return true end
  if seat.Occupant and seat.Occupant ~= hum then return false, "someone else is at the helm" end
  local ok, why = BF.fly(seat.Position + Vector3.new(0, 4, 0), ctx, { note = "To the boat" })
  if not ok then return false, tostring(why) end
  local untilAt = now() + 3
  while now() < untilAt and hum.SeatPart ~= seat do
    if ctx.stop then return false, "stopped" end
    BF.holdAt(seat.Position + Vector3.new(0, 1.5, 0))
    ctx:beat("Sitting at the helm")
    task.wait(0.1)
  end
  -- (let go: a held body fights the seat's weld)
  BF.release()
  local settle = now() + 1.5
  while now() < settle and hum.SeatPart ~= seat do ctx:beat("Sitting at the helm"); task.wait(0.1) end
  if hum.SeatPart == seat then return true end
  return false, "the seat did not take the body"
end
-- The nearest dealer that sells `key`, flown to, then CommF_ "BuyBoat", key (Library.luau:525).
function Boat.buy(ctx, key)
  if key == "" then return false, "no boat picked" end
  local best, bestGap
  local root = BF.root()
  for name in pairs(Boat.DEALERS) do
    local at = npcAt(name)
    local gap = at and root and (at - root.Position).Magnitude
    if gap and (not bestGap or gap < bestGap) then best, bestGap = name, gap end
  end
  if not best then return false, "no boat dealer found" end
  local ok, why = toNpc(ctx, best)
  if not ok then return false, why end
  local sent, answer = BF.invoke(8, "BuyBoat", key)
  local said = { [1] = "Boat purchased.", [0] = "Not enough money.", [2] = "The boat spawn is blocked by another boat.", [3] = "You don't own this game pass.",
    [4] = "Boat locked: not yet." }
  last.boat = sent and (said[answer] or tostring(answer)) or ("No answer: " .. tostring(answer))
  BF.say("Boat: " .. last.boat)
  if sent and answer == 1 then SEA.boats += 1; return true end
  return false, last.boat
end

-- ---------------------------------------------------------------- where the boat is
local Zone = {}
function Zone.danger()
  -- the raw value the server sets, and the level the compass shows (SeaExploration.luau:12, 71-76)
  local raw = tonumber(B.LP:GetAttribute("DangerLevel")) or 0
  local get = BF.mod("Util", "GetDangerLevel")
  if type(get) ~= "function" then return 0, raw end
  local ok, info = BF.game(get, raw)
  return ok and type(info) == "table" and math.max(0, (tonumber(info.level) or 1) - 1) or 0, raw
end
function Zone.land(point)
  local measure = BF.mod("IslandDistance")
  if type(measure) ~= "function" then return nil end
  local ok, gap, island = BF.game(measure, point)          -- IslandDistance.luau:117-133 -> studs from the nearest island's edge, that island
  if not ok or type(gap) ~= "number" then return nil end
  return gap, type(island) == "table" and island or nil
end
-- How far out: the value the target is in, and whether it is reached. Danger only reads in the Third Sea.
function Zone.reached(point)
  if O.seaZone == "danger" and BF.sea() == 3 then
    local level = Zone.danger()
    return level >= (O.seaDanger or 3), string.format("danger %d of %d", level, O.seaDanger or 3)
  end
  local gap = Zone.land(point)
  if not gap then return false, "distance unknown" end
  return gap >= (O.seaDistance or 1200), string.format("%d of %d studs from land", math.floor(gap), O.seaDistance or 1200)
end
-- the throttle and steer that point the boat away from the nearest land (steer > 0 turns right: Movement.luau:217)
function Zone.course(seat)
  local gap, island = Zone.land(seat.Position)
  local look = seat.CFrame.LookVector * Vector3.new(1, 0, 1)
  if look.Magnitude < 0.01 then return 0, 0 end
  look = look.Unit
  local away
  if gap and island and typeof(island.Position) == "Vector3" then away = (seat.Position - island.Position) * Vector3.new(1, 0, 1) end
  if not away or away.Magnitude < 1 then return 1, 0 end
  away = away.Unit
  local turn = look:Cross(away).Y            -- (negative = the open sea is to the right)
  local steer = math.clamp(-turn * 2, -1, 1)
  if look:Dot(away) < 0 then steer = turn <= 0 and 1 or -1 end
  return 1, steer
end

-- ---------------------------------------------------------------- the Sail job
local sail = { stalls = 0, restUntil = 0 }
local function driving(seat, throttle, steer)
  Boat.drive = { seat = seat, throttle = throttle, steer = steer }
end
local function sailStep(ctx, boat, state)
  local seat = boat:FindFirstChild("VehicleSeat")
  local reached, text = Zone.reached(seat.Position)
  if reached then
    if O.seaKeep == true then
      -- (a slow wide circle: the boat stays out but keeps moving)
      driving(seat, 0.4, 0.3)
      ctx:beat("Out at sea, circling: " .. text)
    else
      driving(seat, 0, 0)
      ctx:beat("Out at sea, holding: " .. text)
    end
    state.movedAt, state.from = now(), seat.Position
    ctx:progress()
    return
  end
  local throttle, steer = Zone.course(seat)
  if state.turnUntil and now() < state.turnUntil then throttle, steer = 0.6, 1 end
  driving(seat, throttle, steer)
  ctx:beat("Sailing out: " .. text)
  -- (no headway for 20 s at full throttle: something is in the way. Turned for 5 s, five times at most)
  if not state.from or (seat.Position - state.from).Magnitude > 40 then
    state.from, state.movedAt = seat.Position, now()
    ctx:progress()
  elseif now() - state.movedAt > 20 then
    sail.stalls += 1
    state.movedAt, state.turnUntil = now(), now() + 5
    BF.say("Sail: the boat made no headway, turning")
  end
end
local function sailLoop(ctx)
  local state = {}
  sail.stalls = 0
  while B.alive and not ctx.stop do
    if not ctx:body(40) then return end
    local boat = Boat.mine()
    if not boat then
      Boat.drive = nil
      if O.seaBuy == true and now() >= Boat.buyAt then
        Boat.buyAt = now() + 60
        local ok, why = Boat.buy(ctx, O.seaBoat or "")
        if not ok then BF.say("Sail: no boat (" .. tostring(why) .. "), asked again in 1 min") end
        ctx:sleep(3, "Waiting for the boat")
      else
        BF.say("Sail: you have no boat out; tick Buy one or get one at a dealer")
        Config.set("bloxfruits.seaSail", false)
        return
      end
    elseif not Boat.seated(boat) then
      Boat.drive = nil
      local ok, why = Boat.sit(ctx, boat)
      if not ok then
        sail.restUntil = now() + 60
        BF.say("Sail: could not sit at the helm (" .. tostring(why) .. "), tried again in 1 min")
        return
      end
    else
      sailStep(ctx, boat, state)
      if sail.stalls >= 5 then
        Boat.drive = nil
        sail.restUntil = now() + 120
        BF.say("Sail: stuck five times, resting 2 min")
        return
      end
    end
    task.wait(0.2)
  end
end

-- ---------------------------------------------------------------- sea events
local Ev = { aside = {}, streak = {}, excluded = {}, view = nil, viewAt = -1e9, back = false }
-- the kinds, by name. Only "Sea Beast", "Terrorshark" and "Leviathan" are named in the client (React/Components/PlayerProfile/
-- CONSTANTS.luau:18; SyncLeviathan.luau:7); the other names are public knowledge, unverified. Order matters: terror before shark.
Ev.KINDS = {
  { "beast", "Sea Beast", { "sea beast", "seabeast" } }, { "leviathan", "Leviathan", { "leviathan" } },
  { "terror", "Terrorshark", { "terrorshark", "terror shark" } }, { "piranha", "Piranha", { "piranha" } },
  { "crew", "Fish Crew", { "fish crew" } }, { "ghost", "Ghost Ship", { "ghost ship", "ghostship", "cursed ship" } }, { "shark", "Shark", { "shark" } },
}
function Ev.kindOf(name)
  local lower = string.lower(name)
  for _, row in ipairs(Ev.KINDS) do
    for _, word in ipairs(row[3]) do
      if string.find(lower, word, 1, true) then return row[1], row[2] end
    end
  end
  return nil
end
-- BF.fight needs a Humanoid with the real health and a root; a FakeHumanoid holds the real health elsewhere (LocalScriptBossBar.luau:24-31).
function Ev.fightable(model)
  if model:FindFirstChild("FakeHumanoid") then return false end
  return BF.living(model) and not ((BF.shunned[model] or 0) > now())
end
local function picked(kind)
  local list = type(O.seaEventPick) == "table" and O.seaEventPick or {}
  return table.find(list, kind) ~= nil
end
-- living, ticked, fightable bodies: { model, kind, label }, nearest first. Kept 1 s.
function Ev.targets()
  if Ev.view and now() - Ev.viewAt < 1 then return Ev.view end
  local out, t = {}, now()
  for _, name in ipairs({ "SeaBeasts", "SeaEvents", "Enemies" }) do
    local folder = workspace:FindFirstChild(name)
    for _, model in ipairs(folder and folder:GetChildren() or {}) do
      local kind, label = nil, nil
      if model:IsA("Model") then kind, label = Ev.kindOf(model.Name) end
      if kind and picked(kind) and not ((Ev.aside[kind] or 0) > t) then
        if Ev.fightable(model) then
          out[#out + 1] = { model = model, kind = kind, label = label }
        elseif not Ev.excluded[kind] and (model:FindFirstChild("FakeHumanoid") or not model:FindFirstChildOfClass("Humanoid")) then
          Ev.excluded[kind] = true
          BF.say(label .. " has no Humanoid health: Sea events leaves it alone")
        end
      end
    end
  end
  local root = BF.root()
  if root then
    table.sort(out, function(a, b) return (a.model.HumanoidRootPart.Position - root.Position).Magnitude < (b.model.HumanoidRootPart.Position - root.Position).Magnitude end)
  end
  Ev.view, Ev.viewAt = out, now()
  return out
end
-- deaths in a row on one kind: three = that kind is left alone 30 min (like the boss part's guard)
local function evGuard(ctx, row, result, before)
  if result == "died" or not BF.alive() then ctx:body(40) end
  if result == "dead" then Ev.streak[row.kind] = 0; return end
  local died = BF.count.deaths - before
  if died <= 0 then return end
  SEA.deaths += died
  Ev.streak[row.kind] = (Ev.streak[row.kind] or 0) + died
  if Ev.streak[row.kind] >= 3 then
    Ev.streak[row.kind], Ev.aside[row.kind] = 0, now() + 1800
    BF.say(row.label .. " killed the body 3 times in a row: left alone for 30 min")
  end
end
local function evBack(ctx)
  local boat = Boat.mine()
  if not boat or Boat.seated(boat) then Ev.back = false; return end
  local ok, why = Boat.sit(ctx, boat)
  if not ok then BF.say("Sea events: could not get back on the boat (" .. tostring(why) .. ")") end
  Ev.back = false
end
local function eventsLoop(ctx)
  while B.alive and not ctx.stop do
    if not ctx:body(40) then return end
    local row = Ev.targets()[1]
    if not row then
      if Ev.back and O.seaReturn ~= false then evBack(ctx) end
      Ev.back = false
      BF.release()
      return
    end
    Boat.standUp()
    Ev.back = true
    local before = BF.count.deaths
    local result = BF.fight(row.model, ctx, function()
      local list = {}
      for _, other in ipairs(Ev.targets()) do
        if other.kind == row.kind then list[#list + 1] = other.model end
      end
      return list
    end, { height = O.seaFightHeight or 20 })
    Ev.viewAt = -1e9
    if result == "dead" then SEA.kills += 1; BF.say(row.label .. " down") end
    if result == "stopped" then return end
    evGuard(ctx, row, result, before)
    task.wait()
  end
end

-- ---------------------------------------------------------------- Mirage Island (Third Sea)
local Mir = { done = BF.keep({}) }
-- its mark: the Location part "Mirage Island" (CONSTANTS.luau:18 names it; IslandDistance.luau:8 reads Locations), else the fog zone
-- "MirageIsland" under _WorldOrigin.LightingZones (WeatherStuff.luau:43) - the same two places the ESP part watches
function Mir.part()
  local origin = workspace:FindFirstChild("_WorldOrigin")
  local places = origin and origin:FindFirstChild("Locations")
  local mark = places and places:FindFirstChild("Mirage Island")
  if mark and mark:IsA("BasePart") then return mark end
  local zones = origin and origin:FindFirstChild("LightingZones")
  local zone = zones and zones:FindFirstChild("MirageIsland")
  return zone and zone:IsA("BasePart") and zone or nil
end
-- the highest ground of the island: rays straight down over its area onto workspace.Map
function Mir.top(part)
  local map = workspace:FindFirstChild("Map")
  if not map then return nil end
  local params = RaycastParams.new()
  params.FilterType = Enum.RaycastFilterType.Include
  params.FilterDescendantsInstances = { map }
  local mesh = part:FindFirstChildWhichIsA("SpecialMesh")
  local scale = mesh and mesh.Scale.X or 1
  local radius = math.clamp(math.max(part.Size.X, part.Size.Z) * scale / 2, 100, 1500)
  local best
  for i = -4, 4 do
    for j = -4, 4 do
      local from = Vector3.new(part.Position.X + radius * i / 4, part.Position.Y + 3000, part.Position.Z + radius * j / 4)
      local hit = workspace:Raycast(from, Vector3.new(0, -6000, 0), params)
      if hit and (not best or hit.Position.Y > best.Y) then best = hit.Position end
    end
  end
  return best
end
local function mirageLoop(ctx)
  if not ctx:body(40) then return end
  local part = Mir.part()
  if not part then return end
  Mir.done[part] = true
  local top = Mir.top(part)
  if top then
    local ok = BF.fly(top + Vector3.new(0, 6, 0), ctx, { note = "To the top of Mirage Island" })
    if ok then ctx:sleep(O.mirageWait or 5, "On the top of Mirage Island") end
  end
  -- (the blue gear: nothing in the client names it, so it is not looked for. Mirage chests are "DiamondChest" = Mirage Chest
  -- (ChestConfiguration/ChestTypes.luau:6): the Loot tab's chest farm takes them by their tag when it is on)
  local dealer = npcAt("Advanced Fruit Dealer")                 -- NPCList.luau:60 (DialoguesList.FruitShop2)
  if dealer and (dealer - part.Position).Magnitude < 3000 then
    toNpc(ctx, "Advanced Fruit Dealer")
    last.mirage = "At the Advanced Fruit Dealer."
  else
    last.mirage = "Visited; the Advanced Fruit Dealer was not near."
  end
  SEA.mirage += 1
  ctx:progress()
  BF.say("Mirage Island: " .. last.mirage)
  BF.release()
end

-- ---------------------------------------------------------------- Kitsune Island (Third Sea, blue moon)
local Kit = { embers = BF.keep({}), held = 0, emptySince = nil, wakeAt = 0, aside = BF.keep({}) }
-- An ember the server sends (Net "SpawnBlueEmbers", n) is a clone of the client's EmberTemplate put in workspace; touching it fires
-- Net "CollectBlueEmber" and destroys it (Controllers/BlueMoonClient.luau:89-124, 112-113). The one that follows the player is renamed
-- "AttachedAzureEmber" (line 28) and is not one.
function Kit.watch(child)
  if child.Name == "EmberTemplate" and child:IsA("Model") then Kit.embers[child] = true end
end
function Kit.list()
  local out, root, t = {}, BF.root(), now()
  for model in pairs(Kit.embers) do
    local part = model.Parent == workspace and model.PrimaryPart
    if part and not ((Kit.aside[model] or 0) > t) then out[#out + 1] = { model = model, part = part } end
  end
  if root then table.sort(out, function(a, b) return (a.part.Position - root.Position).Magnitude < (b.part.Position - root.Position).Magnitude end) end
  return out
end
function Kit.shrine()
  -- the shrine's statue: workspace.Map.KitsuneIsland.optimizedcylinder (BlueMoonClient.luau:237-238)
  local map = workspace:FindFirstChild("Map")
  local island = map and map:FindFirstChild("KitsuneIsland")
  local statue = island and island:FindFirstChild("optimizedcylinder")
  return statue and statue:IsA("BasePart") and statue.Position or nil
end
function Kit.canWake()
  -- the shrine's "Touch Statue" works on a full moon before the blue one (DialoguesList.luau:5226-5230)
  local light = S.Lighting
  return light:GetAttribute("MoonPhase") == 5 and not light:GetAttribute("IsBlueMoon") and not light:GetAttribute("BlueMoonEnded")
end
-- chase one ember onto the body: it runs from a body within 100 studs (BlueMoonClient.luau:155-161), so it is held onto, frame by frame
local function chase(ctx, item)
  local untilAt = now() + 8
  while item.model.Parent and now() < untilAt do
    if ctx.stop then return "stopped" end
    if not BF.alive() then return "died" end
    local at = item.part.Position
    local root = BF.root()
    if root and (root.Position - at).Magnitude > 60 then
      BF.fly(at, ctx, { direct = (root.Position - at).Magnitude < 350, note = "To an Azure Ember" })
    else
      BF.holdAt(at)
    end
    ctx:beat("Catching an Azure Ember")
    task.wait(0.05)
  end
  if item.model.Parent then Kit.aside[item.model] = now() + 30; return "missed" end
  return "taken"
end
local function offer(ctx)
  local at = Kit.shrine()
  if not at then last.kitsune = "The shrine was not found."; return end
  if not BF.fly(at + Vector3.new(0, 4, 8), ctx, { note = "To the Kitsune shrine" }) then return end
  -- DialoguesList.luau:13, 5268: Net "KitsuneStatuePray":InvokeServer() -> the shrine's sentence
  local ok, text = Net.ask(8, "KitsuneStatuePray")
  last.kitsune = ok and tostring(text or "...") or ("No answer: " .. tostring(text))
  if ok then SEA.offers += 1; Kit.held = 0 end
  BF.say("Kitsune shrine: " .. last.kitsune)
end
local function wake(ctx)
  Kit.wakeAt = now() + 300
  local at = Kit.shrine()
  if not at then return end
  if not BF.fly(at + Vector3.new(0, 4, 8), ctx, { note = "To the Kitsune shrine" }) then return end
  local ok = Net.fire("TouchKitsuneStatue")                       -- DialoguesList.luau:12, 5230 (FireServer, nothing more)
  last.kitsune = ok and "The statue was touched." or "The statue could not be touched."
  BF.say("Kitsune shrine: " .. last.kitsune)
end
local function kitsuneLoop(ctx)
  while B.alive and not ctx.stop do
    if not ctx:body(40) then return end
    local item = Kit.list()[1]
    if item then
      Kit.emptySince = nil
      local result = chase(ctx, item)
      if result == "taken" then SEA.embers += 1; Kit.held += 1; ctx:progress() end
      if result == "stopped" then return end
    elseif O.kitsuneOffer == true and Kit.held > 0 and Kit.emptySince and now() - Kit.emptySince > 10 then
      offer(ctx)
      Kit.held = 0
    elseif O.kitsuneWake == true and Kit.canWake() and now() >= Kit.wakeAt then
      wake(ctx)
    else
      Kit.emptySince = Kit.emptySince or now()
      if not (O.kitsuneOffer == true and Kit.held > 0) then BF.release(); return end
      ctx:sleep(1, "Waiting for embers")
    end
    task.wait()
  end
end
local function kitsuneWanted()
  if O.kitsuneFarm ~= true or BF.sea() ~= 3 then return false end
  if not Kit.scanned then
    -- (embers already out when the switch went on: one look through workspace's children)
    Kit.scanned = true
    for _, child in ipairs(workspace:GetChildren()) do Kit.watch(child) end
  end
  if #Kit.list() > 0 then return true end
  if O.kitsuneOffer == true and Kit.held > 0 then return true end
  return O.kitsuneWake == true and Kit.canWake() and now() >= Kit.wakeAt and Kit.shrine() ~= nil
end

-- ---------------------------------------------------------------- Prehistoric Island (Third Sea): dragon eggs
local Pre = { aside = BF.keep({}) }
-- An egg carries the tag "PrehistoricIslandDragonEgg"; its ProximityPrompt is kept only for an event participant (player attribute
-- PrehistoricIslandParticipant) (Controllers/PrehistoricIslandClient.luau:30-58).
function Pre.eggs()
  local out, t = {}, now()
  if not B.LP:GetAttribute("PrehistoricIslandParticipant") then return out end
  for _, egg in ipairs(S.CollectionService:GetTagged("PrehistoricIslandDragonEgg")) do
    local prompt = egg:FindFirstChildWhichIsA("ProximityPrompt", true)
    if prompt and prompt.Enabled and egg:IsDescendantOf(workspace) and not ((Pre.aside[egg] or 0) > t) then out[#out + 1] = { egg = egg, prompt = prompt } end
  end
  return out
end
local function eggsLoop(ctx)
  while B.alive and not ctx.stop do
    if not ctx:body(40) then return end
    local item = Pre.eggs()[1]
    if not item then BF.release(); return end
    local at = pivotOf(item.egg)
    local ok = at and BF.fly(at + Vector3.new(0, 3, 0), ctx, { note = "To a dragon egg" })
    if ok then
      -- (the prompt held the way a key press holds it: the engine's own ProximityPrompt input)
      pcall(function() item.prompt:InputHoldBegin() end)
      ctx:sleep((item.prompt.HoldDuration or 0) + 0.3, "Taking a dragon egg")
      pcall(function() item.prompt:InputHoldEnd() end)
      ctx:sleep(1.5, "Taking a dragon egg")
    end
    if item.egg.Parent and item.prompt.Parent then
      Pre.aside[item.egg] = now() + 60
      BF.say("A dragon egg was not taken: set aside for 1 min")
    else
      SEA.eggs += 1
      ctx:progress()
    end
    task.wait()
  end
end

-- ---------------------------------------------------------------- fishing
local Fish = { listening = false, biteAt = 0, reeledAt = 0, startedAt = 0, sinceSell = 0 }
local VIM = nil
-- the mouse button the game's fishing controls are bound to (FishingClient.luau:832-868), pressed at the middle of the screen
local function press(down)
  if not VIM then
    local ok, service = pcall(function() return game:GetService("VirtualInputManager") end)
    VIM = ok and service or false
  end
  if not VIM then return false end
  local camera = workspace.CurrentCamera
  local size = camera and camera.ViewportSize or Vector2.new(800, 600)
  return pcall(function() VIM:SendMouseButtonEvent(size.X / 2, size.Y / 2, 0, down, game, 0) end)
end
-- the rod: a Tool with FishingRodData (FishingClient.luau:158)
function Fish.rod()
  for _, from in ipairs({ BF.char(), B.LP:FindFirstChild("Backpack") }) do
    for _, tool in ipairs(from and from:GetChildren() or {}) do
      if tool:IsA("Tool") and tool:FindFirstChild("FishingRodData") then return tool end
    end
  end
  return nil
end
function Fish.bait()
  local data = B.LP:FindFirstChild("Data")
  local fishing = data and data:FindFirstChild("FishingData")
  local bait = fishing and fishing:GetAttribute("SelectedBait")   -- FishingClient.luau:112
  return bait ~= nil and bait ~= "None", bait
end
-- What the server tells the client: (player, event, ...) -> "SpawnFishOnBob" = a bite, "ReeledIn" = done (FishingClient.luau:41-85)
function Fish.listen()
  if Fish.listening then return end
  local remote = Net.get("RemoteEvent", "FishingRemote")
  if not remote then return end
  Fish.listening = true
  local ok, conn = BF.game(function()
    return remote.OnClientEvent:Connect(function(player, event)
      if not B.alive or player ~= B.LP then return end
      if event == "SpawnFishOnBob" then Fish.biteAt = now() end
      if event == "ReeledIn" then Fish.reeledAt = now() end
    end)
  end)
  if ok and typeof(conn) == "RBXScriptConnection" then B.own(function() conn:Disconnect() end) end
end
-- the minigame's own frames: PlayerGui.Fishing_Reeling.Minigame.Container.Fish / ReelZone (CatchingMinigame.luau:34-39, 53)
local function minigame()
  local gui = B.LP:FindFirstChild("PlayerGui")
  local reel = gui and gui:FindFirstChild("Fishing_Reeling")
  local frame = reel and reel:FindFirstChild("Minigame")
  local box = frame and frame:FindFirstChild("Container")
  local fish, zone = box and box:FindFirstChild("Fish"), box and box:FindFirstChild("ReelZone")
  if fish and zone and fish.Visible then return fish, zone end
  return nil
end
-- Held while the fish is right of the reel zone: holding moves the zone right (CatchingMinigame.luau:446-450).
local function playMinigame(ctx)
  local appear = now() + 4
  while not minigame() and now() < appear do ctx:beat("Hooked"); task.wait(0.05) end
  local untilAt, holding = now() + 60, false
  while now() < untilAt do
    if ctx.stop then press(false); return false end
    local fish, zone = minigame()
    if not fish then break end
    local want = fish.Position.X.Scale > zone.Position.X.Scale
    if want ~= holding then press(want); holding = want end
    ctx:beat("Reeling in")
    task.wait()
  end
  press(false)
  return true
end
-- one cast: equip, hold to cast, wait for the bite, click, play the reel
local function castOnce(ctx, rod)
  local hum = BF.hum()
  if rod.Parent ~= BF.char() and hum then
    -- (the game's Equipped handler sends "RodEquipped" itself: FishingClient.luau:173-189)
    pcall(function() hum:EquipTool(rod) end)
    ctx:sleep(1, "Taking the rod")
  end
  Fish.biteAt = 0
  local castAt = now()
  press(true)
  ctx:sleep(O.fishHold or 1.2, "Casting")
  press(false)
  SEA.casts += 1
  local untilAt = now() + (O.fishWait or 60)
  while Fish.biteAt < castAt and now() < untilAt do
    if ctx.stop then return "stopped" end
    ctx:beat("Waiting for a bite")
    task.wait(0.05)
  end
  if Fish.biteAt < castAt then
    -- (a click with the line out and no bite reels it in: FishingClient.luau:104-107)
    press(true); task.wait(0.05); press(false)
    ctx:sleep(1.5, "No bite")
    return "nothing"
  end
  SEA.bites += 1
  press(true); task.wait(0.05); press(false)                         -- the reaction the game waits for (FishingClient.luau:526-535)
  playMinigame(ctx)
  local done = now() + 4
  while Fish.reeledAt < castAt and now() < done do ctx:beat("Reeled in"); task.wait(0.1) end
  SEA.reeled += 1
  Fish.sinceSell += 1
  ctx:progress()
  return "caught"
end
local function sellFish(ctx)
  local home = BF.root() and BF.root().Position
  local ok, why = toNpc(ctx, "Fisherman")                          -- NPCFishClient.luau:1414 (the NPC's name)
  if ok then
    local sent, text = jobs(8, "FishingNPC", "SellFish")         -- NPCFishClient.luau:1093 -> a sentence
    last.fish = sent and tostring(text or "Sold.") or ("No answer: " .. tostring(text))
    if sent then SEA.sold += 1 end
  else
    last.fish = "Sell: " .. tostring(why)
  end
  BF.say("Fisherman: " .. last.fish)
  Fish.sinceSell = 0
  if home then BF.fly(home, ctx, { note = "Back to the fishing spot" }) end
  BF.release()
end
-- bait is crafted: "Bait","Check" lists it, then Net "Craft" Check / Craft (NPCFishClient.luau:897-947, 37-56; CraftWindow.luau:964)
local function buyBait(ctx)
  local ok, why = toNpc(ctx, "Fisherman")
  if not ok then return false, why end
  local sent, info = jobs(8, "FishingNPC", "Bait", "Check", "Fisherman")
  if not sent or type(info) ~= "table" then return false, "no bait list" end
  local want, name = tostring(O.fishBait or ""), nil
  for _, row in ipairs(type(info.All) == "table" and info.All or {}) do
    if type(row) == "table" and row.Unlocked and (want == "" or string.lower(tostring(row.Name)) == string.lower(want)) then name = row.Name; break end
  end
  if not name then return false, "no bait of that name is open to you" end
  local checked, recipe = Net.ask(8, "Craft", "Check", name)
  local result = checked and type(recipe) == "table" and recipe.Result
  if type(result) ~= "table" or not result.Recipe then return false, "the recipe was not given" end
  if result.Could == false then return false, tostring(result.ErrorMessage or "cannot craft it") end
  local made, answer = Net.ask(8, "Craft", "Craft", result.Recipe, 1, {})
  if not (made and answer) then return false, "the craft was refused" end
  BF.say("Bait crafted: " .. tostring(name))
  return true
end
local function fishLoop(ctx)
  Fish.listen()
  local misses = 0
  while B.alive and not ctx.stop do
    if not ctx:body(40) then return end
    BF.release()       -- (fishing never holds the body: the game turns it to cast and a moving body loses the line)
    local rod = Fish.rod()
    if not rod then BF.say("Fishing: no rod in the backpack"); Config.set("bloxfruits.fishFarm", false); return end
    if not Fish.bait() then
      local ok, why = false, "no bait equipped"
      if O.fishBuyBait == true then ok, why = buyBait(ctx) end
      if not ok or not Fish.bait() then
        BF.say("Fishing: " .. tostring(why) .. (ok and "; equip it in the inventory" or ""))
        Config.set("bloxfruits.fishFarm", false)
        return
      end
    end
    local result = castOnce(ctx, rod)
    if result == "stopped" then press(false); return end
    if result == "nothing" then misses += 1 else misses = 0 end
    if misses >= 5 then
      BF.say("Fishing: five casts with no bite. Face the water; fishing rests 2 min")
      Fish.restUntil = now() + 120
      return
    end
    if O.fishSell == true and Fish.sinceSell >= (O.fishSellEvery or 20) then sellFish(ctx) end
    task.wait(0.5)
  end
end
-- the Angler's quest, as his dialogue asks it (NPCFishClient.luau:1187-1291)
local function questOnce(ctx)
  once.quest = false
  local ok, why = toNpc(ctx, "Angler")
  if not ok then last.fish = "Angler: " .. tostring(why); BF.release(); return end
  local spoke, info = jobs(8, "FishingNPC", "Angler", "Speak")
  if not spoke or type(info) ~= "table" then last.fish = "The Angler did not answer."; BF.release(); return end
  local level = type(info.LevelData) == "table" and tonumber(info.LevelData.level) or 0
  if level < 20 then
    last.fish = string.format("The Angler wants fishing level 20 (you: %d).", level)
  else
    local _, check = jobs(8, "FishingNPC", "Angler", "CheckQuest")
    if type(check) == "table" and check.TurnInText then
      last.fish = tostring(check.TurnInText)
    elseif info.canAccept then
      local sent, given, text = jobs(8, "FishingNPC", "Angler", "AskQuest")
      last.fish = (sent and given) and tostring(text or "Quest taken.") or tostring(text or "Not now.")
    else
      last.fish = info.IsInQuest and "You are on his quest already." or "He has no quest for you now."
    end
  end
  BF.say("Angler: " .. last.fish)
  ctx:progress()
  BF.release()
end

-- ---------------------------------------------------------------- crafting
local Craft = {}
-- the keys the game's own crafters pass to Net "Craft" "Check", and who they are:
-- scrolls: DialoguesList.luau:3542 (DialoguesList.Scroll = NPC "Dragon Talon Sage", NPCList.luau:1519-1526);
-- Shark Hunter: DialoguesList.luau:3415; Beast Hunter: 3508; Fossil Expert: 3342; Dragon Hunter: DialoguesList/NPCs/DragonHunter.luau:92.
-- What each takes: Modules/Data/CraftingRecipes.luau:38-52.
Craft.LIST = {
  { "CommonScroll", "Common Scroll", "Dragon Talon Sage" }, { "RareScroll", "Rare Scroll", "Dragon Talon Sage" },
  { "LegendaryScroll", "Legendary Scroll", "Dragon Talon Sage" }, { "MythicalScroll", "Mythical Scroll", "Dragon Talon Sage" },
  { "ToothNecklace", "Shark Tooth Necklace", "Shark Hunter" }, { "TerrorJaw", "Terror Jaw", "Shark Hunter" }, { "SharkAnchor", "Monster Magnet (Shark Anchor)", "Shark Hunter" },
  { "LeviathanCrown", "Leviathan Crown", "Beast Hunter" }, { "LeviathanShield", "Leviathan Shield", "Beast Hunter" }, { "LeviathanBoat", "Beast Hunter boat", "Beast Hunter" },
  { "TRexSkull", "T-Rex Skull", "Fossil Expert" }, { "DinoHood", "Dino Hood", "Fossil Expert" },
  { "Dragonheart", "Dragonheart", "Dragon Hunter" }, { "Dragonstorm", "Dragonstorm", "Dragon Hunter" }, { "Volcanic Magnet", "Volcanic Magnet", "Dragon Hunter" },
}
function Craft.row(key)
  for _, row in ipairs(Craft.LIST) do
    if row[1] == key then return row end
  end
  return nil
end
-- "Shark Tooth 3/10, Terror Eyes 0/2" from the recipe's Required (its shape is not in the client: read loosely) and the stash
function Craft.needs(required)
  local stash = BF.etcItems and BF.etcItems(true) or {}
  local parts = {}
  for key, value in pairs(type(required) == "table" and required or {}) do
    local name, need = key, value
    if type(value) == "table" then name, need = value.Name or value[1] or key, value.Amount or value.Required or value[2] end
    local have = stash and tonumber(stash[tostring(name)])
    parts[#parts + 1] = string.format("%s %s/%s", tostring(name), have and tostring(have) or "?", tostring(need))
  end
  return table.concat(parts, ", ")
end
-- Net "Craft" "Check", key (DialoguesList.luau:3320, 3391, 3486; DragonHunter.luau:69) -> { Required, Result, ResultStats }
function Craft.check(key)
  local ok, answer = Net.ask(8, "Craft", "Check", key)
  if not ok then return nil, "No answer: " .. tostring(answer) end
  if type(answer) ~= "table" then return nil, "The game gave no recipe for it." end
  local result = type(answer.Result) == "table" and answer.Result or {}
  local text = string.format("%s: %s. Needs %s", tostring(result.Name or key), result.Could and "can be crafted" or tostring(result.ErrorMessage or "cannot be crafted yet"),
    Craft.needs(answer.Required))
  if key == "SharkAnchor" then
    -- (the Shark Hunter shows it only once the first two are crafted: DialoguesList.luau:3418-3423)
    local asked, open = Net.ask(8, "Craft", "PossibleHardcode", "SharkAnchor")
    if asked and open ~= true then text = text .. " Locked: craft the necklace and the jaw first." end
  end
  return answer, text
end
local function craftOnce(ctx)
  local key = once.craft
  once.craft = nil
  local row = Craft.row(key or "")
  if not row then return end
  -- (the craft window is opened at the crafter: the body is taken there first, if the crafter can be found)
  if npcAt(row[3]) then toNpc(ctx, row[3]) end
  local answer, text = Craft.check(key)
  if answer and type(answer.Result) == "table" and answer.Result.Recipe and answer.Result.Could ~= false then
    -- CraftWindow.luau:964  u1:InvokeServer("Craft", a2.Recipe, u17, tbl_upv_4)  (u17 = amount, 1 at first: line 553; tbl_upv_4 = {} : line 55)
    local made, result = Net.ask(10, "Craft", "Craft", answer.Result.Recipe, 1, {})
    if made and result then
      SEA.crafts += 1
      local got = type(result) == "table" and type(result.Result) == "table" and result.Result.Name or row[2]
      text = "Crafted: " .. tostring(got)
    else
      text = "The server refused: " .. tostring(result)
    end
  end
  last.craft = text
  BF.say("Craft: " .. text)
  Window.toast({ title = "Craft", text = text, icon = "hammer", time = 8 })
  ctx:progress()
  BF.release()
end

-- ---------------------------------------------------------------- start
local function start()
  -- the ember watch (it costs nothing until an ember is put in workspace)
  B.connect(workspace.ChildAdded, function(child) if O.kitsuneFarm == true then Kit.watch(child) end end, "bloxfruits.seaEmbers")
  -- the helm: after Roblox's VehicleController and before the next frame's ShipController step (Movement.luau:177-180)
  B.connect(S.RunService.Heartbeat, function()
    local d = Boat.drive
    if not d then return end
    local job = BF.running()
    local seat, hum = d.seat, BF.hum()
    if not (job and job.id == "seaSail" and seat and seat.Parent and hum and seat.Occupant == hum) then Boat.drive = nil; return end
    seat.ThrottleFloat = d.throttle
    seat.SteerFloat = d.steer
  end, "bloxfruits.seaDrive")

  BF.job({ id = "seaEvents", label = "Sea events", priority = 62, switch = "bloxfruits.seaEvents", quiet = 25, patience = 300,
    want = function() return O.seaEvents == true and BF.sea() ~= 1 and (#Ev.targets() > 0 or Ev.back) end, run = eventsLoop })
  BF.job({ id = "seaBoatBuy", label = "Buy a boat", priority = 73, quiet = 25, patience = 120,
    want = function() return once.buy == true end,
    run = function(ctx)
      once.buy = false
      Boat.buy(ctx, O.seaBoat or "")
      BF.release()
    end })
  BF.job({ id = "seaCraft", label = "Craft", priority = 74, quiet = 25, patience = 120, want = function() return once.craft ~= nil end, run = craftOnce })
  BF.job({ id = "fishQuest", label = "Angler quest", priority = 71, quiet = 25, patience = 120, want = function() return once.quest == true end, run = questOnce })
  BF.job({ id = "prehistoricEggs", label = "Dragon eggs", priority = 69, switch = "bloxfruits.prehistoricEggs", quiet = 25, patience = 120,
    want = function() return O.prehistoricEggs == true and BF.sea() == 3 and #Pre.eggs() > 0 end, run = eggsLoop })
  BF.job({ id = "kitsune", label = "Azure embers", priority = 68, switch = "bloxfruits.kitsuneFarm", quiet = 25, patience = 120, want = kitsuneWanted, run = kitsuneLoop })
  BF.job({ id = "mirage", label = "Mirage Island", priority = 67, switch = "bloxfruits.mirageFarm", quiet = 30, patience = 240,
    want = function()
      if (O.mirageFarm ~= true and not Mir.go) or BF.sea() ~= 3 then return false end
      local part = Mir.part()
      if not part then Mir.go = false; return false end
      return Mir.go == true or not Mir.done[part]
    end,
    run = function(ctx) Mir.go = false; mirageLoop(ctx) end })
  BF.job({ id = "seaSail", label = "Sail", priority = 35, switch = "bloxfruits.seaSail", quiet = 25, patience = 300,
    want = function() return O.seaSail == true and BF.sea() ~= 1 and now() >= sail.restUntil end, run = sailLoop })
  BF.job({ id = "fishing", label = "Fishing", priority = 33, switch = "bloxfruits.fishFarm", quiet = 30, patience = 240,
    want = function() return O.fishFarm == true and now() >= (Fish.restUntil or 0) and Fish.rod() ~= nil end, run = fishLoop })
end

-- ---------------------------------------------------------------- the tab
local function countLine()
  return string.format("%d sea kills  ·  %d deaths at sea  ·  %d boats  ·  %d Mirage visits  ·  %d embers  ·  %d eggs", SEA.kills, SEA.deaths, SEA.boats, SEA.mirage,
    SEA.embers, SEA.eggs)
end
local function fishLine()
  return string.format("%d casts  ·  %d bites  ·  %d reeled  ·  %d sales  ·  %d crafts", SEA.casts, SEA.bites, SEA.reeled, SEA.sold, SEA.crafts)
end
local function zoneLine()
  local boat = Boat.mine()
  local seat = boat and boat:FindFirstChild("VehicleSeat")
  local root = BF.root()
  local at = (seat and seat.Position) or (root and root.Position)
  local gap = at and Zone.land(at)
  local level, raw = Zone.danger()
  return string.format("%s  ·  danger %d (raw %d)  ·  %s from land", boat and "Boat out" or "No boat out", level, math.floor(raw), gap and (math.floor(gap) .. " st") or "?")
end
local function liveCard(page)
  local live = page:section({ title = "At sea so far", icon = "activity", full = true })
  local counts = live:note({ icon = "gauge", text = countLine() })
  local fish = live:note({ icon = "target", text = fishLine() })
  local zone = live:note({ icon = "compass", text = "..." })
  Motion.every(function()
    if not (counts.frame.Parent and Window.anyOpen()) then return end
    counts.set(countLine())
    fish.set(fishLine())
    local ok, text = pcall(zoneLine)
    zone.set(ok and text or "...")
  end, 1, "bloxfruits.seaStatus")
end
local function boatCard(page)
  local s = page:section({ title = "Boat", icon = "anchor", desc = "Sails your own boat with its own helm." })
  s:dropdown({ id = "bloxfruits.seaBoat", label = "Boat", options = Boat.options() })
  s:button({ id = "bloxfruits.seaBuyNow", label = "Get this boat", desc = "Flies to a boat dealer and buys it.", text = "Buy", run = function() once.buy = true end })
  s:toggle({ id = "bloxfruits.seaSail", label = "Sail", desc = "Takes the boat out and keeps it there.", default = false, children = function(sub)
    sub:segmented({ id = "bloxfruits.seaZone", label = "Out to", options = { { "distance", "Distance" }, { "danger", "Danger level" } }, width = 260 })
    sub:slider({ id = "bloxfruits.seaDistance", label = "Distance from land", min = 200, max = 5000, step = 100, default = 1200, suffix = " st" })
    sub:slider({ id = "bloxfruits.seaDanger", label = "Danger level", tip = "Third Sea only; shown on the compass.", min = 1, max = 6, step = 1, default = 3 })
    sub:toggle({ id = "bloxfruits.seaKeep", label = "Keep sailing while waiting", desc = "Circles slowly instead of stopping.", default = false, bindable = false })
    sub:toggle({ id = "bloxfruits.seaBuy", label = "Buy one when I have none", desc = "Buys the boat picked above.", default = false, bindable = false })
  end })
  local said = s:note({ icon = "info", text = last.boat })
  Motion.every(function()
    if not (said.frame.Parent and Window.anyOpen()) then return end
    said.set("Dealer: " .. last.boat)
  end, 1, "bloxfruits.seaBoatNote")
end
local function eventOptions()
  local out = {}
  for _, row in ipairs(Ev.KINDS) do out[#out + 1] = { row[1], row[2] } end
  return out
end
local function eventsCard(page)
  local s = page:section({ title = "Sea events", icon = "swords", desc = "Leaves the boat, fights, comes back." })
  s:toggle({ id = "bloxfruits.seaEvents", label = "Fight sea events", desc = "Fights the ticked ones while they are out.", default = false, children = function(sub)
    sub:multi({ id = "bloxfruits.seaEventPick", label = "Which", options = eventOptions(), default = { "shark", "piranha", "terror", "crew", "ghost" } })
    sub:slider({ id = "bloxfruits.seaFightHeight", label = "Height above it", min = 6, max = 60, step = 1, default = 20, suffix = " st" })
    sub:toggle({ id = "bloxfruits.seaReturn", label = "Back to the boat after", desc = "Sits at the helm again.", default = true, bindable = false })
  end })
  s:note({ icon = "info", text = "Sea beasts and the Leviathan keep their health off the Humanoid: not fought." })
end
local function islandCards(page)
  local mirage = page:section({ title = "Mirage Island", icon = "mountain", column = 2, desc = "Third Sea, when it rises." })
  mirage:toggle({ id = "bloxfruits.mirageFarm", label = "Mirage Island", desc = "Top of the island, then the fruit dealer.", default = false, children = function(sub)
    sub:slider({ id = "bloxfruits.mirageWait", label = "Stay on the top", min = 2, max = 60, step = 1, default = 5, suffix = " s" })
  end })
  mirage:button({ id = "bloxfruits.mirageGo", label = "Go now", desc = "Once, while the island is up.", text = "Go", run = function() Mir.go = true end })
  mirage:note({ icon = "info", text = "Blue gear: not built, the game's code never names it." })
  mirage:note({ icon = "package", text = "Its chests: turn on the chest farm in Loot." })
  local kitsune = page:section({ title = "Kitsune Island", icon = "moon", column = 2, desc = "Third Sea, blue moon." })
  kitsune:toggle({ id = "bloxfruits.kitsuneFarm", label = "Azure embers", desc = "Catches the embers the shrine sends.", default = false, children = function(sub)
    sub:toggle({ id = "bloxfruits.kitsuneOffer", label = "Offer them at the shrine", desc = "When no ember is left.", default = false, bindable = false })
    sub:toggle({ id = "bloxfruits.kitsuneWake", label = "Wake the shrine", desc = "Touches the statue on a full moon.", default = false, bindable = false })
  end })
  local said = kitsune:note({ icon = "info", text = last.kitsune })
  local pre = page:section({ title = "Prehistoric Island", icon = "flame", column = 2, desc = "Third Sea." })
  pre:toggle({ id = "bloxfruits.prehistoricEggs", label = "Dragon eggs", desc = "Takes eggs when you are in the event.", default = false, bindable = false })
  pre:note({ icon = "info", text = "Dino bones: not built, nothing in the client picks them up." })
  local frozen = page:section({ title = "Frozen Dimension", icon = "snowflake", column = 2 })
  frozen:note({ icon = "info", text = "Not built: the client holds only its name, nothing to collect." })
  Motion.every(function()
    if not (said.frame.Parent and Window.anyOpen()) then return end
    said.set("Shrine: " .. last.kitsune)
  end, 1, "bloxfruits.seaKitsuneNote")
end
local function fishCard(page)
  local s = page:section({ title = "Fishing", icon = "target", desc = "Stand facing water. Uses the game's own rod." })
  s:toggle({ id = "bloxfruits.fishFarm", label = "Auto fish", desc = "Casts, strikes on the bite, reels in.", default = false, children = function(sub)
    sub:slider({ id = "bloxfruits.fishHold", label = "Hold to cast", min = 0.3, max = 3, step = 0.1, default = 1.2, suffix = " s" })
    sub:slider({ id = "bloxfruits.fishWait", label = "Wait for a bite", min = 10, max = 180, step = 5, default = 60, suffix = " s" })
    sub:toggle({ id = "bloxfruits.fishSell", label = "Sell fish", desc = "At the Fisherman, then back.", default = false, children = function(sub2)
      sub2:slider({ id = "bloxfruits.fishSellEvery", label = "Every", min = 5, max = 100, step = 5, default = 20, suffix = " fish" })
    end })
    sub:toggle({ id = "bloxfruits.fishBuyBait", label = "Craft bait when out", desc = "At the Fisherman.", default = false, bindable = false })
    sub:input({ id = "bloxfruits.fishBait", label = "Bait name", placeholder = "empty = the first open one" })
  end })
  s:button({ id = "bloxfruits.fishQuestNow", label = "Angler quest", desc = "Flies to the Angler and asks.", text = "Ask", run = function() once.quest = true end })
  local said = s:note({ icon = "info", text = last.fish })
  Motion.every(function()
    if not (said.frame.Parent and Window.anyOpen()) then return end
    said.set(last.fish)
  end, 1, "bloxfruits.seaFishNote")
end
local function craftCard(page)
  local s = page:section({ title = "Crafting", icon = "hammer", column = 2, desc = "The game's own craft call." })
  local options = {}
  for _, row in ipairs(Craft.LIST) do options[#options + 1] = { row[1], row[2] } end
  s:dropdown({ id = "bloxfruits.craftItem", label = "Make", options = options })
  s:button({ id = "bloxfruits.craftCheck", label = "Check", desc = "Asks what it needs. Crafts nothing.", text = "Check", run = function()
    task.spawn(function()
      local _, text = Craft.check(O.craftItem or "")
      last.craft = text
      Window.toast({ title = "Craft", text = text, icon = "hammer", time = 8 })
    end)
  end })
  s:button({ id = "bloxfruits.craftNow", label = "Craft", desc = "Flies to its crafter and makes one.", text = "Craft", run = function()
    if Craft.row(O.craftItem or "") then once.craft = O.craftItem end
  end })
  local said = s:note({ icon = "info", text = last.craft })
  Motion.every(function()
    if not (said.frame.Parent and Window.anyOpen()) then return end
    said.set(last.craft)
  end, 1, "bloxfruits.seaCraftNote")
end
local function sea(page)
  liveCard(page)
  if BF.sea() == 1 then
    local note = page:section({ title = "Second and Third Sea", icon = "anchor" })
    note:note({ icon = "info", text = "Boats, sea events and the rare islands work in the Second and Third Sea." })
  else
    boatCard(page)
    eventsCard(page)
    if BF.sea() == 3 then
      islandCards(page)
    else
      local note = page:section({ title = "Rare islands", icon = "mountain", column = 2 })
      note:note({ icon = "info", text = "Mirage, Kitsune and Prehistoric work in the Third Sea." })
    end
  end
  fishCard(page)
  craftCard(page)
end

BF.parts[#BF.parts + 1] = { id = "sea", start = start, sea = sea,
  defaults = { seaBoat = "", seaSail = false, seaZone = "distance", seaDistance = 1200, seaDanger = 3, seaKeep = false, seaBuy = false, seaEvents = false,
    seaEventPick = { "shark", "piranha", "terror", "crew", "ghost" }, seaFightHeight = 20, seaReturn = true, mirageFarm = false, mirageWait = 5,
    kitsuneFarm = false, kitsuneOffer = false, kitsuneWake = false, prehistoricEggs = false, fishFarm = false, fishHold = 1.2, fishWait = 60, fishSell = false,
    fishSellEvery = 20, fishBuyBait = false, fishBait = "", craftItem = "CommonScroll" } }
end
do -- bloxfruits_world.lua
-- ============================================================================
--  Blox Fruits     the world: going places, buying things, other servers
--
--  Travel: one job, "Travel", owns the body only while a trip is set: an
--  island (the game's own Locations zones), a quest giver, an NPC, a player.
--  Seas: the game's own commands (TravelMain / TravelDressrosa / TravelZou),
--  and the hub follows across the teleport. Shop: the commands each NPC's
--  dialogue sends, with the answer put in words the way that dialogue does.
--  Server: the game's own server list (ReplicatedStorage.__ServerBrowser).
--
--  Dump: Volt\workspace\dumps\2753915549\4630\fast\ (paths below are under it).
--  Nothing here was run on the live game: every call is unproven.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion = B.S, B.Config, B.Window, B.Motion
local BF = B.BloxFruits
local O = BF.O
local function now() return os.clock() end

local function commas(n)
  local text = tostring(math.floor(tonumber(n) or 0))
  local out = text:reverse():gsub("(%d%d%d)", "%1,"):reverse()
  return (out:gsub("^,", ""))
end
local function toast(title, text, good)
  BF.say(title .. ": " .. text)
  Window.toast({ title = title, text = text, icon = "info", tone = good and "ok" or nil, time = 5 })
end
-- (a command whose answer is shown: the click thread is not held while the server thinks)
local function later(fn) task.spawn(function() B.try("bloxfruits.world", fn) end) end
-- the game's own client refuses a sea change or a hop while the character is "InCombat"
-- (StarterGui/ServerBrowser/LocalScript.luau:394-397)
local function inCombat()
  local character = BF.char()
  return character ~= nil and character:GetAttribute("InCombat") and true or false
end

-- ============================================================================ places
-- Islands: workspace._WorldOrigin.Locations holds one BasePart per island, a sphere zone (its SpecialMesh
-- scales it: radius = Size.X * Mesh.Scale.X / 2, StarterCharacterScripts/LastSpawnPoint.luau:178-191). Its
-- centre may be inside the rock, so a trip lands on a player spawn inside the zone when there is one
-- (_WorldOrigin.PlayerSpawns/<team>/<model>/<parts>, LastSpawnPoint.luau:157-163), else above the centre.
local function spawnParts()
  local origin = workspace:FindFirstChild("_WorldOrigin")
  local folder = origin and origin:FindFirstChild("PlayerSpawns")
  local out = {}
  for _, team in ipairs(folder and folder:GetChildren() or {}) do
    for _, model in ipairs(team:GetChildren()) do
      for _, part in ipairs(model:GetChildren()) do
        if part:IsA("BasePart") then out[#out + 1] = part.Position end
      end
    end
  end
  return out
end
local function landing(zone)
  local mesh = zone:FindFirstChildWhichIsA("SpecialMesh")
  local radius = mesh and zone.Size.X * mesh.Scale.X / 2 or zone.Size.X / 2
  local best, bestGap
  for _, point in ipairs(spawnParts()) do
    local gap = (point - zone.Position).Magnitude
    if gap <= radius and (not bestGap or gap < bestGap) then best, bestGap = point, gap end
  end
  return best and best + Vector3.new(0, 5, 0) or zone.Position + Vector3.new(0, 30, 0)
end
-- label -> where to land. Two zones of one name (Skylands has three) are told apart by a number.
local function islands()
  local origin = workspace:FindFirstChild("_WorldOrigin")
  local folder = origin and origin:FindFirstChild("Locations")
  local out, order, seen = {}, {}, {}
  for _, zone in ipairs(folder and folder:GetChildren() or {}) do
    if zone:IsA("BasePart") then
      seen[zone.Name] = (seen[zone.Name] or 0) + 1
      local label = seen[zone.Name] > 1 and string.format("%s (%d)", zone.Name, seen[zone.Name]) or zone.Name
      out[label] = zone
      order[#order + 1] = label
    end
  end
  table.sort(order)
  return out, order
end
-- quest givers of this sea, from the farm part's catalogue (GuideModule's NPCList: NPCName + Position)
local function givers()
  local out, order = {}, {}
  if type(BF.quests) ~= "function" then return out, order end
  for _, quest in ipairs(BF.quests()) do
    if not out[quest.giver] then
      out[quest.giver] = quest.at
      order[#order + 1] = quest.giver
    end
  end
  table.sort(order)
  return out, order
end
-- NPCs: near ones stand in workspace.NPCs, the rest are parked in ReplicatedStorage.NPCs by the game's
-- own NPC loader (ReplicatedStorage/NPCManager/NPC/NPCInitialization.luau:236, :429). Both keep their place.
-- A model is there only within a couple of hundred studs (measured, NOTES.md), so every NPC the engine has ever
-- seen (BF.npcSeen, kept on disk a file a sea) is listed too. Nearest first, as the body would fly it (portals too).
local function npcs()
  local out, order = {}, {}
  local function add(name, at)
    if out[name] == nil and typeof(at) == "Vector3" and at.Magnitude > 1 then
      out[name] = at
      order[#order + 1] = name
    end
  end
  local function scan(folder)
    for _, model in ipairs(folder and folder:GetChildren() or {}) do
      if model:IsA("Model") and not out[model.Name] then
        local ok, pivot = pcall(model.GetPivot, model)
        if ok and pivot then add(model.Name, pivot.Position) end
      end
    end
  end
  scan(workspace:FindFirstChild("NPCs"))
  scan(S.ReplicatedStorage:FindFirstChild("NPCs"))
  for name, at in pairs(BF.npcSeen or {}) do add(name, at) end
  local root = BF.root()
  if root and type(BF.trip) == "function" then
    local from, length = root.Position, {}
    for _, name in ipairs(order) do
      local ok, d = pcall(BF.trip, from, out[name])
      length[name] = ok and tonumber(d) or (out[name] - from).Magnitude
    end
    table.sort(order, function(a, b)
      if length[a] ~= length[b] then return length[a] < length[b] end
      return a < b
    end)
  else
    table.sort(order)
  end
  return out, order
end
-- a player by name or shown name: exact first, then the start of it
local function findPlayer(text)
  text = string.lower(tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", ""))
  if text == "" then return nil end
  local prefix
  for _, player in ipairs(S.Players:GetPlayers()) do
    if player ~= B.LP then
      local name, shown = string.lower(player.Name), string.lower(player.DisplayName)
      if name == text or shown == text then return player end
      if not prefix and (string.sub(name, 1, #text) == text or string.sub(shown, 1, #text) == text) then prefix = player end
    end
  end
  return prefix
end
local function playerPoint(player)
  local character = player and player.Character
  local root = character and character:FindFirstChild("HumanoidRootPart")
  return root and root.Position
end

-- ============================================================================ the Travel job
-- trip = { name, find = fn() -> Vector3 or nil, follow = moving target, tries }; nil = no trip, and the job wants nothing
local trip
BF.tripLine = "No trip."
local function finish(text)
  trip = nil
  BF.tripLine = text
  BF.say(text)
end
local function travel(ctx)
  local mine = trip
  while B.alive and not ctx.stop and trip == mine and mine do
    if not ctx:body(40) then finish("Trip to " .. mine.name .. " given up: no body"); return end
    local point = mine.find()
    if not point then finish(mine.name .. " is not there any more: trip ended"); return end
    BF.tripLine = string.format("Going to %s  ·  %d studs", mine.name, math.floor(((BF.root() and BF.root().Position or point) - point).Magnitude))
    local ok, why = BF.fly(point, ctx, { note = "To " .. mine.name })
    if trip ~= mine then return end
    if ok then
      -- (a player walks on: flown to again, at most four times, while they are more than 60 studs from where we landed)
      local moved = mine.follow and mine.find()
      if moved and (moved - point).Magnitude > 60 and (mine.legs or 0) < 4 then
        mine.legs = (mine.legs or 0) + 1
      else
        BF.release()
        ctx:progress()
        finish("Arrived at " .. mine.name)
        return
      end
    elseif why == "stopped" then
      return
    else
      mine.tries = (mine.tries or 0) + 1
      if mine.tries >= 3 then finish(string.format("Trip to %s failed three times (%s)", mine.name, tostring(why))); return end
      ctx:sleep(2, "Trying again: " .. tostring(why))
    end
    task.wait()
  end
end
local function go(name, find, follow)
  if not find() then toast("Travel", name .. " was not found here.", false); return end
  trip = { name = name, find = find, follow = follow, tries = 0, legs = 0 }
  BF.tripLine = "Setting off for " .. name
end

-- ============================================================================ seas
-- CommF_ "TravelMain" / "TravelDressrosa" / "TravelZou": what the game's server menu sends
-- (StarterGui/ServerBrowser/LocalScript.luau:447, :458, :469) and the sea captains' "Yes" (ReplicatedStorage/DialoguesList.luau:740, :641, :693).
local SEAS = {
  { sea = 1, label = "First Sea", command = "TravelMain", need = "No requirement (Sea Captain, DialoguesList.luau:740)." },
  { sea = 2, label = "Second Sea", command = "TravelDressrosa", need = "Level 700, then the Detective's key, the Ice Admiral beaten." },
  { sea = 3, label = "Third Sea", command = "TravelZou", need = "Level 1,500, Don Swan beaten, King Red Head's quest done." },
}
local function changeSea(entry)
  if BF.sea() == entry.sea then toast(entry.label, "You are in it already.", false); return end
  if inCombat() then toast(entry.label, "Not while in combat: the game refuses it too.", false); return end
  later(function()
    local ok, answer = BF.invoke(15, entry.command)       -- ServerBrowser/LocalScript.luau:405 (CommF_:InvokeServer(a2))
    if not ok then toast(entry.label, "No answer: " .. tostring(answer), false); return end
    -- (the captains show the answer as their line of text, DialoguesList.luau:641: so it is shown as it came)
    toast(entry.label, "The server said: " .. (answer == nil and "nothing (a teleport may follow)" or tostring(answer)), answer == nil)
  end)
end
-- What the game itself asks when its server menu loads: Second Sea is open when TalkedDetective, UsedKey and
-- KilledIceBoss are all true (LocalScript.luau:510-526); Third Sea when ZQuestProgress "Check" answers 1 (:555-567).
local function checkSeas()
  later(function()
    local ok2, second = BF.invoke(8, "DressrosaQuestProgress")   -- ServerBrowser/LocalScript.luau:510
    local ok3, third = BF.invoke(8, "ZQuestProgress", "Check")   -- ServerBrowser/LocalScript.luau:555
    local parts = {}
    if ok2 and type(second) == "table" then
      parts[#parts + 1] = string.format("Second Sea: detective %s, key %s, Ice Admiral %s", second.TalkedDetective and "yes" or "no",
        second.UsedKey and "yes" or "no", second.KilledIceBoss and "yes" or "no")
    else
      parts[#parts + 1] = "Second Sea: no answer"
    end
    parts[#parts + 1] = "Third Sea: " .. (ok3 and (third == 1 and "open" or "not yet (" .. tostring(third) .. ")") or "no answer")
    toast("Seas", table.concat(parts, ".  "), ok2 and ok3)
  end)
end
-- CommF_ "SetSpawnPoint", no argument (the Set Home Point NPC, DialoguesList.luau:416):
-- 0 = only Pirates can, -1 = failed, anything else = set.
local function setSpawn()
  later(function()
    local ok, answer = BF.invoke(8, "SetSpawnPoint")
    if not ok then toast("Home point", "No answer: " .. tostring(answer), false)
    elseif answer == 0 then toast("Home point", "Only Pirates can set a home point.", false)
    elseif answer == -1 then toast("Home point", "Failed to set the home point.", false)
    else toast("Home point", "Home point set (" .. tostring(answer) .. ").", true) end
  end)
end
-- The hub comes back on the far side of a teleport (a sea change, a hop, a rejoin): exactly as glorybound.lua does.
-- What is queued cannot be taken back on every executor, so the queued text first reads a file this switch writes:
-- "off" there and it loads nothing. (getgenv does not cross a teleport; a file in the workspace does.)
local FOLLOW_FLAG = "BasedHub/bloxfruits/follow.txt"
local function writeFlag(on)
  if type(writefile) ~= "function" then return end
  pcall(function()
    if type(makefolder) == "function" and type(isfolder) == "function" then
      if not isfolder("BasedHub") then makefolder("BasedHub") end
      if not isfolder("BasedHub/bloxfruits") then makefolder("BasedHub/bloxfruits") end
    end
    writefile(FOLLOW_FLAG, on and "on" or "off")
  end)
end
-- the executor's own way to empty the queue, under either name it goes by (nil when it has none)
local function clearQueue()
  if type(clear_teleport_queue) == "function" then return clear_teleport_queue end
  if type(clearteleportqueue) == "function" then return clearteleportqueue end
  return nil
end
local function follow()
  local World = B.World
  if not Config.get("bloxfruits.travelFollow") then
    writeFlag(false)
    -- (emptied where the executor can: then a later switch-on queues afresh. Emptying takes all that is queued, but
    -- the hub's own come-back is held off by World.queued while this one is queued, so it is only this one.)
    local clear = clearQueue()
    if BF.queued and clear and pcall(clear) then
      BF.queued = false
      B.genv.BASED_FOLLOWING = nil
      if World then World.queued = false end
    end
    return
  end
  writeFlag(true)
  -- (a dev build run with getgenv().BASED_FILE set comes back as that file, and carries the name over again)
  local file = type(B.genv.BASED_FILE) == "string" and B.genv.BASED_FILE or "BasedHub.lua"
  -- (what is queued stacks, and outlives a hub that was run again: the mark names the file queued, so the same file is
  -- not queued twice and another one is, after it; the last one queued is the one that comes back, World.followText)
  if (World and World.queued) or BF.queued or B.genv.BASED_FOLLOWING == file or type(queue_on_teleport) ~= "function" then return end
  BF.queued = true
  B.genv.BASED_FOLLOWING = file
  if World then World.queued = true end
  local gate = string.format('local flagOk, flag = pcall(readfile, %q); if flagOk and flag == "off" then return end', FOLLOW_FLAG)
  local carry = string.format('%s getgenv().BASED_FILE = %q; getgenv().BASED_INTRO = "off"', gate, file)
  pcall(queue_on_teleport, World and World.followText and World.followText(file, carry) or string.format('pcall(function() %s; loadstring(readfile(%q))() end)', carry, file))
end

-- TODO portals (NOT built, by rule): the game's own client sends CommF_ "requestEntrance", <Vector3 or a name>
-- (StarterPlayerScripts/AnimateEntrance.luau:89) and, when the answer is a Vector3, sets the root's CFrame to it
-- itself (:90-93). It is called with a part's position when the body touches an entrance (:954, :1145, :1194),
-- with a TeleportSpawn position (:638, :689), and with names ("WaterfallBossHitbox" :372, "TurtleEntranceBoss" :426).
-- Using it would mean moving the body outside BF.fly: it needs an engine door first (see the report).

-- ============================================================================ abilities
-- BuyHaki goes through the Ability Teacher's Library.buyAbility (DialoguesList/Library.luau:498):
-- 1 = learned, 0 = not enough money, 2 = already known. Prices are the teacher's own words (NPCs/HakiTeacher.luau:50, :71, :92).
-- Observation is the Instinct Teacher's: KenTalk "Start" 0 = known, 1 = offered, else too weak; KenTalk "Buy" 0 = learned
-- (DialoguesList.luau:2013, :2054; price at :2044).
local ABILITIES = {
  { key = "Geppo", label = "Sky jump (Geppo)", price = 10000 },          -- NPCs/HakiTeacher.luau:38
  { key = "Buso", label = "Buso haki (Aura)", price = 25000 },          -- NPCs/HakiTeacher.luau:59
  { key = "Soru", label = "Flash step (Soru)", price = 100000 },        -- NPCs/HakiTeacher.luau:80
  { key = "Ken", label = "Observation (Instinct)", price = 750000, ken = true },
}
local owned, lastTry, tooWeak = {}, {}, {}
local function buyKen()
  local ok, start = BF.invoke(8, "KenTalk", "Start")                     -- DialoguesList.luau:2013
  if not ok then return false, "no answer: " .. tostring(start) end
  if start == 0 then owned.Ken = true; return false, "already known" end
  if start ~= 1 then tooWeak.Ken = now() + 600; return false, "the teacher says you are not strong enough yet" end
  local sent, answer = BF.invoke(8, "KenTalk", "Buy")                   -- DialoguesList.luau:2054
  if not sent then return false, "no answer: " .. tostring(answer) end
  if answer == 0 then owned.Ken = true; return true, "learned" end
  return false, "not enough money"
end
local function buyAbility(entry)
  lastTry[entry.key] = now()
  if entry.ken then return buyKen() end
  local ok, answer = BF.invoke(8, "BuyHaki", entry.key)                 -- DialoguesList/Library.luau:498
  if not ok then return false, "no answer: " .. tostring(answer) end
  if answer == 1 then owned[entry.key] = true; return true, "learned" end
  if answer == 2 then owned[entry.key] = true; return false, "already known" end
  if answer == 0 then return false, "not enough money" end
  return false, "unexpected answer " .. tostring(answer)
end
local function knows(entry)
  if owned[entry.key] then return true end
  -- (a body that owns Buso carries the tag "Buso", StarterCharacterScripts/Aura: measured in NOTES.md)
  if entry.key == "Buso" then
    local character, has = BF.char(), false
    if character then pcall(function() has = character:HasTag("Buso") end) end
    return has
  end
  return false
end
-- the switch: each ability not owned, when Beli allows, at most once every 30 s each; one at a time
local buying = false
local function autoAbilities()
  if not O.autoAbilities or buying then return end
  local beli = tonumber(BF.data("Beli")) or 0
  for _, entry in ipairs(ABILITIES) do
    if not knows(entry) and beli >= entry.price and now() - (lastTry[entry.key] or -1e9) >= 30 and (tooWeak[entry.key] or 0) < now() then
      buying = true
      task.spawn(function()
        local good, text = buyAbility(entry)
        buying = false
        BF.say(entry.label .. ": " .. text)
        if good then Window.toast({ title = "Bought", text = entry.label .. " learned.", icon = "zap", tone = "ok", time = 5 }) end
      end)
      return
    end
  end
end

-- ============================================================================ dealers
-- CommF_ "BuyItem", name (DialoguesList/ItemPurchase.luau:1308): 1 = bought, 0 = not enough money, 2 = owned,
-- 3 = a level is needed (the second answer is the level). Prices: Shop.LEGACY_BELI_ITEMS[name].Price, read live.
local ITEM_DEALERS = {
  { id = "shopGun", title = "Weapon Dealer", items = { "Slingshot", "Musket", "Flintlock" } },                -- DialoguesList.luau:38, :50, :62
  { id = "shopGun2", title = "Advanced Weapons Dealer", items = { "Refined Slingshot", "Dual Flintlock", "Cannon" } }, -- :87, :99, :111
  { id = "shopSword1", title = "Sword Dealer", items = { "Katana", "Cutlass" } },                            -- :139, :151
  { id = "shopSword2", title = "Sword Dealer of the West", items = { "Dual Katana", "Iron Mace" } },          -- :176, :188
  { id = "shopSword3", title = "Sword Dealer of the East", items = { "Triple Katana", "Pipe" } },            -- :213, :225
  { id = "shopSword4", title = "Master Sword Dealer", items = { "Dual-Headed Blade", "Bisento" } },           -- :250, :262
  -- (accessories: same command, same answers; each has a condition of its own in LEGACY_BELI_ITEMS.luau:81-129)
  { id = "shopWear", title = "Accessories", items = { "Black Cape", "Tomoe Ring", "Swordsman Hat" } },        -- :2988, :3057, NPCs/Hasan.luau:89
}
local prices
local function price(name)
  if prices == nil then
    prices = BF.mod("Shop", "LEGACY_BELI_ITEMS") or false
  end
  local item = prices and prices[name]
  return type(item) == "table" and tonumber(item.Price) or nil
end
local function buyItem(name)
  later(function()
    local ok, answer, level = BF.invoke(10, "BuyItem", name)
    if not ok then toast(name, "No answer: " .. tostring(answer), false)
    elseif answer == 1 then toast(name, "Bought.", true)
    elseif answer == 0 then toast(name, "Not enough Beli.", false)
    elseif answer == 2 then toast(name, "You own it already.", false)
    elseif answer == 3 then toast(name, "You need level " .. tostring(level) .. ".", false)
    else toast(name, "The server said " .. tostring(answer) .. ".", false) end
  end)
end
-- Fighting style teachers: CommF_ "Buy<Style>" with no argument buys (with `true` it only asks). Words per answer
-- as each teacher says them; Electric answers differently (DialoguesList.luau:2246-2276).
local STYLE_WORDS = { [1] = "learned", [0] = "not enough money (or fragments)", [2] = "you know it already", [3] = "you are not strong enough yet" }
local ELECTRO_WORDS = { [1] = "learned", [3] = "not enough money", [4] = "you are still in combat", [0] = "you need a Lightning Bolt", [2] = "you know it already" }
local STYLES = {
  { command = "BuyBlackLeg", label = "Dark Step", cost = "$150,000" },                       -- DialoguesList.luau:2114
  { command = "BuyElectro", label = "Electric", cost = "$500,000 + a Lightning Bolt", words = ELECTRO_WORDS }, -- :2246
  { command = "BuyFishmanKarate", label = "Water Kung-fu", cost = "$750,000" },              -- :2381
  { command = "BuySuperhuman", label = "Superhuman", cost = "$3,000,000" },                  -- :1045
  { command = "BuyDeathStep", label = "Death Step", cost = "$2,500,000 + 5,000 F" },         -- :2451
  { command = "BuySharkmanKarate", label = "Sharkman Karate", cost = "$2,500,000 + 5,000 F" }, -- :2653
  { command = "BuyElectricClaw", label = "Electric Claw", cost = "$3,000,000 + 5,000 F" },   -- :2828 (first a 30 s run, "Start", :2806: not done here)
  { command = "BuyDragonTalon", label = "Dragon Talon", cost = "$3,000,000 + 5,000 F" },     -- NPCs/TalonTeacher.luau:52
  { command = "BuyGodhuman", label = "Godhuman", cost = "$5,000,000 + 5,000 F" },            -- :2532
  { command = "BuySanguineArt", label = "Sanguine Art", cost = "$5,000,000 + 5,000 F" },     -- :2731
}
local function buyStyle(command)
  local style
  for _, entry in ipairs(STYLES) do if entry.command == command then style = entry end end
  if not style then return end
  later(function()
    local ok, answer = BF.invoke(10, style.command)
    local words = style.words or STYLE_WORDS
    if not ok then toast(style.label, "No answer: " .. tostring(answer), false)
    elseif type(answer) == "string" then toast(style.label, answer, false)
    else toast(style.label, words[answer] or ("the server said " .. tostring(answer)), answer == 1) end
  end)
end
-- Boats: CommF_ "BuyBoat", <BoatInfo key> (DialoguesList/Library.luau:525); 1 bought, 0 money, 2 the spawn is blocked,
-- 3 game pass, 4 locked (:526-553). The list is the dealer's own (Modules/BoatInfo.luau getForDealer, Pirate / Marine by team).
local BOAT_WORDS = { [1] = "bought", [0] = "not enough money", [2] = "another boat is blocking the spawn", [3] = "you do not own the game pass", [4] = "that boat is locked for now" }
local function boats()
  local info = BF.mod("Modules", "BoatInfo")
  local options = {}
  if not (info and type(info.getForDealer) == "function" and type(info.List) == "table") then return options end
  local pirates = S.Teams:FindFirstChild("Pirates")
  local ok, list = BF.game(info.getForDealer, (pirates and B.LP.Team == pirates) and "Pirate" or "Marine")
  for _, key in ipairs(ok and type(list) == "table" and list or {}) do
    local boat = info.List[key]
    if type(boat) == "table" then options[#options + 1] = { key, string.format("%s  ·  %s", tostring(boat.DisplayName), commas(boat.Cost)) } end
  end
  return options
end
local function buyBoat(key)
  later(function()
    local ok, answer = BF.invoke(10, "BuyBoat", key)
    if not ok then toast("Boat", "No answer: " .. tostring(answer), false)
    else toast("Boat", BOAT_WORDS[answer] or ("the server said " .. tostring(answer)), answer == 1) end
  end)
end
-- Haki colour (the Barista Cousin): "ColorsDealer", "1" names today's colour (or 1 = Aura too weak);
-- "ColorsDealer", "2" buys it: 1 obtained, 0 money, 2 known, else gone (DialoguesList.luau:1941, :1956-1973).
local function colourOffer()
  later(function()
    local ok, name, tier = BF.invoke(8, "ColorsDealer", "1")
    if not ok then toast("Haki colour", "No answer: " .. tostring(name), false)
    elseif name == 1 then toast("Haki colour", "Your Aura is not strong enough yet.", false)
    elseif name then toast("Haki colour", string.format("On offer: %s (%s).", tostring(name), (tonumber(tier) or 0) >= 3 and "legendary" or "rare"), true)
    else toast("Haki colour", "Nothing on offer.", false) end
