-- ============================================================================ servers
-- The game's server list: ReplicatedStorage.__ServerBrowser (a RemoteFunction). "getjob" = this server's id;
-- a page number 1..100 = { [JobId] = { Count, Region, Bounty } }; "teleport", JobId = join it
-- (StarterGui/ServerBrowser/LocalScript.luau:17, :274, :51). The game asks all 100 pages, one each 1/50 s (:254-311).
local function browser() return S.ReplicatedStorage:FindFirstChild("__ServerBrowser") end
local function ask(remote, timeout, ...)
  local args = table.pack(...)
  local done, out = false, nil
  task.spawn(function()
    out = table.pack(pcall(remote.InvokeServer, remote, table.unpack(args, 1, args.n)))
    done = true
  end)
  local started = now()
  while not done and now() - started < timeout do task.wait() end
  if not done then return false, "timeout" end
  if not out[1] then return false, tostring(out[2]) end
  return true, table.unpack(out, 2, out.n)
end
-- every server the list holds, staggered as the game does; gives up waiting after 25 s
local function listServers(remote, firstOnly)
  local found, finished = {}, 0
  for page = 1, 100 do
    task.delay(page / 50, function()
      local ok, servers = ask(remote, 8, page)
      if ok and type(servers) == "table" then
        for job, info in pairs(servers) do
          if type(info) == "table" then found[job] = tonumber(info.Count) or 0 end
        end
      end
      finished += 1
    end)
  end
  local started = now()
  while finished < 100 and now() - started < 25 and B.alive do
    if firstOnly and next(found) ~= nil and now() - started > 1 then break end
    task.wait(0.1)
  end
  return found
end
local hopping = false
BF.hopLine = ""
local function hopTo(remote, job)
  BF.hopLine = "Asking to join " .. string.sub(job, 1, 8) .. "…"
  local ok, answer = ask(remote, 12, "teleport", job)           -- ServerBrowser/LocalScript.luau:51
  BF.hopLine = ok and ("The server said: " .. tostring(answer)) or ("No answer: " .. tostring(answer))
  BF.say("Hop: " .. BF.hopLine)
  task.wait(12)
  if B.alive then toast("Server hop", "Still here 12 s later. " .. BF.hopLine, false) end
end
local function hop()
  if hopping then return end
  local remote = browser()
  if not remote then toast("Server hop", "The game's server list is not here.", false); return end
  if inCombat() then toast("Server hop", "Not while in combat.", false); return end
  hopping = true
  task.spawn(function()
    B.try("bloxfruits.hop", function()
      local mode = O.hopMode or "fewest"
      if mode == "job" then
        local job = tostring(O.hopJob or ""):gsub("%s", "")
        if #job < 10 then toast("Server hop", "Type a JobId first.", false) return end
        hopTo(remote, job)
        return
      end
      local _, here = ask(remote, 8, "getjob")                   -- ServerBrowser/LocalScript.luau:17
      BF.hopLine = "Reading the server list…"
      local servers = listServers(remote, mode == "any")
      local max = S.Players.MaxPlayers
      local picks = {}
      for job, count in pairs(servers) do
        if job ~= here and job ~= game.JobId and count < max then picks[#picks + 1] = { job, count } end
      end
      if #picks == 0 then BF.hopLine = "No other server with room."; toast("Server hop", BF.hopLine, false) return end
      local pick
      if mode == "fewest" then
        table.sort(picks, function(a, b) return a[2] < b[2] end)
        pick = picks[1]
      else
        pick = picks[Random.new():NextInteger(1, #picks)]
      end
      BF.say(string.format("Hop: %d servers with room; going to one with %d players", #picks, pick[2]))
      hopTo(remote, pick[1])
    end)
    hopping = false
  end)
end
-- Rejoin is Roblox's own TeleportService into this very server (the game's list shows its own server as not joinable).
local function rejoin()
  later(function()
    local ok, err = pcall(function() S.TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, B.LP) end)
    if not ok then
      ok, err = pcall(function() S.TeleportService:Teleport(game.PlaceId, B.LP) end)
    end
    toast("Rejoin", ok and "Teleport asked for." or ("Refused: " .. tostring(err)), ok)
  end)
end
local function serverLine()
  return string.format("%d / %d players  ·  server %s", #S.Players:GetPlayers(), S.Players.MaxPlayers, string.sub(game.JobId ~= "" and game.JobId or "(studio)", 1, 8))
end

-- ============================================================================ start
local function start()
  BF.job({ id = "travel", label = "Travel", priority = 95, quiet = 25, patience = 600,
    want = function() return trip ~= nil end, run = travel })
  Motion.every(function() B.try("bloxfruits.abilities", autoAbilities) end, 0.2, "bloxfruits.abilities")
  Config.on("bloxfruits.travelFollow", follow)
  follow()
end

-- ============================================================================ the tabs
local function options(order, empty)
  local out = {}
  for _, name in ipairs(order) do out[#out + 1] = { name, name } end
  if #out == 0 then out[1] = { "", empty } end
  return out
end
local function travelTab(page)
  local s = page:section({ title = "Go to", icon = "navigation", desc = "Flown there by the hub's own pilot." })
  local state = s:note({ icon = "map-pin", text = BF.tripLine })
  local _, islandOrder = islands()
  s:dropdown({ id = "bloxfruits.travelIsland", label = "Island", options = options(islandOrder, "None found") })
  s:button({ id = "bloxfruits.travelIslandGo", label = "Fly to the island", text = "Go", run = function()
    local name = O.travelIsland
    go(name, function() local zones = islands(); return zones[name] and landing(zones[name]) end)
  end })
  local _, giverOrder = givers()
  s:dropdown({ id = "bloxfruits.travelGiver", label = "Quest giver", options = options(giverOrder, "None found") })
  s:button({ id = "bloxfruits.travelGiverGo", label = "Fly to the quest giver", text = "Go", run = function()
    local name = O.travelGiver
    go(name, function() local at = givers(); return at[name] and at[name] + Vector3.new(0, 5, 0) end)
  end })
  local _, npcOrder = npcs()
  s:dropdown({ id = "bloxfruits.travelNpc", label = "NPC", options = options(npcOrder, "None found") })
  s:button({ id = "bloxfruits.travelNpcGo", label = "Fly to the NPC", text = "Go", run = function()
    local name = O.travelNpc
    go(name, function() local at = npcs(); return at[name] and at[name] + Vector3.new(0, 5, 0) end)
  end })
  s:input({ id = "bloxfruits.travelPlayer", label = "Player", placeholder = "Name or shown name" })
  s:button({ id = "bloxfruits.travelPlayerGo", label = "Fly to the player", text = "Go", run = function()
    local player = findPlayer(O.travelPlayer)
    if not player then toast("Travel", "No player by that name here.", false); return end
    go(player.Name, function() local at = playerPoint(player); return at and at + Vector3.new(0, 4, 0) end, true)
  end })
  s:button({ id = "bloxfruits.travelStop", label = "Stop the trip", text = "Stop", run = function()
    if trip then finish("Trip stopped by hand") end
  end })
  Motion.every(function()
    if not (state.frame.Parent and Window.anyOpen()) then return end
    state.set(BF.tripLine)
  end, 3, "bloxfruits.tripLine")

  local seas = page:section({ title = "Seas", icon = "anchor", column = 2, desc = "The game's own sea change. Not in combat." })
  for _, entry in ipairs(SEAS) do
    seas:button({ id = "bloxfruits.sea" .. entry.sea, label = entry.label, desc = entry.need, text = "Go", run = function() changeSea(entry) end })
  end
  seas:button({ id = "bloxfruits.seaCheck", label = "What is unlocked", desc = "Asks the game, as its server menu does.", text = "Check", run = checkSeas })
  seas:toggle({ id = "bloxfruits.travelFollow", label = "Come back after a teleport", desc = "The hub starts itself again in the new sea.", default = true, bindable = false })
  local home = page:section({ title = "Home point", icon = "flag", column = 2 })
  home:button({ id = "bloxfruits.setSpawn", label = "Set spawn here", desc = "The game's command. Pirates only.", text = "Set", run = setSpawn })
end
local function shopTab(page)
  local skills = page:section({ title = "Abilities", icon = "zap", desc = "Each one bought with the teacher's own command." })
  for _, entry in ipairs(ABILITIES) do
    skills:button({ id = "bloxfruits.buy" .. entry.key, label = entry.label, desc = "$" .. commas(entry.price), text = "Buy", run = function()
      later(function()
        local good, text = buyAbility(entry)
        toast(entry.label, text, good)
      end)
    end })
  end
  skills:toggle({ id = "bloxfruits.autoAbilities", label = "Buy abilities as soon as I can afford them", desc = "Tries each one at most every 30 s.", default = false, bindable = false })

  for index, dealer in ipairs(ITEM_DEALERS) do
    local card = page:section({ title = dealer.title, icon = dealer.id == "shopWear" and "crown" or "package", column = index % 2 == 0 and 2 or 1 })
    local list = {}
    for _, name in ipairs(dealer.items) do
      local cost = price(name)
      list[#list + 1] = { name, cost and string.format("%s  ·  $%s", name, commas(cost)) or name }
    end
    card:dropdown({ id = "bloxfruits." .. dealer.id, label = "Item", options = list })
    card:button({ id = "bloxfruits." .. dealer.id .. "Buy", label = "Buy it", desc = "Spends Beli.", text = "Buy", run = function() buyItem(O[dealer.id]) end })
  end
  local styles = page:section({ title = "Fighting style teachers", icon = "target", column = 2 })
  local list = {}
  for _, style in ipairs(STYLES) do list[#list + 1] = { style.command, style.label .. "  ·  " .. style.cost } end
  styles:dropdown({ id = "bloxfruits.shopStyle", label = "Style", options = list })
  styles:button({ id = "bloxfruits.shopStyleBuy", label = "Learn it", desc = "Spends Beli (and fragments).", text = "Buy", run = function() buyStyle(O.shopStyle) end })
  local boat = page:section({ title = "Boat Dealer", icon = "anchor" })
  local boatList = boats()
  if #boatList == 0 then boatList[1] = { "", "None found" } end
  boat:dropdown({ id = "bloxfruits.shopBoat", label = "Boat", options = boatList })
  boat:button({ id = "bloxfruits.shopBoatBuy", label = "Buy it", desc = "Spends Beli. It appears at a boat spawn.", text = "Buy", run = function()
    if O.shopBoat ~= "" then buyBoat(O.shopBoat) end
  end })
  local colour = page:section({ title = "Haki colour", icon = "gem", column = 2 })
  colour:button({ id = "bloxfruits.colourAsk", label = "Today's colour", desc = "Only asks: spends nothing.", text = "Ask", run = colourOffer })
  colour:button({ id = "bloxfruits.colourBuy", label = "Buy today's colour", desc = "Spends Beli.", text = "Buy", run = colourBuy })
  local team = page:section({ title = "Team", icon = "flag" })
  team:button({ id = "bloxfruits.teamPirates", label = "Join the Pirates", text = "Join", run = function() setTeam("Pirates") end })
  team:button({ id = "bloxfruits.teamMarines", label = "Join the Marines", text = "Join", run = function() setTeam("Marines") end })
end
local function serverTab(page)
  local s = page:section({ title = "This server", icon = "server" })
  local line = s:note({ icon = "server", text = serverLine() })
  s:button({ id = "bloxfruits.copyJob", label = "Copy this server's JobId", text = "Copy", run = function()
    toast("JobId", B.clipboard(game.JobId) and "Copied." or "This executor cannot copy.", true)
  end })
  s:button({ id = "bloxfruits.rejoin", label = "Rejoin", desc = "Back into this same server.", text = "Rejoin", run = rejoin })
  local h = page:section({ title = "Server hop", icon = "radar", column = 2, desc = "Through the game's own server list." })
  h:segmented({ id = "bloxfruits.hopMode", label = "To", options = { { "any", "Any other" }, { "fewest", "Fewest players" }, { "job", "A JobId" } }, width = 300 })
  h:input({ id = "bloxfruits.hopJob", label = "JobId", placeholder = "Paste a JobId" })
  local state = h:note({ icon = "activity", text = "" })
  h:button({ id = "bloxfruits.hop", label = "Hop", text = "Hop", run = hop })
  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    line.set(serverLine())
    state.set(hopping and ("Working…  " .. BF.hopLine) or BF.hopLine)
  end, 1, "bloxfruits.serverLine")
end

-- (the safe-mode card of the combat part hops through this when it is here)
BF.hop = hop

BF.parts[#BF.parts + 1] = { id = "world", start = start, travel = travelTab, shop = shopTab, server = serverTab,
  defaults = { travelIsland = "", travelGiver = "", travelNpc = "", travelPlayer = "", travelFollow = true, autoAbilities = false,
    shopGun = "Slingshot", shopGun2 = "Refined Slingshot", shopSword1 = "Katana", shopSword2 = "Dual Katana", shopSword3 = "Triple Katana",
    shopSword4 = "Dual-Headed Blade", shopWear = "Black Cape", shopStyle = "BuyBlackLeg", shopBoat = "", hopMode = "fewest", hopJob = "" } }
end
do -- bloxstrike.lua
-- ============================================================================
--  BloxStrike   see them, aim at them, know them
--
--  Read from the game on 2026-11-16 (place 114234929420007, universe 7633926880, version 9965: 1,125
--  client scripts decompiled) and measured on an alt the owner chose for it. The game has an anti-
--  cheat of its own; nothing here reads it, works round it or hides from it. Nothing here calls into
--  the game's code or changes it either: every part reads the world and draws over it. (A hook on the
--  game's bullet code was in while the alt's guns broke, until a rejoin: every such hook is gone.
--  based/_work/bloxstrike-1116/NOTES.md.)
--
--   * Who plays (the game's Components.Common.Participants, done here the same way): every Player,
--     and every Folder in ReplicatedStorage.Combatants, a bot. A bot's body is the Model in
--     workspace.Characters whose Bot is true and whose CombatantId is its folder's.
--   * Combatants also holds a child for each player (found by its UserId): with the bots' folders it
--     carries Team, Health, Armor (JSON), Money, HasDefuseKit, Kills, Deaths, for both teams.
--   * Alive (CharacterResolver.isAlivePlayer): a Player whose Dead is false and Health above 0; a bot
--     whose Dead is not true and whose Health, if it has one, is above 0.
--   * The team rule is the game's own (AimAssistController.isEnemyTeam): Team is "Terrorists" or
--     "Counter-Terrorists"; in Deathmatch everyone is an enemy; in Zombie Survival no player is.
--   * The bodies are shells the client makes (Controllers.CharacterController.RemoteCharacters): each
--     frame the game puts a shell's root where the server's pose for it says (BulkMoveTo) and animates
--     the rest. A player the server sends no pose for is hidden: its shell goes to ReplicatedStorage.
--     _PVS_CulledCharacters and its ClientCharacterPresentationVisible to false, and it stays where it
--     was. So a shell in the world is the body where the client knows it is; one out of it is only
--     where it was last seen. A bot out of sight has no model in the world at all.
--   * Zombies are client models in workspace.HordeShells, each with a HordeId (HordeProtocol).
--   * Characters have no Humanoid: R15 parts, a HumanoidRootPart, attributes Health, MaxHealth, Dead,
--     Team, Bot, CombatantId. What a player holds is its Player's CurrentEquipped, JSON { Name, ... }.
--   * Smoke is the folders workspace.Debris.VoxelSmoke_* of SmokeVoxel parts; the game's own aim
--     assist calls a target behind one unseen, and so does this.
--
--  The parts (games/bloxstrike_*.lua) each own one thing: aim, the overlay. This file is what they share.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util

local BS = { parts = {}, log = {}, started = false, bodies = {}, byKey = {} }
B.BloxStrike = BS
BS.PLACE, BS.UNIVERSE, BS.VERSION = 114234929420007, 7633926880, 9965
BS.TEAMS = { Terrorists = true, ["Counter-Terrorists"] = true }
BS.SHOWN = "ClientCharacterPresentationVisible"
BS.R15 = { "Head", "UpperTorso", "LowerTorso", "LeftUpperArm", "LeftLowerArm", "LeftHand", "RightUpperArm", "RightLowerArm", "RightHand",
  "LeftUpperLeg", "LeftLowerLeg", "LeftFoot", "RightUpperLeg", "RightLowerLeg", "RightFoot" }
BS.BONES = { { "Head", "UpperTorso" }, { "UpperTorso", "LowerTorso" }, { "UpperTorso", "LeftUpperArm" }, { "LeftUpperArm", "LeftLowerArm" },
  { "LeftLowerArm", "LeftHand" }, { "UpperTorso", "RightUpperArm" }, { "RightUpperArm", "RightLowerArm" }, { "RightLowerArm", "RightHand" },
  { "LowerTorso", "LeftUpperLeg" }, { "LeftUpperLeg", "LeftLowerLeg" }, { "LeftLowerLeg", "LeftFoot" }, { "LowerTorso", "RightUpperLeg" },
  { "RightUpperLeg", "RightLowerLeg" }, { "RightLowerLeg", "RightFoot" } }

-- ---------------------------------------------------------------- the weapons
-- What each thing in the hand is, from the game's own Database.Custom.Weapons (v9965): automatic or not, the seconds
-- between shots, the range in studs. Kept here as data: nothing reads the game's modules while it runs.
local function gun(auto, rate, range) return { kind = "gun", auto = auto, rate = rate, range = range } end
BS.WEAPONS = {
  ["AK-47"] = gun(true, 0.1, 1200), ["AUG"] = gun(true, 0.1, 1200), ["AWP"] = gun(false, 1.46, 1200),
  ["Desert Eagle"] = gun(false, 0.225, 1200), ["Dual Berettas"] = gun(false, 0.12, 1200), ["FAMAS"] = gun(true, 0.1, 1200),
  ["Five-SeveN"] = gun(false, 0.15, 1200), ["Galil AR"] = gun(true, 0.09, 1200), ["Glock-18"] = gun(false, 0.15, 1200),
  ["M4A1-S"] = gun(true, 0.1, 1200), ["M4A4"] = gun(true, 0.09, 1200), ["MAC-10"] = gun(true, 0.075, 1200),
  ["MAG-7"] = gun(false, 0.88, 120), ["MP9"] = gun(true, 0.07, 1200), ["Negev"] = gun(true, 0.075, 1200),
  ["Nova"] = gun(false, 0.88, 120), ["P250"] = gun(false, 0.15, 1200), ["P90"] = gun(true, 0.07, 1200),
  -- (the R8 fires on a held button: a 0.2 s charge, then again while it is held)
  ["R8 Revolver"] = gun(true, 0.43, 1200),
  ["Sawed-Off"] = gun(false, 0.8, 120), ["SG 553"] = gun(true, 0.1, 1200), ["SSG 08"] = gun(false, 1.25, 1200),
  ["Tec-9"] = gun(false, 0.12, 1200), ["USP-S"] = gun(false, 0.17, 1200), ["XM1014"] = gun(false, 0.35, 120),
  ["Zeus x27"] = gun(false, 0.15, 13.5),
}
-- knives swing again while held, 3 studs; grenades and the bomb are never the triggerbot's
for _, name in ipairs({ "Butterfly Knife", "CT Knife", "Flip Knife", "Gut Knife", "Karambit", "LightSaber", "M9 Bayonet",
  "Skeleton Knife", "Stiletto Knife", "T Knife" }) do
  BS.WEAPONS[name] = { kind = "melee", auto = true, rate = 0.36, range = 3 }
end
for _, name in ipairs({ "Decoy Grenade", "Flashbang", "HE Grenade", "Incendiary Grenade", "Molotov", "Smoke Grenade" }) do
  BS.WEAPONS[name] = { kind = "grenade" }
end
BS.WEAPONS.C4 = { kind = "bomb" }
-- one the table does not know (a weapon added after v9965): told by its name, else taken for a gun held down
local function guess(name)
  local low = string.lower(name)
  if low:find("knife") or low:find("bayonet") or low:find("karambit") or low:find("saber") then return { kind = "melee", auto = true, rate = 0.36, range = 3 } end
  if low:find("grenade") or low:find("molotov") or low:find("flash") or low:find("decoy") or low:find("smoke") then return { kind = "grenade" } end
  if low == "c4" or low:find("bomb") then return { kind = "bomb" } end
  if low:find("glove") or low:find("wrap") then return { kind = "none" } end
  return { kind = "gun", auto = true, rate = 0.1, range = 1200 }
end

-- ---------------------------------------------------------------- the round
function BS.myTeam() return B.LP:GetAttribute("Team") end
function BS.mode() return workspace:GetAttribute("Gamemode") end
function BS.state() return workspace:GetAttribute("GameState") end
-- the zombies mode: the game's own test (Components.Common.IsSurvivalMode) is this one line
function BS.survival()
  return BS.mode() == "Zombie Survival"
end
-- the game's own rule (AimAssistController.isEnemyTeam)
function BS.enemyTeam(team)
  if BS.survival() then return false end
  local mine = BS.myTeam()
  if not (BS.TEAMS[mine] and BS.TEAMS[team]) then return false end
  if BS.mode() == "Deathmatch" then return true end
  return mine ~= team
end
function BS.myCharacter()
  local character = B.LP.Character
  return character and character.Parent and character or nil
end
function BS.alive()
  local character = BS.myCharacter()
  if not character then return false end
  return (tonumber(character:GetAttribute("Health")) or 0) > 0 and character:GetAttribute("Dead") ~= true
    and character:IsDescendantOf(workspace)
end

-- ---------------------------------------------------------------- the bodies
-- One record a participant (or zombie), kept between refreshes: where it was last seen outlives the model.
--   key, participant, name, bot, zombie, team, enemy, alive, character, root, head, parts, health, maxHealth,
--   combatant, money, armor, armorType, kit, kills, deaths, weapon, inWorld, visible, lastPos, lastSeen
local json, jsonCount = {}, 0
local function decode(text)
  if type(text) ~= "string" or text == "" then return nil end
  local known = json[text]
  if known ~= nil then return known or nil end
  local ok, value = pcall(function() return S.HttpService:JSONDecode(text) end)
  if jsonCount > 400 then table.clear(json); jsonCount = 0 end
  json[text], jsonCount = ok and value or false, jsonCount + 1
  return ok and value or nil
end
-- what it holds: the Player's CurrentEquipped (RemoteCharacters.decodeCurrentEquipped), else the model's
local function weaponOf(participant, character)
  local raw = participant and participant:GetAttribute("CurrentEquipped")
  local data = decode(raw)
  if type(data) == "table" and type(data.Name) == "string" then return data.Name end
  if type(raw) == "string" and raw ~= "" and raw:sub(1, 1) ~= "{" then return raw end
  local folder = character and character:FindFirstChild("WeaponModel")
  local equipped = folder and folder:FindFirstChild("Equipped")
  if not equipped then return nil end
  local named = equipped:GetAttribute("Weapon") or equipped:GetAttribute("Name")
  if type(named) == "string" then return named end
  local weapon = equipped:FindFirstChildWhichIsA("Model") or equipped:FindFirstChildOfClass("Folder")
  local name = weapon and (weapon:GetAttribute("Weapon") or weapon:GetAttribute("Name"))
  return type(name) == "string" and name or nil
end
-- What I hold now: { name, rounds, capacity, spec } from my Player's CurrentEquipped (JSON, as the game writes it).
function BS.held()
  local data = decode(B.LP:GetAttribute("CurrentEquipped"))
  if type(data) ~= "table" or type(data.Name) ~= "string" then return nil end
  return { name = data.Name, rounds = tonumber(data.Rounds), capacity = tonumber(data.Capacity), spec = BS.WEAPONS[data.Name] or guess(data.Name) }
end

local function fill(body, character)
  body.character = character
  local root = character and (character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart)
  body.root = root
  body.head = character and character:FindFirstChild("Head") or nil
  local parts = body.parts or {}
  table.clear(parts)
  if character then
    for _, name in ipairs(BS.R15) do
      local part = character:FindFirstChild(name)
      if part and part:IsA("BasePart") then parts[name] = part end
    end
  end
  body.parts = parts
end
BS.fill = fill

-- Is the body in the world right now, posed where the client knows it is? Cheap: the overlay asks it every frame,
-- so a shell the game has just hidden is never drawn where it no longer is, and a new life is taken up at once.
function BS.present(body)
  local participant = body.participant
  if participant and participant:IsA("Player") then
    local character = participant.Character
    if character ~= body.character then fill(body, character) end
  end
  local character, root = body.character, body.root
  if not (character and root and root.Parent) then return false end
  if not character:IsDescendantOf(workspace) then return false end
  if character:GetAttribute(BS.SHOWN) == false or character:GetAttribute("Dead") == true then return false end
  return true
end

local function aliveOf(participant)
  if participant:IsA("Player") then
    -- (the hub's services are cloned references, never == the game's own: the parent is told by its class)
    local parent = participant.Parent
    if not (parent and parent:IsA("Players")) or participant:GetAttribute("Dead") ~= false then return false end
    local health = participant:GetAttribute("Health")
    return type(health) == "number" and health > 0
  end
  if participant:GetAttribute("Dead") == true then return false end
  local health = participant:GetAttribute("Health")
  return type(health) ~= "number" or health > 0
end

local function record(key)
  local body = BS.byKey[key]
  if not body then
    body = { key = key, parts = {} }
    BS.byKey[key] = body
  end
  return body
end

function BS.refresh()
  local now = os.clock()
  local camera = workspace.CurrentCamera
  local eye = camera and camera.CFrame.Position
  -- the combatants' folders: each by its UserId, and the bots among them (a Folder each)
  local byUser, botFolders = {}, {}
  local folder = S.ReplicatedStorage:FindFirstChild("Combatants")
  for _, combatant in ipairs(folder and folder:GetChildren() or {}) do
    local id = combatant:GetAttribute("UserId")
    if type(id) == "number" then byUser[id] = combatant end
    if combatant:IsA("Folder") then botFolders[#botFolders + 1] = combatant end
  end
  -- the bots' bodies in the world, by CombatantId (as Participants.Character finds them)
  local botBodies = {}
  local characters = workspace:FindFirstChild("Characters")
  for _, model in ipairs(characters and characters:GetChildren() or {}) do
    if model:IsA("Model") and model:GetAttribute("Bot") == true then
      local id = model:GetAttribute("CombatantId")
      if id ~= nil and botBodies[id] == nil then botBodies[id] = model end
    end
  end
  local list, seen = {}, {}
  local function settle(body)
    body.inWorld = body.alive and BS.present(body)
    if body.inWorld then
      body.lastPos, body.lastSeen = body.root.Position, now
      body.visible = eye ~= nil and BS.canSee(eye, body.head or body.root, body, true)
    else
      body.visible = false
    end
    if not body.alive then body.lastPos, body.lastSeen = nil, nil end
    list[#list + 1] = body
  end
  local function take(participant, key, isBot, combatant, character)
    seen[key] = true
    local body = record(key)
    body.participant, body.bot, body.zombie, body.combatant = participant, isBot, false, combatant
    local display = isBot and participant:GetAttribute("DisplayName")
    body.name = type(display) == "string" and display or participant.Name
    body.team = participant:GetAttribute("Team")
    body.enemy = BS.enemyTeam(body.team)
    if character and not character.Parent then character = nil end
    if character ~= body.character or (character and not (body.root and body.root.Parent)) then fill(body, character) end
    body.alive = aliveOf(participant)
    body.health = tonumber(participant:GetAttribute("Health")) or (character and tonumber(character:GetAttribute("Health"))) or 0
    body.maxHealth = math.max(1, tonumber(participant:GetAttribute("MaxHealth")) or (character and tonumber(character:GetAttribute("MaxHealth"))) or 100)
    local info = combatant or participant
    body.money = tonumber(info:GetAttribute("Money"))
    body.kit = info:GetAttribute("HasDefuseKit") == true
    body.kills, body.deaths = tonumber(info:GetAttribute("Kills")), tonumber(info:GetAttribute("Deaths"))
    local armor = decode(info:GetAttribute("Armor"))
    body.armor = type(armor) == "table" and tonumber(armor.Health) or nil
    body.armorType = type(armor) == "table" and armor.Type or nil
    body.weapon = body.alive and (weaponOf(participant, character) or body.weapon) or nil
    settle(body)
  end
  for _, player in ipairs(S.Players:GetPlayers()) do
    if player ~= B.LP then take(player, player.UserId, false, byUser[player.UserId], player.Character) end
  end
  for _, bot in ipairs(botFolders) do
    local key = bot:GetAttribute("UserId")
    if key == nil then key = "bot:" .. bot.Name end
    take(bot, key, true, bot, botBodies[bot:GetAttribute("CombatantId")])
  end
  -- the zombies: the client's own models of them
  if BS.survival() then
    local shells = workspace:FindFirstChild("HordeShells")
    for _, model in ipairs(shells and shells:GetChildren() or {}) do
      local id = model:IsA("Model") and model:GetAttribute("HordeId")
      if id ~= nil and id ~= false then
        local key = "z:" .. tostring(id)
        seen[key] = true
        local body = record(key)
        if body.character ~= model or not (body.root and body.root.Parent) then fill(body, model) end
        body.participant, body.combatant = nil, nil
        body.name, body.bot, body.zombie, body.team, body.enemy = "Zombie", true, true, "Zombies", true
        body.health = tonumber(model:GetAttribute("Health")) or 100
        body.maxHealth = math.max(1, tonumber(model:GetAttribute("MaxHealth")) or 100)
        body.alive = model:GetAttribute("Dead") ~= true and body.health > 0
        settle(body)
      end
    end
  end
  for key in pairs(BS.byKey) do
    if not seen[key] then BS.byKey[key] = nil end
  end
  BS.bodies = list
  BS.refreshed = now
end

-- ---------------------------------------------------------------- sight
local rayParams = RaycastParams.new()
rayParams.FilterType = Enum.RaycastFilterType.Exclude
rayParams.IgnoreWater = true
-- the slab test, against one smoke voxel's box
local function hitsBox(origin, dir, low, high, length)
  local tmin, tmax = 0, length
  for _, axis in ipairs({ "X", "Y", "Z" }) do
    local o, d = origin[axis], dir[axis]
    if math.abs(d) < 1e-8 then
      if o < low[axis] or o > high[axis] then return false end
    else
      local t1, t2 = (low[axis] - o) / d, (high[axis] - o) / d
      if t1 > t2 then t1, t2 = t2, t1 end
      tmin, tmax = math.max(tmin, t1), math.min(tmax, t2)
      if tmin > tmax then return false end
    end
  end
  return true
end
function BS.throughSmoke(from, to)
  local debris = workspace:FindFirstChild("Debris")
  if not debris then return false end
  local delta = to - from
  local length = delta.Magnitude
  if length < 1e-3 then return false end
  local dir = delta / length
  for _, cloud in ipairs(debris:GetChildren()) do
    if cloud:IsA("Folder") and cloud.Name:match("^VoxelSmoke_") then
      for _, voxel in ipairs(cloud:GetChildren()) do
        if voxel:IsA("BasePart") and voxel.Name == "SmokeVoxel" then
          local half = voxel.Size * 0.5
          if hitsBox(from, dir, voxel.Position - half, voxel.Position + half, length) then return true end
        end
      end
    end
  end
  return false
end
-- What a bullet passes through, as the game's own rays have it (Components.Common.GetRayIgnore): workspace.Debris,
-- the camera, the map's Cameras, Barriers and Ambience, its Zones.Spawns and Zones.Sites, and your own body.
-- Made again at most four times a second.
local ignoreList, ignoreAt = {}, -1
function BS.rayIgnore()
  local now = os.clock()
  if now - ignoreAt < 0.25 then return ignoreList end
  ignoreAt = now
  local list = {}
  local function add(instance) if instance then list[#list + 1] = instance end end
  add(workspace:FindFirstChild("Debris"))
  add(workspace.CurrentCamera)
  add(BS.myCharacter())
  local map = workspace:FindFirstChild("Map")
  if map then
    for _, name in ipairs({ "Cameras", "Barriers", "Ambience" }) do add(map:FindFirstChild(name)) end
    local zones = map:FindFirstChild("Zones")
    if zones then
      for _, name in ipairs({ "Spawns", "Sites" }) do add(zones:FindFirstChild(name)) end
    end
  end
  ignoreList = list
  return list
end

-- Can `part` of `body` be seen from `from`: nothing solid between, by the game's own rule of what a bullet passes
-- through, and no smoke.
function BS.canSee(from, part, body, smoke)
  if not (part and part.Parent) then return false end
  rayParams.FilterDescendantsInstances = BS.rayIgnore()
  local to = part.Position
  local hit = workspace:Raycast(from, to - from, rayParams)
  if hit and not (body.character and hit.Instance:IsDescendantOf(body.character)) then return false end
  if smoke ~= false and BS.throughSmoke(from, to) then return false end
  return true
end

-- ---------------------------------------------------------------- picking a target
-- The parts an aim may go for, in the order "Closest" tries them.
BS.AIM_PARTS = { Head = { "Head" }, Chest = { "UpperTorso" }, Body = { "UpperTorso", "LowerTorso" },
  Closest = { "Head", "UpperTorso", "LowerTorso" } }
-- The best enemy for the crosshair now: { body, part, screen, distance, pixels } or nil.
--   opts: fov (px), part ("Head"|"Chest"|"Body"|"Closest"), visible (bool), smoke (bool), range (studs), sticky (body)
function BS.pick(opts)
  local camera = workspace.CurrentCamera
  if not camera then return nil end
  local view = camera.ViewportSize
  local center = Vector2.new(view.X * 0.5, view.Y * 0.5)
  local from = camera.CFrame.Position
  local best, bestScore = nil, math.huge
  local names = BS.AIM_PARTS[opts.part or "Head"] or BS.AIM_PARTS.Head
  for _, body in ipairs(BS.bodies) do
    if body.enemy and body.alive and body.health > 0 and BS.present(body) then
      for _, name in ipairs(names) do
        local part = body.parts[name] or (name == "Head" and body.head) or nil
        if part and part.Parent then
          local point, onScreen = camera:WorldToViewportPoint(part.Position)
          local distance = (part.Position - from).Magnitude
          if onScreen and point.Z > 0 and distance <= (opts.range or 2000) then
            local pixels = (Vector2.new(point.X, point.Y) - center).Magnitude
            if pixels <= (opts.fov or 120) then
              -- (the one already held is kept unless another is clearly nearer the crosshair)
              local score = pixels * (body == opts.sticky and 0.6 or 1)
              if score < bestScore and (not opts.visible or BS.canSee(from, part, body, opts.smoke)) then
                best, bestScore = { body = body, part = part, screen = Vector2.new(point.X, point.Y), distance = distance, pixels = pixels }, score
              end
            end
          end
        end
      end
    end
  end
  return best
end

-- ---------------------------------------------------------------- the log, the line on the page
function BS.note(text)
  local log = BS.log
  log[#log + 1] = { at = os.clock(), text = text }
  if #log > 40 then table.remove(log, 1) end
  BS.status = text
end
local function statusLine()
  local parts = { tostring(BS.mode() or "?"), tostring(BS.state() or "?") }
  local team = BS.myTeam()
  parts[#parts + 1] = BS.TEAMS[team] and team or "no team yet"
  local enemies, seen = 0, 0
  for _, body in ipairs(BS.bodies) do
    if body.enemy and body.alive then
      enemies += 1
      if body.inWorld then seen += 1 end
    end
  end
  parts[#parts + 1] = string.format("%d enemies alive, %d in sight", enemies, seen)
  return table.concat(parts, "  ·  ")
end
BS.statusLine = statusLine

-- ---------------------------------------------------------------- the tabs
local function extend(kind, page)
  for _, part in ipairs(BS.parts) do
    if part[kind] then B.try("bloxstrike." .. part.id .. "." .. kind, part[kind], page) end
  end
end
local function has(kind)
  for _, part in ipairs(BS.parts) do
    if part[kind] then return true end
  end
  return false
end

local function start(hub)
  -- the bodies, ten times a second: cheap, and every part reads the same records
  -- (Motion.every's second argument is how many times a second)
  Motion.every(function() B.try("bloxstrike.refresh", BS.refresh) end, 10, "bloxstrike.refresh")
  -- and at once when a body comes into the world or someone joins, so a peek is not a tenth of a second late
  -- (the folder is watched again if a new map brings a new one)
  local function soon() BS.dirty = true end
  local watched, watch = nil, nil
  local function follow()
    local characters = workspace:FindFirstChild("Characters")
    if characters == watched then return end
    if watch then pcall(function() watch:Disconnect() end) end
    watched, watch = characters, nil
    if characters then watch = characters.ChildAdded:Connect(soon) end
    soon()
  end
  follow()
  Motion.every(follow, 0.5, "bloxstrike.characters")
  B.own(function() if watch then pcall(function() watch:Disconnect() end) end end)
  B.connect(S.Players.PlayerAdded, soon, "bloxstrike.players")
  B.connect(S.RunService.Heartbeat, function()
    if BS.dirty then
      BS.dirty = false
      B.try("bloxstrike.refresh", BS.refresh)
    end
  end, "bloxstrike.soon")
end

B.game({
  id = "bloxstrike",
  name = "BloxStrike",
  tagline = "See them. Hit them. Know them.",
  universes = { BS.UNIVERSE },
  places = { BS.PLACE },
  icon = "crosshair",
  -- (the universal ESP and aim read Humanoids, which this game's bodies do not have: its own are here instead;
  -- movement is the server's in this game. Kept: the server tools.)
  universal = { "world" },
  tabs = function(hub)
    start(hub)
    for _, part in ipairs(BS.parts) do
      if part.start then B.try("bloxstrike." .. part.id, part.start, hub) end
    end
    BS.started = true
    hub:page({ id = "aim", title = "Aim", icon = "crosshair", build = function(page)
      local you = page:section({ title = "Round", icon = "activity", full = true })
      local line = you:note({ icon = "info", text = statusLine() })
      Motion.every(function()
        if not (line.frame.Parent and Window.anyOpen()) then return end
        line.set(statusLine())
      end, 1, "bloxstrike.status")
      extend("aim", page)
    end })
    if has("visuals") then
      hub:page({ id = "visuals", title = "Visuals", icon = "eye", build = function(page) extend("visuals", page) end })
    end
    if has("info") then
      hub:page({ id = "info", title = "Intel", icon = "radar", build = function(page) extend("info", page) end })
    end
  end,
})
end
do -- bloxstrike_aim.lua
-- ============================================================================
--  BloxStrike   the aim: assist and triggerbot
--
--  Read from the game (CameraController, InputController.Actions.Fire, AimAssistController), version 9965:
--   * CameraController reads CurrentCamera.CFrame every frame at RenderPriority.Camera + 1 and builds the
--     view from it, adding its own pull (for pads and phones) and the weapon's kick. Turning the camera
--     just before that step is how the game's own assist does it, and how this one does.
--   * A shot goes down the view's centre (with the weapon's spread), from the Fire action on the left
--     mouse button: the triggerbot presses that same button.
--  Nothing here changes the game's code. (Silent aim, no recoil and no spread did, through hooks on the
--  game's bullet and camera tables; they were taken out on 2026-11-16 after the alt's guns broke while
--  one of them was in: based/_work/bloxstrike-1116/NOTES.md.)
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util
local BS = B.BloxStrike

local aim = { fired = 0 }
BS.aim = aim

local function start(hub)
  local map = {}
  for id, default in pairs({ assist = false, assistKey = "rmb", assistPart = "Head", assistFov = 140, assistSmooth = 40,
    visibleOnly = true, smoke = true, showFov = false, trigger = false, triggerDelay = 40, triggerHead = false }) do
    Config.define("bloxstrike." .. id, default)
    map[id] = "bloxstrike." .. id
  end
  local O = Config.mirror(map)
  aim.options = O

  -- ---------------------------------------------------------------- aim assist: the camera turned before the game's own step
  local function held()
    if O.assistKey == "always" then return true end
    return S.UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
  end
  local name = "BASED.bloxstrike.assist"
  pcall(function()
    S.RunService:BindToRenderStep(name, Enum.RenderPriority.Camera.Value, function(dt)
      if not (O.assist and BS.alive() and held()) then aim.locked = nil; return end
      local camera = workspace.CurrentCamera
      if not camera then return end
      local target = BS.pick({ fov = O.assistFov, part = O.assistPart, visible = O.visibleOnly, smoke = O.smoke, sticky = aim.locked, range = 2000 })
      aim.locked = target and target.body or nil
      if not target then return end
      local from = camera.CFrame.Position
      local want = (target.part.Position - from).Unit
      local have = camera.CFrame.LookVector
      -- smoothing the same at any frame rate: the share of the gap closed each sixtieth of a second
      local keep = math.clamp(O.assistSmooth / 100, 0, 0.98)
      local close = 1 - keep ^ (math.max(dt, 1 / 240) * 60)
      local look = have:Lerp(want, close)
      if look.Magnitude < 1e-3 then return end
      camera.CFrame = CFrame.lookAt(from, from + look.Unit)
    end)
  end)
  B.own(function() pcall(function() S.RunService:UnbindFromRenderStep(name) end) end)

  -- ---------------------------------------------------------------- the circle
  local circle
  if type(Drawing) == "table" and Drawing.new then
    local ok, made = pcall(Drawing.new, "Circle")
    if ok then
      circle = made
      circle.Thickness, circle.NumSides, circle.Filled, circle.Transparency = 1, 64, false, 0.6
      circle.Color = Color3.fromRGB(255, 255, 255)
      circle.Visible = false
      B.own(function() pcall(function() circle:Remove() end) end)
    end
  end
  -- (every frame: Motion.every's rate is times a second, nil for every frame; 0 is never, which hid this circle until 11-16)
  Motion.every(function()
    if not circle then return end
    local camera = workspace.CurrentCamera
    circle.Visible = O.showFov and BS.alive() and camera ~= nil
    if circle.Visible then
      local view = camera.ViewportSize
      circle.Position = Vector2.new(view.X * 0.5, view.Y * 0.5)
      circle.Radius = O.assistFov
      circle.Color = aim.locked and Color3.fromRGB(255, 90, 90) or Color3.fromRGB(255, 255, 255)
    end
  end, nil, "bloxstrike.fov")

  -- ---------------------------------------------------------------- triggerbot: fires the way the weapon in hand fires
  -- Held down for an automatic (and the R8 and a knife), tapped once per its fire rate for a semi-automatic, only within
  -- the weapon's range, never with a grenade or the bomb, never on an empty magazine (BS.WEAPONS, the game's own data).
  -- The crosshair's ray is the game's: from the camera down its look, through what a bullet passes through.
  -- Only while you play: the mouse locked to the centre (no menu open), nothing typed into, the hub's window shut.
  -- A button you hold yourself is left alone, and never let go by it.
  local UIS = S.UserInputService
  local TAP = 0.04 -- how long a tap holds the button: long enough for the game to see it
  local triggerParams = RaycastParams.new()
  triggerParams.FilterType = Enum.RaycastFilterType.Exclude
  local trig = { down = false, since = nil, lastShot = -1, lostAt = nil, why = "off" }
  aim.trig = trig
  local function button(down)
    local ok = false
    if down and type(mouse1press) == "function" then ok = pcall(mouse1press)
    elseif not down and type(mouse1release) == "function" then ok = pcall(mouse1release) end
    if not ok then
      pcall(function()
        local camera = workspace.CurrentCamera
        local view = camera.ViewportSize
        S.VirtualInputManager:SendMouseButtonEvent(view.X * 0.5, view.Y * 0.5, 0, down, game, 0)
      end)
    end
  end
  local function press()
    if trig.down then return end
    -- (the button already down is the player's own)
    if UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then return end
    button(true)
    trig.down, trig.lastShot = true, os.clock()
    aim.fired += 1
  end
  local function release()
    if not trig.down then return end
    button(false)
    trig.down, trig.lostAt = false, nil
  end
  aim.release = release
  local function playing()
    if not BS.alive() then return false, "dead" end
    if UIS:GetFocusedTextBox() then return false, "typing" end
    if UIS.MouseBehavior ~= Enum.MouseBehavior.LockCenter then return false, "a menu is open" end
    if Window.anyOpen() then return false, "the hub is open" end
    return true
  end
  local function underCrosshair(range)
    local camera = workspace.CurrentCamera
    if not camera then return nil end
    local look = camera.CFrame
    triggerParams.FilterDescendantsInstances = BS.rayIgnore()
    local hit = workspace:Raycast(look.Position, look.LookVector * math.min(range, 2000), triggerParams)
    if not hit then return nil end
    for _, body in ipairs(BS.bodies) do
      if body.enemy and body.alive and body.character and hit.Instance:IsDescendantOf(body.character) and BS.present(body) then
        if O.triggerHead and hit.Instance ~= body.head then return nil end
        if O.smoke and BS.throughSmoke(look.Position, hit.Position) then return nil end
        return body
      end
    end
    return nil
  end
  local function stop(why)
    trig.since, trig.why = nil, why
    release()
  end
  B.connect(S.RunService.Heartbeat, function()
    if not O.trigger then return stop("off") end
    local ok, why = playing()
    if not ok then return stop(why) end
    local held = BS.held()
    local spec = held and held.spec
    if not (spec and (spec.kind == "gun" or spec.kind == "melee")) then return stop("not a gun in hand") end
    if spec.kind == "gun" and held.rounds == 0 then return stop("empty") end
    local body = underCrosshair((spec.range or 1200) + (spec.kind == "melee" and 1 or 0))
    local now = os.clock()
    if body then
      trig.lostAt, trig.why = nil, "on " .. tostring(body.name)
      trig.since = trig.since or now
      if now - trig.since < O.triggerDelay / 1000 then return end
      if spec.auto then
        press()
      elseif trig.down then
        if now - trig.lastShot >= TAP then release() end
      elseif now - trig.lastShot >= (spec.rate or 0.15) + 0.01 then
        press()
      end
    else
      trig.since, trig.why = nil, "waiting"
      if trig.down then
        if spec.auto then
          -- (a moment's grace: a body flickering at the crosshair's edge does not cut a spray short)
          trig.lostAt = trig.lostAt or now
          if now - trig.lostAt >= 0.06 then release() end
        elseif now - trig.lastShot >= TAP then
          release()
        end
      end
    end
  end, "bloxstrike.trigger")
  B.own(release)
end

local PARTS = { { "Head", "Head" }, { "Chest", "Chest" }, { "Body", "Body" }, { "Closest", "Closest" } }
local function aimCards(page)
  local box = page:section({ title = "Aim assist", icon = "crosshair", desc = "Turns your view onto them." })
  box:toggle({ id = "bloxstrike.assist", label = "Aim assist", desc = "Pulls the view to the nearest enemy.", default = false })
  box:segmented({ id = "bloxstrike.assistKey", label = "When", desc = "Right mouse held, or always.", options = { { "rmb", "Right mouse" }, { "always", "Always" } }, default = "rmb", width = 200 })
  box:dropdown({ id = "bloxstrike.assistPart", label = "Aim at", desc = "Where on the body.", options = PARTS, default = "Head" })
  box:slider({ id = "bloxstrike.assistFov", label = "Reach", desc = "Pixels from the crosshair.", min = 20, max = 600, step = 10, default = 140, suffix = " px" })
  box:slider({ id = "bloxstrike.assistSmooth", label = "Smoothing", desc = "0 snaps; higher is gentler.", min = 0, max = 95, step = 5, default = 40, suffix = "%" })
  box:toggle({ id = "bloxstrike.visibleOnly", label = "Only who you can see", desc = "Not through walls.", default = true })
  box:toggle({ id = "bloxstrike.smoke", label = "Not through smoke", desc = "As the game's own assist.", default = true })

  -- (a feature of its own, at the owner's ask: on or off, whatever aim assist is set to)
  local fov = page:section({ title = "FOV circle", icon = "target", desc = "The aim's reach, drawn round the crosshair." })
  fov:toggle({ id = "bloxstrike.showFov", label = "Show FOV circle", desc = "As wide as Reach; red while it holds someone.", default = false })

  local gun = page:section({ title = "Triggerbot", icon = "zap", desc = "Fires the way your weapon fires." })
  gun:toggle({ id = "bloxstrike.trigger", label = "Triggerbot", desc = "Fires while an enemy is under the crosshair.", default = false })
  gun:slider({ id = "bloxstrike.triggerDelay", label = "Reaction", desc = "Wait before the first shot.", min = 0, max = 300, step = 10, default = 40, suffix = " ms" })
  gun:toggle({ id = "bloxstrike.triggerHead", label = "Only on the head", desc = "Waits for the head.", default = false })
  local count = gun:note({ icon = "info", text = "" })

  Motion.every(function()
    if not (count.frame.Parent and Window.anyOpen()) then return end
    local trig = aim.trig
    count.set(string.format("Triggerbot %d shots  ·  %s%s", aim.fired, trig and trig.why or "off",
      aim.locked and ("  ·  aim on " .. tostring(aim.locked.name)) or ""))
  end, 1, "bloxstrike.aim.line")
end

BS.parts[#BS.parts + 1] = { id = "aim", start = start, aim = aimCards }
end
do -- bloxstrike_esp.lua
-- ============================================================================
--  BloxStrike   the overlay: ESP, "last seen", the enemy panel, the bomb
--
--  Read from the game, version 9965:
--   * The bodies are BS.bodies (games/bloxstrike.lua). Each frame the game poses every shell it has a pose
--     for (RemoteCharacters: the root put where the server's pose says, the rest animated) and builds the
--     view (CameraController, RenderPriority.Camera + 1). The overlay is drawn after both, at
--     RenderPriority.Last + 100, so a box sits on the body in the frame it is shown, not one frame behind.
--   * Whether a body is in the world is asked every frame (BS.present): a shell the game has just hidden
--     is not drawn where it no longer is. One the game has hidden is only where it was last seen: the
--     client has no pose for it, so neither has this.
--   * Walls do not hide what is drawn (the drawings and chams are on top of everything), nor does distance
--     past the range slider's top.
--   * The planted bomb is a model tagged "Bomb" (Controllers.Observers.Game.BombPlanted): its attribute
--     BombPlanted is JSON { Time, TimeUntilExplode, ... } (40 s as the game reads it when missing), and
--     IsGettingDefused, Defused, Exploding say the rest.
--   * Every combatant's Money, Armor, HasDefuseKit and Health are on its folder, for both teams.
--  Drawn with the executor's Drawing objects, made once a body and reused; nothing is put in the game's world.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util
local BS = B.BloxStrike

local esp = { pools = {}, chams = {}, panelLines = {}, frames = 0 }
BS.esp = esp

local ENEMY, COVER, MATE, GHOST = Color3.fromRGB(255, 84, 84), Color3.fromRGB(186, 120, 255), Color3.fromRGB(86, 168, 255), Color3.fromRGB(255, 196, 92)
local WHITE, BLACK = Color3.new(1, 1, 1), Color3.new(0, 0, 0)
local NO_LIMIT = 10000

local drawing = type(Drawing) == "table" and type(Drawing.new) == "function"
local function draw(kind, props)
  if not drawing then return nil end
  local ok, object = pcall(Drawing.new, kind)
  if not ok or not object then return nil end
  for key, value in pairs(props or {}) do pcall(function() object[key] = value end) end
  object.Visible = false
  return object
end
local function hideAll(set)
  for _, object in pairs(set) do
    if type(object) == "table" then hideAll(object) elseif object then pcall(function() object.Visible = false end) end
  end
end
local function removeAll(set)
  for _, object in pairs(set) do
    if type(object) == "table" then removeAll(object) elseif object then pcall(function() object:Remove() end) end
  end
end

-- Text sized to the screen: the sizes given are for a 1080-line screen and grow with a taller one (measured
-- 11-16: on the owner's 2560x1369 the 14 px enemy panel was hard to read over a bright wall).
local function textSize(base)
  local camera = workspace.CurrentCamera
  local scale = camera and math.clamp(camera.ViewportSize.Y / 1080, 1, 2) or 1
  return math.floor(base * scale + 0.5)
end

-- one body's drawings, made the first time it is drawn
local function poolFor(body)
  local pool = esp.pools[body.key]
  if pool then return pool end
  pool = {
    outline = draw("Square", { Thickness = 3, Filled = false, Color = BLACK, Transparency = 0.6 }),
    box = draw("Square", { Thickness = 1, Filled = false }),
    barBack = draw("Square", { Thickness = 1, Filled = true, Color = BLACK, Transparency = 0.6 }),
    bar = draw("Square", { Thickness = 1, Filled = true }),
    name = draw("Text", { Size = textSize(14), Center = true, Outline = true, Font = 2, Color = WHITE }),
    info = draw("Text", { Size = textSize(13), Center = true, Outline = true, Font = 2, Color = Color3.fromRGB(220, 220, 220) }),
    tracer = draw("Line", { Thickness = 1, Transparency = 0.7 }),
    look = draw("Line", { Thickness = 1, Transparency = 0.85 }),
    arrow = draw("Triangle", { Thickness = 1, Filled = true, Transparency = 0.85 }),
    ghost = draw("Text", { Size = textSize(13), Center = true, Outline = true, Font = 2, Color = GHOST }),
    bones = {},
  }
  for index = 1, #BS.BONES do pool.bones[index] = draw("Line", { Thickness = 1, Transparency = 0.9 }) end
  esp.pools[body.key] = pool
  return pool
end

local function screen(camera, position)
  local point = camera:WorldToViewportPoint(position)
  return Vector2.new(point.X, point.Y), point.Z > 0.1
end

-- The box round a body as the game has posed it this frame: every part, each as wide and tall as it is on
-- screen (its own axes onto the camera's, at its depth). minX, minY, maxX, maxY, nearest (the depth of the part
-- nearest the camera); the four are nil when all is behind the camera.
local function boxOf(body, camera, right, up, focal)
  local minX, minY, maxX, maxY, n = math.huge, math.huge, -math.huge, -math.huge, 0
  local nearest = math.huge
  local function add(position, ex, ey)
    local p = camera:WorldToViewportPoint(position)
    if p.Z < nearest then nearest = p.Z end
    -- (a part all but touching the camera would stretch the box over the whole screen: left out)
    if p.Z <= 0.5 then return end
    local k = focal / p.Z
    ex, ey = ex * k, ey * k
    if p.X - ex < minX then minX = p.X - ex end
    if p.X + ex > maxX then maxX = p.X + ex end
    if p.Y - ey < minY then minY = p.Y - ey end
    if p.Y + ey > maxY then maxY = p.Y + ey end
    n += 1
  end
  -- Near the camera the quick way (each part's size at its middle's depth) is off at the screen's edges with a wide
  -- view (measured 11-16 at a 90 degree view: heads a few px out of their box within ~20 studs). So a body within
  -- 25 studs has every corner of every part put on the screen; one further off keeps the quick way (under a pixel off).
  local close = body.root and body.root.Parent and (body.root.Position - camera.CFrame.Position).Magnitude < 25
  for _, part in pairs(body.parts) do
    if part.Parent then
      local cf = part.CFrame
      local h = part.Size * 0.5
      if close then
        for sx = -1, 1, 2 do
          for sy = -1, 1, 2 do
            for sz = -1, 1, 2 do
              add(cf * Vector3.new(h.X * sx, h.Y * sy, h.Z * sz), 0, 0)
            end
          end
        end
      else
        local rx, ry, rz = cf.RightVector, cf.UpVector, cf.LookVector
        add(cf.Position,
          math.abs(rx:Dot(right)) * h.X + math.abs(ry:Dot(right)) * h.Y + math.abs(rz:Dot(right)) * h.Z,
          math.abs(rx:Dot(up)) * h.X + math.abs(ry:Dot(up)) * h.Y + math.abs(rz:Dot(up)) * h.Z)
      end
    end
  end
  if n == 0 and body.root and body.root.Parent then add(body.root.Position, 1.2, 2.8) end
  if n == 0 then return nil, nil, nil, nil, nearest end
  return minX, minY, maxX, maxY, nearest
end
-- A body with a part nearer the camera than this is right on top of you: a box on it would run off the screen
-- (measured 11-16: a teammate's feet at the camera stretched his box to 18,000 px), so nothing is drawn on it.
local TOO_CLOSE = 1.5

local function start(hub)
  local map = {}
  for id, default in pairs({ esp = false, espTeam = false, espBox = true, espName = true, espHealth = true, espInfo = true, espSkeleton = false,
    espChams = false, espTracers = false, espSight = true, espArrows = true, espLook = false, espGhosts = true, ghostFor = 12,
    espRange = NO_LIMIT, panel = false, bomb = false }) do
    Config.define("bloxstrike." .. id, default)
    map[id] = "bloxstrike." .. id
  end
  local O = Config.mirror(map)
  esp.options = O

  -- chams: the engine's own outline, kept in a folder of the hub's (31 at most are drawn by the engine)
  local chamFolder = Instance.new("Folder")
  chamFolder.Name = "BASED.bloxstrike.chams"
  pcall(function() chamFolder.Parent = (gethui and gethui()) or S.CoreGui end)
  if not chamFolder.Parent then chamFolder.Parent = workspace.CurrentCamera end
  B.own(chamFolder)
  local function chamFor(body, on, color)
    local cham = esp.chams[body.key]
    if not on then
      if cham then cham.Enabled = false end
      return
    end
    if not cham then
      cham = Instance.new("Highlight")
      cham.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
      cham.FillTransparency, cham.OutlineTransparency = 0.55, 0.1
      cham.Parent = chamFolder
      esp.chams[body.key] = cham
    end
    if cham.Adornee ~= body.character then cham.Adornee = body.character end
    cham.FillColor, cham.OutlineColor = color, WHITE
    cham.Enabled = true
  end

  -- ---------------------------------------------------------------- each frame, after the game has posed the bodies and set the view
  local used = {}
  local function frame()
    table.clear(used)
    local camera = workspace.CurrentCamera
    if O.esp and camera and drawing then
      esp.frames += 1
      local cf = camera.CFrame
      local camPos, right, up = cf.Position, cf.RightVector, cf.UpVector
      local subject = camera.CameraSubject
      local view = camera.ViewportSize
      local focal = view.Y / (2 * math.tan(math.rad(camera.FieldOfView) * 0.5))
      local centreScreen = Vector2.new(view.X * 0.5, view.Y * 0.5)
      local now = os.clock()
      local chams = 0
      local mine = BS.myTeam()
      local range = O.espRange >= NO_LIMIT and math.huge or O.espRange
      for _, body in ipairs(BS.bodies) do
        if body.alive and (body.enemy or (O.espTeam and body.team == mine)) then
          local live = BS.present(body)
          if live then body.lastPos, body.lastSeen = body.root.Position, now end
          -- the body the camera is on (the one you spectate, or the camera inside it): nothing is drawn on it
          -- (measured 11-16: spectating a teammate in first person, its box filled the screen)
          local viewed = live and ((subject ~= nil and subject:IsDescendantOf(body.character))
            or (body.head ~= nil and (body.head.Position - camPos).Magnitude < 2.5))
          local color = not body.enemy and MATE or ((O.espSight and not body.visible) and COVER or ENEMY)
          if live and not viewed and (body.root.Position - camPos).Magnitude <= range then
            local pool = poolFor(body)
            used[body.key] = true
            pool.ghost.Visible = false
            local distance = (body.root.Position - camPos).Magnitude
            local minX, minY, maxX, maxY, nearest = boxOf(body, camera, right, up, focal)
            local tooClose = nearest < TOO_CLOSE
            local onScreen = minX ~= nil and not tooClose and maxX >= 0 and minX <= view.X and maxY >= 0 and minY <= view.Y
            if tooClose then
              hideAll(pool)
            elseif onScreen then
              if pool.arrow then pool.arrow.Visible = false end
              -- (one far away is never drawn smaller than 5 x 9 px, round its middle: it stays easy to see)
              local width, height = math.max(maxX - minX + 2, 5), math.max(maxY - minY + 2, 9)
              local corner = Vector2.new(math.floor((minX + maxX) * 0.5 - width * 0.5), math.floor((minY + maxY) * 0.5 - height * 0.5))
              local centreX = corner.X + width * 0.5
              if pool.box then
                pool.box.Visible, pool.outline.Visible = O.espBox, O.espBox
                pool.box.Position, pool.box.Size, pool.box.Color, pool.box.Transparency = corner, Vector2.new(width, height), color, 1
                pool.outline.Position, pool.outline.Size = corner, Vector2.new(width, height)
              end
              local health = tonumber(body.participant and body.participant:GetAttribute("Health"))
                or tonumber(body.character:GetAttribute("Health")) or body.health
              if pool.bar then
                local share = math.clamp(health / body.maxHealth, 0, 1)
                pool.barBack.Visible, pool.bar.Visible = O.espHealth, O.espHealth
                pool.barBack.Position, pool.barBack.Size = Vector2.new(corner.X - 6, corner.Y - 1), Vector2.new(4, height + 2)
                pool.bar.Position = Vector2.new(corner.X - 5, corner.Y + height * (1 - share))
                pool.bar.Size = Vector2.new(2, height * share)
                pool.bar.Color = Color3.fromHSV(0.33 * share, 0.85, 1)
              end
              if pool.name then
                pool.name.Visible = O.espName
                pool.name.Text = body.name
                pool.name.Position = Vector2.new(centreX, corner.Y - pool.name.Size - 2)
                pool.name.Color = color
              end
              if pool.info then
                pool.info.Visible = O.espInfo
                local bits = { string.format("%dm", math.floor(distance * 0.28 + 0.5)) }
                if body.weapon then bits[#bits + 1] = body.weapon end
                bits[#bits + 1] = string.format("%d hp", math.floor(health + 0.5))
                if body.armor and body.armor > 0 then bits[#bits + 1] = string.format("%d armour", math.floor(body.armor + 0.5)) end
                if body.kit then bits[#bits + 1] = "kit" end
                pool.info.Text = table.concat(bits, " · ")
                pool.info.Position = Vector2.new(centreX, corner.Y + height + 2)
              end
              if pool.tracer then
                pool.tracer.Visible = O.espTracers
                pool.tracer.From, pool.tracer.To, pool.tracer.Color = Vector2.new(view.X * 0.5, view.Y), Vector2.new(centreX, corner.Y + height), color
              end
              if pool.look then
                local head = body.head
                local show = O.espLook and head ~= nil and head.Parent ~= nil
                if show then
                  local a, oa = screen(camera, head.Position)
                  local b, ob = screen(camera, head.Position + head.CFrame.LookVector * 6)
                  show = oa and ob
                  if show then pool.look.From, pool.look.To, pool.look.Color = a, b, color end
                end
                pool.look.Visible = show
              end
              for index, bone in ipairs(BS.BONES) do
                local line = pool.bones[index]
                if line then
                  local a, b = body.parts[bone[1]], body.parts[bone[2]]
                  local show = O.espSkeleton and a ~= nil and b ~= nil and a.Parent ~= nil and b.Parent ~= nil
                  if show then
                    local pa, oa = screen(camera, a.Position)
                    local pb, ob = screen(camera, b.Position)
                    show = oa and ob
                    if show then line.From, line.To, line.Color = pa, pb, color end
                  end
                  line.Visible = show
                end
              end
            else
              -- in the world but off the screen: an arrow round the crosshair, pointing the way to turn
              hideAll(pool)
              if O.espArrows and pool.arrow and body.enemy then
                local rel = cf:PointToObjectSpace(body.root.Position)
                local dir = Vector2.new(rel.X, -rel.Y)
                if dir.Magnitude < 1e-3 then dir = Vector2.new(0, 1) end
                dir = dir.Unit
                local radius = math.min(view.X, view.Y) * 0.28
                local back = centreScreen + dir * radius
                local side = Vector2.new(-dir.Y, dir.X) * 7
                pool.arrow.PointA, pool.arrow.PointB, pool.arrow.PointC = centreScreen + dir * (radius + 14), back + side, back - side
                pool.arrow.Color = color
                pool.arrow.Visible = true
              end
            end
            if O.espChams and chams < 30 then
              chams += 1
              chamFor(body, true, color)
            else
              chamFor(body, false)
            end
          elseif not live and O.espGhosts and body.enemy and body.lastPos and body.lastSeen and now - body.lastSeen <= O.ghostFor then
            -- hidden by the game: a dim box where it was last seen (a body's height there), and how long ago
            local pool = poolFor(body)
            used[body.key] = true
            hideAll(pool)
            local top, onTop = screen(camera, body.lastPos + Vector3.new(0, 2.6, 0))
            local bottom, onBottom = screen(camera, body.lastPos - Vector3.new(0, 3, 0))
            if onTop and onBottom then
              local height = math.max(bottom.Y - top.Y, 9)
              local width = math.max(height * 0.45, 5)
              local corner = Vector2.new(math.floor(top.X - width * 0.5), math.floor(top.Y))
              if pool.box then
                pool.box.Visible, pool.outline.Visible = O.espBox, O.espBox
                pool.box.Position, pool.box.Size, pool.box.Color, pool.box.Transparency = corner, Vector2.new(width, height), GHOST, 0.55
                pool.outline.Position, pool.outline.Size = corner, Vector2.new(width, height)
              end
              if pool.ghost then
                pool.ghost.Visible = true
                pool.ghost.Text = string.format("%s · %ds ago", body.name, math.floor(now - body.lastSeen))
                pool.ghost.Position = Vector2.new(top.X, corner.Y - pool.ghost.Size - 2)
              end
            end
            chamFor(body, false)
          end
        end
      end
    end
    for key, pool in pairs(esp.pools) do
      if not used[key] then hideAll(pool) end
    end
    for key, cham in pairs(esp.chams) do
      if not used[key] or not (O.esp and O.espChams) then cham.Enabled = false end
    end
  end
  esp.frame = frame
  local step = "BASED.bloxstrike.esp"
  pcall(function()
    S.RunService:BindToRenderStep(step, Enum.RenderPriority.Last.Value + 100, function()
      B.try("bloxstrike.esp", frame)
    end)
  end)
  B.own(function() pcall(function() S.RunService:UnbindFromRenderStep(step) end) end)
  -- (bodies that are gone: their drawings go with them)
  Motion.every(function()
    for key, pool in pairs(esp.pools) do
      if not BS.byKey[key] then removeAll(pool); esp.pools[key] = nil end
    end
    for key, cham in pairs(esp.chams) do
      if not BS.byKey[key] then cham:Destroy(); esp.chams[key] = nil end
    end
  end, 0.5, "bloxstrike.esp.sweep")
  B.own(function()
    for _, pool in pairs(esp.pools) do removeAll(pool) end
    table.clear(esp.pools)
  end)

  -- ---------------------------------------------------------------- the enemy panel and the bomb
  -- (a dark backdrop under the list: it stays readable over a bright wall)
  local panelBack = draw("Square", { Filled = true, Thickness = 1, Color = Color3.fromRGB(10, 10, 14), Transparency = 0.55, ZIndex = 0 })
  local panelTitle = draw("Text", { Size = textSize(16), Outline = true, Font = 2, Color = WHITE, ZIndex = 2 })
  local bombText = draw("Text", { Size = textSize(20), Center = true, Outline = true, Font = 2, Color = WHITE, ZIndex = 2 })
  B.own(function()
    if panelBack then pcall(function() panelBack:Remove() end) end
    if panelTitle then pcall(function() panelTitle:Remove() end) end
    if bombText then pcall(function() bombText:Remove() end) end
    removeAll(esp.panelLines)
  end)
  -- how wide a line of text is drawn: the executor's own measure where it has one
  local function widthOf(text)
    local ok, bounds = pcall(function() return text.TextBounds end)
    if ok and typeof(bounds) == "Vector2" and bounds.X > 0 then return bounds.X end
    return #tostring(text.Text) * text.Size * 0.6
  end
  local function bombState()
    for _, model in ipairs(S.CollectionService:GetTagged("Bomb")) do
      local raw = model:GetAttribute("BombPlanted")
      if type(raw) == "string" and model:GetAttribute("Defused") ~= true and model:GetAttribute("Exploded") ~= true then
        local ok, data = pcall(function() return S.HttpService:JSONDecode(raw) end)
        if ok and type(data) == "table" then
          local planted = tonumber(data.Time) or workspace:GetServerTimeNow()
          local fuse = math.max(tonumber(data.TimeUntilExplode) or 40, 0.1)
          return { left = planted + fuse - workspace:GetServerTimeNow(), site = data.Site or data.BombSite, defusing = model:GetAttribute("IsGettingDefused") == true }
        end
      end
    end
    return nil
  end
  esp.bombState = bombState
  Motion.every(function()
    local camera = workspace.CurrentCamera
    if not (drawing and camera) then return end
    -- the panel: every enemy, alive first
    local rows = {}
    if O.panel then
      for _, body in ipairs(BS.bodies) do
        if body.enemy and not body.zombie then rows[#rows + 1] = body end
      end
      table.sort(rows, function(a, b)
        if a.alive ~= b.alive then return a.alive end
        return (a.health or 0) > (b.health or 0)
      end)
    end
    local top = camera.ViewportSize.Y * 0.32
    local titleSize = panelTitle and panelTitle.Size or 16
    local lineSize = textSize(15)
    local step = lineSize + 3
    local widest = 0
    if panelTitle then
      local alive = 0
      for _, body in ipairs(rows) do if body.alive then alive += 1 end end
      panelTitle.Visible = O.panel and #rows > 0
      panelTitle.Text = string.format("ENEMIES  %d alive", alive)
      panelTitle.Position = Vector2.new(18, top)
      if panelTitle.Visible then widest = widthOf(panelTitle) end
    end
    for index = 1, math.max(#rows, #esp.panelLines) do
      local line = esp.panelLines[index]
      local body = rows[index]
      if body and not line then
        line = draw("Text", { Size = lineSize, Outline = true, Font = 3, ZIndex = 2 })
        esp.panelLines[index] = line
      end
      if line then
        line.Visible = body ~= nil
        if body then
          local bits = { string.format("%-14s", tostring(body.name):sub(1, 14)) }
          if body.alive then
            bits[#bits + 1] = string.format("%3d hp", math.floor((body.health or 0) + 0.5))
            bits[#bits + 1] = body.armor and body.armor > 0 and string.format("%3d ar", math.floor(body.armor + 0.5)) or "  - ar"
          else
            bits[#bits + 1] = "  dead   "
          end
          bits[#bits + 1] = body.money and string.format("$%-5d", body.money) or "$?    "
          if body.kit then bits[#bits + 1] = "kit" end
          if body.alive and body.weapon then bits[#bits + 1] = body.weapon end
          line.Text = table.concat(bits, "  ")
          line.Color = not body.alive and Color3.fromRGB(130, 130, 130) or (body.inWorld and ENEMY or WHITE)
          line.Position = Vector2.new(18, top + titleSize + 6 + (index - 1) * step)
          widest = math.max(widest, widthOf(line))
        end
      end
    end
    if panelBack then
      local shown = O.panel and #rows > 0
      panelBack.Visible = shown
      if shown then
        panelBack.Position = Vector2.new(10, top - 6)
        panelBack.Size = Vector2.new(widest + 16, titleSize + 6 + #rows * step + 10)
      end
    end
    -- the bomb
    if bombText then
      local bomb = O.bomb and bombState() or nil
      bombText.Visible = bomb ~= nil
      if bomb then
        local left = math.max(bomb.left, 0)
        bombText.Text = string.format("BOMB%s  %.1fs%s", bomb.site and ("  " .. tostring(bomb.site)) or "", left, bomb.defusing and "  ·  defusing" or "")
        bombText.Color = left > 10 and Color3.fromRGB(255, 220, 90) or (left > 5 and Color3.fromRGB(255, 150, 60) or Color3.fromRGB(255, 70, 70))
        bombText.Position = Vector2.new(camera.ViewportSize.X * 0.5, 64)
      end
    end
  end, 10, "bloxstrike.panel")
end

local function visualCards(page)
  local box = page:section({ title = "ESP", icon = "eye", desc = "Everyone the game puts in the world, through walls." })
  box:toggle({ id = "bloxstrike.esp", label = "ESP", desc = "Boxes on enemies.", default = false })
  box:toggle({ id = "bloxstrike.espTeam", label = "Teammates too", desc = "In their own colour.", default = false })
  box:toggle({ id = "bloxstrike.espBox", label = "Box", default = true })
  box:toggle({ id = "bloxstrike.espName", label = "Name", default = true })
  box:toggle({ id = "bloxstrike.espHealth", label = "Health bar", default = true })
  box:toggle({ id = "bloxstrike.espInfo", label = "Distance, weapon, armour", default = true })
  box:toggle({ id = "bloxstrike.espSight", label = "Colour by sight", desc = "Red in the open, violet behind cover.", default = true })
  box:toggle({ id = "bloxstrike.espSkeleton", label = "Skeleton", default = false })
  box:toggle({ id = "bloxstrike.espLook", label = "Where they look", desc = "A short line from the head.", default = false })
  box:toggle({ id = "bloxstrike.espChams", label = "Chams", desc = "The body lit through walls.", default = false })
  box:toggle({ id = "bloxstrike.espTracers", label = "Tracers", default = false })
  box:toggle({ id = "bloxstrike.espArrows", label = "Arrows off screen", desc = "Points to enemies behind you.", default = true })
  box:slider({ id = "bloxstrike.espRange", label = "Range", desc = "All the way right is no limit.", min = 100, max = NO_LIMIT, step = 100, default = NO_LIMIT, suffix = " studs" })
  local fog = page:section({ title = "Hidden by the game", icon = "ghost", desc = "The game hides who it has no position for." })
  fog:toggle({ id = "bloxstrike.espGhosts", label = "Last seen", desc = "Where an enemy was when the game hid it.", default = true })
  fog:slider({ id = "bloxstrike.ghostFor", label = "Keep for", min = 2, max = 60, step = 1, default = 12, suffix = " s" })
end

local function infoCards(page)
  local box = page:section({ title = "Intel", icon = "radar", desc = "What the game tells every player." })
  box:toggle({ id = "bloxstrike.panel", label = "Enemy panel", desc = "Health, armour, money, kit, weapon.", default = false })
  box:toggle({ id = "bloxstrike.bomb", label = "Bomb timer", desc = "Seconds left once it is planted.", default = false })
  local list = page:section({ title = "Enemies", icon = "users" })
  local text = list:note({ icon = "list", text = "" })
  Motion.every(function()
    if not (text.frame.Parent and Window.anyOpen()) then return end
    local rows = {}
    for _, body in ipairs(BS.bodies) do
      if body.enemy then
        rows[#rows + 1] = string.format("%s%s  ·  %s  ·  $%s%s", body.alive and "" or "(dead) ", tostring(body.name),
          body.alive and string.format("%d hp", math.floor((body.health or 0) + 0.5)) or "-", tostring(body.money or "?"), body.kit and "  ·  kit" or "")
      end
    end
    text.set(#rows > 0 and table.concat(rows, "\n") or "No enemies: no team yet, or the round has not started.")
  end, 1, "bloxstrike.info.line")
end

BS.parts[#BS.parts + 1] = { id = "esp", start = start, visuals = visualCards, info = infoCards }
end
do -- glorybound.lua
-- ============================================================================
--  GloryBound   the gym, the gate, the vault, and round again
--
--  Read from the game on 2026-11-11 (place 137629355240872, universe
--  10768652372, version 728: all 519 client scripts, decompiled, and the live
--  state of one account). What every part of this module rests on:
--
--   * One folder of remotes, ReplicatedStorage.Remotes, every one a RemoteEvent
--     (CombatFx alone is unreliable). The server counts each remote by the
--     second (Shared.Config.Remote.Limits, copied into LIMITS below) and keeps
--     a tally of a client that goes over (AbuseThreshold 5 inside AbuseWindow
--     30 s). Nothing leaves here faster than four fifths of its limit, and a
--     send that would is held, never sent late in a bunch.
--   * What the server holds of the player comes down StateSync: whole once
--     ({ full = true, data }), then in pieces ({ patch }). TrainingFx carries
--     the strength numbers between patches. Where the body is and what it is
--     doing are attributes of the Player (Zone, Training, LobbyStatus,
--     CombatState); the match is the attributes of ReplicatedStorage.GameState
--     (ServerMode "Lobby" | "Arena", Phase, Round, ...).
--   * The lobby and the arena are one place on different servers. A match is a
--     teleport away and another back: the hub is queued to start again on the
--     other side, or the farm would end at the gate.
--   * The client has no kick, no ban and no watch on scripts, logs or the
--     character's speed. What it does have is a server that checks: every
--     number below is the server's own, and the module never asks for more.
--   * ShopPrompt opens a Robux prompt. It is never sent from here.
--
--  The parts (games/glorybound_*.lua) each own one thing: the gym, the arena,
--  the vault and skills, the daily gifts. This file is what they share.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util

local GB = { parts = {}, state = {}, sends = 0, held = 0, synced = nil, owner = nil, log = {} }
B.GloryBound = GB
GB.PLACE, GB.UNIVERSE, GB.VERSION = 137629355240872, 10768652372, 728

-- ---------------------------------------------------------------- remotes
-- { a second, at once }: the game's own table. A remote that is not in it gets its default, 5 and 5.
local LIMITS = {
  Attack = { 7, 10 }, AttackRelease = { 7, 10 }, Block = { 10, 10 }, Dash = { 2, 4 }, TrainStop = { 2, 3 }, TrainRep = { 3, 24 },
  SkillUpgrade = { 4, 4 }, Rebirth = { 1, 1 }, ChestBuy = { 2, 3 }, ChestOpen = { 2, 2 }, ArmorEquip = { 4, 5 }, ArmorUnequip = { 4, 5 },
  WeaponEquip = { 3, 4 }, CosmeticEquip = { 3, 4 }, SpectateStart = { 1, 2 }, TravelTo = { 1, 2 }, KitSelect = { 1, 2 },
  RequestSync = { 0.2, 1 }, QueueJoin = { 1, 3 }, QueueLeave = { 1, 3 }, TripState = { 4, 8 }, BoonPick = { 2, 3 }, LeaveMatch = { 0.5, 2 },
  FunnelStep = { 0.5, 3 }, DailyAction = { 2, 4 }, HeadLook = { 12, 30 }, HelmetHide = { 1, 3 }, PatchAction = { 2, 4 },
  SettingsSave = { 4, 10 }, AbilityAction = { 4, 8 }, AbilityCast = { 3, 4 }, TitleEquip = { 0.5, 2 }, SpectreAction = { 1, 3 },
  ArmorerAction = { 1, 3 }, HofRequest = { 0.5, 2 }, RiftAction = { 1, 2 }, NightmareChoice = { 0.5, 2 },
  PartyInvite = { 1, 4 }, PartyRespond = { 2, 4 }, PartyLeave = { 0.5, 2 }, PartyKick = { 1, 3 }, PartyPromote = { 0.5, 2 },
}
local DEFAULT_LIMIT = { 5, 5 }
-- a Robux prompt, and the game's own bookkeeping of where a new player is: never by the hub's hand
local NEVER = { ShopPrompt = true, FunnelStep = true, TutorialAction = true }
GB.LIMITS, GB.MARGIN = LIMITS, 0.8

local remotes, buckets = {}, {}
function GB.remote(name)
  local remote = remotes[name]
  if remote and remote.Parent then return remote end
  local folder = S.ReplicatedStorage:FindFirstChild("Remotes")
  remote = folder and folder:FindFirstChild(name) or nil
  remotes[name] = remote
  return remote
end
-- The server's count of a remote, kept here a little meaner than it keeps it: four fifths of the
-- rate, and one less at once (it also counts what the player's own clicks send, which this cannot see).
local function bucket(name)
  local now = os.clock()
  local b = buckets[name]
  if not b then
    local limit = LIMITS[name] or DEFAULT_LIMIT
    local size = math.max(1, limit[2] - 1)
    b = { rate = limit[1] * GB.MARGIN, size = size, tokens = size, at = now }
    buckets[name] = b
  end
  b.tokens = math.min(b.size, b.tokens + (now - b.at) * b.rate)
  b.at = now
  return b
end
function GB.ready(name) return bucket(name).tokens >= 1 end
-- seconds until one more of `name` may go
function GB.due(name)
  local b = bucket(name)
  return b.tokens >= 1 and 0 or (1 - b.tokens) / b.rate
end
-- Sends it now or not at all: true when it went. (false, "rate") is one held back.
function GB.send(name, ...)
  if NEVER[name] then return false, "never" end
  local remote = GB.remote(name)
  if not remote then return false, "no remote" end
  local b = bucket(name)
  if b.tokens < 1 then
    GB.held += 1
    return false, "rate"
  end
  b.tokens -= 1
  GB.sends += 1
  remote:FireServer(...)
  return true
end
-- Waits its turn (never longer than `limit` s), then sends. For the things done once: a claim, a buy.
function GB.sendWhenDue(limit, name, ...)
  local started = os.clock()
  while B.alive and not GB.ready(name) do
    if os.clock() - started > (limit or 5) then return false, "rate" end
    task.wait(math.min(GB.due(name), 0.25) + 0.01)
  end
  if not B.alive then return false, "unloaded" end
  return GB.send(name, ...)
end
function GB.on(name, fn)
  local remote = GB.remote(name)
  if not remote then return nil end
  return B.connect(remote.OnClientEvent, function(...)
    B.identity()
    fn(...)
  end, "glorybound." .. name)
end

-- ---------------------------------------------------------------- what the server holds
local state = GB.state
GB.onState = B.Signal.new()
local function adopt(data, whole)
  if type(data) ~= "table" then return end
  if whole then table.clear(state) end
  for key, value in pairs(data) do
    if type(key) == "string" then state[key] = value end
  end
  GB.synced = os.clock()
  GB.onState:fire(data, whole == true)
end
GB.adopt = adopt
function GB.num(key, default)
  local value = tonumber(state[key])
  if value ~= nil and value == value then return value end
  return default or 0
end
function GB.flag(name)
  local flags = state.Flags
  if type(flags) ~= "table" then return nil end
  return flags[name]
end
function GB.attr(name) return B.LP:GetAttribute(name) end
function GB.matchState(name)
  local folder = S.ReplicatedStorage:FindFirstChild("GameState")
  if not folder then return nil end
  return folder:GetAttribute(name)
end
function GB.mode()
  local mode = GB.matchState("ServerMode")
  if mode == nil then mode = workspace:GetAttribute("ServerMode") end
  return mode
end
function GB.inLobby() return GB.mode() == "Lobby" end
function GB.inArena() return GB.mode() == "Arena" end
-- A new player is walked through a tutorial that the game drives by the hand: nothing is done for them until it is over.
function GB.settled() return GB.attr("TutorialStage") == "Done" and GB.attr("DataLoaded") ~= false end

-- One of the game's own controllers, as the game loaded it (a require of a module that is already
-- running hands back what it returned: measured on the client, 2026-10-09).
function GB.controller(name)
  if type(require) ~= "function" then return nil end
  local scripts = B.LP:FindFirstChild("PlayerScripts")
  local folder = scripts and scripts:FindFirstChild("Controllers")
  local module = folder and folder:FindFirstChild(name)
  if not module then return nil end
  local ok, value = pcall(require, module)
  B.identity()
  if ok and type(value) == "table" then return value end
  return nil
end

-- One of the game's own tables of what things are (Shared.Defs.Weapons, .Armor, .Skills, .Creatures, .Boons):
-- the game's, asked, never a copy that an update would leave behind.
local defs = {}
function GB.def(name)
  if defs[name] ~= nil then return defs[name] or nil end
  local found = false
  if type(require) == "function" then
    local shared = S.ReplicatedStorage:FindFirstChild("Shared")
    local folder = shared and shared:FindFirstChild("Defs")
    local module = folder and folder:FindFirstChild(name)
    if module then
      local ok, value = pcall(require, module)
      B.identity()
      if ok and type(value) == "table" then found = value end
    end
  end
  defs[name] = found
  return found or nil
end

-- ---------------------------------------------------------------- the body
-- One part has the body at a time: the gym does not walk it to a barbell while the arena fights with it.
function GB.take(who)
  if GB.owner == nil or GB.owner == who then
    GB.owner = who
    return true
  end
  return false
end
function GB.drop(who)
  if GB.owner == who then GB.owner = nil end
end
function GB.alive()
  local humanoid = B.humanoid()
  return humanoid ~= nil and humanoid.Health > 0 and B.root() ~= nil
end
function GB.flat(a, b)
  local dx, dz = a.X - b.X, a.Z - b.Z
  return math.sqrt(dx * dx + dz * dz)
end
-- Walks there on its own legs, at the speed the game gave them. `keep` is asked every step and
-- ends the walk when it says no. true when it stands within `reach` of the point.
function GB.walk(to, reach, limit, keep)
  local started, told, last, stuckAt = os.clock(), 0, nil, os.clock()
  reach, limit = reach or 3, limit or 20
  while B.alive do
    local root, humanoid = B.root(), B.humanoid()
    if not (root and humanoid) or humanoid.Health <= 0 then return false, "no body" end
    if keep and not keep() then return false, "called off" end
    local position = root.Position
    if GB.flat(position, to) <= reach then return true end
    local now = os.clock()
    if now - started > limit then return false, "too long" end
    -- (a wall, a column: a body that has not moved a stud in a second and a half is not getting there this way)
    if last == nil or GB.flat(position, last) > 1 then last, stuckAt = position, now end
    if now - stuckAt > 1.5 then return false, "stuck" end
    if now - told > 0.5 then
      told = now
      humanoid:MoveTo(Vector3.new(to.X, position.Y, to.Z))
    end
    task.wait(0.1)
  end
  return false, "unloaded"
end
function GB.halt()
  local root, humanoid = B.root(), B.humanoid()
  if root and humanoid then humanoid:MoveTo(root.Position) end
end

-- ---------------------------------------------------------------- getting there round things
-- (2026-11-16, the owner: the chase "never gets blocked by objects/walls"). A step goes straight when nothing solid is in
-- the way (rays at knee and chest height, down the middle and either side of the body; enemies and players are not
-- walls, and the sand's drifts are a stud tall, under the knee ray); else along a path round it (PathfindingService,
-- worked out on a thread of its own, made again when the goal moves 6 studs or 1.5 s pass); and a body told to move that
-- has not moved half a stud in 0.6 s hops and steps aside. No teleports: the game's own legs only.
local mover = { waypoints = nil, index = 0, goal = nil, madeAt = -math.huge, busy = false, last = nil, lastAt = 0, unstuck = 0 }
GB.mover = mover
local rays = RaycastParams.new()
rays.FilterType = Enum.RaycastFilterType.Exclude
rays.RespectCanCollide = true
local function notWalls()
  local list = {}
  local function add(instance) if instance then list[#list + 1] = instance end end
  add(B.character())
  add(workspace:FindFirstChild("ActiveEnemies"))
  add(workspace:FindFirstChild("ChallengeWorldFx"))
  add(workspace:FindFirstChild("FX"))
  for _, player in ipairs(S.Players:GetPlayers()) do add(player.Character) end
  return list
end
-- Is something solid between here and there (flat)? true and what it hit.
function GB.blocked(from, to)
  local flat = Vector3.new(to.X - from.X, 0, to.Z - from.Z)
  local distance = flat.Magnitude
  if distance < 1 then return false end
  rays.FilterDescendantsInstances = notWalls()
  local direction = flat.Unit * math.min(distance, 80)
  local side = Vector3.new(-flat.Unit.Z, 0, flat.Unit.X) * 1.2
  for _, height in ipairs({ -1.4, 0.6 }) do
    for _, offset in ipairs({ Vector3.zero, side, -side }) do
      local hit = workspace:Raycast(from + Vector3.new(0, height, 0) + offset, direction, rays)
      if hit then return true, hit end
    end
  end
  return false
end
local function plan(from, goal)
  if mover.busy then return end
  mover.busy = true
  task.spawn(function()
    local ok, path = pcall(function()
      local made = S.PathfindingService:CreatePath({ AgentRadius = 2.2, AgentHeight = 5.5, AgentCanJump = true, WaypointSpacing = 5 })
      made:ComputeAsync(from, goal)
      return made
    end)
    B.identity()
    if ok and path and path.Status == Enum.PathStatus.Success then
      mover.waypoints, mover.index = path:GetWaypoints(), 2
    else
      mover.waypoints = nil
    end
    mover.goal, mover.madeAt, mover.busy = goal, os.clock(), false
  end)
end
-- One step towards `goal`, every tick a walk is wanted: "straight", "path", "direct" (no path to be had) or "unstuck".
function GB.steer(humanoid, root, goal)
  local now = os.clock()
  local here = root.Position
  if not mover.last or (here - mover.last).Magnitude > 0.5 then mover.last, mover.lastAt = here, now end
  if GB.flat(here, goal) > 2.5 and now - mover.lastAt > 0.6 then
    -- (told to go and not going: a hop, and a step aside of the way it was trying)
    mover.lastAt, mover.unstuck, mover.waypoints = now, mover.unstuck + 1, nil
    humanoid.Jump = true
    local way = Vector3.new(goal.X - here.X, 0, goal.Z - here.Z)
    way = way.Magnitude > 0.1 and way.Unit or Vector3.new(1, 0, 0)
    local side = Vector3.new(-way.Z, 0, way.X) * (mover.unstuck % 2 == 0 and 6 or -6)
    humanoid:MoveTo(here + side + way * 2)
    return "unstuck"
  end
  if not GB.blocked(here, goal) then
    mover.waypoints = nil
    humanoid:MoveTo(goal)
    return "straight"
  end
  if not mover.waypoints or not mover.goal or GB.flat(mover.goal, goal) > 6 or now - mover.madeAt > 1.5 then plan(here, goal) end
  local waypoints = mover.waypoints
  if waypoints then
    local point = waypoints[mover.index]
    while point and GB.flat(here, point.Position) < 3 do
      mover.index += 1
      point = waypoints[mover.index]
    end
    if point then
      if point.Action == Enum.PathWaypointAction.Jump then humanoid.Jump = true end
      humanoid:MoveTo(point.Position)
      return "path"
    end
  end
  humanoid:MoveTo(goal)
  return "direct"
end
-- The game's own travel between the lobby's rooms (Gym, Vault, Shop, Armory, HallOfFame, Sparring, Gate):
-- three seconds apart, and the server puts the body there itself.
GB.travelled = -math.huge
function GB.travel(point)
  if os.clock() - GB.travelled < 3.2 then return false, "cooldown" end
  local ok, why = GB.send("TravelTo", point)
  if ok then GB.travelled = os.clock() end
  return ok, why
end
function GB.prompt(prompt)
  if type(fireproximityprompt) ~= "function" then return false end
  local ok = pcall(fireproximityprompt, prompt)
  B.identity()
  return ok
end

-- ---------------------------------------------------------------- the log, and the line on the page
-- What it did, for the page and for whoever reads a run afterwards: the last forty lines.
function GB.note(text)
  local log = GB.log
  log[#log + 1] = { at = os.clock(), text = text }
  if #log > 40 then table.remove(log, 1) end
  GB.status = text
end
function GB.toast(title, text, icon, tone)
  if Config.get("glorybound.toasts") == false then return end
  Window.toast({ title = title, text = text, icon = icon or "swords", tone = tone or "accent", time = 4 })
end

-- ---------------------------------------------------------------- start
local function start(hub)
  Config.define("glorybound.toasts", true)
  Config.define("glorybound.follow", true)
  Config.define("glorybound.minimise", true)

  GB.on("StateSync", function(packet)
    if type(packet) ~= "table" then return end
    if packet.full and type(packet.data) == "table" then adopt(packet.data, true)
    elseif type(packet.patch) == "table" then adopt(packet.patch, false) end
  end)
  -- (the gym's numbers come this way between patches, and the game's own copy is written from it the same)
  GB.on("TrainingFx", function(fx)
    if type(fx) ~= "table" or (fx.stat ~= nil and fx.stat ~= "Strength") then return end
    local patch = {}
    patch.Strength, patch.StrengthCap = tonumber(fx.value), tonumber(fx.cap)
    patch.StrengthXP, patch.StrengthXPToNext, patch.TrainingMult = tonumber(fx.xp), tonumber(fx.xpToNext), tonumber(fx.mult)
    if next(patch) ~= nil then adopt(patch, false) end
    GB.onTraining:fire(fx)
  end)
  -- The whole of it was sent before the hub was here: the game's own copy is read once, and what
  -- comes after is heard first hand.
  local client = GB.controller("ClientState")
  if client and type(client.get) == "function" then
    local ok, data = pcall(client.get)
    B.identity()
    if ok and type(data) == "table" and next(data) ~= nil then adopt(data, true) end
  end
  -- (no copy to read: it is asked for, once, as the game itself asks when its own never came)
  task.delay(6, function()
    if B.alive and not GB.synced then GB.send("RequestSync") end
  end)

  -- The hub comes back on the other side of the gate. Once a session: what is queued stacks.
  local function follow()
    local World = B.World
    -- (the file this hub was run from when the one who ran it says so, else the installed one; and no intro between a match and the lobby)
    local file = type(B.genv.BASED_FILE) == "string" and B.genv.BASED_FILE or "BasedHub.lua"
    -- (what is queued stacks, and outlives a hub that was run again: the mark names the file queued, so the same file is
    -- not queued twice and another one is, after it; the last one queued is the one that comes back, World.followText)
    if (World and World.queued) or GB.queued or B.genv.BASED_FOLLOWING == file or not Config.get("glorybound.follow") or type(queue_on_teleport) ~= "function" then return end
    GB.queued = true
    B.genv.BASED_FOLLOWING = file
    if World then World.queued = true end
    local carry = string.format('getgenv().BASED_FILE = %q; getgenv().BASED_INTRO = "off"', file)
    -- (and it comes up minimised on the other side: a farm that goes match to match does not open its window over the
    -- game each time; the menu key opens it. The owner's ask, 2026-11-16)
    if Config.get("glorybound.minimise") ~= false then carry = carry .. "; getgenv().BASED_MINIMISED = true" end
    pcall(queue_on_teleport, World and World.followText and World.followText(file, carry) or string.format('pcall(function() %s; loadstring(readfile(%q))() end)', carry, file))
  end
  Config.on("glorybound.follow", follow)
  follow()
end
GB.onTraining = B.Signal.new()

-- ---------------------------------------------------------------- the tabs
-- A part adds its cards to a tab by naming it: { id, start = fn(hub), farm = fn(page), combat = fn(page), ... }
local function extend(kind, page)
  for _, part in ipairs(GB.parts) do
    if part[kind] then B.try("glorybound." .. part.id .. "." .. kind, part[kind], page) end
  end
end
local function has(kind)
  for _, part in ipairs(GB.parts) do
    if part[kind] then return true end
  end
  return false
end

local function statusLine()
  local s = GB.state
  if not GB.synced then return "Waiting for the game's data." end
  local parts = {}
  parts[#parts + 1] = string.format("Level %d", GB.num("Level", 1))
  parts[#parts + 1] = string.format("Strength %s / %s", util.comma(GB.num("Strength", 1)), util.comma(GB.num("StrengthCap", 50)))
  parts[#parts + 1] = string.format("Rebirth %d", GB.num("Rebirth", 0))
  parts[#parts + 1] = string.format("$%s", util.comma(GB.num("Cash", 0)))
  local line = table.concat(parts, "  ·  ")
  if s.RebirthReady == true then line = line .. "  ·  rebirth ready" end
  return line
end
GB.statusLine = statusLine

-- The whole farm in one press: everything that costs nothing. What spends (buying chests, selling, skill points) is the player's to switch on.
local FULL = { "train", "fight", "rebirth", "open", "collect", "wear", "gifts", "quests", "wheel", "patch" }
function GB.preset(on)
  for _, id in ipairs(FULL) do Config.set("glorybound." .. id, on == true) end
  if not on then Config.set("glorybound.aura", false) end
end
local function farmPage(hub)
  hub:page({ id = "farm", title = "Farm", icon = "repeat", build = function(page)
    local you = page:section({ title = "You", icon = "user", full = true })
    local line = you:note({ icon = "activity", text = statusLine() })
    local doing = you:note({ icon = "info", text = "" })
    you:button({ id = "glorybound.full", label = "Full auto", desc = "Training, fights, rebirths, chests, gear and daily gifts: all on.", text = "Switch on", run = function()
      GB.preset(true)
      Window.toast({ title = "Full auto is on", text = "Nothing that spends cash or points was switched on.", icon = "repeat", tone = "ok", time = 4 })
    end })
    you:button({ id = "glorybound.stop", label = "Stop", desc = "Everything off. The body stays where it is.", text = "Switch off", run = function()
      GB.preset(false)
      Window.toast({ title = "The farm is off", icon = "circle-pause", time = 3 })
    end })
    Motion.every(function()
      if not (line.frame.Parent and Window.anyOpen()) then return end
      line.set(statusLine())
      doing.set(GB.status or "Idle.")
    end, 2, "glorybound.status")
    extend("farm", page)
    local session = page:section({ title = "Session", icon = "plug" })
    session:toggle({ id = "glorybound.follow", label = "Come back after the gate", desc = "Starts BASED again on the match server.", default = true, bindable = false })
    session:toggle({ id = "glorybound.minimise", label = "Stay minimised after teleports", desc = "The window stays down in each new match. The menu key opens it.", default = true, bindable = false })
    session:toggle({ id = "glorybound.toasts", label = "Say what it did", desc = "A note for a rebirth, a chest, a win.", default = true, bindable = false })
  end })
end

B.game({
  id = "glorybound",
  name = "GloryBound",
  tagline = "Train. Fight. Loot. Again.",
  universes = { 10768652372 },
  places = { 137629355240872 },
  icon = "swords",
  tabs = function(hub)
    start(hub)
    for _, part in ipairs(GB.parts) do
      if part.start then B.try("glorybound." .. part.id, part.start, hub) end
    end
    -- (every part is here now: until this, none of them acts, or the first to start would decide without the rest)
    GB.started = true
    farmPage(hub)
    if has("combat") then
      hub:page({ id = "combat", title = "Arena", icon = "sword", build = function(page) extend("combat", page) end })
    end
    if has("loot") then
      hub:page({ id = "loot", title = "Vault", icon = "gem", build = function(page) extend("loot", page) end })
    end
    if has("daily") then
      hub:page({ id = "daily", title = "Daily", icon = "sunrise", build = function(page) extend("daily", page) end })
    end
  end,
})
end
do -- glorybound_arena.lua
-- ============================================================================
--  GloryBound   the arena: the queue, the fight, the way back
--
--  Read from the game (MatchmakingController, CombatController, ParryFx, BoonController,
--  ReviveOfferController, SummaryController, Shared.Defs.Kits / Creatures / Boons, version 728):
--
--   * QueueJoin("ArenaPVE") is Survival with a team (four, the empty places filled with the
--     game's own bots after up to 90 s); QueueJoin("ArenaPVE", "solo") is Survival alone, at
--     once, for 85% of the pay. The Player's Queue is the mode while queued and "" when not.
--     A match is a teleport to another server of the same place (GameState.ServerMode "Arena")
--     and one back: the game's own scripts do the trip.
--   * An attack is Attack(count, direction): a count that goes up by one, and a flat direction.
--     Nothing says who is hit: the server finds that out itself, from where the two bodies
--     are. The game's own controller exports attack(), dash(), getCooldowns(), isActive(): the
--     fight is driven through those, so the count, the combo, the cooldown and the swing are
--     the game's own and nothing is sent that a click would not send. Its attack goes for the
--     enemy the body FACES (within reach + 2 studs and half the swing's arc + 15 degrees), so
--     facing one is choosing it.
--   * Enemies are workspace.ActiveEnemies' children: Health, MaxHealth, AIState (Chase, Windup,
--     Attack, Recover, Stunned, Dead, ...), CreatureId, Elite. A blow coming is AIState
--     "Windup" with AttackKind and WindupEnd (the server's clock): read, never guessed.
--   * Block(true, the server's time) raises the shield (the Gladiator alone has one): 70% off
--     a blow from inside its 110 degrees, and no swing while it is up. Raised a quarter of a
--     second before a blow lands, it is a parry the game calls good. The server marks a client
--     whose parries are perfect nine times in ten: this one is never that early.
--   * Dash(direction) is two charges, four seconds each, 16 studs in 0.2 s with 0.15 s of it
--     untouchable. The body moves itself (the client is its own authority there).
--   * Between rounds a MatchEvent "boonOffer" names three boons; BoonPick(id) takes one, and
--     the server takes one itself after 15 s.
--   * Down: a ReviveOffer comes. "decline" is free; "buy" is free only while the offer says
--     credits are left, and a Robux prompt otherwise: it is only ever sent with credits.
--   * The end is a RewardSummary (cash, xp, round, chest) and the server's own return to the
--     lobby 5 to 10 s later; LeaveMatch("continue") asks for it now. "leave", sent alive,
--     halves the pay and is never sent.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util
local GB = B.GloryBound

local arena = { state = "off", matches = 0, rounds = 0, cash = 0, xp = 0, swings = 0, blocks = 0, dashes = 0, casts = 0, boons = {}, downs = 0, skips = 0, retries = 0,
  blocking = false, blockAt = -math.huge, seq = 0, nextSwing = 0, asked = -math.huge, told = 0, offer = nil, last = nil, facing = false }
GB.arena = arena
-- how far each kit's first swing reaches, and how long a swing takes (Shared.Defs.Kits, version 728)
local REACH = { Gladiator = 7, Lancer = 11, Berserker = 9.5, Archer = 40 }
local SWING = { Gladiator = 0.43, Lancer = 0.45, Berserker = 0.85, Archer = 0.45 }
arena.REACH = REACH
-- what each boon is worth to each way of playing, by what it changes (Shared.Defs.Boons: effect = { key = amount })
local WORTH = {
  damage = { damageMult = 10, doubleStrike = 9, thunder = 9, critBonus = 8, execute = 7, burn = 7, lifesteal = 6, pardon = 5, defense = 4, regen = 4, abilityCooldown = 3, blockGuard = 2, walkMult = 2, dashCooldownMult = 2, cashMult = 1 },
  survive = { pardon = 10, lifesteal = 10, regen = 9, defense = 9, blockGuard = 6, damageMult = 6, doubleStrike = 5, thunder = 5, critBonus = 4, execute = 4, burn = 4, walkMult = 3, dashCooldownMult = 3, abilityCooldown = 2, cashMult = 1 },
  cash = { cashMult = 12, damageMult = 8, doubleStrike = 7, thunder = 7, lifesteal = 7, critBonus = 6, execute = 5, burn = 5, defense = 5, regen = 5, pardon = 5, abilityCooldown = 2, blockGuard = 2, walkMult = 2, dashCooldownMult = 2 },
}
local RARE = { Common = 1, Rare = 1.3, Epic = 1.7, Legendary = 2.4 }

local function now() return workspace:GetServerTimeNow() end
local function rootOf(model)
  local part = model.PrimaryPart or model:FindFirstChild("HumanoidRootPart")
  if part and part:IsA("BasePart") then return part end
  return nil
end
-- every enemy on its feet: { model, root, hp, state, edge } with edge the flat gap to its side, nearest first
function arena.enemies()
  local out = {}
  local folder = workspace:FindFirstChild("ActiveEnemies")
  local mine = B.root()
  if not (folder and mine) then return out end
  local at = mine.Position
  for _, model in ipairs(folder:GetChildren()) do
    local state = model:GetAttribute("AIState")
    local hp = tonumber(model:GetAttribute("Health")) or 0
    local root = state ~= "Dead" and hp > 0 and rootOf(model) or nil
    if root and math.abs(root.Position.Y - at.Y) < 12 then
      out[#out + 1] = { model = model, root = root, hp = hp, state = state, edge = GB.flat(root.Position, at) - root.Size.X * 0.5 }
    end
  end
  table.sort(out, function(a, b) return a.edge < b.edge end)
  return out
end
-- what a creature's blow is: { kind, range | radius | distance, windup, ... } from the game's own table
local function blowOf(model)
  local Creatures = GB.def("Creatures")
  local id, kind = model:GetAttribute("CreatureId"), model:GetAttribute("AttackKind")
  if not (Creatures and id) then return nil end
  local creature
  if type(Creatures.get) == "function" then
    local ok, value = pcall(Creatures.get, id)
    if ok and type(value) == "table" then creature = value end
  end
  if not creature then
    local byId = type(Creatures.byId) == "table" and Creatures.byId or Creatures
    creature = type(byId[id]) == "table" and byId[id] or nil
  end
  if not (creature and type(creature.attacks) == "table") then return nil end
  for _, blow in ipairs(creature.attacks) do
    if blow.id == kind or blow.kind == kind then return blow end
  end
  return nil
end
-- The blow about to land on this body, if there is one: the enemy, the seconds left, how far it reaches. A blow is seen
-- while it winds up and lands when the wind-up ends: or later, by as long as the lunge, the charge or the arrow takes to
-- cross the gap (measured live 2026-11-11: with the shield timed to the wind-up alone, 13 arrows in 14 and every lunge
-- and charge got through, and every plain swing was met).
local incoming = {}
arena.incoming = incoming
-- Is this blow aimed at this body? The game's own test before it reacts (v746 ParryFx), so a wind-up that is not coming
-- this way is let be (2026-11-16: the fight backed off from every wind-up in reach, and as a Lancer in a horde it hardly
-- swung): a lunge or a charge when the body is within width/2 + 4 of the enemy's line and no more than its distance + 8
-- ahead; a swing or a breath when within its reach x 1.3 and inside half its arc + 25 degrees of where the enemy faces; a
-- slam when within its radius (+2) of the enemy; a shot when the enemy faces the body.
local function aimed(enemy, blow, at)
  local look = enemy.root.CFrame.LookVector
  look = Vector3.new(look.X, 0, look.Z)
  if look.Magnitude < 0.1 then return true end
  look = look.Unit
  local rel = Vector3.new(at.X - enemy.root.Position.X, 0, at.Z - enemy.root.Position.Z)
  local along = rel:Dot(look)
  local side = (rel - look * along).Magnitude
  local kind = blow and blow.kind or "melee"
  if kind == "lunge" or kind == "charge" then
    local width = tonumber(blow.width) or 3
    local distance = tonumber(blow.distance) or tonumber(blow.range) or 12
    return side <= width / 2 + 4 and along >= -2 and along <= distance + 8, along, look
  elseif kind == "slam" then
    return rel.Magnitude <= (tonumber(blow.radius) or 8) + 2, along, look
  elseif kind == "projectile" then
    return along > 0 and along <= (tonumber(blow.range) or 60) + 4 and side <= 5, along, look
  end
  local range = tonumber(blow and blow.range) or 6
  if rel.Magnitude > range * 1.3 + (enemy.root.Size.X * 0.5) then return false, along, look end
  if rel.Magnitude < 1 then return true, along, look end
  local arc = math.rad((tonumber(blow and blow.arc) or 90) / 2 + 25)
  return math.acos(math.clamp(rel.Unit:Dot(look), -1, 1)) <= arc, along, look
end
arena.aimed = aimed
-- The blow about to land on this body, of those aimed at it: { enemy, at (server time it lands), left, kind, blow, look }.
-- A lunge or a charge lands after the wind-up by its travel: max(0, along - Size.Z/2 - width/2 - 1.5) / speed (+ a
-- quarter of its ramp); a breath goes on burning for its duration.
function arena.threat(list, root)
  local clock = now()
  local at = root.Position
  for _, enemy in ipairs(list) do
    local state = enemy.state
    if state == "Windup" or state == "Charge" then
      local ends = tonumber(enemy.model:GetAttribute("WindupEnd"))
      local blow = ends and blowOf(enemy.model) or nil
      local kind = blow and blow.kind or "melee"
      local isAimed, along, look = aimed(enemy, blow, at)
      if ends and isAimed then
        local travel = 0
        if kind == "lunge" or kind == "charge" then
          local width = tonumber(blow and blow.width) or 3
          local speed = tonumber(blow and blow.speed) or (kind == "charge" and 55 or 42)
          travel = math.max(0, (along or 0) - enemy.root.Size.Z / 2 - width / 2 - 1.5) / speed + (tonumber(blow and blow.rampTime) or 0) * 0.25
        elseif kind == "projectile" then
          travel = math.max(enemy.edge, 0) / math.max(tonumber(blow and blow.speed) or 60, 10)
        end
        local foe = enemy.model
        incoming[enemy.model] = { enemy = enemy, at = ends + travel, kind = kind, blow = blow, look = look,
          lasts = kind == "breath" and (tonumber(blow and blow.duration) or 1.5) or 0,
          heavy = (tonumber(blow and blow.damage) or 1) >= 1.25 or foe:GetAttribute("Boss") == true or foe:GetAttribute("Champion") == true }
      elseif not isAimed and incoming[enemy.model] and incoming[enemy.model].kind ~= "charge" and not incoming[enemy.model].heavy then
        -- (turned away before it landed: let be; a charge keeps its line once it has started, and a heavy blow is run from
        -- until it has landed: a step aside out of its aim is not yet out of its reach)
        incoming[enemy.model] = nil
      end
    elseif state == "Attack" and not incoming[enemy.model] then
      -- A breath already burning that has turned onto this body after a wind-up that faced elsewhere: 11-16 round 60, a
      -- cerberus' breath burned three ticks of 15 at a time on a body that never saw it coming.
      local blow = blowOf(enemy.model)
      local ends = tonumber(enemy.model:GetAttribute("WindupEnd"))
      if blow and blow.kind == "breath" and ends then
        local lasts = tonumber(blow.duration) or 1.5
        local isAimed, _, look = aimed(enemy, blow, at)
        if isAimed and clock < ends + lasts then
          incoming[enemy.model] = { enemy = enemy, at = ends, kind = "breath", blow = blow, look = look, lasts = lasts, heavy = true }
        end
      end
    end
  end
  local best
  for model, blow in pairs(incoming) do
    local left = blow.at - clock
    if left < -(0.2 + blow.lasts) or not model.Parent or (tonumber(model:GetAttribute("Health")) or 0) <= 0 then
      incoming[model] = nil
    elseif left < 1.5 and (not best or left < best.left) then
      -- (a breath that is burning is a threat only while the body is still in its cone: one walked out of no longer
      -- hides the other blows coming)
      if not (left < 0 and blow.lasts > 0) or aimed(blow.enemy, blow.blow, at) then
        blow.left = left
        best = blow
      end
    end
  end
  return best
end
-- Ground that is about to be struck: the arrow storm's rings (MatchEvent "challengeFx", kind "volley": where, how wide,
-- and when on the server's clock) and a boss's marked circles (parts tagged BossMark). The one this body stands in that
-- lands soonest, or nil.
arena.hazards = {}
function arena.danger(root)
  local clock = now()
  local worst
  for index = #arena.hazards, 1, -1 do
    local hazard = arena.hazards[index]
    if clock > hazard.impact + 0.3 then
      table.remove(arena.hazards, index)
    elseif hazard.impact - clock < 3 and GB.flat(root.Position, hazard.at) < hazard.radius + 1.5 and (not worst or hazard.impact < worst.impact) then
      worst = hazard
    end
  end
  -- (the arrow storm's rings are parts tagged VolleyMark {ImpactAt, Radius} too, v746: leaving every one before it lands
  -- pays the round's "untouched" bonus)
  local okVolley, volley = pcall(function() return S.CollectionService:GetTagged("VolleyMark") end)
  for _, part in ipairs(okVolley and volley or {}) do
    local radius, impact = tonumber(part:GetAttribute("Radius")) or 9, tonumber(part:GetAttribute("ImpactAt"))
    if impact and part:IsA("BasePart") and impact - clock < 3 and impact - clock > -0.3
      and GB.flat(root.Position, part.Position) < radius + 1.5 and (not worst or impact < worst.impact) then
      worst = { at = part.Position, radius = radius, impact = impact }
    end
  end
  -- A boss's marks (BossHazardFx, v746): parts tagged BossMark. Circles (circle, puddle, star, rift: Radius) and lines
  -- (strip, lance: Dir, Length, Width), each struck at ImpactAt. A line is left sideways.
  local ok, marks = pcall(function() return S.CollectionService:GetTagged("BossMark") end)
  for _, part in ipairs(ok and marks or {}) do
    local impact = tonumber(part:GetAttribute("ImpactAt"))
    if impact and part:IsA("BasePart") and part:GetAttribute("Struck") ~= true and impact - clock < 3 and impact - clock > -0.3 and (not worst or impact < worst.impact) then
      local kind = part:GetAttribute("Kind")
      local dir = part:GetAttribute("Dir")
      local length, width = tonumber(part:GetAttribute("Length")), tonumber(part:GetAttribute("Width"))
      if (kind == "strip" or kind == "lance") and typeof(dir) == "Vector3" and length and width then
        local d = Vector3.new(dir.X, 0, dir.Z)
        if d.Magnitude > 0.1 then
          d = d.Unit
          local rel = Vector3.new(root.Position.X - part.Position.X, 0, root.Position.Z - part.Position.Z)
          local along = rel:Dot(d)
          local side = rel - d * along
          -- (whether the line starts at the part or is centred on it: both covered)
          if side.Magnitude < width / 2 + 1.5 and along > -length / 2 - 1.5 and along < length + 1.5 then
            local out = side.Magnitude > 0.3 and side.Unit or Vector3.new(-d.Z, 0, d.X)
            worst = { at = root.Position - side, radius = width / 2, impact = impact, line = out }
          end
        end
      else
        local radius = tonumber(part:GetAttribute("Radius"))
        if radius and GB.flat(root.Position, part.Position) < radius + 1.5 then
          worst = { at = part.Position, radius = radius, impact = impact }
        end
      end
    end
  end
  -- A boss's mechanics (BossMechFx, v746: folders tagged BossMech; Kind, StartAt, ImpactAt, Radius, Safe, ObjectValues
  -- Boss and Target). "leap": the boss jumps at its target; the circle follows the target until JumpAt, then sits at
  -- Center until it lands at ImpactAt: out of it the moment it is fixed (the owner, 2026-11-16: "dashes away when a boss
  -- jumps and shows a big red circle"). "ring": a wall closes on Center and strikes at ImpactAt: be inside Inner when it
  -- does (then an echo rolls out to EchoInner by EchoAt). "leash" is not danger but a place: arena.leash() below.
  local okMech, mechs = pcall(function() return S.CollectionService:GetTagged("BossMech") end)
  local character = B.character()
  for _, folder in ipairs(okMech and mechs or {}) do
    local impact = tonumber(folder:GetAttribute("ImpactAt"))
    local kind = folder:GetAttribute("Kind")
    if impact and type(folder:GetAttribute("Result")) ~= "string" then
      local radius = tonumber(folder:GetAttribute("Radius")) or 2
      local centre = folder:GetAttribute("Center")
      local targetValue = folder:FindFirstChild("Target")
      local target = targetValue and targetValue.Value
      local mine = target ~= nil and character ~= nil and (target == character or target == B.LP)
      if kind == "leap" and impact - clock > -0.3 and impact - clock < 4 then
        local jumpAt = tonumber(folder:GetAttribute("JumpAt")) or impact
        if typeof(centre) ~= "Vector3" and mine and clock < jumpAt then centre = root.Position end
        local gap = typeof(centre) == "Vector3" and GB.flat(root.Position, centre) or math.huge
        if gap < radius + (clock >= jumpAt and 10 or 2) and (not worst or impact < worst.impact) then
          -- (before the jump it follows this body: nothing to run from yet, but a dash is kept for it; once fixed, it is
          -- known a little way outside too, so a body that got out is not chased back in)
          worst = { at = centre, radius = radius, impact = impact, leap = true, fixed = clock >= jumpAt, clear = gap >= radius + 1.5 }
        end
        if mine and clock < impact then arena.leapComing = impact end
      elseif kind == "ring" and typeof(centre) == "Vector3" then
        local inner = tonumber(folder:GetAttribute("Inner")) or radius
        local echoAt, echoInner = tonumber(folder:GetAttribute("EchoAt")), tonumber(folder:GetAttribute("EchoInner"))
        local d = GB.flat(root.Position, centre)
        if clock < impact and impact - clock < 4 and d > inner - 1.5 and (not worst or impact < worst.impact) then
          worst = { at = centre, radius = inner, impact = impact, inside = true }
        elseif echoAt and echoInner and clock >= impact and clock < echoAt then
          -- (the echo: a ring rolling out from the middle to EchoInner; where it is now, and when it reaches this body)
          local reach = echoInner * math.clamp((clock - impact) / math.max(echoAt - impact, 0.1), 0, 1)
          if d < echoInner + 1 and d > reach - 1 then
            local reachesAt = impact + (d / math.max(echoInner, 0.1)) * (echoAt - impact)
            if not worst or reachesAt < worst.impact then worst = { at = centre, radius = echoInner, impact = reachesAt, echo = true } end
          end
        end
      end
    end
  end
  return worst
end
-- A boss's leash on this body (BossMech "leash"): the chain holds while the body is within Safe + Radius of the boss;
-- { anchor (the boss), leash } or nil.
function arena.leash(root)
  local okMech, mechs = pcall(function() return S.CollectionService:GetTagged("BossMech") end)
  local character = B.character()
  for _, folder in ipairs(okMech and mechs or {}) do
    if folder:GetAttribute("Kind") == "leash" and type(folder:GetAttribute("Result")) ~= "string" then
      local targetValue, bossValue = folder:FindFirstChild("Target"), folder:FindFirstChild("Boss")
      local target, boss = targetValue and targetValue.Value, bossValue and bossValue.Value
      if boss and (target == character or target == B.LP) then
        local part = boss:IsA("Model") and (boss.PrimaryPart or boss:FindFirstChild("HumanoidRootPart")) or (boss:IsA("BasePart") and boss) or nil
        if part then
          local reach = (tonumber(folder:GetAttribute("Safe")) or 14) + (tonumber(folder:GetAttribute("Radius")) or 2) - 2
          return { anchor = Vector3.new(part.Position.X, root.Position.Y, part.Position.Z), leash = math.max(reach, 4) }
        end
      end
    end
  end
  return nil
end
-- the boon to take of the ones offered: the rarest of what this way of playing wants
function arena.choose(offered, focus)
  local Boons = GB.def("Boons")
  local worth = WORTH[focus] or WORTH.damage
  local best, bestScore
  for index, entry in ipairs(offered) do
    local id = type(entry) == "table" and entry.id or entry
    if type(id) == "string" then
      local boon = Boons and type(Boons.get) == "function" and Boons.get(id) or nil
      local rarity = (type(entry) == "table" and entry.rarity) or (boon and boon.rarity) or "Common"
      local score = 0
      for key, amount in pairs(boon and type(boon.effect) == "table" and boon.effect or {}) do
        score += (worth[key] or 1) * (0.5 + math.min(math.abs(tonumber(amount) or 0), 1))
      end
      score = (score + 0.01 * (4 - index)) * (RARE[rarity] or 1)
      if not best or score > bestScore then best, bestScore = id, score end
    end
  end
  return best
end

local function start(hub)
  local map = {}
  for id, default in pairs({ fight = false, mode = "team", fightWhen = "tired", aura = false, chase = true, space = true, block = true, dodge = true,
    cast = true, boons = true, boonFocus = "damage", reviveFree = true, hurry = true, retry = true, skip = true, gate = "descend" }) do
    Config.define("glorybound." .. id, default)
    map[id] = "glorybound." .. id
  end
  local O = Config.mirror(map)
  arena.options = O
  local LP = B.LP

  local function kit() return GB.state.Kit or GB.attr("Kit") or "Gladiator" end
  -- the game's own hands, when they can be had: its attack is a click, with everything a click checks
  local function hands()
    if arena.combat == nil then arena.combat = GB.controller("CombatController") or false end
    return arena.combat or nil
  end
  -- on its feet in a match that is being fought
  function arena.active()
    if not GB.inArena() then return false end
    if GB.attr("CombatState") ~= "Alive" or GB.attr("Zone") ~= "Arena" then return false end
    if GB.matchState("Phase") == "Ending" then return false end
    return GB.alive()
  end
  -- is the queue (or a match) the body's business just now? The gym stands aside while it is.
  function arena.holding()
    if not O.fight then return false end
    local queue = GB.attr("Queue")
    return (type(queue) == "string" and queue ~= "") or arena.state == "asking" or GB.inArena()
  end

  -- ---------------------------------------------------------------- the shield, the feet
  local function setBlock(on, clock)
    if arena.blocking == on then return true end
    if clock - arena.blockAt < 0.16 then return false end
    local ok
    if on then ok = GB.send("Block", true, now()) else ok = GB.send("Block", false) end
    if ok then
      arena.blocking, arena.blockAt = on, clock
      if on then arena.blocks += 1 end
    end
    return ok
  end
  local function face(root, point)
    local flat = Vector3.new(point.X - root.Position.X, 0, point.Z - root.Position.Z)
    if flat.Magnitude < 0.3 then return end
    root.CFrame = CFrame.lookAt(root.Position, root.Position + flat)
  end
  local function turning(humanoid, own)
    -- (while it fights the body faces its enemy whichever way it steps: the engine would turn it to its walk)
    if arena.facing ~= own then
      arena.facing = own
      humanoid.AutoRotate = not own
    end
  end
  local function go(humanoid, point, clock)
    if clock - arena.told < 0.25 and arena.goal and (arena.goal - point).Magnitude < 2 then return end
    arena.told, arena.goal = clock, point
    humanoid:MoveTo(point)
  end
  local function stay(humanoid, root, clock)
    if arena.goal == nil then return end
    arena.goal, arena.told = nil, clock
    humanoid:MoveTo(root.Position)
  end
  -- The sand: an ellipse, and the game says how big (the Arena model's EllipseA and EllipseB, 95 and 70 studs on the
  -- live map; its bounding box takes in the stands and bounds nothing). A step back is never a step into the wall.
  local function ring()
    local model = workspace:FindFirstChild("Arena")
    if arena.ring and arena.ringOf == model then return arena.ring end
    local center, a, b = Vector3.new(0, 0, -1400), 55, 55
    if model then
      local mark = model:FindFirstChild("FloorCenter")
      if mark and mark:IsA("BasePart") then center = mark.Position end
      a = tonumber(model:GetAttribute("EllipseA")) or a
      b = tonumber(model:GetAttribute("EllipseB")) or b
    end
    arena.ring, arena.ringOf = { center = center, a = math.max(a, 10), b = math.max(b, 10), known = model ~= nil }, model
    return arena.ring
  end
  arena.ringNow = ring
  local function away(root, from, step)
    local out = Vector3.new(root.Position.X - from.X, 0, root.Position.Z - from.Z)
    out = out.Magnitude > 0.1 and out.Unit or Vector3.new(0, 0, 1)
    local r = ring()
    local point = root.Position + out * step
    local x, z = (point.X - r.center.X) / r.a, (point.Z - r.center.Z) / r.b
    if x * x + z * z > 0.81 then
      -- (near the wall: along it and towards the middle, not through it)
      local inward = Vector3.new(r.center.X - root.Position.X, 0, r.center.Z - root.Position.Z)
      inward = inward.Magnitude > 0.1 and inward.Unit or Vector3.new(0, 0, 1)
      local side = Vector3.new(-out.Z, 0, out.X)
      point = root.Position + (inward * 0.7 + side * 0.3).Unit * step
    end
    return point
  end
  -- A way out that stays on the sand: the way asked if a dash that way (16 studs) lands short of the wall; else along the
  -- wall to the side nearer the middle; else in towards the middle. Measured 11-16 (R35): a champion's maul landed five
  -- times running for 33 each, for the way out of its reach was into the wall, where a dash is refused and a walk goes
  -- nowhere.
  local function onSand(root, way, step)
    local r = ring()
    -- (only where the sand is known: an arena the game has not drawn is not guessed at)
    if not r.known then return way, false end
    local function value(dir)
      local land = root.Position + dir * step
      local x, z = (land.X - r.center.X) / r.a, (land.Z - r.center.Z) / r.b
      return x * x + z * z
    end
    if value(way) <= 0.8 then return way, false end
    local inward = Vector3.new(r.center.X - root.Position.X, 0, r.center.Z - root.Position.Z)
    inward = inward.Magnitude > 0.1 and inward.Unit or Vector3.new(0, 0, 1)
    -- (square to the blow first, the side nearer the middle before the other; then those halfway in; then straight in)
    local side = Vector3.new(-way.Z, 0, way.X)
    local d = side:Dot(inward)
    if d < 0 or (d == 0 and value(-side) < value(side)) then side = -side end
    for _, dir in ipairs({ side, -side, (side + inward).Unit, (inward - side).Unit }) do
      if value(dir) <= 0.8 then return dir, true end
    end
    return inward, true
  end
  arena.onSand = onSand

  -- ---------------------------------------------------------------- one swing
  local function strike(clock, target, root, any)
    local combat = hands()
    if combat and type(combat.attack) == "function" then
      if type(combat.getCooldowns) == "function" then
        local ok, cooldowns = pcall(combat.getCooldowns)
        if ok and type(cooldowns) == "table" and (tonumber(cooldowns.attack) or 0) > 0 then return false end
      end
      -- (only at someone: with no target the game swings where the camera looks, and its attack() says true whatever
      -- went out; measured 11-16: 12 presses in 8 s, 1 enemy hurt)
      if not any and type(combat.getTarget) == "function" then
        local okTarget, aimedAt = pcall(combat.getTarget)
        B.identity()
        if okTarget and aimedAt == nil then return false end
      end
      local ok, sent = pcall(combat.attack)
      B.identity()
      if ok and sent then
        arena.swings += 1
        return true
      end
      return false
    end
    -- By hand, where the game's controller cannot be had: the count after the last one the server took, and the way to the enemy.
    if clock < arena.nextSwing then return false end
    local flat = Vector3.new(target.root.Position.X - root.Position.X, 0, target.root.Position.Z - root.Position.Z)
    if flat.Magnitude < 0.05 then return false end
    local character = B.character()
    local seq = math.max(arena.seq, tonumber(character and character:GetAttribute("MoveSeq")) or 0) + 1
    if GB.send("Attack", seq, flat.Unit) then
      arena.seq = seq
      arena.swings += 1
      local sheet = type(GB.state.StatSheet) == "table" and GB.state.StatSheet or {}
      arena.nextSwing = clock + (SWING[kit()] or 0.45) * math.clamp(tonumber(sheet.cooldownMult) or 1, 0.5, 2) + 0.06
      return true
    end
    return false
  end
  -- A dash the way `direction` goes. The game's own dash picks its way from what is held against where the body looks,
  -- and goes forward when nothing is: so the body is turned that way and walked that way first. Kept off the wall.
  local function dashTo(humanoid, root, direction)
    local combat = hands()
    if not (combat and type(combat.dash) == "function") then return false end
    direction = Vector3.new(direction.X, 0, direction.Z)
    if direction.Magnitude < 0.1 then return false end
    direction = direction.Unit
    local r = arena.ringNow and arena.ringNow() or nil
    if r then
      local land = root.Position + direction * 16
      local x, z = (land.X - r.center.X) / r.a, (land.Z - r.center.Z) / r.b
      if x * x + z * z > 0.85 then return false end
    end
    root.CFrame = CFrame.lookAt(root.Position, root.Position + direction)
    humanoid:MoveTo(root.Position + direction * 16)
    local ok, went = pcall(combat.dash)
    B.identity()
    if ok and went then
      arena.dashes += 1
      arena.dashAt = os.clock()
    end
    return ok and went
  end
  local function cast(clock, target, root)
    if not O.cast then return end
    local equipped = GB.attr("AbilityEquipped")
    if type(equipped) ~= "string" or equipped == "" then return end
    local ready = tonumber(GB.attr("AbilityReadyAt")) or 0
    if now() < ready or clock - (arena.castAt or -math.huge) < 0.6 then return end
    if target.edge > 14 then return end
    local flat = Vector3.new(target.root.Position.X - root.Position.X, 0, target.root.Position.Z - root.Position.Z)
    if flat.Magnitude < 0.05 then return end
    arena.castAt = clock
    if GB.send("AbilityCast", flat.Unit) then arena.casts += 1 end
  end

  -- ---------------------------------------------------------------- a moment of the fight
  -- (rewritten 2026-11-16 for the owner's "smarter, faster" against v746; the numbers are the game's, NOTES.md)
  -- where each kit stands to hit: the Lancer's sweep reaches 10 and its thrusts 11 and 12.5, so it strikes from 8.5 and
  -- all three land; out of reach of most plain swings (4.5 to 7) all the same
  local BEST = { Gladiator = 5, Lancer = 8.5, Berserker = 7.5, Archer = 28 }
  arena.BEST = BEST
  local function cooldowns()
    local combat = hands()
    if combat and type(combat.getCooldowns) == "function" then
      local ok, value = pcall(combat.getCooldowns)
      B.identity()
      if ok and type(value) == "table" then return value end
    end
    return {}
  end
  -- a point kept within the round's leash (the chariot's push radius, the eye's zone)
  local function leashed(point, plan)
    if not (plan and plan.anchor and plan.leash) then return point end
    local off = Vector3.new(point.X - plan.anchor.X, 0, point.Z - plan.anchor.Z)
    if off.Magnitude <= plan.leash then return point end
    local at = plan.anchor + off.Unit * plan.leash
    return Vector3.new(at.X, point.Y, at.Z)
  end
  -- a walk there round whatever is in the way (GB.steer), told again at most every 0.15 s unless the goal moved
  local function steer(humanoid, root, point, clock)
    if clock - (arena.steeredAt or -math.huge) < 0.15 and arena.goal and (arena.goal - point).Magnitude < 1.5 then return end
    arena.steeredAt, arena.goal = clock, point
    arena.moving = GB.steer(humanoid, root, point)
  end
  local function flatUnit(v, fallback)
    v = Vector3.new(v.X, 0, v.Z)
    if v.Magnitude < 0.1 then return fallback or Vector3.new(1, 0, 0) end
    return v.Unit
  end
  -- Which way out of a blow: off a line (lunge, charge, shot, breath) to the side the body is already on; out of a slam
  -- radially; back out of reach from a plain swing. The way towards the leash's anchor when there is one.
  local function escape(threat, root, plan)
    local enemyAt = threat.enemy.root.Position
    local rel = Vector3.new(root.Position.X - enemyAt.X, 0, root.Position.Z - enemyAt.Z)
    local look = threat.look or flatUnit(-rel)
    local kind = threat.kind
    local way, need
    if kind == "slam" or kind == "melee" then
      way = flatUnit(rel)
      local reach = kind == "slam" and (tonumber(threat.blow and threat.blow.radius) or 8) + 3 or (tonumber(threat.blow and threat.blow.range) or 6) * 1.3 + 2
      need = math.max(reach - rel.Magnitude, 2)
    else
      local along = rel:Dot(look)
      local side = rel - look * along
      way = side.Magnitude > 0.3 and side.Unit or Vector3.new(-look.Z, 0, look.X)
      need = math.max((tonumber(threat.blow and threat.blow.width) or 3) / 2 + 4 - side.Magnitude, 2)
      if kind == "breath" then need = math.max(need, 8) end
    end
    if plan and plan.anchor then
      -- (the side nearer the anchor, so the leash holds)
      local toward = Vector3.new(plan.anchor.X - root.Position.X, 0, plan.anchor.Z - root.Position.Z)
      if toward.Magnitude > 1 and way:Dot(toward) < -0.2 and (kind ~= "slam" and kind ~= "melee") then way = -way end
    end
    -- (never into the wall: along it instead, and further, for along it a step gains less ground from the blow)
    local turned
    way, turned = onSand(root, way, 16)
    if turned then need = math.max(need * 1.6, need + 4) end
    return way, need
  end
  -- Who to cut down: the round's own target first; else by distance, the wounded and healers and thieves sooner, a shielded
  -- one facing the body later (80% off from its front); a leashed body only takes on what comes within reach of the leash.
  local function pick(list, root, plan, reach)
    if plan and plan.target then
      for _, enemy in ipairs(list) do
        if enemy.model == plan.target then return enemy end
      end
    end
    local best, bestScore
    for _, enemy in ipairs(list) do
      local model = enemy.model
      local inLeash = true
      if plan and plan.anchor and plan.leash then inLeash = GB.flat(enemy.root.Position, plan.anchor) <= plan.leash + reach + 2 end
      if inLeash then
        local score = enemy.edge
        local elite = model:GetAttribute("Elite")
        if elite == "Healer" then score -= 10 end
        if model:GetAttribute("Thief") then score -= 6 end
        local max = tonumber(model:GetAttribute("MaxHealth")) or enemy.hp
        score -= (1 - enemy.hp / math.max(max, 1)) * 5
        if elite == "Shielded" then
          local look = flatUnit(enemy.root.CFrame.LookVector)
          local to = flatUnit(root.Position - enemy.root.Position)
          if look:Dot(to) > 0.4 then score += 8 end
        end
        if not best or score < bestScore then best, bestScore = enemy, score end
      end
    end
    return best
  end

  local function fight(clock)
    local root, humanoid = B.root(), B.humanoid()
    if not (root and humanoid) then return end
    -- (the swings the server took: the character's MoveSeq goes up by one for each)
    local character = B.character()
    local seq = character and tonumber(character:GetAttribute("MoveSeq"))
    if seq and arena.lastSeq and seq > arena.lastSeq and seq - arena.lastSeq < 50 then arena.accepted = (arena.accepted or 0) + seq - arena.lastSeq end
    -- (a new body counts from the start again: the count follows it down as well as up)
    if seq then arena.lastSeq = seq end
    local list = arena.enemies()
    local mine = kit()
    local reach = REACH[mine] or 7
    local plan = GB.goal and GB.goal.plan and GB.goal.plan(root) or nil
    arena.plan = plan
    if plan and plan.why ~= arena.planWhy then
      arena.planWhy = plan.why
      GB.note(plan.why)
    elseif not plan then
      arena.planWhy = nil
    end
    local cd = cooldowns()
    local charges = tonumber(cd.dashCharges) or 0
    arena.charges = charges
    -- (a champion or a boss on the field may leap at this body, and its circle is fixed only ~0.6 s before it lands: too
    -- late to walk out of, so one dash is kept for it and its blows are walked from unless both are ready. Measured 11-16:
    -- two leaps landed, for 82 and 91, with both dashes spent on the champion's blows)
    -- (the round's own champion counts as one whatever its marks: 11-16 the Champion round's cerberus carried none)
    local champ = GB.goal and GB.goal.champion and GB.goal.champion() or nil
    arena.champ = champ
    local keep = 0
    for _, enemy in ipairs(list) do
      if enemy.model == champ or enemy.model:GetAttribute("Champion") or enemy.model:GetAttribute("Boss") then
        keep = 1
        break
      end
    end
    arena.keepDash = keep
    -- (low on health, the body comes before the round: a blow is got out of beyond the chariot's or the eye's leash, and
    -- with a dash when one is to spare. Measured 11-16: in the chariot rounds a brute's cleave landed again and again on
    -- a body held to the push, 271 down to 62, and one such run ended there)
    local low = (tonumber(humanoid.MaxHealth) or 0) > 0 and humanoid.Health / humanoid.MaxHealth < 0.4
    arena.low = low
    -- (a boss's leash on this body: a tether the fight keeps to, whatever else the round wants)
    local tether = arena.leash(root)
    if tether then
      plan = { kind = "leash", anchor = tether.anchor, leash = tether.leash, point = tether.anchor, target = plan and plan.target, why = "Held by the boss's leash." }
      arena.plan = plan
    end

    -- 1. Ground about to be struck (the arrow storm's rings, a boss's marks and mechanics).
    arena.leapComing, arena.holdUntil = nil, nil
    local hazard = O.dodge and arena.danger(root) or nil
    -- A boss's leap: the circle follows this body until the jump, so there is nothing to run from yet, only a dash to keep;
    -- once its landing is fixed, out at once, by dash if there is one (and the dash is untouchable as it lands).
    if hazard and hazard.leap then
      if hazard.fixed and hazard.clear then
        -- (out of it already: held out until it lands, blows still dodged meanwhile; 11-16 the stand-in walked straight
        -- back in after the champion and spent its second dash getting out again)
        arena.holdUntil = hazard.impact
        hazard = nil
      elseif hazard.fixed then
        local way = flatUnit(root.Position - hazard.at)
        if GB.flat(root.Position, hazard.at) < 3 then
          -- (from its very middle any way is out, but not into a body: 11-16, a leap landed with the body 8.7 studs in
          -- after a dash taken with the champion at its side. Away from whatever stands near, the nearest the most)
          local push = Vector3.new(0, 0, 0)
          for _, enemy in ipairs(list) do
            if enemy.edge < 12 then
              local off = Vector3.new(root.Position.X - enemy.root.Position.X, 0, root.Position.Z - enemy.root.Position.Z)
              if off.Magnitude > 0.1 then push += off.Unit / math.max(enemy.edge, 1) end
            end
          end
          if push.Magnitude > 0.05 then way = push.Unit end
        end
        way = onSand(root, way, 16)
        if arena.blocking then setBlock(false, clock) end
        if charges >= 1 and dashTo(humanoid, root, way) then
          arena.state = "dodging"
          arena.leapsDodged = (arena.leapsDodged or 0) + 1
          return
        end
        turning(humanoid, false)
        steer(humanoid, root, Vector3.new(hazard.at.X, root.Position.Y, hazard.at.Z) + way * (hazard.radius + 5), clock)
        arena.state = "dodging"
        return
      end
      hazard = nil
    end
    -- A ring closing in: into its middle before it strikes.
    if hazard and hazard.inside then
      turning(humanoid, false)
      local centre = Vector3.new(hazard.at.X, root.Position.Y, hazard.at.Z)
      local way = flatUnit(centre - root.Position)
      local need = GB.flat(root.Position, hazard.at) - (hazard.radius - 2.5)
      if need > 6 and hazard.impact - now() < need / math.max(humanoid.WalkSpeed, 8) + 0.2 and charges >= 1 and dashTo(humanoid, root, way) then
        arena.state = "dodging"
        return
      end
      steer(humanoid, root, centre, clock)
      arena.state = "dodging"
      if list[1] and list[1].edge <= reach then strike(clock, list[1], root) end
      return
    end
    -- The ring's echo rolling out: through it, untouchable, as it reaches this body.
    if hazard and hazard.echo then
      local left = hazard.impact - now()
      if left < 0.2 and left > -0.05 and charges >= 1 then
        if dashTo(humanoid, root, (onSand(root, flatUnit(root.Position - hazard.at), 16))) then
          arena.state = "dodging"
          return
        end
      end
      hazard = nil
    end
    if hazard and hazard.impact - now() < 1.8 then
      local way = hazard.line or flatUnit(root.Position - hazard.at)
      if plan and plan.anchor then
        local toward = flatUnit(plan.anchor - root.Position)
        if way:Dot(toward) < -0.3 then way = flatUnit(way + toward * 1.2, way) end
      end
      way = onSand(root, way, 16)
      if arena.blocking then setBlock(false, clock) end
      local left = hazard.impact - now()
      local inside = hazard.radius + 1.5 - GB.flat(root.Position, hazard.at)
      -- (late, and a dash left: dash out; else walk, swinging at whatever is in reach meanwhile. Not the dash kept for a
      -- champion's leap: 11-16 R45, a champion threw its marks and its leap together, the last dash went on a mark and the
      -- leap landed for 80)
      if left < 0.35 and inside > 2 and charges - keep >= 1 and dashTo(humanoid, root, way) then
        arena.state = "dodging"
        return
      end
      turning(humanoid, false)
      steer(humanoid, root, Vector3.new(hazard.at.X, root.Position.Y, hazard.at.Z) + way * (hazard.radius + 4), clock)
      arena.state = "dodging"
      if list[1] and list[1].edge <= reach then strike(clock, list[1], root) end
      return
    end

    -- 2. A blow aimed at this body (only those: the game's own test).
    local threat = (O.block or O.dodge) and arena.threat(list, root) or nil
    if threat then
      local kind, left = threat.kind, threat.left
      -- (a heavy hitter's plain blow too: a boss or champion, or a blow worth x1.25 or more, is dashed out of when a dash is
      -- there, not taken on the shield; the owner, 2026-11-16)
      local foe = threat.enemy.model
      local heavy = (tonumber(threat.blow and threat.blow.damage) or 1) >= 1.25 or foe:GetAttribute("Boss") == true or foe:GetAttribute("Champion") == true
        or foe == arena.champ or (tonumber(foe:GetAttribute("MaxHealth")) or 0) >= 3000
      local hard = kind == "slam" or kind == "charge" or kind == "breath" or (heavy and charges - keep >= 1)
      -- The Gladiator's shield, a quarter of a second ahead (a parry the game calls good) for what a shield stops.
      if O.block and mine == "Gladiator" and not hard and left <= 0.3 then
        turning(humanoid, true)
        face(root, threat.enemy.root.Position)
        stay(humanoid, root, clock)
        setBlock(true, clock)
        arena.state = "blocking"
        return
      end
      if O.dodge and (mine ~= "Gladiator" or hard) then
        local way, need = escape(threat, root, plan)
        -- across it just before it lands: the dash is untouchable for its first 0.15 s (in a zone or by the chariot, only a
        -- dash that lands inside it, unless the blow is a hard one: 11-16, an Eye round failed at 0.75 with dashes out)
        local keeps = true
        if plan and plan.anchor and plan.leash and not hard and not low then
          local land = root.Position + way * 16
          keeps = GB.flat(land, plan.anchor) <= plan.leash + 3
        end
        -- (a dash is kept for what cannot be walked from: a small blow gets one only with both charges ready, and none
        -- while a boss's leap is coming. Measured 11-16: a 14-stud leap landed with the body 8.2 studs in, both dashes
        -- spent; HP 86, and the run ended two rounds on)
        -- (low on health, the dash kept for a leap is spent on a heavy blow when no leap is on its way: a blow that lands
        -- now outweighs one that may come. 11-16 round 60: two bites of 58 walked from, 94 down to 38, a dash in hand)
        local spare = (hard and charges - keep >= 1) or (charges >= 2 and not arena.leapComing)
          or (low and charges - keep >= 1 and not arena.leapComing) or (low and (hard or heavy) and charges >= 1 and not arena.leapComing)
        -- A breath burns on for its duration (1.5 s for the champion hound): out of its cone to the side while it burns,
        -- swinging at whatever is in reach meanwhile. Measured 11-16: five ticks of 8 taken in a row, swinging at the
        -- hound from in front of it, for nothing dodged a blow once it had begun.
        if threat.lasts > 0 and left <= 0 then
          if arena.blocking then setBlock(false, clock) end
          if not threat.dashed and spare and charges >= 1 and not arena.leapComing and dashTo(humanoid, root, way) then
            threat.dashed = true
            arena.state = "dodging"
            return
          end
          turning(humanoid, false)
          steer(humanoid, root, leashed(root.Position + way * (need + 2), plan), clock)
          arena.state = "dodging"
          if list[1] and list[1].edge <= reach then strike(clock, list[1], root) end
          return
        end
        -- (dashed out of it already: held where the dash left it until it has landed, not walked back into its reach, and
        -- no second dash spent on the same blow)
        if threat.dashed and left > -0.1 then
          stay(humanoid, root, clock)
          arena.state = "dodging"
          if list[1] and list[1].edge <= reach then strike(clock, list[1], root) end
          return
        end
        if keeps and spare and charges >= 1 and left <= 0.2 and left > -0.05 then
          if arena.blocking then setBlock(false, clock) end
          if dashTo(humanoid, root, way) then
            threat.dashed = true
            arena.state = "dodging"
            return
          end
        end
        -- no dash to spend (or not yet time): walk out of it, early enough to make it at a walk (a heavy one sooner: a
        -- step started late is a bite of 33 taken at the edge of its reach)
        local speed = math.max(humanoid.WalkSpeed, 8)
        if left <= need / speed + ((hard or heavy) and 0.3 or 0.12) and left > -0.05 then
          if arena.blocking then setBlock(false, clock) end
          turning(humanoid, true)
          face(root, threat.enemy.root.Position)
          local out = root.Position + way * (need + 1.5)
          steer(humanoid, root, low and out or leashed(out, plan), clock)
          arena.state = "dodging"
          return
        end
      end
    end
    if arena.blocking then
      if not setBlock(false, clock) then return end
    end

    -- (out of a leap's circle that has yet to land: held there, swinging at what is in reach, not walked back into it)
    if arena.holdUntil and now() < arena.holdUntil + 0.05 then
      stay(humanoid, root, clock)
      arena.state = "dodging"
      if list[1] and list[1].edge <= reach then strike(clock, list[1], root) end
      return
    end

    -- 3. The round's errand: a purse to step on.
    if plan and plan.pickup then
      -- (a purse far off: a dash towards it when one is to spare, so the thieves do not get there first)
      local far = GB.flat(root.Position, plan.point)
      if far > 18 and charges >= 2 and not arena.leapComing and dashTo(humanoid, root, flatUnit(plan.point - root.Position)) then
        arena.state = "errand"
        return
      end
      turning(humanoid, false)
      steer(humanoid, root, plan.point, clock)
      arena.state = "errand"
      return
    end

    -- 4. The fight.
    local target = pick(list, root, plan, reach)
    if not target then
      arena.target = nil
      turning(humanoid, false)
      if plan and plan.point then
        steer(humanoid, root, plan.point, clock)
        arena.state = "errand"
      else
        stay(humanoid, root, clock)
        arena.state = "waiting"
      end
      return
    end
    arena.target = target.model
    cast(clock, target, root)
    local toTarget = flatUnit(target.root.Position - root.Position)
    -- The Lancer's dash thrust as the way in: a target 15 to 26 studs off, a dash kept for the next blow: dash at it and
    -- thrust within 0.35 s (a line 14 long, up to 4 hit, x1.5).
    if mine == "Lancer" and O.chase and not (plan and plan.anchor) and charges >= 2 and target.edge >= 15 and target.edge <= 26 and not threat and not arena.leapComing then
      if dashTo(humanoid, root, toTarget) then
        arena.thrustBy = clock + 0.32
        arena.state = "dash thrust"
        return
      end
    end
    if arena.thrustBy and clock <= arena.thrustBy then
      turning(humanoid, true)
      face(root, target.root.Position)
      if strike(clock, target, root, true) then arena.thrusts = (arena.thrusts or 0) + 1; arena.thrustBy = nil end
      return
    end
    arena.thrustBy = nil
    local best = BEST[mine] or (reach - 1.5)
    -- (a champion or a boss is fought by the Lancer from further off, and stepped back from sooner: its thrusts still land
    -- from 10.5, a lion's maul (6.5) does not. 11-16: three mauls in 7 s on a Lancer held at 8.5, 42 down to 1)
    local margin = 2.5
    local foe = target.model
    if mine == "Lancer" and (foe == arena.champ or foe:GetAttribute("Champion") == true or foe:GetAttribute("Boss") == true or (tonumber(foe:GetAttribute("MaxHealth")) or 0) >= 3000) then
      best, margin = 10.5, 1.5
    end
    if target.edge <= reach + 1 then
      arena.state = "fighting"
      turning(humanoid, true)
      face(root, target.root.Position)
      -- held at the kit's best distance: a step back from nearer than best - 2.5, a step in from further than best
      local half = target.root.Size.X * 0.5
      if O.space and target.edge < best - margin then
        steer(humanoid, root, leashed(target.root.Position - toTarget * (best + half), plan), clock)
      elseif O.chase and target.edge > best then
        steer(humanoid, root, leashed(target.root.Position - toTarget * (best + half - 0.5), plan), clock)
      elseif plan and plan.point and GB.flat(root.Position, plan.point) > 3 then
        steer(humanoid, root, leashed(plan.point, plan), clock)
      else
        stay(humanoid, root, clock)
      end
      strike(clock, target, root)
    elseif O.chase then
      arena.state = "chasing"
      turning(humanoid, false)
      steer(humanoid, root, leashed(target.root.Position - toTarget * (best + target.root.Size.X * 0.5 - 0.5), plan), clock)
    else
      arena.state = "waiting"
      turning(humanoid, false)
    end
  end
  local function rest()
    local humanoid = B.humanoid()
    if arena.facing and humanoid then turning(humanoid, false) end
    if arena.blocking then setBlock(false, os.clock()) end
    arena.goal, arena.target = nil, nil
  end

  -- ---------------------------------------------------------------- what the match says
  GB.on("MatchEvent", function(event)
    if type(event) ~= "table" or type(event.type) ~= "string" then return end
    local kind = event.type
    if kind == "boonOffer" then
      if event.userId ~= nil and event.userId ~= LP.UserId then return end
      local offered = event.boons or event.choices or event.options or event.offer or event.ids
      if type(offered) ~= "table" then return end
      arena.offer = { boons = offered, at = os.clock(), round = event.round }
    elseif kind == "boonPicked" then
      if event.userId == nil or event.userId == LP.UserId then arena.offer = nil end
    elseif kind == "challengeFx" then
      if event.kind == "volley" and type(event.rings) == "table" then
        for _, at in ipairs(event.rings) do
          if typeof(at) == "Vector3" then
            arena.hazards[#arena.hazards + 1] = { at = at, radius = tonumber(event.radius) or 9, impact = tonumber(event.impactAt) or (now() + 2) }
          end
        end
      end
    elseif kind == "bossCutscene" then
      -- (a boss's entrance: the game's own Skip sends BossCutsceneSkip(its id), BossCutscene controller; with breaks
      -- skipped, so is this)
      if O.skip and (O.fight or O.aura) and event.id ~= nil and event.canSkip ~= false and arena.skippedCut ~= event.id then
        arena.skippedCut = event.id
        task.delay(0.6, function()
          if B.alive and O.skip then GB.send("BossCutsceneSkip", event.id) end
        end)
      end
    elseif kind == "roundStart" then
      arena.round = tonumber(event.round) or arena.round
    elseif kind == "roundCleared" then
      arena.rounds += 1
    elseif kind == "downed" then
      if event.userId == LP.UserId then arena.downs += 1 end
    elseif kind == "matchEnd" then
      arena.ended = { at = os.clock(), result = tostring(event.result), round = tonumber(event.round) }
      GB.note("The match is over: " .. tostring(event.result) .. ", round " .. tostring(event.round) .. ".")
    elseif kind == "matchFound" then
      GB.note("A match was found.")
    end
  end)
  GB.on("RewardSummary", function(summary)
    if type(summary) ~= "table" then return end
    arena.matches += 1
    arena.cash += tonumber(summary.cash) or 0
    arena.xp += tonumber(summary.xp) or 0
    arena.last = { cash = tonumber(summary.cash) or 0, xp = tonumber(summary.xp) or 0, round = tonumber(summary.round) or 0, reason = tostring(summary.reason), at = os.clock(),
      chest = type(summary.chest) == "table" and summary.chest.tier or nil }
    arena.summary = os.clock()
    GB.toast("Round " .. arena.last.round .. ": " .. arena.last.reason, string.format("+$%s, +%s XP", util.comma(arena.last.cash), util.comma(arena.last.xp)), "trophy", "ok")
  end)
  GB.on("ReviveOffer", function(offer)
    if type(offer) ~= "table" or offer.id == nil then return end
    if offer.state ~= nil and offer.state ~= "open" then return end
    if arena.answered == offer.id then return end
    arena.answered = offer.id
    -- (a moment, as a hand would take; then the free one if there is one, and never the one that costs)
    task.delay(0.8, function()
      if not B.alive or not O.fight then return end
      local free = O.reviveFree and (tonumber(offer.credits) or 0) > 0
      GB.sendWhenDue(3, "ReviveOfferAnswer", offer.id, free and "buy" or "decline")
      GB.note(free and "Rose again, free." or "Passed on the paid revive.")
    end)
  end)

  -- ---------------------------------------------------------------- between rounds, and after the last
  -- The break between rounds: the game's own skip vote (BreakSkipHud: BreakSkip(true) is the state wanted; a vote while
  -- GameState.BreakSkip is "open", an opt-in while GameState.AutoSkip is on/wait/go; a majority skips it, and solo that is
  -- one). Never while it says "wait": that is the boon picks being waited for.
  local function skipBreak(clock)
    if not (O.skip and (O.fight or O.aura)) then return end
    if GB.matchState("Phase") ~= "InMatch" or GB.matchState("RoundPhase") ~= "Intermission" then return end
    if clock - (arena.skipAt or -math.huge) < 2 then return end
    local want = false
    local key = GB.matchState("BreakSkipKey")
    if GB.matchState("BreakSkip") == "open" and type(key) == "string" and key ~= "" and GB.attr("BreakSkipVoted") ~= key then want = true end
    local auto, autoKey = GB.matchState("AutoSkip"), GB.matchState("AutoSkipKey")
    if (auto == "on" or auto == "go") and type(autoKey) == "string" and autoKey ~= "" and GB.attr("AutoSkipOn") ~= autoKey then want = true end
    if want then
      arena.skipAt = clock
      if GB.send("BreakSkip", true) then arena.skips += 1 end
    end
  end
  -- Retry (the end screen's own: LeaveMatch("retry"), SummaryController) unless the lobby has something better: a rebirth
  -- that is ready, or the gym when the farm trains between runs.
  function arena.wantsRetry()
    if not O.retry then return false end
    local vault, gym = GB.vault, GB.gym
    if vault and vault.options and vault.options.rebirth and vault.rebirthReady and vault.rebirthReady() then return false end
    if O.fightWhen ~= "always" and gym and gym.wanted and gym.wanted() then return false end
    return true
  end

  -- After the pay: straight into another run, or back to the lobby now (the server's own return is 5 to 10 s). Only once
  -- the match is over for this body: down, or won (a won run ends with the body on its feet: 11-16 08:28, a run won at
  -- round 60 sent nothing and waited 16 s for the server's own return).
  local function afterPay(clock)
    if not (O.fight and arena.summary) then return end
    if GB.attr("CombatState") == "Alive" and not (arena.last and arena.last.reason == "Victory") then return end
    local waited = clock - arena.summary
    if arena.wantsRetry() and waited > 1.2 then
      arena.summary = nil
      if GB.send("LeaveMatch", "retry") then
        arena.retries += 1
        GB.note("Retrying: the next run, no trip to the lobby.")
      end
    elseif O.hurry and waited > 2.5 then
      arena.summary = nil
      GB.send("LeaveMatch", "continue")
    end
  end

  -- The nightmare gate (v746 NightmareGateUi): round 60 cleared, take the win or go 20 rounds deeper. GameState
  -- NightmareGate = "open" with NightmareGateEnds; the player's NightmareChoice is "" until chosen; the answer is the
  -- remote NightmareChoice "claim" | "descend". Answered late in its window, so one at the keyboard has most of it to
  -- choose for themselves (the owner's ask, 2026-11-16, with a screenshot of it: "an automatic respond when im not
  -- playing"; the nightmare rounds pay shards and sigils besides).
  local function gate(clock)
    if not (O.fight or O.aura) or (O.gate ~= "descend" and O.gate ~= "claim") then return end
    if GB.matchState("NightmareGate") ~= "open" then return end
    local chosen = GB.attr("NightmareChoice")
    if type(chosen) == "string" and chosen ~= "" then return end
    if clock - (arena.gateAt or -math.huge) < 3 then return end
    local ends = tonumber(GB.matchState("NightmareGateEnds"))
    if ends and ends - now() > 4 then return end
    arena.gateAt = clock
    if GB.send("NightmareChoice", O.gate) then
      arena.gates = (arena.gates or 0) + 1
      GB.note(O.gate == "descend" and "Through the nightmare gate: 20 rounds more." or "Took the win at the nightmare gate.")
    end
  end

  -- ---------------------------------------------------------------- the lobby: the queue
  local function wantsQueue()
    if not (O.fight and GB.inLobby() and GB.settled() and GB.synced) then return false end
    if GB.attr("Zone") == "Arena" or GB.attr("Sparring") == true then return false end
    local gym, vault = GB.gym, GB.vault
    -- (the shrine first: a rebirth that is ready is worth more than a match)
    if vault and vault.options and vault.options.rebirth and vault.rebirthReady() then return false end
    if O.fightWhen ~= "always" and gym and gym.wanted and gym.wanted() then return false end
    return true
  end
  local function lobby(clock)
    local queue = GB.attr("Queue")
    local queued = type(queue) == "string" and queue ~= ""
    if queued then
      if not O.fight and arena.queuedByUs then
        if GB.send("QueueLeave") then arena.queuedByUs = false end
        return
      end
      if arena.state ~= "queued" then
        arena.state, arena.queuedAt = "queued", clock
        GB.note("In the queue for " .. tostring(queue) .. ".")
      end
      return
    end
    if arena.state == "queued" then arena.state = "off" end
    if not wantsQueue() then
      if arena.state == "asking" then arena.state = "off" end
      return
    end
    if clock - arena.asked < 12 then return end
    arena.state = "asking"
    -- (off the barbell first, as the game's own mode screen does it)
    local gym = GB.gym
    if gym and gym.training() then
      gym.leave("queue")
      return
    end
    local ok
    if O.mode == "solo" then ok = GB.send("QueueJoin", "ArenaPVE", "solo") else ok = GB.send("QueueJoin", "ArenaPVE") end
    if ok then
      arena.asked, arena.queuedByUs = clock, true
      GB.note(O.mode == "solo" and "Asked for a solo run." or "Asked for a team match.")
    end
  end

  -- one pass of the loop; true when it ran through
  local function pass()
    local clock = os.clock()
    if not GB.started then
      task.wait(0.1)
    elseif GB.inArena() then
      if O.fight or O.aura then
        if arena.active() and (O.fight or O.aura) and GB.take("arena") then
          -- (the boon first: it is offered between rounds, when nothing is swinging)
          local offer = arena.offer
          if offer and O.boons and clock - offer.at > 0.7 then
            local id = arena.choose(offer.boons, O.boonFocus)
            arena.offer = nil
            if id and GB.send("BoonPick", id) then
              arena.boons[#arena.boons + 1] = id
              GB.note("Took the boon " .. id .. ".")
            end
          end
          B.try("glorybound.fight", fight, clock)
          B.try("glorybound.gate", gate, clock)
          -- (a won match ends with the body still on its feet, so its end is looked to from here as well)
          B.try("glorybound.after", afterPay, clock)
        else
          rest()
          GB.drop("arena")
          B.try("glorybound.gate", gate, clock)
          B.try("glorybound.after", afterPay, clock)
        end
        B.try("glorybound.skip", skipBreak, clock)
      else
        rest()
        GB.drop("arena")
      end
      task.wait(0.05)
    else
      if arena.facing or arena.blocking then rest() end
      GB.drop("arena")
      B.try("glorybound.queue", lobby, clock)
      task.wait(0.5)
    end
    return true
  end
  task.spawn(function()
    while B.alive do
      -- (2026-11-17: a fault in a pass is noted and the loop goes on; one used to end the whole fight farm)
      if not B.try("glorybound.arena", pass) then
        pcall(rest)
        GB.drop("arena")
        task.wait(0.5)
      end
    end
  end)
  B.own(function()
    local humanoid = B.humanoid()
    if humanoid and arena.facing then humanoid.AutoRotate = true end
    if arena.blocking then pcall(GB.send, "Block", false) end
  end)
end

local function farm(page)
  local box = page:section({ title = "Arena", icon = "swords", desc = "Queues, fights, comes back, queues again." })
  box:toggle({ id = "glorybound.fight", label = "Auto fight", desc = "Survival runs, start to finish.", default = false })
  box:segmented({ id = "glorybound.mode", label = "Run", desc = "Team waits for a party or bots. Solo starts at once, pays 85%.",
    options = { { "team", "Team" }, { "solo", "Solo" } }, default = "team", width = 150 })
  box:segmented({ id = "glorybound.fightWhen", label = "Go", desc = "Between sets: only when the gym has nothing to give.",
    options = { { "tired", "Between sets" }, { "always", "Always" } }, default = "tired", width = 210 })
  box:toggle({ id = "glorybound.retry", label = "Retry straight away", desc = "The next run without the lobby; a ready rebirth comes first.", default = true })
  box:toggle({ id = "glorybound.skip", label = "Skip breaks", desc = "Votes to cut the wait between rounds.", default = true })
  box:segmented({ id = "glorybound.gate", label = "Round 60 gate", desc = "20 more rounds, or the win now. Answered late, so you can pick first.",
    options = { { "descend", "Descend" }, { "claim", "Claim" }, { "off", "Ask me" } }, default = "descend", width = 230 })
  box:toggle({ id = "glorybound.hurry", label = "Leave when it ends", desc = "Asks for the lobby as soon as the pay is in.", default = true })
  local line = box:note({ icon = "info", text = "" })
  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    local text
    if arena.state == "queued" then text = string.format("In the queue, %d s.", math.floor(os.clock() - (arena.queuedAt or os.clock())))
    elseif GB.inArena() then text = string.format("Round %s  ·  %s  ·  %d swings landed  ·  %d dashes, %d blocks", tostring(GB.matchState("Round") or "?"), arena.state,
      arena.accepted or 0, arena.dashes, arena.blocks)
    else text = arena.matches > 0 and string.format("%d run%s  ·  $%s  ·  %s XP", arena.matches, arena.matches == 1 and "" or "s", util.comma(arena.cash), util.comma(arena.xp)) or "No run yet." end
    line.set(text)
  end, 2, "glorybound.arena.line")
end

local function combat(page)
  local hit = page:section({ title = "Blade", icon = "sword", desc = "How it fights, for Auto fight and for a match of your own." })
  hit:toggle({ id = "glorybound.aura", label = "Fight for me", desc = "In a match you joined by hand. Auto fight does it by itself.", default = false })
  hit:toggle({ id = "glorybound.chase", label = "Chase", desc = "Walks to the nearest enemy.", default = true })
  hit:toggle({ id = "glorybound.space", label = "Arm's length", desc = "Steps back from an enemy that is too close.", default = true })
  hit:toggle({ id = "glorybound.cast", label = "Cast the blessing", desc = "Your equipped ability, whenever it is ready.", default = true })

  local guard = page:section({ title = "Guard", icon = "shield", desc = "Reads every wind-up the server shows." })
  guard:toggle({ id = "glorybound.block", label = "Auto block", desc = "Gladiator: shield up just before a blow lands.", default = true })
  guard:toggle({ id = "glorybound.dodge", label = "Auto dodge", desc = "Dashes out of a slam, steps out of a swing.", default = true })
  guard:toggle({ id = "glorybound.reviveFree", label = "Free revives", desc = "Takes a revive that costs nothing. Never a paid one.", default = true })

  local boons = page:section({ title = "Boons", icon = "sparkles", desc = "Picked the moment they are offered." })
  boons:toggle({ id = "glorybound.boons", label = "Pick boons", desc = "The rarest one that suits the focus.", default = true })
  boons:segmented({ id = "glorybound.boonFocus", label = "Focus", tip = "What a boon is judged by.",
    options = { { "damage", "Damage" }, { "survive", "Survive" }, { "cash", "Cash" } }, default = "damage", width = 230 })
end

GB.parts[#GB.parts + 1] = { id = "arena", start = start, farm = farm, combat = combat }
end
do -- glorybound_daily.lua
-- ============================================================================
--  GloryBound   the daily gifts: the calendar, the wheel, the quests, a code
--
--  Read from the game (DailyController, DailyCodes, PatchNotesController, version 728):
--
--   * Everything is one remote, DailyAction(verb, key): "claim" (today's calendar gift),
--     "spin" (the wheel), "qclaim" with a quest's key (d1..d3, w1..w4) or a bonus row's
--     (dBonus, wBonus), "code" with the text typed. The answer is DailyResult { action, ok,
--     reason, ... }.
--   * What can be claimed is in DailyState, which the server sends whenever it changes:
--     cal.claimable; wheel.free + wheel.edictFree + wheel.bank (spins that cost nothing;
--     wheel.paid are bought with Robux and are left for the player to spend); quests.daily
--     and quests.weekly entries with canClaim; quests.bonus.daily / .weekly with ready.
--     The game's own DailyController hands back the last one it was sent (state()).
--   * The patch notes pay a chest once a version: PatchState { canClaim }, PatchAction
--     "opened" then "claim". The chest lands in OwnedChests and the vault part opens it.
--   * Lobby only, and only once the tutorial is done: the game's own buttons say the same. The wheel is not turned
--     from a barbell either (measured 2026-11-11: a spin sent mid-set came back "Finish your lift first."), so the
--     gym is asked to stand up for the moment a free spin takes. A quest's reward is paid mid-set all the same.
--   * A code is letters and digits, sixteen at most. Six wrong ones in a minute lock the
--     field for a minute: one is sent at a time and the answer is waited for.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util
local GB = B.GloryBound

local daily = { state = nil, patch = nil, claims = 0, spins = 0, quests = 0, busy = nil, last = nil, code = nil, wheelAt = -math.huge, refusedAt = {} }
GB.daily = daily

-- spins that cost nothing
function daily.freeSpins()
  local wheel = type(daily.state) == "table" and daily.state.wheel
  if type(wheel) ~= "table" or wheel.pending then return 0 end
  return (tonumber(wheel.free) or 0) + (tonumber(wheel.edictFree) or 0) + (tonumber(wheel.bank) or 0)
end
-- May a free spin wait while the body lifts? Only on a 1.5x seat that standing up would lose (gym.keepSeat), with room
-- in the bank (it holds bankMax, 5 measured on version 753: one more past that would be lost) and for 25 minutes at most.
daily.WAIT = 25 * 60
function daily.mayWait(clock)
  local gym = GB.gym
  if not (gym and gym.keepSeat and gym.keepSeat()) then return false end
  local wheel = type(daily.state) == "table" and daily.state.wheel or {}
  if (tonumber(wheel.bank) or 0) >= (tonumber(wheel.bankMax) or 5) - 1 then return false end
  return clock - (daily.heldSince or clock) < daily.WAIT
end
-- every key that can be claimed now, in the order the game lists them
function daily.ready()
  local out = {}
  local quests = type(daily.state) == "table" and daily.state.quests
  if type(quests) ~= "table" then return out end
  for _, list in ipairs({ quests.daily, quests.weekly }) do
    for _, quest in ipairs(type(list) == "table" and list or {}) do
      if type(quest) == "table" and quest.canClaim == true and type(quest.key) == "string" then out[#out + 1] = quest.key end
    end
  end
  local bonus = quests.bonus
  if type(bonus) == "table" then
    for _, name in ipairs({ "daily", "weekly" }) do
      local row = bonus[name]
      if type(row) == "table" and row.ready == true and row.claimed ~= true and type(row.key) == "string" then out[#out + 1] = row.key end
    end
  end
  return out
end
function daily.open()
  local state = daily.state
  return type(state) == "table" and state.unlocked == true and state.lobby ~= false
end

local function start(hub)
  local map = {}
  for id, default in pairs({ gifts = false, wheel = false, quests = false, patch = false }) do
    Config.define("glorybound." .. id, default)
    map[id] = "glorybound." .. id
  end
  Config.define("glorybound.code", "")
  local O = Config.mirror(map)
  daily.options = O

  GB.on("DailyState", function(state)
    if type(state) == "table" then daily.state = state end
  end)
  GB.on("DailyResult", function(result)
    if type(result) ~= "table" then return end
    daily.last = result
    daily.busy = nil
    local action = result.action
    -- (a no is a no for a minute: what the server would not take is not asked for again and again)
    if result.ok == false and type(action) == "string" then daily.refusedAt[action] = os.clock() end
    if action == "claim" and result.ok ~= false then
      daily.claims += 1
      GB.toast("Daily gift", "Day " .. tostring(result.streak or "?") .. " claimed.", "sunrise", "ok")
    elseif action == "spin" and result.ok ~= false then
      daily.spins += 1
    elseif action == "qclaim" and result.ok ~= false then
      daily.quests += 1
    elseif action == "code" then
      daily.code = { status = tostring(result.status or (result.ok and "ok" or "invalid")), at = os.clock(), wait = tonumber(result.wait) }
      if daily.code.status == "ok" then GB.toast("Code redeemed", nil, "badge-check", "ok") end
    end
  end)
  GB.on("PatchState", function(state)
    if type(state) == "table" then daily.patch = state end
  end)
  -- what was sent before the hub was here
  for name, key in pairs({ DailyController = "state", PatchNotesController = "patch" }) do
    local controller = GB.controller(name)
    if controller and type(controller.state) == "function" then
      local ok, value = pcall(controller.state)
      B.identity()
      if ok and type(value) == "table" then daily[key] = value end
    end
  end

  local function ask(verb, key)
    if not GB.send("DailyAction", verb, key) then return false end
    daily.busy = { verb = verb, at = os.clock() }
    return true
  end
  function daily.redeem(text)
    text = string.upper((string.gsub(tostring(text or ""), "[^%w]", "")))
    if text == "" or #text > 16 then return false, "empty" end
    if not (GB.inLobby() and GB.settled()) then return false, "lobby" end
    local code = daily.code
    if code and code.wait and os.clock() - code.at < code.wait then return false, "locked" end
    if daily.busy then return false, "busy" end
    return ask("code", text)
  end

  -- one pass of the loop; true when it ran through
  local function pass()
    local clock = os.clock()
    if daily.busy and clock - daily.busy.at > 8 then daily.busy = nil end
    if daily.freeSpins() <= 0 then daily.heldSince, daily.held = nil, false end
    local calm = GB.started and GB.inLobby() and GB.settled() and GB.attr("Zone") ~= "Arena"
    if calm and not daily.busy then
      if daily.open() then
        local state = daily.state
        local keys = daily.ready()
        if O.gifts and type(state.cal) == "table" and state.cal.claimable == true and clock - (daily.refusedAt.claim or -math.huge) > 60 then
          if ask("claim", nil) then GB.note("Claiming the daily gift.") end
        elseif O.quests and keys[1] and clock - (daily.refusedAt.qclaim or -math.huge) > 60 then
          if ask("qclaim", keys[1]) then GB.note("Claiming quest " .. keys[1] .. ".") end
        elseif O.wheel and daily.freeSpins() > 0 and clock - daily.wheelAt > 10 and clock - (daily.refusedAt.spin or -math.huge) > 60 then
          local lifting = GB.attr("Training")
          if type(lifting) == "string" and lifting ~= "" then
            -- (off the barbell for it: the gym stands up while this is asked, and sits down again after. Not off a 1.5x
            -- seat another player would take in those seconds, though: then the spin waits for the next time the body
            -- is up anyway, at the shrine or for a fight, unless the bank is nearly full or it has waited too long)
            daily.heldSince = daily.heldSince or clock
            if daily.mayWait(clock) then
              if not daily.held then GB.note("A free spin waits for the next rebirth: the 1.5x seat is kept.") end
              daily.held = true
            else
              daily.held = false
              GB.errand = { who = "wheel", ends = clock + 12 }
            end
          elseif ask("spin", nil) then
            -- (the wheel takes its time to turn: one spin, then the next when it has stopped)
            daily.wheelAt = clock
            daily.heldSince, daily.held = nil, false
            GB.errand = nil
            GB.note("Spinning the wheel.")
          end
        elseif GB.errand and GB.errand.who == "wheel" then
          GB.errand = nil
        end
      end
      local patch = daily.patch
      if O.patch and type(patch) == "table" and patch.canClaim == true and patch.claimed ~= true and clock - (daily.patchAt or -math.huge) > 20 then
        daily.patchAt = clock
        if GB.send("PatchAction", "opened") then
          task.wait(1.2)
          if GB.send("PatchAction", "claim") then GB.note("Claiming the patch notes chest.") end
        end
      end
    end
    -- (a spin held for the next break looks often: the body is up for only a few seconds at the shrine)
    task.wait(daily.held and 0.5 or 2)
    return true
  end
  task.spawn(function()
    while B.alive do
      if not B.try("glorybound.daily", pass) then task.wait(2) end
    end
  end)
end

local STATUS = { ok = "Redeemed.", invalid = "Not a code.", used = "Already used.", expired = "Expired.", locked = "Locked for a while.", busy = "Too many tries: wait.",
  timeout = "No answer.", empty = "Type a code first.", lobby = "In the lobby only." }
local function page(tab)
  local gifts = tab:section({ title = "Gifts", icon = "sunrise", desc = "Claimed in the lobby, as they come up." })
  gifts:toggle({ id = "glorybound.gifts", label = "Daily gift", desc = "Today's calendar reward.", default = false })
  gifts:toggle({ id = "glorybound.quests", label = "Quest rewards", desc = "Daily and weekly, and their bonus rows.", default = false })
  gifts:toggle({ id = "glorybound.wheel", label = "Free wheel spins", desc = "Only spins that cost nothing.", default = false })
  gifts:toggle({ id = "glorybound.patch", label = "Patch notes chest", desc = "One chest every update.", default = false })
  local line = gifts:note({ icon = "info", text = "" })

  local codes = tab:section({ title = "Code", icon = "key", desc = "From the game's own channels." })
  codes:input({ id = "glorybound.code", label = "Code", placeholder = "Type it here" })
  local answer
  codes:button({ id = "glorybound.redeem", label = "Redeem", desc = "Sends it once and waits for the answer.", text = "Redeem", bindable = false, run = function()
    local ok, why = daily.redeem(Config.get("glorybound.code"))
    if answer then answer.set(ok and "Sent." or (STATUS[why] or tostring(why))) end
  end })
  answer = codes:note({ icon = "info", text = "No code sent yet." })

  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    if type(daily.state) ~= "table" then
      line.set("Waiting for the game's daily state.")
    elseif not daily.open() then
      line.set("Not open yet: finish the tutorial, in the lobby.")
    else
      local cal = type(daily.state.cal) == "table" and daily.state.cal or {}
      line.set(string.format("Streak %s  ·  %s  ·  %d free spin%s  ·  %d quest%s ready", tostring(cal.streak or 0), cal.claimable and "gift ready" or "gift claimed",
        daily.freeSpins(), daily.freeSpins() == 1 and "" or "s", #daily.ready(), #daily.ready() == 1 and "" or "s"))
    end
    local code = daily.code
    if code and os.clock() - code.at < 30 then answer.set(STATUS[code.status] or code.status) end
  end, 2, "glorybound.daily.line")
end

GB.parts[#GB.parts + 1] = { id = "daily", start = start, daily = page }
end
do -- glorybound_goal.lua
-- ============================================================================
--  GloryBound   the round's challenge: what a round asks besides killing
--
--  Read from the game (version 746: Shared.Defs.Challenges, Shared.Config, ChariotGlideRule, PurseFx, ChallengeWorldFx;
--  every number is in based/_work/glorybound-1116/NOTES.md). The server tells the round's challenge in
--  ReplicatedStorage.GameState.Challenge and judges all of it itself; nothing here sends a remote.
--
--   * Chariot ("PUSH THE CHARIOT", round 3 and at random): it rolls while a fighter stands within 12 studs of it
--     (pushRadius), 4.5 studs a second, along Workspace.Arena.ChariotPath to the gate, 65 s. Where the server has it is
--     the CFrameValue GlideCF under the model (the client draws it a tenth of a second late). The body stands behind it,
--     inside the radius with room to spare, and fights whatever comes without leaving it.
--   * Treasure ("TREASURE HUNT"): purses are instances tagged Purse; one is taken by coming within 4.5 studs of it
--     (pickupRadius), once it has landed (LandAt) and while no thief holds it (State "carried"). Thieves are enemies with
--     a Thief attribute, Carrying = true while they hold one: those are cut down. 75% of the purses wins the round.
--   * Eye ("THE EMPEROR'S EYE"): a zone of radius 13 round GameState.ObjectivePos fills while a fighter stands in it.
--   * Rivals: the enemy whose RivalOf is this player's UserId (other players' rivals take 30% from you).
--   * Champion: GameState.ObjectiveTarget names it.
--  (Volley's rings are the arena part's to step out of: they are danger, not a goal.)
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util
local GB = B.GloryBound

local goal = { kind = nil, purses = 0, why = nil }
GB.goal = goal
-- the server's numbers (Shared.Config / Defs.Challenges, version 746)
goal.PUSH_RADIUS, goal.PICKUP_RADIUS, goal.EYE_RADIUS = 12, 4.5, 13

local function now() return workspace:GetServerTimeNow() end
local function partOf(inst)
  if not inst then return nil end
  if inst:IsA("BasePart") then return inst end
  if inst:IsA("Model") then return inst.PrimaryPart or inst:FindFirstChild("Base") or inst:FindFirstChildWhichIsA("BasePart", true) end
  return nil
end
local function tagged(tag)
  local ok, list = pcall(function() return S.CollectionService:GetTagged(tag) end)
  return ok and list or {}
end
local function alive(model)
  return model and model.Parent and (tonumber(model:GetAttribute("Health")) or 0) > 0 and model:GetAttribute("AIState") ~= "Dead"
end
function goal.challenge() return GB.matchState("Challenge") end

-- ---------------------------------------------------------------- the chariot
-- { model, position (the server's), cframe } or nil
function goal.chariot()
  local model = tagged("ChallengeChariot")[1]
  if not model then
    local folder = workspace:FindFirstChild("ChallengeObjects")
    model = folder and folder:FindFirstChild("Chariot")
  end
  if not (model and model.Parent) then return nil end
  local glide = model:FindFirstChild("GlideCF", true)
  local cframe = glide and glide:IsA("CFrameValue") and glide.Value or nil
  local base = partOf(model)
  if not cframe and base then cframe = base.CFrame end
  if not cframe then return nil end
  return { model = model, position = cframe.Position, cframe = cframe }
end
-- The way it rolls from here: towards the next point of Workspace.Arena.ChariotPath (numbered in their names).
local pathCache, pathOf = nil, nil
local function chariotPath()
  local arena = workspace:FindFirstChild("Arena")
  local folder = arena and arena:FindFirstChild("ChariotPath")
  if pathOf == folder and pathCache then return pathCache end
  local points = {}
  for _, part in ipairs(folder and folder:GetChildren() or {}) do
    if part:IsA("BasePart") then points[#points + 1] = { n = tonumber(part.Name:match("(%d+)")) or 0, position = part.Position } end
  end
  table.sort(points, function(a, b) return a.n < b.n end)
  pathCache, pathOf = points, folder
  return points
end
function goal.heading(position)
  local points = chariotPath()
  if #points < 2 then return nil end
  -- (the point it is nearest, and the one after it, or the last two)
  local best, bestD = 1, math.huge
  for index, point in ipairs(points) do
    local d = GB.flat(point.position, position)
    if d < bestD then best, bestD = index, d end
  end
  local ahead = points[math.min(best + 1, #points)].position
  if best == #points then ahead = points[#points].position end
  local way = Vector3.new(ahead.X - position.X, 0, ahead.Z - position.Z)
  if way.Magnitude < 0.5 then
    local a, b = points[math.max(best - 1, 1)].position, points[best].position
    way = Vector3.new(b.X - a.X, 0, b.Z - a.Z)
  end
  return way.Magnitude > 0.1 and way.Unit or nil
end

-- ---------------------------------------------------------------- purses and thieves
-- Purses that can be taken: landed (or about to), held by no thief. Nearest first: { inst, position, distance }.
function goal.purses(from)
  local list = {}
  local clock = now()
  for _, inst in ipairs(tagged("Purse")) do
    local part = partOf(inst)
    if part and part:IsDescendantOf(workspace) and inst:GetAttribute("State") ~= "carried" then
      local land = tonumber(inst:GetAttribute("LandAt")) or 0
      -- (one still in the air is gone for when it lands: the body is on its way meanwhile, there as it lands; measured
      -- 11-16 at 1.2 s ahead: 4 purses of 8, the thieves had the rest)
      if land <= clock + 4 then
        list[#list + 1] = { inst = inst, position = part.Position, distance = GB.flat(from, part.Position), landAt = land }
      end
    end
  end
  table.sort(list, function(a, b) return a.distance < b.distance end)
  return list
end
-- Thieves on their feet, the ones holding a purse first, then the nearest: { model, root, carrying }.
function goal.thieves(from)
  local list = {}
  local folder = workspace:FindFirstChild("ActiveEnemies")
  for _, model in ipairs(folder and folder:GetChildren() or {}) do
    if model:GetAttribute("Thief") and alive(model) then
      local root = partOf(model)
      if root then
        list[#list + 1] = { model = model, root = root, carrying = model:GetAttribute("Carrying") == true, distance = GB.flat(from, root.Position) }
      end
    end
  end
  table.sort(list, function(a, b)
    if a.carrying ~= b.carrying then return a.carrying end
    return a.distance < b.distance
  end)
  return list
end

-- ---------------------------------------------------------------- who to cut down first
function goal.rival()
  local folder = workspace:FindFirstChild("ActiveEnemies")
  local me = B.LP.UserId
  for _, model in ipairs(folder and folder:GetChildren() or {}) do
    if tonumber(model:GetAttribute("RivalOf")) == me and alive(model) then return model end
  end
  return nil
end
-- The champion GameState.ObjectiveTarget names: by name, or by what the model says it is.
function goal.champion()
  local target = GB.matchState("ObjectiveTarget")
  if type(target) ~= "string" or target == "" then return nil end
  local folder = workspace:FindFirstChild("ActiveEnemies")
  local wanted = string.lower(target)
  for _, model in ipairs(folder and folder:GetChildren() or {}) do
    if alive(model) then
      for _, said in ipairs({ model.Name, model:GetAttribute("DisplayName"), model:GetAttribute("Name"), model:GetAttribute("Title"), model:GetAttribute("CreatureName") }) do
        if type(said) == "string" and string.lower(said) == wanted then return model end
      end
      if model:GetAttribute("Champion") == true or model:GetAttribute("IsChampion") == true then return model end
    end
  end
  return nil
end

-- ---------------------------------------------------------------- what the round wants now
-- { kind, point = where to be, anchor + leash = stay within leash of anchor, pickup = walk onto point, target = model,
--   why } or nil when the round asks nothing but the fight.
function goal.plan(root)
  local O = goal.options
  if not (O and root) then return nil end
  local kind = goal.challenge()
  local here = root.Position
  if kind == "Chariot" and O.chariot then
    local chariot = goal.chariot()
    if chariot then
      -- (behind it, the side away from where it rolls, 6 studs off: well inside the 12-stud radius, out of its way)
      local heading = goal.heading(chariot.position) or Vector3.new(chariot.cframe.LookVector.X, 0, chariot.cframe.LookVector.Z)
      if heading.Magnitude < 0.1 then heading = Vector3.new(0, 0, 1) end
      local spot = chariot.position - heading.Unit * 6
      return { kind = "chariot", point = Vector3.new(spot.X, here.Y, spot.Z), anchor = Vector3.new(chariot.position.X, here.Y, chariot.position.Z),
        leash = goal.PUSH_RADIUS - 3, why = "Pushing the chariot." }
    end
  elseif kind == "Treasure" and O.purses then
    local thieves = goal.thieves(here)
    local purses = goal.purses(here)
    local carrying = thieves[1] and thieves[1].carrying and thieves[1] or nil
    -- (a purse a few strides away first; a thief running off with one before a purse across the sand)
    if purses[1] and (not carrying or purses[1].distance < carrying.distance + 10) then
      return { kind = "purse", point = Vector3.new(purses[1].position.X, here.Y, purses[1].position.Z), pickup = true, why = "Taking a purse." }
    end
    if carrying then return { kind = "thief", target = carrying.model, why = "After a thief with a purse." } end
    if thieves[1] then return { kind = "thief", target = thieves[1].model, why = "After a thief." } end
  elseif kind == "Eye" and O.eye then
    local centre = GB.matchState("ObjectivePos")
    if typeof(centre) == "Vector3" and centre.Magnitude > 1 then
      local at = Vector3.new(centre.X, here.Y, centre.Z)
      return { kind = "eye", point = at, anchor = at, leash = goal.EYE_RADIUS - 5, why = "Holding the Emperor's eye." }
    end
  elseif kind == "Rivals" then
    local rival = goal.rival()
    if rival then return { kind = "rival", target = rival, why = "After the rival." } end
  elseif kind == "Champion" then
    local champion = goal.champion()
    if champion then return { kind = "champion", target = champion, why = "At the champion." } end
  end
  return nil
end

local function start(hub)
  local map = {}
  for id, default in pairs({ chariot = true, purses = true, eye = true }) do
    Config.define("glorybound." .. id, default)
    map[id] = "glorybound." .. id
  end
  goal.options = Config.mirror(map)
end

local function combat(page)
  local box = page:section({ title = "Challenges", icon = "target", desc = "What each round asks, done while it fights." })
  box:toggle({ id = "glorybound.chariot", label = "Push the chariot", desc = "Stays by it and fights from there.", default = true })
  box:toggle({ id = "glorybound.purses", label = "Treasure hunt", desc = "Takes the purses, cuts down the thieves.", default = true })
  box:toggle({ id = "glorybound.eye", label = "Emperor's eye", desc = "Stands in the zone until it fills.", default = true })
end

GB.parts[#GB.parts + 1] = { id = "goal", start = start, combat = combat }
end
do -- glorybound_gym.lua
-- ============================================================================
--  GloryBound   the gym: a barbell, three reps a second, until the cap
--
--  Read from the game (TrainingController, StationPrompts, Shared.Config.Training, version 728):
--
--   * Twelve barbells, workspace.Lobby.Gym.Barbells.B1..B12, each a Model with MachineId,
--     Occupant (a UserId, 0 when free) and, on B7..B12, Boost = 1.5 and Unlock = "Community":
--     those are for members of the game's group (the Player's BoostUnlocked).
--   * Training starts at the barbell's own prompt (Prompt.TrainPrompt, 9 studs, no hold) and
--     the server answers by setting the Player's Training to the barbell's id. There is no
--     remote for it. It ends with TrainStop, or by itself when the body jumps or travels.
--   * Strength comes by the second while the body is on the barbell (BaseGainPerTick 50, times
--     1.2 a rebirth, the barbell's boost and how tired it is), and each rep adds to it. A rep is
--     a press of the button: the client counts one every third of a second at the most
--     (MaxRepsPerSecond 3), and sends the count, TrainRep(n), no more than twice a second
--     (RepSendInterval 0.5). The Auto trainer the game sells for Robux is that same loop, run
--     by the client on its own Heartbeat: what goes to the server is the same from either.
--   * Tired: Fatigue rises on the barbell and falls a point a second off it; a match takes 600
--     away. Under 900 the gains are whole, then 75%, 50%, 25% and 10% (TrainingMult says which).
--   * At the cap (Strength = StrengthCap) nothing more is gained and the game's own button
--     stops counting: it is the shrine's turn (see the vault part).
--
--  2026-11-17 (the owner: auto training must be steady and never stop, and with 1.5x picked always
--  go for the 1.5x barbells). Seen live on game version 753, a full server: all six 1.5x barbells
--  taken, and after a rebirth the body sat on a plain one for the rest of the cycle. Now: on a plain
--  (or lesser) barbell it looks every two seconds and moves up the moment a 1.5x one is free; a
--  fault in one pass of the loop is noted and the loop goes on (one error used to end the whole
--  farm until the hub was run again); a barbell that will not take the body is left alone for
--  longer each time it refuses.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util
local GB = B.GloryBound

local gym = { machine = nil, reps = 0, sends = 0, gained = 0, levels = 0, since = nil, sat = 0, tried = {}, refusals = {}, freeSince = {}, moves = 0, faults = 0, state = "off" }
GB.gym = gym
gym.REP, gym.SEND, gym.REACH, gym.LOOK = 1 / 3, 0.5, 6, 1
-- (a free one is gone to once it has stayed free this long, not at the first blink: measured on a full server, 11-17,
-- other players left a 1.5x seat 8.1, 11.7 and 13.9 s at a time and came back to it; this hub's own rebirth leaves it 4.9 s.
-- Two seconds, a look a second and a walk of three or four get there first against the first kind)
gym.SETTLE = 2

-- every barbell: { model, id, boost, locked, prompt, at }
local function machines()
  local lobby = workspace:FindFirstChild("Lobby")
  local room = lobby and lobby:FindFirstChild("Gym")
  local folder = room and room:FindFirstChild("Barbells")
  local out = {}
  for _, model in ipairs(folder and folder:GetChildren() or {}) do
    local id = model:GetAttribute("MachineId")
    local kind = model:GetAttribute("MachineType")
    local part = model:FindFirstChild("Prompt")
    local prompt = part and part:FindFirstChild("TrainPrompt")
    if id ~= nil and (kind == nil or kind == "Barbell") and prompt and part:IsA("BasePart") then
      local unlock = model:GetAttribute("Unlock")
      out[#out + 1] = { model = model, id = tostring(id), boost = tonumber(model:GetAttribute("Boost")) or 1,
        locked = type(unlock) == "string" and unlock ~= "", prompt = prompt, at = part.Position }
    end
  end
  return out
end
gym.machines = machines
-- someone else is on it: the barbell says so, or their own Training does (the two are set a moment apart)
local function taken(machine)
  local me = B.LP
  local who = tonumber(machine.model:GetAttribute("Occupant")) or 0
  if who > 0 and who ~= me.UserId then return true end
  for _, player in ipairs(S.Players:GetPlayers()) do
    if player ~= me and player:GetAttribute("Training") == machine.id then return true end
  end
  return false
end
gym.taken = taken
-- what a barbell gives: its boost (1.5 on the group's ones), 1 on a plain one
local function worth(machine) return machine and machine.locked and machine.boost or 1 end
gym.worth = worth
local function byId(id)
  if type(id) ~= "string" or id == "" then return nil end
  for _, machine in ipairs(machines()) do
    if machine.id == id then return machine end
  end
  return nil
end
gym.byId = byId
-- left alone for a while after it would not have the body: 12 s after a walk that failed, and 24, 48, ... up to five
-- minutes after each time the server would not seat it there
local function shut(machine, now)
  local at = gym.tried[machine.id]
  if not at then return false end
  return now - at < math.min(12 * 2 ^ (gym.refusals[machine.id] or 0), 300)
end
-- The best free one: the biggest boost this player may use, then the nearest (`except`: the one the body is on;
-- `settle`: only one seen free that long, see gym.SETTLE).
local function pick(useBoost, except, settle)
  local root = B.root()
  if not root then return nil end
  local open = GB.attr("BoostUnlocked") == true
  local best, bestBoost, bestGap
  local now = os.clock()
  for _, machine in ipairs(machines()) do
    local usable = not machine.locked or (open and useBoost)
    local settled = not settle or now - (gym.freeSince[machine.id] or now) >= settle
    if usable and settled and machine.id ~= except and not taken(machine) and not shut(machine, now) then
      local boost = worth(machine)
      local gap = GB.flat(root.Position, machine.at)
      if not best or boost > bestBoost or (boost == bestBoost and gap < bestGap) then best, bestBoost, bestGap = machine, boost, gap end
    end
  end
  return best
end
gym.pick = pick
-- how long each barbell has been free, as seen from the one the body is on (looked at every gym.LOOK while lifting)
function gym.watch(here)
  local now = os.clock()
  for _, machine in ipairs(machines()) do
    if machine.id == (here and here.id) or taken(machine) then
      gym.freeSince[machine.id] = nil
    elseif not gym.freeSince[machine.id] then
      gym.freeSince[machine.id] = now
    end
  end
end
-- A better barbell than the one the body is on, free for gym.SETTLE (with 1.5x picked): the one to move up to.
function gym.better()
  local here = byId(GB.attr("Training"))
  gym.watch(here)
  if not (gym.options and gym.options.trainBoost) then return nil end
  local other = pick(true, here and here.id, gym.SETTLE)
  if other and worth(other) > worth(here) + 1e-6 then return other end
  return nil
end
-- On a 1.5x barbell with no other 1.5x one free (for gym.SETTLE): standing up would hand the seat to another player in
-- the seconds it is empty (a full server keeps all six taken). What can wait for the next time the body is up anyway
-- (the wheel) waits.
function gym.keepSeat()
  local here = byId(GB.attr("Training"))
  if worth(here) <= 1 then return false end
  local other = pick(true, here.id, gym.SETTLE)
  return not (other and worth(other) >= worth(here))
end

function gym.training()
  local id = GB.attr("Training")
  return type(id) == "string" and id ~= ""
end
function gym.capped()
  local cap = GB.num("StrengthCap", 0)
  return cap > 0 and GB.num("Strength", 0) >= cap
end
-- how much of a tick's gain the body gets for how tired it is: 1, 0.75, 0.5, 0.25 or 0.1
function gym.gains() return GB.num("TrainingMult", 1) end

local function start(hub)
  local map = {}
  for id, default in pairs({ train = false, trainBoost = true, trainFloor = "full", trainRest = true }) do
    Config.define("glorybound." .. id, default)
    map[id] = "glorybound." .. id
  end
  local O = Config.mirror(map)
  gym.options = O
  local FLOOR = { full = 0.99, most = 0.74, half = 0.49, any = 0 }

  GB.onTraining:connect(function(fx)
    if fx.started then return end
    local gained = tonumber(fx.gained)
    if gained and gained == gained and gained > 0 then gym.gained += gained end
    if fx.levelUp then gym.levels += 1 end
  end)

  -- worth lifting now: on, in the lobby, under the cap, and not too tired for what was asked
  function gym.wanted()
    if not (O.train and GB.inLobby() and GB.settled()) then return false, "off" end
    if GB.attr("Sparring") == true or GB.attr("Zone") == "Arena" then return false, "busy" end
    -- (another part needs the body off the barbell for a moment: the wheel is not turned from one)
    if GB.errand and os.clock() < GB.errand.ends then return false, "errand" end
    -- (the queue has the body: the game's own mode screen takes it off the barbell too)
    if GB.arena and GB.arena.holding and GB.arena.holding() then return false, "queue" end
    if gym.capped() then return false, "cap" end
    if gym.gains() < (FLOOR[O.trainFloor] or 0.99) then return false, "tired" end
    return true
  end

  local pending, lastRep, sentAt = 0, 0, 0
  local function flush()
    if pending <= 0 then return true end
    local ok = GB.send("TrainRep", pending)
    if ok then
      gym.reps += pending
      gym.sends += 1
      pending, sentAt = 0, os.clock()
    end
    return ok
  end
  local function leave(why)
    -- (asked once: the server takes a moment to clear Training, and the game's own button waits half a second too)
    if gym.training() and os.clock() - (gym.leftAt or -math.huge) > 1 then
      -- (what was counted goes with it, but not at the cap: the game's own button counts nothing there)
      if not gym.capped() then flush() end
      if GB.send("TrainStop") then gym.leftAt = os.clock() end
    end
    pending = 0
    gym.machine, gym.since = nil, nil
    gym.state = why or "off"
    GB.drop("gym")
  end
  gym.leave = leave

  -- to a free barbell, and on it
  local function sit()
    local machine = pick(O.trainBoost)
    if not machine then
      gym.state = "full"
      GB.note("Every barbell is taken.")
      return false
    end
    gym.state = "walking"
    GB.note("Going to barbell " .. machine.id .. (machine.locked and string.format(" (%sx)", tostring(machine.boost)) or "") .. ".")
    local keep = function() return O.train and not gym.training() and not taken(machine) end
    local there, why = GB.walk(machine.at, gym.REACH, 25, keep)
    if not there and why == "stuck" then
      -- (a wall between: the game's own travel puts the body in the gym, and it walks from there)
      if GB.travel("Gym") then task.wait(1.2) end
      there, why = GB.walk(machine.at, gym.REACH, 25, keep)
    end
    if not there then
      if why ~= "called off" then gym.tried[machine.id] = os.clock() end
      return false
    end
    GB.halt()
    if not GB.prompt(machine.prompt) then
      gym.state = "no prompt"
      GB.note("This executor cannot press a prompt: walk up and press E once.")
      return false
    end
    local asked = os.clock()
    while B.alive and os.clock() - asked < 2.5 do
      if GB.attr("Training") == machine.id then
        gym.machine, gym.since, gym.state = machine, os.clock(), "lifting"
        gym.sat += 1
        gym.refusals[machine.id], gym.tried[machine.id] = nil, nil
        pending, lastRep, sentAt = 0, os.clock(), os.clock()
        GB.note("Lifting at barbell " .. machine.id .. (worth(machine) > 1 and string.format(" (%sx)", tostring(machine.boost)) or "") .. ".")
        return true
      end
      task.wait(0.1)
    end
    -- (the server did not take it: someone got there first, or it wants the body nearer. Another one, then, and this one
    -- left alone a little longer each time it says no)
    gym.tried[machine.id] = os.clock()
    gym.refusals[machine.id] = (gym.refusals[machine.id] or 0) + 1
    return false
  end

  local lookedAt = 0
  -- one pass of the loop; true when it ran through (a fault in it is caught below and the loop goes on)
  local function step()
    local want, why = false, "off"
    if GB.started then want, why = gym.wanted() end
    if not GB.started then
      task.wait(0.1)
    elseif gym.training() then
      if not want then
        if gym.state ~= why then
          if why == "cap" then GB.note("Strength is at its cap.") elseif why == "tired" then GB.note("Too tired to gain: resting.") end
        end
        leave(why)
        task.wait(0.2)
      else
        -- (found on a barbell it did not walk to: the player sat down, or the hub came back mid-set)
        if not gym.machine then
          gym.machine = byId(GB.attr("Training")) or { id = GB.attr("Training") }
          gym.since, gym.state = os.clock(), "lifting"
          GB.take("gym")
        end
        local now = os.clock()
        if now - lastRep >= gym.REP then
          lastRep = now
          pending += 1
        end
        if pending > 0 and now - sentAt >= gym.SEND then flush() end
        -- (on a plain barbell, or a lesser one, with a better one free now: up to it. Seats free up when their players go
        -- to the shrine or to a fight, and on a full server every 1.5x one can be taken when this one sat down)
        if now - lookedAt >= gym.LOOK then
          lookedAt = now
          local better = gym.better()
          if better then
            gym.moves += 1
            GB.note(string.format("Barbell %s (%sx) is free: moving up to it.", better.id, tostring(better.boost)))
            leave("moving")
            local asked = os.clock()
            while B.alive and gym.training() and os.clock() - asked < 2.5 do task.wait(0.1) end
          end
        end
      end
      task.wait()
    elseif want and GB.take("gym") then
      if not sit() then
        GB.drop("gym")
        task.wait(1)
      end
    else
      if gym.machine then leave(why) end
      if gym.state ~= "off" and not want then gym.state = why or "off" end
      task.wait(0.5)
    end
    return true
  end
  task.spawn(function()
    while B.alive do
      if not B.try("glorybound.gym", step) then
        -- (a fault: noted in the hub's faults, the body let go, and the farm goes on after a breath)
        gym.faults += 1
        pending, gym.machine, gym.since = 0, nil, nil
        GB.drop("gym")
        task.wait(1)
      end
    end
  end)
  B.own(function()
    -- (unloaded mid-set: what was counted is sent, and the body stays on its barbell as the player left it)
    if gym.training() and pending > 0 then pcall(flush) end
  end)
end

local function farm(page)
  local box = page:section({ title = "Gym", icon = "activity", desc = "Lifts for Strength, as fast as the game counts." })
  box:toggle({ id = "glorybound.train", label = "Auto train", desc = "Finds a free barbell and lifts.", default = false })
  box:toggle({ id = "glorybound.trainBoost", label = "1.5x barbells first", desc = "Moves up to one the moment it is free.", default = true })
  box:segmented({ id = "glorybound.trainFloor", label = "Lift down to", desc = "Tired lifting gains less.",
    options = { { "full", "100%" }, { "most", "75%" }, { "half", "50%" }, { "any", "Any" } }, default = "full", width = 200 })
  local line = box:note({ icon = "info", text = "" })
  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    local text
    if gym.state == "lifting" and gym.since then
      local here = gym.machine and (gym.machine.at and gym.machine or byId(gym.machine.id))
      local boost = worth(here) > 1 and string.format(" (%sx)", tostring(here.boost)) or ""
      text = string.format("Barbell %s%s  ·  %d reps  ·  %s XP (%s a minute)  ·  gains %d%%", tostring(gym.machine and gym.machine.id or "?"), boost, gym.reps,
        util.comma(gym.gained), util.comma(gym.gained / math.max((os.clock() - (gym.first or gym.since)) / 60, 1 / 60)), math.floor(gym.gains() * 100 + 0.5))
      if boost == "" and gym.options and gym.options.trainBoost and GB.attr("BoostUnlocked") == true then text = text .. "  ·  every 1.5x is taken: moves up when one frees" end
    elseif gym.state == "cap" then text = "At the cap: rebirth to lift again."
    elseif gym.state == "tired" then text = string.format("Resting: gains are at %d%%.", math.floor(gym.gains() * 100 + 0.5))
    elseif gym.state == "full" then text = "Every barbell is taken."
    elseif gym.state == "walking" or gym.state == "moving" then text = "Walking to a barbell."
    elseif gym.state == "queue" then text = "Off the barbell: a match is coming."
    else text = gym.reps > 0 and string.format("%d reps, %s XP this session.", gym.reps, util.comma(gym.gained)) or "Off." end
    line.set(text)
  end, 2, "glorybound.gym.line")
end

GB.parts[#GB.parts + 1] = { id = "gym", start = start, farm = farm }
end
do -- glorybound_vault.lua
-- ============================================================================
--  GloryBound   the vault: chests, what is worn, skills, the shrine
--
--  Read from the game (ChestController, InventoryController, SkillController, RebirthController
--  and Shared.Defs, version 728):
--
--   * A chest is bought with ChestBuy(tier), "Common" 400, "Rare" 1,200, "Epic" 3,200, and
--     opened with ChestOpen(uid), uid a key of OwnedChests ("<userId>_<n>"). The answer to both
--     is ChestResult { ok, tier, chestUid, reason, item = { kind, id, uid, rarity, name,
--     amount, duplicate } }. The game's own vault waits 2.5 s between buys and 1.15 s between
--     opens, and opens only in the lobby with the body not in a fight: so does this.
--   * A weapon is its id (OwnedWeapons[id], SelectedWeapons[kit] = id), a piece of armour a
--     uid (OwnedArmor[uid] = id, EquippedArmor[slot] = uid). WeaponEquip(id), ArmorEquip(uid).
--     The game calls a weapon better by its damage and a piece by its vitality: nothing else.
--   * A copy too many is a spare. ItemSell("All") sells every spare that is not locked; one
--     alone goes as ItemSell("Weapon", id) or ItemSell("Armor", id). Epic and better can be
--     salvaged at the forge instead, which is worth more than their price: they are kept
--     unless asked.
--   * A skill point is a level, three more a rebirth. Shared.Defs.Skills.canBuy is the game's
--     own rule (the tier's level, a node before it, the points) and is asked, not copied.
--   * Rebirth: Strength at its cap and the level the next one asks (3, 5, 6, 7, ...): the
--     server says so in RebirthReady. The game's button works only beside the shrine and
--     stops a set first (TrainStop, then Rebirth 0.3 s later). Strength goes back to 1, the
--     cap grows by half and every lift is worth a fifth more; levels, gear, cash and skills
--     stay, and a rebirth pays 3 points and, at some counts, a chest.
--   * Anything that asks for Robux is left alone: ShopPrompt, the paid vault, the skill reset.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util
local GB = B.GloryBound

local vault = { opened = 0, bought = 0, sold = 0, equipped = 0, skills = 0, rebirths = 0, items = {}, last = nil, waiting = nil, singles = true }
GB.vault = vault
local RARITY = { Common = 1, Uncommon = 2, Rare = 3, Epic = 4, Legendary = 5, Mythic = 6 }
local PRICE = { Common = 400, Rare = 1200, Epic = 3200 }
local SLOTS = { "Helmet", "Chestplate", "Gloves", "Legs", "Boots" }
local BRANCHES = { "Gladius", "Scutum", "Fortuna", "Numen" }
vault.RARITY, vault.PRICE = RARITY, PRICE

local def = GB.def

-- in the lobby, on its feet, out of any fight: where the game lets the vault and the backpack be used
function vault.calm()
  if not (GB.inLobby() and GB.settled()) then return false end
  local zone = GB.attr("Zone")
  if zone ~= nil and zone ~= "Lobby" then return false end
  local combat = GB.attr("CombatState")
  return combat ~= "Alive" and combat ~= "Downed"
end

-- ---------------------------------------------------------------- chests
local function serial(uid) return tonumber(string.match(tostring(uid), "_(%d+)$")) or 0 end
function vault.chests()
  local owned = GB.state.OwnedChests
  local out = {}
  if type(owned) ~= "table" then return out end
  for uid, value in pairs(owned) do
    local tier = type(value) == "table" and value.tier or value
    out[#out + 1] = { uid = uid, tier = tostring(tier) }
  end
  table.sort(out, function(a, b) return serial(a.uid) < serial(b.uid) end)
  return out
end

-- ---------------------------------------------------------------- what is worn
-- the best weapon of the kit in hand, by the game's own measure: damage
function vault.bestWeapon()
  local Weapons = def("Weapons")
  local owned, kit = GB.state.OwnedWeapons, GB.state.Kit
  if not (Weapons and type(Weapons.get) == "function" and type(owned) == "table" and type(kit) == "string") then return nil end
  local selected = type(GB.state.SelectedWeapons) == "table" and GB.state.SelectedWeapons[kit] or GB.state.SelectedWeapon
  local best, bestDamage
  for id in pairs(owned) do
    local item = Weapons.get(id)
    if type(item) == "table" and item.kit == kit and (tonumber(item.strengthReq) or 0) <= GB.num("Strength", 1) then
      local damage = tonumber(item.damage) or 0
      -- (as good as what is held is not a reason to change)
      if not best or damage > bestDamage or (damage == bestDamage and id == selected) then best, bestDamage = id, damage end
    end
  end
  if best and best ~= selected then
    local held = selected and Weapons.get(selected)
    if type(held) == "table" and (tonumber(held.damage) or 0) >= bestDamage then return nil end
    return best
  end
  return nil
end
-- for each slot, the piece with the most vitality that is not the one on: { { slot, uid }, ... }
function vault.bestArmor()
  local Armor = def("Armor")
  local owned = GB.state.OwnedArmor
  if not (Armor and type(Armor.get) == "function" and type(owned) == "table") then return {} end
  local worn = type(GB.state.EquippedArmor) == "table" and GB.state.EquippedArmor or {}
  local best = {}
  for uid, id in pairs(owned) do
    local item = Armor.get(id)
    if type(item) == "table" and type(item.slot) == "string" then
      local vitality = tonumber(item.vitality) or 0
      local top = best[item.slot]
      if not top or vitality > top.vitality or (vitality == top.vitality and worn[item.slot] == uid) then best[item.slot] = { uid = uid, vitality = vitality } end
    end
  end
  local out = {}
  for _, slot in ipairs(SLOTS) do
    local top = best[slot]
    if top and worn[slot] ~= top.uid then
      local on = worn[slot] and owned[worn[slot]] and Armor.get(owned[worn[slot]])
      if not (type(on) == "table" and (tonumber(on.vitality) or 0) >= top.vitality) then out[#out + 1] = { slot = slot, uid = top.uid } end
    end
  end
  return out
end

-- ---------------------------------------------------------------- spares
-- every copy too many, with what it is: { kind = "Weapon" | "Armor", id, rarity, count }
function vault.spares()
  local out = {}
  local Weapons, Armor = def("Weapons"), def("Armor")
  local locks = type(GB.state.ItemLocks) == "table" and GB.state.ItemLocks or {}
  local spare = type(GB.state.Spares) == "table" and GB.state.Spares.Weapon
  if type(spare) == "table" and Weapons then
    for id, count in pairs(spare) do
      count = tonumber(count) or 0
      local item = Weapons.get(id)
      if count > 0 and type(item) == "table" and not (type(locks.Weapon) == "table" and locks.Weapon[id]) then
        out[#out + 1] = { kind = "Weapon", id = id, rarity = tostring(item.rarity), count = count }
      end
    end
  end
  local owned = GB.state.OwnedArmor
  if type(owned) == "table" and Armor then
    local copies, locked = {}, {}
    for uid, id in pairs(owned) do
      copies[id] = (copies[id] or 0) + 1
      if type(locks.Armor) == "table" and locks.Armor[uid] then locked[id] = true end
    end
    for id, count in pairs(copies) do
      local item = Armor.get(id)
      -- (a piece with a lock on any copy of it is left whole: which copy a sale takes is the server's choice)
      if count > 1 and type(item) == "table" and not locked[id] then
        out[#out + 1] = { kind = "Armor", id = id, rarity = tostring(item.rarity), count = count - 1 }
      end
    end
  end
  table.sort(out, function(a, b) return a.id < b.id end)
  return out
end

-- ---------------------------------------------------------------- skills
-- The next node to put a point in: along the chosen branch (the cheapest tier first), the start of the tree before
-- anything, and another branch only once that one is full.
function vault.nextSkill(path)
  local Skills = def("Skills")
  local owned = type(GB.state.Skills) == "table" and GB.state.Skills or {}
  if not (Skills and type(Skills.canBuy) == "function" and type(Skills.list) == "table") then return nil end
  local level, points = GB.num("Level", 1), GB.num("SkillPoints", 0)
  if points <= 0 then return nil end
  local order = { path }
  for _, branch in ipairs(BRANCHES) do
    if branch ~= path then order[#order + 1] = branch end
  end
  local function buyable(id)
    local ok, why = Skills.canBuy(owned, id, level, points)
    return ok == true, why
  end
  -- (the tree's first node belongs to no branch and opens every one of them)
  for _, node in ipairs(Skills.list) do
    if node.branch == nil and buyable(node.id) then return node.id end
  end
  for _, branch in ipairs(order) do
    local best, bestTier, waits = nil, nil, false
    for _, node in ipairs(Skills.list) do
      if node.branch == branch then
        local ok, why = buyable(node.id)
        local tier = tonumber(node.tier) or 0
        if ok and (not best or tier < bestTier) then best, bestTier = node.id, tier end
        -- (something here will open with a level or more points: the points are kept for it)
        if not ok and why ~= "maxed" then waits = true end
      end
    end
    if best then return best end
    if waits then return nil end
  end
  return nil
end

-- ---------------------------------------------------------------- the shrine
function vault.shrine()
  local lobby = workspace:FindFirstChild("Lobby")
  local stations = lobby and lobby:FindFirstChild("Stations")
  local shrine = stations and stations:FindFirstChild("RebirthShrine")
  local prompt = shrine and shrine:FindFirstChildWhichIsA("ProximityPrompt", true)
  local part = prompt and prompt.Parent
  if not prompt then return nil end
  local at = (part:IsA("BasePart") and part.Position) or (part:IsA("Attachment") and part.WorldPosition) or nil
  if not at then return nil end
  return { at = at, reach = prompt.MaxActivationDistance }
end
-- the level the next rebirth asks (Shared.Defs.Rebirth.levelFor: 3, 5, 6, 7, ...)
function vault.rebirthLevel(count)
  count = math.clamp(math.floor(count), 0, 50)
  local late = count > 10 and math.floor((count - 10) / 6) or 0
  return math.clamp(math.floor(3 + 2 * count ^ 0.7) + late, 1, 250)
end
function vault.rebirthReady()
  if GB.num("Rebirth", 0) >= 50 then return false, "max" end
  local cap = GB.num("StrengthCap", 0)
  if not (GB.state.RebirthReady == true or (cap > 0 and GB.num("Strength", 0) >= cap)) then return false, "strength" end
  if GB.num("Level", 1) < vault.rebirthLevel(GB.num("Rebirth", 0)) then return false, "level" end
  return true
end

local function start(hub)
  local map = {}
  for id, default in pairs({ open = false, collect = true, buy = false, buyTier = "Epic", keep = 0, wear = false, sell = false, sellUpTo = "Rare",
    skills = false, skillPath = "Gladius", rebirth = false }) do
    Config.define("glorybound." .. id, default)
    map[id] = "glorybound." .. id
  end
  local O = Config.mirror(map)
  vault.options = O

  GB.on("ChestResult", function(result)
    if type(result) ~= "table" then return end
    vault.waiting = nil
    vault.last = result
    if result.ok == false then
      vault.refused = { at = os.clock(), reason = tostring(result.reason) }
      return
    end
    if result.bought or result.purchased then
      vault.bought += 1
      return
    end
    local item = result.item
    if type(item) ~= "table" then return end
    vault.opened += 1
    local entry = { kind = tostring(item.kind), name = tostring(item.name or item.id or item.amount or "?"), rarity = tostring(item.rarity or ""), duplicate = item.duplicate == true }
    table.insert(vault.items, 1, entry)
    if #vault.items > 12 then table.remove(vault.items) end
    if (RARITY[entry.rarity] or 0) >= RARITY.Epic then
      GB.toast(entry.rarity .. ": " .. entry.name, entry.duplicate and "A spare copy." or "From a " .. tostring(result.tier) .. " chest.", "gem", "ok")
    end
  end)

  local lastOpen, lastBuy, lastWear, lastSell, lastSkill = -math.huge, -math.huge, -math.huge, -math.huge, -math.huge
  local function chestsStep(now)
    if vault.waiting and now - vault.waiting < 6 then return end
    vault.waiting = nil
    if vault.refused and now - vault.refused.at < 20 then return end
    local owned = vault.chests()
    if O.open and #owned > 0 and now - lastOpen >= 1.3 then
      if GB.send("ChestOpen", owned[1].uid) then
        lastOpen, vault.waiting = now, now
        GB.note("Opening a chest: " .. owned[1].tier .. ".")
      end
      return
    end
    local price = PRICE[O.buyTier]
    if O.buy and price and #owned < 60 and GB.num("Cash", 0) - price >= O.keep and now - lastBuy >= 2.6 and now - lastOpen >= 1.3 then
      if GB.send("ChestBuy", O.buyTier) then
        lastBuy, vault.waiting = now, now
        GB.note("Buying a chest: " .. O.buyTier .. ".")
      end
    end
  end
  -- The game shows what came out and waits for its Collect button: on a chest this opened, the button is pressed
  -- (the button's own signal, as a click would fire it), or the screen would stay up over a farm nobody is watching.
  local function collectStep(now)
    if not O.collect or type(firesignal) ~= "function" or now - lastOpen > 45 then return end
    local gui = B.LP:FindFirstChildOfClass("PlayerGui")
    local screen = gui and gui:FindFirstChild("ChestReveal")
    local button = screen and screen.Enabled and screen:FindFirstChild("Collect", true) or nil
    if not (button and button:IsA("GuiButton") and button.Visible) then
      vault.collectSeen = nil
      return
    end
    if not vault.collectSeen then
      vault.collectSeen = now
      return
    end
    if now - vault.collectSeen < 1 then return end
    vault.collectSeen = nil
    pcall(firesignal, button.Activated)
    B.identity()
  end
  local function wearStep(now)
    if not O.wear or now - lastWear < 2 then return end
    local weapon = vault.bestWeapon()
    if weapon then
      if GB.send("WeaponEquip", weapon) then
        lastWear = now
        vault.equipped += 1
        GB.note("Took up a better weapon.")
      end
      return
    end
    local pieces = vault.bestArmor()
    if pieces[1] and GB.send("ArmorEquip", pieces[1].uid) then
      lastWear = now
      vault.equipped += 1
      GB.note("Better " .. string.lower(pieces[1].slot) .. " put on.")
    end
  end
  local function sellStep(now)
    if not O.sell or now - lastSell < 1.5 then return end
    local spares = vault.spares()
    if #spares == 0 then return end
    local ceiling = RARITY[O.sellUpTo] or RARITY.Rare
    local within, total = {}, 0
    for _, spare in ipairs(spares) do
      if (RARITY[spare.rarity] or 99) <= ceiling then within[#within + 1] = spare end
      total += spare.count
    end
    if #within == 0 then return end
    if #within == #spares then
      -- (every spare may go: the game's own "sell all", one call)
      if GB.send("ItemSell", "All") then
        lastSell = now
        vault.sold += total
        GB.note(string.format("Sold %d spare%s.", total, total == 1 and "" or "s"))
      end
      return
    end
    -- One at a time, and only while each one is seen to go: a sale the server did not take is not asked for twice.
    if not vault.singles then return end
    local spare = within[1]
    if vault.asked and vault.asked.kind == spare.kind and vault.asked.id == spare.id and vault.asked.count == spare.count then
      if now - vault.asked.at > 6 then vault.singles = false end
      return
    end
    if GB.send("ItemSell", spare.kind, spare.id) then
      lastSell = now
      vault.asked = { kind = spare.kind, id = spare.id, count = spare.count, at = now }
      vault.sold += 1
      GB.note("Sold a spare " .. string.lower(spare.rarity) .. " " .. string.lower(spare.kind) .. ".")
    end
  end
  local function skillStep(now)
    if not O.skills or now - lastSkill < 1 then return end
    local id = vault.nextSkill(O.skillPath)
    if id and GB.send("SkillUpgrade", id) then
      lastSkill = now
      vault.skills += 1
      GB.note("A point into " .. id .. ".")
    end
  end

  -- The shrine: the body is walked to it, a set is stopped as the game stops it, and the count is watched.
  local function trip(shrine)
    local before = GB.num("Rebirth", 0)
    -- (off the barbell first: the server holds a body that is lifting where it stands)
    local gym = GB.gym
    if gym and gym.training() then
      if gym.leave then gym.leave("cap") else GB.send("TrainStop") end
      local asked = os.clock()
      while B.alive and gym.training() and os.clock() - asked < 2 do task.wait(0.1) end
    end
    GB.take("shrine")
    GB.note("Going to the shrine.")
    local keep = function() return O.rebirth and vault.rebirthReady() and vault.calm() end
    local reach = math.max(4, shrine.reach - 3)
    local there, why = GB.walk(shrine.at, reach, 30, keep)
    if not there and why == "stuck" then
      if GB.travel("Gym") then task.wait(1.2) end
      there = GB.walk(shrine.at, reach, 30, keep)
    end
    if there then
      GB.halt()
      task.wait(0.3)
      if GB.sendWhenDue(3, "Rebirth") then
        local asked = os.clock()
        while B.alive and os.clock() - asked < 5 do
          if GB.num("Rebirth", 0) > before then
            vault.rebirths += 1
            GB.note("Reborn: rebirth " .. GB.num("Rebirth", 0) .. ".")
            GB.toast("Rebirth " .. GB.num("Rebirth", 0), "Strength starts again, with a higher cap.", "sunrise", "ok")
            break
          end
          task.wait(0.2)
        end
      end
    end
  end
  -- (2026-11-17: the body is let go however the trip ends. A fault on the way used to keep it held by the shrine for
  -- good, and with the rebirth done nothing came back to let it go: the gym could never have it again)
  local function rebirth()
    local shrine = vault.shrine()
    if not shrine then return false end
    if not GB.take("shrine") then return false end
    local ok, err = pcall(trip, shrine)
    GB.drop("shrine")
    vault.shrineAt = os.clock()
    if not ok then error(err, 0) end
    return true
  end

  task.spawn(function()
    while B.alive do
      if GB.started and vault.calm() and GB.synced then
        local now = os.clock()
        B.try("glorybound.vault.chests", chestsStep, now)
        B.try("glorybound.vault.collect", collectStep, now)
        B.try("glorybound.vault.wear", wearStep, now)
        B.try("glorybound.vault.sell", sellStep, now)
        B.try("glorybound.vault.skills", skillStep, now)
        if O.rebirth and vault.rebirthReady() and now - (vault.shrineAt or -math.huge) > 8 then B.try("glorybound.vault.rebirth", rebirth) end
      end
      task.wait(0.5)
    end
  end)
end

local function loot(page)
  local chests = page:section({ title = "Chests", icon = "package", desc = "Opened in the lobby, one at a time." })
  chests:toggle({ id = "glorybound.open", label = "Open chests", desc = "Every chest you own or win.", default = false })
  chests:toggle({ id = "glorybound.collect", label = "Press Collect", desc = "Closes the game's reveal screen after each one.", default = true })
  chests:toggle({ id = "glorybound.buy", label = "Buy chests", desc = "Spends spare cash at the vault.", default = false, children = function(sub)
    sub:segmented({ id = "glorybound.buyTier", label = "Which", tip = "Epic has the best odds for its price.", options = { { "Common", "Common" }, { "Rare", "Rare" }, { "Epic", "Epic" } }, default = "Epic", width = 220 })
    sub:slider({ id = "glorybound.keep", label = "Keep", tip = "Cash it never spends.", min = 0, max = 200000, step = 500, default = 0, curve = 2.5, format = function(v) return "$" .. util.comma(v) end })
  end })
  local line = chests:note({ icon = "info", text = "" })

  local gear = page:section({ title = "Gear", icon = "shield", desc = "Best damage, best vitality." })
  gear:toggle({ id = "glorybound.wear", label = "Wear the best", desc = "Equips a better weapon or piece at once.", default = false })
  gear:toggle({ id = "glorybound.sell", label = "Sell spares", desc = "Copies you have twice. Locked ones stay.", default = false, children = function(sub)
    sub:segmented({ id = "glorybound.sellUpTo", label = "Up to", tip = "Epic and better can be salvaged at the forge instead.",
      options = { { "Common", "Common" }, { "Uncommon", "Uncommon" }, { "Rare", "Rare" }, { "Mythic", "All" } }, default = "Rare", width = 290 })
  end })

  local grow = page:section({ title = "Growth", icon = "sprout", desc = "Points and rebirths, spent as they come." })
  grow:toggle({ id = "glorybound.skills", label = "Spend skill points", desc = "One branch first, then the rest.", default = false, children = function(sub)
    sub:segmented({ id = "glorybound.skillPath", label = "Branch", tip = "Gladius hits, Scutum lasts, Fortuna earns, Numen casts.",
      options = { { "Gladius", "Gladius" }, { "Scutum", "Scutum" }, { "Fortuna", "Fortuna" }, { "Numen", "Numen" } }, default = "Gladius", width = 300 })
  end })
  grow:toggle({ id = "glorybound.rebirth", label = "Auto rebirth", desc = "Walks to the shrine when Strength is capped.", default = false })
  local grown = grow:note({ icon = "info", text = "" })

  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    local owned = #vault.chests()
    local text = string.format("%d waiting  ·  %d opened  ·  %d bought", owned, vault.opened, vault.bought)
    local top = vault.items[1]
    if top then text = text .. "  ·  last: " .. (top.rarity ~= "" and (top.rarity .. " ") or "") .. top.name end
    line.set(text)
    local ready, why = vault.rebirthReady()
    local need = vault.rebirthLevel(GB.num("Rebirth", 0))
    grown.set(string.format("%d point%s to spend  ·  %s", GB.num("SkillPoints", 0), GB.num("SkillPoints", 0) == 1 and "" or "s",
      ready and "rebirth ready" or (why == "level" and ("rebirth needs level " .. need) or (why == "max" and "every rebirth done" or "rebirth at the Strength cap"))))
  end, 2, "glorybound.vault.line")
end

GB.parts[#GB.parts + 1] = { id = "vault", start = start, loot = loot }
end
do -- throwfood.lua
-- ============================================================================
--  Throw Food For Animals   throw, catch, place, train, and again
--
--  Read from the game on 2026-11-15 (place 120219252362013, universe 10766972131,
--  version 1264: 1,083 client scripts decompiled, and the live state of one account).
--  What every part of this module rests on, each one measured on the client:
--
--   * One folder of remotes, ReplicatedStorage.Remotes (Shared.Remotes makes them): the
--     actions are RemoteFunctions that answer a table, { Ok = true, ... } or { Ok = false,
--     Reason = "..." }. The game's own client asks them through Remotes.Invoke.
--   * A throw is four calls: Throw_Start (the server wants the body at the line: from the
--     plot it answers TooFar), Throw_MeterStarted (an event: the server starts the meter's
--     clock), Throw_Resolve(meter) and Throw_Complete. The meter swings on Shared.
--     ThrowMeterMath: at the top of its swing (HalfPeriod, 1.086 s) it is 1, "PERFECT", 20
--     studs more. Resolve sent at that moment came back Accuracy 0.9994 to 0.9996, and with
--     the catch in it (ModelName, Rarity, Rank, AreaIndex, Distance, FlightTime, Mutation).
--     Complete hands the animal over (AnimalId) once the server has waited out the flight
--     and the reveal itself: 3.8 to 4.3 s. None of the game's cinematic is needed for any of it.
--   * A throw gives no XP. XP comes from the pull-up bar: Training_Start works from anywhere
--     (it did from the line and from the plot), a rep each 0.5 s worth the bar's XpPerRep, and
--     level 6 -> 12 in 9 s on the second bar. Training_Bonus(id, ends) offers a tap bonus every
--     few seconds; Training_TapBonus(id) takes it (ExtraReps 1). A throw is refused while
--     training ("Training") and training while a throw is in flight ("Throwing"): the one body
--     does one or the other. Between a stop and the next start there is a short Cooldown.
--   * A level is 5 studs of throw power (Config.LevelConfig). How far a throw lands picks the
--     area and the depth in it; the food's Bait picks the animal there (Shared.AnimalRoll, the
--     same module the server rolls with). Income is base x mutation x size^1.8 (Shared.Mutations).
--   * What the server holds of the player is the PlayerData replica, read through the game's
--     own DataController (Money, Level, Xp, Stand, FenceLevel, EquippedFood, OwnedFoods, Animals...).
--   * The game moves a player who has not touched a key for 18 minutes to another server
--     (Controllers.AFKRejoin fires AFK_Rejoin). Its idle clock is the IdleSeconds upvalue.
--   * Shop_Prompt opens a Robux prompt; Gift_*, Sell_Protected and Dev_Action are Robux gifts,
--     bought animals and the developers' own: none of them is ever sent from here.
--
--  The parts (games/throwfood_*.lua) each own one thing: the throw and the bar, the plot and
--  the shop, the free things. This file is what they share.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util

local TF = { parts = {}, log = {}, calls = 0, refused = 0, started = false }
B.ThrowFood = TF
TF.PLACE, TF.UNIVERSE, TF.VERSION = 120219252362013, 10766972131, 1264
-- the game's rarities, lowest first (Config.RarityConfig, FoodsConfig)
TF.RARITY_ORDER = { "Common", "Uncommon", "Rare", "Epic", "Legendary", "Mythic", "Secret", "Divine", "Celestial", "Eternal",
  "Cosmic", "Supreme", "Sovereign" }
TF.rarityRank = {}
for index, name in ipairs(TF.RARITY_ORDER) do TF.rarityRank[name] = index end

-- ---------------------------------------------------------------- remotes
-- a Robux prompt, Robux gifts, bought animals, the developers' own tools, and the game's own way out of the server
local NEVER = { Shop_Prompt = true, Gift_Request = true, Gift_Respond = true, Gift_Cancel = true, Sell_Protected = true,
  Dev_Action = true, AFK_Rejoin = true, Shop_DevPromptCancelled = true }
TF.NEVER = NEVER
local remotes = {}
function TF.remote(name)
  local remote = remotes[name]
  if remote and remote.Parent then return remote end
  local folder = S.ReplicatedStorage:FindFirstChild("Remotes")
  remote = folder and folder:FindFirstChild(name) or nil
  remotes[name] = remote
  return remote
end
-- Asks the server and waits for its answer, never longer than `limit` s. Always hands back a table:
-- the server's own, or { Ok = false, Reason = "..." } with why there was none.
function TF.call(name, limit, ...)
  if NEVER[name] then return { Ok = false, Reason = "Never" } end
  local remote = TF.remote(name)
  if not (remote and remote:IsA("RemoteFunction")) then return { Ok = false, Reason = "NoRemote" } end
  local args = table.pack(...)
  local box = { done = false }
  TF.calls += 1
  task.spawn(function()
    local ok, value = pcall(function() return remote:InvokeServer(table.unpack(args, 1, args.n)) end)
    box.ok, box.value, box.done = ok, value, true
  end)
  local started = os.clock()
  limit = limit or 10
  while not box.done do
    if not B.alive then return { Ok = false, Reason = "Unloaded" } end
    if os.clock() - started > limit then return { Ok = false, Reason = "Timeout" } end
    task.wait()
  end
  B.identity()
  if not box.ok then return { Ok = false, Reason = "Error", Error = tostring(box.value) } end
  if type(box.value) ~= "table" then return { Ok = false, Reason = "BadResponse" } end
  if box.value.Ok ~= true then
    TF.refused += 1
    -- (what the server said no to, and why, by count: for the page, and for whoever reads a run afterwards)
    local key = name .. ":" .. tostring(box.value.Reason)
    TF.reasons[key] = (TF.reasons[key] or 0) + 1
  end
  return box.value
end
TF.reasons = {}
function TF.fire(name, ...)
  if NEVER[name] then return false end
  local remote = TF.remote(name)
  if not (remote and remote:IsA("RemoteEvent")) then return false end
  TF.calls += 1
  remote:FireServer(...)
  return true
end
function TF.on(name, fn)
  local remote = TF.remote(name)
  if not (remote and remote:IsA("RemoteEvent")) then return nil end
  return B.connect(remote.OnClientEvent, function(...)
    B.identity()
    fn(...)
  end, "throwfood." .. name)
end

-- ---------------------------------------------------------------- the game's own modules
-- A require of a module that is already running hands back what it returned: the game's own tables,
-- asked each time, never a copy an update would leave behind. "Config.GameConfig", "Shared.AnimalRoll", "AnimalsData".
local mods = {}
function TF.mod(path)
  local cached = mods[path]
  if cached ~= nil then return cached or nil end
  local found = false
  if type(require) == "function" then
    local node = S.ReplicatedStorage
    for name in string.gmatch(path, "[^%.]+") do
      node = node and node:FindFirstChild(name)
    end
    if node and node:IsA("ModuleScript") then
      local ok, value = pcall(require, node)
      B.identity()
      if ok and type(value) == "table" then found = value end
    end
  end
  -- (not there yet while the game loads: asked again next time, not remembered as missing)
  if found then mods[path] = found end
  return found or nil
end
-- One of the game's controllers (PlayerScripts.Client.Controllers.<name>), as the game loaded it.
local controllers = {}
function TF.controller(name)
  local cached = controllers[name]
  if cached then return cached end
  if type(require) ~= "function" then return nil end
  local scripts = B.LP:FindFirstChild("PlayerScripts")
  local client = scripts and scripts:FindFirstChild("Client")
  local folder = client and client:FindFirstChild("Controllers")
  local module = folder and folder:FindFirstChild(name)
  if not module then return nil end
  local ok, value = pcall(require, module)
  B.identity()
  if ok and type(value) == "table" then
    controllers[name] = value
    return value
  end
  return nil
end
-- (a call into the game's code, its answer or nil: the game's helpers are not ours to let throw)
function TF.ask(fn, ...)
  if type(fn) ~= "function" then return nil end
  local out = table.pack(pcall(fn, ...))
  B.identity()
  if not out[1] then return nil end
  return table.unpack(out, 2, out.n)
end

-- ---------------------------------------------------------------- what the server holds
-- The replica's own table (read, never written): nil until the game has it.
function TF.data()
  local dc = TF.controller("DataController")
  if not dc or type(dc.GetData) ~= "function" then return nil end
  local data = TF.ask(dc.GetData, dc)
  return type(data) == "table" and data or nil
end
function TF.num(key, default)
  local data = TF.data()
  local value = data and tonumber(data[key])
  if value ~= nil and value == value then return value end
  return default or 0
end
function TF.money() return TF.num("Money", 0) end
function TF.level() return math.max(1, TF.num("Level", 1)) end
function TF.attr(name) return B.LP:GetAttribute(name) end
-- The game has the player: data in, a body standing, no tutorial walking them by the hand.
function TF.ready()
  local data = TF.data()
  if not data or TF.attr("DataLoaded") == false then return false, "data" end
  local humanoid = B.humanoid()
  if not humanoid or humanoid.Health <= 0 or not B.root() then return false, "body" end
  local state = TF.controller("ClientState")
  if state and state.TutorialActive == true then return false, "tutorial" end
  return true
end
-- How far the next throw goes before the meter's bonus: the level's power, or less when the player set the slider lower.
function TF.power()
  local levels = TF.mod("Config.LevelConfig")
  local data = TF.data()
  if not (levels and data) then return 0 end
  return TF.ask(levels.EffectiveThrowPower, TF.level(), tonumber(data.ThrowPower) or 0) or 0
end
-- How many levels `seconds` on the bar would bring, by the game's own numbers: the bar's XpPerRep a rep each
-- Training.RepInterval (0.5 s), times the player's XP boosts (Shared.Boosts: passes, trail), against
-- Shared.BalanceCurve.GetXpForLevel (what the game's own level bar reads). Tap bonuses are left out.
function TF.levelsIn(seconds)
  local curve, stands, boosts, rules = TF.mod("Shared.BalanceCurve"), TF.mod("Config.StandsConfig"), TF.mod("Shared.Boosts"), TF.mod("Config.GameConfig")
  local data = TF.data()
  if not (curve and stands and data) then return 0 end
  local bar = TF.ask(stands.Get, math.max(1, tonumber(data.Stand) or 1))
  if not (bar and tonumber(bar.XpPerRep)) then return 0 end
  local boost = (boosts and TF.ask(boosts.Xp, B.LP) or 1) * (boosts and TF.ask(boosts.TrailXp, B.LP) or 1)
  local interval = rules and rules.Training and tonumber(rules.Training.RepInterval) or 0.5
  local xp = (tonumber(data.Xp) or 0) + bar.XpPerRep * boost * seconds / interval
  local level, gained = TF.level(), 0
  for _ = 1, 400 do
    local need = TF.ask(curve.GetXpForLevel, B.LP, level)
    if not need or need <= 0 or xp < need then break end
    xp -= need
    level += 1
    gained += 1
  end
  return gained
end
-- the level's whole power, whatever the slider says
function TF.fullPower()
  local levels = TF.mod("Config.LevelConfig")
  return levels and TF.ask(levels.ThrowPowerForLevel, TF.level()) or TF.power()
end
function TF.bonusStuds()
  local game = TF.mod("Config.GameConfig")
  return game and game.Throw and tonumber(game.Throw.MeterBonusStuds) or 20
end

-- The animals: on the plot and in the backpack, with what each one earns.
function TF.incomeOf(entry, best)
  local mutations = TF.mod("Shared.Mutations")
  if not mutations then return 0 end
  return TF.ask(mutations.IncomeOf, entry, best) or 0
end
function TF.slots()
  local fence = TF.mod("Config.FenceConfig")
  local level = TF.num("FenceLevel", 0)
  return fence and TF.ask(fence.SlotsFor, level) or 10
end
function TF.animals()
  local data = TF.data()
  local out = { placed = {}, backpack = {}, income = 0, worst = nil, best = nil }
  if not data or type(data.Animals) ~= "table" then return out end
  local mutations = TF.mod("Shared.Mutations")
  local bestIncome = mutations and TF.ask(mutations.BestIncome, data.Animals) or 1
  for id, entry in pairs(data.Animals) do
    if type(entry) == "table" and entry.ModelName then
      local item = { id = tostring(id), entry = entry, name = entry.ModelName, mutation = entry.Mutation, bought = entry.Bought == true,
        income = TF.incomeOf(entry, bestIncome) }
      if entry.Placed then
        out.placed[#out.placed + 1] = item
        out.income += item.income
        if not out.worst or item.income < out.worst.income then out.worst = item end
      else
        out.backpack[#out.backpack + 1] = item
      end
      if not out.best or item.income > out.best.income then out.best = item end
    end
  end
  out.slots = TF.slots()
  -- The plot as it would be with the best on it: what is in the backpack counts, as Equip best would put it out.
  -- `free` is what not even that fills; `floor` is what the weakest of that best plot earns.
  local all = {}
  for _, item in ipairs(out.placed) do all[#all + 1] = item.income end
  for _, item in ipairs(out.backpack) do all[#all + 1] = item.income end
  table.sort(all, function(a, b) return a > b end)
  out.free = math.max(0, out.slots - #all)
  out.floor = out.free > 0 and 0 or (all[out.slots] or 0)
  out.bestPlot = 0
  for i = 1, math.min(out.slots, #all) do out.bestPlot += all[i] end
  return out
end

-- One animal by name: { name, rarity, income, rank, area } from the game's own economy table.
local names, species = nil, {}
function TF.species(name)
  local known = species[name]
  if known then return known end
  local economy = TF.mod("Config.AnimalEconomy")
  local row = economy and (TF.ask(economy.Get, name) or (economy.List and economy.List[name]))
  if not names then
    -- (the names the game shows, "Polar Bear" for "Polar Bear", "Giraffe" for "Giraffee": once, from AnimalsData)
    local data = TF.mod("AnimalsData")
    if data then
      names = {}
      for _, list in pairs(data) do
        if type(list) == "table" then
          for _, animal in ipairs(list) do
            if type(animal) == "table" and animal.ModelName then names[animal.ModelName] = animal.Name or animal.ModelName end
          end
        end
      end
    end
  end
  known = { name = names and names[name] or name, model = name, rarity = row and row.Rarity or "?", income = row and tonumber(row.Income) or 0,
    rank = row and row.Rank, area = row and row.Area }
  if row then species[name] = known end
  return known
end

-- ---------------------------------------------------------------- where a throw lands, and what it may bring
-- { area, areaName, depth, distance } for a perfect throw of `power`. The server keeps a landing 8 studs inside the
-- area it falls in (AreaUtil.ComputeLanding, LandingEdgeMargin) and 4 studs off the lines between its thirds (KeepOffLines,
-- LineMargin): measured, power 488 + bonus 19.95 = 507.95 landed at 501, the far end of Desert, not in Jungle; 43 + 19.99
-- landed at 65, pushed past a third's line.
function TF.landing(power)
  local areas = TF.mod("Shared.AreaUtil")
  local config = TF.mod("Config.AreasConfig")
  local rules = TF.mod("Config.GameConfig")
  if not areas then return nil end
  local distance = (power or TF.power()) + TF.bonusStuds() * 0.998
  local position, index = TF.ask(areas.ComputeLanding, distance)
  if not (position and index) then return nil end
  local margin = rules and rules.Throw and tonumber(rules.Throw.LineMargin) or 4
  local z = TF.ask(areas.KeepOffLines, index, position.Z, margin) or position.Z
  local depth = TF.ask(areas.DepthInArea, index, z) or 0
  local area = config and TF.ask(config.Get, index)
  return { area = index, areaName = area and area.Name or ("Area " .. index), key = area and area.Key, depth = depth, distance = distance }
end
-- What the next throw may bring, by the game's own roll: the weight of each animal at that depth
-- with the food in hand, times the chance of each mutation (size can only add to it, and is left out).
--   chance: that it earns more than the weakest of the best plot (anything does when a slot is free)
--   gain:   what the plot is expected to earn more a second for it, and `share` that over what it earns now
function TF.odds(power)
  local roll, mutations = TF.mod("Shared.AnimalRoll"), TF.mod("Shared.Mutations")
  local animalsData, foods = TF.mod("AnimalsData"), TF.mod("Config.FoodsConfig")
  local spot = TF.landing(power)
  if not (roll and mutations and animalsData and foods and spot and spot.key) then return nil end
  local food = TF.ask(foods.Get, TF.num("EquippedFood", 1)) or TF.ask(foods.Get, 1)
  local weights = food and TF.ask(roll.Weights, food.Bait, spot.area, spot.depth)
  local list = animalsData[spot.key]
  if not (weights and type(list) == "table") then return nil end
  local plot = TF.animals()
  local floor = plot.floor or 0
  local chances = TF.ask(mutations.MutationChances, 1) or { { Multiplier = 0, Chance = 1 } }
  local chance, gain, top, topWeight = 0, 0, nil, -1
  for rank, weight in ipairs(weights) do
    local animal = list[rank]
    local base = animal and TF.species(animal.ModelName).income or 0
    for _, outcome in ipairs(chances) do
      local multiplier = (tonumber(outcome.Multiplier) or 0) > 0 and outcome.Multiplier or 1
      local value = base * multiplier
      if value > floor then
        local p = weight * (tonumber(outcome.Chance) or 0)
        chance += p
        gain += p * (value - floor)
      end
    end
    if weight > topWeight and animal then top, topWeight = animal.Name or animal.ModelName, weight end
  end
  local income = math.max(plot.bestPlot or plot.income or 0, 1)
  return { chance = math.clamp(chance, 0, 1), gain = gain, share = gain / income, free = plot.free, floor = floor, likely = top, spot = spot }
end

-- ---------------------------------------------------------------- the body
-- While the hub throws, the game's own line and bar are told it is busy, as the game tells them
-- during its own throw: nothing of the game's starts a second throw or a training under it.
function TF.hold(on)
  local state = TF.controller("ClientState")
  if not state then return end
  if on then
    if state.Busy == nil or state.Busy == "BASED" then state.Busy = "BASED" end
  elseif state.Busy == "BASED" then
    state.Busy = nil
  end
end
-- One body, and one part with it at a time: the throw does not have it walked to the shop under it.
-- A part takes it for what it does there and gives it back; a training goes on while the body is away
-- (measured: XP kept coming with the body at the food shop, 2026-11-16).
TF.owner, TF.queue = nil, {}
function TF.take(who)
  -- (the farm has the body nearly all the time: a short trip that is waiting for it goes first)
  if who == "farm" and TF.owner ~= "farm" then
    for other in pairs(TF.queue) do
      if other ~= who then return false end
    end
  end
  if TF.owner == nil or TF.owner == who then
    TF.owner = who
    return true
  end
  return false
end
function TF.release(who)
  if TF.owner == who then TF.owner = nil end
end
-- Where the server wants the body for a thing done on the plot (the game's own teleports, PlotController):
--   "shop"  the food shop's circle (Shop_Buy, Shop_Equip answer TooFar from away: measured)
--   "stand" in front of the pull-up bar's upgrade button (PlotController.TeleportToStand)
--   "fence" by the fence sign (FenceConfig.SignOffset, SignRange 22)
--   "plot"  the middle of the plot (an egg goes on it)
function TF.spot(kind)
  local plots = workspace:FindFirstChild("Plots")
  local index = TF.attr("PlotIndex")
  local part = plots and index and plots:FindFirstChild(tostring(index))
  local config = TF.mod("Config.GameConfig")
  if not (part and part:IsA("BasePart") and config and config.Plot) then return nil end
  local base, plotConfig = part.Position, config.Plot
  if kind == "shop" then
    return base + (plotConfig.ShopCircleOffset or Vector3.new(10.53, 0.51, -30.8)) + Vector3.new(0, 3, 0)
  elseif kind == "stand" then
    local button = base + (plotConfig.UpgradeButtonOffset or Vector3.new(-16, 0.65, -39))
    local spot = base + (plotConfig.TrainingSpotOffset or Vector3.new(-16, 0.5, -30.5))
    local away = Vector3.new(button.X - spot.X, 0, button.Z - spot.Z)
    away = away.Magnitude > 0.1 and away.Unit or Vector3.new(0, 0, -1)
    return button + away * 3.8 + Vector3.new(0, 3, 0), button
  elseif kind == "fence" then
    local fence = TF.mod("Config.FenceConfig")
    return base + (fence and fence.SignOffset or Vector3.new(-8.5, 0, -24.6)) + Vector3.new(0, 3.5, 4)
  elseif kind == "plot" then
    return base + Vector3.new(0, part.Size.Y / 2 + 3, 0)
  end
  return nil
end
function TF.goTo(position, face)
  local root = B.root()
  if not (root and position) then return false end
  root.AssemblyLinearVelocity = Vector3.zero
  root.CFrame = face and CFrame.lookAt(position, Vector3.new(face.X, position.Y, face.Z)) or CFrame.new(position)
  -- (the server reads where the body is from what reached it: a moment for the move to get there)
  task.wait(0.35)
  return true
end
-- Takes the body (waits for it up to `limit` s), stands it where `kind` is done, runs fn there, gives it back.
function TF.errand(who, kind, fn, limit)
  local started = os.clock()
  -- (asked by the part that has the body already, in the middle of what it does: it keeps it afterwards)
  local had = TF.owner == who
  if not had then
    TF.queue[who] = started
    -- (and not while the player is playing: their body is theirs then)
    local function playing() return TF.farm and TF.farm.paused and TF.farm.paused() end
    while playing() or not TF.take(who) do
      if not B.alive or os.clock() - started > (limit or 20) then
        TF.queue[who] = nil
        return nil, "busy"
      end
      task.wait(0.05)
    end
    TF.queue[who] = nil
  end
  local ok, result = pcall(function()
    local position, face = TF.spot(kind)
    if not position then return { Ok = false, Reason = "NoSpot" } end
    TF.goTo(position, face)
    return fn()
  end)
  if not had then TF.release(who) end
  B.identity()
  if not ok then return { Ok = false, Reason = "Error", Error = tostring(result) } end
  return result
end

-- the game itself busy with the player: a throw, a training or an egg hatch of the game's own
-- (its offline screen is not: it stays up until the player closes it, and the hub claims what it offers)
function TF.gameBusy()
  local state = TF.controller("ClientState")
  if not state then return false end
  return state.Busy ~= nil and state.Busy ~= "BASED"
end
B.own(function() pcall(TF.hold, false) end)

-- ---------------------------------------------------------------- numbers, the log, the line on the page
-- The game's own way of writing money (1.2K, 3.4Qa ...): its numbers go past 1e50.
function TF.cash(n)
  local format = TF.mod("Shared.NumberFormat")
  local text = format and TF.ask(format.Money, n)
  if type(text) == "string" then return text end
  return "$" .. util.comma(math.floor(tonumber(n) or 0))
end
function TF.short(n)
  local format = TF.mod("Shared.NumberFormat")
  local text = format and TF.ask(format.Abbreviate, n)
  if type(text) == "string" then return text end
  return util.comma(math.floor(tonumber(n) or 0))
end
function TF.note(text)
  local log = TF.log
  log[#log + 1] = { at = os.clock(), text = text }
  if #log > 40 then table.remove(log, 1) end
  TF.status = text
end
function TF.toast(title, text, icon, tone)
  if Config.get("throwfood.toasts") == false then return end
  Window.toast({ title = title, text = text, icon = icon or "target", tone = tone or "accent", time = 4 })
end
TF.onCatch = B.Signal.new()

local function statusLine()
  if not TF.data() then return "Waiting for the game's data." end
  local parts = { string.format("Level %s", util.comma(TF.level())), string.format("Power %s", TF.short(TF.power())) }
  local spot = TF.landing()
  if spot then parts[#parts + 1] = string.format("lands in %s (%d%%)", spot.areaName, math.floor(spot.depth * 100 + 0.5)) end
  parts[#parts + 1] = TF.cash(TF.money())
  local plot = TF.animals()
  parts[#parts + 1] = TF.cash(plot.income) .. "/s"
  parts[#parts + 1] = string.format("plot %d/%d", #plot.placed, plot.slots or 10)
  return table.concat(parts, "  ·  ")
end
TF.statusLine = statusLine

-- ---------------------------------------------------------------- the tabs
-- A part adds its cards to a tab by naming it: { id, start = fn(hub), farm = fn(page), plot = fn(page), shop = fn(page), extra = fn(page) }
local function extend(kind, page)
  for _, part in ipairs(TF.parts) do
    if part[kind] then B.try("throwfood." .. part.id .. "." .. kind, part[kind], page) end
  end
end
local function has(kind)
  for _, part in ipairs(TF.parts) do
    if part[kind] then return true end
  end
  return false
end

-- The whole farm in one press. It spends the game's cash (food, bars, the fence) and sells what is not on the plot:
-- that is how this game moves on. Robux is never asked for.
local FULL = { "throw", "train", "tapBonus", "equip", "sell", "equipFood", "buyFood", "buyBars", "buyFence",
  "claimFree", "offline", "index", "trail", "eggs", "stay" }
TF.FULL = FULL
function TF.preset(on)
  for _, id in ipairs(FULL) do Config.set("throwfood." .. id, on == true) end
end

local function farmPage(hub)
  hub:page({ id = "farm", title = "Farm", icon = "target", build = function(page)
    local you = page:section({ title = "You", icon = "user", full = true })
    local line = you:note({ icon = "activity", text = statusLine() })
    local doing = you:note({ icon = "info", text = "" })
    you:button({ id = "throwfood.full", label = "Full auto", desc = "Throws, trains, places the best, sells the rest, buys upgrades.", text = "Switch on", run = function()
      TF.preset(true)
      Window.toast({ title = "Full auto is on", text = "Robux is never asked for.", icon = "repeat", tone = "ok", time = 4 })
    end })
    you:button({ id = "throwfood.stop", label = "Stop", desc = "Everything off.", text = "Switch off", run = function()
      TF.preset(false)
      Window.toast({ title = "The farm is off", icon = "circle-pause", time = 3 })
    end })
    Motion.every(function()
      if not (line.frame.Parent and Window.anyOpen()) then return end
      line.set(statusLine())
      doing.set(TF.status or "Idle.")
    end, 1, "throwfood.status")
    extend("farm", page)
    local session = page:section({ title = "Session", icon = "plug" })
    session:toggle({ id = "throwfood.toasts", label = "Say what it caught", desc = "A note for a rare catch or a new animal.", default = true, bindable = false })
  end })
end

local function start(hub)
  Config.define("throwfood.toasts", true)
end

B.game({
  id = "throwfood",
  name = "Throw Food For Animals",
  -- (the sidebar's heading: the whole name does not fit there)
  short = "Throw Food",
  tagline = "Throw far. Catch rare. Again.",
  universes = { TF.UNIVERSE },
  places = { TF.PLACE },
  icon = "target",
  tabs = function(hub)
    start(hub)
    for _, part in ipairs(TF.parts) do
      if part.start then B.try("throwfood." .. part.id, part.start, hub) end
    end
    -- (every part is here now: until this, none of them acts, or the first to start would decide without the rest)
    TF.started = true
    farmPage(hub)
    if has("plot") then
      hub:page({ id = "plot", title = "Animals", icon = "trees", build = function(page) extend("plot", page) end })
    end
    if has("shop") then
      hub:page({ id = "shop", title = "Shop", icon = "shopping-cart", build = function(page) extend("shop", page) end })
    end
    if has("extra") then
      hub:page({ id = "extra", title = "Rewards", icon = "gem", build = function(page) extend("extra", page) end })
    end
  end,
})
end
do -- throwfood_extra.lua
-- ============================================================================
--  Throw Food For Animals   the free things: claims, trails, eggs, and staying in the server
--
--  Read from the game (ExclusiveShopController, OfflineEarnings, IndexRewardsController, Shared.
--  IndexRewards, PlotController, EggController, AFKRejoin), version 1264:
--
--   * Shop_ClaimFree: the free animal of the shop (a Hyena), once (FreeAnimalClaimed).
--   * Offline_Claim: what the plot earned while away (OfflinePending.Base). The doubled one is
--     a Robux product (Shop_Prompt "OfflineDouble"): never asked.
--   * IndexRewards_Claim(key): a finished collection of the index pays a trail. Shared.IndexRewards.
--     Claimable(data) is the game's own list of what may be claimed now. A trail adds a little cash
--     or XP (Config.IndexRewardsConfig.Trails[key].Bonus); IndexRewards_Equip(key) wears one.
--   * Egg_Place(key, position): an egg the player holds (a tool with EggKey) set on their own plot,
--     where it hatches by itself. Eggs come from Robux and gifts only: NOT run live (none owned).
--   * AFKRejoin: 1,080 s with no input and the game sends the player to another server. Its clock is
--     the first upvalue of AFKRejoin.IdleSeconds; set to now it reads 0 (measured: 49 s -> 0.00005 s).
--     The hub's own Anti-AFK (VirtualUser) does not reach it: measured, the clock kept counting.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util
local TF = B.ThrowFood

local extra = { claimed = 0, offline = 0, trails = 0, eggs = 0, kept = 0, wait = {} }
TF.extra = extra

-- the game's idle clock back to now: true when it was there to set
local function stay()
  local afk = TF.controller("AFKRejoin")
  if not (afk and type(afk.IdleSeconds) == "function") then return false end
  if type(debug.getupvalue) ~= "function" or type(debug.setupvalue) ~= "function" then return false end
  local ok, value = pcall(debug.getupvalue, afk.IdleSeconds, 1)
  -- (some executors answer name, value; others the value alone)
  if ok and type(value) ~= "number" then ok, value = pcall(function() local _, v = debug.getupvalue(afk.IdleSeconds, 1) return v end) end
  if not ok or type(value) ~= "number" or value > os.clock() + 1 then return false end
  local set = pcall(debug.setupvalue, afk.IdleSeconds, 1, os.clock())
  if set then extra.kept += 1 end
  return set
end
extra.stay = stay

local function due(key, seconds)
  local now = os.clock()
  if now < (extra.wait[key] or 0) then return false end
  extra.wait[key] = now + seconds
  return true
end

-- the best trail of the kind asked for, of those owned: its key, or nil
local function bestTrail(kind)
  local data = TF.data()
  local config = TF.mod("Config.IndexRewardsConfig")
  local trails = data and type(data.Trails) == "table" and data.Trails
  if not (trails and config and type(config.Trails) == "table") then return nil end
  local owned = type(trails.Owned) == "table" and trails.Owned or {}
  local best, bestValue = nil, -1
  for key, on in pairs(owned) do
    -- (a set of names, { Leaf = true }, or a list of them, { "Leaf" }: either is read)
    local name = type(key) == "number" and on or (on and key)
    local trail = type(name) == "string" and config.Trails[name]
    local bonus = trail and type(trail.Bonus) == "table" and trail.Bonus
    if bonus then
      local value = tonumber(bonus[kind == "xp" and "Xp" or "Cash"]) or 0
      -- (none of the kind asked for: the other kind is still better than none)
      if value <= 0 then value = (tonumber(bonus.Xp) or tonumber(bonus.Cash) or 0) / 1000 end
      if value > bestValue then best, bestValue = name, value end
    end
  end
  return best, trails.Equipped
end
extra.bestTrail = bestTrail

-- where on the plot an egg may go: the plot's own floor, inside its edge
local function plotSpot()
  local index = TF.attr("PlotIndex")
  local plots = workspace:FindFirstChild("Plots")
  local part = plots and index and plots:FindFirstChild(tostring(index))
  if not (part and part:IsA("BasePart")) then return nil end
  local half = part.Size / 2
  local x = (math.random() - 0.5) * math.max(0, half.X - 8)
  local z = (math.random() - 0.5) * math.max(0, half.Z - 8)
  return part.Position + Vector3.new(x, half.Y, z)
end

local function pass(O)
  local data = TF.data()
  if not data then return end
  if O.claimFree and data.FreeAnimalClaimed ~= true and due("free", 60) then
    local answer = TF.call("Shop_ClaimFree", 8)
    if answer.Ok then
      extra.claimed += 1
      TF.note("Claimed the free animal.")
      TF.toast("Free animal", "Claimed from the shop.", "gem", "ok")
    end
  end
  local pending = type(data.OfflinePending) == "table" and tonumber(data.OfflinePending.Base) or 0
  if O.offline and pending > 0 and due("offline", 30) then
    local answer = TF.call("Offline_Claim", 8)
    if answer.Ok then
      extra.offline += 1
      TF.note("Claimed the offline earnings.")
    end
  end
  if O.index and due("index", 10) then
    local rewards = TF.mod("Shared.IndexRewards")
    local keys = rewards and TF.ask(rewards.Claimable, data) or {}
    for _, key in ipairs(type(keys) == "table" and keys or {}) do
      local answer = TF.call("IndexRewards_Claim", 8, key)
      if answer.Ok then
        extra.claimed += 1
        TF.note("Claimed the index reward " .. tostring(key) .. ".")
        TF.toast("Index reward", tostring(key), "trophy", "ok")
      end
      task.wait(0.2)
    end
  end
  if O.trail and due("trail", 10) then
    local best, worn = bestTrail(O.trailKind)
    if best and best ~= worn then
      local answer = TF.call("IndexRewards_Equip", 8, best)
      if answer.Ok then
        extra.trails += 1
        TF.note("Wearing the " .. tostring(best) .. " trail.")
      end
    end
  end
  if O.eggs and due("eggs", 5) and not TF.gameBusy() then
    local holders = { B.LP:FindFirstChildOfClass("Backpack"), B.LP.Character }
    for _, holder in ipairs(holders) do
      for _, tool in ipairs(holder and holder:GetChildren() or {}) do
        local key = tool:IsA("Tool") and tool:GetAttribute("EggKey")
        local spot = key and plotSpot()
        if spot then
          -- (set from the plot, as the game's own hand does it)
          local answer = TF.errand("extra", "plot", function() return TF.call("Egg_Place", 8, key, spot) end) or {}
          if answer.Ok then
            extra.eggs += 1
            TF.note("Set an egg on the plot.")
          end
          return
        end
      end
    end
  end
end

local function start(hub)
  local map = {}
  for id, default in pairs({ claimFree = false, offline = false, index = false, trail = false, trailKind = "cash", eggs = false, stay = false }) do
    Config.define("throwfood." .. id, default)
    map[id] = "throwfood." .. id
  end
  local O = Config.mirror(map)
  extra.options = O
  task.spawn(function()
    while B.alive do
      if TF.started and TF.ready() then B.try("throwfood.extra", pass, O) end
      task.wait(2)
    end
  end)
  -- the game's idle clock, a good while before its 18 minutes
  task.spawn(function()
    while B.alive do
      if O.stay then B.try("throwfood.stay", stay) end
      task.wait(30)
    end
  end)
end

local function extraCards(page)
  local box = page:section({ title = "Free", icon = "gem", desc = "Everything the game gives away." })
  box:toggle({ id = "throwfood.claimFree", label = "Free animal", desc = "The shop's free one, once.", default = false })
  box:toggle({ id = "throwfood.offline", label = "Offline earnings", desc = "Claimed as soon as they show.", default = false })
  box:toggle({ id = "throwfood.index", label = "Index rewards", desc = "Each finished collection's trail.", default = false })
  box:toggle({ id = "throwfood.trail", label = "Wear the best trail", desc = "Of the trails you own.", default = false })
  box:segmented({ id = "throwfood.trailKind", label = "Best for", desc = "Trails add cash or XP.", options = { { "cash", "Cash" }, { "xp", "XP" } }, default = "cash", width = 160 })
  box:toggle({ id = "throwfood.eggs", label = "Hatch your eggs", desc = "Sets eggs you hold on the plot.", default = false })
  local session = page:section({ title = "Stay", icon = "clock" })
  session:toggle({ id = "throwfood.stay", label = "Stay in this server", desc = "The game moves idle players after 18 min.", default = false })
  local line = session:note({ icon = "info", text = "" })
  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    local afk = TF.controller("AFKRejoin")
    local idle = afk and TF.ask(afk.IdleSeconds)
    line.set(string.format("Idle clock %s  ·  claimed %d  ·  eggs %d", idle and string.format("%d s of 1080", math.floor(idle)) or "?", extra.claimed + extra.offline, extra.eggs))
  end, 2, "throwfood.extra.line")
end

TF.parts[#TF.parts + 1] = { id = "extra", start = start, extra = extraCards }
end
do -- throwfood_farm.lua
-- ============================================================================
--  Throw Food For Animals   the throw and the bar: one body, one at a time
--
--  Read from the game (ThrowController, ThrowMeter, Shared.ThrowMeterMath, TrainingController,
--  GameConfig.Throw / .Training, version 1264), and measured on the client 2026-11-15:
--
--   * The line is workspace.StarterArea.CrossLine (Z -40). The game starts its own throw when the
--     body walks past it; the hub stands the body a stud short of it, where the game's own line
--     does nothing, and asks Throw_Start from there. The server wants the body within about 8 studs
--     of the launch point (AreaUtil.GetLaunchPosition, Z -45): measured 2026-11-16, standing 3 studs
--     behind the line (8.5 away) is TooFar every time, 2 behind (7.6) and 1 behind (6.7) are taken.
--   * The meter: Throw_MeterStarted starts the server's clock, Throw_Resolve(1) sent HalfPeriod
--     later (1.086 s: ln(2.6) / (0.55 x 1.6)) is a PERFECT every time (0.9994-0.9996 measured).
--   * Throw_Complete is answered when the server has waited out the flight and the reveal: 3.8 to
--     4.3 s, longer the farther it flew. A whole throw is about 5.5 s; the server's own Cooldown
--     between two is 1.5 s and is inside that already.
--   * Training_Start wants the body near the plot's training spot (plot + GameConfig.Plot.
--     TrainingSpotOffset): measured 2026-11-16, 0, 6 and 10 studs from it are taken, 14 and 20 are
--     TooFar. (A first test that seemed to train from the line was the server still seeing the body
--     where it had stood a moment before.) The game draws its own circle on that spot and starts its
--     own training sequence when the body stands in it: the hub stands seven studs to the side.
--     Training_Stop, then a throw, then Training_Start again: a short Cooldown between a stop and a
--     start ("Cooldown" is answered, and it is asked again).
--   * After Throw_Complete the server itself puts the body at the plot's entrance (measured): the
--     next throw stands it at the line again, the next training by the bar.
--   * A throw gives no XP and training brings no animal: when to throw is the farm's real
--     question. "Smart" asks the game's own roll how likely the next throw beats the weakest animal
--     on the plot (TF.odds), and throws when that is worth it, when a slot is free, or when it has
--     not thrown for a while (mutations come from any throw).
--   * During the game's Ring Rush event a throw may be offered as a ring flight (RingRush = true):
--     the game's client only flies it if it asks RingRush_Begin. The hub never does, and the throw
--     resolves the ordinary way, as the game's own client does when that call fails.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util
local TF = B.ThrowFood

local farm = { state = "off", throws = 0, perfect = 0, accuracy = 0, caught = {}, rarities = {}, newOnes = 0, best = nil,
  lastThrow = -math.huge, trainRetry = 0, trained = false, levels = 0, startLevel = nil, bonuses = 0, supers = 0, since = nil }
TF.farm = farm
farm.LINE_GAP, farm.REACH = 1, 7
-- how far "Smart" looks ahead: the throw now against the same throw after this many seconds on the bar
farm.LOOK = 30

-- ---------------------------------------------------------------- the line
local function line()
  local area = workspace:FindFirstChild("StarterArea")
  if not (area and area:IsA("BasePart")) then return nil end
  local cross = area:FindFirstChild("CrossLine")
  local z = cross and cross:IsA("BasePart") and cross.Position.Z or (area.Position.Z + area.Size.Z / 2)
  return area, z
end
-- standing short of the line (not past it: the game's own throw would start) and near enough the launch point
local function atLine()
  local root = B.root()
  local area, z = line()
  if not (root and area) then return false end
  local areas = TF.mod("Shared.AreaUtil")
  local launch = areas and TF.ask(areas.GetLaunchPosition) or Vector3.new(area.Position.X, area.Position.Y + area.Size.Y / 2, area.Position.Z)
  local position = root.Position
  return position.Z >= z and (position - launch).Magnitude <= farm.REACH
end
farm.atLine = atLine
local function toLine(force)
  if not force and atLine() then return true end
  local root, humanoid = B.root(), B.humanoid()
  local area, z = line()
  if not (root and humanoid and area) then return false end
  local top = area.Position.Y + area.Size.Y / 2
  local y = top + humanoid.HipHeight + root.Size.Y / 2 + 0.1
  local at = Vector3.new(area.Position.X, y, z + farm.LINE_GAP)
  root.AssemblyLinearVelocity = Vector3.zero
  root.CFrame = CFrame.lookAt(at, at - Vector3.new(0, 0, 1))
  -- (the server reads where the body is from what reached it: a moment for the move to get there)
  task.wait(0.2)
  return true
end
farm.toLine = toLine

-- ---------------------------------------------------------------- the bar
local function training() return TF.attr("Training") == true end
farm.training = training
farm.BAR_SIDE, farm.BAR_REACH = 7, 9
-- the plot's training spot (the middle of the game's own circle), and a place to stand beside it
local function barSpot()
  local plots = workspace:FindFirstChild("Plots")
  local index = TF.attr("PlotIndex")
  local part = plots and index and plots:FindFirstChild(tostring(index))
  local config = TF.mod("Config.GameConfig")
  if not (part and part:IsA("BasePart") and config and config.Plot) then return nil end
  return part.Position + (config.Plot.TrainingSpotOffset or Vector3.new(-16, 0.5, -30.5))
end
farm.barSpot = barSpot
local function atBar()
  local root, spot = B.root(), barSpot()
  if not (root and spot) then return false end
  local flat = Vector3.new(root.Position.X - spot.X, 0, root.Position.Z - spot.Z).Magnitude
  -- (near enough for the server, and out of the game's own circle, a few studs across)
  return flat <= farm.BAR_REACH and flat >= 4 and math.abs(root.Position.Y - spot.Y) < 8
end
farm.atBar = atBar
local function toBar()
  if atBar() then return true end
  local root, humanoid, spot = B.root(), B.humanoid(), barSpot()
  if not (root and humanoid and spot) then return false end
  local x, z = spot.X + farm.BAR_SIDE, spot.Z
  -- (the ground there, found from above: the lobby is not one flat part)
  local params = RaycastParams.new()
  params.FilterType = Enum.RaycastFilterType.Exclude
  params.FilterDescendantsInstances = { B.LP.Character }
  local hit = workspace:Raycast(Vector3.new(x, spot.Y + 30, z), Vector3.new(0, -60, 0), params)
  local floor = hit and hit.Position.Y or spot.Y
  local at = Vector3.new(x, floor + humanoid.HipHeight + root.Size.Y / 2 + 0.1, z)
  root.AssemblyLinearVelocity = Vector3.zero
  root.CFrame = CFrame.lookAt(at, Vector3.new(spot.X, at.Y, spot.Z))
  task.wait(0.25)
  return true
end
farm.toBar = toBar
local function stopTraining()
  if not training() then return true end
  TF.call("Training_Stop", 6)
  local asked = os.clock()
  while B.alive and training() and os.clock() - asked < 2 do task.wait(0.05) end
  return not training()
end
farm.stopTraining = stopTraining
local startOnce
local function startTraining()
  if training() then return true end
  if os.clock() < farm.trainRetry then return false end
  if not TF.take("farm") then return false, "body" end
  local ok, on, why = pcall(startOnce)
  TF.release("farm")
  B.identity()
  if not ok then return false, tostring(on) end
  return on, why
end
function startOnce()
  -- (no bar bought yet: the game itself sends the player to the button first)
  if TF.num("Stand", 0) < 1 then
    farm.trainRetry = os.clock() + 5
    return false, "NoBar"
  end
  -- (just after a throw the server puts the body at the plot's entrance itself, and that move can land after
  -- ours: the body is put by the bar, and asked about only once it has stayed there a moment)
  for _ = 1, 3 do
    toBar()
    task.wait(0.15)
    if atBar() then break end
  end
  local answer = TF.call("Training_Start", 6)
  if not answer.Ok and answer.Reason == "TooFar" then
    task.wait(0.4)
    toBar()
    task.wait(0.3)
    answer = TF.call("Training_Start", 6)
  end
  farm.why = answer.Reason
  if answer.Ok then
    farm.trained = true
    farm.trainRetry = 0
    return true
  end
  -- (Cooldown: a moment after a stop. Throwing: our own throw still landing. Anything else: soon again.)
  farm.trainRetry = os.clock() + ((answer.Reason == "Cooldown" or answer.Reason == "Throwing" or answer.Reason == "TooFar") and 0.35 or 1.5)
  return false, answer.Reason
end
farm.startTraining = startTraining

-- ---------------------------------------------------------------- aiming
-- "Missing animals": the game's own slider (Player_SetThrowPower, 0 = full power, any power from
-- LevelConfig.MinThrowPower up to the level's) lands a throw at a chosen depth of a chosen area, and
-- the food in hand picks what lives there (AnimalRoll.Weights). The plan is the one place, food and
-- power with the best chance at an animal the index does not have yet; the index keeps an animal once
-- caught, sold or not (measured: Frog stayed in it after every Frog was sold).
local function plan(floorChance)
  local data = TF.data()
  local areas, config, roll = TF.mod("Shared.AreaUtil"), TF.mod("Config.AreasConfig"), TF.mod("Shared.AnimalRoll")
  local animalsData, foods, levels = TF.mod("AnimalsData"), TF.mod("Config.FoodsConfig"), TF.mod("Config.LevelConfig")
  if not (data and areas and config and roll and animalsData and foods and levels) then return nil end
  local index = type(data.Index) == "table" and data.Index or {}
  local owned = type(data.OwnedFoods) == "table" and data.OwnedFoods or {}
  local top = TF.ask(levels.ThrowPowerForLevel, TF.level()) or 0
  local low = math.min(tonumber(levels.MinThrowPower) or 0, top)
  local bonus = TF.bonusStuds()
  local launch = TF.ask(areas.GetLaunchPosition)
  if not launch then return nil end
  local best = nil
  for areaIndex = 1, TF.ask(areas.Count) or 0 do
    local reach = TF.ask(areas.DistanceToAreaStart, areaIndex)
    local area, geo = TF.ask(config.Get, areaIndex), TF.ask(areas.Get, areaIndex)
    local list = area and animalsData[area.Key]
    if reach and reach <= top + bonus + 1 and geo and type(list) == "table" then
      local missing = {}
      for rank, animal in ipairs(list) do
        if type(animal) == "table" and animal.ModelName and not index[animal.ModelName] then missing[rank] = animal end
      end
      if next(missing) then
        -- (foods past three baits over the area's own read the same there: one of each centre is enough)
        local menu, centres = {}, {}
        for foodIndex = 1, TF.ask(foods.Count) or 0 do
          local food = (owned[foodIndex] or owned[tostring(foodIndex)]) and TF.ask(foods.Get, foodIndex)
          local centre = food and TF.ask(roll.FoodCenter, food.Bait, areaIndex)
          if centre then
            local key = string.format("%.3f", centre)
            if not centres[key] then centres[key] = true; menu[#menu + 1] = { index = foodIndex, food = food } end
          end
        end
        for step = 1, 19 do
          local depth = step / 20
          local z = geo.ZStart - depth * (geo.ZStart - geo.ZEnd)
          local power = (launch.Z - z) - bonus * 0.998
          if power >= low and power <= top then
            for _, item in ipairs(menu) do
              local weights = TF.ask(roll.Weights, item.food.Bait, areaIndex, depth)
              for rank, animal in pairs(missing) do
                local chance = weights and weights[rank] or 0
                if chance >= (floorChance or 0) and chance > (best and best.chance or 0) then
                  best = { area = areaIndex, areaName = area.Name, depth = depth, power = math.floor(power), food = item.index,
                    foodName = item.food.Name, model = animal.ModelName, name = animal.Name or animal.ModelName, chance = chance }
                end
              end
            end
          end
        end
      end
    end
  end
  return best
end
farm.plan = plan

-- Power and food set for the throw about to be made: the plan's when hunting, full power otherwise.
local function aim()
  local O = farm.options
  local data = TF.data()
  if not data then return nil end
  local target = nil
  if O.aim == "index" then
    local now = os.clock()
    -- (worked out again after a catch or a level, and at most every few seconds)
    if not farm.target or farm.targetLevel ~= TF.level() or now - (farm.targetAt or 0) > 15 or farm.targetStale then
      farm.target = plan((O.huntChance or 5) / 100)
      farm.targetLevel, farm.targetAt, farm.targetStale = TF.level(), now, false
    end
    target = farm.target
  end
  farm.hunting = target ~= nil
  local want = target and target.power or 0
  local have = tonumber(data.ThrowPower) or 0
  -- (full power is 0 to the game; a power at or over the level's is full as well)
  if math.abs(have - want) >= 1 and not (want == 0 and have >= TF.fullPower()) then
    local answer = TF.call("Player_SetThrowPower", 6, want)
    if answer.Ok then farm.aimed = want ~= 0
    elseif target then farm.hunting, target = false, nil end
  end
  if target and (tonumber(data.EquippedFood) or 1) ~= target.food then
    -- (food is changed at the shop's circle: from anywhere else the answer is TooFar)
    TF.errand("farm", "shop", function() return TF.call("Shop_Equip", 6, target.food) end)
  end
  return target
end
farm.aim = aim

-- ---------------------------------------------------------------- the throw
local function peak()
  local math_ = TF.mod("Shared.ThrowMeterMath")
  return math_ and TF.ask(math_.HalfPeriod) or 1.0858
end
local function remember(result, answer)
  farm.throws += 1
  farm.lastThrow = os.clock()
  local accuracy = tonumber(result.Accuracy) or 0
  farm.accuracy = farm.accuracy + (accuracy - farm.accuracy) / farm.throws
  if accuracy >= 0.92 then farm.perfect += 1 end
  local rarity = tostring(result.Rarity or "?")
  farm.rarities[rarity] = (farm.rarities[rarity] or 0) + 1
  if result.IsNew then farm.newOnes += 1 end
  local income = tonumber(result.Income) or 0
  local catch = { name = result.DisplayName or result.ModelName, model = result.ModelName, rarity = rarity, mutation = result.Mutation,
    income = income, area = result.AreaName, depth = result.Depth, new = result.IsNew == true, id = answer and answer.AnimalId, at = os.clock() }
  table.insert(farm.caught, 1, catch)
  if #farm.caught > 8 then table.remove(farm.caught) end
  local record = not farm.best or income > farm.best.income
  if record then farm.best = catch end
  -- (a new animal, or the one hunted: the plan is worked out again before the next throw)
  if catch.new or (farm.target and farm.target.model == catch.model) then farm.targetStale = true end
  local label = (catch.mutation and (catch.mutation .. " ") or "") .. tostring(catch.name)
  TF.note(string.format("Caught %s (%s, %s/s) in %s.", label, rarity, TF.short(income), tostring(result.AreaName or "?")))
  -- a note on screen for what is worth one: a new animal, a mutation of Diamond or better (Gold comes one throw in
  -- eight: it would be a note every minute), or the best catch of the session
  local mutations = TF.mod("Config.MutationsConfig")
  local tier = 1
  for _, mutation in ipairs(mutations and mutations.List or {}) do
    if type(mutation) == "table" and mutation.Name == catch.mutation then tier = tonumber(mutation.Multiplier) or 1 end
  end
  if catch.new or tier >= 3 or (record and farm.throws > 1) then
    TF.toast(catch.new and "New animal!" or (record and "Best catch yet!" or "Caught!"), string.format("%s · %s · %s/s", label, rarity, TF.short(income)), "sparkles", "ok")
  end
  TF.onCatch:fire(catch, result)
end

-- One throw, start to finish: true when an animal came of it. (false, why) when it did not.
local function throwOnce()
  if TF.gameBusy() then return false, "game" end
  local clock = { at = os.clock() }
  farm.clock = clock
  if not stopTraining() then return false, "training" end
  clock.stopped = os.clock()
  local target = aim()
  clock.aimed = os.clock()
  if not toLine() then return false, "line" end
  clock.lined = os.clock()
  TF.hold(true)
  local start = TF.call("Throw_Start", 10)
  local tries = 0
  while not start.Ok and B.alive and tries < 6 do
    tries += 1
    local why = start.Reason
    if why == "Cooldown" then task.wait(0.4)
    elseif why == "Training" then stopTraining()
    elseif why == "TooFar" then
      -- (the body did not stay where it was put, or the server has not seen it there yet: put again)
      toLine(true)
      task.wait(0.2)
    elseif why == "Busy" then
      -- (the server still holds a throw of ours that never finished: let it go)
      TF.call("Throw_Cancel", 6)
      task.wait(0.4)
    else
      break
    end
    start = TF.call("Throw_Start", 10)
  end
  if not start.Ok then
    TF.hold(false)
    farm.failed = (farm.failed or 0) + 1
    return false, tostring(start.Reason)
  end
  -- a lucky throw the player has saved, used when they said to (the game's own button does the same)
  local options = farm.options
  -- (never on a throw aimed short at a missing animal: a lucky throw is worth most at full power)
  if options and options.useSaved and not target and (tonumber(start.Saved) or 0) > 0 then
    local super = TF.call("Throw_UseSuper", 8)
    if super.Ok then farm.supers += 1 end
  end
  clock.started = os.clock()
  TF.fire("Throw_MeterStarted")
  local began, top = os.clock(), peak()
  while B.alive and os.clock() - began < top - 0.008 do S.RunService.Heartbeat:Wait() end
  local result = TF.call("Throw_Resolve", 10, 1)
  clock.resolved = os.clock()
  if not result.Ok then
    TF.call("Throw_Cancel", 6)
    TF.hold(false)
    return false, tostring(result.Reason)
  end
  -- (the game's own client tells the server here that the reveal was seen; the server waits it out regardless)
  TF.fire("Throw_Revealed")
  local answer = TF.call("Throw_Complete", 20)
  clock.completed = os.clock()
  TF.hold(false)
  if not answer.Ok then return false, tostring(answer.Reason) end
  remember(result, answer)
  -- (how long each part took, the last throw: for the page)
  farm.took = string.format("stop %.1f, aim %.1f, line %.1f, start %.1f, meter %.1f, landing %.1f", clock.stopped - clock.at,
    clock.aimed - clock.stopped, clock.lined - clock.aimed, clock.started - clock.lined, clock.resolved - clock.started, clock.completed - clock.resolved)
  return true
end
-- (the body is the throw's from the bar to the catch: the shop's trips wait for it)
local function throw()
  if not TF.take("farm") then return false, "body" end
  local ok, done, why = pcall(throwOnce)
  TF.release("farm")
  TF.hold(false)
  B.identity()
  if not ok then return false, tostring(done) end
  return done, why
end
farm.throw = throw

-- ---------------------------------------------------------------- when to throw
local smart
local function wanted()
  local O = farm.options
  if not O.throw then return false, "off" end
  local now = os.clock()
  -- (nothing else for the body to do: throw on)
  if not O.train or TF.num("Stand", 0) < 1 then return true, "only" end
  -- (hunting the index: throws while a missing animal is in reach at the chance asked for)
  if O.aim == "index" then
    if not farm.target or farm.targetStale or now - (farm.targetAt or 0) > 15 or farm.targetLevel ~= TF.level() then
      farm.target = plan((O.huntChance or 5) / 100)
      farm.targetLevel, farm.targetAt, farm.targetStale = TF.level(), now, false
    end
    if farm.target then return true, "hunt" end
  end
  if O.throwMode == "always" then return true, "always" end
  if O.throwMode == "every" then return now - farm.lastThrow >= O.throwEvery, "every" end
  -- (worked out once a second at most: it reads the whole plot and the level curve; a catch or a level asks again)
  local level = TF.level()
  if farm.decided and now - farm.decided.at < 1 and farm.decided.level == level and farm.decided.throws == farm.throws then
    return farm.decided.want, farm.decided.why
  end
  local want, why = smart(O, now)
  farm.decided = { at = now, level = level, throws = farm.throws, want = want, why = why }
  return want, why
end
-- (the Smart rule itself: see wanted)
function smart(O, now)
  -- (read at full power: the slider may still be where a hunt left it, and the next throw puts it back)
  local full = TF.fullPower()
  local odds = TF.odds(full)
  farm.odds = odds
  if not odds then return now - farm.lastThrow >= O.throwWait, "wait" end
  if odds.free > 0 then return true, "free" end
  -- A look ahead: the same throw after LOOK seconds more on the bar. When that one is worth more than twice this one (the
  -- next third, the next area: Jungle animals earn forty times Desert's), the bar comes first. Without it the farm threw
  -- for ten minutes at the far end of Desert, two levels short of Jungle (measured 2026-11-16).
  local levels = TF.levelsIn(farm.LOOK)
  local soon = levels > 0 and TF.odds(full + 5 * levels) or nil
  farm.soon, farm.soonLevels = soon, levels
  local later = soon and soon.share or 0
  -- (worth a throw: the plot is expected to earn at least this much more for it, and waiting would not double it)
  if odds.share * 100 >= O.throwGain and odds.share >= later * 0.5 then return true, "gain" end
  return now - farm.lastThrow >= O.throwWait, "wait"
end
farm.wanted = wanted

local function start(hub)
  local map = {}
  for id, default in pairs({ throw = false, throwMode = "smart", throwGain = 3, throwWait = 120, throwEvery = 20, train = false,
    tapBonus = false, useSaved = false, aim = "far", huntChance = 5, yield = false, yieldFor = 8 }) do
    Config.define("throwfood." .. id, default)
    map[id] = "throwfood." .. id
  end
  local O = Config.mirror(map)
  farm.options = O
  -- Hunting stopped, or throwing: the slider goes back to full power, so the player's own throw is a whole one.
  local function fullAgain()
    farm.target, farm.hunting = nil, false
    task.spawn(function()
      local data = TF.data()
      if data and (tonumber(data.ThrowPower) or 0) ~= 0 and farm.aimed then
        local answer = TF.call("Player_SetThrowPower", 6, 0)
        if answer.Ok then farm.aimed = false end
      end
    end)
  end
  Config.on("throwfood.aim", function(value) if value ~= "index" then fullAgain() end end)
  Config.on("throwfood.throw", function(value) if not value then fullAgain() end end)

  -- The player's own hand: a key that moves or jumps, or a click in the world (not on a menu, not typing). The farm
  -- steps aside for a few seconds after the last one, so a player who plays is not pulled back to the line.
  local MOVES = { [Enum.KeyCode.W] = true, [Enum.KeyCode.A] = true, [Enum.KeyCode.S] = true, [Enum.KeyCode.D] = true,
    [Enum.KeyCode.Up] = true, [Enum.KeyCode.Down] = true, [Enum.KeyCode.Left] = true, [Enum.KeyCode.Right] = true, [Enum.KeyCode.Space] = true }
  farm.played = -math.huge
  B.connect(S.UserInputService.InputBegan, function(input, processed)
    if processed or not O.yield then return end
    local kind = input.UserInputType
    if (kind == Enum.UserInputType.Keyboard and MOVES[input.KeyCode]) or kind == Enum.UserInputType.MouseButton1 or kind == Enum.UserInputType.Touch
      or kind == Enum.UserInputType.Gamepad1 then
      farm.played = os.clock()
    end
  end, "throwfood.yield")
  function farm.paused()
    return O.yield and os.clock() - farm.played < (O.yieldFor or 8)
  end

  -- the tap bonus: offered as an event while training, taken at once
  TF.on("Training_Bonus", function(id, ends)
    if not (O.tapBonus and training()) or id == nil then return end
    task.spawn(function()
      local answer = TF.call("Training_TapBonus", 5, id)
      if answer.Ok then farm.bonuses += 1 end
    end)
  end)

  task.spawn(function()
    while B.alive do
      local ok = TF.started and TF.ready()
      if not ok then
        farm.state = "waiting"
        task.wait(0.5)
      elseif TF.gameBusy() then
        -- (the player is in the middle of something of the game's own: a throw by hand, an egg, the offline screen)
        farm.state = "game"
        task.wait(0.5)
      elseif farm.paused() then
        -- (the player is playing: nothing moves the body; a training already going goes on by itself)
        if farm.state ~= "paused" then TF.note("Paused: you are playing.") end
        farm.state = "paused"
        task.wait(0.25)
      else
        if not farm.startLevel then
          farm.startLevel, farm.since = TF.level(), os.clock()
          farm.startIncome = TF.animals().income
        end
        local want, why = wanted()
        if want then
          farm.state = "throwing"
          -- (the server's own 1.5 s between two throws is waited out here, with the body free: a trip to the shop fits in it)
          local since = os.clock() - farm.lastThrow
          if since < 1.45 then task.wait(1.45 - since) end
          local done, reason = throw()
          if not done then
            if reason ~= "body" then TF.note("No throw: " .. tostring(reason) .. ".") end
            task.wait((reason == "game" or reason == "body") and 0.25 or 1.5)
          end
        elseif O.train then
          local was = farm.state
          local on, reason = startTraining()
          farm.state = on and "training" or (reason == "NoBar" and "nobar" or "starting")
          if farm.state ~= was then
            if farm.state == "nobar" then TF.note("No pull-up bar yet: Shop > Auto buy bars gets one.")
            elseif farm.state == "training" then
              local odds, soon = farm.odds, farm.soon
              if odds and soon and soon.spot and soon.spot.area ~= odds.spot.area then
                TF.note(string.format("Training: %d levels to %s, where a throw is worth far more.", farm.soonLevels or 0, tostring(soon.spot.areaName)))
              else
                TF.note(odds and string.format("Training. A throw now would add about %.1f%% income.", odds.share * 100) or "Training.")
              end
            end
          end
          local _ = why
          task.wait(0.25)
        else
          -- (switched off: training the hub started is stopped, so the player's own throw is not refused)
          if farm.trained and training() then stopTraining() end
          farm.trained = false
          farm.state = "off"
          task.wait(0.5)
        end
      end
    end
  end)
  B.own(function()
    -- (unloaded: the bar the hub put the body on is left, so the game does not refuse the player's next throw)
    if farm.trained and training() then pcall(function() TF.remote("Training_Stop"):InvokeServer() end) end
  end)
end

local function percent(n) return string.format("%d%%", math.floor((n or 0) * 100 + 0.5)) end
local function farmCards(page)
  local box = page:section({ title = "Throw", icon = "target", desc = "Perfect every time, no cinematic." })
  box:toggle({ id = "throwfood.throw", label = "Auto throw", desc = "Stands at the line and throws.", default = false })
  box:segmented({ id = "throwfood.throwMode", label = "When", desc = "Smart: when a throw beats training.",
    options = { { "smart", "Smart" }, { "always", "Non-stop" }, { "every", "Timer" } }, default = "smart", width = 220 })
  box:slider({ id = "throwfood.throwGain", label = "Smart: worth at least", desc = "Expected extra income from one throw.", min = 1, max = 25, step = 1, default = 3, suffix = "%" })
  box:slider({ id = "throwfood.throwWait", label = "Smart: at least every", desc = "For a shot at mutations.", min = 15, max = 600, step = 15, default = 120, suffix = " s" })
  box:slider({ id = "throwfood.throwEvery", label = "Timer: every", desc = "Seconds of training between throws.", min = 5, max = 300, step = 5, default = 20, suffix = " s" })
  box:segmented({ id = "throwfood.aim", label = "Aim", desc = "Missing: hunts animals your index lacks.",
    options = { { "far", "Farthest" }, { "index", "Missing" } }, default = "far", width = 200 })
  box:slider({ id = "throwfood.huntChance", label = "Missing: chance at least", desc = "Skips animals rarer than this.", min = 1, max = 50, step = 1, default = 5, suffix = "%" })
  box:toggle({ id = "throwfood.useSaved", label = "Use saved lucky throws", desc = "Spends your saved super throws.", default = false })
  local line = box:note({ icon = "info", text = "" })
  local hunt = box:note({ icon = "search", text = "" })

  local bar = page:section({ title = "Train", icon = "activity", desc = "XP for levels: 5 power a level." })
  bar:toggle({ id = "throwfood.train", label = "Auto train", desc = "Trains at your bar between throws.", default = false })
  bar:toggle({ id = "throwfood.tapBonus", label = "Take tap bonuses", desc = "Every bonus, at once.", default = false })
  bar:toggle({ id = "throwfood.yield", label = "Pause while you play", desc = "Steps aside while you move or click.", default = false })
  bar:slider({ id = "throwfood.yieldFor", label = "Pause for", desc = "After your last key or click.", min = 3, max = 60, step = 1, default = 8, suffix = " s" })
  local barLine = bar:note({ icon = "info", text = "" })

  local lastBox = page:section({ title = "This session", icon = "sparkles" })
  local session = lastBox:note({ icon = "activity", text = "" })
  local catches = lastBox:note({ icon = "list", text = "Nothing yet." })

  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    local odds = farm.odds or TF.odds()
    local text = string.format("%d throws  ·  %s perfect", farm.throws, farm.throws > 0 and percent(farm.perfect / farm.throws) or "-")
    if odds then
      text = text .. string.format("  ·  next: %s %s, %s", odds.spot.areaName, percent(odds.spot.depth),
        odds.free > 0 and "a free slot" or string.format("+%.1f%% income expected", odds.share * 100))
    end
    line.set(text)
    local target = farm.target
    if farm.options.aim == "index" then
      hunt.set(target and string.format("Hunting %s in %s at %s with %s: %s a throw", tostring(target.name), tostring(target.areaName), percent(target.depth),
        tostring(target.foodName), percent(target.chance)) or "No missing animal in reach at that chance: throwing for income.")
    else
      hunt.set("Aiming as far as you can throw.")
    end
    local since = farm.since and math.max((os.clock() - farm.since) / 3600, 1 / 3600)
    local gained = farm.startLevel and (TF.level() - farm.startLevel) or 0
    local state = training() and "on the bar" or (farm.state == "nobar" and "no bar yet" or "off the bar")
    barLine.set(string.format("%s  ·  +%s levels (%s an hour)  ·  %d bonuses", state, util.comma(gained), since and util.comma(math.floor(gained / since)) or "0", farm.bonuses))
    if farm.since then
      local minutes = math.floor((os.clock() - farm.since) / 60)
      local income = TF.animals().income
      session.set(string.format("%d min  ·  +%s levels  ·  %s/s -> %s/s  ·  %d throws  ·  %d new animals%s", minutes, util.comma(gained),
        TF.short(farm.startIncome or 0), TF.short(income), farm.throws, farm.newOnes,
        farm.best and string.format("  ·  best %s%s (%s/s)", farm.best.mutation and (farm.best.mutation .. " ") or "", tostring(farm.best.name), TF.short(farm.best.income)) or ""))
    end
    if #farm.caught > 0 then
      local rows = {}
      for i = 1, math.min(5, #farm.caught) do
        local c = farm.caught[i]
        rows[#rows + 1] = string.format("%s%s%s · %s · %s/s", c.new and "NEW " or "", c.mutation and (c.mutation .. " ") or "", tostring(c.name), c.rarity, TF.short(c.income))
      end
      catches.set(table.concat(rows, "\n"))
    end
  end, 1, "throwfood.farm.line")
end

TF.parts[#TF.parts + 1] = { id = "farm", start = start, farm = farmCards }
end
do -- throwfood_plot.lua
-- ============================================================================
--  Throw Food For Animals   the plot and the shop: the best out, the rest sold, the next thing bought
--
--  Read from the game (AnimalsPanel, SellShop, ShopController, PlotController; Config.FoodsConfig,
--  StandsConfig, FenceConfig, MutationsConfig; Shared.AnimalRoll, Shared.Mutations), version 1264:
--
--   * Plot_EquipBest puts the best animals out and takes weaker ones in (answers Placed, Removed,
--     Count): the game's own "Equip best" button. A caught animal waits in the backpack until then.
--     What an animal earns is base x mutation x size^1.8 (Mutations.IncomeOf): that is what "best" is.
--   * Plot_SellAll sells every animal in the backpack that was not bought with Robux (answers Count,
--     Money); Plot_SellAnimal(id) sells one. An animal sells for 20 times what it earns a second.
--   * Food: Shop_Buy(index), Shop_Equip(index) (FoodsConfig.List). A food's Bait against the area
--     where the throw lands is what the roll reads (AnimalRoll.FoodCenter): past three baits over the
--     area's own it adds nothing there. "Smart" buys a food when it moves that centre.
--   * The pull-up bar: Stand_Upgrade buys the next one (each doubles the XP of a rep).
--     The fence: Plot_UpgradeFence (more slots: 10 -> 12 -> 14 ...).
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion, util = B.S, B.Config, B.Window, B.Motion, B.util
local TF = B.ThrowFood

local plot = { placed = 0, swapped = 0, sold = 0, soldFor = 0, bought = {}, spent = 0, wait = {} }
TF.plot = plot

-- the game's mutations by what they multiply: { name = multiplier }
local function multipliers()
  local config = TF.mod("Config.MutationsConfig")
  local out = {}
  for _, mutation in ipairs(config and config.List or {}) do
    if type(mutation) == "table" and mutation.Name then out[mutation.Name] = tonumber(mutation.Multiplier) or 1 end
  end
  return out
end

-- ---------------------------------------------------------------- the animals
-- Never sold: bought ones, and what the player said to keep (a mutation from a tier up, a rarity and up).
local function keep(item, O)
  if item.bought then return true end
  if O.keepMutation ~= "off" and item.mutation then
    local table_ = multipliers()
    local need, have = table_[O.keepMutation], table_[item.mutation]
    if need and have and have >= need then return true end
  end
  local from = TF.rarityRank[O.keepRarity]
  if from then
    local rank = TF.rarityRank[TF.species(item.name).rarity] or 0
    if rank >= from then return true end
  end
  return false
end
plot.keep = keep

-- Is there anything for Equip best to do: an animal waiting that earns more than the weakest out, or a free slot it can fill?
local function better(animals)
  animals = animals or TF.animals()
  if #animals.backpack == 0 then return false end
  if #animals.placed < (animals.slots or 10) then return true end
  local weakest = animals.worst and animals.worst.income or 0
  for _, item in ipairs(animals.backpack) do
    if item.income > weakest then return true end
  end
  return false
end
plot.better = better

-- Puts the best out, the weaker ones in. true when it was asked and answered.
local function equipBest()
  local answer = TF.call("Plot_EquipBest", 8)
  if answer.Ok then
    local placed, removed = tonumber(answer.Placed) or 0, tonumber(answer.Removed) or 0
    plot.placed += placed
    plot.swapped += removed
    if placed > 0 or removed > 0 then
      TF.note(removed > 0 and string.format("Swapped %d weaker animal%s for better ones.", removed, removed == 1 and "" or "s")
        or string.format("Put %d more on the plot.", placed))
    end
  end
  return answer.Ok == true
end
plot.equipBest = equipBest

-- Sells what is in the backpack, is not kept, and earns no more than the weakest on the plot (so nothing that
-- belongs out there goes). Puts the best out first when the player said to.
local function sellRest(O)
  if O.equip and better() then equipBest() end
  local animals = TF.animals()
  -- (nothing out yet: nothing is weaker than the plot, so nothing goes)
  local weakest = animals.worst and animals.worst.income or 0
  -- (a plot that is not full: nothing in the backpack is "worse than the plot", unless placing is off by choice)
  if #animals.placed < (animals.slots or 10) and O.equip then return 0 end
  local sell, held = {}, 0
  for _, item in ipairs(animals.backpack) do
    if keep(item, O) or item.income > weakest then held += 1 else sell[#sell + 1] = item end
  end
  if #sell == 0 then return 0 end
  local count, money = 0, 0
  if held == 0 then
    -- (every one of them goes: the game's own Sell all, one call. It never sells a bought one either.)
    local answer = TF.call("Plot_SellAll", 8)
    if answer.Ok then count, money = tonumber(answer.Count) or #sell, tonumber(answer.Money) or 0 end
  else
    for _, item in ipairs(sell) do
      local answer = TF.call("Plot_SellAnimal", 8, item.id)
      if answer.Ok then
        count += 1
        money += tonumber(answer.Money) or 0
      end
      task.wait(0.15)
    end
  end
  if count > 0 then
    plot.sold += count
    plot.soldFor += money
    TF.note(string.format("Sold %d for %s.", count, TF.cash(money)))
  end
  return count
end
plot.sellRest = sellRest

-- ---------------------------------------------------------------- the shop
-- the food in hand and the best one owned (FoodsConfig.List order: the bait goes up with it)
local function foods()
  local config = TF.mod("Config.FoodsConfig")
  local data = TF.data()
  if not (config and data) then return nil end
  local owned = type(data.OwnedFoods) == "table" and data.OwnedFoods or {}
  local best = 1
  local count = TF.ask(config.Count) or 0
  for index = 1, count do
    if owned[index] == true or owned[tostring(index)] == true then best = index end
  end
  return { config = config, best = best, held = tonumber(data.EquippedFood) or 1, count = count, owned = owned }
end
plot.foods = foods
-- Does food `next` bring better animals where the throw lands than food `have` does?
local function moves(next, have)
  local roll = TF.mod("Shared.AnimalRoll")
  local spot = TF.landing(TF.fullPower())
  if not (roll and spot and next and have) then return false end
  local a = TF.ask(roll.FoodCenter, next.Bait, spot.area)
  local b = TF.ask(roll.FoodCenter, have.Bait, spot.area)
  return a ~= nil and b ~= nil and a > b + 1e-6
end
plot.moves = moves

-- What there is to buy now, cheapest first: { kind, price, name, run, can }.
local function wishes(O)
  local out = {}
  local data = TF.data()
  if not data then return out end
  -- (what may be spent: all of it, or what is over the reserve asked for)
  local money = TF.money()
  local spendable = money * (1 - math.clamp((O.reserve or 0) / 100, 0, 0.95))
  local shelf = foods()
  if O.buyFood and shelf and shelf.best < shelf.count then
    local index = shelf.best + 1
    local next, have = TF.ask(shelf.config.Get, index), TF.ask(shelf.config.Get, shelf.best)
    local locked = shelf.config.IsLocked and TF.ask(shelf.config.IsLocked, index)
    if next and tonumber(next.Price) and not locked and (O.foodMode == "next" or moves(next, have)) then
      out[#out + 1] = { kind = "food", key = "food" .. index, index = index, price = next.Price, name = next.Name or ("food " .. index),
        run = function() return TF.errand("shop", "shop", function() return TF.call("Shop_Buy", 8, index) end) end }
    end
  end
  local stands = TF.mod("Config.StandsConfig")
  local stand = tonumber(data.Stand) or 0
  local bar = O.buyBars and stands and TF.ask(stands.Get, stand + 1)
  if bar and tonumber(bar.Price) then
    out[#out + 1] = { kind = "bar", key = "bar" .. (stand + 1), price = bar.Price, name = bar.Name or ("bar " .. (stand + 1)),
      run = function() return TF.errand("shop", "stand", function() return TF.call("Stand_Upgrade", 8) end) end }
  end
  local fence = TF.mod("Config.FenceConfig")
  local level = tonumber(data.FenceLevel) or 0
  local upgrade = O.buyFence and fence and TF.ask(fence.Get, level + 1)
  if upgrade and tonumber(upgrade.Price) then
    out[#out + 1] = { kind = "fence", key = "fence" .. (level + 1), price = upgrade.Price, name = string.format("Fence (%d slots)", tonumber(upgrade.Slots) or 0),
      run = function() return TF.errand("shop", "fence", function() return TF.call("Plot_UpgradeFence", 8) end) end }
  end
  table.sort(out, function(a, b) return a.price < b.price end)
  for _, wish in ipairs(out) do wish.can = spendable >= wish.price end
  return out
end
plot.wishes = wishes

local function shop(O)
  local now = os.clock()
  -- the best food owned in hand (not while the throw is aimed at a missing animal: that throw picks its own)
  local shelf = foods()
  local farm = TF.farm
  if O.equipFood and shelf and shelf.held ~= shelf.best and not (farm and farm.hunting) and now >= (plot.wait.equip or 0) then
    local answer = TF.errand("shop", "shop", function() return TF.call("Shop_Equip", 8, shelf.best) end) or {}
    if answer.Ok then TF.note("Holding the best food now.") else plot.wait.equip = now + 10 end
  end
  for _, wish in ipairs(wishes(O)) do
    if wish.can and now >= (plot.wait[wish.key] or 0) then
      local answer = wish.run() or {}
      if answer.Ok then
        plot.bought[#plot.bought + 1] = wish.name
        plot.spent += wish.price
        TF.note(string.format("Bought %s for %s.", wish.name, TF.cash(wish.price)))
        TF.toast("Bought", string.format("%s · %s", wish.name, TF.cash(wish.price)), "shopping-cart", "ok")
        -- (a new food is held at once when the player said to: it is what the next throw reads)
        if wish.kind == "food" and O.equipFood and not (farm and farm.hunting) then
          TF.errand("shop", "shop", function() return TF.call("Shop_Equip", 8, wish.index) end)
        end
        task.wait(0.3)
      else
        -- (refused: not again for a while, whatever the reason)
        plot.wait[wish.key] = now + 20
      end
      -- (one buy a pass: the money is less now, and the next pass reads it again)
      break
    end
  end
end

local function start(hub)
  local map = {}
  for id, default in pairs({ equip = false, sell = false, keepMutation = "off", keepRarity = "off",
    equipFood = false, buyFood = false, foodMode = "smart", buyBars = false, buyFence = false, reserve = 0 }) do
    Config.define("throwfood." .. id, default)
    map[id] = "throwfood." .. id
  end
  local O = Config.mirror(map)
  plot.options = O

  -- Acted on when something changed: a catch, or the backpack is not what it was after the last pass.
  -- (an animal that is kept, or not good enough for the plot, would otherwise be offered to the server every second)
  local dirty, seen = true, -1
  TF.onCatch:connect(function() dirty = true end)
  for _, id in ipairs({ "equip", "sell", "keepMutation", "keepRarity" }) do Config.on("throwfood." .. id, function() dirty = true end) end
  task.spawn(function()
    while B.alive do
      if TF.started and TF.ready() then
        if O.equip or O.sell then
          local animals = TF.animals()
          local count = #animals.backpack
          if dirty or count ~= seen then
            dirty = false
            if O.sell then
              if B.try("throwfood.sell", sellRest, O) == nil and O.equip and better() then equipBest() end
            elseif better(animals) then
              equipBest()
            end
            seen = #TF.animals().backpack
          end
        end
        if O.equipFood or O.buyFood or O.buyBars or O.buyFence then B.try("throwfood.shop", shop, O) end
      end
      task.wait(1)
    end
  end)
end

-- ---------------------------------------------------------------- the cards
local RARITIES = { { "off", "Sell any" } }
for _, name in ipairs(TF.RARITY_ORDER) do RARITIES[#RARITIES + 1] = { name, name .. " and up" } end
local MUTATIONS = { { "off", "Sell any" }, { "Gold", "Gold and up" }, { "Diamond", "Diamond and up" }, { "Emerald", "Emerald and up" },
  { "Ruby", "Ruby and up" }, { "Rainbow", "Rainbow only" } }

local function plotCards(page)
  local box = page:section({ title = "Plot", icon = "trees", desc = "The best on the plot, the rest turned to cash." })
  box:toggle({ id = "throwfood.equip", label = "Replace weaker ones", desc = "A better catch takes a weak one's slot.", default = false })
  box:toggle({ id = "throwfood.sell", label = "Sell the rest", desc = "What is weaker than your whole plot.", default = false })
  box:dropdown({ id = "throwfood.keepMutation", label = "Keep mutations", desc = "Never sells these.", options = MUTATIONS, default = "off" })
  box:dropdown({ id = "throwfood.keepRarity", label = "Keep rarity", desc = "Never sells these.", options = RARITIES, default = "off" })
  box:button({ id = "throwfood.equipNow", label = "Equip best now", text = "Equip", run = function() task.spawn(equipBest) end })
  box:button({ id = "throwfood.sellNow", label = "Sell the rest now", desc = "Keeps what you said to keep.", text = "Sell", run = function()
    task.spawn(function() sellRest(plot.options) end)
  end })
  local line = box:note({ icon = "info", text = "" })
  local top = page:section({ title = "On your plot", icon = "star" })
  local list = top:note({ icon = "list", text = "" })
  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    local animals = TF.animals()
    line.set(string.format("%d/%d placed  ·  %s/s  ·  %d in the backpack  ·  %d swapped  ·  sold %d for %s", #animals.placed, animals.slots or 10,
      TF.cash(animals.income), #animals.backpack, plot.swapped, plot.sold, TF.cash(plot.soldFor)))
    table.sort(animals.placed, function(a, b) return a.income > b.income end)
    local rows = {}
    for i = 1, math.min(12, #animals.placed) do
      local item = animals.placed[i]
      rows[#rows + 1] = string.format("%s%s · %s/s", item.mutation and (item.mutation .. " ") or "", TF.species(item.name).name, TF.short(item.income))
    end
    list.set(#rows > 0 and table.concat(rows, "\n") or "Nothing placed yet.")
  end, 2, "throwfood.plot.line")
end

local function shopCards(page)
  local box = page:section({ title = "Shop", icon = "shopping-cart", desc = "Spends the game's cash, cheapest first. Never Robux." })
  box:toggle({ id = "throwfood.equipFood", label = "Hold the best food", desc = "The best food you own, always.", default = false })
  box:toggle({ id = "throwfood.buyFood", label = "Auto buy food", desc = "The next food, when it is worth it.", default = false })
  box:segmented({ id = "throwfood.foodMode", label = "Food", desc = "Smart: only food that helps where you land.",
    options = { { "smart", "Smart" }, { "next", "Every one" } }, default = "smart", width = 180 })
  box:toggle({ id = "throwfood.buyBars", label = "Auto buy bars", desc = "The next pull-up bar: double XP each.", default = false })
  box:toggle({ id = "throwfood.buyFence", label = "Auto buy fence", desc = "More slots on the plot.", default = false })
  box:slider({ id = "throwfood.reserve", label = "Keep in reserve", desc = "Never spends this share of your cash.", min = 0, max = 90, step = 5, default = 0, suffix = "%" })
  local line = box:note({ icon = "info", text = "" })
  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    local O = plot.options
    local everything = setmetatable({ buyFood = true, buyBars = true, buyFence = true }, { __index = function(_, key) return O[key] end })
    local rows = {}
    for _, wish in ipairs(wishes(everything)) do
      rows[#rows + 1] = string.format("%s: %s%s", wish.name, TF.cash(wish.price), wish.can and " (can buy)" or "")
    end
    local shelf = foods()
    local held = shelf and TF.ask(shelf.config.Get, shelf.held)
    local text = (held and ("Holding " .. tostring(held.Name)) or "") .. (#plot.bought > 0 and string.format("  ·  bought %d for %s", #plot.bought, TF.cash(plot.spent)) or "")
    line.set(text .. (#rows > 0 and ("\nNext: " .. table.concat(rows, "  ·  ")) or "\nNothing that helps to buy now."))
  end, 2, "throwfood.shop.line")
end

TF.parts[#TF.parts + 1] = { id = "plot", start = start, plot = plotCards, shop = shopCards }
end
do -- 90_boot.lua
-- ============================================================================
--  90 boot     order of operations
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Window, Assets = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Window, B.Assets
local UIS = S.UserInputService

local function boot()
  if not game:IsLoaded() then game.Loaded:Wait() end
  Config.init()
  Assets.init()
  if B.Prefs then B.Prefs.define() end
  if B.Prefs then B.Prefs.apply() end
  if B.Unnamed then B.Unnamed.start() end
  if B.Novoline then B.Novoline.start() end
  Window.build()
  -- the game is looked up first: its module can ask for Universal not to be loaded at all
  if B.Registry then B.try("registry.pick", B.Registry.pick) end
  for _, register in ipairs(B.pages or {}) do
    local name = B.universalPages and B.universalPages[register]
    if not name or not B.Registry or B.Registry.keeps(name) then B.try("pages", register) end
  end
  if B.Registry then B.try("registry", B.Registry.resolve) end
  Window.rebuildNav()
  Config.listen()

  -- the menu key, the palette, and the panic key
  B.connect(UIS.InputBegan, function(input)
    if Config.capturing then return end
    if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
    local name = input.KeyCode.Name
    if UIS:GetFocusedTextBox() then return end
    if name == Config.get("app.key.menu") then
      if B.Loader and B.Loader.active then return end
      Window.toggleActive()
    elseif name == Config.get("app.key.panic") then
      B.unload()
    elseif input.KeyCode == Enum.KeyCode.K and (UIS:IsKeyDown(Enum.KeyCode.LeftControl) or UIS:IsKeyDown(Enum.KeyCode.RightControl)) and Window.open then
      Window.palette()
    end
  end, "boot.keys")

  -- Started again by itself on the far side of a teleport and asked to stay down (a farm that goes from mission to
  -- mission): the window is not opened, and the island and the menu key bring it up. The mark is used once, so a
  -- hub run again by hand in the same session opens as it always does.
  -- (2026-11-18: and by default, Settings > On screen > Start minimised. getgenv().BASED_SHOW = true opens it anyway:
  -- the spec's worlds set it, every scenario there was written for a hub that opens)
  local minimised = B.genv.BASED_MINIMISED == true or (Config.get("app.startMinimised") == true and B.genv.BASED_SHOW ~= true)
  B.genv.BASED_MINIMISED = nil
  local function reveal()
    if not minimised then Window.showActive(true) end
    if B.Hud then B.try("hud", B.Hud.start) end
    if B.Unnamed then B.try("unnamed.watermark", B.Unnamed.watermark) end
    if B.Novoline and B.Novoline.active() then B.try("novoline.island", B.Novoline.island) end
    if B.Keys then B.try("keys.hud", B.Keys.hud) end
    if B.Registry then B.try("registry.announce", B.Registry.announce) end
  end
  -- the other tabs are assembled a card per frame in the background: under the intro when there
  -- is one, so the hub is complete the moment it appears
  task.delay(0.7, function() if B.alive then Window.prebuild() end end)
  -- The first launch on this machine: which look to open in is asked once, when the intro is done
  -- (not when an intro is forced off for one launch: that is a test or a reload)
  local function begin()
    -- (2026-11-11: only when there is more than one look to pick: Unnamed and Novoline are out of the build for now)
    -- (2026-11-14: the Unnamed menu is back as the SECOND menu, the owner's word: "as the secondary use". The hub opens in
    -- the BASED one and nothing is asked; the other is picked in Settings > Menu style, or the menu at the window's top.
    -- The picker is for the day all three are in the build again)
    if Config.firstRun and B.Picker and (B.Unnamed and B.Novoline) and B.genv.BASED_INTRO ~= "off" and not B.genv.BASED_NO_PICKER then
      B.Picker.show(function(look)
        if look then Config.set("app.gui", look) end
        B.try("reveal", reveal)
      end)
    else
      reveal()
    end
  end
  if B.Loader then B.Loader.run(begin) else begin() end
  B.bootMs = math.floor((os.clock() - B.bootClock) * 1000)
end

task.spawn(function()
  local ok, err = xpcall(boot, function(e) return tostring(e) .. "\n" .. debug.traceback("", 2) end)
  if not ok then
    B.fault("boot", err)
    pcall(function()
      S.StarterGui:SetCore("SendNotification", { Title = "BASED Hub", Text = "Failed to start: " .. string.sub(tostring(err), 1, 120), Duration = 8 })
    end)
  end
end)
end
return B
